(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["産業3次"]=[{"id":"00002492","register_sub_id":"101","register_pk":"103482","name":"上川倉庫一号倉庫","kana":"かみかわそうこいちごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76282255,"lng":142.36384052,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積165㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0039","desc":"ＪＲ旭川駅前の約０．５ｈａの敷地を占める上川倉庫群は，グリッド状街路網の１区画分を囲むように配置されている。平側で通りに面し，敷地正面の事務所西側に位置する木骨煉瓦造平屋建の一号倉庫は，現在多目的ホールとして市民に広く活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002492"},{"id":"00002494","register_sub_id":"101","register_pk":"103484","name":"上川倉庫三号倉庫（チェアーズギャラリー）","kana":"かみかわそうこさんごうそうこ（ちぇあーずぎゃらりー）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.762608,"lng":142.36349904,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積223㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0041","desc":"当初，上川倉庫は穀物貯蔵に用いられた。三号倉庫は敷地西角を占め，二号倉庫と横並びで配置される。小屋組を木製キングポストトラスとし，焼過ぎ煉瓦を用いた基壇と小口を二枚重ねた歯飾り付の蛇腹が外観を引き締める。現在，椅子の展示室として活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002494"},{"id":"00002491","register_sub_id":"101","register_pk":"103481","name":"上川倉庫事務所","kana":"かみかわそうこじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76274907,"lng":142.3640528,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積120㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0038","desc":"上川倉庫群の正面，宮下通側のほぼ中央に立つ敷地内唯一の木造建築。東面に煉瓦の煙突を建ちあげた下見板張洋館で，妻面をペディメント状に造りファイニアルを載せ，２階中央に要石及び額縁飾付半円アーチ窓を配するなど正面妻側に特に丹念な意匠を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002491"},{"id":"00002497","register_sub_id":"101","register_pk":"103487","name":"上川倉庫十一号倉庫（大雪地ビール館）","kana":"かみかわそうこじゅういちごうそうこ（だいせつじびーるかん）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76261121,"lng":142.36389431,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積430㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0044","desc":"敷地の中央にある。倉庫群の中で最も規模が大きく，最後に建設された倉庫。妻側が隠れる他の倉庫と異なり，欠円アーチの開口部のみでなく，２段の歯飾付蛇腹を有す三角ペディメントを両妻側に設ける。現在，ビアホールとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002497"},{"id":"00002496","register_sub_id":"101","register_pk":"103486","name":"上川倉庫十号倉庫（デザインギャラリー）","kana":"かみかわそうこじゅうごうそうこ（でざいんぎゃらりー）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76250328,"lng":142.36365104,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積231㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0043","desc":"明治３１年に開業した鉄道駅構内に面する。通路を挟んで三号倉庫に直角に取り付き，現在ギャラリーとして活用されている。外壁煉瓦長手積とし，蛇腹に２段の歯飾りを設ける。鉄道の発展に伴い敷地が整えられた上川倉庫群の歴史を物語る重要な建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002496"},{"id":"00002493","register_sub_id":"101","register_pk":"103483","name":"上川倉庫二号倉庫（リハーサルホール）","kana":"かみかわそうこにごうそうこ（りはーさるほーる）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76280838,"lng":142.36361931,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積165㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0040","desc":"妻側で通りに面し敷地の北角を占める。一号倉庫と同規模の木骨煉瓦造倉庫で，敷地内平側中央に４枚厚の３心円アーチからなる入口と，その左右に欠円アーチの開口部を設ける。倉庫群中，最初に完成した建造物で，現在音楽の稽古場として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002493"},{"id":"00002495","register_sub_id":"101","register_pk":"103485","name":"上川倉庫八号倉庫","kana":"かみかわそうこはちごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76269279,"lng":142.36416124,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木骨煉瓦造平屋建、瓦葺一部鉄板葺、建築面積165㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0042","desc":"宮下通に面し事務所東側に隣接する。切妻造，瓦葺一部鉄板葺，外観イギリス積で，隅部に焼過ぎ煉瓦で柱型をつくり，一号倉庫と類似した規模，外観をもつ。事務所と対照的な重厚かつ連続的外観を一号倉庫と共に構成し，近代的街路景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002495"},{"id":"00001461","register_sub_id":"101","register_pk":"102451","name":"旧丹波屋旅館洋館","kana":"きゅうたんばやりょかんようかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道枝幸郡中頓別町字小頓別91-1","lat":44.82787447,"lng":142.30438782,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、亜鉛メッキ鋼板葺、建築面積50㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"01 － 0017","desc":"国道２７５号線に面し，和館の東妻面に接続して建つ。寄棟小屋根の両端を切り落とした腰折屋根が特徴的な木造２階建，屋根裏部屋付き，下見板張の洋館で，縦長窓の上部にスティックワークにより扁平アーチのファンライトを造りだしている点にも特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001461"},{"id":"00001460","register_sub_id":"101","register_pk":"102450","name":"旧丹波屋旅館和館","kana":"きゅうたんばやりょかんわかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道枝幸郡中頓別町字小頓別91-1","lat":44.82787996,"lng":142.30436158,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、亜鉛メッキ鋼板葺、建築面積102㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"01 － 0016","desc":"宗谷本線音威子府駅から分岐してオホーツク回りで稚内に至る旧天北線の小頓別駅の駅前旅館。主屋としての和館は小頓別駅開業時に合わせて建設されたもの。木造２階建，切妻屋根，平入で，正面中央に切妻破風の玄関を設け，階上を客室に充てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001460"},{"id":"00002576","register_sub_id":"101","register_pk":"103566","name":"旧北陸銀行江別支店","kana":"きゅうほくりくぎんこうえべつしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道江別市二条2-6","lat":43.11358538,"lng":141.55917472,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造2階建、鉄板葺、建築面積57㎡","structure_material":"石造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"01 － 0048","desc":"江別駅近くの商業中心地にある銀行建築で，現在は喫茶店として活用されている。切妻造・平入で，正面に下屋庇とポーチを設けた形式で，構造は石造，小屋組はキングポストトラスである。土蔵造風の外観は，地方における銀行の支店建築に通じている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002576"},{"id":"00014445","register_sub_id":"101","register_pk":"512429","name":"銀鱗荘旧本館（旧猪俣家住宅）","kana":"ぎんりんそうきゅうほんかん（きゅういのまたけじゅうたく）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道小樽市桜一丁目1-2他","lat":43.18067778,"lng":141.03493333,"geo_status":"db","era":"明治後期／昭和13年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造3階建、瓦葺、建築面積420㎡","structure_material":"木造3階建","registered":"2023.02.27(令和5.02.27)","register_no":"01 - 0163","desc":"石狩湾を望む丘陵の一角に建つ。開道70年を機に移築した旧鰊漁家と、サンルーム等を備えた地階付平屋の増築部よりなる。移築部は木造二階建、平入、望楼付で、内部に二間半の神棚を祀る六間取り広間を設ける。豪壮な漁家建築を核とする近代の旅館施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014445"},{"id":"00014446","register_sub_id":"101","register_pk":"512430","name":"グリル銀鱗荘（旧北海道水産記念館）","kana":"ぐりるぎんりんそう（きゅうほっかうどうすいさんきねんかん）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道小樽市桜一丁目1-2他","lat":43.18048056,"lng":141.03474722,"geo_status":"db","era":"明治後期／昭和16年移築、同44年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積259㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"01 - 0164","desc":"銀鱗荘旧本館の西側に北面して建つ。鰊の一時保管に用いた「廊下」を移築し、水産記念館として改装したもの。木造二階建、寄棟造妻入で、外装漆喰塗とし四周の窓を虫籠窓風とする外観と太い軸部が重厚。本館と共に北海道水産業の繁栄を物語る記念碑的な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014446"},{"id":"00000115","register_sub_id":"101","register_pk":"101105","name":"五島軒本店旧館","kana":"ごとうけんほんてんきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道函館市末広町4-13","lat":41.76350076,"lng":140.7162289,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造・鉄筋コンクリート造2階建，亜鉛板葺，建築面積1865㎡","structure_material":"木造・鉄筋コンクリート造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"01 － 0002","desc":"昭和９年の大火の後に再建された木造及び鉄筋コンクリート造，２階建のレストランで，亀井勝二郎・竹下茂の設計と伝える。質素な外観と対照的な高い腰壁・落ちついた色調の布壁でまとめた格調高い内装に特徴があり，結婚式場にも利用され広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000115"},{"id":"00015270","register_sub_id":"101","register_pk":"532394","name":"さっぽろテレビ塔","kana":"さっぽろてれびとう","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"北海道","address":"北海道札幌市中央区大通西一丁目1他","lat":43.06111389,"lng":141.35644444,"geo_status":"db","era":"昭和32年／昭和38年改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄骨造及び鉄筋コンクリート造、高さ144m、脚間35m、地下2階付","structure_material":"鉄骨造及び鉄筋コンクリート造","registered":"2025.03.13(令和7.03.13)","register_no":"01 - 0171","desc":"大通公園の東端に位置し、電波発信及び観光拠点の機能を担う自立式鉄塔。総高一四四メートル、末広がりの立面形状で、四隅でトラスを三角錐状に組み、上下に展望台を設けた全一四節の主塔部とアンテナを支持する鉄塔部からなる。札幌を代表するランドマーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015270"},{"id":"00004684","register_sub_id":"101","register_pk":"105674","name":"函館大手町ハウス（旧浅野セメント函館営業所）","kana":"はこだておおてまちはうす（きゅうあさのせめんとはこだてえいぎょうしょ）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"北海道","address":"北海道函館市大手町5-1","lat":41.77050806,"lng":140.7232207,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、銅板葺、建築面積139㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"01 － 0062","desc":"木造２階建で，正面両脇を突出して塔状に扱い，コンクリートブロックで隅柱を表す。正面入口にファンライトを飾り，アーケード上をバルコニーとする。窓庇と窓台は直線的な意匠。棟札から棟梁は村木甚三郎。平成１６年の改修工事で往時の外観に整備された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004684"},{"id":"00011612","register_sub_id":"101","register_pk":"210628","name":"宮本商産旧本社ビル","kana":"みやもとしょうさんきゅうほんしゃびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道帯広市西二条南五丁目1他","lat":42.926993,"lng":143.201273,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積91㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"01-0149","desc":"駅前通りの角地に建つ木造二階建の社屋。東正面は煉瓦タイル貼とし、二層分の柱形を配して花崗岩の帯を廻らす。壁頂にコーニスとデンティルを廻らし、正面中央にペディメントを飾るなど、重厚な趣を見せる。戦前の帯広の繁栄を伝える良質な事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011612"},{"id":"00003775","register_sub_id":"101","register_pk":"104765","name":"青森県立郷土館（旧青森銀行本店）","kana":"あおもりけんりつきょうどかん（きゅうあおもりぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"青森県","address":"青森県青森市本町2-8-14","lat":40.82729533,"lng":140.74885468,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積750㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"02 － 0026","desc":"第五十九銀行青森支店として建設。鉄筋コンクリート造２階建の銀行建築で，吹抜の営業室にはフラットスラブ風の柱頭を持つ８本の円柱を建て，ギャラリーを廻す。古典主義建築の骨格を保持しつつ細部装飾を省略したモダニズム建築の一例。設計は堀江幸治。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003775"},{"id":"00009111","register_sub_id":"101","register_pk":"164664","name":"石場旅館","kana":"いしばりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"青森県","address":"青森県弘前市大字元寺町55","lat":40.60559146,"lng":140.46969264,"geo_status":"db","era":"明治12年／明治中期増築・昭和30年頃・昭和45年改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積456㎡","structure_material":"木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"通り西側に建つ。妻入の2階建、建築面積456平方メートル。東西棟の入母屋造鉄板葺2棟を雁行させる。南側を前方に出し、玄関やフロントを配し、後方に土蔵を附属し、北奥の棟に広間や客室を設ける。屋号をあしらうガラスや欄干が、老舗旅館の風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009111"},{"id":"00003342","register_sub_id":"101","register_pk":"104332","name":"旧高谷銀行本店（盛農薬商会倉庫）","kana":"きゅうたかやぎんこうほんてん（もりのうやくしょうかいそうこ）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県つがる市木造千代町34-2","lat":40.80827949,"lng":140.38607317,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、鉄板葺、建築面積91㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"02 － 0022","desc":"町中心部，木造駅を起点とする表通りに面する敷地に建つ。正面中央に，規模と意匠の異なる円柱に挟まれた入口を設け，その上部及び左右に，高密度な浅彫をあしらった窓及び屋根窓を設ける。様式に拘らない自由で独特なデザインが特徴。堀江組の設計施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003342"},{"id":"00003341","register_sub_id":"101","register_pk":"104331","name":"旧弘前無尽社屋（三上ビル）","kana":"きゅうひろさきむじんしゃおく（みかみびる）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"青森県","address":"青森県弘前市大字元寺町9","lat":40.60341924,"lng":140.469711,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階一部4階建、建築面積109㎡","structure_material":"鉄筋コンクリート造3階一部4階建","registered":"2003.07.01(平成15.07.01)","register_no":"02 － 0021","desc":"弘前公園東方に位置する。弘前市内初期の鉄筋コンクリート造建造物で，設計は青森工業学校長の大竹巽。角地の隅を切り垂直性を強調した壁面を立ち上げ，３階窓上部にあしらった歯飾状装飾を背面にまで連続させるなどアールデコ調の意匠に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003341"},{"id":"00000232","register_sub_id":"101","register_pk":"101222","name":"佐滝本店","kana":"さたきほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県三戸郡三戸町大字八日町49","lat":40.37723463,"lng":141.25649929,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積99㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"02 － 0001","desc":"南部地方における鉄筋コンクリート造の先駆け的な建物。近年２階正面が改修され、蔦に覆われたかつてのおもむきが一新された。塔屋風の屋根飾りを持ち当時流行したドイツ表現派の影響が見られる構成となる。設計施工は弘前の堀江組。側面にアーチ門が付設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000232"},{"id":"00006116","register_sub_id":"101","register_pk":"107100","name":"新むつ旅館本館","kana":"しんむつりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"青森県","address":"青森県八戸市小中野六丁目110-1","lat":40.519657,"lng":141.518463,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積177㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"02 － 0052","desc":"八戸市中心部の小中野新地に所在。桁行６間規模，切妻造，鉄板葺，平入の木造２階建で，２階に３列５室の客室を配す。中央に天窓を開けた吹抜と洋風意匠のＹ字状階段を設け，たちが高く，１階軒先部の細工や２階軒の出桁上に照明を付けた独特のつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006116"},{"id":"00011839","register_sub_id":"101","register_pk":"354911","name":"ヤマニ仙遊館土蔵","kana":"やまにせんゆうかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"青森県","address":"青森県南津軽郡大鰐町大字蔵館字村岡47","lat":40.521448,"lng":140.575718,"geo_status":"db","era":"明治30年頃／昭和中期・同56年改修","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、鋼板葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"02-104","desc":"本館の北西側に建つ。建築面積五〇平方メートル、土蔵造二階建、銅板葺で、外壁は一階を石張風に、二階を漆喰塗とする。屋根は置屋根形式とし、街路に面した北面に二階には小ぶりな窓を開き、庇をかける。温泉街のかつての景観を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011839"},{"id":"00011838","register_sub_id":"101","register_pk":"354910","name":"ヤマニ仙遊館本館","kana":"やまにせんゆうかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"青森県","address":"青森県南津軽郡大鰐町大字蔵館字村岡47","lat":40.521284,"lng":140.575853,"geo_status":"db","era":"明治30年頃／昭和中期・同56年改修","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積328㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"02-103","desc":"平川沿いに南面して建つ旅館。建築面積三二八平方メートル、木造二階建鋼板葺で、北面中央に玄関を開き、左方に座敷等を、右方に帳場等を配す。玄関奥の階段を上がった二階には、東西に中廊下を通して南北に客室を並べる。大鰐温泉の往時の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011838"},{"id":"00014556","register_sub_id":"101","register_pk":"515098","name":"旧高善旅館（柳翁宿）","kana":"きゅうたかぜんりょかん（りゅうおうじゅく）","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県遠野市中央通り2-11","lat":39.32921111,"lng":141.52856111,"geo_status":"db","era":"明治前期／明治39年・大正5年増築、昭和23年改修、昭和60年移築、平成25年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積243㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"03 - 0120","desc":"遠野屈指の旅館で元は城下中心地にあり要人が宿泊した。東側切妻造に明治後期に西側入母屋造を増築。東側は通り土間・広いミセ・吹抜常居を並べた遠野の典型町家。西側は起り屋根石敷玄関を構えて正面を大階段とし、二階に床構え付客室を配した近代和風旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014556"},{"id":"00007830","register_sub_id":"101","register_pk":"108811","name":"黒沢治助商店一番蔵及び二番蔵","kana":"くろさわちすけしょうてんいちばんぐらおよびにばんぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27407897,"lng":141.30121624,"geo_status":"db","era":"大正7／昭和6・昭和43改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積175㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0077","desc":"主屋の東南に東西棟で建つ。桁行１９ｍ梁間７．２ｍと規模の大きい土蔵造２階建で、北面に庇を付ける。外壁は白漆喰仕上げを基調に、腰を海鼠壁とし、鉢巻や両開の掛子塗戸は角を白漆喰とする黒漆喰仕上げ。重厚で、丁寧な仕上げになる外観は見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007830"},{"id":"00007831","register_sub_id":"101","register_pk":"108812","name":"黒沢治助商店穀物蔵","kana":"くろさわちすけしょうてんこくもつぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27408271,"lng":141.30143795,"geo_status":"db","era":"昭和前期／昭和後期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、鉄板葺、建築面積93㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0078","desc":"一番蔵及び二番蔵の東に東西棟で建つ。桁行１３ｍ梁間５．５ｍの木造２階建。切妻造鉄板葺で、北面に庇を付ける。現在は白漆喰塗とし、開口に鉄扉を吊る。内部は板壁で、トラス組。１階は一室、２階は階段室と三室に間仕切り、穀物など食料を保管した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007831"},{"id":"00007828","register_sub_id":"101","register_pk":"108809","name":"黒沢治助商店主屋","kana":"くろさわちすけしょうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27422139,"lng":141.30075991,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0075","desc":"敷地北辺の中央に東西棟で建つ。木造平屋建の切妻造桟瓦葺で、西面下屋南寄りに、切妻屋根を付け、袖塀を設け、出入口とする。漆喰仕上げの大壁造とし、雨戸も外側を漆喰仕上げの上に銅板を張る。南側に通り土間を設け、ジョウイ等を配する。重厚で、力強い外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007828"},{"id":"00007832","register_sub_id":"101","register_pk":"108813","name":"黒沢治助商店倉庫","kana":"くろさわちすけしょうてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27412365,"lng":141.30060025,"geo_status":"db","era":"昭和前期／昭和後期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、鉄板葺、建築面積129㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0079","desc":"敷地前寄り、店舗の南に建つ。東西２３ｍの長い木造２階建。２階正面は、間口６．４ｍで、柱形を現し、三分して各間に鉄扉を吊る。１階は庇を付け、大きく開口を設け、銅板張雨戸をたてる。壁は人造石洗出し仕上げ。伝統的な意匠の店舗と鮮やかな対比を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007832"},{"id":"00007827","register_sub_id":"101","register_pk":"108808","name":"黒沢治助商店店舗","kana":"くろさわちすけしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27419605,"lng":141.30054032,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0074","desc":"通りの東側に占める短冊形の敷地の西正面に建つ。桁行８．５ｍ梁間１２ｍ、木造２階建、切妻造桟瓦葺の町家で、軒などを塗り込める。１階に事務室などを配し、２階に十五畳と二十畳の座敷を設け、座敷飾りを構える。良材や大材を多く用い、質の高い意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007827"},{"id":"00007834","register_sub_id":"101","register_pk":"108815","name":"黒沢治助商店防火塀","kana":"くろさわちすけしょうてんぼうかべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27408592,"lng":141.30057878,"geo_status":"db","era":"大正後期・昭和20頃","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造、延長45m","structure_material":"煉瓦造","registered":"2009.11.02(平成21.11.02)","register_no":"03-0081","desc":"敷地前方の南辺と北辺に築かれる。北辺は高さ２．７ｍ厚さ３８㎝延長６．８ｍ、煉瓦造で、敷地内側を人造石洗出し仕上げとする。南辺は煉瓦を内外とも現し、前方２８ｍを高さ３．７ｍに、後方１０ｍを高さ２．７ｍに積む。防火に対する意識の高さが窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007834"},{"id":"00007833","register_sub_id":"101","register_pk":"108814","name":"黒沢治助商店門及び石塀","kana":"くろさわちすけしょうてんもんおよびいしべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27414799,"lng":141.30041083,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"門 石造、間口3.6m、 塀 石造、延長7.2m","structure_material":"門 石造","registered":"2009.11.02(平成21.11.02)","register_no":"03-0080","desc":"店舗の正面、通り沿いに位置する。高さ２．６ｍ、３７㎝角の御影石の石柱を間口３．６ｍに建て、門とする。門柱から通りに沿って江戸切仕上げの御影石を積み、上部に笠石を置く。高さ９０㎝厚さ３０㎝で、延長７．２ｍ。敷地正面において、屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007833"},{"id":"00007829","register_sub_id":"101","register_pk":"108810","name":"黒沢治助商店渡廊下","kana":"くろさわちすけしょうてんわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27424504,"lng":141.30065687,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0076","desc":"店舗と主屋を繋ぐ。桁行８．５ｍ梁間２．４ｍの木造平屋建、東西棟の桟瓦葺とする。南側を廊下とし、北側に便所や洗面所、物入を配する。南面は腰にタイルを貼り、上部に窓を連続して開け、軒や戸袋を塗り込める。雨戸は漆喰仕上げ銅板張の防火戸とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007829"},{"id":"00016465","register_sub_id":"101","register_pk":"574827","name":"鉛温泉藤三旅館白猿の湯","kana":"なまりおんせんふじさんりょかんしろさるのゆ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県花巻市鉛字中平75-1他","lat":39.46231083,"lng":140.99528194,"geo_status":"db","era":"昭和前期／平成16年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造地上1階地下1階建、鉄板葺、建築面積109㎡","structure_material":"木造地上1階地下1階建","registered":"2026.02.10(令和8.02.10)","register_no":"03 - 0129","desc":"本館の東方に位置する浴室棟。平屋建寄棟造鉄板葺で棟中央に越屋根を設ける。二箇所の入口から石段で地階の浴場に至り、中央に岩盤を刳抜いた深さ約一・三メートルの大浴槽を配する。浴槽周囲は石敷床に石壁で重厚に仕上げ、上部を吹抜とした開放的な浴室棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016465"},{"id":"00016464","register_sub_id":"101","register_pk":"574826","name":"鉛温泉藤三旅館本館","kana":"なまりおんせんふじさんりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県花巻市鉛字中平75-1他","lat":39.46231083,"lng":140.99528194,"geo_status":"db","era":"昭和16年／昭和39年増築","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造3階建、瓦葺一部鉄板葺、建築面積607㎡","structure_material":"木造3階建","registered":"2026.02.10(令和8.02.10)","register_no":"03 -0128","desc":"鉛温泉に位置する旅館。豊沢川沿いに建つ木造三階建で、南東に座敷棟を接続する。南面東寄りに唐破風造の玄関を突出し、上部を楼閣風につくり入母屋屋根を付す。内部は各階中廊下の南北に客室を並べる。川に面した大規模な三階建旅館が温泉地の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016464"},{"id":"00012082","register_sub_id":"101","register_pk":"352881","name":"花巻温泉旧松雲閣別館","kana":"はなまきおんせんきゅうしょううんかくべっかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"昭和前","pref":"岩手県","address":"岩手県花巻市湯本第1地割他","lat":39.45369,"lng":141.068657,"geo_status":"db","era":"昭和2年／昭和14年・同36年増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積957㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"03-102","desc":"木造二階建の大規模旅館建築。桁行五五・五メートル、梁間一六・三メートルで、南正面中央やや右寄りに玄関を開き、一、二階とも中廊下を通して南、東に客間を配し、背面側には広間等を置く。屋根は赤色の釉薬瓦で葺き、花巻温泉の往時の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012082"},{"id":"00011033","register_sub_id":"101","register_pk":"205140","name":"萬代舘","kana":"ばんだいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岩手県","address":"岩手県二戸郡一戸町一戸字本町49","lat":40.217532,"lng":141.302421,"geo_status":"db","era":"昭和31／平成20改修","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積374㎡","structure_material":"木造平屋一部2階建","registered":"2016.08.01(平成28.08.01)","register_no":"03 - 0086","desc":"一戸の中心地、馬淵川を渡るメインストリートの突当りに建つ。正面は下部をタイル貼、上部をモルタル塗りとし、内部は玄関を入って左右に階段を設け、一部二階を設ける総椅子式としている。高度成長期以前に全国で多数建設された映画館の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011033"},{"id":"00011038","register_sub_id":"101","register_pk":"205145","name":"一條旅舘土蔵","kana":"いちじょうりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県白石市福岡蔵本字鎌先一番40-1","lat":38.024403,"lng":140.574838,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積41㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"04 - 0125","desc":"敷地最奥部、一段高い位置に建つ。桁行五間、梁間二間半の土蔵造で、屋根は置屋根鉄板葺。外壁は腰下見板張上部は白漆喰塗とする。背面側のみ三尺、他は一尺五寸間隔で柱を建てる。北側正面には庇を設け、扉は土扉、板戸、格子戸の三重とするなど質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011038"},{"id":"00011036","register_sub_id":"101","register_pk":"205143","name":"一條旅舘木造本館","kana":"いちじょうりょかんもくぞうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県白石市福岡蔵本字鎌先一番40-4","lat":38.024882,"lng":140.575104,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造3階一部地下1階建、鉄板葺、建築面積228㎡","structure_material":"木造3階一部地下1階建","registered":"2016.08.01(平成28.08.01)","register_no":"04 - 0123","desc":"白石市郊外の鎌先温泉の湯治宿。昭和一二年の豪雨被害の後に建て替えられたもの。一階から三階まで四周に廊下を廻らし、八畳、六畳、四畳半の座敷が全一〇室並ぶ。高欄と木製建具を連ねる瀟洒な外観のみならず、スギの良材を多用し過半を通し柱とする点も特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011036"},{"id":"00011037","register_sub_id":"101","register_pk":"205144","name":"一條旅舘湯向棟","kana":"いちじょうりょかんゆむかいとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県白石市福岡蔵本字鎌先一番40-4","lat":38.024672,"lng":140.574947,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積294㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"04 - 0124","desc":"鎌先温泉は正長元年開湯と伝える古くからの湯治場で、一條旅舘はその細長い谷戸の奥に位置する。湯向棟は木造本館と同じく各階に四周に廊下を廻らし、八畳、六畳の座敷を全八室並べる。昭和初期の大規模木造建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011037"},{"id":"00002582","register_sub_id":"101","register_pk":"103572","name":"老松永田醸造店舗","kana":"おいまつながたじょうぞうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県亘理郡亘理町字上町31","lat":38.03231648,"lng":140.85411576,"geo_status":"db","era":"明治20代","year":1887,"year_source":"converted","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"04 － 0038","desc":"亘理町中心部にある醸造業の老舗で，店舗は街道に東面して建つ。２階建，切妻造・桟瓦葺，平入で，下屋庇を設けた桁行南４間をミセ，北２間を袖蔵とした構成である。正面２階は壁を海鼠壁とし，小庇の持送り，観音扉や棟積など全体に重厚なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002582"},{"id":"00011444","register_sub_id":"101","register_pk":"210404","name":"岡崎旅館別館北棟","kana":"おかざきりょかんべっかんきたとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉4-7","lat":38.145976,"lng":140.534399,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、鋼板葺、建築面積140㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"04-0126","desc":"青根温泉の中心に位置する。東西棟で建つ木造二階建、寄棟造鋼板葺で、内部は一〇畳間の座敷を三室並べ、東・北面に廊下を廻らし、北西部に八畳間の張出しを設ける。障子や欄間に精密な細工を凝らし、縁側のガラス戸や手摺りの組子により、独特の外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011444"},{"id":"00011445","register_sub_id":"101","register_pk":"210403","name":"岡崎旅館別館南棟","kana":"おかざきりょかんべっかんみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉4-7","lat":38.145804,"lng":140.534533,"geo_status":"db","era":"明治中期／平成23年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、鋼板葺、建築面積230㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"04-0127","desc":"別館北棟に矩折れに南接して建つ。木造二階建、寄棟造、鋼板葺。内部は一、二階とも中廊下を挟み大小の座敷を全二〇室並べ、東・南面に廊下を廻らす。小屋組は和小屋である。内部の保存状態が良く、青根温泉において、明治三九年大火前の風情を伝える旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011445"},{"id":"00003048","register_sub_id":"101","register_pk":"104038","name":"男山本店店舗","kana":"おとこやまほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市魚町2-2-14","lat":38.90641004,"lng":141.57432362,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積173㎡","structure_material":"木造3階建","registered":"2003.01.31(平成15.01.31)","register_no":"04 － 0045","desc":"木筋コンクリート造・３階建の店舗建築で，気仙沼湾最奥の内湾をほぼ南に望んで建つ。洗い出し仕上の外壁は，各階に蛇腹を廻し，パラペットは柱型や欄干及びゲーブルなどで飾るなど，際だった存在である。市内魚町にあって，昭和初期の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003048"},{"id":"00003046","register_sub_id":"101","register_pk":"104036","name":"角星店舗","kana":"かくぼしてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市魚町2-1-9","lat":38.90628642,"lng":141.57384104,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積99㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"04 － 0043","desc":"気仙沼湾最奥の内湾に面した魚町にあり，通りに面して建つ。木造・２階建，切妻造・桟瓦葺の土蔵造であるが，敷地形状に合わせた不等辺四角形の平面のため，両側の柱や出梁及び垂木などを平行四辺形に木取りするなど，希少な大工技術を用いた繊細な店舗建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003046"},{"id":"00013477","register_sub_id":"101","register_pk":"504845","name":"旧菅野屋勘兵衛（廻船問屋菅勘資料館）主屋","kana":"きゅうかんのやかんべえ（かいせんどんやかんかんしりょうかん）おもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池中町24-1","lat":38.65154722,"lng":141.28010278,"geo_status":"db","era":"明治22年頃／昭和48年、平成20年改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0182","desc":"市内中心部にある廻船問屋を営んだ商家。主屋は、道路に南面する店舗の背面に接続して建つ。木造平屋建、切妻造鉄板葺で、東、北面に下屋を廻し、北面西端に便所を付す。内部は一列四室とし、最奥を床付の座敷とする。庭に向けて開放的なつくりを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013477"},{"id":"00013479","register_sub_id":"101","register_pk":"504847","name":"旧菅野屋勘兵衛（廻船問屋菅勘資料館）穀蔵","kana":"きゅうかんのやかんべえ（かいせんどんやかんかんしりょうかん）こくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池中町24-1","lat":38.65167778,"lng":141.280225,"geo_status":"db","era":"明治32年頃／平成20年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0184","desc":"文庫蔵東側に南面して建つ二階建の土蔵造桟瓦葺で、妻入正面に下屋、二階に鳥居形枠窓を開く。外壁は漆喰で軒先まで塗込めて鉢巻を廻し、腰と下屋との取合を海鼠壁とする。内部は漆喰塗で和小屋を現す。文庫蔵よりやや簡素ながら敷地景観に重厚さを加える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013479"},{"id":"00013478","register_sub_id":"101","register_pk":"504846","name":"旧菅野屋勘兵衛（廻船問屋菅勘資料館）文庫蔵","kana":"きゅうかんのやかんべえ（かいせんどんやかんかんしりょうかん）ぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池中町24-1","lat":38.65169444,"lng":141.28016111,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0183","desc":"主屋北側に南面して建つ。二階建の土蔵造桟瓦葺で、妻入の正面に下屋、二階窓上に大振りの庇を付す。外壁は漆喰で軒先まで塗込めて鉢巻を廻し、腰、下屋との取合、軒下を海鼠壁とする。内部は漆喰塗で二重梁の和小屋を現す。重厚な敷地景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013478"},{"id":"00013487","register_sub_id":"101","register_pk":"504855","name":"旧佐忠商店（冨谷宿）店舗及び主屋","kana":"きゅうさちゅうしょうてん（とみやじゅく）てんぽおよびおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県富谷市富谷新町35","lat":38.39911667,"lng":140.88798056,"geo_status":"db","era":"明治後期／昭和20年代・同50年代改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階及び木造平屋建、瓦葺及び銅板葺、建築面積141㎡","structure_material":"土蔵造2階及び木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0192","desc":"奥州街道富谷宿にある商家。街道に南面して建つ土蔵造桟瓦葺の店舗は、正面に下屋を付し、背後に切妻造銅板葺の主屋が接続する。店舗正面外観は、白漆喰塗と海鼠壁の外壁上部に黒漆喰塗の鉢巻三段を廻し、扇垂木風の軒とする。重厚感ある街道景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013487"},{"id":"00013488","register_sub_id":"101","register_pk":"504856","name":"旧佐忠商店（冨谷宿）門","kana":"きゅうさちゅうしょうてん（とみやじゅく）もん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県富谷市富谷新町35","lat":38.39905,"lng":140.88808333,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口3.9m","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0193","desc":"店舗正面東側に建つ門。本柱上に冠木を渡して扉を開き、冠木に束を立てて棟木を受け、束から腕木を出して軒の深い切妻屋根を支える。本柱の外側に柱を立てて棟木を受け、両潜戸を開く。壁は漆喰塗とし、冠木上には欄間を飾る。店舗と共に街道景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013488"},{"id":"00012685","register_sub_id":"101","register_pk":"367589","name":"旧平野本店店舗兼主屋","kana":"きゅうひらのほんてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県気仙沼市新町70","lat":38.90690278,"lng":141.565515,"geo_status":"db","era":"大正10年頃／昭和8年頃増築、昭和38年頃改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、金属板葺、建築面積116㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 167","desc":"東浜街道と気仙沼街道が合流する角地に東面して建つ木造二階建で、南の洋風建築の店舗と北の寄棟造鉄板葺の住宅からなる。店舗は二階に半円アーチ窓を並べ、大ぶりのパラペットを立ち上げるなど華やかに仕上げる。地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012685"},{"id":"00005219","register_sub_id":"101","register_pk":"106207","name":"三事堂ささ木店舗及び住宅","kana":"さんじどうささきてんぽおよびじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県気仙沼市八日町2-3-27","lat":38.90546576,"lng":141.57241467,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造2階建、鉄板葺、建築面積143㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"04 － 0053","desc":"間口５間，奥行３間２尺の２階建店舗に，奥行３間半の２階建住宅が接続する。屋根は寄棟造の鉄板葺である。正面１階は改修されているが，２階窓は櫛形ペディメントと窓台で洋風に飾る。ガラス窓桟割も技巧的である。外壁は２階軒裏までを白漆喰仕上げとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005219"},{"id":"00005220","register_sub_id":"101","register_pk":"106208","name":"三事堂ささ木土蔵","kana":"さんじどうささきどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県気仙沼市八日町2-3-27","lat":38.90719436,"lng":141.57133428,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"04 － 0054","desc":"桁行３間，梁間２間規模の土蔵造２階建で，道路側妻面の１，２階に窓を開く。屋根は切妻造の桟瓦葺で，１階に瓦葺庇を付ける。外壁は白漆喰塗である。南面中央，店舗内部に戸口を開き，漆喰塗の両開き土戸を釣り込む。小屋組は洋風トラスである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005220"},{"id":"00001993","register_sub_id":"101","register_pk":"102983","name":"庄子屋醤油店店舗及び住宅","kana":"しょうじやしょうゆてんてんぽおよびじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区八幡町4-222","lat":38.27012088,"lng":140.84917602,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"04 － 0032","desc":"仙台味噌醸造元の店舗住宅で国道４８号線に沿って南面して建つ。木造２階建，切妻造，桟瓦葺，平入，間口５間の店舗の背後に西に寄せて平屋建，寄棟造，桟瓦葺の住居部が取付く。仙台旧市街でも多くみられたセガイ造りの商家建築の型式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001993"},{"id":"00012870","register_sub_id":"101","register_pk":"368086","name":"壽丸屋敷主屋","kana":"すまるやしきしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県白石市字中町48-5他","lat":38.00383056,"lng":140.62306667,"geo_status":"db","era":"大正10年頃／昭和39年増築","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積338㎡","structure_material":"木造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 178","desc":"店蔵の背面に南面して建つ。入母屋造平屋建の正面東端に入母屋玄関を出し、東に洋風応接間、西に2列4室を配し、西面に角屋で上座敷棟を延ばす。東側に二階建の別棟を付し、一階に台所等、二階に居室を設ける。白石城下の商家の伝統的な構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012870"},{"id":"00012869","register_sub_id":"101","register_pk":"368085","name":"壽丸屋敷店蔵","kana":"すまるやしきみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県白石市字中町48-5他","lat":38.00375833,"lng":140.62271944,"geo_status":"db","era":"明治後期／平成17年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 177","desc":"白石旧城下中心部のもと商家で、店蔵は街路に西面して建つ。切妻造の土蔵造二階建で、一階の窓に鉄製格子を嵌め、二階に観音扉付の二窓を穿つ。一階は前土間の店舗とし、二階に二室を設ける。重厚かつ均整の取れた外観で、旧城下の街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012869"},{"id":"00004493","register_sub_id":"101","register_pk":"105483","name":"武山米店店舗及び主屋","kana":"たけやまこめてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市魚町1-1-13","lat":38.90693214,"lng":141.57292034,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、亜鉛メッキ鋼板葺、建築面積115㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"04 － 0050","desc":"奥行に従い幅の狭まる不整形な敷地に建つ変形平面の町家。屋根は切妻造の鉄板葺で，正面の垂木を扇形に配するのが特徴。２階の腰壁と戸袋は銅板張である。１階は正面一杯を店舗とする。２階の座敷２室は，敷地の制約から台形平面をなす。背後に蔵が附属する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004493"},{"id":"00012871","register_sub_id":"101","register_pk":"506171","name":"玉幸","kana":"たまこう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県白石市字堂場前24他","lat":38.00490278,"lng":140.62471389,"geo_status":"db","era":"明治後期／大正14年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺及び金属板葺、建築面積678㎡","structure_material":"木造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 179","desc":"市街地東部にある料亭。寄棟造の玄関棟北面に入母屋玄関を出し、東前方に居住棟を連ね、東背面と西面に入母屋造の東棟と西棟を接続する。東西2棟に客間計8室を並べ、居住棟に調理場等を配して一部二階建とする。戦前の町の賑わいを伝える大規模和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012871"},{"id":"00009870","register_sub_id":"101","register_pk":"196017","name":"丹六園店舗兼主屋","kana":"たんろくえんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県塩竈市宮町101","lat":38.31774624,"lng":141.01925448,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積124㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"04 － 0090","desc":"鹽竈神社門前町の角地に建つ菓子店で、入母屋造桟瓦葺である。接道する南面と東面は出桁造として軒を深め、重厚な外観を見せる。南からミセ、七畳、オカミ（座敷）、台所及び居間を並べる。南寄りに二階を設け、座敷を配する。門前町の歴史的景観を伝える商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009870"},{"id":"00009873","register_sub_id":"101","register_pk":"196020","name":"千田家住宅石蔵","kana":"ちだけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市南町2-122-1","lat":38.90557224,"lng":141.57244976,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造2階建、建築面積33㎡","structure_material":"石造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"04 － 0093","desc":"主屋の東側北寄りに東西棟で建つ。石造二階建で南に土蔵が接続する。「塩釜石」と称する凝灰岩を布積とする。窓の庇に幾何学形状の持送りを付け、軒蛇腹を人造石研出し仕上げとするなど凝った意匠である。前年の大火後に建てられ、耐火性を意識した石蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009873"},{"id":"00009871","register_sub_id":"101","register_pk":"196018","name":"千田家住宅主屋","kana":"ちだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市南町2-122-1","lat":38.90546576,"lng":141.57241467,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階一部3階建、建築面積127㎡、車庫付","structure_material":"木造2階一部3階建","registered":"2014.04.25(平成26.04.25)","register_no":"04 － 0091","desc":"内湾地区の交差点に面して建ち、木造モルタル塗で外壁に水平の張出しを廻らせる。隅部分は円弧状平面で塔屋風に三階を設け、また煙突状の飾り窓を付けてアクセントとするなど、表現主義を取入れた特徴的な外観になり、地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009871"},{"id":"00009872","register_sub_id":"101","register_pk":"196019","name":"千田家住宅土蔵","kana":"ちだけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県気仙沼市南町2-122-1","lat":38.90552881,"lng":141.57253304,"geo_status":"db","era":"大正5頃／昭和8頃・平成23改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積41㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"04 － 0092","desc":"主屋の東側に南北棟で建ち、北には石蔵が接続する。二段積の石積基礎の上に土台を廻し、柱を密に立てて貫で強固に固め、外壁はモルタル塗とする。当地区では昭和四年の大火を免れた希少な蔵であり、主屋とともに歴史的な街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009872"},{"id":"00013344","register_sub_id":"101","register_pk":"368432","name":"鳥山米穀店店舗兼主屋","kana":"とりやまべいこくてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市宮城野区原町三丁目461","lat":38.26656667,"lng":140.90683611,"geo_status":"db","era":"明治7年頃／昭和53年・同61年・平成20年改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造二階一部平屋建、瓦葺、建築面積152㎡","structure_material":"木造二階一部平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"04 － 0180","desc":"仙台城下東隣の宿場町の原町で、石巻街道に南面して建つ。木造切妻造桟瓦葺で、二階建東西棟の店舗背面に平屋建の主屋が続く。店舗正面の一階下屋は、西半に格子を嵌め、東半中央間を出入口とする。内部に通り土間がないなど、旧仙台藩領の町家の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013344"},{"id":"00010252","register_sub_id":"101","register_pk":"199026","name":"不忘閣穀蔵","kana":"ふぼうかくこくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.144905,"lng":140.53455,"geo_status":"db","era":"明治29年頃／平成18年改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積41㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0102","desc":"座敷蔵の北側に並び建つ。土蔵造、桁行九・一メートル梁間四・五メートル、文庫蔵と座敷蔵と一連の金属板葺の置屋根をかける。外壁は漆喰塗で鉢巻を廻らせ、腰を海鼠壁とし、東面中央に戸口と窓を設け、窓枠を黒漆喰で丁寧に仕上げて外観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010252"},{"id":"00010249","register_sub_id":"101","register_pk":"199023","name":"不忘閣御殿棟","kana":"ふぼうかくごてんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.144192,"lng":140.534624,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、銅板葺、建築面積161㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0099","desc":"離れ北西隅に渡廊下で接続して建つ。木造二階建、入母屋造で北面と南面に千鳥破風を飾り、周囲にガラス窓と刎高欄を廻らす。一二畳半の主座敷は上段とし、上質な座敷飾、小組格天井張など高い格式を示す。旧藩主一門の宿泊を意図した、優美な意匠の旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010249"},{"id":"00010251","register_sub_id":"101","register_pk":"199025","name":"不忘閣座敷蔵","kana":"ふぼうかくざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.144786,"lng":140.534579,"geo_status":"db","era":"明治29年頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0101","desc":"文庫蔵と穀蔵の間に並び建ち、一体的な置屋根をかける。土蔵造二階建、桁行一一メートル梁間五・五メートルである。東面に戸口を二箇所設け、外壁は漆喰塗で鉢巻を廻らせ、一階の腰及び二階東面の腰を海鼠壁とする。二階はもと居室で、逗留客に供された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010251"},{"id":"00010248","register_sub_id":"101","register_pk":"199022","name":"不忘閣離れ","kana":"ふぼうかくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.14405,"lng":140.534957,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、鉄板葺、建築面積225㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0098","desc":"本館の南側に渡廊下で接続する南北棟と、その南端から東に延びる東西棟からなる、く字形平面の木造二階建である。前庭に面して同形同大の客室を並べて開放的なガラス窓を開き、手摺を廻らして表情をつける。当地方における湯治場の様子を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010248"},{"id":"00010250","register_sub_id":"101","register_pk":"199024","name":"不忘閣文庫蔵","kana":"ふぼうかくぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.1447,"lng":140.534612,"geo_status":"db","era":"明治29年","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0100","desc":"敷地北寄りに南北に直列する土蔵群の南端に建つ。土蔵造二階建、桁行八・三メートル梁間四・五メートルで、北側の座敷蔵、穀蔵と一体の置屋根をかける。東面を戸口とし外壁は漆喰塗で鉢巻を廻らせ、腰を海鼠壁とする。明治大火を免れた、歴史的価値のある土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010250"},{"id":"00010247","register_sub_id":"101","register_pk":"199021","name":"不忘閣本館","kana":"ふぼうかくほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.144365,"lng":140.53485,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積253㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0097","desc":"青根温泉中心部に構える敷地の中央に南北棟で建つ。木造二階建で、正面中央に入母屋造の車寄、背面中央に休憩所の張出しを設ける。上下階とも中廊下を直交方向に通して平面を四分し、各室に異なる意匠の座敷飾を備える。堂々とした容姿が湯治場の情緒を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010247"},{"id":"00010253","register_sub_id":"101","register_pk":"199027","name":"不忘閣門","kana":"ふぼうかくもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.14466204,"lng":140.53492024,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、鉄板葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"04-0103","desc":"敷地東辺に構える棟門形式の門で、二・七メートルと広い間口をもつ。切妻造金属板葺で両脇に袖塀を付け、南側に潜戸を開く。木太い柱と冠木を組み、棟束と腕木で小屋を受ける。伊達家の湯別当を務めた当主佐藤家の由緒を伝え、風格ある屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010253"},{"id":"00001853","register_sub_id":"101","register_pk":"102843","name":"ゆさや旅館本館","kana":"ゆさかりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県大崎市鳴子温泉字湯元46-2、47、47-2","lat":38.74162779,"lng":140.71761638,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積695㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"04 － 0030","desc":"鳴子温泉の発祥とされる「滝の湯」の湯守となった寛永９年創業の老舗旅館で，昭和１１年の改築。木造２階建，入母屋造，瓦葺で，鉄板葺の下屋をまわす。間口は１１間半，１階は湯治部屋を中心とし，２階正面道路側に上客客室を配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001853"},{"id":"00001854","register_sub_id":"101","register_pk":"102844","name":"ゆさや旅館土蔵","kana":"ゆさやりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県大崎市鳴子温泉字湯元74-2、74-3","lat":38.74187731,"lng":140.71794821,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積35㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"04 － 0031","desc":"本館の道路を隔てた向かいの敷地奥に位置する。桁行３間半，梁行２間半規模の切妻造，妻入の蔵で，北西面の妻面に片流れの下屋を付けて蔵前とする。腰を人造石洗出し，石目地仕上げとし，開口部はアーチ型とする。構造は「木筋コンクリート」とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001854"},{"id":"00002598","register_sub_id":"101","register_pk":"103588","name":"勇駒酒造本社店舗","kana":"いさみごましゅぞうほんしゃてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市増田町増田字中町64","lat":39.20354338,"lng":140.54599736,"geo_status":"db","era":"大正末期／昭和10代増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、鉄板葺、建築面積104㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0086","desc":"増田町の中心部，街道沿いにある。東西に細長い敷地で，店舗はその東に建つ。入母屋造の２階建で，正面となる東面に平屋建で看板建築の店舗を設ける。看板部分はセメントモルタルで酒樽を模した鏝絵を描き，商家の並ぶ町並の中で存在感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002598"},{"id":"00007719","register_sub_id":"101","register_pk":"108701","name":"石直商店店舗兼主屋","kana":"いしなおしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字七日町122","lat":39.20238448,"lng":140.54653011,"geo_status":"db","era":"明治前期／昭和43改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積258㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05-0168","desc":"通りの東に占める短冊状の敷地の西端に建つ。切妻造妻入鉄板葺で、正面は白漆喰壁に束や梁をあらわす。正面側を店舗とし、通り土間を付ける居室を奥に配する。店舗２階は舟底状の天井を張る座敷で、トコや付書院を構え、通り側に縁を設ける。商家の構えをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007719"},{"id":"00007720","register_sub_id":"101","register_pk":"108702","name":"石直商店文庫蔵","kana":"いしなおしょうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字七日町122","lat":39.20244404,"lng":140.547013,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05-0169","desc":"敷地の中央に東西棟で建つ。桁行７．３ｍ梁間４．６ｍの土蔵造２階建、置屋根の切妻造妻入鉄板葺とする。外壁は白漆喰仕上げで、腰に下見板を張る。西面の入口には片引戸をたてる。小屋組は梁上に束と小梁で地棟を支持し、密に垂木を配る。丁寧に造られた土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007720"},{"id":"00012467","register_sub_id":"101","register_pk":"367762","name":"今野商店土蔵","kana":"いまのしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市大森町字大森175","lat":39.343822,"lng":140.427719,"geo_status":"geocoded","era":"明治43年／大正15年･昭和47年頃改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造一部煉瓦造2階建、金属板葺、建築面積39㎡","structure_material":"土蔵造一部煉瓦造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"05 － 0219","desc":"店蔵背面に接し、東の街路に面して建つ。土蔵造二階建、切妻造妻入で、南側面と一階正面南半の壁は煉瓦造の現しとする。正面は白漆喰塗を基調としつつ、破風と円弧状の窓庇を黒漆喰塗として表構えを引締める。店蔵と同じく街路沿いの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012467"},{"id":"00012466","register_sub_id":"101","register_pk":"367761","name":"今野商店店蔵","kana":"いまのしょうてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市大森町字大森175","lat":39.31374139,"lng":140.56669444,"geo_status":"db","era":"大正15年／昭和47年頃・平成28年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"05 － 0218","desc":"大森町にある商家で、店蔵は敷地東北隅に北面して建つ。土蔵造二階建で、切妻屋根を矩折れにかける。一階は正面を石造風とし、東側面に下屋を付す。内部は店舗空間を広く取り、中央部に吹抜けを設ける。市街中心部の角地にあって歴史的景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012466"},{"id":"00001033","register_sub_id":"101","register_pk":"102023","name":"木村屋商店本店","kana":"きむらやしょうてんほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市大町5-23","lat":39.31514555,"lng":140.56823892,"geo_status":"db","era":"明治37頃","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造２階建，鉄板葺，建築面積35㎡","structure_material":"土蔵造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"05 － 0046","desc":"旧羽州街道沿い，横手市街の藩政期以降に栄えた商業地に位置し，旅館「平利」・「平源」旅館の向いに建つ。明治３５・３６年の大火の教訓から蔵造りとした店舗建築で，２階に重厚な防火戸を付ける。羽州街道の町並みを知る上で貴重な遺構のひとつになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001033"},{"id":"00008245","register_sub_id":"101","register_pk":"133887","name":"旧石宇商店座敷蔵","kana":"きゅういしうしょうてんざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県横手市増田町増田字七日町140","lat":39.20329473,"lng":140.54564607,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積101㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0181","desc":"短冊状の敷地の中央、東西棟で建つ。桁行９．１ｍ梁間４．２ｍの２階建土蔵。置屋根で周囲に鞘を設ける。切石積基礎上、漆喰仕上げとし、腰などを黒漆喰とする。１階は前後二室に分け、奥の座敷にはトコなどを構える。地区内において掉尾に位置する座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008245"},{"id":"00008243","register_sub_id":"101","register_pk":"133885","name":"旧栄助商店座敷蔵","kana":"きゅうえいすけしょうてんざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市増田町増田字七日町154-2他","lat":39.20212833,"lng":140.54613894,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、鉄板葺、建築面積116㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0179","desc":"通りに東面する短冊形の敷地中央に位置する。桁行９．１ｍ梁間５．６ｍの切妻造妻入で、鉄板葺の置屋根とし、周囲に鞘を設ける。切石積基礎上に建ち、漆喰仕上げで、腰や開口部などを黒漆喰とする。伝統的な架構を用いており、当地における標準的な座敷蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008243"},{"id":"00001833","register_sub_id":"101","register_pk":"102823","name":"旧大島商会店舗","kana":"きゅうおおしましょうかいてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市大町一丁目8-2","lat":39.71937222,"lng":140.11811944,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積73㎡","structure_material":"煉瓦造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0066","desc":"秋田市内最初期の煉瓦造建築で，両側面及び背面に控壁を設ける。基礎と建物四隅，及びアーチ型の開口部廻りに積んだ切石の白さが赤煉瓦壁に映える。高級雑貨等を販売した県内最初の百貨店として建設されたもので，１階正面中央のアーチ型の広い出入口に特色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001833"},{"id":"00013493","register_sub_id":"101","register_pk":"504858","name":"旧加藤茶舗店蔵","kana":"きゅうかとうちゃほみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県横手市十文字町字曙町7-3","lat":39.22172778,"lng":140.52425,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、鉄板葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"05 － 0234","desc":"吉乃鉱山の物資運搬拠点として発展した十文字に所在。二階建切妻造平入で一間幅の下屋を設ける。一階は四間幅の間口いっぱいを開口とした開放的な構えとし、二階は引込戸の窓を開ける。一階は一室として柱を密に立てる。地域のランドマーク的存在の店舗。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013493"},{"id":"00007715","register_sub_id":"101","register_pk":"108697","name":"旧佐々虎呉服店（佐々木家住宅）資材蔵","kana":"きゅうささとらごふくてんしざいぐら（ささきけじゅうたく）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字中町91","lat":39.20464875,"lng":140.54663574,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積111㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05 - 0164","desc":"座敷蔵の東南に東西棟で建つ。桁行１２ｍ梁間５．２ｍの土蔵造２階建で、切妻造鉄板葺の置屋根とする。白漆喰仕上げで、西正面には掛子塗の両開戸を構え、上部に鏝絵の家紋を飾る。内部は板敷で、１、２階とも二室に間仕切る。増田地区における最大規模の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007715"},{"id":"00007713","register_sub_id":"101","register_pk":"108695","name":"旧佐々虎呉服店（佐々木家住宅）主屋及び座敷蔵","kana":"きゅうささとらごふくてんしゅおくおよびざしきくら（ささきけじゅうたく）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県横手市増田町増田字中町91","lat":39.20466606,"lng":140.54622351,"geo_status":"db","era":"昭和15・明治17","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造一部土蔵造2階建、鉄板葺、建築面積199㎡","structure_material":"木造一部土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05 - 0162","desc":"主屋と座敷蔵が東西に連続して建つ。主屋は切妻造の木造２階建。南面に吹抜けの廊下を設け、北側には１、２階とも二室を配し、数寄屋風意匠になる接客用座敷とする。座敷蔵は大規模な土蔵造２階建、主屋側は黒漆喰磨仕上げで、角に施された白漆喰の線が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007713"},{"id":"00007718","register_sub_id":"101","register_pk":"108700","name":"旧佐藤三十郎商店店舗兼主屋及び座敷蔵","kana":"きゅうさとうさんじゅうろうしょうてんてんぽけんしゅおくおよびざしきくら","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字七日町147","lat":39.20277144,"lng":140.54598212,"geo_status":"db","era":"明治20・明治11／大正期・昭和50頃改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造一部土蔵造平屋一部2階建、鉄板葺、建築面積385㎡","structure_material":"木造一部土蔵造平屋一部2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05-0167","desc":"東面する切妻造妻入の店舗兼主屋と、その西の座敷蔵が連続して建ち、南に通り土間を設ける。正面は白漆喰壁に短い束と梁の伝統的構え。座敷蔵は１階西寄りを南北二室に間仕切り、南に座敷、北に納戸を配する。座敷は漆塗とし、凝った造りの浅いトコを構える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007718"},{"id":"00007838","register_sub_id":"101","register_pk":"108819","name":"旧清水肉店店舗兼主屋","kana":"きゅうしみずにくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県横手市増田町増田字本町76","lat":39.2049405,"lng":140.54456729,"geo_status":"db","era":"昭和8／昭和51・平成10改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積154㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"05 - 0173","desc":"南北に細長い敷地に南寄りに建つ。 桁行１９ｍ梁間８．２ｍの木造２階建、南北棟の切妻造鉄板葺。南妻面は、螻羽が深く、小屋組を現す白漆喰仕上げとし、庇に吹寄垂木と疎垂木を併用。内部は一部を吹抜けとする通り土間を南側に設ける。積雪地らしい町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007838"},{"id":"00005539","register_sub_id":"101","register_pk":"106527","name":"旧関善酒店主屋","kana":"きゅうせきぜんしゅてんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県鹿角市花輪字上花輪85","lat":40.185196,"lng":140.789032,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積590㎡","structure_material":"木造平屋一部2階建","registered":"2006.08.03(平成18.08.03)","register_no":"05 － 0146","desc":"県道に西面して建つ。桁行１４間，梁間１１間の規模で，木造平屋一部２階建，切妻造，鉄板葺，平入とし，正面にこみせを設ける。北側を床上部とし，表側に店土間をとり，通り土間を通す。通り土間上部の架構は見事で，全体に技術，規模，意匠共に秀でる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005539"},{"id":"00008246","register_sub_id":"101","register_pk":"133888","name":"旧長江八兵衛商店座敷蔵","kana":"きゅうながえはちべえしょうてんざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県横手市増田町増田字中町66","lat":39.20367931,"lng":140.54565786,"geo_status":"db","era":"弘化4年(1847)","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積152㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0182","desc":"東西に細長い敷地の中央に東西棟で建つ妻入の２階建土蔵。桁行１５ｍ梁間５．９ｍで、切妻造鉄板葺の鞘を設ける。外観は黒漆喰と白漆喰を塗り分ける。１階西寄りに畳敷の居室を間仕切り、トコやトコ脇を構え、柱を漆塗とする。梁組など古風な仕様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008246"},{"id":"00007836","register_sub_id":"101","register_pk":"108817","name":"旧長江八兵衛商店味噌蔵","kana":"きゅうながえはちべえしょうてんみそぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字中町66","lat":39.20368554,"lng":140.54529245,"geo_status":"db","era":"明治前期／大正期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、金属板葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"05-0171","desc":"東と北に接道し、東西に細長い敷地の西端に建つ。桁行８．２ｍ梁間５．５ｍの土蔵造２階建で、東西棟の切妻造金属板葺。東妻面にトマエを付し、掛子塗三段の土扉を中心からずらして吊る。内部は１、２階とも一室。当地域における古い形式の小屋架構を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007836"},{"id":"00004897","register_sub_id":"101","register_pk":"105887","name":"國萬歳酒造主屋","kana":"くにばんざいしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県秋田市新屋元町142他","lat":39.68418176,"lng":140.08396517,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階一部平屋建、鋼板葺、建築面積270㎡","structure_material":"木造2階一部平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"05 － 0123","desc":"市街地南部の雄物川左岸，旧羽州浜街道沿いに位置する。間口３間半，寄棟造，妻入の木造２階建で，正面に張出す庇の中央に切妻の玄関を設ける。内部は，通り土間に沿って帳場及びオエを配する。醸造業が盛んな新屋地区の歴史的街路景観の構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004897"},{"id":"00007716","register_sub_id":"101","register_pk":"108698","name":"興文館東海林書店店舗兼主屋及び座敷蔵","kana":"こうぶんかんしょうじしょてんてんぽけんしゅおくおよびざしきくら","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字中町100","lat":39.20382196,"lng":140.54637551,"geo_status":"db","era":"明治前期・明治2／大正2改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造一部土蔵造2階一部平屋建、鉄板葺、建築面積459㎡","structure_material":"木造一部土蔵造2階一部平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"05 - 0165","desc":"通りに西面して、店舗兼主屋、座敷蔵が東西に連続して建つ。正面に入母屋造２階建を配し、その東に三段に棟高が異なる切妻屋根が続く。主屋は南の庭園側に明るく開放的な通り土間を設け、北に居室を配する。座敷蔵は増田地区における古い座敷蔵のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007716"},{"id":"00008242","register_sub_id":"101","register_pk":"133884","name":"佐々平商店文庫蔵","kana":"ささへいしょうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県横手市増田町増田字中町96","lat":39.20414373,"lng":140.54640858,"geo_status":"db","era":"文久4年(1864)／大正6年改修","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積114㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0178","desc":"東西に長い敷地に東西棟で建つ。桁行１１ｍ梁間５．４ｍ、妻入の２階建土蔵で、鉄板葺の鞘を設ける。西面の出入口を黒漆喰、他を白漆喰で仕上げる。束を建て鳥居型とする二重梁を妻面に、梁上に小梁二段を重ねる三重梁を中間に置き棟木を支持する古い架構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008242"},{"id":"00007837","register_sub_id":"101","register_pk":"108818","name":"佐藤養助漆蔵資料館旧米蔵","kana":"さとうようすけうるしぐらしりょうかんきゅうこめぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県横手市増田町増田字本町5他","lat":39.20536749,"lng":140.54533367,"geo_status":"db","era":"大正後期／平成13改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、鉄板葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"05-0172","desc":"南北に長い矩形敷地の北東に建つ。桁行７．３ｍ梁間５．５ｍの土蔵造２階建、切妻造鉄板葺。南妻に主たる出入口を穿ち、黒漆喰仕上げとし、角に白漆喰を配し、冠木中央には「龍」の字を鏝細工で飾る。掛子塗三段の両開扉を吊る。丁寧に仕上げられた土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007837"},{"id":"00001832","register_sub_id":"101","register_pk":"102822","name":"高砂堂店舗","kana":"たかさごどうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県秋田市保戸野通町2-24","lat":39.72065599,"lng":140.118591,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0065","desc":"商店街の角地に建つ木造２階建，寄棟造の店舗。街路側二面に庇を設ける。白漆喰塗籠，瓦葺の和風の外観とするが，内部は洋風とし一階床に男鹿石，ショーケース台に大理石や瑪瑙を用いる。設計・施工は大工藤本東三郎。平成７年，道路拡幅に伴い後方に曳屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001832"},{"id":"00008244","register_sub_id":"101","register_pk":"133886","name":"髙橋茶舗座敷蔵","kana":"たかはしさほざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県横手市増田町増田字七日町151","lat":39.20234667,"lng":140.54605127,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積171㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0180","desc":"東西に細長い敷地の中央に東西棟で建つ。桁行１１ｍ梁間６．４ｍの２階建土蔵、切妻造の置屋根とし、周囲に鞘を設ける。切石積基礎上、全体を黒漆喰仕上げとし、細く白漆喰で角など輪郭を縁取る。１階内部はもとは三室に間仕切られ、透かし彫りの欄間が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008244"},{"id":"00007952","register_sub_id":"101","register_pk":"128785","name":"鶴の湯温泉本陣","kana":"つるのゆおんせんほんじん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県仙北市田沢湖田沢字湯ノ岱2番地先先達沢国有林生保内事業区50林班ハ小班","lat":39.80515018,"lng":140.77966356,"geo_status":"db","era":"明治前期／昭和後期・平成10頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺、建築面積225㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"05-0174","desc":"東西４３ｍと桁行に長い建物で、寄棟造茅葺とし、南面に煙出を設ける。西半部は入口土間と十一畳からなる客室五室を並べ、東半部には休憩室や事務室などを配する。外壁は竪板張とし、内部には釿仕上げの梁を架け渡す。風趣に富む湯治場の雰囲気をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007952"},{"id":"00003496","register_sub_id":"101","register_pk":"104486","name":"十和田ホテル本館","kana":"とわだほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県鹿角郡小坂町十和田湖字鉛山","lat":40.43953794,"lng":140.84358214,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造一部鉄筋コンクリート造3階建、鋼板葺、建築面積780㎡","structure_material":"木造一部鉄筋コンクリート造3階建","registered":"2003.09.19(平成15.09.19)","register_no":"05 － 0094","desc":"十和田八幡平国立公園内の湖畔高台に築かれた県営ホテル。Ｌ字形平面で、外装全体に秋田杉を用い，石積基壇上に半割の丸太を配すのが特徴。内部は，玄関吹抜や銘木を用いた巧妙な意匠の室内など見所が多い。昭和前期の大規模木造建築の好例。設計は長倉謙介。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003496"},{"id":"00009878","register_sub_id":"101","register_pk":"196025","name":"那波紙店五号倉庫","kana":"なばかみてんごごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県秋田市大町5-249-11","lat":39.71505378,"lng":140.11400615,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積111㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0199","desc":"店舗兼主屋の斜向かいの敷地に東西棟で建つ。木造二階建、桁行一四・六メートル梁間七・六メートル、切妻造鉄板葺で小屋はキングポストトラスを組む。外壁はモルタル塗で、正面となる東妻は洗出し仕上げとし、妻壁を立ち上げ、柱形を表すなど意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009878"},{"id":"00009876","register_sub_id":"101","register_pk":"196023","name":"那波紙店商品蔵","kana":"なばかみてんしょうひんぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市大町4-219他","lat":39.7152667,"lng":140.11476504,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積157㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0197","desc":"店舗兼主屋の後方南寄りに東西棟で建つ。土蔵造二階建、桁行一一メートル梁間六・七メートルで、並び建つ文庫蔵とともに鞘屋根を一連に架けて、主屋と一体的な空間構成とする。二重梁の上に舟肘木状の材を直交させて棟木を受ける小屋組に、地方的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009876"},{"id":"00009874","register_sub_id":"101","register_pk":"196021","name":"那波紙店店舗兼主屋","kana":"なばかみてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市大町4-219他","lat":39.71531667,"lng":140.11453661,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、鉄板葺、建築面積463㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0195","desc":"久保田城の南西方敷地に西面して建つ。切妻造妻入鉄板葺で、南西面に下屋を廻らし、妻壁の梁や束を化粧で現す。南側に通す土間沿いにオエや台所を並べ、奥寄りの仏間や座敷を鍵型に張出す。コミセの名残をとどめる間取りや妻壁意匠に当地の町家の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009874"},{"id":"00009875","register_sub_id":"101","register_pk":"196022","name":"那波紙店文庫蔵","kana":"なばかみてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市大町4-219他","lat":39.71533094,"lng":140.11477932,"geo_status":"db","era":"明治中期／明治41移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鋼板葺、建築面積106㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0196","desc":"店舗兼主屋の後方北寄りに東西棟で建つ。土蔵造二階建、桁行七・三メートル梁間五・二メートルで、置屋根式の屋根を主屋の屋根と一連とし、内蔵形式とする。外壁漆喰塗で鉢巻を廻らし、西面の戸口に上質な掛子塗の扉を吊り、要所を黒漆喰塗で引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009875"},{"id":"00009877","register_sub_id":"101","register_pk":"196024","name":"那波紙店向かい蔵","kana":"なばかみてんむかいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市大町5-201-2","lat":39.71510613,"lng":140.11472475,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鋼板葺、建築面積70㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0198","desc":"商品蔵と通りを挟む敷地に東西棟で建つ切妻造で、桁行九・七メートル梁間五メートル、土蔵造二階建である。西妻を戸口として下屋を設け、南面に窓を設ける。外壁は漆喰塗で腰を簓子下見板張とする。小屋組は、商品蔵に似て、二重梁で棟木を支持する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009877"},{"id":"00002591","register_sub_id":"101","register_pk":"103581","name":"日の丸醸造本社店舗","kana":"ひのまるじょうぞうほんしゃてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町七日町114-2","lat":39.2020569,"lng":140.54656071,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、鉄板葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0079","desc":"増田町の中心部にあり，街道に西面して建つ平屋建の店舗建築。切妻造・鉄板葺で，妻入とする。通りに面した妻面は４重の化粧梁を見せ，地棟を突出させて，下屋庇を葺き下ろした構成になり，緩勾配の屋根と相俟って，当地方の妻入町家の形態をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002591"},{"id":"00000182","register_sub_id":"101","register_pk":"101172","name":"平源旅館土蔵","kana":"ひらげんりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市大町6-24","lat":39.31522449,"lng":140.56859758,"geo_status":"db","era":"大正15以前","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建，鋼板葺，建築面積81㎡","structure_material":"土蔵造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"05 － 0014","desc":"本館の脇に、同じく街道に面して建つ土蔵である。大正15年の火災に際して本館は焼失したが、この土蔵は難を逃れた。腰の部分を石張とする外観が特徴的であり、洋風の本館部分と好対照をなす。大火以前の横手の様子を今日に伝える建物として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000182"},{"id":"00000181","register_sub_id":"101","register_pk":"101171","name":"平源旅館本店","kana":"ひらげんりょかんほんてん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市大町6-24","lat":39.31540133,"lng":140.56868259,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建，鋼板葺，建築面積675㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"05 － 0013","desc":"旧街道に面して建つ旅館で、皇族が宿泊するなど高い格式を誇る。外観は洋風であるが、内装のほとんどは和風である。意匠ではなく部材の取り扱いで格を示す内装や、玄関部やトイレなどのタイルの意匠、ファサード廻りの装飾などが特に優れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000181"},{"id":"00005536","register_sub_id":"101","register_pk":"106524","name":"森九商店主屋","kana":"もりきゅうしょうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県秋田市新屋表町9-40","lat":39.68086557,"lng":140.08266927,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋一部2階建、鋼板葺、建築面積175㎡","structure_material":"木造平屋一部2階建","registered":"2006.08.03(平成18.08.03)","register_no":"05 － 0143","desc":"醸造業の多い表町の旧街道沿いに西面して建つ。桁行１１間半，梁間５間の規模で，木造平屋建，切妻造，鋼板葺，妻入とし，南側を通り土間とする。正面は奥行１間半の下屋庇を出し，その上方の妻面には梁組を表して意匠とし，旧街道の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005536"},{"id":"00004496","register_sub_id":"101","register_pk":"105486","name":"森長旅館土蔵","kana":"もりちょうりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県男鹿市船川港船川字栄町82","lat":39.88390466,"lng":139.84733203,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、鉄板葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"05 － 0115","desc":"本館から庭を挟んだ敷地北東隅に建つ。土蔵造２階建で，切妻造の置屋根を鉄棒の方杖が支える。西面に戸口を設け，両妻に各１箇所の窓を開く。男鹿石の切石基礎上に建ち，外壁は白漆喰塗で，腰部と鉢巻を黒漆喰塗とする。街路側の窓周りの漆喰彫刻が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004496"},{"id":"00004495","register_sub_id":"101","register_pk":"105485","name":"森長旅館離れ","kana":"もりちょうりょかんはなれ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"秋田県","address":"秋田県男鹿市船川港船川字栄町82","lat":39.88378745,"lng":139.84725273,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積79㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"05 － 0114","desc":"本館の東南に位置し，附属棟から２階の渡廊下で接続する木造２階建である。屋根は寄棟造で鉄板葺とする。外壁は下見板張である。１階は物置で２階に１０畳と８畳の床構えをもつ客室を設ける。北面に庇を付けて１間幅の廊下とし，手摺付の濡縁を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004495"},{"id":"00004494","register_sub_id":"101","register_pk":"105484","name":"森長旅館本館","kana":"もりちょうりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県男鹿市船川港船川字栄町82","lat":39.88388169,"lng":139.84712683,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積237㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"05 － 0113","desc":"角地に建つ木造２階建洋風旅館で，方形マンサード屋根を鉄板葺とする。外壁はモルタル仕上で隅柱を見せ，胴蛇腹と軒蛇腹を廻す。北面玄関は起り破風に蝙蝠を飾る。内部は中廊下で和室の客室を配し，背面には厨房等を置く。船川港の往時の賑わいを伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004494"},{"id":"00008241","register_sub_id":"101","register_pk":"133883","name":"山中吉助商店座敷蔵","kana":"やまなかきちすけしょうてんざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字中町104","lat":39.20353881,"lng":140.54652803,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積131㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0177","desc":"細長い敷地の中央に位置する、妻入の２階建土蔵。西妻や開口部を黒漆喰、他を白漆喰とする。１階は当初は前後二室に分け、後方の室には棹を漆塗とする棹縁天井を張る。１階は一尺五寸毎に栗と杉の柱を交互に密に建てる。当地域の典型的な意匠を示す座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008241"},{"id":"00000810","register_sub_id":"101","register_pk":"101800","name":"料亭金勇","kana":"りょうていかねゆう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県能代市柳町13-8","lat":40.20896537,"lng":140.02537986,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積469㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"05 － 0034","desc":"県内屈指の老舗料亭の大規模和風建築。外観は，２階に手摺り，１階に庇を付け正面及び側面両端に入母屋屋根を付ける賑やかな構成になる。１１０畳大の２階大広間はじめ各室は上質な造りになり，秋田杉の本場能代を象徴する建物として広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000810"},{"id":"00001479","register_sub_id":"101","register_pk":"102469","name":"阿久津家住宅店蔵","kana":"あくつけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県南会津郡南会津町針生字鳥井戸1186","lat":37.18841374,"lng":139.66029581,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積127㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"07 － 0036","desc":"北を正面として建ち，墨書より大正５年の建築とわかる。寄棟造・妻入で，平面は凸形になる。北突出部が土蔵造・２階建で座敷をもち，南が真壁造・平屋建で広間と土間を配し，鉄板葺（もと茅葺）の大屋根を架けた形式で，この地方では店蔵造といわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001479"},{"id":"00001163","register_sub_id":"101","register_pk":"102153","name":"和泉屋旅館主屋","kana":"いずみやりょかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県南会津郡南会津町田島字上町甲4047、4048","lat":37.20090258,"lng":139.77255927,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造２階建，瓦葺，建築面積536㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"07 － 0030","desc":"田島町の市街のほぼ中央に建つ木造２階建の旅館建築。昭和９年５月の大火直後に再建された。棟梁は越後の大工で、要所に銘木を用いており全体に凝った造りとなる。正面中央に組物付きの向唐破風造りの大玄関が付く特異な外観は、広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001163"},{"id":"00001164","register_sub_id":"101","register_pk":"102154","name":"和泉屋旅館土蔵","kana":"いずみやりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県南会津郡南会津町田島字上町甲4047","lat":37.20109651,"lng":139.77259007,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，鉄板葺，建築面積115㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"07 － 0031","desc":"奥行きの長い敷地の中央東端に建つ妻入の南北棟で、建築年代は様式から明治期と推定される。間口２間半、奥行６間で、南面に庇が付く。内外の造作とも標準的な規模になり、営業用の什器類を納める。屋根は置屋根とし、上部に昭和９年の大火の痕跡が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001164"},{"id":"00001856","register_sub_id":"101","register_pk":"102846","name":"御菓子師玉嶋屋主屋","kana":"おんかししたましまやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県二本松市本町一丁目86","lat":37.5914,"lng":140.43605,"geo_status":"db","era":"大正8頃／昭和13増築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、金属板葺、建築面積251㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"07 － 0042","desc":"旧国道４号線に面して建つ。大正７年の大火後の再建になり，木造２階建，銅板瓦棒葺，切妻造，平入の店舗の奥に応接室，台所，昭和１３年建設の座敷を通土間に沿って配する。正面庇上に立てた２本の袖看板が特徴的で，屋号を打ち出した銅細工にも見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001856"},{"id":"00000510","register_sub_id":"101","register_pk":"101500","name":"花水館奥の間（御殿）","kana":"かすいかんおくのま（ごてん）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県福島市飯坂町字西滝ノ町21","lat":37.83459505,"lng":140.45238351,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積71㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0008","desc":"貴賓客が宿泊するための座敷で，旅館の中庭に建つ。１０畳間２室からなる室内は，柱や天井等の造作に良質な材料を用い，床の間等に銘木を用いる等，入念で優れた仕上げになる。平屋建ながら２重の銅板屋根を持つ外観はこの時代の特徴を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000510"},{"id":"00008812","register_sub_id":"101","register_pk":"162255","name":"冠木商店質蔵","kana":"かぶきしょうてんしちぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県喜多方市字一丁目4536-1","lat":37.65337698,"lng":139.87293403,"geo_status":"db","era":"天保13年(1842)","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0126","desc":"座敷蔵の東に位置する。東西棟の切妻造桟瓦葺、桁行11ｍ梁間4.8ｍで、西面に蔵前を設ける。土蔵造2階建。漆喰仕上げとし、西面には両開戸の出入口、東面には片開戸の窓2箇所を穿ち、いずれも掛子塗。市内に残る古い土蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008812"},{"id":"00008811","register_sub_id":"101","register_pk":"162254","name":"冠木商店主屋及び座敷蔵","kana":"かぶきしょうてんしゅおくおよびざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県喜多方市字一丁目4536-1","lat":37.65336847,"lng":139.87267706,"geo_status":"db","era":"嘉永7年(1854)／明治中期増築・昭和4年改築","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造及び土蔵造2階建、瓦葺、建築面積268㎡","structure_material":"木造及び土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0125","desc":"通りに西面する敷地の西寄りに主屋を建て、東に座敷蔵、南に2階座敷を付設。建築面積268㎡の木造及び土蔵造2階建、入母屋棟と切妻棟を組み合わせる桟瓦葺屋根。座敷蔵は漆喰仕上げで、一部を黒漆喰とする。良質な座敷を残す、老舗商家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008811"},{"id":"00008813","register_sub_id":"101","register_pk":"162256","name":"冠木商店南の蔵","kana":"かぶきしょうてんみなみのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字一丁目4536-1","lat":37.65331061,"lng":139.87292211,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0127","desc":"質蔵の南に位置し、南は小路沿いとなる。東西棟の切妻造桟瓦葺、桁行11ｍ梁間4.8mで、蔵前を設ける。蔵前は瓦葺庇をかけ、軒まで塗り込める。小路側は腰に煉瓦を積み、上部を中塗、鉢巻を漆喰仕上げとし、街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008813"},{"id":"00002351","register_sub_id":"101","register_pk":"103341","name":"旧甲斐家住宅店蔵","kana":"きゅうかいけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市字1-4611","lat":37.65644047,"lng":139.87212035,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積103㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"07 － 0056","desc":"江戸期には酒造業，明治以後味噌醤油の醸造業を営む商家の店蔵。一階に店舗，応接間，２階に座敷を配し，上下階を螺旋状の階段で連絡する。立ちが高く，２階の軒を大きく持ち出した重厚な外観を造るとともに，２階窓回りなど細部には精巧な仕事がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002351"},{"id":"00012872","register_sub_id":"101","register_pk":"367980","name":"旧採進堂酒店主屋","kana":"きゅうさいしんどうさけてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市飯坂町字湯沢9-2","lat":37.832225,"lng":140.45259167,"geo_status":"db","era":"明治31年頃／昭和10年頃・同50年代増築、昭和30年代改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"07 － 0210","desc":"飯坂温泉中心部の街路に北面して建つ。切妻造桟瓦葺の二階建一部平屋建、背面東側にカッテ、ザシキを突出し、二階の中廊下沿いに居室を配する。二階正面は出格子と当地域特有の鎬付の出梁を備え、下屋上に銘酒の看板を並べる。近代温泉地の隆盛を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012872"},{"id":"00008816","register_sub_id":"101","register_pk":"162259","name":"旧嶋新商店一号蔵・二号蔵及び三号蔵","kana":"きゅうしましんしょうてんいちごうくら・にごうくらおよびさんごうくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字一丁目4647-1","lat":37.65357634,"lng":139.87169238,"geo_status":"db","era":"明治18年","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積204㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0130","desc":"東西に長い敷地中央に位置する。桁行36ｍに及ぶ2階建土蔵。東から3室に分け、東端の1号蔵は東面に蔵前を設け、2・3号蔵は南面に出入口を穿つ。切妻造桟瓦葺。腰板張の漆喰仕上げで、鳥居型に仕上げた窓を要所に配し、リズミカルな外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008816"},{"id":"00008815","register_sub_id":"101","register_pk":"162258","name":"旧嶋新商店座敷蔵及び主屋","kana":"きゅうしましんしょうてんざしきぐらおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字一丁目4647-1","lat":37.65348807,"lng":139.87206224,"geo_status":"db","era":"明治11年／明治中期・昭和後期改修","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"土蔵造及び木造2階建、瓦葺及び鉄板葺、建築面積185㎡","structure_material":"土蔵造及び木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0129","desc":"店舗蔵西に座敷蔵、主屋と続く。座敷蔵は東西棟の切妻造桟瓦葺で、南面に下屋を付設。土蔵造2階建、漆喰仕上げ、2階に掛子塗戸を吊る。南面に廊下を通し、トコを構えるザシキなど3室を北側に並べ、西奥に主屋の板間や台所を配する。喜多方の町家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008815"},{"id":"00008814","register_sub_id":"101","register_pk":"162257","name":"旧嶋新商店店舗蔵","kana":"きゅうしましんしょうてんてんぽぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字一丁目4647-1","lat":37.65342923,"lng":139.87222932,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0128","desc":"通りに東面する平入町家。切妻造桟瓦葺の木造2階建で、正・背面に下屋を付設。間口12ｍ奥行9.0ｍ。1階は店舗、2階に座敷3室を配する。正面2階は漆喰塗大壁造とし、窓を3所穿つ。妻壁は煉瓦積。煉瓦と漆喰壁が印象的な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008814"},{"id":"00008817","register_sub_id":"101","register_pk":"162260","name":"旧嶋新商店四号蔵","kana":"きゅうしましんしょうてんよんごうくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字一丁目4647-1","lat":37.65363938,"lng":139.87142128,"geo_status":"db","era":"明治18年","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0131","desc":"3号蔵西に東西棟で建つ。東面切妻造、西面寄棟造の桟瓦葺、桁行9.6ｍ梁間5.7ｍの土蔵造2階建。南面東に庇を付け、掛子塗戸を吊る。腰板張、漆喰仕上げ、窓枠は鳥居型で鉄扉を開く。大規模な2階建土蔵が連続する重厚な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008817"},{"id":"00008818","register_sub_id":"101","register_pk":"162261","name":"旧山時呉服店家財蔵","kana":"きゅうやまときごふくてんかざいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県喜多方市字一丁目4647-2","lat":37.65385668,"lng":139.87163127,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積89㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"07 － 0132","desc":"通りの西側に占める短冊形の敷地中央に位置する。桁行13ｍ梁間6.7ｍの2階建土蔵。切妻造桟瓦葺、南面の中央に出入口を穿ち、引戸をたてる。出入口まわりや南面の腰をモルタル仕上げ、小屋組をトラス組とするなど近代的な仕様になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008818"},{"id":"00014731","register_sub_id":"101","register_pk":"518989","name":"栗花家住宅主屋","kana":"くりはなけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県伊達郡桑折町字北町76","lat":37.847625,"lng":140.51868889,"geo_status":"db","era":"明治41年／昭和後期増築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積129㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"07 - 0282","desc":"旧蚕物商の店蔵の東に接続して建つ主屋。平屋建切妻造桟瓦葺の東西棟で、敷地北辺に寄せて建ち、南側に通路を設ける。内部は四室を配して北東隅を床構え付き座敷とし、東に風呂便所を角屋で延ばす。店蔵と一体となって街道沿いの歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014731"},{"id":"00014730","register_sub_id":"101","register_pk":"518988","name":"栗花家住宅店蔵","kana":"くりはなけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県伊達郡桑折町字北町76","lat":37.84763056,"lng":140.518575,"geo_status":"db","era":"明治41年／平成23年改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"07 - 0281","desc":"桑折宿の中心部に位置する蚕物商の店蔵。奥州街道に西面する二階建切妻造平入鉄板葺で、外壁は軒まで塗込め、二階南北妻に窓を各1箇所開ける。一階は前土間のミセで摺上戸を残し、二階は一室で繭の保管場。重厚な外観が街道沿いの歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014730"},{"id":"00011631","register_sub_id":"101","register_pk":"210647","name":"源泉亭湯口屋旅館本館","kana":"げんせんていゆぐちやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県岩瀬郡天栄村大字湯本字居平14-1他","lat":37.278758,"lng":139.991437,"geo_status":"db","era":"明治4年頃","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造2階建、茅葺、建築面積405㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"07-0175","desc":"集落の中央通り最奥に建つ旅館。木造二階建、寄棟造茅葺屋根。傾斜地に建つため各階床高に段差が設けられている。一階茶の間は吹抜けとして上部梁を表し、二階には客室を配す。大規模な茅葺建物で、湯治場として知られる岩瀬湯本温泉の景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011631"},{"id":"00008247","register_sub_id":"101","register_pk":"133889","name":"島慶園店舗蔵","kana":"しまけいえんてんぽぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県喜多方市字二丁目4656-3","lat":37.65269099,"lng":139.87227407,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積78㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0109","desc":"通りに西面して建つ。間口１０ｍの土蔵造２階建、切妻造桟瓦葺で、正面に下屋を付設する。白漆喰仕上げで、２階窓まわりを黒漆喰とする。１階を広い店舗、２階を板敷の倉庫とし、トラス組を現す。店蔵が建ち並ぶ通りに位置し、伝統的な街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008247"},{"id":"00013495","register_sub_id":"101","register_pk":"504860","name":"鈴木屋利兵衛旧主屋","kana":"すずきやりへえきゅうおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県会津若松市大町一丁目357","lat":37.498725,"lng":139.92837778,"geo_status":"db","era":"江戸末期／明治後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"07 － 0241","desc":"店蔵の背後に接続して建つ。木造平屋建、切妻造鉄板葺で、外壁は漆喰で軒先まで塗込める。内部は一列四室を配して北東に土間を突出する。小屋組を土で塗込める他、居室部の柱や長押なども塗込めた上で化粧板を張るなど、当主の高い防火意識の反映を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013495"},{"id":"00013494","register_sub_id":"101","register_pk":"504859","name":"鈴木屋利兵衛店蔵","kana":"すずきやりへえみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県会津若松市大町一丁目357","lat":37.49859167,"lng":139.92833889,"geo_status":"db","era":"江戸末期／明治43年頃・昭和46年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積125㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"07 － 0240","desc":"旧若松城下の北方郭外にある代々塗物を扱う商家。街道に南面して建つ土蔵造の店蔵は、正面、西面に下屋を廻し、外壁を黒漆喰で出桁造の軒先まで塗込める。内部二階は、明治末期に天井や階段手摺などを洋風に設えた。重厚な店蔵への洋風意匠導入の様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013494"},{"id":"00013496","register_sub_id":"101","register_pk":"504591","name":"関善吉薬局店蔵","kana":"せきぜんきちやっきょくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市川原町161","lat":37.490075,"lng":139.91510556,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積62㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"07 － 0242","desc":"若松城下の西方郭外にある薬局。旧下野街道に北面して建つ土蔵造二階建で、正面に下屋を付す。外壁は黒漆喰で出桁造の軒先まで塗込める。内部一階には調剤室、薬品棚を設けるほか、下屋境に防火対策で漆喰塗の大型引戸を備えるなど、当時の商家の有様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013496"},{"id":"00013028","register_sub_id":"101","register_pk":null,"name":"竹藤主屋","kana":"たけとうおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市中央一丁目69","lat":37.49821667,"lng":139.92990833,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、金属板葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0221","desc":"店舗の北背面に接続する。南から客間、中間、勝手の３室を並べ東に廊下を通す当地方の典型的な平面である。廊下の東は中庭とする。柱と長押に丸太の面皮材、落し掛に竹を用い、床脇物入は敷居下になぐりの蹴込板を入れるなど、数寄屋風の意匠で整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013028"},{"id":"00013030","register_sub_id":"101","register_pk":null,"name":"竹藤座敷蔵","kana":"たけとうざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県会津若松市中央一丁目69","lat":37.49838889,"lng":139.93003333,"geo_status":"db","era":"文政6年（1823）／昭和58年・同60年頃改修","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0223","desc":"敷地の北東に建つ南北棟で、外壁は漆喰塗とする。南妻の戸口は漆喰塗扉の両開きである。内部１階は南から前室、次の間、座敷が並ぶ。２階は家財蔵とする。座敷・次の間境中央に２階梁受け柱が立ち、低い根太天井、奥行の浅い床棚など、古風な座敷蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013030"},{"id":"00013029","register_sub_id":"101","register_pk":null,"name":"竹藤竹蔵","kana":"たけとうたけぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県会津若松市中央一丁目69","lat":37.4984,"lng":139.92997222,"geo_status":"db","era":"天明5年(1785)／文久2年(1862)移築、昭和60年頃改修","year":1785,"year_source":"db","year_min":1785,"year_max":1785,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積77㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0222","desc":"敷地の北西に建つ桁行７間の南北棟で、外壁は蔵前下屋廻りとも塗込とし、南妻上部に井桁の屋号を塗出す。２階窓は鉄扉両開きとする。内部は土間床で商品蔵兼加工場であった。小屋組は１間毎に登り梁を架け、裏板を漆喰揚塗とする。重厚な構造の土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013029"},{"id":"00013027","register_sub_id":"101","register_pk":"368337","name":"竹藤店舗","kana":"たけとうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県会津若松市中央一丁目69","lat":37.49814444,"lng":139.92989167,"geo_status":"db","era":"天保12年（1841）／昭和45年改修","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"木造2階建、金属板葺、建築面積82㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0220","desc":"街路に南面して建つ間口７間の大型店舗で、正面に下屋を付す。内部は東半が土間みせ、西半が床上の帳場で西端を倉庫とし、２階は物置とする。一階下屋正面は一間幅の腰高障子を立て、下屋境は全面摺上戸、二階正面は板壁とする。古い店舗形式を残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013027"},{"id":"00000512","register_sub_id":"101","register_pk":"101502","name":"なかむらや旅館新館","kana":"なかむらやりょかんしんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市飯坂町字湯沢18","lat":37.83226146,"lng":140.45233483,"geo_status":"db","era":"明治29頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造３階建一部平屋建，瓦葺，建築面積78㎡","structure_material":"土蔵造３階建一部平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0010","desc":"現所有者の祖先が営業を始め間もない頃の建築と伝える。本館と同じ土蔵造，木造３階建だが，全階平面が同大で２・３階が高く開放的な点は好対照をなす。本館とともに特異な外観で，人々の目を引く建物である。西側には旧土蔵(本館と同じ頃)が附属する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000512"},{"id":"00000511","register_sub_id":"101","register_pk":"101501","name":"なかむらや旅館本館","kana":"なかむらやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県福島市飯坂町字湯沢18","lat":37.83214902,"lng":140.45232806,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造３階建，瓦葺，建築面積209㎡","structure_material":"土蔵造３階建","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0009","desc":"江戸時代に創業した旅館を現所有者の祖先が買い取り営業を続けたと伝える。創業時の施設と伝える本館は，外壁を土蔵造とする。外観には後世の改造がみられるが，３階を１・２階より小さくして安定感をもたせた重厚な姿は特異で，町中で特に目立つ存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000511"},{"id":"00011854","register_sub_id":"101","register_pk":"211042","name":"ぬる湯温泉旅館・二階堂帳場棟","kana":"ぬるゆおんせんりょかん・にかいどうちょうばとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市桜本字温湯11","lat":37.728935,"lng":140.293293,"geo_status":"db","era":"明治15年頃／大正12年増築、昭和50年・平成5年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積120㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"07-178","desc":"中座敷棟の東に東西棟で接続する。一階は正面側に全長に渡る土間を配し、床上部は居室にあてる。二階は大正一二年の増築で、客室四室を並べ北に廊下、南に広縁を付ける。客室は床の間を備え、東西各二室は部屋境は襖で一室ともなり、欄間を入れ意匠に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011854"},{"id":"00011853","register_sub_id":"101","register_pk":"211041","name":"ぬる湯温泉旅館・二階堂中座敷棟","kana":"ぬるゆおんせんりょかん・にかいどうなかざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市桜本字温湯11","lat":37.729012,"lng":140.293029,"geo_status":"db","era":"明治35年頃／平成5年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積234㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"07-177","desc":"古家棟の東北に東西棟で接続する。一、二階とも二列各五室の客室を並べ、四周に廊下を廻らす。二階は床の間・床脇を備え、長押を廻した上質な造りである。外壁は下見板張で、モールディング付額縁の窓と雲形の持送りなど、和洋折衷の意匠を特徴とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011853"},{"id":"00011852","register_sub_id":"101","register_pk":"211040","name":"ぬる湯温泉旅館・二階堂古家棟","kana":"ぬるゆおんせんりょかん・にかいどうふるやとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市桜本字温湯11","lat":37.728986,"lng":140.292829,"geo_status":"db","era":"明治5年頃／昭和32年増築、平成18年改修","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造3階建、茅葺、建築面積166㎡","structure_material":"木造3階建","registered":"2017.10.27(平成29.10.27)","register_no":"07-176","desc":"福島市西部にある温泉施設。一、二階は廊下を十字に配し、四方に二室ずつ広縁付の客室を設ける。茅葺屋根は、西側を寄棟造とするが、東側を半切妻造のあづま造として当地方特有の外観を見せ、妻面の垂木を扇状に配し凝った意匠とし、景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011852"},{"id":"00014999","register_sub_id":"101","register_pk":"529277","name":"藤田家住宅座敷蔵","kana":"ふじたけじゅうたくざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県白河市二番町46-1","lat":37.12558056,"lng":140.20435278,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"07 - 0285","desc":"店舗兼主屋の北西に建つ座敷蔵。二階建切妻造銅板葺で外壁漆喰塗仕上。軒に鉢巻を廻らす。１階は２室を配し西室南に蔵前が付く。東室は床と床脇を構え東辺に縁を付す。床廻りは黒檀や紫檀など用材吟味し、湾曲状の削出材でつなぐ違棚など良質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014999"},{"id":"00014998","register_sub_id":"101","register_pk":"529276","name":"藤田家住宅店舗兼主屋","kana":"ふじたけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県白河市二番町46-1","lat":37.12540833,"lng":140.20433333,"geo_status":"db","era":"大正前期／昭和中期・平成30年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階一部平屋建、瓦葺一部銅板葺、建築面積169㎡","structure_material":"木造2階一部平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"07 - 0284","desc":"小峰旧城下の角地に建つ味噌醤油醸造業の店舗兼主屋。奥州街道に東面する2階建切妻造平入桟瓦葺の店舗の西に平屋建銅板葺の主屋を接続。店舗一階は広い土間、二階は三室を矩折れに並べ、南西が床構え付き座敷。ガラス戸の開放的な外観が街道景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014998"},{"id":"00015000","register_sub_id":"101","register_pk":"529278","name":"藤田家住宅土蔵","kana":"ふじたけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県白河市二番町46-1","lat":37.12560833,"lng":140.204225,"geo_status":"db","era":"江戸末期／明治41年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"07 - 0286","desc":"座敷蔵の西に位置する家財蔵。切石積基礎に建つ二階建切妻造銅板葺で、外壁は漆喰塗仕上、軒に鉢巻を廻らす。東妻を戸口とし、各階板敷の一室で北西に階段を配す。小屋組は中古で、登梁を水平の繋梁で挟む。西妻に庇付窓を上下に開け、敷地北西景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015000"},{"id":"00011045","register_sub_id":"101","register_pk":"205152","name":"松本屋家財蔵","kana":"まつもとやかざいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市字三丁目4791","lat":37.650269,"lng":139.871942,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"07 - 0164","desc":"敷地南東隅に建つ家財蔵。土蔵造二階建、切妻造桟瓦葺平入で、北面に出入口を開く。内部は一階をコンクリート土間とする。外壁は腰をモルタル塗とする他は漆喰塗で、北面に開く窓三所には片開鉄扉を付すなど、文庫蔵とほぼ共通の意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011045"},{"id":"00011043","register_sub_id":"101","register_pk":"205150","name":"松本屋店舗蔵","kana":"まつもとやてんぽぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県喜多方市字三丁目4791","lat":37.650409,"lng":139.871501,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"07 - 0162","desc":"短冊状敷地の、街路に西面して建つ土蔵造二階建の店蔵。一階は店舗で正面に三尺の下屋を付す。二階は八畳二室の座敷を並べる。外壁は腰人造石吹付仕上、他は漆喰塗とし、二階正面には両開き土戸付の窓を三連並べ、袖壁付小庇を付すなど、重厚な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011043"},{"id":"00011044","register_sub_id":"101","register_pk":"205151","name":"松本屋文庫蔵","kana":"まつもとやぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市字三丁目4791","lat":37.650299,"lng":139.871828,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"07 - 0163","desc":"敷地南側のやや東寄りに建つ文庫蔵。土蔵造二階建、切妻造桟瓦葺妻入で、西面正面に前室を付す。内部は一階二階とも板床で要所に物入を付す。外壁は腰をモルタル塗とする他は漆喰塗で、窓には片開鉄扉が付くが、正面二階窓は両開き土戸として正面性を高める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011044"},{"id":"00000024","register_sub_id":"101","register_pk":"101014","name":"向瀧客室棟（会議室、菊の間他）","kana":"むかいたききゃくしつとう（かいぎしつ、きくのまほか）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県会津若松市東山町大字湯本字川向200","lat":37.4780661,"lng":139.96051797,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造3階建、瓦葺、建築面積360㎡","structure_material":"木造3階建","registered":"1996.12.20(平成8.12.20)","register_no":"07 － 0004","desc":"向瀧客室棟（会議室，菊の間他）は，客室棟（花月の間，梅の間他）とともに東京の棟梁の手になり，地元の職人が多くの造作を手がけたと伝える。数寄屋風の客間や洋風の会議室等の各室の意匠に特徴があり，当時の職人技術の水準を示した建物の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000024"},{"id":"00000023","register_sub_id":"101","register_pk":"101013","name":"向瀧客室棟（花月の間、梅の間他）","kana":"むかいたききゃくしつとう（かげつのま、うめのまほか）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県会津若松市東山町大字湯本字川向200","lat":37.47819094,"lng":139.96064167,"geo_status":"db","era":"明治30代","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積248㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"07 － 0003","desc":"向瀧客室棟（花月の間，梅の間他）は，東京から棟梁を呼んでつくったと伝える建物で，書院造風の意匠をもつ客室には，地元の職人矢仲喜代八が作った建具が残る。当時の東京と会津の職人の技術水準の高さを示した建物の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000023"},{"id":"00000021","register_sub_id":"101","register_pk":"101011","name":"向瀧玄関","kana":"むかいたきげんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市東山町大字湯本字川向200","lat":37.47807412,"lng":139.9610895,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造2階建、瓦葺、建築面積636㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"07 － 0001","desc":"向瀧は江戸時代に「きつね湯」の愛称で親しまれた温泉保養所で，明治６年から旅館となった。玄関は，浴場「きつね湯」がある建物で，道路に面した大きな入母屋造の屋根や２階の大広間に特徴があり，会津東山温泉の歴史的景観を知る上で欠くことができない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000021"},{"id":"00000022","register_sub_id":"101","register_pk":"101012","name":"向瀧はなれ","kana":"むかいたきはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市東山町大字湯本字川向200","lat":37.47789659,"lng":139.96087074,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"07 － 0002","desc":"向瀧はなれは，玄関と同時に建設されたもので，工事は会津若松の棟梁本間辰五郎が手がけた。トコ・違棚を備えた本格的な書院造風の意匠になる続き間座敷をもった建物で，向瀧に残る各建物の規範となった建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000022"},{"id":"00009426","register_sub_id":"101","register_pk":"194219","name":"矢部家住宅一号蔵","kana":"やべけじゅうたくいちごうぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県喜多方市字西町2840","lat":37.65306061,"lng":139.88025495,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"07 － 0134","desc":"座敷蔵の北側に南北棟で建つ。土蔵造二階建、桁行九・六メートル梁間四・七メートル、切妻造桟瓦葺で、東面の戸口に下屋を設ける。外壁は漆喰塗で腰を簓子下見板張とし、南妻面は上下に二箇所ずつ窓を穿つ。座敷蔵や綿蔵とともに商家の屋敷構えを特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009426"},{"id":"00009425","register_sub_id":"101","register_pk":"194218","name":"矢部家住宅座敷蔵","kana":"やべけじゅうたくざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県喜多方市字西町2840-2","lat":37.65290357,"lng":139.88035013,"geo_status":"db","era":"明治30年","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積77㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"07 － 0133","desc":"敷地中央に南北棟で建つ。土蔵造二階建、切妻造桟瓦葺で、南面を下屋とする。外観は漆喰塗で軒の繰蛇腹を深めて重厚な構えとする。内部は下階に座敷二室を並べてトコなどを整え、南端を広縁とし、上階は家財蔵に用いる。主に接客用に使用する、上質な座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009425"},{"id":"00009427","register_sub_id":"101","register_pk":"194220","name":"矢部家住宅綿蔵","kana":"やべけじゅうたくわたぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県喜多方市字西町2840","lat":37.65315579,"lng":139.88025495,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"07 － 0135","desc":"敷地北端に東西棟で建つ。土蔵造二階建、桁行四・三メートル梁間五・二メートル、切妻造桟瓦葺で、東妻面の戸口に下屋を設ける。外壁は漆喰塗で軒蛇腹を廻らし、腰を洗出しとする。通り沿いの北面二階の窓には掛子塗の扉を両開きに吊り、街路景観を引立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009427"},{"id":"00002353","register_sub_id":"101","register_pk":"103343","name":"若喜商店店舗","kana":"わかきしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県喜多方市字3-4786","lat":37.65010757,"lng":139.87142139,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、建築面積98㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"07 － 0058","desc":"味噌醤油醸造業を営む商家の店舗。木造２階建で，地元出身の本間嘉平の設計による。外観は，屋根をコンクリートスラブ陸屋根，外壁をタイル張りとしたモダニズムの意匠でまとめられ，八角の小窓や張出し窓を設け変化を付ける。角地に建ち町並みに異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002353"},{"id":"00002504","register_sub_id":"101","register_pk":"103494","name":"市島銃砲火薬店店舗","kana":"いちじまじゅうほうかやくてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県山形市七日町5-10-53","lat":38.25084783,"lng":140.34172093,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建、亜鉛メッキ銅板葺、建築面積45㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"06 － 0040","desc":"江戸時代より火薬を扱っていた商家で通りに面して建ち，１階が店舗，２階は畳敷の和室になる。外壁はモルタル洗出し仕上げで，目地や柱型及び柱頭飾をつくり，石造風の意匠とする。山形で最初の鉄筋コンクリート造店舗建築で，小規模ながら重厚な造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002504"},{"id":"00012469","register_sub_id":"101","register_pk":"367764","name":"旧小池薬局恵比寿屋本店","kana":"きゅうこいけやっきょくえびすやほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県鶴岡市本町一丁目6-88","lat":38.72718,"lng":139.83075,"geo_status":"geocoded","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積136㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2018.11.02(平成30.11.02)","register_no":"06 － 0191","desc":"市中心部の銀座通りに建つ事務所ビル。長方形平面の鉄筋コンクリート造三階建で、正面一階を石造風、二階以上をタイル張とし、コーニス中央にメダイヨンを飾る。内部は一階を店舗、二階以上を事務室とする。県内における初期鉄筋コンクリート造ビルの好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012469"},{"id":"00010554","register_sub_id":"101","register_pk":"201128","name":"旧丸中横仲商店江戸蔵","kana":"きゅうまるなかよこなかしょうてんえどぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県長井市あら町2461他","lat":38.10101534,"lng":140.03859852,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"06－0158","desc":"敷地北寄り、質蔵の北、粉蔵の東に位置する。桁行九・五メートル梁間四・八メートル、土蔵造二階建、妻入である。小屋はアーチ状の梁で棟木を受け、垂木を架ける。外壁漆喰塗で東面に質蔵同様の縦長窓を設け、掛子塗の土戸を吊るなど、高い左官技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010554"},{"id":"00010553","register_sub_id":"101","register_pk":"201127","name":"旧丸中横仲商店粉蔵","kana":"きゅうまるなかよこなかしょうてんこなぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県長井市あら町2461他","lat":38.10102353,"lng":140.03844335,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、鉄板葺、建築面積55㎡","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"06－0157","desc":"敷地北辺中央の西寄りに、東西棟で江戸蔵と並び建つ。桁行九・五メートル梁間五・七メートル、木造平屋建で、東妻を戸口とし、両妻上部にガラリを付ける。小屋は和小屋で隅部に火打梁を架ける。西面窓の庇を受ける鉄製持送りの幾何模様意匠が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010553"},{"id":"00010550","register_sub_id":"101","register_pk":"201124","name":"旧丸中横仲商店砂糖蔵","kana":"きゅうまるなかよこなかしょうてんさとうぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市あら町2459-2他","lat":38.100836,"lng":140.03852,"geo_status":"db","era":"明治7年","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造、鉄板葺、建築面積47㎡","structure_material":"土蔵造","registered":"2015.08.04(平成27.08.04)","register_no":"06－0154","desc":"最上川の舟運で栄えた長井市街地に建つ土蔵群の一つ。東西に長い敷地の、中央南寄りに位置する。東西棟の土蔵造平屋建で、置屋根形式とする。かつて商品の砂糖を納めた蔵で、桁行約一二メートルを測る大型の蔵。妻側には上下二段に掛子塗の開口部を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010550"},{"id":"00010552","register_sub_id":"101","register_pk":"201126","name":"旧丸中横仲商店質蔵","kana":"きゅうまるなかよこなかしょうてんしちぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市あら町2460他","lat":38.10091775,"lng":140.03858952,"geo_status":"db","era":"明治8年","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"06－0156","desc":"敷地の中央東寄り、土蔵の東隣に東西棟で建つ。土蔵造二階建、平入で、屋根は置屋根形式とする。東面に並べて設けた縦長窓は、上下階で縦に一枚とする両開土戸を開く。開口部周りに黒漆喰を施して対比をつける。質屋を営んでいた際に質物を納めたと伝わる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010552"},{"id":"00010551","register_sub_id":"101","register_pk":"201125","name":"旧丸中横仲商店土蔵","kana":"きゅうまるなかよこなかしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市あら町2460他","lat":38.10093946,"lng":140.03844406,"geo_status":"db","era":"明治7年","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"06－0155","desc":"敷地の中央西寄りに、東西棟で質蔵と並び建つ。土蔵造二階建、平入で、屋根は置屋根形式とする。外壁は漆喰塗を基調とし、北面壁と四周の鉢巻を黒漆喰として対比をつける。南面には上下階に各三箇所の掛子塗の開口部を開き、高い左官技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010551"},{"id":"00010726","register_sub_id":"101","register_pk":"201561","name":"旧山寺ホテル","kana":"きゅうやまでらほてる","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県山形市大字山寺字南院4278","lat":38.310715,"lng":140.434882,"geo_status":"db","era":"明治後期／大正5・昭和11改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、鋼板葺及び鉄板葺、建築面積423㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0161","desc":"立石寺門前の川岸に建ち、中央の本館、西の居住部、東の新館と、二階建三棟を複合する。本館北面に当初の玄関を構え、仙山線開業頃に山寺駅側に唐破風造の玄関を設けた。新館二階は幾何意匠の立面を構成して時代的特徴を示すなど、門前の歴史的風致に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010726"},{"id":"00014557","register_sub_id":"101","register_pk":"515099","name":"古勢起屋本館","kana":"こせきやほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県尾花沢市大字銀山新畑字北412","lat":38.56968611,"lng":140.53155278,"geo_status":"db","era":"大正3年／昭和7年増築、令和4年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積218㎡","structure_material":"木造3階建","registered":"2023.08.07(令和5.08.07)","register_no":"06 - 0209","desc":"銀山温泉街の銀山川北岸に所在する木造三階建温泉旅館。入母屋造銅板葺で各階に庇を巡らす。一階表通り側に浴室を設ける当地旅館の典型。客室は元は床構え付和室を並べる。玄関及び塔屋状の構えと、銀山川を望む二・三階の縁は歴史的温泉街の風情を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014557"},{"id":"00006987","register_sub_id":"101","register_pk":"107969","name":"齋藤家住宅主屋","kana":"さいとうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県長井市館町北639-1","lat":38.10003349,"lng":140.03807197,"geo_status":"db","era":"江戸末期／大正後期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0104","desc":"通りに西面する平入の町家。切妻造茅葺で、背面を葺き降ろし、正面に鉄板葺下屋を設ける。木造つし２階建で、内部は田の字型に４室に間仕切り、通り側にミセ、背面側に座敷や居間を配する。正面の格子や、茅葺屋根、妻などに伝統的な外観をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006987"},{"id":"00006988","register_sub_id":"101","register_pk":"107970","name":"齋藤家住宅土蔵","kana":"さいとうけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市館町北639-1","lat":38.09990546,"lng":140.03806122,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鉄板葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0105","desc":"主屋の南方に位置する。切妻造鉄板葺の置屋根。土蔵造２階建、桁行１２ｍ梁間４．６ｍで、内部は桁行に２室に分ける。外壁は中塗で、正面とその周囲を黒漆喰塗、窓まわりを白漆喰塗とする。小屋は軸太の棟木と垂木から構成され、重厚な空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006988"},{"id":"00003053","register_sub_id":"101","register_pk":"104043","name":"山王くらぶ","kana":"さんのうくらぶ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県酒田市日吉町2-2-25","lat":38.91846966,"lng":139.83221724,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積603㎡","structure_material":"木造2階一部平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"06 － 0052","desc":"木造・２階建の和風建築で，道路側の西面を凝った意匠を軽快にまとめ，東西に細長い雁行状の形態で敷地奥に延び，土蔵造の座敷や数寄屋造の茶室等を接続する。地元で名棟梁として知られた佐藤泰太良の作品で，手の込んだ上質かつ丁寧なつくりになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003053"},{"id":"00013019","register_sub_id":"101","register_pk":"368226","name":"四山楼蔵座敷","kana":"しさんろうくらざしき","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県山形市七日町二丁目163-1他","lat":38.25281111,"lng":140.34166111,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積103㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"06 － 0193","desc":"主屋東側に東西棟で建つ。桁行六間、梁間三間、土蔵造二階建、切妻造で、東、北、西面に下屋を設けて廊下とする。一階に設けた座敷は床に銘木を用い、格天井を張る。庭に面する北面は黒漆喰塗の掛子塗土戸で重厚に見せる。県内に多く見られる蔵座敷の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013019"},{"id":"00013018","register_sub_id":"101","register_pk":"368225","name":"四山楼主屋","kana":"しさんろうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県山形市七日町二丁目163-1他","lat":38.25298333,"lng":140.34145556,"geo_status":"db","era":"明治44年／昭和33年改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、金属板葺、建築面積432㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"06 － 0192","desc":"山形市の繁華街に位置する料亭。敷地中央に西面して建つ、木造二階建、寄棟造で、西面中央に玄関が突出する。一階は北面中央に設けた洋風意匠のホールの両側に客室を配し、二階は大振りの床、舞台を備えた大広間とする。近代山形の繁栄を伝える上質な料亭。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013018"},{"id":"00000020","register_sub_id":"101","register_pk":"101010","name":"相馬屋主屋","kana":"そうまやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県酒田市日吉町1-2-20","lat":38.91941924,"lng":139.8332811,"geo_status":"db","era":"明治28頃","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積483㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"06 － 0003","desc":"相馬屋は江戸時代末期から続いた料亭で，主屋は明治27年の地震時の大火によって焼失した直後に，残った土蔵等を取り込んで建設したものである。店，広間，土蔵等を繋いだ複雑な構成は特異で，トコ棚を備えた各室に用いられている技能の水準も高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000020"},{"id":"00002736","register_sub_id":"101","register_pk":"103726","name":"千歳館客室ちとせ","kana":"ちとせかんきゃくしつちとせ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県山形市七日町四丁目107-2","lat":38.25390848,"lng":140.343079,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"06 － 0044","desc":"敷地の東北隅に建つ。１０畳の前室と床棚を備える１５畳の主室を持ち，庭に向いた南側から東へと広縁を廻らす。西側には廊下を隔てて風呂を設けていた。棚奥と東・南面の広縁両端間に花頭窓を設け，欄間や障子などの細部意匠などにも見るべき点がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002736"},{"id":"00002735","register_sub_id":"101","register_pk":"103725","name":"千歳館主屋","kana":"ちとせかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県山形市七日町四丁目107-2他","lat":38.25393134,"lng":140.34279448,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積380㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"06 － 0043","desc":"木造２階建。１階南北に中廊下を通し，西側を洋風，東側を和風とする。立面もこれに呼応し西面は線材を強調する洋風で中央に玄関ポーチを設ける。東面は庭に向いて純和風の構成である。料亭建築の好例であるとともに，和洋の意匠を併せ持つ特異な建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002735"},{"id":"00006982","register_sub_id":"101","register_pk":"107964","name":"長沼合名会社内蔵","kana":"ながぬまごうめいがいしゃうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.11261,"lng":140.036652,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0099","desc":"店舗兼主屋の土間北面に蔵前を介して接続する。桁行９．２ｍ梁間３．７ｍ規模の土蔵造２階建で、切妻造置屋根鉄板葺とする。南妻に掛子塗両開戸をたて、各階東側面に窓を開け、１、２階通しの掛子塗戸を建てる。家財等を納めた土蔵で、伝統的な屋敷構えを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006982"},{"id":"00006983","register_sub_id":"101","register_pk":"107965","name":"長沼合名会社新蔵","kana":"ながぬまごうめいがいしゃしんぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.11281604,"lng":140.03657196,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積62㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0100","desc":"内蔵の北に南北棟で建つ。桁行１１ｍ梁間５．６ｍの土蔵造２階建、切妻造鉄板葺置屋根とする。外壁は漆喰仕上げで、腰板を張る。東面南寄りに扉口を開き、内部を板敷、壁板張とする。南面には庇を設け、１、２階とも２ヶ所の窓を設け、窓ごとに両開戸をたてる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006983"},{"id":"00006981","register_sub_id":"101","register_pk":"107963","name":"長沼合名会社店舗兼主屋","kana":"ながぬまごうめいがいしゃてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.112385,"lng":140.036728,"geo_status":"db","era":"天保9／昭和33改修","year":1838,"year_source":"db","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0098","desc":"通りに南面する敷地の出入口付近に東を正面に建つ。切妻造とし、もと茅葺の鉄板葺で、越屋根を設ける。桁行２０ｍ梁間１０ｍと規模が大きい。内部は北側に土間、南にトコや神棚を備える座敷や仏間、納戸、茶の間など６室を配し、地域的な特色ある平面を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006981"},{"id":"00006980","register_sub_id":"101","register_pk":"107962","name":"鍋屋本店主屋","kana":"なべやほんてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市十日町1-573","lat":38.11211314,"lng":140.03695376,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、茅葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0097","desc":"店舗の背面に南北棟で建つ。切妻造平入茅葺で、桁行１８ｍ梁間６．７ｍ規模。東を正面とし中央南寄りに入口を設け、トコを構える座敷や居間を店舗側に、背面に台所などを配する。棟を違えて建つ店舗と主屋を一連の建築として構成する町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006980"},{"id":"00006979","register_sub_id":"101","register_pk":"107961","name":"鍋屋本店店舗","kana":"なべやほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市十日町1-573","lat":38.11224238,"lng":140.03695924,"geo_status":"db","era":"明治後期／昭和40頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、茅葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0096","desc":"十日町通りに北面して建つ、木造つし２階建。屋根茅葺とし、東面は切妻で漆喰壁に架構を見せ、西面は寄棟造として葺き降ろす。内部は、もとは床を設けたが、今は土間の一室とする。正面つし２階の格子や、落ち着きある茅葺など、伝統的な街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006979"},{"id":"00012096","register_sub_id":"101","register_pk":"352895","name":"錦屋内蔵","kana":"にしきやうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県東置賜郡川西町大字上小松字北十日町1509","lat":38.007695,"lng":140.046988,"geo_status":"db","era":"明治前期／昭和60年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、金属板葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"06-189","desc":"店舗兼主屋の東に西面して建つ。桁行三間梁間二間、土蔵造二階建、妻入。内部は一、二階とも一室で、二階の床板や壁板にケヤキ板を用い、仕上げがよく残る。外壁は漆喰塗、腰部モルタル仕上げで、目地を切り石積風にみせ、街道沿いの歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012096"},{"id":"00012095","register_sub_id":"101","register_pk":"352894","name":"錦屋店舗兼主屋","kana":"にしきやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県東置賜郡川西町大字上小松字北十日町1509","lat":38.007743,"lng":140.046889,"geo_status":"db","era":"江戸後期／明治前期増築、大正期・昭和50年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"06-188","desc":"店舗はつし二階建平入で、後方に平屋建の主屋を棟を直交して接続する。屋根は切妻造、茅葺。妻面に束や貫を現し、当地域の町家の特徴を示す。正面の下屋庇は失われているが、つし二階の虫籠窓は残る。茅葺の外観で地域の歴史的景観を良好に形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012095"},{"id":"00011240","register_sub_id":"101","register_pk":"209075","name":"ニュー村尾浪漫館離れ","kana":"にゅーむらおろまんかんはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県上山市新湯88-5他","lat":38.157494,"lng":140.273646,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積522㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"06－0176","desc":"敷地の中央にあり、池に面して入母屋造、セメント製桟瓦葺の五棟を配し、それぞれを渡廊下で結ぶ。外壁や庇など庭園からの見栄えに配慮するとともに、内部も座敷飾、欄間、障子戸、襖絵など、手の込んだ豪華な意匠とする。温泉街の繁栄と格式をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011240"},{"id":"00000121","register_sub_id":"101","register_pk":"101111","name":"能登屋旅館本館","kana":"のとやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県尾花沢市大字銀山新畑446","lat":38.56941396,"lng":140.53158751,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造3階建塔屋付，鉄板葺，建築面積333㎡","structure_material":"木造3階建塔屋付","registered":"1997.05.07(平成9.05.07)","register_no":"06 － 0006","desc":"銀山川と背後の急傾斜地に挟まれた狭隘な場所に立置する秘湯の里銀山温泉街にある老舗の温泉旅館で，銀山川に面して木造３階建，塔屋付きの外観を保つ。和風を基調としながら正面にバルコニー付きの玄関を持つなど洒落た外観意匠は広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000121"},{"id":"00000120","register_sub_id":"101","register_pk":"101110","name":"ホテル音羽屋本館","kana":"ほてるおとわやほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県米沢市駅前2-1-40","lat":37.90956007,"lng":140.12663162,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造3階建，瓦葺，建築面積100㎡","structure_material":"木造3階建","registered":"1997.05.07(平成9.05.07)","register_no":"06 － 0005","desc":"木造３階建，入母屋造で，正面に千鳥破風の屋根を設ける。１階にアーチ状の出入り口や窓を設け，２階に出窓，３階には花頭窓風の窓を開き，隅柱等に色付けするなどの正面の賑やかな外観の意匠に特徴があり，米沢の駅前においてひときわ目を引く建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000120"},{"id":"00008808","register_sub_id":"101","register_pk":"162251","name":"山城屋旧館","kana":"やましろやきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県上山市湯町277他","lat":38.16024028,"lng":140.27681126,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積219㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"06 － 0126","desc":"敷地中央に建ち、木造2階建、建築面積219㎡、寄棟造鉄板葺である。上下階とも、蔵王連峰を望む南東面に客室を配置し、周囲に廊下を廻らし、ガラス戸を建てて開放的につくる。2階建具に色ガラスを使うなど、瀟洒な外観の旅館建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008808"},{"id":"00008809","register_sub_id":"101","register_pk":"162252","name":"山城屋荷蔵","kana":"やましろやにぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県上山市湯町277他","lat":38.16025531,"lng":140.27697017,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、鉄板葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"06 － 0127","desc":"旧館東側の通路沿いに建ち、桁行9.4ｍ梁間4.7ｍ、土蔵造2階建、切妻造妻入、置屋根式の瓦葺で、北面出入口に庇を付ける。外壁は漆喰塗で腰を簓子下見板張とし、窓枠などを漆喰塗で丁寧に仕上げる。温泉街の景観に風情を添えている","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008809"},{"id":"00008810","register_sub_id":"101","register_pk":"162253","name":"旅館よね本旅館棟","kana":"りょかんよねもとりょかんとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県上山市沢丁421","lat":38.15516617,"lng":140.27475915,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積178㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"06 － 0128","desc":"敷地中央に建ち、木造2階建、建築面積178㎡、寄棟造鉄板葺である。外壁は柱形をみせたモルタル塗で、1階は西隅を隅切してドリス式風の柱形をつくり、2階は丸窓を配し、また南面には入母屋造の玄関を構えるなど奇想の外観になる旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008810"},{"id":"00001558","register_sub_id":"101","register_pk":"102548","name":"足利銀行黒羽支店（旧黒羽銀行）","kana":"あしかがぎんこうくろばねしてん（きゅうくろばねぎんこう）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県大田原市黒羽向町32","lat":36.85997,"lng":140.116974,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積500㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"09 － 0025","desc":"明治末期頃，黒羽市街の中心部に建てられた。寄棟造・桟瓦葺，２階建で，下屋庇や大谷石積の張出し及び玄関ポーチを設ける。外壁は出桁造の２階軒まで黒漆喰塗とし，２階の鉄扉や１階正面の鉄格子など開口部を厳重に構える。重厚な土蔵造の銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001558"},{"id":"00003789","register_sub_id":"101","register_pk":"104779","name":"天海家住宅店舗","kana":"あまがいけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市嘉右衛門町５他","lat":36.38595881,"lng":139.73324319,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0092","desc":"旧例幣使街道に東面して建つ。桁行３間半梁間２間，切妻造，桟瓦葺，平入のたちの高い木造２階建店舗で，前面に奥行半間の下屋庇を設ける。隣地に接する北側の妻壁は凝灰岩の石積とし，屋根上まで建ち上げて卯建風にしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003789"},{"id":"00001885","register_sub_id":"101","register_pk":"102875","name":"五十畑荒物店店舗","kana":"いかはたあらものてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町11-4","lat":36.37892269,"lng":139.73360565,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0039","desc":"五十畑家は大正１２年創業で，現在の店舗はもと糸綿商佐山家が明治中期に建設したという。切妻造・平入，総２階建の土蔵造で，幅広の正面下屋庇が特色。外壁は漆喰塗であるが，両妻面は簓子下見板張とする。奥の住居とは１階奥中央の出入口で結ばれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001885"},{"id":"00001872","register_sub_id":"101","register_pk":"102862","name":"大島肥料店店舗","kana":"おおしまひりょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市大町字通大町56他","lat":36.391598,"lng":139.734848,"geo_status":"db","era":"明治15","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0026","desc":"大島家は江戸末期から肥料商を営んできた旧家で，店舗の見世蔵は棟札より初代元平が明治１５年に建設したことがわかる。西面して建つ切妻造・平入・２階建，正面下屋庇付の土蔵造。下屋両端の腰部石張や，２階の窓庇の鉄製装飾持送りに特色がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001872"},{"id":"00013683","register_sub_id":"101","register_pk":"505191","name":"太田家住宅稲荷社","kana":"おおたけじゅうたくいなりしゃ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市天明町字現石町2579-3","lat":36.31219722,"lng":139.57455833,"geo_status":"db","era":"明治14年頃","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積0.5㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 262","desc":"敷地北寄りに建つ。正面一間側面二間切妻造桟瓦葺妻入。土台に角柱を立て腰長押、内法長押を廻し組物は舟肘木。壁に菱格子を嵌め、正面扉は格子入の桟唐戸。屋根瓦は規模にあわせた小瓦で家紋入鬼瓦を据える。小規模ながら精巧な屋敷社。奥庭の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013683"},{"id":"00013684","register_sub_id":"101","register_pk":"505193","name":"太田家住宅表門及び石塀","kana":"おおたけじゅうたくおもてもんおよびいしべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2583-2他","lat":36.31203889,"lng":139.57489167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"表門 石造、間口2.4m、石塀 石造、総延長9.8m","structure_material":"表門 石造","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 263","desc":"見世蔵の南に建つ。石塀は延長九・八メートルで、基礎石上に切石積とし高さは三・九メートル。表門は石塀の中央に開けた間口二・四メートルの開口で、御影石の角柱を立て楣石を載せる。門扉は木製。繰形付楣石の両端に獅子彫刻を載せた特徴的な意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013684"},{"id":"00013679","register_sub_id":"101","register_pk":"505183","name":"太田家住宅中蔵","kana":"おおたけじゅうたくなかぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2582-2","lat":36.31205833,"lng":139.57458889,"geo_status":"db","era":"明治8年頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造一部木造2階建、瓦葺、建築面積76㎡","structure_material":"土蔵造一部木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 258","desc":"主屋の西に建つ。土蔵造二階建と棟を直交する木造二階建を接続させ一体とする。土蔵部分は漆喰塗で鉢巻を廻す。戸前は両開き戸で、内部は一階、二階とも板敷で壁に板を張る。木造部分は数寄屋風意匠を採り、使用人部屋や浴室を備える。敷地中央の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013679"},{"id":"00013680","register_sub_id":"101","register_pk":"505185","name":"太田家住宅西蔵","kana":"おおたけじゅうたくにしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2582-2","lat":36.31203889,"lng":139.57442778,"geo_status":"db","era":"明治8年頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 259","desc":"中蔵の西に建つ。土蔵造二階建切妻造桟瓦葺で南北棟。東に下屋を付し土戸引分の戸口を二箇所とる。二階も東に土戸両開きの窓を二箇所開ける。外壁は漆喰塗で鉢巻まで塗込める。内部は一、二階とも二室で二階南室を畳敷とし他は板敷。敷地西辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013680"},{"id":"00013682","register_sub_id":"101","register_pk":"505189","name":"太田家住宅八幡社","kana":"おおたけじゅうたくはちまんしゃ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2583-2","lat":36.31195833,"lng":139.57465,"geo_status":"db","era":"明治14年頃","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.2㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 261","desc":"敷地南に位置。一間社入母屋造銅板葺で、正面に千鳥破風及び唐破風造の向拝を付す。土台に丸柱を立て腰長押、内法長押を廻し組物は出組を詰組とする。擬宝珠高欄付の縁を正側面に廻す。虹梁や拳鼻の彫刻は精緻で要所に金具を打つ等小規模ながら精巧な屋敷社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013682"},{"id":"00013678","register_sub_id":"101","register_pk":"505181","name":"太田家住宅見世蔵及び主屋","kana":"おおたけじゅうたくみせぐらおよびおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2582-2","lat":36.31203611,"lng":139.57483611,"geo_status":"db","era":"明治8年頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積145㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 257","desc":"佐野市の中心部に位置。見世蔵は土蔵造二階建切妻造桟瓦葺で正面に下屋を通す。二階は出桁造で軒裏まで塗込め、棟を高く積む等店蔵の特徴を示す。主屋は棟を直交させて西に接続する。二階建切妻造桟瓦葺で南に下屋を付す。重厚な見世蔵が通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013678"},{"id":"00013681","register_sub_id":"101","register_pk":"505187","name":"太田家住宅南蔵","kana":"おおたけじゅうたくみなみぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県佐野市大和町字江戸町2583-1","lat":36.31193889,"lng":139.57439167,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"09 － 260","desc":"敷地南西隅に建つ。土蔵造二階建、切妻造桟瓦葺で東に下屋を付し、板戸片引を建てる。二階の東と南に窓を開ける。鉢巻を二重にするなど重厚な外観を持つ。内部は一、二階とも一室で板敷に漆喰壁。小屋組は登梁と二重梁を交互に架ける。西辺の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013681"},{"id":"00008639","register_sub_id":"101","register_pk":"149360","name":"大谷好美館","kana":"おおやこうびかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県鹿沼市今宮町字西中町1609-4","lat":36.5649263,"lng":139.74538535,"geo_status":"db","era":"明治後期／昭和前期・平成18年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、鉄板葺、建築面積61㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0193","desc":"神社への参道に西面して建つ。木造2階建、下見板張とする写真館。入母屋造妻入鉄板葺で、正面にポーチを付け、妻壁には植物模様や「美」の文字を飾る。1階を和室や待合室、2階を広い撮影室とする。屋根に採光のための天窓を設け、写真館らしい外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008639"},{"id":"00001887","register_sub_id":"101","register_pk":"102877","name":"雅秀店舗","kana":"がしゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町3-2","lat":36.37890142,"lng":139.731598,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0041","desc":"旧例幣使街道の西木戸があった幸来橋の東にある。南面して建ち，切妻造・桟瓦葺，総２階建の土蔵造。外壁は黒漆喰塗で，両妻面とも簓子下見板張，２階窓には観音扉を備える。２階は中央で左右に間仕切り，座敷とする。高い棟積，大柄な影盛など豪壮な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001887"},{"id":"00010915","register_sub_id":"101","register_pk":"208886","name":"加登屋旅館別館","kana":"かどやりょかんべっかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県那須塩原市板室字塩沢854他","lat":37.067433,"lng":139.923706,"geo_status":"db","era":"昭和12頃／昭和48改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積33㎡","structure_material":"木造3階建","registered":"2016.02.25(平成28.02.25)","register_no":"09-0222","desc":"本館と悠仙閣の間に挟まれて建つ。木造三階建で、各階とも客室となる。内部は簡素ながらも座敷飾を備えた和室を並べる一方、壁面をドイツ壁風の仕上げとして、側面には上下窓を持つなど外観には洋風意匠を織り交ぜ、当時の流行を取り入れた旅館建築となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010915"},{"id":"00010914","register_sub_id":"101","register_pk":"208885","name":"加登屋旅館本館","kana":"かどやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県那須塩原市板室字塩沢854他","lat":37.067517,"lng":139.923769,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積114㎡","structure_material":"木造3階建","registered":"2016.02.25(平成28.02.25)","register_no":"09-0221","desc":"加登屋旅館は、板室温泉の老舗旅館のひとつ。本館は木造三階建で、一階を帳場などの事務空間とし、二階と三階は西に廊下を通し、六畳間の客室を並べ、端の部屋には床構えを設ける。東正面には木製手摺を張り出して、湯治場としての温泉街の情緒を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010914"},{"id":"00010916","register_sub_id":"101","register_pk":"208887","name":"加登屋旅館悠仙閣","kana":"かどやりょかんゆうせんかく","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"栃木県","address":"栃木県那須塩原市板室字塩沢854他","lat":37.067367,"lng":139.923697,"geo_status":"db","era":"昭和27頃","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積73㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"09-0223","desc":"別館の南に接続して建つ。木造二階建で、一階を玄関と客室及び浴室、二階を客室とする。内外とも、随所に奇木を用いたり、円窓や変形六角形の下地窓を穿ったりするなど、数寄屋風の趣向を凝らした造形を見せ、温泉街の通りに対して洒脱な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010916"},{"id":"00007178","register_sub_id":"101","register_pk":"108160","name":"旧足利銀行栃木支店","kana":"きゅうあしかがぎんこうとちぎしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県栃木市万町15-25","lat":36.38292693,"lng":139.73443217,"geo_status":"db","era":"昭和9／平成17移築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"09 － 0175","desc":"旧例幣使街道に東面して建つ。建築面積１１１㎡。切妻造鉄板葺の周囲にパラペットを立ち上げ、外観を陸屋根に見せる木造平屋建。正面中央に出入口を設け、その両脇にトスカナ式オーダー風の角柱を建てる。古典様式になる昭和前期の銀行建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007178"},{"id":"00016647","register_sub_id":"101","register_pk":"579131","name":"旧下野中央銀行喜連川支店店舗","kana":"きゅうしもつけちゅうおうぎんこうきつれがわしてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県さくら市喜連川4341-1","lat":36.718092,"lng":140.026202,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積94㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"09 - 0278","desc":"奥州街道に西面して建つ旧銀行店舗。設計は大森茂。鉄筋コンクリート造平屋建でパラペットを付す。外観は八角形柱型を並べ、半円アーチ形や四葉形の窓を飾り、人造石とタイル貼の独特な外観を持つ。内部はカウンターや金庫室が残る。地域の近代化を象徴する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016647"},{"id":"00011864","register_sub_id":"101","register_pk":"354914","name":"旧土佐屋薬局座敷蔵・中蔵・奥蔵","kana":"きゅうとさややっきょくざしきぐら・なかぐら・おくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市本町2942","lat":36.313884,"lng":139.574063,"geo_status":"db","era":"明治10年頃／明治23年増築、平成15年改修","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積106㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"09-236","desc":"主屋の北側に建つ。敷地奥に奥蔵が建ち、一段棟を低くし中蔵が続き、座敷蔵は棟を直交し、主屋側に観音扉を開く。奥蔵は桁行六間と大規模で、一階に鉄板張で和紙の目張をした薬庫を設け、座敷蔵は拭漆仕上げの上質な造り。商家を構成する上で欠かせない土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011864"},{"id":"00011863","register_sub_id":"101","register_pk":"354913","name":"旧土佐屋薬局店舗兼主屋","kana":"きゅうとさややっきょくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市本町2942","lat":36.313696,"lng":139.574075,"geo_status":"db","era":"明治28年頃／昭和中期改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積136㎡、門及び塀付","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"09-235","desc":"旧日光例幣使街道沿いに南面する。正面を黒漆喰塗とし、蛇腹の軒や棟の影盛など重厚な外観を見せるが、脇の門塀は石積アーチ状の洋風意匠である。表庭に面した座敷は数寄屋風、二階表側の座敷は曲率の強い室床など趣向を凝らした意匠に見応えがある商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011863"},{"id":"00013225","register_sub_id":"101","register_pk":"366214","name":"旧南間ホテル別館（ましこ悠和館）","kana":"きゅうなんまほてるべっかんましこゆうわかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県芳賀郡益子町大字益子字向原4264-8","lat":36.46365556,"lng":140.11539444,"geo_status":"db","era":"昭和4年頃／昭和48年移築、平成31年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、金属板葺、建築面積298㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"09 － 0252","desc":"日光市湯元から町東部の現在地に移築した建物。入母屋造の主体部両端から入母屋造の翼部を突出したコの字形平面で、真壁造の外壁に、刎高欄や腕木庇などの和風意匠を巧みに取り入れた外観とする。客室の床に銘木を使用するなど、近代の和風ホテル建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013225"},{"id":"00005242","register_sub_id":"101","register_pk":"106230","name":"旧日光市庁舎本館","kana":"きゅうにっこうしちょうしゃほんかん","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県日光市中鉢石町999","lat":36.750759,"lng":139.607422,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造3階建、鉄板葺、建築面積2470㎡","structure_material":"木造3階建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0137","desc":"日光街道沿いに「大名ホテル」として建設される。間口４４ｍ，奥行１７ｍの木造３階建の主体部は正面モルタル塗，背面下見板張とし，大ぶりな破風を載せた左右翼部を正面に張出し中央を望楼風とした城郭風の造り。南に入母屋造，総３階建の付属棟を接続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005242"},{"id":"00001879","register_sub_id":"101","register_pk":"102869","name":"好古壱番館（旧安達呉服店店舗）","kana":"こうこいちばんかん（きゅうあだちごふくてんてんぽ）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市万町4-2","lat":36.38052155,"lng":139.73413965,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積56㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0033","desc":"蔵造の町並に点在する洋風建築のひとつ。もと呉服商の店舗で大正１２年の建設。木造２階建で，１階正面をポーチ状に張出し，銅板葺の寄棟マンサード屋根を架け，屋根窓を設ける。柱や扁平アーチ部を石張で石造風に仕上げるなど，大正期の意匠をよく表現する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001879"},{"id":"00003799","register_sub_id":"101","register_pk":"104789","name":"櫻井肥料店店舗","kana":"さくらいひりょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市万町15-17","lat":36.384018,"lng":139.734772,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積80㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0102","desc":"旧例幣使街道に東面して建つ。間口桁行７間半梁間３間，切妻造，桟瓦葺，平入の２階建大型町家で，前面に半間の下屋を設ける。南寄りに１間幅の通路をとり，その南側を板敷物置，北側をミセとする。南面のみ漆喰塗とし，１階に煉瓦造袖壁を建てるのも特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003799"},{"id":"00003802","register_sub_id":"101","register_pk":"104792","name":"櫻井肥料店煉瓦蔵","kana":"さくらいひりょうてんれんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市万町15-17","lat":36.38400147,"lng":139.73448097,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造平屋建、瓦葺、建築面積12㎡","structure_material":"煉瓦造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0105","desc":"主屋の西南方に位置し，文庫蔵と向き合って建つ。桁行２間半梁間１間規模，寄棟造，桟瓦葺，平入の平屋建煉瓦造物置で，壁厚は煉瓦１枚積とする。小規模ながら，フランス積で，壁上部に煉瓦を抜いて千鳥模様を造りだすなど煉瓦積技法にも見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003802"},{"id":"00001881","register_sub_id":"101","register_pk":"102871","name":"佐藤家住宅店舗","kana":"さとうけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町14-2","lat":36.38001452,"lng":139.73392565,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0035","desc":"旧例幣使街道沿いに西面して建つ土蔵造の店舗。切妻造・平入，総２階建，正面下屋庇付で，軒は出桁造。外壁は黒漆喰塗になり，正面２階窓はやや縦長であるが，南妻面にも窓を設ける。全体に階高も高く，開口部も多くなっており，明治中期と推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001881"},{"id":"00014735","register_sub_id":"101","register_pk":"518993","name":"三斗小屋温泉大黒屋旅館本館","kana":"さんどごやおんせんだいこくやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県那須塩原市板室字三斗小屋湯所919他","lat":37.13833889,"lng":139.94569167,"geo_status":"db","era":"明治2年頃／明治5年増築、大正前期・昭和前期・同中期・同54年改修","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積223㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"09 - 0273","desc":"那須岳中腹に位置する三斗小屋温泉の旅館。2階建の南北棟で北を寄棟造、南を切妻造とし、屋根は鉄板葺とする。北に玄関と広間、南に風呂を配し、これらを結ぶ中廊下を通して、周囲に客室を配す。建ちが低く古式で、近世由来の温泉宿の様相を留める旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014735"},{"id":"00003803","register_sub_id":"101","register_pk":"104793","name":"下都賀酒造協同組合事務所","kana":"しもつがしゅぞうきょうどうくみあいじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県栃木市万町25-16","lat":36.38101803,"lng":139.73794355,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積104㎡","structure_material":"木骨石造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0106","desc":"栃木市街の東部に位置する。桁行６間梁間５間，寄棟造，桟瓦葺の２階建事務所建築で，正面中央に洗出し仕上げの玄関ポーチを突き出す。２階中央に破風型の庇を付けるほかは縦長窓を整然と並べ，軒蛇腹や胴蛇腹を石で造り出す。木骨石造事務所建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003803"},{"id":"00001875","register_sub_id":"101","register_pk":"102865","name":"下野新聞社栃木支局","kana":"しもつけしんぶんしゃとちぎしきょく","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県栃木市万町7-5","lat":36.382347,"lng":139.73468,"geo_status":"db","era":"文久1","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0029","desc":"もとは「毛惣」で知られた肥料商の２代目毛塚惣八が建設した見世蔵で，墨書から大工棟梁は地元の鈴木七右衛門とわかる。切妻造・平入，総２階建，正面は下屋庇付で軒を出桁造，黒漆喰塗とする重厚な土蔵造で，正面２階の窓は縦長の古い形式をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001875"},{"id":"00001882","register_sub_id":"101","register_pk":"102872","name":"関根家住宅店舗","kana":"せきねけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市倭町11-4","lat":36.37900204,"lng":139.73362872,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積46㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0036","desc":"洋風店舗建築のひとつで，明治から昭和初期まで煙草卸売商を営んでいた。大正１１年の建設で，タイル張２階建，桟瓦葺。正面と両側面のパラペットを高く上げ，正面壁面は柱，縦長窓，装飾などが左右対称に整然と配され，大正期のセセッション風意匠が目立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001882"},{"id":"00001878","register_sub_id":"101","register_pk":"102868","name":"大二商店店舗","kana":"だいにしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市万町4-3","lat":36.3806508,"lng":139.73416251,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0032","desc":"旧例幣使街道沿いに西面し，山本有三ふるさと記念館の少し南に建つ。もと糸綿商を営んだ屋号釜藤の見世蔵。規模は桁行３間半・梁間３間で，切妻造・平入，総２階建，正面下屋庇付の土蔵造。高さを低く押さえ，２階窓の形式も古風で，明治初期と推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001878"},{"id":"00002754","register_sub_id":"101","register_pk":"103744","name":"高木会館","kana":"たかぎかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県那須塩原市本町5-19","lat":36.97023,"lng":140.058197,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造2階建、瓦葺、建築面積116㎡","structure_material":"石造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"09 － 0053","desc":"黒磯初の銀行の本店建築で，現在はレストランなどに活用されている。２階建で，切妻造・桟瓦葺，外壁は正面が芦野石，他が大谷石である。重厚な石積を基調としながら，軽快な櫛形風ペディメントやアーチ型飾りを備えるなど，町並のシンボル的存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002754"},{"id":"00003794","register_sub_id":"101","register_pk":"104784","name":"舘野家住宅店舗","kana":"たてのけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県栃木市泉町2-32","lat":36.38451726,"lng":139.73418211,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積83㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0097","desc":"旧例幣使街道に東面して建つ。桁行７間梁間４間半規模，寄棟造，鉄板葺の木造２階建店舗で，外観はヴェランダや連アーチの窓を配するなど洋風に見せる。店舗内部は土間と１２畳の帳場から成る和風店舗のつくりで，２階南側の１室のみを洋室に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003794"},{"id":"00003798","register_sub_id":"101","register_pk":"104788","name":"舘野家住宅鼻緒蔵","kana":"たてのけじゅうたくはなおぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市泉町2-32","lat":36.38445317,"lng":139.73385122,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0101","desc":"主屋の西南方に位置し，南北棟で建つ。切妻造，桟瓦葺，平入の２階建土蔵で，桁行５間半梁間３間と大きく，外周廻りを簓子下見板張とする。墨書から，施主「舘野平兵衛」，大工「早川辰造」が判明する。舘野家の最盛期の生業を示す遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003798"},{"id":"00001894","register_sub_id":"101","register_pk":"102884","name":"塚田家住宅銘木蔵","kana":"つかだけじゅうたくめいぼくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.37807674,"lng":139.73073521,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積152㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0048","desc":"屋敷地の南辺に建つ切妻造・桟瓦葺，東西棟の巨大な倉庫建築。北面の庭側に吹放し下屋庇を備え，西面は落棟・入母屋屋根とする。外壁は東・南・西の３面が白漆喰塗で，北面の庇上は簓子下見板張になる。材木問屋としての建築構成上，根幹をなす存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001894"},{"id":"00001896","register_sub_id":"101","register_pk":"102886","name":"塚田歴史伝説館事務室、売店及び休憩所","kana":"つかだれきしでんせつかんじむしつ、ばいてんおよびきゅうけいじょ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.378429,"lng":139.73122559,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積180㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0050","desc":"屋敷地東辺に建ち，墨書より大正５年の建設とわかる。いずれも２階建で，桟瓦葺屋根の東西に長大な建築。３つの建物に巧みに連結した構成で，破風や窓が効果的に配され，変化に富む外観となっている。現在は，一般公開のための管理施設として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001896"},{"id":"00001895","register_sub_id":"101","register_pk":"102885","name":"塚田歴史伝説館展示館","kana":"つかだれきしでんせつかんてんじかん","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.37854004,"lng":139.73107907,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0049","desc":"塚田家は昭和５４年より土蔵群を中心として邸内を一般公開している。展示館は邸内で最も古い土蔵。主屋の南辺に建ち，南北棟で切妻造・桟瓦葺，東面に吹放し下屋庇を付け，巴波川側の西面は２階に５つの鉄格子入窓を軽快に配し，整った意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001895"},{"id":"00001897","register_sub_id":"101","register_pk":"102887","name":"塚田歴史伝説館人形山車・銘木展示館（旧荷蔵）","kana":"つかだれきしでんせつかんにんぎょうだし・めいぼくてんじかん（きゅうにぐら）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.37833649,"lng":139.73096897,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積322㎡","structure_material":"土蔵造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0051","desc":"屋敷地のほぼ中央に建つＬ字型平面の２階建倉庫。桟瓦葺屋根で覆い，基本的には真壁造で，外壁の一部を簓子下見板張とする。小屋組はキングポストトラスで，明治４２年の上棟である。中央に通路をもち，もとは荷蔵であったが，現在は展示施設として活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001897"},{"id":"00001889","register_sub_id":"101","register_pk":"102879","name":"毛塚紙店店舗","kana":"てづかかみてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町10-3","lat":36.37821831,"lng":139.73352958,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0043","desc":"江戸中期より紙商を営んだ老舗で，明治期には県内有数の紙問屋となった。店舗は西面して建ち，小屋梁墨書から明治４１年の上棟と判明。切妻造・平入の２階建，正面下屋庇付の形式で，黒漆喰塗，出桁造で３重蛇腹の軒，高い箱棟など，重厚な意匠の見世蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001889"},{"id":"00013041","register_sub_id":"101","register_pk":"368230","name":"寺岡糸店石蔵","kana":"てらおかいとてんいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県佐野市天明町2702","lat":36.312975,"lng":139.57436667,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積73㎡","structure_material":"石造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0248","desc":"敷地北辺の中央に南面して建つ。石造平屋建、切妻造桟瓦葺で、正面に庇を付す。外部は大谷石積を現して鉢巻二段を廻し、正面入口は鉄製戸を引分ける。内部は小幅板を等間隔に張り、小屋はトラス組とする。糸問屋の歴史を伝える原糸貯蔵用の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013041"},{"id":"00013042","register_sub_id":"101","register_pk":"368348","name":"寺岡糸店大門","kana":"てらおかいとてんおおもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県佐野市天明町2702","lat":36.31257222,"lng":139.57451667,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、間口3.1m、左右袖塀付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0249","desc":"店舗東側に建つ資材搬入に用いた門。木製、高さ3・6メートル、方形の木製門柱一対を間口3・1メートルで立て、木製の両開戸を備える。門柱両脇に延びる袖塀は、基礎を花崗岩の延石、屋根を金属板葺とした板塀。店舗と調和した街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013042"},{"id":"00013039","register_sub_id":"101","register_pk":"368229","name":"寺岡糸店主屋","kana":"てらおかいとてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県佐野市天明町2702","lat":36.31273889,"lng":139.57428333,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0246","desc":"店舗後部の西側に接続して建つ、木造２階建、寄棟造桟瓦葺の主屋。南面東寄りに入母屋造の玄関を構え、上下階とも四周に下屋を廻す。外壁は真壁漆喰塗で腰を下見板張とする。内部は一階を書院風、二階を数寄屋風に仕上げる。瀟洒な屋敷景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013039"},{"id":"00013038","register_sub_id":"101","register_pk":"368346","name":"寺岡糸店店舗","kana":"てらおかいとてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県佐野市天明町2702","lat":36.31264722,"lng":139.57442222,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積206㎡","structure_material":"木造2階一部平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0245","desc":"市街地中心部にある商家。店舗は街道に南面して建つ寄棟造桟瓦葺で、正面に下屋を付し、背面にコの字形の居住部が接続する。外壁は漆喰塗で腰を下見板張とする。内部前寄りの店舗部分は２層吹抜とした開放的なつくり。重厚な街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013038"},{"id":"00013040","register_sub_id":"101","register_pk":"368347","name":"寺岡糸店文庫蔵","kana":"てらおかいとてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市天明町2702","lat":36.31281667,"lng":139.57424167,"geo_status":"db","era":"明治7年／昭和8年頃改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0247","desc":"主屋北西に接続し、南北棟で建つ。土蔵造二階建、切妻造桟瓦葺で、南面に蔵前を付す。外壁は人造石洗出しで石積風に仕上、鉢巻二段を廻し、正面入口は漆喰塗戸を引分ける。内部は漆喰塗で、登梁形式の小屋組とする。敷地西辺の屋敷構えの一角を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013040"},{"id":"00001886","register_sub_id":"101","register_pk":"102876","name":"中田家住宅店舗","kana":"なかたけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県栃木市倭町316","lat":36.37879507,"lng":139.73323793,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積89㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0040","desc":"旧例幣使街道沿いに東面して建つ。切妻造・平入，総２階建，正面下屋庇付の土蔵造店舗で，江戸末期と推定。桁行５間と規模が大きく，梁間も３間あるため棟が高くなり，黒漆喰塗の外壁と相俟って重厚感がある。鉄格子入の２階窓は小さく，古めかしい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001886"},{"id":"00004921","register_sub_id":"101","register_pk":"105911","name":"日光金谷ホテル観覧亭（竜宮）","kana":"にっこうかなやほてるかんらんてい（りゅうぐう）","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県日光市上鉢石町1300","lat":36.75156572,"lng":139.6047834,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、銅板葺、建築面積172㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0129","desc":"本館南方の高台に位置し，冬場にはスケートリンクになる池に面して南北棟で建つ。桁行５間，梁間２間半の規模，入母屋造，銅板葺の木造２階建で，入側柱には奇木を用いた凝った造りとし，周囲に下屋を廻し，北方の展望閣に向けて渡り廊下を下屋から延ばす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004921"},{"id":"00004920","register_sub_id":"101","register_pk":"105910","name":"日光金谷ホテル新館","kana":"にっこうかなやほてるしんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市上鉢石町1300","lat":36.75208735,"lng":139.60339868,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積503㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0128","desc":"本館の北西方に建つ。桁行１８間半，梁間８間規模，入母屋造，鉄板葺の木造２階建で，外壁は下見板張とし，胴蛇腹位置に瓔珞飾りと擬宝珠高欄を廻す。１階に無柱のバンケットホールを設け，小屋トラスから鉄棒で２階床を吊る特異な構造を有するのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004920"},{"id":"00004922","register_sub_id":"101","register_pk":"105912","name":"日光金谷ホテル展望閣","kana":"にっこうかなやほてるてんぼうかく","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県日光市上鉢石町1300","lat":36.75170305,"lng":139.60460003,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積62㎡、渡廊下付","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0130","desc":"観覧亭（竜宮）の北方，高台崖際に建ち，観覧亭とは渡り廊下で繋がれる。桁行４間半，梁間２間の規模，東西棟，入母屋造，銅板葺の木造平屋建で，内部は化粧屋根裏とし，小壁下に内法長押を廻す。展望に配慮した吹き放ちの開放的なつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004922"},{"id":"00004923","register_sub_id":"101","register_pk":"105913","name":"日光金谷ホテル別館","kana":"にっこうかなやほてるべっかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県日光市上鉢石町1300","lat":36.75251726,"lng":139.60403241,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造一部鉄筋コンクリート造3階建、銅板葺、建築面積423㎡","structure_material":"木造一部鉄筋コンクリート造3階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0131","desc":"本館の北東に建つ。桁行１６間，梁行８間規模，木造３階建の客室棟で，南面に唐破風造の車寄を付け，外観は真壁造に見せ，屋根は八棟造風に賑やかにつくる。久米権九郎設計になる和風建築で，構造は組立柱等を用いた久米独自の耐震木構法による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004923"},{"id":"00004919","register_sub_id":"101","register_pk":"105909","name":"日光金谷ホテル本館","kana":"にっこうかなやほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市上鉢石町1300","lat":36.7521656,"lng":139.60397516,"geo_status":"db","era":"明治26／昭和11増改造","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積1395㎡","structure_material":"木造3階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0127","desc":"明治２６年開業時の木造２階建を昭和１１年に地面を掘り下げて３階建とする。東を正面としたＬ字形平面で，１階にフロントロビーとバー，２階に食堂と７客室，３階に１７客室等を配し，内部に和風意匠を採り入れる。近代日光のシンボル的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004919"},{"id":"00005243","register_sub_id":"101","register_pk":"106231","name":"日光物産商会店舗","kana":"にっこうぶっさんしょうかいてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市上鉢石町1026他","lat":36.75307106,"lng":139.605225,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、鉄板葺、建築面積233㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0138","desc":"日光二社一寺の門前に位置し，桁行２２ｍ，梁間１１ｍ規模の商業建築。木造２階建，入母屋造とし，２階に三斗組と蟇股を配した高欄を廻らし，妻面に琴柱花頭窓を穿ち，妻飾には二重虹梁大瓶束笈形の架構を見せるなど，寺院建築の細部を随所に取り入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005243"},{"id":"00003792","register_sub_id":"101","register_pk":"104782","name":"野口栄三商店店舗及び主屋","kana":"のぐちえいぞうしょうてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市泉町2-27","lat":36.38527083,"lng":139.73405838,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、鉄板及び瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0095","desc":"旧例幣使街道に東面して建つ。店舗は，桁行３間梁間２間半，南北棟，切妻造，鉄板葺の平入２階建で，前面に半間の下屋庇を差し出す。主屋は，桁行４間梁間２間，東西棟，切妻造，桟瓦葺の２階建で，南面に１間幅の下屋庇を設け店舗土間からの通り庭とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003792"},{"id":"00003793","register_sub_id":"101","register_pk":"104783","name":"野口栄三商店土蔵","kana":"のぐちえいぞうしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市泉町2-27","lat":36.38525993,"lng":139.73392255,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0096","desc":"主屋の西方に中庭を介して東西棟で建つ。桁行３間梁間３間，切妻造，桟瓦葺の妻入２階建土蔵で，東妻面に庇を差し出して蔵前をとる。墨書から大工「早川助造」が判明。もと美術小間物商内田家の荷蔵で，店舗及び主屋とともに当地町家の構えをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003793"},{"id":"00004914","register_sub_id":"101","register_pk":"105904","name":"原田家住宅店舗","kana":"はらだけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市通6-3225-1","lat":36.33807401,"lng":139.441406,"geo_status":"db","era":"大正9頃／昭和53曳家","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積45㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0122","desc":"旧国道５０号沿いに北面して建つ。桁行３間半，梁間２間半の規模，切妻造桟瓦葺，平入の木造２階建で，正面に半間の下屋をかけ，外壁は下見板張とする。明治から昭和初期に多く建築された出桁造の店舗の形式を良く残し，往時の通りの様子を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004914"},{"id":"00008641","register_sub_id":"101","register_pk":"149362","name":"福田家住宅奥座敷","kana":"ふくだけじゅうたくおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県鹿沼市上材木町1827他","lat":36.56935215,"lng":139.747925,"geo_status":"db","era":"明治後期／昭和20年頃移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0195","desc":"主屋の東に渡り廊下を介して続く。桁行7.4ｍ梁間5.7ｍ、木造2階建、東西棟の切妻造桟瓦葺。1、2階とも座敷2室を東西に並べ、南・西面に縁をまわし、主座敷には上質な座敷飾りを備える。開放的で、品格のある近代の接客空間をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008641"},{"id":"00008640","register_sub_id":"101","register_pk":"149361","name":"福田家住宅店棚及び主屋","kana":"ふくだけじゅうたくみせだなおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県鹿沼市上材木町1827他","lat":36.56926887,"lng":139.74777033,"geo_status":"db","era":"江戸末期／明治中期・大正前期増築・昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、瓦葺、建築面積221㎡","structure_material":"木造2階一部平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0194","desc":"旧鹿沼宿に位置し、旧例幣使街道に西面する。間口9.6ｍの木造二階建、切妻造の店棚と、東背面に続く木造平屋建、寄棟造の主屋からなる。桟瓦葺。正面に土間の深い銅板葺下屋を付け、その上部に格子窓を広く構え、落ち着きのある商家の佇まいをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008640"},{"id":"00001888","register_sub_id":"101","register_pk":"102878","name":"丸三家具店店舗","kana":"まるさんかぐてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町10-3","lat":36.37827466,"lng":139.73349938,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0042","desc":"切妻造・平入，２階建，正面下屋庇付，黒漆喰塗，出桁造・３重蛇腹の軒など，北隣に建つ明治４１年上棟の毛塚紙店店舗とほどんど同じ形式であるが，桁行３間と規模が半間小さい。横長の２階窓や高い箱棟，大柄な影盛など，明治後期の特色をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001888"},{"id":"00004916","register_sub_id":"101","register_pk":"105906","name":"柳田家住宅事務所","kana":"やなぎだけじゅうたくじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市通6-3226-1他","lat":36.33809686,"lng":139.44122783,"geo_status":"db","era":"明治24／昭和53曳家","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積181㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0124","desc":"当初は店舗兼住宅で，正面に下屋が付く切妻造桟瓦葺，平入木造２階建の店舗である。背面に桟瓦葺の木造平屋建の旧住宅が続く。外壁は漆喰塗と下見板張を基本とし，正面窓下を御影石等で飾る。隣地の原田家住宅店舗と共に織物産業隆盛期の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004916"},{"id":"00004917","register_sub_id":"101","register_pk":"105907","name":"柳田家住宅倉庫","kana":"やなぎだけじゅうたくそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市通6-3226-1他","lat":36.33818576,"lng":139.44108434,"geo_status":"db","era":"大正初期／昭和53曳家","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0125","desc":"敷地北西隅に建つ切妻造桟瓦葺の土蔵造２階建，腰部分を石積とする。東面平壁に入口を設け，両妻壁各階中央に窓を設ける。外壁は漆喰塗とし，北面及び西面を下見板張とする。当初は西蔵と呼ばれ，事務所，表門と並んで旧国道５０号線沿いの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004917"},{"id":"00001876","register_sub_id":"101","register_pk":"102866","name":"山本有三ふるさと記念館南棟","kana":"やまもとゆうぞうふるさときねんかんなんとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市万町5-3","lat":36.38103735,"lng":139.7343091,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0030","desc":"旧栃木宿のほぼ中央，旧例幣使街道沿いに西面して建つ。北棟と屋根を共有するが，北棟より先の建設である。切妻造・平入，総２階建，正面下屋庇付，黒漆喰塗の重厚な土蔵造。正面２階の窓はやや縦長で観音開扉を有し，背面には平屋建の居住棟が連続している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001876"},{"id":"00001877","register_sub_id":"101","register_pk":"102867","name":"山本有三ふるさと記念館北棟","kana":"やまもとゆうぞうふるさときねんかんほくとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市万町5-3","lat":36.38107455,"lng":139.734306,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0031","desc":"北棟は南面の柱が南棟壁面に組み込まれており，南棟より少し遅れての増築と推定。規模や形式は南棟とほぼ同じであるが，軒廻りや両側戸袋付の正面２階の横長窓など，意匠に変化をもたせ，巧みに処理している。とくに１階内部は土間と帳場の構えがよく残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001877"},{"id":"00000750","register_sub_id":"101","register_pk":"101740","name":"横山郷土館麻蔵","kana":"よこやまきょうどかんあさぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町2-16","lat":36.38141784,"lng":139.73245178,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造２階建，瓦葺，建築面積66㎡","structure_material":"石造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"09 － 0008","desc":"主屋の北側に建つ。麻は地元の特産品で，舟運による関連製品の売買で栄えた付近一帯には多数の蔵が残る。なかでもこの蔵は，比較的に大規模な石造の蔵としてひときわ目立つ存在。窓の意匠や小屋のトラス等には，洋風建築からの影響がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000750"},{"id":"00000749","register_sub_id":"101","register_pk":"101739","name":"横山郷土館店舗及び住居","kana":"よこやまきょうどかんてんぽおよびじゅうきょ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町2-16","lat":36.38127655,"lng":139.73240092,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造２階建，瓦葺，建築面積256㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"09 － 0007","desc":"横山家は巴波川の舟運を利用して苧麻問屋を営み栄えた家で，川沿いの道路に面して広い屋敷地を構える。東面して接道する主屋は，前面を店舗，後方を住宅とし，正面をつし２階の町家風にした特徴あるつくりになる。店舗内部は北半を問屋，南半を銀行とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000749"},{"id":"00000751","register_sub_id":"101","register_pk":"101741","name":"横山郷土館文庫蔵","kana":"よこやまきょうどかんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町2-16","lat":36.38120732,"lng":139.73240798,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"石造２階建，瓦葺，建築面積66㎡","structure_material":"石造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"09 － 0009","desc":"主屋を挟み麻蔵と対称の位置にあり，独特の屋敷構えと景観を形成する石造の蔵。石材は，県内鹿沼市で産する深岩石と呼ばれる凝灰岩。つくりは麻蔵と似るが，軒を煉瓦積みとすることや１・２階間の石材の色をかえるなど，意匠により細かな配慮がなされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000751"},{"id":"00001880","register_sub_id":"101","register_pk":"102870","name":"綿忠はきもの店店舗","kana":"わたちゅうはきものてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県栃木市万町4-1","lat":36.38038931,"lng":139.73409055,"geo_status":"db","era":"安政3","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0034","desc":"綿忠は江戸後期創業という商家で，店舗は小屋梁の墨書から安政３年５月の上棟とわかる。桁行３間・梁間２間半と小規模で，通り土間が奥の住居棟まで続く。総２階建，正面下屋庇付の土蔵造で，全体に階高が低く，２階の縦長窓など幕末期の意匠がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001880"},{"id":"00000755","register_sub_id":"101","register_pk":"101745","name":"伊香保観光ホテル","kana":"いかほかんこうほてる","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県渋川市伊香保町伊香保字甲境沢550-1","lat":36.49866549,"lng":138.92455426,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造３階建，瓦葺一部鉄板葺，建築面積1874㎡","structure_material":"木造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"10 － 0028","desc":"明治の初頭より居留外国人の間で温泉場として名が知られていた伊香保の玄関口に位置する外国人向けホテル。外国人を意識した五重塔風の塔屋が特徴。木造３階建、一部ＲＣ造地下室付きで、正門からの脇道を跨ぐかたちで大食堂を配置し、三方にテラスを付す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000755"},{"id":"00002016","register_sub_id":"101","register_pk":"103006","name":"石坂家住宅土蔵","kana":"いしざかけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県渋川市下ノ町2467-1","lat":36.49598063,"lng":139.00364059,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造2階建、瓦葺、建築面積112㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0058","desc":"桁行７間半，梁間４間規模，東西棟，寄棟造，桟瓦葺，平入の２階建土蔵で，南面に３箇所の引戸口を設ける。内部は桁行２間半づつ３室に分け，中央室に階段を付ける。石坂家が質屋を営んでいた時の質蔵でもあり，主屋とともに当家の繁栄振りを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002016"},{"id":"00015401","register_sub_id":"101","register_pk":"533416","name":"江原本家上毛倉庫一号棟","kana":"えばらほんけじょうもうそうこいちごうとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県前橋市表町二丁目25-2","lat":36.38461667,"lng":139.07346111,"geo_status":"db","era":"昭和24年／平成2年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積331㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0363","desc":"ＪＲ前橋駅の北口正面に位置し、かつて繭や生糸を保管した倉庫業の営業倉庫。敷地南東に建つ鉄筋コンクリート造切妻造桟瓦葺、外壁モルタル塗仕上で鉢巻を廻らし、高窓に鉄扉を付す。小屋組は木造のキングポスト・トラス。土蔵風の外観が歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015401"},{"id":"00015403","register_sub_id":"101","register_pk":"533418","name":"江原本家上毛倉庫三号煉瓦棟","kana":"えばらほんけじょうもうそうこさんごうれんがとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県前橋市表町二丁目25-2","lat":36.38521944,"lng":139.07328889,"geo_status":"db","era":"明治29年／昭和22年頃・平成元年・同30年改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積300㎡","structure_material":"煉瓦造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0365","desc":"敷地北側に南面して建つ、かつて繭や生糸を保管した営業倉庫。煉瓦造二階建切妻造桟瓦葺で、外壁の四周に胴蛇腹と軒蛇腹を廻らし、アーチ窓を並べた長大な外観。小屋組は木造のキングポスト・トラスとする。２号煉瓦棟とともに敷地内最古の貴重な煉瓦造倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015403"},{"id":"00015404","register_sub_id":"101","register_pk":"533419","name":"江原本家上毛倉庫七号棟","kana":"えばらほんけじょうもうそうこななごうとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県前橋市表町二丁目25-2","lat":36.38470833,"lng":139.07319444,"geo_status":"db","era":"昭和25年／平成元年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積463㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0366","desc":"敷地中央に建つ米穀類用の営業倉庫。鉄筋コンクリート造切妻造桟瓦葺の南北棟で、東・西面に出入口を開け、外壁モルタル塗仕上。内部は一室の土間とし、上部に木造のキングポスト・トラスを現し、内壁は漆喰塗仕上で下部を竪板目板張。敷地内最大規模の倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015404"},{"id":"00015402","register_sub_id":"101","register_pk":"533417","name":"江原本家上毛倉庫二号煉瓦棟","kana":"えばらほんけじょうもうそうこにごうれんがとう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県前橋市表町二丁目25-2","lat":36.38498333,"lng":139.07343889,"geo_status":"db","era":"明治29年／昭和22年頃・平成2年・平成21年改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積335㎡","structure_material":"煉瓦造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"10 - 0364","desc":"敷地東辺に西面して建つ、かつて繭や生糸を保管した営業倉庫。煉瓦造二階建切妻造平入桟瓦葺で、外壁四周に胴蛇腹と軒蛇腹を廻らし、長大な桁行にアーチ窓を並べた端正な外観。小屋組は木造キングポスト・トラス。明治期の前橋の繁栄を示す貴重な煉瓦造倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015402"},{"id":"00007724","register_sub_id":"101","register_pk":"108706","name":"荻野家住宅北蔵","kana":"おぎのけじゅうたくきたぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.21147869,"lng":138.78232077,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0272","desc":"主屋の西に位置する。桁行１１ｍ梁間４．８ｍと比較的規模の大きな土蔵造２階建で、東西棟の切妻造桟瓦葺とする。外壁は白漆喰仕上げ。１階は二室に分け、東と南面に開口を設け、東面には両開の掛子塗戸を吊る。２階は一室で、トラス組架構を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007724"},{"id":"00007722","register_sub_id":"101","register_pk":"108704","name":"荻野家住宅主屋","kana":"おぎのけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.2114394,"lng":138.78247866,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0270","desc":"旧中山道脇往還に東面する短冊状の敷地の東寄りに位置する。木造２階建、起りのある入母屋造妻入桟瓦葺。１、２階とも二室に分かれ、１階はブツマなどの居室、２階にはトコや棚などを備える客間を配する。南面庭側を開放的に扱うなど軽快な近代和風建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007722"},{"id":"00007727","register_sub_id":"101","register_pk":"108709","name":"荻野家住宅新蔵","kana":"おぎのけじゅうたくしんぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.21153109,"lng":138.78199765,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0275","desc":"北蔵や南蔵などと少し離れた敷地西端に、南北棟で建つ。寄棟造桟瓦葺、桁行９．５ｍ梁間４．７ｍの土蔵造２階建。１階東面中央に出入口、２階に窓２ヶ所を開け、鉄扉を吊る。小屋はトラス組。西堀を介して旧道に面する敷地背後の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007727"},{"id":"00007728","register_sub_id":"101","register_pk":"108710","name":"荻野家住宅防火壁","kana":"おぎのけじゅうたくぼうかへき","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.21145998,"lng":138.78255877,"geo_status":"db","era":"大正13頃／昭和25頃増築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造一部鉄筋コンクリート造、延長18m","structure_material":"煉瓦造一部鉄筋コンクリート造","registered":"2009.08.07(平成21.08.07)","register_no":"10-0276","desc":"敷地北辺に主屋に接して築かれる。全長１３ｍ、高さ７．３ｍ、厚さ０．４３ｍの煉瓦造で、東側５．０ｍをＲＣ造で増築。主屋前寄りの長さ１．５ｍは１．４ｍほど高くし、棟を造り、ウダツ風に見せる。延焼防止に造られた防火壁で、地域の大火の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007728"},{"id":"00007723","register_sub_id":"101","register_pk":"108705","name":"荻野家住宅店蔵","kana":"おぎのけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.21139233,"lng":138.78259828,"geo_status":"db","era":"明治後期／大正期・昭和45頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0271","desc":"旧脇往還に東面して建つ。桁行７．７ｍ梁間５．７ｍの平入土蔵造２階建、切妻造桟瓦葺で、正面に庇を付ける。外壁は白漆喰仕上げで、腰をモルタル洗い出し仕上げとする。正面は１階にもとは土戸をたて、２階に２ヶ所窓を開けた。凝った大棟のつくりは印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007723"},{"id":"00007725","register_sub_id":"101","register_pk":"108707","name":"荻野家住宅南蔵","kana":"おぎのけじゅうたくみなみぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.21142532,"lng":138.78225672,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0273","desc":"北蔵の南に東西棟で並び建つ。桁行４．９ｍ梁間３．７ｍの土蔵造２階建、切妻造妻入桟瓦葺。外壁は白漆喰仕上げ。１階東面に両開の掛子塗戸を吊り、２階南面には窓を穿ち、鉄扉とする。内部は１、２階とも一室。大梁上に束を建て棟木を支持する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007725"},{"id":"00007726","register_sub_id":"101","register_pk":"108708","name":"荻野家住宅物置蔵及び長屋","kana":"おぎのけじゅうたくものおきぐらおよびながや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県甘楽郡下仁田町大字下仁田字中町西甲334他","lat":36.2113836,"lng":138.78236443,"geo_status":"db","era":"明治後期／大正期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階一部平屋建、瓦葺、建築面積46㎡","structure_material":"木造2階一部平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"10-0274","desc":"敷地の南辺に位置し、南側の殿小路に面する。物置蔵は桁行７．６ｍ梁間２．８ｍの木造２階建、切妻造桟瓦葺。長屋は桁行１２ｍ梁間２．２ｍの木造平屋建で、物置蔵寄りに門口を開ける。小路側に腰モルタル洗い出しの白漆喰壁が連続し、重厚な屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007726"},{"id":"00005409","register_sub_id":"101","register_pk":"106397","name":"金善ビル","kana":"かなぜんびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町5-345","lat":36.411583,"lng":139.339294,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積94㎡、塔屋付","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0158","desc":"間口８．２ｍ，奥行９．１ｍ，地下１階地上４階建，塔屋付きの鉄筋コンクリート造ビルで，１階はたちを高く造り石張風とし，２階以上には白タイルを張り，玄関上方等にセセッション風装飾を付ける。地方都市における初期鉄筋コンクリート造事務所ビルの好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005409"},{"id":"00006976","register_sub_id":"101","register_pk":"107958","name":"旧勝山社煉瓦蔵","kana":"きゅうかつやましゃれんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県前橋市本町2-3-8","lat":36.38989152,"lng":139.06963159,"geo_status":"db","era":"明治35／昭和28移築・昭和56改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積45㎡","structure_material":"煉瓦造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"10 － 0252","desc":"桁行８．８ｍ梁間５．１ｍ妻入の煉瓦造２階建で、屋根は切妻造桟瓦葺である。外壁の煉瓦はイギリス積で、鉢巻や窓まわりに土蔵風の意匠を見せる。正面出入口は後世の改修。小屋組はキングポスト・トラスである。軒が高く重厚な外観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006976"},{"id":"00010919","register_sub_id":"101","register_pk":"208890","name":"旧館林二業見番組合事務所","kana":"きゅうたてばやしにぎょうけんばんくみあいじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県館林市本町二丁目1704","lat":36.24616,"lng":139.534414,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積195㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"10-0327","desc":"料亭と芸妓置屋の二業の旧組合事務所。木造二階建で通りに西面する。一階は事務室と座敷、二階は舞台を持つ畳敷の大広間をおく。通りに面する西面は入母屋造屋根の妻と唐破風造の玄関を見せ、二階には左右対称の切妻屋根を並べるなど、和風意匠で華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010919"},{"id":"00004926","register_sub_id":"101","register_pk":"105916","name":"旧松岡商店蔵","kana":"きゅうまつおかしょうてんくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市永楽町6-7","lat":36.41248859,"lng":139.33701314,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積29㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0129","desc":"敷地の北寄りに，事務所と主屋の間に東西棟で建つ。木造２階建の蔵で，切妻造，鉄板葺の置屋根を置く。道路に面する北壁面には各階に２つの窓を開く。南面に入口を設け，蔵前を置く。外壁はモルタル塗で，事務所や主屋と共に，創建時の様子を良く伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004926"},{"id":"00004925","register_sub_id":"101","register_pk":"105915","name":"旧松岡商店事務所","kana":"きゅうまつおかしょうてんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市永楽町6-7","lat":36.4124459,"lng":139.337067,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0128","desc":"道路沿いに東面して建つ。表側の事務室２室と検反場を矩折に配し，寄棟屋根を南東隅で直交する木造平屋建。その南部に東西棟の切妻造，木造平屋建の荷受場が接続する。正面等に茶系のタイルを用いて洋風の外観を見せる商店建築で，窓脇のレリーフや丸窓が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004925"},{"id":"00004207","register_sub_id":"101","register_pk":"105197","name":"旧安田銀行担保倉庫（協同組合前橋商品市場倉庫）","kana":"きゅうやすだぎんこうたんぽそうこ（きょうどうくみあいまえばししょうひんいちばそうこ）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県前橋市住吉町2-10-2","lat":36.39725576,"lng":139.07012121,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積693㎡","structure_material":"煉瓦造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"10 － 0118","desc":"群馬商業銀行附属前橋倉庫として建設。主として生糸等の担保用倉庫で，桁行３０間梁間６間規模，切妻造，桟瓦葺の煉瓦造２階建，イギリス積の２戸前倉庫。煉瓦は日本煉瓦製造製，階下２枚階上１枚半積で，木造床，小屋組は木造のキングポストトラスである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004207"},{"id":"00002005","register_sub_id":"101","register_pk":"102995","name":"小見家住宅（水村園）新蔵","kana":"こみけじゅうたく（みずむらえん）しんぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県高崎市本町123-1","lat":36.330818,"lng":139.003128,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0047","desc":"味噌蔵の北方に位置する桁行３間半，梁行２間規模，南北棟，切妻造，桟瓦葺，平入の２階建土蔵。棟高は一番高く，東面に観音扉を付ける。内部は現在は南妻面に階段を取付け，２階の西と北の２面に造りつけの茶箱を配する。茶舗の歴史を物語る土蔵として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002005"},{"id":"00002006","register_sub_id":"101","register_pk":"102996","name":"小見家住宅（水村園）前蔵","kana":"こみけじゅうたく（みずむらえん）まえぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県高崎市本町123-1","lat":36.33089644,"lng":139.00312457,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0048","desc":"敷地の北西隅に位置し，新蔵の北妻面に接して建つ。桁行２間半，梁行は新蔵と同じ２間で，南北棟，切妻造，桟瓦葺，平入とする。棟は新蔵よりも低く，東面の入口は引戸としてより簡素なつくりとし，防火帯としての土蔵群の北端を押さえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002006"},{"id":"00002008","register_sub_id":"101","register_pk":"102998","name":"小見家住宅（水村園）レンガ蔵","kana":"こみけじゅうたく（みずむらえん）れんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県高崎市本町123-1","lat":36.330791,"lng":139.003174,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"煉瓦造2階建、瓦葺、建築面積53㎡","structure_material":"煉瓦造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0050","desc":"敷地の東辺沿い，着物蔵・味噌蔵・新蔵に向きあう位置に建つ。桁行７間半，梁行２間の規模で，東面は煉瓦造防火壁を利用し，西面は木柱を建てて吹放ちとし，南北棟の桟瓦葺寄棟屋根を架ける。煉瓦造と木造の混合構造による数少ない事例のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002008"},{"id":"00005926","register_sub_id":"101","register_pk":"106911","name":"島田商店旧石蔵","kana":"しまだしょうてんきゅういしぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市巴町1-1121-8","lat":36.409115,"lng":139.336197,"geo_status":"db","era":"昭和12／昭和60改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造2階建、瓦葺、建築面積99㎡","structure_material":"石造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0205","desc":"敷地の南面西端に位置する桁行６間，梁間５間の石造２階建。外壁は大谷石で梁形，柱形をモルタル塗とする。小屋組はキングポストトラス。当初は東面中央に戸口を設け，２階に窓を開く。商品倉庫であった内部を改修し，越屋根と玄関を付加して歯科医院とした。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005926"},{"id":"00005925","register_sub_id":"101","register_pk":"106910","name":"島田商店旧事務所","kana":"しまだしょうてんきゅうじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市巴町1-1121-8","lat":36.40903149,"lng":139.33630028,"geo_status":"db","era":"明治後期／昭和12・60改造","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0204","desc":"店舗西に接続する木造平屋建で，桁行３間，梁間４間の東西棟。島田家が取得後，板敷の事務所とし，北側に変形６畳室があり，北辺の廊下が店舗に通じる。南面はパラペットを飾り，西妻の入口上はステップゲーブル形に整える。後に南側内部を車庫に改修した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005925"},{"id":"00005927","register_sub_id":"101","register_pk":"106912","name":"島田商店旧倉庫","kana":"しまだしょうてんきゅうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市巴町1-1121-8","lat":36.40923677,"lng":139.33626779,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0206","desc":"旧石蔵の背後，敷地北西隅に位置する。木造２階建，切妻造，桟瓦葺で，桁行６間，梁間５間。小屋組はキングポストトラス。東面中央の戸口に両開鉄扉を吊り，２階東面と南面に小窓を開く。外壁はモルタル塗で，鉢巻は洗出し仕上げとし，近代以降の特徴をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005927"},{"id":"00005824","register_sub_id":"101","register_pk":"106810","name":"島田商店店舗","kana":"しまだしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市巴町1-1121-8","lat":36.40900292,"lng":139.33638607,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0203","desc":"南と東で街路に面する木造２階建で，方３間半の入母屋造，桟瓦葺の東西棟。１階は庇下に折曲りの土間を設け，畳敷の店舗の北に８畳室を置く。２階は６畳座敷と次の間６畳と板間を配し，外縁に手摺を巡らす。街路側南東隅を切るなど，近代以降の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005824"},{"id":"00003808","register_sub_id":"101","register_pk":"104798","name":"正田醤油正田記念館","kana":"しょうだしょうゆしょうだきねんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県館林市栄町3-1","lat":36.24789804,"lng":139.52684096,"geo_status":"db","era":"嘉永6／昭和62移築","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積191㎡","structure_material":"木造2階一部平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0106","desc":"創業時の店舗主屋。主体部は桁行８間梁間３間半規模，南北棟，切妻造の木造２階建で，南面と東面に半間の下屋を設け，北面に桁行２間半梁間６間の平屋建を延ばすほか，西面は２階屋根を葺下ろして背面部を覆う。棟札から「大工棟梁栗原藤右衛門」が判明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003808"},{"id":"00002214","register_sub_id":"101","register_pk":"103204","name":"白井屋","kana":"しろいや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県吾妻郡中之条町大字中之条1798","lat":36.5870215,"lng":138.84343489,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、鉄板葺、建築面積111㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"10 － 0079","desc":"三国街道脇往還に通じる新道に東面して建つ。間口桁行７間，梁行４間規模，切妻造の木造２階建で，平入とし，２階を「せがい造」に造り，６畳の客室を５室配する。周辺に官公庁舎がたちはじめた明治２５年頃から宿屋を開業と伝える。明治期旅籠遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002214"},{"id":"00000187","register_sub_id":"101","register_pk":"101177","name":"積善館山荘","kana":"せきぜんかんさんそう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県吾妻郡中之条町大字四万4236-1","lat":36.68633974,"lng":138.77348319,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建，鉄板葺，建築面積490㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"10 － 0008","desc":"四万温泉の老舗旅館の宿泊施設の一つで、前新とともに昭和初期の建築。本館の背後に建ち、木造２階建て、平面は突出した中央部を中心に左右対称の入母屋の屋根をつける変化に富んだ構成になる。施工の地元の職人の手になり、床廻りの意匠が特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000187"},{"id":"00003516","register_sub_id":"101","register_pk":"104506","name":"豊田屋旅館本館","kana":"とよたやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県高崎市八島町68","lat":36.322041,"lng":139.00914865,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"10 － 0100","desc":"高崎駅前通に北面して建つ。木造，２階建，入母屋造，桟瓦葺で，１階正面には庇を付け，中央玄関上部に唐破風を構える。客室５室を取る２階は，中廊下や周囲に廊下を配し各室の独立性を確保し旅館らしい平面とする。賑やかな外観の周囲でひときわ目立つ建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003516"},{"id":"00004933","register_sub_id":"101","register_pk":"105923","name":"中村弥市商店店舗","kana":"なかむらやいちしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-6-33","lat":36.41897355,"lng":139.34461445,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0136","desc":"本町通に接し，西面して建つ。桁行５間，梁間３間半，桟瓦葺，東西棟の木造２階建で，正面を寄棟造とする。東側以外の３方に半間の下屋を張出す。北側の路地に面する外壁は大壁とし鼠漆喰仕上とする。創建時の店構えを良く残し，織物産業の興隆を伝え貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004933"},{"id":"00005762","register_sub_id":"101","register_pk":"106750","name":"平田家住宅旧店舗","kana":"ひらたけじゅうたくきゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県桐生市本町1-6-28","lat":36.4185732,"lng":139.34429093,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0199","desc":"本町通りに西面する間口３間半，土蔵造２階建の平入町家。切妻造，桟瓦葺で，表に瓦葺下屋を付ける。１階は土間に改修され，北側の店蔵の戸口前と東面に床板を張る。２階は床構えをもつ１０畳座敷がある。白漆喰塗の外壁に２階の重厚な塗戸内面の黒漆喰が映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005762"},{"id":"00005783","register_sub_id":"101","register_pk":"106771","name":"平田家住宅旧店蔵","kana":"ひらたけじゅうたくきゅうみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市本町1-6-28","lat":36.4186017,"lng":139.3443109,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"10 － 0200","desc":"本町通りに西面する間口３間半，土蔵造２階建の平入町家。切妻造，桟瓦葺で，表に瓦葺下屋を付ける。１階は土間に改修され，北側の店蔵の戸口前と東面に床板を張る。２階は床構えをもつ１０畳座敷がある。白漆喰塗の外壁に２階の重厚な塗戸内面の黒漆喰が映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005783"},{"id":"00005583","register_sub_id":"101","register_pk":"106571","name":"法師温泉長寿館大浴場（法師乃湯）","kana":"ほうしおんせんちょうじゅかんだいよくじょう（ほうしのゆ）","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県利根郡みなかみ町永井650他","lat":36.74428677,"lng":138.83019761,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0189","desc":"法師川東岸に，本館の北側に建つ。桁行１２ｍ，梁間１０ｍの規模で，木造平屋建，寄棟造，杉皮葺とする。屋根は和小屋に一部トラスを用い，棟上に櫓状の換気口を付ける。軒は四周をせがい造とし，外壁を下見板張とする。アーチ窓を開き，特徴ある意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005583"},{"id":"00005584","register_sub_id":"101","register_pk":"106572","name":"法師温泉長寿館別館","kana":"ほうしおんせんちょうじゅかんべっかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県利根郡みなかみ町永井650他","lat":36.74417659,"lng":138.8298859,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積276㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0190","desc":"法師川西岸に南北棟で建ち，桁行３７ｍ，梁間９ｍの規模で，木造２階建，切妻造，鉄板葺とする。１，２階共に客室を一列に並べ，川側に広縁をとって掃き出しのガラス戸を並べ，反対側は片廊下として，腰窓を付ける。外壁は漆喰塗で，落ち着いた意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005584"},{"id":"00005582","register_sub_id":"101","register_pk":"106570","name":"法師温泉長寿館本館","kana":"ほうしおんせんちょうじゅかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県利根郡みなかみ町永井650他","lat":36.74412659,"lng":138.83022379,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、杉皮葺、建築面積368㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0188","desc":"法師川東岸に南北棟で建ち，桁行３０ｍ，梁間１４ｍの規模で，木造２階建，切妻造，杉皮葺とし，軒をせがい造とする。１階に玄関，事務室等を置き，２階に客室をとる。玄関上部に切妻造の屋根を付け，２階正面には手摺を付ける。屋根には煙出しを上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005582"},{"id":"00002014","register_sub_id":"101","register_pk":"103004","name":"堀口家住宅付属屋","kana":"ほりぐちけじゅうたくふぞくや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県渋川市上ノ町2341","lat":36.495861,"lng":139.000214,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積131㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0056","desc":"街道に沿って店蔵の東面に接して建つ。木造２階建，東西棟の切妻造，もと板葺（現在は鉄板葺）で平入とする。１階は作業場を兼ねた店でトロッコレールを残し，２階は街道側を倉庫として使用していた。店蔵とともに明治の街道筋の面影を伝えており貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002014"},{"id":"00002010","register_sub_id":"101","register_pk":"103000","name":"堀口家住宅店蔵","kana":"ほりぐちけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県渋川市上ノ町2335","lat":36.495884,"lng":139.000092,"geo_status":"db","era":"慶応2","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0052","desc":"渋川における老舗の金物商家で，主要地方道渋川松井田線と平沢川とに挟まれた南北に長い敷地の北西隅に北面して建つ。間口４間奥行３間半規模の２階建，切妻造，桟瓦葺，平入の黒漆喰塗店蔵で，重厚さにおいて卓越している。年代は棟札による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002010"},{"id":"00004797","register_sub_id":"101","register_pk":"105787","name":"森合資会社事務所","kana":"もりごうしがいしゃじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-3-11","lat":36.4196099,"lng":139.34473883,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"10 － 0123","desc":"街路に東面する間口４間奥行６間の木造平屋建。正面北寄の玄関上部にペディメントを掲げ，銅板製の軒蛇腹を巡らし，外壁を白化粧煉瓦張とするなど洋風意匠を取り入れる。入口と窓の庇は反りをもち，垂木を見せた和風意匠とする。街路景観のアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004797"},{"id":"00004798","register_sub_id":"101","register_pk":"105788","name":"森合資会社店蔵","kana":"もりごうしがいしゃみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市本町1-3-11","lat":36.41954876,"lng":139.34464524,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積82㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"10 － 0124","desc":"事務所の南に接続する桁行６間，梁間３間規模の土蔵造２階建である。切妻造，桟瓦葺で，街路に面した妻面の１，２階に窓を開き，漆喰塗の両開き戸を吊り込む。外壁は白漆喰塗で，２段の水切を塗出し，腰は石積とする。事務所と共に街路景観の一要素をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004798"},{"id":"00009129","register_sub_id":"101","register_pk":"164682","name":"山本館本店","kana":"やまもとかんほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県吾妻郡草津町大字草津字西町404","lat":36.62321014,"lng":138.59633507,"geo_status":"db","era":"昭和3年／昭和10年増築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造地上3階地下1階建、鉄板葺、建築面積370㎡","structure_material":"木造地上3階地下1階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"草津温泉の湯畑の西隣に位置する。建築面積370平方メートル、木造3階地下1階建、入母屋造鉄板葺、塔屋付で、東面に千鳥破風を飾る。正面入口に構える唐破風造の玄関や、各階に廻らした軒庇が外観を特徴付けており、草津のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009129"},{"id":"00011061","register_sub_id":"101","register_pk":"205168","name":"横手館本館西棟","kana":"よこてかんほんかんにしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県渋川市伊香保町伊香保字香湯12-1","lat":36.49656,"lng":138.916439,"geo_status":"db","era":"大正10頃／昭和前期・同後期改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造4階建、鉄板葺、建築面積369㎡","structure_material":"木造4階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0330","desc":"東棟の西に続いて建つ。四階建で各階外壁をせがいで持ち出し、ガラス窓と化粧垂木付の水平庇を連続させる外観は東館と共通する。内部客室も当初の状況を良く残し、様々な銘木や趣向を凝らした造形、障子や欄間の精緻な細工も見事な上質の木造旅館建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011061"},{"id":"00011060","register_sub_id":"101","register_pk":"205167","name":"横手館本館東棟","kana":"よこてかんほんかんひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県渋川市伊香保町伊香保字香湯12-1","lat":36.496461,"lng":138.916701,"geo_status":"db","era":"大正9頃／昭和後期・平成22改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積519㎡","structure_material":"木造3階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0329","desc":"伊香保温泉の石段の上方東側に位置する旅館で、東館は敷地中央に建つ。木造三階建、入母屋造鉄板葺で、外周部はガラス窓と各階の庇を水平に連続させ、大屋根と庇には化粧垂木を付し、要所に庇を貫く化粧丸太附柱をアクセントとし、温泉街の景観に寄与する","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011060"},{"id":"00014136","register_sub_id":"101","register_pk":"508766","name":"青山茶舗旧納屋（楽風）","kana":"あおやまちゃほきゅうなや（らふ）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市浦和区岸町四丁目84","lat":35.85513889,"lng":139.65509722,"geo_status":"db","era":"明治24年／平成4年改修","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"11-0214","desc":"中山道沿い商家の納屋で主屋背面側に南面して建つ。真壁造２階建、切妻造桟瓦葺平入で、正面に庇を架け、２階南面に２箇所窓を開ける。内部は各階東西二室に分け、一階背面側に一室配する。茶等の保管に使用した。街道沿いの広大な敷地中程に景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014136"},{"id":"00014135","register_sub_id":"101","register_pk":"508765","name":"青山茶舗店舗兼主屋","kana":"あおやまちゃほてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市浦和区岸町四丁目84","lat":35.855075,"lng":139.65483333,"geo_status":"db","era":"明治後期／昭和前期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積135㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"11-0213","desc":"浦和宿の南に位置。中山道に西面する店舗と棟を直交する主屋からなり、店舗は２階建切妻造桟瓦葺。正面に下屋を通し、軒、下屋とも出桁造とする。１階は南を土間、北を畳敷のミセとし２階も２室とる。主屋は平屋建で８畳２室。旧街道に重厚な店構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014135"},{"id":"00010920","register_sub_id":"101","register_pk":"208891","name":"秋田家住宅店舗兼主屋","kana":"あきたけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県所沢市寿町527","lat":35.791383,"lng":139.468085,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積112㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"11-0149","desc":"所沢駅北西の商業地で通りに南面し、一階前半部のミセの開口を広めて格子戸をたてる。切妻造の二階を東に寄せ、上下階とも出桁造で軒先まで銅板を張り防火を講ずる、特徴的な外観をもつ。二階には瀟洒な造作の座敷を設ける。織物業で栄えた当地の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010920"},{"id":"00000034","register_sub_id":"101","register_pk":"101024","name":"あさひ銀行川越支店（旧八十五銀行本店本館）","kana":"あさひぎんこうかわごえしてん（きゅうはちじゅうごぎんこうほんてんほんかん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県川越市幸町４-２","lat":35.92258465,"lng":139.4831374,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"鉄骨鉄筋コンクリート造3階建塔屋・金庫室付、建築面積291㎡","structure_material":"鉄骨鉄筋コンクリート造3階建塔屋・金庫室付","registered":"1996.12.20(平成8.12.20)","register_no":"11 － 0001","desc":"ネオルネサンスリバイバル，サラセン風など各種様式を折衷的に用いた洋風銀行建築。設計は保岡勝也，施工は印藤順造。川越の伝統的な町並みの中で近代のあゆみを示す象徴として，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000034"},{"id":"00003380","register_sub_id":"101","register_pk":"104370","name":"朝日屋原薬局主屋","kana":"あさひやはらやっきょくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県志木市本町二丁目1618","lat":35.83379079,"lng":139.57950679,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"11 － 0049","desc":"街道に面して建つ店舗兼用住宅。木造２階建，切妻造，平入で西を正面とし，下屋庇を設ける。屋根はすべて桟瓦葺で，棟瓦を高く積む。１階は開放的な店構えだが，２階は窓に鉄格子をつけ，軒を出桁造とするなど，土蔵造と異なる重厚な外観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003380"},{"id":"00000757","register_sub_id":"101","register_pk":"101747","name":"回漕問屋吉野屋土蔵","kana":"かいそうどんやよしのやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県ふじみ野市福岡3-4-12","lat":35.88562381,"lng":139.52303518,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造２階建，瓦葺，建築面積20㎡","structure_material":"土蔵造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"11 － 0006","desc":"吉野屋は安永２年(1773)に船問屋になり回漕業を営み栄えた家で，土蔵は新河岸川沿いにある旧屋敷地に建つ。二階建の小規模な土蔵だが，近辺では往時の建物が少なくなってきており，舟運で栄えた河岸の様子を物語る建物として貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000757"},{"id":"00004209","register_sub_id":"101","register_pk":"105199","name":"割烹旅館二葉本店本館","kana":"かっぽうりょかんふたばほんてんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県比企郡小川町大字大塚32-5","lat":36.05564652,"lng":139.26101152,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積461㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"11 － 0082","desc":"小川町駅からの駅前通りに西面して建つ。正面側は複雑な屋根構成をもち，内部２階には床の間と舞台を両面に配した７０畳の大広間を設ける。東京から棟梁を招いて造らせたと伝える。吟味された用材とともに職人芸が随所に発揮された数寄屋風料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004209"},{"id":"00004210","register_sub_id":"101","register_pk":"105200","name":"割烹旅館二葉本店六六亭","kana":"かっぽうりょかんふたばほんてんろくろくてい","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県比企郡小川町大字大塚32-5","lat":36.0557028,"lng":139.26129272,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"11 － 0083","desc":"本館の東方，庭園内の池畔に建つ。逆Ｚ字形の棟をもつ寄棟造，桟瓦葺の平屋建で，内部は４畳半と８畳の客室２室等から成り，池上の８畳茶室は船底天井をもち，南面と東面に高欄付きの縁を廻す。本館と同様銘木奇木を用いた数寄屋風離れの好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004210"},{"id":"00009905","register_sub_id":"101","register_pk":"196052","name":"金子家住宅主屋","kana":"かねこけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県入間郡越生町大字越生字町769","lat":35.96394214,"lng":139.29757897,"geo_status":"db","era":"安政5／明治前期・大正期改修","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造2階建、瓦葺、建築面積230㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"11 － 0141","desc":"通りに南面して建つ。出桁造の二階建で、一階前寄りをミセとして正面に下屋を設ける。ミセ・チャノマの西側に座敷を張出し、背面側に通土間を通じて広い土間を設ける。二階にも四室の座敷を設ける。生糸産業で栄えた当地における幕末の商家の佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009905"},{"id":"00003831","register_sub_id":"101","register_pk":"104821","name":"カフェ・パリー","kana":"かふぇ・ぱりー","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1036-1","lat":35.99420992,"lng":139.0835754,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積60㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0068","desc":"木造２階建で，通り側壁面を高く立上げ，片流れの鉄板葺屋根を架け，小屋裏窓を設けて正面３階建にみせる。モルタル塗の外壁は，上部にコーニスを廻し，窓上には装飾をつける。外観を洋風とした店舗兼用住宅で，昭和初期における多様な建築意匠の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003831"},{"id":"00000813","register_sub_id":"101","register_pk":"101803","name":"川越商工会議所（旧武州銀行川越支店）","kana":"かわごえしょうこうかいぎしょ（きゅうぶしゅうぎんこうかわごえしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県川越市仲町1-12","lat":35.92102812,"lng":139.48343037,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上２階建，建築面積566㎡","structure_material":"鉄筋コンクリート造地下１階地上２階建","registered":"1998.10.09(平成10.10.09)","register_no":"11 － 0007","desc":"蔵造りの町並の続く市街地に立地する。外観はドーリス式の列柱を配した重厚な構えになるが，全体の意匠はルネッサンス・リバイバル様式とする。交差点側にバロック風の装飾を付けた特徴的な出入口を設けるなど，時代の特徴を伝える銀行建築の一つである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000813"},{"id":"00010748","register_sub_id":"101","register_pk":"201583","name":"木下半助商店石蔵","kana":"きのしたはんすけしょうてんいしくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県越谷市中町4675","lat":35.893339,"lng":139.786305,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積32㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"11 ‐ 0146","desc":"店舗及び土蔵の南隣に南北棟で建つ。主構造は木造二階建で、外壁に房州石を張り、石目を意匠的に表して石造風に見せる。上下階とも一室で、通路に面する東面に戸口または窓を二箇所ずつ開き、掛子塗戸形状の鉄扉を吊る。防火性向上への工夫がみられる商品蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010748"},{"id":"00010750","register_sub_id":"101","register_pk":"201585","name":"木下半助商店稲荷社","kana":"きのしたはんすけしょうてんいなりしゃ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県越谷市中町4675","lat":35.893075,"lng":139.785948,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.6㎡、覆屋付","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"11 ‐ 0148","desc":"敷地最奥に東面する、ケヤキ造の一間社流造社殿で、身舎の三方に縁を廻らし、組物出組、腰組四手先とする手の込んだ形式になる。身舎正面の小脇板や庇虹梁上に龍彫刻を配し、組物間に花鳥の彫刻を配して巻斗を置く。随所を技巧的で表情豊かな彫刻で飾る屋敷社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010750"},{"id":"00010749","register_sub_id":"101","register_pk":"201584","name":"木下半助商店主屋","kana":"きのしたはんすけしょうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県越谷市中町4675","lat":35.893157,"lng":139.786051,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積48㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"11 ‐ 0147","desc":"敷地奥寄りに建つ、離れ座敷のような趣の住宅。木造二階建、寄棟造桟瓦葺で、二階窓に庇を廻らせる。上下階とも二室で縁を設けて丸太桁を通す。床廻りや室境の透彫欄間に和洋の銘木を使い、付書院の欄間は巧緻な組子細工を飾る。瀟洒な意匠になる住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010749"},{"id":"00010747","register_sub_id":"101","register_pk":"201582","name":"木下半助商店店舗及び土蔵","kana":"きのしたはんすけしょうてんてんぽおよびどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県越谷市中町4675","lat":35.893437,"lng":139.786383,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建及び土蔵造2階建、鉄板葺及び銅板葺、建築面積71㎡","structure_material":"木造平屋建及び土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"11 ‐ 0145","desc":"日光街道越谷宿の中ほどに位置し北面する道具店で、短冊形敷地の前面に店舗及び土蔵を構える。店舗部は低床のミセの東側に土間を通し、正面に摺揚戸を残す。背後に接続する土蔵は二階建で外壁を銅板張とする。明治期の越谷における商店の面影をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010747"},{"id":"00003820","register_sub_id":"101","register_pk":"104810","name":"旧新井商店商品倉庫","kana":"きゅうあらいしょうてんしょうひんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県秩父市本町1400","lat":35.99678446,"lng":139.08245854,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0057","desc":"店舗と主屋の間の中庭南にある。東西棟の切妻造，妻入，桟瓦葺，２階建で，外壁は漆喰塗とする。軒は二重に鉢巻きを廻す。東面１階は旧事務室と接続し，開口部を鳥居形に縁取り，黒漆喰塗の重厚な観音扉をつける。全体に丁寧なつくりの土蔵建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003820"},{"id":"00005076","register_sub_id":"101","register_pk":"106066","name":"旧新井商店店舗及び主屋","kana":"きゅうあらいしょうてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県秩父市本町1400","lat":35.99675416,"lng":139.08254239,"geo_status":"db","era":"明治初期／明治中期移築／大正初期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階一部平屋建、瓦葺、建築面積189㎡","structure_material":"木造2階一部平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0056","desc":"店舗は切妻造，平入，２階建で旧秩父往還に東面して建ち，南妻面に平屋建の旧事務室を張り出す。寄棟造，平屋建の主屋は後方に廊下で接続する。店舗は重厚な土蔵造で，正面両端に袖卯建をあげ，２階窓に格子を入れる。明治中期商家の佇まいをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005076"},{"id":"00006675","register_sub_id":"101","register_pk":"107658","name":"旧荒井八郎商店大広間棟","kana":"きゅうあらいはちろうしょうてんおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県行田市佐間1-2351-1","lat":36.13400935,"lng":139.46121509,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"11 － 0111","desc":"事務所兼主屋の西北、洋館との間に建つ。東西棟で西側を寄棟造、東側を切妻とする木造平屋建の桟瓦葺。庭園を望む南側に１０畳２室、その控えとして北側に４畳２室を配し、四周に縁を廻す。トコに欅の一枚板、落掛に黒柿を使うなど贅をつくした内装である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006675"},{"id":"00006674","register_sub_id":"101","register_pk":"107657","name":"旧荒井八郎商店事務所兼主屋","kana":"きゅうあらいはちろうしょうてんじむしょけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県行田市佐間1-2351-1","lat":36.13400142,"lng":139.461388,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積213㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"11 － 0110","desc":"事務所兼主屋と大広間棟、洋館の３棟が雁行型に並ぶ。事務所兼主屋は南面して建つ木造２階建で、寄棟造とし、建築面積２１３㎡に及ぶ。屋根に緑釉瓦を葺き、２階をモルタルで仕上げ、１階にスクラッチタイルを貼り、外観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006674"},{"id":"00006676","register_sub_id":"101","register_pk":"107659","name":"旧荒井八郎商店洋館","kana":"きゅうあらいはちろうしょうてんようかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県行田市佐間1-2351-1","lat":36.13400621,"lng":139.46108985,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造3階建、瓦葺、建築面積46㎡","structure_material":"木造3階建","registered":"2007.12.05(平成19.12.05)","register_no":"11 － 0112","desc":"大広間棟の北西に位置し、大広間棟から廊下で繋がる。木造３階建の洋館で、もとはゲストハウス。屋根を緑釉瓦で葺き、外壁はモルタル仕上げ。欠円形の飾り庇のタイル貼を３連格子窓の上に設けるなど、アクセントを付ける。３階は四方に窓を開く望楼である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006676"},{"id":"00005257","register_sub_id":"101","register_pk":"106245","name":"旧大月旅館別館","kana":"きゅうおおつきりょかんべっかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県秩父市番場町1035-3","lat":35.99570021,"lng":139.08386596,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、金属板葺、建築面積46㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"11 － 0095","desc":"木造２階建で，外壁を高く立ち上げた，いわゆる看板建築の外観。角は隅切の形状で，１階入口は竹をモチーフにしたと思われる柱型を設け，コーニスの下はリボンを模した帯風の飾りで装飾する。番場町通と昭和通が交差した角地にあり，際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005257"},{"id":"00004208","register_sub_id":"101","register_pk":"105198","name":"旧小川忠次郎商店店舗及び主屋","kana":"きゅうおがわちゅうじろうしょうてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県行田市忍1-4-6","lat":36.14171369,"lng":139.45687972,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積88㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"11 － 0081","desc":"街路に東面して南北棟の店舗が建ち，その西奥に東西棟の主屋を続ける。店舗南側を土間のミセとし，北側に帳場，ナカノマ，オクを並べ，主屋２階に奥座敷を設ける。北面と西面を塗込めた防火的なつくりが特徴で，行田における足袋産業の隆盛期を物語る建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004208"},{"id":"00002891","register_sub_id":"101","register_pk":"103881","name":"旧柿原商店石塀","kana":"きゅうかきはらしょうてんいしべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市本町1404-4","lat":35.99706991,"lng":139.08255097,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造、延長30m","structure_material":"石造","registered":"2002.08.21(平成14.08.21)","register_no":"11 － 0045","desc":"市街地の角地に屋敷を構える銘仙問屋で，敷地北辺を画するのが石塀である。凝灰岩系の切石布積で，延長約３０ｍの規模を有し，傾斜を基礎の玉石積で処理している。中途の通用口はアーチ式開口部とする。昭和初期の商家建築の外構をよく整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002891"},{"id":"00002887","register_sub_id":"101","register_pk":"103877","name":"旧柿原商店店舗及び主屋","kana":"きゅうかきはらしょうてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市本町1404-4","lat":35.997032,"lng":139.082474,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階及び平屋建、瓦葺、建築面積601㎡","structure_material":"木造2階及び平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"11 － 0041","desc":"木造・２階建（背面一部平屋建）で，寄棟造・桟瓦葺，正面の東面には下屋庇をつける。軒は出桁造で，開口部には繊細な格子戸を入れ，欅材を多用した丁寧なつくりになる。昭和初期の商家建築の形式をよく伝え，市街地の角地でランドマークになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002887"},{"id":"00002888","register_sub_id":"101","register_pk":"103878","name":"旧柿原商店土蔵Ａ","kana":"きゅうかきはらしょうてんどぞうえー","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市本町1404-4","lat":35.996906,"lng":139.08255,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"11 － 0042","desc":"秩父市街の中心部にある銘仙問屋の倉庫建築で，主屋の背後，敷地西側に建つ。桁行３間半梁間２間の２階建の土蔵で，切妻造・桟瓦葺，平入になる。軒は鉢巻のみと簡素だが，腰の簓子下見板張や基礎の玉石積及び小屋のトラス組など，要所を丁寧なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002888"},{"id":"00002890","register_sub_id":"101","register_pk":"103880","name":"旧柿原商店土蔵Ｃ","kana":"きゅうかきはらしょうてんどぞうしー","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市本町1404-4","lat":35.996967,"lng":139.082321,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"11 － 0044","desc":"秩父市街の中心部にある銘仙問屋の倉庫建築で，主屋の南西，土蔵Ｂの東側に直交して建つ。桁行５間梁間２間半の２階建，切妻造・桟瓦葺，平入である。１階の戸口や各階の窓の観音扉は丁寧なつくりで，内部には物置の棚も残り，保存状態が良好な土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002890"},{"id":"00002889","register_sub_id":"101","register_pk":"103879","name":"旧柿原商店土蔵Ｂ","kana":"きゅうかきはらしょうてんどぞうびー","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市本町1404-4","lat":35.996971,"lng":139.082382,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"11 － 0043","desc":"秩父市街の中心部にある銘仙問屋の倉庫建築で，主屋の背後，敷地西側に土蔵Ａと並んで建つ。桁行５間梁間２間の２階建，切妻造・桟瓦葺で，平入とする。１階の戸口や各階の窓の観音扉，腰の簓子下見板張や基礎の玉石積など，丁寧なつくりの土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002889"},{"id":"00000188","register_sub_id":"101","register_pk":"101178","name":"旧本庄商業銀行煉瓦倉庫","kana":"きゅうほんじょうしょうぎょうぎんこうれんがそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県本庄市銀座1-5-16","lat":36.24053447,"lng":139.18336488,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"煉瓦造2階建，瓦葺，建築面積279㎡","structure_material":"煉瓦造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"11 － 0002","desc":"約31m×8.5mの内法の長方形平面の煉瓦造倉庫である。当時高価であった繭や生糸を担保として貯蔵するため、左右対称の位置に設けられた窓に、網戸と鉄扉を設け、通風と防火に配慮している。現在では菓子店の店舗兼工場として活用され、広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000188"},{"id":"00003833","register_sub_id":"101","register_pk":"104823","name":"小池煙草店","kana":"こいけたばこてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1037-7","lat":35.99427988,"lng":139.08385464,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、鉄板葺、建築面積61㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0070","desc":"角地に建つ木造２階建で，通り側の壁を高く立上げ，背面側に鉄板葺の片流れ屋根を架ける。通り側は隅を丸めて連続した壁面とし，コーニス・モールディング・窓周りの縁取りなどと，その他の壁面を色や仕上げで分ける。装飾性に富んだ昭和初期の店舗兼用住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003833"},{"id":"00003843","register_sub_id":"101","register_pk":"104833","name":"小林家住宅主屋","kana":"こばやしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県桶川市寿1-14-11","lat":36.00127,"lng":139.565094,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0080","desc":"中山道桶川宿にある。もと旅籠の建物を，材木商が幕末より店舗に用いてきた。切妻造，桟瓦葺，平入の２階建で，正面に下屋庇を設ける。２階の軒は出桁造で，２階開口部は横一杯に繊細な格子を建て込む。街路に面して建ち，かつての宿場の面影を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003843"},{"id":"00001364","register_sub_id":"101","register_pk":"102354","name":"佐久間旅館奥の間","kana":"さくまりょかんおくのま","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県川越市松江町2-5","lat":35.92149714,"lng":139.48480055,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積65㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"11 － 0010","desc":"川越で由緒ある旅館のひとつ。新築された本館の奥に建ち，小屋組の墨書より明治44年の建築で，大工は清水丑太郎。木造２階建，南面の庭側に縁を廻すほかは防火を重視した大壁造とする。２階にある２つの座敷は銘木を用い，洗練された書院造で格調が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001364"},{"id":"00013227","register_sub_id":"101","register_pk":"366216","name":"島村老茶舗店舗兼主屋","kana":"しまむらろうちゃほてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県桶川市寿二丁目1384","lat":36.00081667,"lng":139.56589722,"geo_status":"db","era":"大正15年／平成30年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積99㎡","structure_material":"木造2階一部平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"11 － 0193","desc":"旧桶川宿に位置し、中山道に西面して建つ商家。木造二階建、切妻造桟瓦葺平入の店舗とその背面に続く平屋建の主屋からなる。店鋪二階の接客用に用いた床棚付の部屋等、内部は当初の姿をよく留める。少なくなりつつある旧宿場町の様相を今に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013227"},{"id":"00009709","register_sub_id":"101","register_pk":"195538","name":"十一屋北西商店蔵","kana":"じゅういちやきたにししょうてんくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県川口市鳩ヶ谷本町1-1773-1","lat":35.83279589,"lng":139.73983906,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積69㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"11 － 0134","desc":"店舗の南隣に東西棟で建つ。土蔵造二階建、桁行一二・七メートル梁間五・四メートル、切妻造桟瓦葺で、東妻面を戸口として下屋を設ける。外壁はモルタル洗出し仕上げで石造風に目地を切り、鉢巻を廻らす。内部は広い一室で、小屋はキングポストトラスとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009709"},{"id":"00009708","register_sub_id":"101","register_pk":"195537","name":"十一屋北西商店店舗","kana":"じゅういちやきたにししょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県川口市鳩ヶ谷本町1-1773","lat":35.83287204,"lng":139.73989141,"geo_status":"db","era":"昭和5頃／昭和30頃改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積52㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"11 － 0133","desc":"旧鳩ヶ谷宿の県道沿いに東面し、木造二階建、切妻造桟瓦葺で正面を下屋とする。一階正面に成二尺超のケヤキの差物を渡し、二階は繊細な格子をたて、軒は上下階とも出桁造とする。内部もケヤキの良材を多用し、二階は座敷を配する。宿場の面影を伝える商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009708"},{"id":"00006446","register_sub_id":"101","register_pk":"107429","name":"十万石ふくさや行田本店店舗","kana":"じゅうまんごくふくさやぎょうだほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県行田市行田20-15","lat":36.141319,"lng":139.461014,"geo_status":"db","era":"明治16／昭和44曳家","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積96㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"11 － 0108","desc":"旧日光館林道に南面して建つ。間口７．９ｍ、奥行１３ｍ、桟瓦葺の土蔵造２階建で、街路に面する切妻棟の背面にＴ字形に棟が接続する。たちが高く、外観を漆喰で塗り込め、大ぶりの鬼板を棟に戴くなど、重厚な意匠で、街路の歴史的景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006446"},{"id":"00004334","register_sub_id":"101","register_pk":"105324","name":"太陽軒","kana":"たいようけん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県川越市元町1-1-23","lat":35.92408938,"lng":139.48476796,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、スレート葺、建築面積154㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"11 － 0085","desc":"関東大震災後の復興商業建築の雰囲気をよく伝える。寄棟造，スレート葺の木造２階建で，軒をやや深く突出させて屋根を隠したつくりとする。隅切りの玄関，玄関上部の円形庇，２階の尖頭隅窓，独特の柱頭を持つ隅柱など，東南角部の表現主義的造形意匠に特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004334"},{"id":"00002603","register_sub_id":"101","register_pk":"103593","name":"武村旅館","kana":"たけむらりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県桶川市南1-8-8","lat":35.99913,"lng":139.567047,"geo_status":"db","era":"江戸末期／明治末期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積102㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"11 － 0039","desc":"中山道の桶川宿にあり，街道に北面して建つ。基本は切妻造・平入であるが，明治末期の改造で正面左半分を突出させ，寄棟造の屋根を付ける。柱や差物が木太くしっかりしたつくりで，正面の入口大戸構や縦格子，庇など，宿場の面影を伝える旅籠建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002603"},{"id":"00003828","register_sub_id":"101","register_pk":"104818","name":"秩父銘仙出張所一","kana":"ちちぶめいせんしゅっちょうしょいち","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1001","lat":35.99608274,"lng":139.08306496,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0065","desc":"かつて秩父銘仙で賑わった買継ぎ通りと呼ばれる通りに東面して建つ。木造２階建，切妻造の桟瓦葺，平入で，正面２階軒を出桁造とし，１階には庇をつける。２戸１棟形式で，外観は基本的に中央で左右対称になる。当時の商業地区の景観の一端を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003828"},{"id":"00003830","register_sub_id":"101","register_pk":"104820","name":"秩父銘仙出張所三","kana":"ちちぶめいせんしゅっちょうしょさん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1001","lat":35.99627848,"lng":139.08312239,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0067","desc":"かつて秩父銘仙で賑わった買継ぎ通りに，東面して建つ。木造２階建，切妻造の平入で，正面２階軒を出桁造，１階は下屋を設ける。２戸１棟形式で，正面は２階が真壁造，１階がガラス戸を入れた開放的な店構えで，当時の商業地区の景観の一端を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003830"},{"id":"00003829","register_sub_id":"101","register_pk":"104819","name":"秩父銘仙出張所二","kana":"ちちぶめいせんしゅっちょうしょに","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1001","lat":35.99638035,"lng":139.08316077,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0066","desc":"かつて秩父銘仙で賑わった買継ぎ通りに，東面して建つ。木造２階建，切妻造の平入で，正面２階軒を出桁造，１階は下屋を設ける。正面は真壁造で軽快な壁面構成をみせ，外観は左右対称の２戸１棟形式になり，当時の商業地区の景観の一端を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003829"},{"id":"00001363","register_sub_id":"101","register_pk":"102353","name":"手打ちそば百丈（旧湯宮釣具店）","kana":"てうちそばひゃくじょう（きゅうゆみやつりぐてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県川越市元町1-1-15","lat":35.92461686,"lng":139.48517667,"geo_status":"db","era":"昭和初期（昭和9以前）","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積55㎡","structure_material":"木造3階建","registered":"1999.10.14(平成11.10.14)","register_no":"11 － 0009","desc":"木造３階建て店舗併用住宅で，昭和初期建設の看板建築である。銅板貼りの壁面は破目地で，隅部を柱型風とし，各階の境に軒蛇腹を廻す。２階正面のエジプト風半円付柱，それぞれ意匠を変えたペジメント風の庇など，多彩な様式細部を巧みにまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001363"},{"id":"00012496","register_sub_id":"101","register_pk":"367791","name":"東京ゴルフ倶楽部クラブハウス","kana":"とうきょうごるふくらぶくらぶはうす","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"埼玉県","address":"埼玉県狭山市柏原字通り窪1957-5","lat":35.881481,"lng":139.401627,"geo_status":"geocoded","era":"昭和38年／昭和47年増築、平成6年改修","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造及び木造2階建、銅板葺、建築面積1498㎡","structure_material":"鉄筋コンクリート造及び木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"11 － 0173","desc":"入間川北岸の段丘上にあるゴルフ場の中心部に建つ。一階鉄筋コンクリート造、二階木造で、変形のロの字平面に緩勾配屋根を輻輳してかけ渡す。丸太の柱や梁を多用し、中央に暖炉を備えた山小屋風のラウンジなど、レーモンドの作風が顕著に表れた円熟期の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012496"},{"id":"00006673","register_sub_id":"101","register_pk":"107656","name":"東玉大正館（旧中井銀行岩槻支店）","kana":"とうぎょくたいしょうかん（きゅうなかいぎんこういわつきしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県さいたま市岩槻区本町3-2439-9","lat":35.9490563,"lng":139.69611419,"geo_status":"db","era":"大正後期／平成18改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造2階建、瓦葺、建築面積130㎡","structure_material":"煉瓦造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"11 － 0109","desc":"通りの北側に建つ煉瓦造２階建で、寄棟造桟瓦葺屋根とする。正面を３分割し、上部を半円アーチ型で飾る入口を中央に開き、２階は左右の対称位置に上げ下げ窓を開ける。腰壁を石貼とし、その上を煉瓦タイルとモルタルで仕上げる。大正期の地方銀行の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006673"},{"id":"00015140","register_sub_id":"101","register_pk":"530564","name":"常盤園茶舗倉庫","kana":"ときわえんちゃほそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県深谷市仲町145","lat":36.19475,"lng":139.28306389,"geo_status":"db","era":"明治40年頃／昭和6年頃・令和4年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"煉瓦造及び木造2階建、瓦葺、建築面積36㎡","structure_material":"煉瓦造及び木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"11 - 0230","desc":"旧中山道の南に敷地を構える茶商の商品兼家財用の倉庫。二階建切妻造桟瓦葺で、一階は煉瓦一枚半積で内法高まで立上げ、上部は土台を据えて木造とし、壁面を煉瓦半枚積とする混構造。昭和6年西埼玉地震後と伝わる鉄骨補強した外観が深谷の歴史を伝える倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015140"},{"id":"00011070","register_sub_id":"101","register_pk":"205177","name":"長谷川家住宅旧店蔵及び主屋","kana":"はせがわけじゅうたくきゅうみせぐらおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市岩槻区本町三丁目2839-1他","lat":35.951236,"lng":139.696367,"geo_status":"db","era":"明治前期／昭和56頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"旧店蔵 土蔵造2階建、瓦葺、建築面積49㎡ 主屋 木造平屋建、瓦葺、建築面積53㎡","structure_material":"旧店蔵 土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"11 - 0155","desc":"岩槻旧城下の町人地に位置し、通りに南面して土蔵造二階建の店蔵を建て、背面側に木造平屋建の主屋が続く。旧店蔵の正面には摺揚戸を残す。漆喰塗の大壁に、塗込められた出桁造の軒、影盛を施した大振りな鬼瓦など、関東の商家の特徴を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011070"},{"id":"00011071","register_sub_id":"101","register_pk":"205178","name":"長谷川家住宅文庫蔵","kana":"はせがわけじゅうたくぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市岩槻区本町三丁目2839-1他","lat":35.951343,"lng":139.696319,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"11 - 0156","desc":"敷地北西隅に東面して建つ。土蔵造二階建で、正面には下屋を付けて壁を入れ、蔵前とする。二階の正面中央には窓を開き、銅板葺の庇を付ける。外壁は白漆喰を基調としつつ、窓まわりや一階出入口の楣などの要所には黒漆喰を用いて飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011071"},{"id":"00010421","register_sub_id":"101","register_pk":"202565","name":"浜島家住宅土蔵","kana":"はまじまけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県春日部市粕壁2-6084-3","lat":35.98359,"lng":139.752109,"geo_status":"db","era":"明治前期／昭和37改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"11 － 0144","desc":"旧日光街道沿いに建つ、もと米問屋の座敷蔵。外壁を黒漆喰塗とし、桟瓦葺屋根の鬼瓦に影盛を施すなど関東地方の土蔵造の特徴を示す。南面二階窓の庇は起り付の切妻屋根で銅板葺とし、懸魚を吊る。旧粕壁宿の商家の数少ない遺構で、往事の面影を伝える大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010421"},{"id":"00003823","register_sub_id":"101","register_pk":"104813","name":"武甲酒造柳田総本店店舗","kana":"ぶこうしゅぞうやなぎだそうほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県秩父市宮側町4389","lat":36.000343,"lng":139.08432,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、金属板葺、建築面積329㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0060","desc":"秩父往還に東面して建つ。２階建，切妻造，鉄板葺，平入で，正面に桟瓦葺の下屋庇を設ける。１階正面は開放的な構えとし，２階は横長の開口部に繊細な格子戸を建て込む。全体にたちが低く，屋根勾配も緩やかで，市内で数少ない江戸期の佇まいをみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003823"},{"id":"00009585","register_sub_id":"101","register_pk":"194581","name":"藤城家住宅内蔵","kana":"ふじしろけじゅうたくうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県草加市高砂2-48-1","lat":35.82926835,"lng":139.80646254,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"11 － 0131","desc":"店舗背後に南北棟で建ち、桁行四・六メートル梁間三・六メートル、土蔵造二階建、切妻造桟瓦葺である。外壁は黒漆喰塗で軒蛇腹を廻らし、南妻面の上下階に開口部を設ける。二階の窓では丁寧に施工された掛子塗の土戸を吊り、庇を設ける。重厚なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009585"},{"id":"00009586","register_sub_id":"101","register_pk":"194582","name":"藤城家住宅外蔵","kana":"ふじしろけじゅうたくそとぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県草加市高砂2-48-1","lat":35.82925169,"lng":139.80670524,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積40㎡","structure_material":"土蔵造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"11 － 0132","desc":"敷地の東奥に東西棟で建つ。桁行七・三メートル梁間三・六メートル、土蔵造平屋建、切妻造桟瓦葺で、南正面に下屋を設ける。外壁漆喰塗で鉢巻を廻らし、一階正面に戸口を開き、二階に窓を二所穿つ。内部は一室で壁に荷摺木を並べる。屋敷景観を整える旧米蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009586"},{"id":"00009584","register_sub_id":"101","register_pk":"194580","name":"藤城家住宅店舗","kana":"ふじしろけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県草加市高砂2-48-1","lat":35.8292589,"lng":139.80637688,"geo_status":"db","era":"昭和11／平成21移築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"11 － 0130","desc":"日光街道草加宿で、街道に西面して建つ。木造二階建、切妻造桟瓦葺で、正面に下屋を設ける。正面構えは、一階はガラス戸を、二階は格子をたて、軒は太い腕木で桁を持出し、出桁造りとする。建ちが高く風格ある趣を持つ昭和初期の商家で、宿場の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009584"},{"id":"00005258","register_sub_id":"101","register_pk":"106246","name":"松本教室主屋","kana":"まつもときょうしつしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市上町1289-1","lat":35.99176952,"lng":139.07971193,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積152㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"11 － 0096","desc":"切妻造，桟瓦葺，平入の木造２階建で，正面に下屋を設ける。桁行８間の真壁造である。１，２階とも開口部が多く，軒は２階正面を出桁造とする。当初は旅館として建てられたもので，旧秩父街道に西面し，近代秩父の商業の繁栄を物語る町家建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005258"},{"id":"00004947","register_sub_id":"101","register_pk":"105937","name":"武蔵野銀行行田支店店舗","kana":"むさしのぎんこうぎょうだしてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県行田市行田4-2","lat":36.14062828,"lng":139.45896497,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積281㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2005.11.10(平成17.11.10)","register_no":"11 － 0091","desc":"忍貯金銀行として建設。鉄筋コンクリート造２階建の銀行建築で，国道に面する側に吹き抜けの営業室を配する。外壁はスクラッチタイル張とし，開口部周りやコーニスには装飾を施した「カストストン」を張る。小川組の設計施工。昭和初期地方銀行建築の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004947"},{"id":"00003832","register_sub_id":"101","register_pk":"104822","name":"安田屋","kana":"やすだや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1036","lat":35.9941848,"lng":139.08366832,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階一部3階建、鉄板葺、建築面積43㎡","structure_material":"木造2階一部3階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0069","desc":"角地に建つ木造２階建で，正面の東側と両側面の壁を高く立上げ，背面側に鉄板葺の片流れ屋根を架ける。壁面はモルタル塗で，小屋裏窓を設け３階建にみせ，上部にコーニスを廻し，窓上にアカンサスをあしらった装飾をつける。洋風意匠を摂取した店舗兼用住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003832"},{"id":"00000387","register_sub_id":"101","register_pk":"101377","name":"吉田町立歴史民俗資料館（旧武毛銀行本店）","kana":"よしだちょうりつれきしみんぞくしりょうかん（きゅうぶもうぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県秩父市下吉田3871-1","lat":36.04204902,"lng":139.03615475,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造2階建，瓦葺，建築面積148㎡","structure_material":"煉瓦造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"11 － 0005","desc":"秩父から上毛地方の顧客を対象にした銀行の本店社屋として建築されたもの。正面及び側面前面を白タイル貼りとし，寄棟造，瓦葺の屋根をかける。小規模な建物ながら全体的に質も高く，幾何学文様を主体とした意匠は，近代建築への移行を示す好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000387"},{"id":"00004507","register_sub_id":"101","register_pk":"105497","name":"赤荻本店見世蔵","kana":"あかおぎほんてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町122","lat":36.30343617,"lng":139.87439159,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0167","desc":"茶商の店舗で，街路に東面する。間口４間奥行２間半，土蔵造２階建の平入町家。寄棟造，桟瓦葺で，表に瓦葺の下屋が付く。正面１階は北端に戸袋を置き，ガラス障子を建て込む。１階は店舗，２階は８畳２室の座敷。外壁は砂摺仕上で景観に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004507"},{"id":"00004508","register_sub_id":"101","register_pk":"105498","name":"秋葉糀味噌醸造見世蔵","kana":"あきばこうじみそじょうぞうみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県結城市大字結城字浦町174-1","lat":36.30295424,"lng":139.87440421,"geo_status":"db","era":"大正13／昭和9改造","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"土蔵造及び木造2階一部平屋建、瓦葺、建築面積108㎡","structure_material":"土蔵造及び木造2階一部平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0168","desc":"味噌醸造業の店舗で，街路に東面する。土蔵造２階建で，南半が切妻造平入，北半が半切妻造妻入で，瓦葺の庇が付く。正面は昭和９年の道路拡幅で改修された。１階南半が土間の店舗，北半が居室，２階は座敷１０畳など４室を配し，背後に平屋の附属屋が続く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004508"},{"id":"00001238","register_sub_id":"101","register_pk":"102228","name":"荒川家住宅石蔵","kana":"あらかわけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県筑西市甲868","lat":36.31138169,"lng":139.98083034,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造２階建，瓦葺，建築面積83㎡","structure_material":"石造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"08 － 0011","desc":"敷地の東北端に位置する東西棟、桟瓦葺、切妻屋根の２階建石蔵。桁行５間、梁間２間半の規模で、栃木近辺でよく見かける大谷石による石蔵に似た造りになるが、東妻面の開口部は直線構成の額縁をとり、雨除けの庇と持送りを付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001238"},{"id":"00008634","register_sub_id":"101","register_pk":"149355","name":"荒川家住宅旧店蔵","kana":"あらかわけじゅうたくきゅうみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県筑西市字田町甲929-1他","lat":36.31097141,"lng":139.9809019,"geo_status":"db","era":"明治後期／昭和8年移築・平成元年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積68㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0254","desc":"通りに北面して建つ。桁行9.5ｍ梁間6.8ｍ、土蔵造を基本に東妻面に切石積を見せる。たちの高い2階建。切妻造桟瓦葺で、正面に下屋を付ける。2階は黒漆喰仕上げとし、広く開口を穿ち、鉄格子を嵌める。重厚な表構えになる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008634"},{"id":"00008633","register_sub_id":"101","register_pk":"149354","name":"荒川家住宅主屋","kana":"あらかわけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県筑西市字田町甲929-1他","lat":36.31086488,"lng":139.98084033,"geo_status":"db","era":"明治25年／昭和8年移築増築・平成元年・平成17年改修","year":1892,"year_source":"converted","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、銅板葺、建築面積131㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0253","desc":"敷地の中央に位置し、南側は庭園に望む。木造2階建、建築面積131㎡。東寄棟西切妻造の東西棟を主棟とし、東面に落棟で寄棟造を張り出す。銅板葺。1階は中廊下を基本とし、1、2階に座敷を設ける。2階座敷には上質なつくりのトコや付書院等を構える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008633"},{"id":"00008635","register_sub_id":"101","register_pk":"149356","name":"荒川家住宅土蔵","kana":"あらかわけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県筑西市字田町甲929-1他","lat":36.31075313,"lng":139.98084006,"geo_status":"db","era":"明治後期／平成元年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積67㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0255","desc":"主屋の南、庭園を挟んだ位置に建つ。東西棟の桁行9.4ｍ梁間5.6ｍ。土蔵造2階建、切妻造桟瓦葺。北面に深い下屋をかけて、出入口2ヶ所を穿ち、掛子塗の両開戸を吊る。内部は和小屋で漆喰仕上げ。重厚な外観が庭園景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008635"},{"id":"00001235","register_sub_id":"101","register_pk":"102225","name":"荒川家住宅店蔵","kana":"あらかわけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県筑西市甲868","lat":36.31118883,"lng":139.98085716,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積99㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"08 － 0008","desc":"３階建洋館の東に隣接して建つ土蔵造２階建、桟瓦葺、東西棟で平入の店舗。間口５間半、奥行３間で、正面前面に１間分の下屋を差出す。２階正面は左右の戸袋部を除いて開口とし開放性の強いつくりとする。明治期商店街の様子を伝えていることで貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001235"},{"id":"00001998","register_sub_id":"101","register_pk":"102988","name":"伊勢屋旅館主屋","kana":"いせやりょかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字下宿町193","lat":36.27698159,"lng":140.09952759,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積77㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"08 － 0048","desc":"伊勢屋は２代前まで「勢州楼」と称する料亭も営んでいた明治以来の老舗旅館。主屋は桁行５間，梁間４間，総２階建で，２階に床の間を備えた３つの客室を設ける。桟瓦葺の屋根は西側が寄棟造，東側が切妻造になり，通りの景観の際だった存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001998"},{"id":"00003368","register_sub_id":"101","register_pk":"104358","name":"市塚紀夫家住宅店舗及び主屋","kana":"いちつかのりおけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁236-1","lat":36.277954,"lng":140.097595,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積235㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0090","desc":"Ｌ字型平面で木造平屋建，屋根は桟瓦葺とする。街路に東面して建つ店舗は寄棟造，平入で，大棟に切妻造の煙出をつけ，正側面に下屋を設ける。住居は店舗西面北端から西に延び，寄棟造屋根をあげる。低平な外観は江戸時代以来の伝統を継承したと思われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003368"},{"id":"00002874","register_sub_id":"101","register_pk":"103864","name":"入江家住宅主屋","kana":"いりえけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁220","lat":36.277889,"lng":140.09938,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"08 － 0068","desc":"町中心部，御陣屋前通りの西側に位置する。桁行６間，梁間３間の規模を有する寄棟造，桟瓦葺，妻入，外装簓子下見板張の木造総２階建で，主屋南側に１間棟門，正面にむくりのついた下屋庇を設ける。２階の軒を高くとり，歴史的街路景観に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002874"},{"id":"00001402","register_sub_id":"101","register_pk":"102392","name":"潮田家住宅袖蔵","kana":"うしおだけじゅうたくそでぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁189","lat":36.277142,"lng":140.09903,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積118㎡","structure_material":"土蔵造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"08 － 0018","desc":"見世蔵の北側に接して建ち，妻面を通りに向けている。明治４５年の建築で，総２階建・切妻造・桟瓦葺，外壁を簓子下見板張とし，見世蔵１階の帳場に面して観音扉口を設ける。高さや壁面線が見世蔵と一体感を持ち，通りに面した商家の構えとして重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001402"},{"id":"00001401","register_sub_id":"101","register_pk":"102391","name":"潮田家住宅見世蔵","kana":"うしおだけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁189","lat":36.27706042,"lng":140.09899107,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積281㎡","structure_material":"土蔵造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"08 － 0017","desc":"潮田家は筑波山北に位置する真壁町のほぼ中心にあり，かつては呉服太物商を営んでいた。見世蔵は明治４３年の建築で，１階は通り側に広く帳場を構え，奥に座敷を配する。高い棟積をもつ重厚な黒漆喰塗の町家で，御陣屋前通りの角地に際だった姿をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001401"},{"id":"00003947","register_sub_id":"101","register_pk":"104937","name":"大森家住宅主屋","kana":"おおもりけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町桜井字東169-1","lat":36.28066124,"lng":140.10399222,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"08 － 0120","desc":"製糸業の家の店舗兼住居。表通りに面する２階建，寄棟造，平入の店舗の奥に平屋，寄棟造の住居部分が接続する。内部は１階前面下屋と南半を広い土間とし北半に座敷を並べ，２階は田字型に部屋を取る。階高を押さえた町屋の姿は，地域の景観上欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003947"},{"id":"00003498","register_sub_id":"101","register_pk":"104488","name":"大和田家貸店舗","kana":"おおわだけかしてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-3-24","lat":36.1899038,"lng":140.274887,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積138㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0103","desc":"市街地に位置するいわゆる看板建築。間口５間，奥行１０間半で，正面には柱頭付円柱形を３本配し，中央柱で店舗を２軒に仕切る。左端柱を上部と下部でずらし，軒下に垂木風歯形飾をあしらい，屋根に３本の煙突風の突起物を立ち上げるなど特異な造形をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003498"},{"id":"00005736","register_sub_id":"101","register_pk":"106724","name":"奥順壱の蔵","kana":"おくじゅんいちのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字大町82","lat":36.303391,"lng":139.877319,"geo_status":"db","era":null,"year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治","structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"08 － 0221","desc":"南北に長い敷地の北端に道路に面して建つ。桁行４間，梁間４間の規模で，木造２階建，切妻造，桟瓦葺とする。側面及び２階軒裏を漆喰で塗り込め，側面腰を下見板張とする。２階に８畳間の座敷を設ける。塗屋形式の店舗が通りの歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005736"},{"id":"00004501","register_sub_id":"101","register_pk":"105491","name":"奥順店舗","kana":"おくじゅんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県結城市大字結城字大町9-2、12-2","lat":36.30356044,"lng":139.87731319,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階一部平屋建、瓦葺、建築面積119㎡","structure_material":"木造2階一部平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0161","desc":"見世蔵の西に並ぶ。街路に面した桁行３間半梁間２間半を２階建とし，１階が店舗，２階が１２畳大の和室となる。屋根は切妻造，桟瓦葺で外壁は銅板張。正面１階はガラス戸，２階は肘掛窓とする。東側面と北背面に平屋を接続して居室を配し，事務所等とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004501"},{"id":"00004500","register_sub_id":"101","register_pk":"105490","name":"奥順見世蔵","kana":"おくじゅんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字大町9-2","lat":36.303516,"lng":139.877457,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0160","desc":"間口４間奥行２間半，土蔵造２階建の町家。屋根は切妻造，桟瓦葺で表に瓦庇が付く。正面１階は全面に建具を建て込み，２階窓の両端に戸袋を設ける。大工棟梁は水戸の松本惣八。１階は前面庇部と東半を土間とした古風な店構えで，２階に１２畳大の座敷をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004500"},{"id":"00007449","register_sub_id":"101","register_pk":"108431","name":"奥庄店舗兼主屋","kana":"おくしょうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県結城市大字結城字大町24他","lat":36.30390359,"lng":139.87552595,"geo_status":"db","era":"昭和10／昭和18・昭和51改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"08 － 0229","desc":"結城城下の大町通りに南面して建つ。木造２階建、切妻造桟瓦葺の平入町家で、背面直角に２階屋を付設し、正面の棟を店舗、奥を居室とする。出桁造で、１階に小庇を付け、１、２階とも正面にガラス戸をたて開放的に扱う。伝統的な商家の構えをよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007449"},{"id":"00006781","register_sub_id":"101","register_pk":"107763","name":"小倉商店店舗兼主屋","kana":"おぐらしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町116","lat":36.303711,"lng":139.87468145,"geo_status":"db","era":"明治初期／平成7改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"08 － 0227","desc":"街路に西面して建つ木造２階建の平入町家。桁行４間梁間５間で切妻造桟瓦葺とする。正面１階は近年の改修で、２階は１本溝に格子戸を建て込む。内部は南を土間、北を１列３室の床上部とし、２階に８畳２室を設ける。出桁造の軒と妻壁の梁組が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006781"},{"id":"00004110","register_sub_id":"101","register_pk":"105100","name":"亀屋商事（旧飯島家住宅）本館","kana":"かめやしょうじ（きゅういいじまけじゅうたく）ほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県古河市雷電町1-78","lat":36.19765893,"lng":139.712662,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、銅板葺一部亜鉛葺、建築面積200㎡、塔屋付","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0124","desc":"県道東野田古河線沿いに建つ。桁行６間半梁間５間半規模の木造２階建で，柱型のタイル張，縦長窓，パラペット状の軒蛇腹や玄関部の大理石円柱など洋風に仕上げる。西南隅に建ち上げた国会議事堂風の望楼は地区のシンボル的存在となっている。棟梁は谷部貞雄。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004110"},{"id":"00004112","register_sub_id":"101","register_pk":"105102","name":"亀屋商事（旧飯島家住宅）本館旧食堂及び旧浴室","kana":"かめやしょうじ（きゅういいじまけじゅうたく）ほんかんきゅうしょくどうおよびきゅうよくしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県古河市雷電町1-78","lat":36.19780945,"lng":139.71262869,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0126","desc":"主屋から北へ延びる廊下の突き当たりに位置し，東側に桁行３間半梁間３間規模，南北棟，片寄棟造の旧食堂，西側に桁行３間梁間２間規模，東西棟，寄棟造の旧浴室を配する。外装は下見板張で，旧食堂の窓にステインドグラス，旧浴室では傘状の竿縁天井を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004112"},{"id":"00004111","register_sub_id":"101","register_pk":"105101","name":"亀屋商事（旧飯島家住宅）本館土蔵","kana":"かめやしょうじ（きゅういいじまけじゅうたく）ほんかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県古河市雷電町1-78","lat":36.19776825,"lng":139.71259862,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積20㎡","structure_material":"土蔵造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0125","desc":"本館主屋北西隅の玄関部の北方に位置し，東西棟で建つ。桁行２間半梁間２間規模，切妻造，桟瓦葺，妻入の２階建土蔵で，主屋と旧食堂及び旧浴室を結ぶ廊下の西面に戸口を開け，南面２階に窓２箇所を開ける。主屋，旧浴室とともに本館西面を構成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004111"},{"id":"00001862","register_sub_id":"101","register_pk":"102852","name":"川島書店見世蔵","kana":"かわしましょてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁335","lat":36.27855886,"lng":140.099976,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0035","desc":"川島家は江戸末期より生薬店を営み，見世蔵は初代清兵衛が建てたと伝える。桁行４間・梁間２間半，正面下屋庇付の切妻造・平入の土蔵造建築。１階を店舗，２階を座敷と板の間の２室とする。真壁町の中で最も整った江戸型の見世蔵で，保存状態も良好である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001862"},{"id":"00003352","register_sub_id":"101","register_pk":"104342","name":"きそば東京庵店舗兼住宅","kana":"きそばとうきょうあんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-3-16","lat":36.18945152,"lng":140.27428472,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積185㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0074","desc":"木造２階建で，東西に細長い敷地形状に合わせて建てられ，桁行約２５ｍの規模を持つ。西側の街路に正面を向けた，入母屋造，妻入で，正面に２階軒庇と下屋庇を設ける。全体に木割の細いつくりとし，軒を吹寄垂木とするなど，軽快な数寄屋風の意匠としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003352"},{"id":"00003783","register_sub_id":"101","register_pk":"104773","name":"北岡家住宅店舗及び主屋","kana":"きたおかけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町飯塚字壱番耕地104","lat":36.27572517,"lng":140.098175,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"08 － 0119","desc":"南北の通りに東面して建つ。桁行６間梁間４間規模，寄棟造，桟瓦葺，妻入の平屋建町家で，正面に１間幅の下屋庇を差し掛ける。通りに面して店舗を設け，奥に６畳，８畳，床・書院付き８畳をＬ字型に配する。大工は近隣川原町の小原某と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003783"},{"id":"00005733","register_sub_id":"101","register_pk":"106721","name":"キヌヤ薬舗店舗","kana":"きぬややくほてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字大町9","lat":36.30347338,"lng":139.87757734,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積32㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"08 － 0220","desc":"南北に長い敷地の南端に道路に面して建つ。桁行３間半，梁間３間半の規模で，木造２階建，切妻造，桟瓦葺とする。側面及び２階軒裏を漆喰で塗り込める。１階を土間，４畳間，板の間とし，２階の４畳半２室を続き間座敷とする。小規模であるが丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005733"},{"id":"00001865","register_sub_id":"101","register_pk":"102855","name":"木村家住宅（小田部生花店）見世蔵","kana":"きむらけじゅうたく（こたべせいかてん）みせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁字高上町217-1","lat":36.277676,"lng":140.099304,"geo_status":"db","era":"嘉永6以前","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0038","desc":"木村家の見世蔵は天保８年火災後，家相図より嘉永６年までに再建されたことがわかる。御陣屋前通りの西側にあり，桁行５間・梁間２間半，正面下屋庇付の切妻造・平入の土蔵造建築。全体に建物の高さが低く，２階開口部が少ないなど，江戸末期の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001865"},{"id":"00006438","register_sub_id":"101","register_pk":"107421","name":"旧おかめ旅館本館","kana":"きゅうおかめりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県東茨城郡大洗町磯浜町2315-4他","lat":36.32081503,"lng":140.56425912,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積187㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"08 － 0226","desc":"涸沼川に北面して建つ木造２階建の旧旅館。屋根は桟瓦葺で、川に面する東西棟を入母屋造とし、寄棟造を直交して南に造る。正面に庇を設け、１階に出格子を付ける。出桁と木太い半繁垂木が深い軒を造り、重厚な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006438"},{"id":"00003776","register_sub_id":"101","register_pk":"104766","name":"旧小野瀬家住宅店舗","kana":"きゅうおのせけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県龍ケ崎市4252","lat":35.905823,"lng":140.187881,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階一部平屋建、瓦葺一部鉄板葺、建築面積210㎡","structure_material":"木造2階一部平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"08 － 0112","desc":"龍ヶ崎市街上町往還に南面して建つ。桁行５間梁間３間，切妻造，桟瓦葺の平入２階建町家で，前面に幅５尺の下屋を差し掛ける。１階店舗の１尺２寸角大黒柱や，成３尺幅１尺材などを用いて整然と組んだ根太天井，下屋部の海老虹梁など剛直な架構に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003776"},{"id":"00005732","register_sub_id":"101","register_pk":"106720","name":"旧黒川米穀店店舗","kana":"きゅうくろかわべいこくてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字西の宮町1319-2","lat":36.304119,"lng":139.878479,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積93㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"08 － 0219","desc":"敷地の南側道路に面して建つ。桁行７間，梁間４間の規模で，土蔵造２階建，切妻造，桟瓦葺，妻入とする。南半を土間とし，奥に６畳間を設け，２階は１０畳の座敷２室を並べる。一部を落ち棟とし，棟積み及び鬼瓦を大きく造り，重厚な意匠としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005732"},{"id":"00011448","register_sub_id":"101","register_pk":"210417","name":"旧大子銀行本店","kana":"きゅうだいごぎんこうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県久慈郡大子町大字大子字金町西側642-2","lat":36.771368,"lng":140.355255,"geo_status":"db","era":"大正6年／昭和48年頃改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺一部銅板葺、建築面積202㎡、塔屋付","structure_material":"木造2階一部平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"08-0299","desc":"旧街道沿いの角地に東面して建つ。木造二階建、寄棟造で、背面に平屋建が附属する。内部は金庫室、階段廻りや天井に往時の姿を良く留める。ドーム屋根の塔屋、円柱やペディメントで飾る正面出入口などが特徴的であり、地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011448"},{"id":"00011052","register_sub_id":"101","register_pk":"205159","name":"旧大徳呉服店袖蔵","kana":"きゅうだいとくごふくてんそでぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県土浦市中央一丁目914-4","lat":36.082483,"lng":140.200035,"geo_status":"db","era":"安政6／平成10改修","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0287","desc":"店蔵北棟の西に前室を介して建つ。商品の呉服を収納していたことから、かつては呉服蔵とも称された。南北両妻面の二階には両開の窓が設けられ、庇を付ける。外壁はもと黒漆喰とみられる。妻面を街路側に見せ、土浦旧城下の景観を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011052"},{"id":"00011050","register_sub_id":"101","register_pk":"205157","name":"旧大徳呉服店店蔵北棟","kana":"きゅうだいとくごふくてんみせぐらきたとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県土浦市中央一丁目914-4","lat":36.082529,"lng":140.200154,"geo_status":"db","era":"江戸末期／明治18・同44・平成10改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0285","desc":"土浦旧城下の町人地にあたり、旧水戸街道の角地に北面して建つ。土蔵造二階建、平入とする。正面を塗込める漆喰は、もと黒漆喰とみられる。天保大火後の江戸末期に建てられた町家としては二階のせいも高く、発達した姿を見せる。城下の歴史的な景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011050"},{"id":"00011051","register_sub_id":"101","register_pk":"205158","name":"旧大徳呉服店店蔵南棟","kana":"きゅうだいとくごふくてんみせぐらみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目914-4","lat":36.082442,"lng":140.200185,"geo_status":"db","era":"明治初期／平成10改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積134㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0286","desc":"街道に北面して建つ北棟の南に接して建つ。東面は土蔵風に造るが、屋根は寄棟、内部は座敷を主とした建物で、一階には八畳と六畳の続き間座敷、二階にも三室の続き間座敷を設ける。本格的な書院座敷を備えるなど、防火性能と瀟洒な内装を具備した建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011051"},{"id":"00011054","register_sub_id":"101","register_pk":"205161","name":"旧大徳呉服店向蔵","kana":"きゅうだいとくごふくてんむこうぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目914-5他","lat":36.082266,"lng":140.200239,"geo_status":"db","era":"明治前期／平成12改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0289","desc":"元蔵の南に東西棟で建つ。北に向けて出入口を開く。もとは布団や食器類などの家財道具を収納していた。小屋は登梁形式とする。東妻側の二階には窓を開いて掛子塗の戸を吊り、腕木で支える庇を付けて、土蔵造の建物が連続する街路の景観に変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011054"},{"id":"00011053","register_sub_id":"101","register_pk":"205160","name":"旧大徳呉服店元蔵","kana":"きゅうだいとくごふくてんもとぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県土浦市中央一丁目914-5他","lat":36.082331,"lng":140.200251,"geo_status":"db","era":"天保13／平成11改修","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0288","desc":"店蔵南棟の南に中庭を介して建つ。南北棟の切妻造二階建で、北正面に庇を設け、二階にも掛子塗の戸を吊る窓を開く。小屋は登梁形式とする。比較的小規模な蔵ではあるが、土浦城下では希少な、天保大火を免れた、年代の明らかな土蔵の遺構として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011053"},{"id":"00010740","register_sub_id":"101","register_pk":"201575","name":"旧田村呉服店蔵","kana":"きゅうたむらごふくてんくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県つくば市北条字日向39-1","lat":36.178144,"lng":140.09177,"geo_status":"db","era":"大正期／平成24改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積32㎡、渡屋根付","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0275","desc":"主屋後方、南北に長い敷地の中央寄りに建つ二階建の土蔵。桁行三間梁間二間半、和小屋組の南北棟、切妻造桟瓦葺で、南妻面の観音扉口には下屋庇を設ける。黒漆喰塗の外壁、北妻の押縁下見板覆い、鉢巻付の軒など丁寧な施工の商品蔵で、商家の構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010740"},{"id":"00010741","register_sub_id":"101","register_pk":"201576","name":"旧田村呉服店穀蔵及び浴室","kana":"きゅうたむらごふくてんこくぐらおよびよくしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県つくば市北条字日向39-1","lat":36.178205,"lng":140.091897,"geo_status":"db","era":"大正期／昭和前期増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造及び木造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造及び木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0276","desc":"桁行三間半の細長い平屋建の土蔵で、敷地中央東側にある。南北棟の切妻造桟瓦葺で、外壁は漆喰塗とし、内部は和小屋組を見せる。西面は扉口、南妻面に庇付の窓を設け、増築された浴室を接続する。商家の後方空間にある簡明な施設で、往時の暮らしぶりを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010741"},{"id":"00010742","register_sub_id":"101","register_pk":"201577","name":"旧田村呉服店炊事場","kana":"きゅうたむらごふくてんすいじば","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県つくば市北条字日向39-1","lat":36.178148,"lng":140.091895,"geo_status":"db","era":"大正期／昭和30頃改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0277","desc":"主屋の北東方、蔵の東に位置する。桁行五間弱、梁間一間強の南北に細長い建物で、南よりスイジバ、ヨクシツ、ベンジョの平面になる。木造平屋建、切妻造桟瓦葺、真壁造の荒壁仕上であるが、基礎切石の一部を高く積む。当初から別棟で、生活様態を伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010742"},{"id":"00010739","register_sub_id":"101","register_pk":"201574","name":"旧田村呉服店ミセ蔵兼主屋","kana":"きゅうたむらごふくてんみせぐらけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県つくば市北条字日向39-1","lat":36.17803,"lng":140.091795,"geo_status":"db","era":"大正期／昭和前期・同後期・平成24頃改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積152㎡、渡屋根付","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0274","desc":"敷地の南で道路に面する。前寄りをミセ蔵、後方を主屋とし、西側二階が当初で、東側二階は昭和前期の増築とみられる。前面一間通りを下屋とし、寄棟造妻入の二階が二棟並んだ正面外観は特異で、黒漆喰塗の重厚な外壁とともに、地域のランドマーク的存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010739"},{"id":"00010908","register_sub_id":"101","register_pk":"208879","name":"旧外池呉服店店舗","kana":"きゅうとのいけごふくてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県久慈郡大子町大字大子字金町東側624・625合併","lat":36.771508,"lng":140.355522,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積103㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"08-0281","desc":"大子町の中心部に位置する。通りに西面して建つ二階建の土蔵造店舗で、外壁を黒漆喰で塗込める。一階を店舗、二階を座敷とし、二階正面には四か所の観音開の窓を穿って、掛子塗の窓を吊って高い左官技術を見せる。重厚な外観で街路に歴史的な景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010908"},{"id":"00011056","register_sub_id":"101","register_pk":"205163","name":"旧野村さとう店袖蔵","kana":"きゅうのむらさとうてんそでぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目950・952合併","lat":36.082689,"lng":140.200072,"geo_status":"db","era":"明治前期／平成14改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0291","desc":"店舗兼主屋の東に接して、旧水戸街道に南面して建つ。南北棟の二階建土蔵で、もとは一階に商品の砂糖を、二階にはその他の物品を収納したと伝わる。土浦旧城下の町家でみられる、店舗と袖蔵を並べて街路側に妻面と平面を見せる構成で、町並みに変化をつけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011056"},{"id":"00011055","register_sub_id":"101","register_pk":"205162","name":"旧野村さとう店店舗兼主屋","kana":"きゅうのむらさとうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目950・952合併","lat":36.08269,"lng":140.199991,"geo_status":"db","era":"明治中期／平成14改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0290","desc":"土浦旧城下の町人地にあたり、旧水戸街道に南面して建つ。店舗兼主屋は総二階建で、店舗部は東西棟、主屋部は南北棟として丁字に組む。正面二階は簓子下見板張とし、軒は出桁造として陰影を付ける。重厚な構えで旧城下の景観を形づくる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011055"},{"id":"00011057","register_sub_id":"101","register_pk":"205164","name":"旧野村さとう店文庫蔵","kana":"きゅうのむらさとうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目950・952合併","lat":36.082811,"lng":140.200044,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0292","desc":"敷地北奥、袖蔵の北方に南北棟で建つ。二階建土蔵で、雛人形などの家財道具などを納めたと伝わる。南に出入口を設け、一階の出入口、二階の窓ともに黒漆喰塗の戸を吊って掛子塗とする外観が特徴。隣接する不動院参道側には漆喰壁を見せ、歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011057"},{"id":"00011058","register_sub_id":"101","register_pk":"205165","name":"旧野村さとう店煉瓦蔵","kana":"きゅうのむらさとうてんれんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県土浦市中央一丁目950・952合併","lat":36.082852,"lng":140.199965,"geo_status":"db","era":"明治中期／平成14・同24改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造平屋建、瓦葺、建築面積28㎡","structure_material":"煉瓦造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"08 - 0293","desc":"敷地北奥、店舗兼主屋の北方に南北棟で建つ。煉瓦造の蔵で建ちが高く、現在は平屋建であるが、もとは二階建であったと伝わる。煉瓦はイギリス積とし、開口上部にはアーチを用いる。土蔵造を中心とする町並みの中で、煉瓦造が異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011058"},{"id":"00001869","register_sub_id":"101","register_pk":"102859","name":"旧真壁郵便局","kana":"きゅうまかべゆうびんきょく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁297","lat":36.27818266,"lng":140.09957382,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄網コンクリート造2階建、建築面積83㎡","structure_material":"鉄網コンクリート造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0042","desc":"当初は第五十銀行（現常陽銀行）の真壁支店として建設され，中心街の角地にあり，ランドマークとして親しまれてきた。ほぼ正方形平面の総２階建で，１階右奥に金庫室が突出する。装飾的要素をほとんど用いない平滑な外観は，昭和初期の意匠の流れを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001869"},{"id":"00005235","register_sub_id":"101","register_pk":"106223","name":"栗山呉服店店舗兼住宅","kana":"くりやまごふくてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-4-25","lat":36.18901436,"lng":140.27470077,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、スレート葺、建築面積84㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"08 － 0202","desc":"水戸街道に直交する街路に北面して建つ。間口９．１ｍ，奥行９．４ｍ規模の木造２階建，平入，出桁造の商店建築。正面は広い開口部の両端に戸袋を配した対称的な外観で，妻側は押縁下見板張とする。昭和４年の大火後に形成された市街地の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005235"},{"id":"00001656","register_sub_id":"101","register_pk":"102646","name":"五木宗レンガ蔵","kana":"ごきそうれんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県常総市水海道元町3421-1","lat":36.023048,"lng":139.986603,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造3階建、建築面積18㎡","structure_material":"煉瓦造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0028","desc":"鬼怒川左岸に発達した河岸問屋のひとつである五木田宗右衛門家の３階建煉瓦造蔵で、「五木宗レンガ造りの蔵」として親しまれている。腰積、胴蛇腹、開口部廻りなどに焼過煉瓦を使用した丁寧な造りになり、内部を構造補強し資料館等として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001656"},{"id":"00004506","register_sub_id":"101","register_pk":"105496","name":"小西見世蔵","kana":"こにしみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町114","lat":36.30322528,"lng":139.87474648,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積88㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0166","desc":"もと金物店で，南を正面とする。間口６間奥行３間半の土蔵造２階建，平入の町家。切妻屋根を桟瓦葺とし，表に瓦葺庇が付く。外壁は黒漆喰塗で，正面１階に出窓，２階は額縁付の格子窓とした重厚な外観である。１階は事務所と店舗，２階は座敷と物置とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004506"},{"id":"00003379","register_sub_id":"101","register_pk":"104369","name":"小林商店米蔵","kana":"こばやししょうてんこめぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町飯塚171-2","lat":36.28015034,"lng":140.095459,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0101","desc":"木造平屋建，切妻造，平入，桟瓦葺で，東側正面に幅５尺の下屋をつける。真壁造で，正面腰と側面を簓子下見板張とし，正面中央のみ開口部とする。倉庫建築だが，土蔵造でなく町家風の形式で，北側に並び建つ店舗と，連続性のある街路景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003379"},{"id":"00003378","register_sub_id":"101","register_pk":"104368","name":"小林商店店舗","kana":"こばやししょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町飯塚171-2","lat":36.280228,"lng":140.095413,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0100","desc":"旧下館街道に面して建つ。街路側は木造平屋建，寄棟造，平入，下屋付で，背後に寄棟造，下屋付の座敷部分を延ばす。屋根はすべて桟瓦葺である。帳場とＬ字型土間からなる店構えを含め，伝統的な形式を継承し，ガラス戸や戸袋などに昭和初期の意匠が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003378"},{"id":"00003779","register_sub_id":"101","register_pk":"104769","name":"桜井家住宅店舗","kana":"さくらいけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁409","lat":36.278904,"lng":140.102631,"geo_status":"db","era":"明治初期／大正10頃増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"08 － 0115","desc":"旧町屋村の中心部に位置し，通りに南面して建つ。桁行５間梁間２間半，切妻造，桟瓦葺の平入町家で，２階は大正中期の増築。１階は東方に土間，西方に帳場を配し，正面は１階腰を石張，２階を簓子下見とし，西妻面のみ土蔵造として火災に備えたつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003779"},{"id":"00003499","register_sub_id":"101","register_pk":"104489","name":"十七屋履物店店舗兼住宅","kana":"じゅうしちやはきものてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-4-22","lat":36.188923,"lng":140.274338,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、スレート葺、建築面積135㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0104","desc":"市繁華街の中町通りに面して建ついわゆる看板建築。間口４間半，奥行１１間半で，正面右側に商品陳列棚を設ける。二階は柱頭風持送上につくった柱型を中心に縦長の連窓を左右に配し，軒下にはロンバルディア帯をあしらう。昭和初期に隆盛した商業建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003499"},{"id":"00004909","register_sub_id":"101","register_pk":"105899","name":"すがや化粧品店店舗兼住宅","kana":"すがやけしょうひんてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-5-1","lat":36.189037,"lng":140.27395376,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"08 － 0197","desc":"市繁華街の中町通りに面して建つ，間口７．２ｍ，奥行２０ｍ規模のいわゆる看板建築。正面２階には両端にコリント式，その内側にイオニア式の柱頭を意識した柱形を現し，さらにデンティル付のコーニス，三角ペディメントをあしらうなど，重厚な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004909"},{"id":"00010256","register_sub_id":"101","register_pk":"199030","name":"鈴木新平商店座敷棟","kana":"すずきしんぺいしょうてんざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町109-1","lat":36.303238,"lng":139.876061,"geo_status":"db","era":"明治16年頃","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0262","desc":"見世蔵の西側に廊下を介して東西棟で建ち、木造平屋建、切妻造スレート葺である。外壁上部は大壁漆喰塗で、北面は腰高に簓子下見板を張り、南東面は下屋を設け、開放的な縁を廻らす。内部はトコや平書院を備えた六畳と八畳仏間とする。落ち着いた佇まいの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010256"},{"id":"00010255","register_sub_id":"101","register_pk":"199029","name":"鈴木新平商店文庫蔵","kana":"すずきしんぺいしょうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町109-1","lat":36.303256,"lng":139.875954,"geo_status":"db","era":"明治16年","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0261","desc":"見世蔵の北隣に、通りに妻面を向けて建つ。土蔵造二階建、切妻造桟瓦葺で、見世蔵の店舗側の南面に戸口を開いて掛子塗の扉を吊る。外壁は黒漆喰仕上げで腰を人造石洗出しとし、水切を廻らす。見世蔵と共に重厚な構えを形成する袖蔵で、商家町の風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010255"},{"id":"00010254","register_sub_id":"101","register_pk":"199028","name":"鈴木新平商店見世蔵","kana":"すずきしんぺいしょうてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町109-1","lat":36.303199,"lng":139.875962,"geo_status":"db","era":"明治16年頃","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0260","desc":"通りに西面する建ちの高い土蔵造二階建。正面に下屋を設けて格子をたて、二階軒は出桁造で軒蛇腹をつくり黒漆喰で塗込める。一階店舗では成の高い差物を桁行に渡し、二階和室に座敷飾を備えるなど旧規をよく残す。織物が盛んな結城の往時を伝える商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010254"},{"id":"00004509","register_sub_id":"101","register_pk":"105499","name":"鈴木紡績見世蔵","kana":"すずきぼうせきみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字西の宮町1355","lat":36.30460869,"lng":139.87555072,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積98㎡","structure_material":"土蔵造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0169","desc":"もと雑穀商の店舗で，街路に北面する。間口５間半奥行３間半の土蔵造平屋建。棟札から「大工棟梁中村榮次郎」が判明。瓦葺屋根は西端が寄棟造，東端が切妻造で、東側の落棟を寄棟造として外観を整える。土間の一部に床を張る他は旧状をよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004509"},{"id":"00010094","register_sub_id":"101","register_pk":"197927","name":"駿河屋宮田書店店舗兼主屋","kana":"するがやみやたしょてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県常陸太田市内堀町字内堀西2357","lat":36.542725,"lng":140.522618,"geo_status":"db","era":"文化7／昭和20頃改修","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積221㎡、門付","structure_material":"土蔵造平屋一部2階建","registered":"2014.10.07(平成26.10.07)","register_no":"08 － 0257","desc":"鯨ヶ丘の台地上に位置する街道に東面する、土蔵造の町家。前面につし二階のミセを建て、背後に、並行した棟の座敷部を建てて接続し、つしの格子窓に土戸と明障子をたてるなど、地方的特色を示す。正面南側には門を設け、商家としての佇まいを良好に残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010094"},{"id":"00010095","register_sub_id":"101","register_pk":"197928","name":"駿河屋宮田書店土蔵","kana":"するがやみやたしょてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県常陸太田市内堀町字内堀西2357","lat":36.54260888,"lng":140.52234579,"geo_status":"db","era":"明治41頃／平成24改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積69㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"08 － 0258","desc":"敷地南西隅に位置し、南北棟で建つ。土蔵造二階建で、東に下屋を設ける。基礎に江戸切仕上の花崗岩を二段積み、柱を三尺毎に立てて壁を塗る。東正面一階は黒漆喰で仕上げ、中央の開口部には、黒漆喰塗の鳥居枠を表す。当地における商家の屋敷構えを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010095"},{"id":"00010910","register_sub_id":"101","register_pk":"208881","name":"大子カフェ店舗兼主屋","kana":"だいごかふぇてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県久慈郡大子町大字大子字本町南側689","lat":36.771338,"lng":140.353865,"geo_status":"db","era":"大正5／平成25改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺、建築面積90㎡","structure_material":"木造2階一部平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"08-0283","desc":"市街地の北に走る通りに北面して角地に建つ。北半の東西棟切妻造二階建部分を店舗、南半の南北棟寄棟造平屋建部分を住居としていた。店舗部東妻側の二階にはガラス戸を入れて高欄を付け、小屋梁を意匠的に見せており、通りの景観を彩る町家となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010910"},{"id":"00010911","register_sub_id":"101","register_pk":"208882","name":"大子カフェ土蔵","kana":"だいごかふぇどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県久慈郡大子町大字大子字本町南側687-2","lat":36.771363,"lng":140.353792,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"08-0284","desc":"店舗兼主屋の西隣に南北棟で建つ二階建土蔵。もとは隣家の金物店の土蔵であったため、西に開口を設けて出入口としている。妻側の北面には二段の水切を入れ、腰には海鼠壁を貼って装飾する。白漆喰を基調としつつ、扉や開口枠などに効果的に黒漆喰を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010911"},{"id":"00002875","register_sub_id":"101","register_pk":"103865","name":"高久家住宅店舗","kana":"たかくけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁191","lat":36.277016,"lng":140.099152,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積131㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"08 － 0069","desc":"町中心部，御陣屋前通りと下宿通りの交差点北東角に建つ。桁行６間，梁間３間半規模の，寄棟造，平入，桟瓦葺の２階建で，外装をモルタル塗とし，２間おきに柱を立てた正面に，一間幅の下屋庇を付ける。改造はあるものの，外観や座敷などに往時の面影を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002875"},{"id":"00003354","register_sub_id":"101","register_pk":"104344","name":"丁子屋店舗兼住宅","kana":"ちょうじやてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県石岡市国府3-5-6","lat":36.18847528,"lng":140.27394583,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積119㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0076","desc":"東面を通りに向けて建つ妻入の商家。木造２階建で，１階は正面が店構えで側面に玄関を備え，２階はつし２階風になる。桟瓦葺屋根は正面寄棟造，背面切妻造で，正面に下屋庇をつける。巧みな軒廻りや，重厚な漆喰塗の外壁は，町並景観の際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003354"},{"id":"00004321","register_sub_id":"101","register_pk":"105311","name":"塚本家住宅見世蔵","kana":"つかもとけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁60","lat":36.27655955,"lng":140.1012048,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0151","desc":"敷地南端接道部分の西側に建つ。桁行５間半梁間２間の規模を有する木造平屋建で，切妻造，桟瓦葺，平入とし，棟を東西に置く。内部は土間，板の間，帳場に分かれ，南面に下屋を張出し，北面は主屋と接続する。土蔵等とともに商家の往時の佇まいを良く伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004321"},{"id":"00001997","register_sub_id":"101","register_pk":"102987","name":"塚本茶舗脇蔵","kana":"つかもとちゃほわきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁213-1","lat":36.27732616,"lng":140.09928172,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"08 － 0047","desc":"塚本家は昭和初期に飯塚家より当地を得，塩の卸商を始め，戦後に茶舗を開業した。切妻造・桟瓦葺の脇蔵はもと飯塚家の文庫蔵で，桁行３間半，梁間２間の総２階建。妻面出入口や２階窓に用いた観音扉や，良材を用いた軸組など，全体に丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001997"},{"id":"00004511","register_sub_id":"101","register_pk":"105501","name":"中澤商店見世蔵及び主屋","kana":"なかざわしょうてんみせぐらおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字穀町1538","lat":36.30578614,"lng":139.8745999,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造及び土蔵造2階一部平屋建、瓦葺、建築面積114㎡","structure_material":"木造及び土蔵造2階一部平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0171","desc":"見世蔵は間口４間奥行２間半の土蔵造２階建で街路に西面する。切妻屋根を桟瓦葺とし，瓦葺庇が付く。２階南面窓は出桁庇と高欄で飾る。１階店舗の土間まわりや土間境の揚げ戸，２階の１４畳蔵座敷等，当初形態をよく残す。東背後には平屋建の居室が接続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004511"},{"id":"00003372","register_sub_id":"101","register_pk":"104362","name":"中村家住宅見世蔵","kana":"なかむらけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁字新宿町433","lat":36.27969869,"lng":140.10076821,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0094","desc":"敷地が接する南側の街路に平行して建つ。南面する木造２階建，切妻造，平入，桟瓦葺である。正面は下屋庇を設け，西端に戸袋を設けただけの開放的な構えとし，２階は観音扉付の窓をつけ，漆喰塗の外壁を簓子下見板張で覆う。端正な外観で，保存状態も良好。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003372"},{"id":"00004114","register_sub_id":"101","register_pk":"105104","name":"西岡家住宅店舗","kana":"にしおかけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字上宿町56-1","lat":36.27722748,"lng":140.10260476,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、鉄板葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0128","desc":"通りから東方に奥まって位置し，西面して建つ。桁行５間梁間３間半の平屋建で，南側桁行３間分を土間とし，北側には１０畳の帳場を設けるとともに，表半間通りは土間とする。外観は改造が大きいが，内部の土間と帳場は往時の醸造業店舗の佇まいをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004114"},{"id":"00002207","register_sub_id":"101","register_pk":"103197","name":"西岡本店米蔵","kana":"にしおかほんてんこめぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町田6-1","lat":36.273594,"lng":140.095535,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積126㎡","structure_material":"土蔵造平屋一部2階建","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0055","desc":"脇蔵の南方に位置する玄米蔵で敷地の東南隅を占める。南北棟，切妻造，桟瓦葺の平屋建土蔵で，規模は桁行８間，梁行３間とし，南側の桁行２間を中２階に造り，西側前面の１間半通りに下屋を架けて蔵前とする。脇蔵とともに造り酒屋らしい街角景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002207"},{"id":"00002205","register_sub_id":"101","register_pk":"103195","name":"西岡本店店舗","kana":"にしおかほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町田6-1","lat":36.273869,"lng":140.095627,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階一部平屋建、瓦葺、建築面積189㎡","structure_material":"木造2階一部平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0053","desc":"銘酒「花の井」で知られる西岡酒造の店舗で，もと清水屋酒造の主屋。桁行７間，梁行５間半規模，桟瓦葺，切妻造の２階建で，東側半間通りを下屋とし，南に平屋建の店舗部を張り出す。改造はあるものの，外観や土間，杜氏用の座敷などに創建時の面影を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002205"},{"id":"00002206","register_sub_id":"101","register_pk":"103196","name":"西岡本店脇蔵","kana":"にしおかほんてんわきぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町田6-1","lat":36.273712,"lng":140.095566,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0054","desc":"店舗の南方に位置し，店舗とは棟の方向を直交させて建つ。桁行５間，梁行３間規模，切妻造，桟瓦葺の平入総２階建土蔵で，戸口は北面に設ける。白米蔵として用いられており，窓の少ない閉鎖的なつくりとする。東側通り沿い家並みの景観形成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002206"},{"id":"00002752","register_sub_id":"101","register_pk":"103742","name":"橋本旅館主屋","kana":"はしもとりょかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁字新宿町410-1","lat":36.279083,"lng":140.102325,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積236㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"08 － 0066","desc":"真壁町の市街地北にあり，記録から建設年代が判明する。角地に建つ主屋は南が正面で，２階はＬ字型平面になり，屋根も正面入母屋造で西側部で後方に大棟が延びる。正面は中央玄関の庇や開放的な２階開口部の扱い及び手摺などに旅館建築の特徴が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002752"},{"id":"00002753","register_sub_id":"101","register_pk":"103743","name":"橋本旅館土蔵","kana":"はしもとりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字新宿町410-1","lat":36.27924476,"lng":140.1024098,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"08 － 0067","desc":"主屋の北西後方に連続して建つ。桁行３間，梁間２間，切妻造・桟瓦葺，平入で，１階戸口は主屋に面した南面に設ける。外壁は白漆喰塗であるが，鉢巻から下を簓子下見板張で覆っている。小規模だがつくりは丁寧で，街路景観の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002753"},{"id":"00004202","register_sub_id":"101","register_pk":"105192","name":"久松商店店舗兼住宅","kana":"ひさまつしょうてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-4-21","lat":36.18882086,"lng":140.2743158,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積136㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"08 － 0135","desc":"中町通りに西面して建つ。正面４間奥行４間規模の店舗の奥に，床付き１０畳座敷，通り土間などを配し，店舗２階に客間を設ける。昭和４年大火後の復興看板建築で，正面両脇柱型は筋面タイル芋目地張，上部蛇腹等はモルタル塗で，壁面はもと銅板張と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004202"},{"id":"00004117","register_sub_id":"101","register_pk":"105107","name":"平井家住宅店舗及び主屋","kana":"ひらいけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁264","lat":36.27902914,"lng":140.09697786,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0131","desc":"Ｔ字路の西南角地に位置し，北面して建つ。店舗は桁行４間半梁間２間，東西棟，切妻造，桟瓦葺の木造２階建で，前面に約５尺の下屋庇を付け，奥に６畳と床付き８畳から成る角屋状の主屋を張り出す。隣家沿いの西面を土蔵風に仕上げているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004117"},{"id":"00004118","register_sub_id":"101","register_pk":"105108","name":"平井家住宅土蔵","kana":"ひらいけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁264","lat":36.27878762,"lng":140.09687872,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0132","desc":"主屋東南隅から道路に沿って南に延びる通り庭及び長屋門に続いて南北棟で建つ。桁行４間梁間２間規模，切妻造，桟瓦葺の平入２階建土蔵で，西面に戸口を設け，１階を土間床，南側半分に２階床を張る。棟木に「明治廿六年第六月 棟梁柴初五郎」と記す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004118"},{"id":"00004201","register_sub_id":"101","register_pk":"105191","name":"平松理容店店舗兼住宅","kana":"ひらまつりようてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市府中2-7-20","lat":36.190277,"lng":140.272919,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積84㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"08 － 0134","desc":"市街中心地の中町通りから西に入った通りに北面して建つ。昭和４年大火の罹災を免れた建造物のひとつ。正面２間半奥行２間半の理容室の奥に和室３室などを１列に配する。正面を擬石で洋風に仕上げた看板建築で，改造はあるが内外とも往時の様子をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004201"},{"id":"00003353","register_sub_id":"101","register_pk":"104343","name":"福島屋砂糖店店舗兼住宅","kana":"ふくしまやさとうてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府3-4-20","lat":36.18874,"lng":140.274338,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積146㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0075","desc":"通りに面して建つ商家建築。桟瓦葺，切妻造，平入の２階建で，正面に下屋庇を設ける。棟瓦を高く積んだ大棟，出桁で３段蛇腹とした２階軒，黒塗の外壁が重厚な外観をつくっている。外壁は通常の土壁漆喰塗でなく，コンクリートを用いている点が珍しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003353"},{"id":"00004203","register_sub_id":"101","register_pk":"105193","name":"府中誉主屋","kana":"ふちゅうほまれしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.1856389,"lng":140.27492659,"geo_status":"db","era":"明治2","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造一部土蔵造2階建、瓦葺、建築面積208㎡","structure_material":"木造一部土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"08 － 0136","desc":"南北に長い敷地の北寄りに建つ。１階は桁行７間梁行７間半の規模で，東面してミセ及び帳場等を配し，西側に座敷等を並べる。２階は北を切妻，南を寄棟とした桟瓦葺で，１階２階とも街路に面した北面廻りを塗込めて防火的なつくりとしているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004203"},{"id":"00002877","register_sub_id":"101","register_pk":"103867","name":"星野家住宅店舗及び主屋","kana":"ほしのけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁288","lat":36.278709,"lng":140.098297,"geo_status":"db","era":"明治中期／昭和初期改造","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階及び平屋建、瓦葺、建築面積109㎡","structure_material":"木造2階及び平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"08 － 0071","desc":"町中心部，高上町通り北側に南面して建つ。桁行４間半，梁間３間規模の書院造風の主屋と，桁行４間，梁間３間半の切妻造，平入店舗から成り，店舗は２階部分を真壁造とし，正面全面に下屋庇を設ける。ショーウィンドーが昭和初期商家の店構えをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002877"},{"id":"00003502","register_sub_id":"101","register_pk":"104492","name":"増渕家住宅店舗","kana":"ますぶちけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁396","lat":36.27862666,"lng":140.1023948,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0107","desc":"旧古城村の西端に位置し，通りに西面して建つ。桁行４間半，梁間２間半の規模で，前面に約４尺の下屋庇を設ける。切妻造，桟瓦葺で，妻面の外装を簓子下見板張とする。出桁端を破風飾りで隠し二階戸袋に良質な欅材を用いるなど，街路景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003502"},{"id":"00003359","register_sub_id":"101","register_pk":"104349","name":"宮本家住宅店蔵","kana":"みやもとけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県つくば市北条188","lat":36.17764766,"lng":140.09315255,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積77㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0081","desc":"北側の街路に面して建つ土蔵造の商家建築で，保存状態が良好。木造２階建，切妻造，平入で，北と西に下屋を設け，東には蔵を附属し，屋根は桟瓦葺とする。東面は簓子下見板張だが，他は軒裏まで丁寧な漆喰塗とし，正面２階の窓の観音扉など，重厚感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003359"},{"id":"00001863","register_sub_id":"101","register_pk":"102853","name":"三輪家住宅見世蔵","kana":"みわけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁229","lat":36.278305,"lng":140.098633,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0036","desc":"三輪家は真壁町の中心，高上町通南側に位置する。北面して建つ見世蔵は，桁行３間・梁間２間，正面下屋庇付の切妻造・平入の土蔵造建築。白漆喰壁や高い箱棟など重厚であるが，正面は１・２階とも片側に戸袋を設けて，開放的な近代の商家のつくりをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001863"},{"id":"00009574","register_sub_id":"101","register_pk":"194570","name":"武蔵屋店舗","kana":"むさしやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県古河市横山町1-5535-2","lat":36.19731836,"lng":139.70469457,"geo_status":"db","era":"明治中期／平成23改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積72㎡、門付","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"08 － 0256","desc":"旧日光街道古河宿に西面して建つ。土蔵造二階建、寄棟造桟瓦葺で、正面を下屋とする。外壁黒塗で軒まで塗込め、腰を石貼とする。二階前面に開放的な縁側を通し、手摺を設け、戸袋を銅板張とする。堅牢かつ重厚な外観をもつ料理屋建築で、宿場の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009574"},{"id":"00004325","register_sub_id":"101","register_pk":"105315","name":"村井醸造店舗","kana":"むらいじょうぞうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁72","lat":36.276459,"lng":140.100128,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積231㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0155","desc":"上宿通りより入る門の正面に構える大規模な土蔵造店舗。桁行９間梁間６間（西半分は８間），切妻造，桟瓦葺，２階建で，東西棟の東半分を落屋根とする。外壁は白漆喰で仕上げ，腰まで簓子下見板張とする。旧市街に残る造り酒屋の中心的な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004325"},{"id":"00004696","register_sub_id":"101","register_pk":"105686","name":"村上家住宅主屋","kana":"むらかみけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字高上町232","lat":36.27824,"lng":140.097977,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積135㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0181","desc":"町中心部の高上町に位置し，南北の通りに西面する敷地の西北部に建つ。桁行６間梁間２間半，南北棟，切妻造，桟瓦葺，平入の平屋建で，前面に下屋を付けた店舗の東奥に東西棟，寄棟造で８畳２室の座敷棟が続き，東南方に東西棟，寄棟造の台所棟を突出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004696"},{"id":"00003497","register_sub_id":"101","register_pk":"104487","name":"森戸文四郎商店店舗兼住宅","kana":"もりとぶんしろうしょうてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府三丁目695-1","lat":36.18956552,"lng":140.27397107,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積153㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0102","desc":"市繁華街の中町通りに面して建つ。間口４間，奥行１５間で，正面をモルタル塗とする。一階に広く開口部をとり，二階部分の中央３柱型間にレリーフと縦長窓を配し，隅部の柱形には褐色タイルを張る。全体でアールデコ調の外観を呈するいわゆる看板建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003497"},{"id":"00004709","register_sub_id":"101","register_pk":"105699","name":"谷口家住宅石蔵","kana":"やぐちけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町桜井172","lat":36.28114552,"lng":140.10414028,"geo_status":"db","era":"大正初期／大正後期増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造一部煉瓦造平屋建、瓦葺、建築面積72㎡","structure_material":"石造一部煉瓦造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0194","desc":"店舗の通りを隔てた向かいの敷地に位置する。桁行６間梁間３間規模，南北棟，寄棟造，桟瓦葺の石造もと２階建で，西面に煉瓦造の旧繭乾燥室を添わす。石蔵の石材は花崗岩で，一つ一つの石に面を取り，軒蛇腹や胴蛇腹に刳型を施すなど精緻なつくりで際立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004709"},{"id":"00004710","register_sub_id":"101","register_pk":"105700","name":"谷口家住宅奥蔵","kana":"やぐちけじゅうたくおくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井172","lat":36.281071,"lng":140.10391531,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積83㎡","structure_material":"土蔵造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0195","desc":"通りの西側の敷地に位置し，石蔵の西南方に南北棟で建つ。桁行６間半梁間３間規模，切妻造，桟瓦葺の平屋建土蔵で，東面北寄りに土庇を差し掛け観音開きの防火扉を備えた戸口を設ける。北妻面に１箇所，南妻面に２箇所，西面に３箇所と窓が多いのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004710"},{"id":"00001553","register_sub_id":"101","register_pk":"102543","name":"谷口家住宅北袖蔵","kana":"やぐちけじゅうたくきたそでぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町桜井373","lat":36.28109,"lng":140.10434,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0025","desc":"江戸初期から続く谷口家は名主もつとめた旧家で，江戸末期には絞油業・醤油醸造業を営んでいた。店舗北側の北袖蔵は，江戸末期の建築と考えられる。東西棟の切妻造・桟瓦葺で，１階店舗側，２階道側に設けた観音扉，高い瓦棟積など，重厚なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001553"},{"id":"00004711","register_sub_id":"101","register_pk":"105701","name":"谷口家住宅穀蔵","kana":"やぐちけじゅうたくこくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井172","lat":36.28101079,"lng":140.10405476,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積66㎡","structure_material":"土蔵造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0196","desc":"奥蔵の東方に位置し，南北棟で建つ。桁行６間梁間３間，切妻造，桟瓦葺のたちの高い平屋建土蔵で，通り側の東面北寄りに奥行１間の下屋を架け，観音開きの防火戸を吊りこんだ戸口を設ける。窓は南北妻面の高い位置に開けられ，ともに観音開きの防火扉を吊る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004711"},{"id":"00001552","register_sub_id":"101","register_pk":"102542","name":"谷口家住宅店舗","kana":"やぐちけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井373","lat":36.28101758,"lng":140.10436898,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0024","desc":"明治期に製糸業を営んだ谷口家は，県内有数の製糸所となった。店舗は棟札より，明治３３年の建築とわかり，棟梁は地元の増渕市太郎。旧道に西面して建つ寄棟造・妻入の形式で，１階のＬ字型土間に商家の店構えがみられ，後面は江戸末期の主屋と接続している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001552"},{"id":"00001554","register_sub_id":"101","register_pk":"102544","name":"谷口家住宅南袖蔵","kana":"やぐちけじゅうたくみなみそでぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井373","lat":36.28090736,"lng":140.10428309,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0026","desc":"店舗南側に少し離れて建つ南袖蔵は，店舗建立後，遅れて建設されたと伝える。形式は北袖蔵と同じで，東西棟の切妻造・桟瓦葺，軒に鉢巻を廻し，外壁が簓子下見板張。観音扉や高い瓦棟積なども共通するが，規模はひとまわり大きく，保存状態も良好。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001554"},{"id":"00001555","register_sub_id":"101","register_pk":"102545","name":"谷口家住宅門","kana":"やぐちけじゅうたくもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井373","lat":36.2809744,"lng":140.10433693,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"薬医門、瓦葺、間口2.7m","structure_material":"薬医門","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0027","desc":"桁行１間梁間１間の薬医門で，内開き板戸をつけ，両側に通用門を設ける。店舗と南袖蔵を繋ぐ位置に建ち，建設年代は南袖蔵と同じ頃とみられる。切妻造・桟瓦葺の大屋根は棟積や降棟を凝った意匠として，屋敷の正門に相応しい格式をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001555"},{"id":"00004705","register_sub_id":"101","register_pk":"105695","name":"谷口義衛家住宅長屋門及び主屋","kana":"やぐちよしえけじゅうたくながやもんおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井1","lat":36.28040548,"lng":140.10376239,"geo_status":"db","era":"明治初期／明治25頃移築増改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0190","desc":"近隣の旧雨引村から移築した長屋門の門口右手に下屋庇を付けて店舗風に改造し，その背後に居住部を増築。長屋門は，桁行１０間５尺梁行２間半規模，寄棟造，桟瓦葺の平屋建で，正面左側桁行２間半分を物置とする。門口の軒を３段の出桁造とするのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004705"},{"id":"00010737","register_sub_id":"101","register_pk":"201572","name":"祐月本店雛蔵","kana":"ゆうげつほんてんひなぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県水戸市末広町二丁目2282-1","lat":36.38972,"lng":140.454966,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0272","desc":"南北棟の二階建土蔵で切妻造桟瓦葺。大谷石布積の基礎に黒漆喰塗の外壁を立上げ、小屋は和小屋組とし、軒に鉢巻を廻す。東面と主屋側の南妻面は一階に扉口を開け、二階に持送り付の小庇をもつ窓を設ける。桁行六間と規模が大きく、重厚かつ丁寧な施工の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010737"},{"id":"00004504","register_sub_id":"101","register_pk":"105494","name":"結真紬見世蔵","kana":"ゆうしんつむぎみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字大町68-1","lat":36.30383866,"lng":139.87499993,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0164","desc":"もと呉服店で街路に北面する。間口４間半奥行３間，土蔵造２階建の平入町家。切妻屋根を桟瓦葺とし，正面に瓦庇が付く。外壁は黒漆喰塗である。正面１階は両脇半間が壁で、ガラス戸を建て込み，２階は格子窓とする。市街に遺る貴重な見世蔵のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004504"},{"id":"00002363","register_sub_id":"101","register_pk":"103353","name":"芥川荘","kana":"あくたがわそう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県長生郡一宮町一宮字林下9240-1","lat":35.38116777,"lng":140.38554778,"geo_status":"db","era":"明治30代","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、茅葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"12 － 0039","desc":"避暑地として開発された海岸地区に建つ。平屋建，寄棟造，茅葺で，主室，次の間２室の３方に縁を回らし，縁の一端に洗面所を付す。当地方の伝統的な民家建築の技法になり，周囲の松林と相俟って良好な景観をなす。芥川龍之介が滞在したことでこの名がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002363"},{"id":"00001246","register_sub_id":"101","register_pk":"102236","name":"熱海輪店（旧千葉銀行大網支店）","kana":"あたみりんてん（きゅうちばぎんこうおおあみしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県山武郡大網白里町大網686-1","lat":35.52538448,"lng":140.32126369,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造２階建，瓦葺，建築面積48㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"12 － 0027","desc":"木造２階建の銀行建築。近年の改装で、モルタル塗石目地仕上げがタイル貼りに変ったが、大正期銀行建築の骨格は旧状を留める。パラペット中央にスクロールを従え、中心に紋章飾りを据えた半円アーチのゲーブルを立上げてファサードに見せ所をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001246"},{"id":"00001170","register_sub_id":"101","register_pk":"102160","name":"新井時計店","kana":"あらいとけいてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県匝瑳市八日市場イ2450","lat":35.701805,"lng":140.549469,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造２階建，瓦葺，建築面積42㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0012","desc":"東金と銚子を結ぶ街道沿い、八日市場本町通り商店街の東寄りに南面して建つ。木造２階建、切妻妻入、モルタル塗の看板建築で、妻面を洋風ペジメントに仕上げ、軒蛇腹下に沿ってネオンサインを掲げる。昭和初期の商店街の面影を伝える遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001170"},{"id":"00007615","register_sub_id":"101","register_pk":"108597","name":"伊勢幸酒店店舗兼主屋","kana":"いせこうしゅてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町久保字根古屋132","lat":35.28652514,"lng":140.24649093,"geo_status":"db","era":"明治6／大正10・昭和45改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0123","desc":"大多喜城下の商人町に所在し、通りに東面して建つ。寄棟造平入の木造２階建で、正面及び北面に下屋庇、南面に玄関を付け、背面に平屋建を突き出す。１階は店舗で間口を大きく開き、２階正面は全面に格子戸をたて込む。城下における商家の表構えをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007615"},{"id":"00007970","register_sub_id":"101","register_pk":"128803","name":"一粒丸三橋薬局店舗","kana":"いちりゅうがんみつはしやっきょくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県成田市仲町363","lat":35.78432647,"lng":140.31730224,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"12-0139","desc":"南北に長い敷地で、成田山参道に北面する。土蔵造２階建で、東西棟の切妻造桟瓦葺。間口８．７ｍの町家。正面は下屋庇を張り出し、黒漆喰仕上げ。１階を広く開放し、２階には掛子塗の両開扉を吊った窓を２ヶ所開ける。土壁で塗り込めた重厚な店蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007970"},{"id":"00007971","register_sub_id":"101","register_pk":"128804","name":"一粒丸三橋薬局土蔵","kana":"いちりゅうがんみつはしやっきょくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県成田市仲町363","lat":35.78415834,"lng":140.31742322,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"12-0140","desc":"店舗の南方に中庭を挟んで西面して建つ。桁行６．４ｍ梁間３．６ｍの土蔵造２階建、南北棟の切妻造桟瓦葺。白漆喰仕上げで、西面に庇を付け、中央に掛子塗の両開戸を吊り、２階には窓を穿つ。鬼瓦に影盛を施し、大棟を複雑な組棟とし、外観を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007971"},{"id":"00006501","register_sub_id":"101","register_pk":"107484","name":"岩井家住宅主屋（旧武蔵屋店舗）","kana":"いわいけじゅうたくしゅおく（きゅうむさしやてんぽ）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県印西市木下1645","lat":35.83975553,"lng":140.14784573,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積99㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"12 － 0089","desc":"通りに南面して、桁行５間半梁間３間、切妻造桟瓦葺２階建を建て、その北側に桁行２間半梁間５間半の切妻造桟瓦葺平屋建を直角に付ける。通り側に広く土間、２階と背面突出部に居室をとる。１階土間まわりや２階の手摺付縁などに旅籠の雰囲気を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006501"},{"id":"00001181","register_sub_id":"101","register_pk":"102171","name":"大屋旅館","kana":"おおやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁64","lat":35.28292566,"lng":140.24733,"geo_status":"db","era":"明治18頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造２階建，瓦葺，建築面積297㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0023","desc":"夷隅神社を核として形成された大多喜城下の新丁地区の、参道脇に位置する門前宿。木造２階建、南北棟、瓦葺切妻屋根、平入の宿屋で、正面２階左右の戸袋に大きく屋号を漆喰で表している。正岡子規が学生時代に泊まったことでも知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001181"},{"id":"00010924","register_sub_id":"101","register_pk":"208895","name":"小高記念館","kana":"おだかきねんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県館山市館山95-70","lat":34.986153,"lng":139.852095,"geo_status":"db","era":"大正期／昭和5頃移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、鉄板葺、建築面積64㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"12-0186","desc":"当初銀行建築として建てられたものを館山港に程近い現在地へ移築したと伝わる。木造二階建で上下窓を並べる洋風外観を持つ。北西隅を切って玄関を開く。一階はもと営業室で、洋風内装とし、二階には一〇畳の和室二間を並べる。港町の風情を彩る洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010924"},{"id":"00013231","register_sub_id":"101","register_pk":"366220","name":"川豊本店店舗","kana":"かわとよほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県成田市仲町386-1","lat":35.78340278,"lng":140.31672222,"geo_status":"db","era":"明治44年頃／大正15年増築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造3階建、金属板葺、建築面積146㎡","structure_material":"木造3階建","registered":"2020.04.03(令和2.04.03)","register_no":"12 － 0297","desc":"成田山新勝寺の参道に西面して建つ、木造三階建、入母屋造金属板葺平入の店鋪。大正期の旅館開業に際し三階を増築した。正面外観は木製建具で開放し、二、三階内部は旅館客室の床回りなどの造作が良く残る。ひと際高い建物は、門前町の景観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013231"},{"id":"00001346","register_sub_id":"101","register_pk":"102336","name":"木内家住宅旧店舗","kana":"きうちけじゅうたくきゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県香取郡多古町多古2613","lat":35.73796179,"lng":140.46582959,"geo_status":"db","era":"昭和4～6","year":1929,"year_source":"converted","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造2階建、銅板葺、建築面積45㎡","structure_material":"石造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"12 － 0033","desc":"通りに面して建つ店舗は切妻造・平入，銅板葺で，通り側に下屋庇を設け，商家の店構えらしく，開口部を多くとる。１階は大谷石積であるが，２階は和風の木造として，伝統と流行が折衷した意匠となっており，この地域の近代商家建築の展開をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001346"},{"id":"00014325","register_sub_id":"101","register_pk":"511314","name":"旧莇家住宅店舗兼主屋","kana":"きゅうあざみけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県印旛郡酒々井町酒々井字上宿1636-1","lat":35.723225,"lng":140.26562778,"geo_status":"db","era":"明治中期／同40年増築・昭和28年改修・平成30年移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積147㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"12 - 0322","desc":"佐倉街道の酒々井宿に所在する醤油や茶の商家。重厚な土蔵造の二階建で、正面格子戸の１階は土間とミセ、高欄付の２階は床構え付の広い座敷とする。角屋で背面に仏間や内向き座敷、土間の妻側に添蔵を設ける。賑わった街道の歴史的景観を伝える豪壮な店舗。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014325"},{"id":"00013047","register_sub_id":"101","register_pk":"368232","name":"旧今井家住宅座敷棟","kana":"きゅういまいけじゅうたくざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県佐倉市新町字仲町北側48-1","lat":35.71966389,"lng":140.23080556,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"12 － 0295","desc":"主屋の背面に接続し、南北棟で建つ。北側を寄棟造、南の主屋側を両下造とする。東面南寄りに玄関を設け、四室を食違に配する。六畳主室には床と違棚を設け、壁を鼠漆喰で塗り、天井も幅広の板をふんだんに使うなど上質なつくりの座敷棟である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013047"},{"id":"00013046","register_sub_id":"101","register_pk":"368231","name":"旧今井家住宅主屋","kana":"きゅういまいけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県佐倉市新町字仲町北側48-1","lat":35.71960278,"lng":140.23081111,"geo_status":"db","era":"明治中期／明治後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"12 － 0294","desc":"旧佐倉城下の町人地で新町通りに南面して建つ元呉服店。妻入で正面を寄棟造として深い下屋を付し、背面は切妻造で座敷棟に接続する。前面のミセは前土間とし、通り土間を持たず床上部から後方ので居住部に続く平面とする。佐倉の商家の佇まいを良く伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013046"},{"id":"00013048","register_sub_id":"101","register_pk":"368233","name":"旧今井家住宅土蔵","kana":"きゅういまいけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県佐倉市新町字仲町北側48-1","lat":35.71976111,"lng":140.23078333,"geo_status":"db","era":"明治25年／平成23年改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"12 － 0296","desc":"南北に長い敷地の中ほどに南北棟で建つ土蔵。妻入で、南正面に下屋を付して出入口を開ける。二階は正背面に庇付の窓を設け、土戸を両開きとする。土戸は丁寧な掛子塗仕上で、高い左官技術がうかがえる。鬼瓦には影盛を施し、地域的な特色を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013048"},{"id":"00007730","register_sub_id":"101","register_pk":"108712","name":"旧河内屋店舗及び主屋","kana":"きゅうかわちやてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県君津市久留里市場字仲町158-1他","lat":35.29535827,"lng":140.07780272,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積135㎡","structure_material":"木造平屋一部2階建","registered":"2009.08.07(平成21.08.07)","register_no":"12-0125","desc":"通りに西面して建つ。間口７．３ｍの商家で、正面に切妻造平入のミセ、後方に木造２階建を設け、その間を両下造で繋ぐ。ミセは内法の高い格天井の一室で、当初は後寄りに低い床を張った。正面は出桁造とし、下屋庇を付け、棟を高く積み、重厚な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007730"},{"id":"00011075","register_sub_id":"101","register_pk":"205182","name":"旧平井家住宅座敷棟","kana":"きゅうひらいけじゅうたくざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県佐倉市新町233-5","lat":35.719052,"lng":140.227435,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"12 - 0189","desc":"平屋建、瓦葺で、棟を東西に通し、西側は寄棟とし、東側は主屋背面に接する。ブツマ、オクノマを東西に並べ、南面と西面に縁を回す。さらに西側には、床や腰壁に大理石を用いた上便所が付属する。年代が明らかであり、商家の暮らしぶりをよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011075"},{"id":"00011074","register_sub_id":"101","register_pk":"205181","name":"旧平井家住宅店舗兼主屋","kana":"きゅうひらいけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県佐倉市新町233-5","lat":35.719056,"lng":140.227526,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積83㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"12 - 0188","desc":"商家町の角地に東面して建つ町家。南北棟の平入、切妻造桟瓦葺二階建。一階正面は開放的なミセとし、揚戸の痕跡が残っている。一階奥側のチャノマなどと、二階を居住空間とする。街道の要衝に位置し、佐倉旧城下の歴史的景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011074"},{"id":"00011076","register_sub_id":"101","register_pk":"205183","name":"旧平井家住宅脇蔵","kana":"きゅうひらいけじゅうたくわきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県佐倉市新町233-6","lat":35.718989,"lng":140.227558,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"12 - 0190","desc":"店舗兼主屋に隣接し、東面して建つ。土蔵造二階建。正面の下屋は腰を人造石研ぎ出し仕上げとし、二階部分を漆喰塗とする。土蔵内部に階段はなく、二階北側の出入り口で主屋と接続する。大八車を収めていたと伝える蔵で、商家の屋敷構成をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011076"},{"id":"00004335","register_sub_id":"101","register_pk":"105325","name":"呉服新川屋店舗","kana":"ごふくしんかわやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県流山市加6-1305","lat":35.85751955,"lng":139.89969463,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"12 － 0058","desc":"流山広小路に東面して建つ。間口４間半規模，南北棟，切妻造，桟瓦葺の平入２階建店蔵で，正面２階を黒漆喰塗，妻面は押縁下見板張とする。大工は土屋熊五郎。大正期の道路拡幅により正面下屋が削られているが，江戸川沿い物資集散地の繁栄振りを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004335"},{"id":"00001169","register_sub_id":"101","register_pk":"102159","name":"坂本総本店店舗","kana":"さかもとそうほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県匝瑳市八日市場イ2474","lat":35.70132014,"lng":140.54791366,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積40㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0011","desc":"総武本線八日市場駅の北西方、東金と銚子を結ぶ街道沿いに建つ黒漆喰塗、切妻平入、二階建の土蔵造り店舗建築。地棟下端の墨書により建設年と棟梁名（大木某）等が判明する。八日市場の往時の街道景観を偲ばせる遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001169"},{"id":"00010120","register_sub_id":"101","register_pk":"197953","name":"笹屋土蔵","kana":"ささやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県流山市流山1-155-1","lat":35.857249,"lng":139.899925,"geo_status":"db","era":"明治31／平成24改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0180","desc":"土蔵造二階建、桁行六・四メートル梁間四・五メートルの東西棟で、切妻造桟瓦葺とする。西妻に両開土戸の戸口を開く。外壁は漆喰塗で、鉢巻と腰を黒漆喰塗で引締める。小屋組は二重梁で棟木下に桁行梁を二段挿入する。旧道沿いの往時の賑わいを伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010120"},{"id":"00010121","register_sub_id":"101","register_pk":"197954","name":"清水屋本店店舗兼主屋","kana":"しみずやほんてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県流山市流山2-26","lat":35.85551,"lng":139.898141,"geo_status":"db","era":"明治中期／昭和8頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積101㎡","structure_material":"木造平屋一部2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0181","desc":"旧街道に東面する和菓子店舗で、背面北寄りに寄棟造平屋建の住居部を突出し、正面庇上にモルタル塗看板を立上げる。二階の軒は浅い出桁造とし、南面窓の腰高さに高欄がつく。店舗の土間床に建つ独立円柱は脚部を大理石塗とする。戦前の店舗建築の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010121"},{"id":"00001244","register_sub_id":"101","register_pk":"102234","name":"染織処谷屋土蔵（夢紫美術館）","kana":"そめおりどころたにやどぞう（ゆめむらさきびじゅつかん）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県香取市小見川580","lat":35.85486128,"lng":140.60749872,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造２階建，瓦葺，建築面積20㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"12 － 0025","desc":"利根川支流黒部川の舟運で栄えた小見川町の代表的商家の土蔵で、旧銚子街道に南面して建つ。南北棟、瓦葺２階建、平入で、店舗側の東面に蔵前を設け、西面は板貼とする外観上は標準的造りの土蔵であるが、洪水に備えて床高を上げるなどの工夫も見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001244"},{"id":"00001348","register_sub_id":"101","register_pk":"102338","name":"多田屋店舗","kana":"ただやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県東金市東金1136","lat":35.56159752,"lng":140.36233738,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積92㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"12 － 0030","desc":"多田屋は文化２年創業の書店で，県下で最も古い。現在の店舗は昭和初期の建築と推測され，木造モルタル塗，総２階建である。腰部は切石積であるが，溝が入った柱型や軒の持ち送りなどは石造を模したもので，全体に古典主義様式建築を意識している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001348"},{"id":"00000235","register_sub_id":"101","register_pk":"101225","name":"千葉トヨペット本社（旧勧業銀行本店）","kana":"ちばとよぺっとほんしゃ（きゅうかんぎょうぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県千葉市美浜区稲毛海岸4-5-1","lat":35.63647736,"lng":140.07788459,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建，瓦葺，建築面積1320㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"12 － 0004","desc":"木造２階建の事務所建築。当初銀行社屋として建てられ、数度の移築を経ている。唐破風をもつ中央の玄関から左右対称に展開し、全体の意匠は和風を基調としている。設計は妻木頼黄と武田五一による。国道に面して建つ特異な外観をもつ大規模な建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000235"},{"id":"00008651","register_sub_id":"101","register_pk":"149372","name":"寺田園旧店舗","kana":"てらだえんきゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県流山市流山二丁目101-1","lat":35.85536961,"lng":139.89834497,"geo_status":"db","era":"明治22年","year":1889,"year_source":"converted","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積67㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"12 － 0154","desc":"江戸川沿いの市街地の中心に位置し、通りに西面する。土蔵造2階建の前後に深い下屋を張り出し、正面7.3ｍ奥行8.5ｍの規模とする。寄棟造桟瓦葺。前寄りを広くミセとし、後方や2階に居室や台所を配する。黒漆喰仕上げになる本格的な蔵造店舗である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008651"},{"id":"00006377","register_sub_id":"101","register_pk":"107360","name":"戸邉五右衞門家住宅米蔵","kana":"とべごえもんけじゅうたくこめぐら","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県野田市中野台字川岸702-1他","lat":35.939816,"lng":139.84915684,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"12 － 0088","desc":"主屋の東南、通り沿いに位置する。桁行５間、梁間２間の寄棟造妻入桟瓦葺の平屋建である。外壁はモルタル塗。内部は桁行で２分され、入口側は米や味噌などを収蔵する蔵、背面側は養蚕部屋として使用されたという。歴史的な屋敷構えを構成する一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006377"},{"id":"00006745","register_sub_id":"101","register_pk":"107728","name":"戸邉五右衞門家住宅主屋","kana":"とべごえもんけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市中野台字川岸699-3他","lat":35.940002,"lng":139.849106,"geo_status":"db","era":"明治26頃／昭和4頃増築・24曳家","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積216㎡","structure_material":"木造平屋一部2階建","registered":"2007.10.02(平成19.10.02)","register_no":"12 － 0085","desc":"江戸川の野田上河岸にあった河岸問屋で、河川改修に伴い曳家された。桁行８間半、梁間６間の大規模な建築で、寄棟造桟瓦葺とする。増築された２階建の洋館は外壁モルタル塗で、２階に縦長窓を配した応接室を設ける。良質な遺構で、河岸の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006745"},{"id":"00006376","register_sub_id":"101","register_pk":"107359","name":"戸邉五右衞門家住宅倉庫","kana":"とべごえもんけじゅうたくそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県野田市中野台字川岸703-1","lat":35.939911,"lng":139.848907,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積103㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"12 － 0087","desc":"主屋の西南、江戸川堤防に面して建つ。桁行８間、梁間３間と規模の大きな倉庫で、寄棟造桟瓦葺とし、平側に吹抜け下屋を設ける。外壁はモルタル塗一部下見板張。内部は桁行で２分され、川側に居室、主屋側には吹抜けの広い収納スペースを設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006376"},{"id":"00006375","register_sub_id":"101","register_pk":"107358","name":"戸邉五右衞門家住宅土蔵","kana":"とべごえもんけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県野田市中野台字川岸702-1","lat":35.940083,"lng":139.848938,"geo_status":"db","era":"昭和4／昭和24曳家","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"12 － 0086","desc":"洋館の奥に建ち、洋館との間に蔵前を設ける。桁行３間、梁間２間、土蔵造の切妻造妻入桟瓦葺で、２階建とし、１階床下も物入として利用する。外壁は漆喰仕上げ。重厚ななかに、庇付の窓や太い折釘、２段に作られた水切りなどが変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006375"},{"id":"00007612","register_sub_id":"101","register_pk":"108594","name":"八鶴亭宿泊館","kana":"はっかくていしゅくはくかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県東金市東金1406-1他","lat":35.56067322,"lng":140.35903601,"geo_status":"db","era":"大正7頃／昭和54頃改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積98㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0120","desc":"新館の東側に接続する木造２階建。寄棟造桟瓦葺で、鉄板葺庇をまわす。Ｌ字型平面になり、１階の西側にホール、東側及び２階に宿泊室を配する。最も高い新館を中心に棟高や屋根形式が異なる本館と宿泊館３棟が並び建ち、八鶴湖の景観に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007612"},{"id":"00007611","register_sub_id":"101","register_pk":"108593","name":"八鶴亭新館","kana":"はっかくていしんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県東金市東金1406-1他","lat":35.56055684,"lng":140.35894342,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造3階建、瓦葺、建築面積104㎡","structure_material":"木造3階建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0119","desc":"本館の東側に接続する木造３階建。入母屋造桟瓦葺屋根を組み合わせ、湖側にも破風を見せる。２階の二十畳は黒檀の絞り丸太をトコ柱に据え、階段室には中央に矩形に網代を張り、周囲に垂木を配る天井をつくる。部屋ごとに天井意匠や銘木を違え、変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007611"},{"id":"00007614","register_sub_id":"101","register_pk":"108596","name":"八鶴亭ビリヤード棟","kana":"はっかくていびりやーどとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県東金市東金1406-1他","lat":35.56052079,"lng":140.35913639,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0122","desc":"浴室棟の東側に接続する。桁行６．４ｍ梁間６．０ｍの木造平屋建。寄棟造で赤色の桟瓦を葺く。北にビリヤード室、南側に廊下を配する。外壁はモルタル塗に目地を入れ石積を模し、角に柱型を表す。和風建築群において、石造風外壁と赤瓦が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007614"},{"id":"00007610","register_sub_id":"101","register_pk":"108592","name":"八鶴亭本館","kana":"はっかくていほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県東金市東金1406-1他","lat":35.5605136,"lng":140.35876799,"geo_status":"db","era":"昭和前期／昭和30頃・平成17改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積414㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0118","desc":"八鶴湖岸沿いの通り南に占める敷地の西北寄りに位置する。木造２階建で、入母屋造桟瓦葺屋根を組み合わせる。１階に六十畳の大広間や玄関、配膳室、２階に宿泊室が配される。各部屋は入口に差掛け屋根を付け、トコや棚に銘木を使うなど凝った意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007610"},{"id":"00007613","register_sub_id":"101","register_pk":"108595","name":"八鶴亭浴室棟","kana":"はっかくていよくしつとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県東金市東金1406-1他","lat":35.5604154,"lng":140.35910938,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺一部鉄板葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0121","desc":"敷地南辺に建ち、渡廊下により新館に接続する。木造平屋建の寄棟造桟瓦葺で、庇と渡廊下は鉄板葺。脱衣室と大浴場、ボイラー室、家族風呂などをＬ字型に配す。家族風呂は市松文様にタイルを床に貼り、内壁に三階菱や円形の開口を設けるなど装飾する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007613"},{"id":"00003392","register_sub_id":"101","register_pk":"104382","name":"廣瀬家住宅井戸上屋","kana":"ひろせけじゅうたくいどうわや","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県習志野市津田沼6-5-11","lat":35.678028,"lng":140.02158386,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、瓦葺、建築面積8.1㎡","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"12 － 0054","desc":"倉庫北端部西方に東西棟で建つ。桁行３．３５ｍ，梁間２．４３ｍ規模で，柱は内転びに建て，四周吹き放ちとし，切妻造，桟瓦葺の屋根を載せる。かっての海岸線と旧の上総街道との間に位置する雑穀問屋の屋敷構えを構成する主要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003392"},{"id":"00003391","register_sub_id":"101","register_pk":"104381","name":"廣瀬家住宅倉庫","kana":"ひろせけじゅうたくそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県習志野市津田沼6-5-11","lat":35.67797252,"lng":140.02162272,"geo_status":"db","era":"明治42／昭和10頃移築改造","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"12 － 0053","desc":"敷地の東寄り中央に南北棟で建つ。桁行５間半，梁間３間規模，切妻造，桟瓦葺で，曳家時の３尺高コンクリート土台に建ち，棟に大きな鬼瓦を載せ，西面に１間幅の下屋を差し掛ける。３尺ピッチの柱間に３本の間柱を建てる「角寄せ蔵」風のつくりに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003391"},{"id":"00006280","register_sub_id":"101","register_pk":"107264","name":"紅屋商店店舗","kana":"べにやしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県館山市長須賀1","lat":34.985184,"lng":139.865814,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0071","desc":"街路にほぼ西面して建つ。木造２階建，切妻造，桟瓦葺，平入で，正面には銅板葺の下屋を設ける。塗屋造で，外壁は人造石洗出しとし，石造風に見せる。現在は１階が店舗，２階が倉庫で，１・２階とも開口部に漆喰塗等の防火扉を設ける。震災復興期の店舗建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006280"},{"id":"00001179","register_sub_id":"101","register_pk":"102169","name":"星野家薬局調剤室","kana":"ほしのけやっきょくちょうざいしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県長生郡長南町長南2574","lat":35.3981938,"lng":140.23167255,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，瓦葺，建築面積15㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0021","desc":"店舗の北に１間分の通路を隔てて建つ２階建、瓦葺切妻屋根、平入の土蔵で、間口２間の妻を街道に向け、街道沿いの前面に２棟を繋ぐように庇を架ける。この庇は千葉県博覧図にも描かれており当初から店舗と一体的につくられたものと推測される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001179"},{"id":"00001178","register_sub_id":"101","register_pk":"102168","name":"星野家薬局店舗","kana":"ほしのけやっきょくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県長生郡長南町長南2574","lat":35.39813217,"lng":140.23171359,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，瓦葺，建築面積30㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0020","desc":"房総往還道の宿場町として栄えた長南宿の中央部に位置する商家。間口４間、奥行３間半の２階建、黒漆喰塗、瓦葺切妻屋根、妻入の土蔵造店舗で、正面サッシュ類を除いて、明治２８年の千葉県博覧図に描かれた外観とほとんど異なるところがない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001178"},{"id":"00006374","register_sub_id":"101","register_pk":"107357","name":"桝田家住宅主屋","kana":"ますだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市今上字浅間下2574-1","lat":35.936882,"lng":139.854416,"geo_status":"db","era":"明治4","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積185㎡","structure_material":"木造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"12 － 0084","desc":"西側を流れる江戸川の堤防に面して建つ。桁行９間、梁間７間の木造２階一部平屋建で、寄棟造桟瓦葺とし、背面を葺き降ろす。１階は梁間前半部が帳場や台所など商用部分、後半部が私的な部屋で、２階には舟宿の客室３室がある。江戸川の舟運の隆盛を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006374"},{"id":"00009588","register_sub_id":"101","register_pk":"194584","name":"桝田家住宅土蔵","kana":"ますだけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県野田市今上字浅現下2574-1","lat":35.93686545,"lng":139.85456825,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"12 － 0164","desc":"主屋南のオクニワの東寄りに建つ土蔵造二階建で、切妻造桟瓦葺。西面戸口にモルタル塗鉄扉を吊り、下屋で主屋と接続する。外壁はモルタル塗で石造風に目地を切り、一階南面と二階南北面に鉄板葺庇付の窓を開く。小屋は二重梁の和小屋。近代的な外壁の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009588"},{"id":"00009587","register_sub_id":"101","register_pk":"194583","name":"桝田家住宅不動尊祠","kana":"ますだけじゅうたくふどうそんほこら","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県野田市今上字浅現下2574-1","lat":35.93681072,"lng":139.85456825,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平家建、瓦葺、建築面積0.6㎡","structure_material":"木造平家建","registered":"2013.06.21(平成25.06.21)","register_no":"12 － 0163","desc":"主屋南のオクニワの南東寄りに位置し、方〇・八メートル規模、切妻造桟瓦葺。乱石積基壇上に土台を伏せ、角柱を長押二段と木鼻付頭貫で固め、組物三斗実肘木、妻飾虹梁大瓶束、一軒繁垂木とし、正面は桟唐戸両開、側背面を横板壁とする、本格的なつくりの祠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009587"},{"id":"00009590","register_sub_id":"101","register_pk":"194586","name":"桝田家住宅煉瓦塀","kana":"ますだけじゅうたくれんがべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市今上字浅現下2574-1","lat":35.93682296,"lng":139.85432297,"geo_status":"db","era":"明治後期／昭和前期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、総延長39m","structure_material":"煉瓦造","registered":"2013.06.21(平成25.06.21)","register_no":"12 － 0166","desc":"屋敷西正面から南面を囲む煉瓦塀。西面は高さ一メートル。主屋の玄関と土間の前に出入口を開き、煉瓦塀端部の縦溝は、江戸川溢水時に堰板を落込む仕掛けである。脇門から南では高さ二・七メートルで、上部に歯形装飾を施し、西寄りに鉄格子付の小窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009590"},{"id":"00009589","register_sub_id":"101","register_pk":"194585","name":"桝田家住宅脇門","kana":"ますだけじゅうたくわきもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市今上字浅現下2574-1","lat":35.93678455,"lng":139.85449687,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口1.5m、左右塀付","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"12 － 0165","desc":"主屋南のオクニワの西面に開く間口一・五メートルの薬医門で、切妻造桟瓦葺。男梁に束立てで棟木を受け、一軒疎垂木とする軽快な門で、板戸を両開に吊る。左右の塀は桟瓦葺で主屋と煉瓦塀に接続し、漆喰塗で腰を羽目板張とする。丁寧なつくりの門塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009589"},{"id":"00013353","register_sub_id":"101","register_pk":"368441","name":"丸屋","kana":"まるや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県鎌ケ谷市鎌ケ谷四丁目17他","lat":35.75663056,"lng":140.01210278,"geo_status":"db","era":"明治30年頃／昭和31年改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積133㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0303","desc":"木下街道の鎌ケ谷宿に建つ、もと旅籠の建物。桁行五間、梁間七間の木造二階建、寄棟造桟瓦葺である。明治35年に廃業した後、間取りなどの改造を受けたが、柱や差物は木太く重厚な造りで、正面入口の揚戸構や庇など、宿場の面影を伝える旅籠建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013353"},{"id":"00013354","register_sub_id":"101","register_pk":"368442","name":"丸屋離れ","kana":"まるやはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県鎌ケ谷市鎌ケ谷四丁目17他","lat":35.75661111,"lng":140.01224444,"geo_status":"db","era":"明治30年頃／昭和50年代増築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0304","desc":"旧旅籠の東に建つ離れ。桁行五間半、梁間三間、木造平屋建、寄棟造桟瓦葺で、北面を除く三方に縁を廻らし、正面東寄りに玄関を付す。八畳と一〇畳を並べ、両室に床棚を設ける。小規模ながら、良質の造作を多用する明治期の新座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013354"},{"id":"00006514","register_sub_id":"101","register_pk":"107497","name":"宮醤油店店舗","kana":"みやしょうゆてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.26191906,"lng":139.885468,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0073","desc":"県道沿いに北面して建つ。桁行５間，梁間３間規模，木造２階建で，平入の切妻造，桟瓦葺。外観正面は１階に引戸，２階に格子窓を設ける。２階軒は出桁造で，桁隠に絵様繰形を施す。また１階には揚戸が残り現在も使用。堅牢で丁寧なつくりで，重厚な外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006514"},{"id":"00006515","register_sub_id":"101","register_pk":"107498","name":"宮醤油店店蔵","kana":"みやしょうゆてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.261929,"lng":139.885437,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0074","desc":"県道沿いに位置し，店舗の西方に連続して建つ。桁行３間，梁間２間半，土蔵造２階建で，平入の切妻造，桟瓦葺。小屋組は和小屋。外壁は下見板張とし，県道側に妻を見せ，庇を設けた塗戸を両開きに開く。店舗・脇蔵とともに重厚な外観で表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006515"},{"id":"00006518","register_sub_id":"101","register_pk":"107501","name":"宮醤油店脇蔵","kana":"みやしょうゆてんわきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.26193585,"lng":139.88557276,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0075","desc":"県道沿いに位置し，店舗の東方に建つ。桁行５間，梁間２間半，土蔵造２階建で，平入の切妻造，桟瓦葺。小屋組はトラスの形式をとる。外壁は下見板張とし，県道側に妻を見せて１・２階に片開塗戸を開く。店舗・店蔵とともに重厚な外観で表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006518"},{"id":"00008650","register_sub_id":"101","register_pk":"149371","name":"ヤマニ綱島商店店舗","kana":"やまにつなしましょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県木更津市中央2-1412-1","lat":35.38372825,"lng":139.92121694,"geo_status":"db","era":"江戸末期／大正後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積100㎡","structure_material":"木造平屋一部2階建","registered":"2011.07.25(平成23.07.25)","register_no":"12 － 0153","desc":"通りに西面して建つ。切妻造桟瓦葺の大壁造の2棟を前後に並べ、正面と南側面に下屋を付け、正面に銅板葺庇を通す。正面は開放し、側面は漆喰の土蔵風に仕上げる。内部は前店蔵を店舗、中店蔵を仕事場とする。棟高の異なる蔵造が前後に並ぶ独特の外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008650"},{"id":"00003393","register_sub_id":"101","register_pk":"104383","name":"旅館松の家","kana":"りょかんまつのいえ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県勝浦市勝浦30","lat":35.14819062,"lng":140.31598217,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺一部銅板葺、建築面積415㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"12 － 0055","desc":"旧市役所通りに北面して建つ木造２階建の和風旅館。通り沿いの主体部は，桁行８間規模の入母屋造，桟瓦葺で，２階はたちが高く，木造和風旅館特有の開放的なつくりになる。正面１階中央の玄関上部に唐破風を付けて旅館建築らしさを演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003393"},{"id":"00003527","register_sub_id":"101","register_pk":"104517","name":"伊勢五蔵","kana":"いせごくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都文京区千石三丁目38-9","lat":35.7269108,"lng":139.74030214,"geo_status":"db","era":"明治前期／昭和3改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0158","desc":"主屋の北に隣接する道具蔵。２階建，土蔵造，切妻造，桟瓦葺で，通りに面した主屋精米所奥に表に妻面を見せて建つ。外壁はモルタル塗で石造風に目地を切り，軒蛇腹，腰部に水切りを付ける。立ちの高い重厚な外観は，主屋と並んで独特の商家の構えを造り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003527"},{"id":"00003526","register_sub_id":"101","register_pk":"104516","name":"伊勢五主屋","kana":"いせごしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都文京区千石三丁目38-9","lat":35.72685996,"lng":139.74036169,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積124㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0157","desc":"江戸時代から続く米屋。主体部は２階建，切妻造，桟瓦葺で，南に寄棟造の平屋部が接続する。１階は通りに面し帳場を取り，６畳，８畳，４畳半などの各室を配し，２階は表側を座敷，裏は物置とする。軒の低い佇まいや格子窓など，往時の町家の姿をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003526"},{"id":"00008263","register_sub_id":"101","register_pk":"133905","name":"伊勢屋店舗兼主屋","kana":"いせやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区日本堤1-208","lat":35.72508934,"lng":139.79708798,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積44㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"13 － 0262","desc":"土手通りに西面して店を開き、東と南も街路に面する。間口４．６ｍ奥行１０ｍの木造２階建、入母屋造妻入桟瓦葺。外壁は下見板張、軒下と妻面は漆喰仕上げとする。１階を店舗、２階を住居とする。正面のカウンターなど、往時の天麩羅屋の佇まいを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008263"},{"id":"00003530","register_sub_id":"101","register_pk":"104520","name":"今半別館北棟","kana":"いまはんべっかんきたとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都台東区浅草2-2-5","lat":35.71315638,"lng":139.79691848,"geo_status":"db","era":"昭和25頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積173㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0161","desc":"玄関棟の北東，中庭を挟んで南棟と対面して建つ。２階建，正面入母屋造，東面切妻造，桟瓦葺で，１階に厨房，配膳室，事務室，２階に大小の座敷を配する。大広間の大床と飾棚による豪華な構成，次の間天井の鳳凰彫物など，宴会場の晴れやかな空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003530"},{"id":"00003528","register_sub_id":"101","register_pk":"104518","name":"今半別館玄関棟","kana":"いまはんべっかんげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都台東区浅草2-2-5","lat":35.71311121,"lng":139.79683051,"geo_status":"db","era":"昭和25頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0159","desc":"今半別館は，今半本店の三田支店が戦後，現在地に移り別館として創業。入母屋造，桟瓦葺の玄関棟は，仲見世通り東裏手の通りから奥まって建ち，入口脇に座敷２室を配す。狭い敷地を巧みに利用し，老舗料理屋に相応しい構えを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003528"},{"id":"00003529","register_sub_id":"101","register_pk":"104519","name":"今半別館南棟","kana":"いまはんべっかんみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都台東区浅草2-2-5","lat":35.71305569,"lng":139.79690513,"geo_status":"db","era":"昭和25頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0160","desc":"玄関棟の南東に接続する。２階建，切妻造，桟瓦葺で，敷地の関係からＬ字型の平面とする。１，２階とも片廊下に沿い客室を配し，１階東端には旧風呂場も残る。室内は各室とも座敷飾りを備え，天井，建具，欄間とも，銘木をふんだんに使い職人芸の粋を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003529"},{"id":"00014458","register_sub_id":"101","register_pk":"512442","name":"今半本店北奥座敷","kana":"いまはんほんてんきたおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都台東区浅草一丁目2-5","lat":35.71160833,"lng":139.79686944,"geo_status":"db","era":"昭和31年頃／平成17年・同26年改修","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0474","desc":"仲見世通り東の街区中心に位置する料亭座敷棟。切妻造で元瓦葺。南側片廊下で四畳半大の座敷を三室並べる。東西両奥座敷の銘木趣味や用材に凝る造りと異なり、組子建具や網代天井等技法に凝る造り。すき焼き料亭に典型的な小座敷で構成する数寄屋風の座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014458"},{"id":"00014456","register_sub_id":"101","register_pk":"512440","name":"今半本店西奥座敷","kana":"いまはんほんてんにしおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都台東区浅草一丁目2-5","lat":35.71156667,"lng":139.79676111,"geo_status":"db","era":"昭和26年頃／平成26年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0472","desc":"仲見世通り東の街区中央にある料亭座敷棟。切妻造で元瓦葺。高床式で床下を収蔵庫とする。北側片廊下で床付き四畳半を三室並べ、春日・吉野・神代の部屋名とし、天井板等にそれぞれの杉材を用いる。すき焼き料亭に典型的な小座敷で構成する数寄屋風の座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014456"},{"id":"00014457","register_sub_id":"101","register_pk":"512441","name":"今半本店東奥座敷","kana":"いまはんほんてんひがしおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都台東区浅草一丁目2-5","lat":35.71156111,"lng":139.79686389,"geo_status":"db","era":"昭和26年頃／平成26年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0473","desc":"仲見世通り東街区内に位置する数寄屋風の座敷棟。切妻造で元瓦葺。北側に玄関付片廊下を配し六畳を三室並べ、松・竹・梅の部屋名とし、床柱や天井棹縁等にそれぞれの材を用いる。竹の間は床を構えず松と梅の続き間とし、すき焼き料亭の小座敷と大宴会に対応。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014457"},{"id":"00014455","register_sub_id":"101","register_pk":"512439","name":"エチソウビル","kana":"えちそうびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区本郷二丁目306-1","lat":35.70647778,"lng":139.76050556,"geo_status":"db","era":"大正後期／昭和7年頃・同61年・平成14年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"鉄筋コンクリート造3階建、建築面積236㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0471","desc":"エチソウビルは本郷通沿い角地に建つ糸物商、越惣商店の自社ビル。西側既存部を取り込み昭和初期に増築した鉄筋コンクリート造三階建塔屋付で南東隅を一段高くする。頂部のデンティルや窓上のアーチ等で飾る外観はアイストップとして街区の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014455"},{"id":"00009907","register_sub_id":"101","register_pk":"196054","name":"江戸屋店舗兼住宅","kana":"えどやてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都中央区日本橋大伝馬町1-5","lat":35.68933492,"lng":139.77807345,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積94㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0322","desc":"通りに面して建つ、木造二階建、人造石洗出し仕上げのいわゆる看板建築で、正面意匠は刷毛を表す。間口六・二メートル奥行一九・六メートルで、一階は店舗、事務所、倉庫、二階は居室及び倉庫とする。内外共に改修も少なく、建具や金庫も当初のものを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009907"},{"id":"00011272","register_sub_id":"101","register_pk":"209108","name":"青梅織物工業協同組合旧都立繊維試験場","kana":"おうめおりものこうぎょうきょうどうくみあいきゅうとりつせんいしけんじょう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市西分町三丁目123","lat":35.78822,"lng":139.266002,"geo_status":"db","era":"昭和10頃／昭和22頃移築、平成9・同18改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積236㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0370","desc":"木造平屋建、寄棟造スレート葺の洋館。当初は府立染織試験場出張所として建てられたと推測される。外壁は下見板張とし、全体を簡素な意匠でまとめる。正面玄関アーチ上部には小ぶりなペディメントを立ち上げアクセントとする。青梅の繁栄を今に伝える洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011272"},{"id":"00011271","register_sub_id":"101","register_pk":"209107","name":"青梅織物工業協同組合本館","kana":"おうめおりものこうぎょうきょうどうくみあいほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市西分町三丁目123他","lat":35.788573,"lng":139.266076,"geo_status":"db","era":"昭和15頃／昭和38増築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建、スレート葺、建築面積280㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0369","desc":"青梅市街地の中ほどに立地する。屋根を寄棟造スレート葺とする木造二階建で、南面に玄関ポーチを設け、東面北寄りに増築された応接室が突出する。一階は事務室等、二階は増築部を除いて一室の大空間とする。織物で栄えた青梅の歴史を今に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011271"},{"id":"00009908","register_sub_id":"101","register_pk":"196055","name":"大野屋總本店店舗","kana":"おおのやそうほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都中央区新富2-6-13","lat":35.67215508,"lng":139.77267322,"geo_status":"db","era":"大正13頃／昭和30頃改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積27㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0323","desc":"角地に北面して建つ。木造二階建、切妻造桟瓦葺で、重厚な甍棟を積む。一階は店舗とし、二階で足袋製造を行う。上下階とも軒が高く、二階は出桁造とする。外壁は簓子下見板張で二階窓に手摺を設ける。震災直後に建てられた、当地に残る数少ない戦前の町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009908"},{"id":"00005591","register_sub_id":"101","register_pk":"106579","name":"大橋茶寮表門","kana":"おおはしさりょうおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66286608,"lng":139.74236998,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0205","desc":"敷地東辺の中央やや北寄りに位置し，幅２．７ｍの棟門形式で，木造，切妻造，桟瓦葺とする。扉は両開きの板戸で，壁面を土壁とし，下部を横板張とする。桁や垂木などに丸太材を用い，数寄屋風とする。茶寮の質素で落ち着きのある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005591"},{"id":"00005587","register_sub_id":"101","register_pk":"106575","name":"大橋茶寮茶室葵","kana":"おおはしさりょうちゃしつあおい","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66289537,"lng":139.74216375,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0201","desc":"敷地北西の隅に建ち，敷地中央の庭を座敷から望む配置とする。木造平屋建，切妻造，桟瓦葺とする。座敷を８畳間と６畳間の続き間とし，座敷西側に水屋を設け，その周りに廊下を廻し，北側を調理場とする。床構え等，京都裏千家の茶室咄々斎を模倣する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005587"},{"id":"00005586","register_sub_id":"101","register_pk":"106574","name":"大橋茶寮茶室桂","kana":"おおはしさりょうちゃしつかつら","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66279092,"lng":139.742157,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0200","desc":"敷地南西隅に位置し，床構えなど桂離宮の意匠を模倣して建築する。桁行４間，梁間３間半の規模で，木造平屋建，切妻造，桟瓦葺とする。１２畳間の座敷を設け，北側と東側を入側とする。東面北端に庭への階段を設け，庭と一体となった空間構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005586"},{"id":"00005590","register_sub_id":"101","register_pk":"106578","name":"大橋茶寮茶室守貧庵","kana":"おおはしさりょうちゃしつしゅひんあん","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66275648,"lng":139.74230598,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0204","desc":"敷地南辺に接し，中央やや東側に建つ。木造平屋建，入母屋造，桟瓦葺とし，外壁を土壁として腰を杉皮張とする。６畳の座敷に床及び隠し仏壇を付属する。南側に廊下を設け，その東端を雪隠とし，さらに東側に腰掛待合を突出させる。質の高い茶室を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005590"},{"id":"00005589","register_sub_id":"101","register_pk":"106577","name":"大橋茶寮茶室如庵写","kana":"おおはしさりょうちゃしつじょあんうつし","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66281342,"lng":139.74234996,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0203","desc":"敷地東辺のやや南側に位置し，木造平屋建，切妻造，桟瓦葺とし，柱に丸太材を使い，外壁を土壁とする。西側にこけら葺の庇を架ける。北側に水屋を設け，その北側を茶室山吹と接続する。３畳半敷きの小規模な建物で，国宝の如庵を模倣してつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005589"},{"id":"00005588","register_sub_id":"101","register_pk":"106576","name":"大橋茶寮茶室山吹","kana":"おおはしさりょうちゃしつやまぶき","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66289949,"lng":139.74230926,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0202","desc":"敷地東辺の中央に位置し，木造平屋建，切妻造，桟瓦葺で，外壁を土壁とする。８畳間の座敷を庭に面し，その東側を水屋とする。座敷の北側に茶寮の玄関を設ける。玄関の北側に控室等を設け敷地北東隅を構成する。高度な数寄屋の技術を用いた茶室を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005588"},{"id":"00005593","register_sub_id":"101","register_pk":"106581","name":"大橋茶寮中門","kana":"おおはしさりょうちゅうもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66282793,"lng":139.74226849,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造、杉皮葺、間口1.0m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0207","desc":"敷地中央の庭に設けられた，間口１ｍの棟門形式の門である。屋根は切妻造，杉皮葺とし，竹を屋根葺材の押さえに使う。柱や桁に細い丸太を使い，柱は添え木をして立てる。各茶室を行き来する門として，数寄屋風の落ち着いた意匠を見せ，各茶室を結びつけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005593"},{"id":"00005592","register_sub_id":"101","register_pk":"106580","name":"大橋茶寮不老門","kana":"おおはしさりょうふろうもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66275504,"lng":139.74222566,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造、銅板葺、間口1.5m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0206","desc":"敷地南辺の中央やや西寄りに位置し，敷地境より少し奥まって建つ。間口１．５ｍの木造の棟門の形式で，切妻造，銅板葺の屋根を載せる。板戸２枚を内開きとし，正面に菱目に組んだ桟を付け，意匠とする。柱や桁に丸太材を用い，数寄屋風の落ち着いた意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005592"},{"id":"00005594","register_sub_id":"101","register_pk":"106582","name":"大橋茶寮塀","kana":"おおはしさりょうへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66275004,"lng":139.74238095,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造、延長53m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0208","desc":"敷地南辺，東辺，北辺の東半を囲う塀で，木造，モルタル塗とする。 建物が接する部分では建物外壁を兼ねる。大谷石の基礎の上に丸太柱を立て，正面東辺は柱を見せ，下部を横板張とし，南端間に潜戸を設ける。南面，北面は柱を塗り込め，上部に笠木を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005594"},{"id":"00013369","register_sub_id":"101","register_pk":"368456","name":"河鹿園稲荷社","kana":"かじかえんいなりしゃ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80101667,"lng":139.18418611,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造、銅板葺、面積0.36㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0447","desc":"枕流亭北の中庭に建つ一間社流造で、北西を正面とする。石積み基壇上に布基礎を廻し、土台建とする。正面に浜床、浜縁を付し、浜床上に庇柱を立て、木階五級を備える。水引虹梁上に蟇股を据え、妻飾りは虹梁大瓶束笈形付。小社ながら本格的な造りである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013369"},{"id":"00013364","register_sub_id":"101","register_pk":"368451","name":"河鹿園渓梅庵","kana":"かじかえんけいばいあん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80096667,"lng":139.18406667,"geo_status":"db","era":"昭和5年頃／昭和39年頃改修、平成元年増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、銅板葺、建築面積104㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0442","desc":"山魚楼の東、一段下に並ぶ東西棟である。北側渡廊下の高低差を利用して一、二階に別の入口を設ける。一階は藤の間六畳、桔梗の間八畳、つばきの間八畳が並ぶ。二階百合の間は八畳と六畳の続き間である。床柱や落掛けの磨き丸太が目を引く数寄屋座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013364"},{"id":"00013363","register_sub_id":"101","register_pk":"368450","name":"河鹿園山魚楼","kana":"かじかえんさんぎょろう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80098333,"lng":139.18390556,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、銅板葺、建築面積72㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0441","desc":"川に面して建つ寄棟造の東西棟。北面に庇付の吹放ち玄関を備え、東に外向きで半間の床を設ける。一階月の間は八畳二室、二階もみじの間は一〇畳二室の続き間で、南側縁には桟割の大きなガラス障子を建込む。銘木を用い、落ち着いた造作の数寄屋座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013363"},{"id":"00013366","register_sub_id":"101","register_pk":"368453","name":"河鹿園射山荘","kana":"かじかえんしゃざんそう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80113611,"lng":139.18400278,"geo_status":"db","era":"昭和5年／平成元年増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、金属板葺、建築面積203㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0444","desc":"敷地中央の北寄りに建つ入母屋造の東西棟である。南面西端に玄関を構え、一階は五一畳の大広間とする。二階は松の間八畳ほかの宿泊室で、各室に洋箪笥を造付ける。床回りに変り木などの銘木を多用し、上面を凸に造った違棚など、独創的な造作を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013366"},{"id":"00013367","register_sub_id":"101","register_pk":"368454","name":"河鹿園大浴場","kana":"かじかえんだいよくじょう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80108611,"lng":139.18421667,"geo_status":"db","era":"昭和前期／平成元年増築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0445","desc":"射山荘の東下方に建つ切妻造の南北棟で、西面に渡廊下が取り付く。南東の大浴場はタイル貼の円形浴槽をもち、南面から東面に大きなガラス窓を建て開放的に造る。北東に川原石を組上げた岩風呂、南西には木製浴槽の小浴室を設ける。多様な趣を備えた浴場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013367"},{"id":"00013362","register_sub_id":"101","register_pk":"368449","name":"河鹿園帳場兼主屋","kana":"かじかえんちょうばけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80112222,"lng":139.18378889,"geo_status":"db","era":"大正14年頃／昭和50年増築","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、金属板葺、建築面積152㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0440","desc":"ＪＲ青梅線御嶽駅の近傍、多摩川左岸の崖上にある敷地の北西の入口に建つ。東西棟で、南正面中央の土間沿いに帳場を設け、北面に厨房を配す。一階西半と二階は住居及び従業員休憩室とする。観光地の休憩所として使用した開業当初に遡る建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013362"},{"id":"00013365","register_sub_id":"101","register_pk":"368452","name":"河鹿園枕流亭","kana":"かじかえんちんりゅうてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80093889,"lng":139.18422778,"geo_status":"db","era":"昭和5年頃／昭和29年移築・増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、銅板葺、建築面積55㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0443","desc":"渓梅庵の東下方に建つ入母屋造の東西棟である。敷地内で最も低い位置で、渡廊下は二階に取付く。一階は八畳二室、二階のやまぶきの間は八畳二室の続き間で、縁は設けず川に向かって開放的な室とする。上質な客室棟で、奥多摩観光の隆盛を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013365"},{"id":"00013368","register_sub_id":"101","register_pk":"368455","name":"河鹿園渡廊下","kana":"かじかえんわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80103889,"lng":139.18414722,"geo_status":"db","era":"昭和前期／昭和29年増築、平成元年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、金属板葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0446","desc":"山魚楼北から渓梅庵北を通り、枕流亭と大浴場へ到る渡廊下。南東下がりの敷地を、階段二箇所と斜路で結ぶ。床面は黒色玉石のモルタル洗出しで、飛石状の切株を擬木で造る。腰壁は竪板張で引違窓を設ける。地形に合わせて曲折しながら巧みにまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013368"},{"id":"00008827","register_sub_id":"101","register_pk":"162270","name":"割烹美家古向島本店店舗","kana":"かっぽうみやこむこうじまほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都墨田区向島5-2-1","lat":35.71715217,"lng":139.80876753,"geo_status":"db","era":"昭和前期／昭和中期・平成9年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺一部鉄板葺、建築面積224㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"13 － 0286","desc":"通り西側に占める短冊形敷地の東寄りに位置する。中庭を5棟が囲む木造2階建で、建築面積224㎡。中庭側に廊下をめぐらし、客室などを周囲に配する。良材を多用し、各室で天井仕様などを違える。近代向島の雰囲気を伝える料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008827"},{"id":"00008826","register_sub_id":"101","register_pk":"162269","name":"神谷バー本館","kana":"かみやばーほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都台東区浅草1-16-33他","lat":35.71094424,"lng":139.7975212,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造6階地下1階建、建築面積181㎡","structure_material":"鉄筋コンクリート造6階地下1階建","registered":"2011.10.28(平成23.10.28)","register_no":"13 － 0285","desc":"西北角地に南面して建つ。鉄筋コンクリート造6階地下1階建、建築面積181㎡。正面には矩形の大きな窓と円形の高窓を穿ち、隅には付柱を飾る。3・4階を通す、三連の半円アーチ窓が外観を特徴付ける。正面性を重視した近代商業建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008826"},{"id":"00000959","register_sub_id":"101","register_pk":"101949","name":"ギャラリー・エフ蔵（株式会社淵川金属事務所）","kana":"ぎゃらりー・えふぐら（かぶしきがいしゃふちかわきんぞくじむしょ）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都台東区雷門二丁目6-1","lat":35.70990739,"lng":139.79688411,"geo_status":"db","era":"慶応4","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積20㎡","structure_material":"土蔵造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"13 － 0050","desc":"隅田川沿いに位置するもと材木問屋の蔵。二階梁下端に「慶応四戊辰年八月吉日 三代目竹屋長四郎」等の墨書銘が認められる。震災と戦災をくぐりぬけてきた下町の土蔵として貴重。現在は喫茶店併設のギャラリーとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000959"},{"id":"00012126","register_sub_id":"101","register_pk":"352925","name":"旧井阪屋本店河合ビル","kana":"きゅういさかやほんてんかわいびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区雷門二丁目3-2","lat":35.709601,"lng":139.795933,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積75㎡、塔屋付","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2018.03.27(平成30.03.27)","register_no":"13-393","desc":"浅草寺の参道に続く通りに建つ。鉄筋コンクリート造三階地下一階建で、塔屋を付ける。外観は一階正面のみ石貼とし、凹凸やレリーフを造り出し、屋上のパラペットを軒蛇腹のように張り出し、表情をつける。昭和初期の商業ビルとして貴重で地域に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012126"},{"id":"00012127","register_sub_id":"101","register_pk":"352926","name":"旧井阪屋本店河合ビル稲荷社","kana":"きゅういさかやほんてんかわいびるいなりしゃ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区雷門二丁目3-10","lat":35.709931,"lng":139.789103,"geo_status":"db","era":"昭和初期／昭和22年頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、金属板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"13-394","desc":"敷地後方に東面して建つ。一・八メートル四方の切石基壇上に基礎石を据え、桁行一メートル、梁間一メートル、切妻造平入で正面を葺下し流造のようにみせる屋根形式。正面に両開格子戸をたてるのみで装飾を控えた外観で、屋敷構えに趣を添える小社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012127"},{"id":"00008825","register_sub_id":"101","register_pk":"162268","name":"旧常盤家本館（石合家住宅主屋）","kana":"きゅうときわやほんかん（いしあいけじゅうたくしゅおく）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都新宿区神楽坂3-2-41他","lat":35.70201935,"lng":139.74056375,"geo_status":"db","era":"昭和25年／昭和29年増築","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積219㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"13 － 0284","desc":"神楽坂界隈に位置する木造2階建で、建築面積219㎡。南面中央の坪庭をコの字型に囲む3棟からなり、唐破風を載せた庇付の玄関を北棟西面に付設。銘木を多用し、客室の障壁画や浴室のステインドグラスなど豊かに装飾される。近代待合の趣を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008825"},{"id":"00007624","register_sub_id":"101","register_pk":"108606","name":"旧ほていや玩具店店舗","kana":"きゅうほていやがんぐてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都青梅市仲町303-2","lat":35.789047,"lng":139.25731131,"geo_status":"db","era":"昭和前期／昭和40改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、鉄板葺、建築面積47㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0245","desc":"青梅街道に北面する木造２階建の店舗。１階を店舗、２階を客間とする。外壁正面は銅板張、側面は鉄板張で、正面２階にバルコニーを張り出し、人造石洗出し仕上げの円柱や手すりを設け、軒まわりやパラペットに装飾を凝らす。昭和戦前における商業建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007624"},{"id":"00015295","register_sub_id":"101","register_pk":"532419","name":"旧宮脇ビル（川崎ブランドデザインビルヂング）","kana":"きゅうみやわきびる（かわさきぶらんどでざいんびるぢんぐ）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都中央区銀座一丁目207","lat":35.673075,"lng":139.77056667,"geo_status":"db","era":"昭和7年／昭和17年増築、令和5年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積45㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2025.03.13(令和7.03.13)","register_no":"13 - 0516","desc":"銀座昭和通りの角地に建つ商業ビル。間口四メートル、奥行九メートルで台形平面。西は鉄筋コンクリート造木造床で、東はラーメン構造で増築し一体化。縦長窓とタイル貼で全体を整える。関東大震災以降、銀座で隆盛した不燃化商業ビルの現存例として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015295"},{"id":"00012298","register_sub_id":"101","register_pk":"531622","name":"喜代川店舗","kana":"きよかわてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都中央区日本橋小網町10-5","lat":35.68268889,"lng":139.78082222,"geo_status":"db","era":"昭和2年頃／昭和40年代・平成25年・同27年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、銅板葺一部瓦葺、建築面積107㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"13-404","desc":"人形町近傍のオフィス街にあり、路地に東面して建つ。寄棟造の平入で正面南端に切妻屋根の玄関を付け、背面に角屋を出す。一階には厨房・客席と居室、二階に座敷五室を設ける。開発著しい都心部で良質な伝統木造建築の姿を留める希少な店舗兼住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012298"},{"id":"00015296","register_sub_id":"101","register_pk":"532420","name":"銀座大野屋店舗兼主屋","kana":"ぎんざおおのやてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都中央区銀座五丁目202-13","lat":35.66965,"lng":139.76666667,"geo_status":"db","era":"昭和26年／昭和後期・平成13年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積39㎡","structure_material":"木造平屋一部2階建","registered":"2025.03.13(令和7.03.13)","register_no":"13 - 0517","desc":"銀座の昭和通りと晴海通りの交差点に位置する足袋店。隅切りの角地形状に合わせた五角形平面に、平屋建の店舗と二階建の作業場兼住居を並べた変則的なつくり。正面にショーウインドー、内部に帳場を残す。戦災直後の銀座の景観を伝える貴重な木造商業建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015296"},{"id":"00014141","register_sub_id":"101","register_pk":"508771","name":"銀座ライオンビル","kana":"ぎんざらいおんびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都中央区銀座七丁目1","lat":35.66916111,"lng":139.76323889,"geo_status":"db","era":"昭和9年／昭和14年・同54年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造地上6階地下1階建、建築面積512㎡、塔屋付","structure_material":"鉄筋コンクリート造地上6階地下1階建","registered":"2022.02.17(令和4.02.17)","register_no":"13-0459","desc":"銀座７丁目に建つ鉄骨鉄筋コンクリート造地下１階地上６階建。外観は１階やパラペットにライト調意匠を残す。内装は６階ホールの他、１階ビヤホールが白眉でタイル張壁面に梁型等の装飾を施し、圧巻のガラスモザイク壁画を飾る。我国ビヤホールの一大傑作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014141"},{"id":"00000639","register_sub_id":"101","register_pk":"101629","name":"さかえビル","kana":"さかえびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区本郷3-38-10","lat":35.70741581,"lng":139.76286532,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上４階建，建築面積105㎡","structure_material":"鉄筋コンクリート造地下１階地上４階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0020","desc":"薬学博士を施主とする薬学研究所を兼ねた事務所ビル。角地に建ち，隅切りの面に正面性をもたせたファサード構成をとる。スクラッチタイル貼りで，要所にテラコッタの装飾を配したアール・デコ建築の佳品となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000639"},{"id":"00003198","register_sub_id":"101","register_pk":"104188","name":"進開屋","kana":"しんかいや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区千石2-30-6","lat":35.72525914,"lng":139.74155129,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積52㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0142","desc":"そば屋の店舗として建築された。１階前半土間に卓・椅子を置いて客席とし，奥を土間と板間に分け調理場とする。客席土間から上がる２階は前後に客座敷２室を配す。立ちの高い外観は１階に出格子を設け，２階は軒をせがい，窓に透かし板の高欄を付けて整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003198"},{"id":"00015414","register_sub_id":"101","register_pk":"533429","name":"新潮社倉庫","kana":"しんちょうしゃそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都新宿区矢来町71-8他","lat":35.70331111,"lng":139.73311111,"geo_status":"db","era":"昭和34年／昭和41年増築","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積471㎡、外階段及びスロープ付","structure_material":"鉄筋コンクリート造5階建","registered":"2025.08.06(令和7.08.06)","register_no":"13 - 0523","desc":"本館と並列して建つ倉庫。鉄筋コンクリート造５階建で、梁を密に配した五百万冊分の収容スペースの他、事務室、昇降機、荷捌場を備え、納品から出庫までの新刊物流拠点であった。階数が異なる本館と高さ、外観を揃え、深い庇を連続し長大な沿道景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015414"},{"id":"00015413","register_sub_id":"101","register_pk":"533428","name":"新潮社本館","kana":"しんちょうしゃほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都新宿区矢来町71-10他","lat":35.70294722,"lng":139.73304722,"geo_status":"db","era":"昭和32年／昭和41年増築、平成4年改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積791㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2025.08.06(令和7.08.06)","register_no":"13 - 0522","desc":"神楽坂に近い高台に建つ出版社の本社ビル。鉄筋コンクリート造、釉薬タイル貼の簡明かつ格調高い外観と、古今東西の人類の文字を刻む壁面レリーフなど社員が関わりデザインした内部造作が特徴。我が国有数の出版・印刷製本業集積地を代表するオフィスビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015413"},{"id":"00012300","register_sub_id":"101","register_pk":"531624","name":"新富町躍金楼店舗","kana":"しんとみちょうてっきんろうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都中央区新富一丁目11-3他","lat":35.67211667,"lng":139.77466944,"geo_status":"db","era":"昭和24年頃／昭和30年代増築、平成24年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積186㎡、塀付","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"13-406","desc":"旧花街にある店舗兼住宅で、街路に南面して建つ。切妻造妻入の両側に下屋を出し、東側面に居室が別棟で取付く。内部の改変があるが、外観は伝統木造の料亭の姿を留め、正面の僅かな空間に前庭を取って門塀を構えるなど、地域の歴史的景観を伝える希少な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012300"},{"id":"00001563","register_sub_id":"101","register_pk":"102553","name":"すぺーす小倉屋蔵","kana":"すぺーすおぐらやくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都台東区谷中七丁目207-2","lat":35.72472439,"lng":139.76890486,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積20㎡","structure_material":"土蔵造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0078","desc":"小倉屋三代目平三郎が店舗に隣接して建てた質蔵。表通りに西妻を向け，東妻を戸口とし庇が附属する。梁間が二間と狭いに関わらず三階建とする本格的な土蔵造で，近在でもひときわ高さが際だった存在である。棟札にも富士山の眺めを詠った句を記す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001563"},{"id":"00001562","register_sub_id":"101","register_pk":"102552","name":"すぺーす小倉屋店舗","kana":"すぺーすおぐらやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都台東区谷中七丁目207-2","lat":35.72465226,"lng":139.76893003,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、スレート葺、建築面積41㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0077","desc":"感応寺（後の天王寺）の門前町で享保年間から代々質屋を営んだ商家で，屋号を小倉屋という。店舗は間口三間の中二階建の町家であり，表通りからやや後退して建つ。大戸口の構えを良く残し，通り庭に面する八畳の帳場を現在ギャラリーとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001562"},{"id":"00007882","register_sub_id":"101","register_pk":"108862","name":"西郊ロッヂング","kana":"せいこうろっぢんぐ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都杉並区荻窪3-63","lat":35.70302366,"lng":139.62530608,"geo_status":"db","era":"昭和13／昭和中期・平成13改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積145㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"13-0253","desc":"本館西側に隣接して、敷地の北西角に沿うようにＬ字形に建つ。木造２階建、桟瓦一部銅板葺、建築面積１４５㎡。１３室を有する集合住宅。北西角を曲壁面とし、その上部に銅板葺ドーム屋根を載せる独特の外観は、ベージュの色調と調和し、親しみを感じさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007882"},{"id":"00002614","register_sub_id":"101","register_pk":"103604","name":"太洋ビルディング（丸石ビルディング）","kana":"たいようびるでぃんぐ（まるいしびるでぃんぐ）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区鍛冶町1-10-4","lat":35.690285,"lng":139.772751,"geo_status":"db","era":"昭和6／昭和8増築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄骨鉄筋コンクリート造6階地下1階、建築面積555㎡","structure_material":"鉄骨鉄筋コンクリート造6階地下1階","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0119","desc":"中央区との区境，旧龍閑川沿いに立地するオフィスビル。石貼の一階部分を除き，主にスクラッチタイル貼の外装とし，６階胴蛇腹と頂部のテラコッタ製蛇腹で外観に変化を与える。１階開口部のアーチ迫石や付柱の柱頭を動植物のレリーフで飾る。山下寿郎設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002614"},{"id":"00008657","register_sub_id":"101","register_pk":"149378","name":"高橋建築事務所社屋","kana":"たかはしけんちくじむしょしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都新宿区矢来町114","lat":35.70392397,"lng":139.73468167,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"converted","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"13 － 0280","desc":"早稲田通りに南面する敷地に建つ。切妻造桟瓦葺の主棟の西北に切妻屋根を突出する木造2階建。ハーフティンバー風の外観で、通り側には出窓を設ける。内部は方杖や梁など木部を現す。イギリス田舎家風の穏やかな外観が神楽坂界隈の景観に潤いを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008657"},{"id":"00002755","register_sub_id":"101","register_pk":"103745","name":"棚澤書店","kana":"たなざわしょてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都文京区本郷6-18-12","lat":35.713577,"lng":139.759064,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"13 － 0127","desc":"本郷通りを挟んだ東京大学正門前にあり，２軒長屋を用いた店舗である。東を正面とし，２階建，切妻造・桟瓦葺，平入，正面半間下屋庇付の形式で，軒は出桁造である。東大周辺に形成された近代商家の町並景観を伝える建物として欠かせない存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002755"},{"id":"00004529","register_sub_id":"101","register_pk":"105519","name":"玉置文治郎ビル","kana":"たまおきぶんじろうびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都中央区東日本橋2-16-8","lat":35.69452538,"lng":139.78556086,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積97㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2005.02.09(平成17.02.09)","register_no":"13 － 0183","desc":"靖国通り沿いに北面して建つ，鉄筋コンクリート造地上４階地下１階建の薬品問屋店舗兼住宅。震災復興商業ビルのひとつで，筋面タイルやテラコッタを用い，幾何学形を装飾に取り込んだ外観は，昭和初期における建築意匠の特徴をよく伝える。設計は森山松之助。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004529"},{"id":"00013971","register_sub_id":"101","register_pk":"508231","name":"茶寮一松表門及び塀","kana":"ちゃりょういちまつおもてもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都台東区雷門一丁目47-1他","lat":35.71077222,"lng":139.79336389,"geo_status":"db","era":"昭和35年","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"門 木造、瓦葺一部銅板葺、間口3.3m 塀 コンクリートブロック造、瓦葺、延長37m","structure_material":"門 木造","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0456","desc":"敷地南・東辺を区画する塀と、隅切部に建つ門。門は切妻造桟瓦葺、軒銅板葺の腕木門で、桁や腕木を塗込め、柱を重厚なタイル貼、板扉を吊り、左脇に潜戸を設ける。塀はコンクリートブロック造、腰を鉄平石貼、桟瓦葺。落着いた雰囲気で料亭に相応しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013971"},{"id":"00013970","register_sub_id":"101","register_pk":"508230","name":"茶寮一松店舗及び住居","kana":"ちゃりょういちまつてんぽおよびじゅうきょ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都台東区雷門一丁目47-1","lat":35.71086111,"lng":139.79318889,"geo_status":"db","era":"昭和35年／令和2年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造二階一部地下一階建、鉄板葺、建築面積389㎡","structure_material":"木造二階一部地下一階建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0455","desc":"浅草雷門通の一筋南に位置する入母屋造料亭。敷地南の前庭を囲むＬ字形平面で、入隅を玄関、南面して座敷を並べ、北に住居部を配す。二階は三間続きの大広間を配し、床の間と舞台を設け、宴席の時代相を示す。随所に銘木や彫刻を飾る数寄屋意匠の料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013970"},{"id":"00007018","register_sub_id":"101","register_pk":"108000","name":"燕湯","kana":"つばめゆ","category":"産業3次","subcategory":"建築物","type_guess":"煙突","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都台東区上野3-9-2","lat":35.705482,"lng":139.772903,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺及び鉄板葺、建築面積205㎡、煙突及び地下燃料庫付","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"13 － 0228","desc":"道路に西面して建つ間口５間半奥行４間の木造２階建で、背面に平屋建浴室、ＲＣ造釜場を付設。正面中央に入母屋屋根の下足場を付け、１階は男女の脱衣場、２階は座敷とする。浴室は梁行中央２間半を建ち上げ湯気抜窓を設ける。ＲＣ造煙突が銭湯を象徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007018"},{"id":"00014570","register_sub_id":"101","register_pk":"515112","name":"手焼せんべい嵯峨の家店舗","kana":"てやきせんべいさがのやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都台東区谷中六丁目14","lat":35.72141389,"lng":139.77063611,"geo_status":"db","era":"明治後期／昭和48年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積32㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"13 - 0485","desc":"谷中寺町の通りに東面する煎餅店。切妻造平入桟瓦葺の二階建店舗兼住居。出桁造の伝統的な町家を改修した看板建築で、一階表を土間ミセ、奥は板敷の作業場とし、床下に炭入付、煎餅焼の窯を置く。二階は三室と増築部分で構成、西室では煎餅干しの作業を行う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014570"},{"id":"00009591","register_sub_id":"101","register_pk":"194587","name":"東京タワー","kana":"とうきょうたわー","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区芝公園4-407-6","lat":35.65857144,"lng":139.74544621,"geo_status":"db","era":"昭和33／昭和42改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄骨造、高さ333m、脚間80m、展望室付","structure_material":"鉄骨造","registered":"2013.06.21(平成25.06.21)","register_no":"13 － 0295","desc":"芝公園に位置する鉄骨造の集約電波塔。二層の大展望台と一層の特別展望台を持つ。高さ三三三メートルと、自立式鉄塔としてはエッフェル塔を凌ぎ、当時世界最高を実現した。戦後日本の復興の象徴として、また高度経済成長の原点として、国民に広く親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009591"},{"id":"00008654","register_sub_id":"101","register_pk":"149375","name":"虎ノ門大坂屋砂場店舗","kana":"とらのもんおおさかやすなばてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都港区虎ノ門1-21","lat":35.66822157,"lng":139.75069123,"geo_status":"db","era":"大正12年／平成6年・平成19年改修","year":1923,"year_source":"converted","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"13 － 0277","desc":"交差点の北西角地に位置する。木造2階建、角地にあわせたＬ字型を基本に隅を斜めに削る。切妻造桟瓦葺とし、隅には千鳥破風を飾る。外壁は下見板張で、小壁を漆喰で仕上げる。2階は座敷で開口部には欄干を出す。町のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008654"},{"id":"00008264","register_sub_id":"101","register_pk":"133906","name":"中江店舗","kana":"なかえてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都台東区日本堤1-208-3","lat":35.725135,"lng":139.79704591,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"13 － 0263","desc":"土手通りに西面して店を開く。桁行５．９ｍ梁間１０ｍの木造２階建。１、２階ともに座敷とし、２階は壁に腰板を張り、欄間には竹の組子に松竹梅と桜をあしらう。街路に平行する南北棟の切妻造桟瓦葺。熨斗瓦を高く積み、建ちの高い表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008264"},{"id":"00012128","register_sub_id":"101","register_pk":"352927","name":"難波商店店舗兼主屋","kana":"なんばしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区寿二丁目6-4他","lat":35.709931,"lng":139.789103,"geo_status":"db","era":"昭和4年頃／昭和43年増築、昭和52年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積74㎡、塔屋付","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2018.03.27(平成30.03.27)","register_no":"13-395","desc":"浅草通りに面する角地に建つ。鉄筋コンクリート造で一階を店舗、地下一階と二階を倉庫、三階を居室とする。外壁は色モルタル塗で、縦長窓と丸窓を開き、緑色の瓦や高欄を廻し意匠性に富む。塔屋は反りの強い屋根を二重に架け、独創的な外観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012128"},{"id":"00003074","register_sub_id":"101","register_pk":"104064","name":"花重店舗","kana":"はなじゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都台東区谷中七丁目311","lat":35.72359807,"lng":139.77017466,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"13 － 0138","desc":"谷中墓地開設とほぼ同時期に開業した生花問屋。明治１０年に前身建物を背面側に曳屋し，木造２階建の店舗兼居室を建てる。１階は店舗で，現在は花屋を営み，２階は３室に区切って畳敷の居室としている。江戸・明治期の谷中の風致を今に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003074"},{"id":"00003394","register_sub_id":"101","register_pk":"104384","name":"ハリオグラスビル","kana":"はりおぐらすびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都中央区日本橋富沢町9-3","lat":35.68887617,"lng":139.78190196,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地下1階地上3階建、建築面積394㎡","structure_material":"鉄筋コンクリート造地下1階地上3階建","registered":"2003.07.01(平成15.07.01)","register_no":"13 － 0148","desc":"北西角の角切り部に営業室玄関を設け，北及び西面に溝彫を施したコリント式大オーダーを廻す。銀行支店建築の好例で，設計は川崎貯蓄銀行建築課，施工は竹中工務店。現在は耐熱ガラス食器会社のショールームを兼ねた本社ビルとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003394"},{"id":"00001249","register_sub_id":"101","register_pk":"102239","name":"はん亭","kana":"はんてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都文京区根津2-12-15","lat":35.71732631,"lng":139.76611242,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造３階建，瓦葺，建築面積36㎡","structure_material":"木造３階建","registered":"1999.08.23(平成11.08.23)","register_no":"13 － 0056","desc":"不忍通りと一本東側の小路に挟まれた敷地の小路側角地に建つ。木造３階建、瓦葺寄棟屋根のもと店舗建築。ほぼ同面積、同高の階を三層に重ねたせいの高い町屋で、根津地区のランドマークとして知られる。現在は内部を改装して串揚屋になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001249"},{"id":"00001761","register_sub_id":"101","register_pk":"102751","name":"鳳明館本館","kana":"ほうめいかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都文京区本郷五丁目426他","lat":35.71120335,"lng":139.75626941,"geo_status":"db","era":"明治30代／昭和初期改造","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造地上2階地下1階建、瓦葺、建築面積591㎡","structure_material":"木造地上2階地下1階建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0087","desc":"木造２階建の近代和風建築。下宿屋として建設されたが，昭和初期に下宿屋兼旅館に改造し、さらに昭和２０年に旅館建築に模様替えした。各室毎に異なったつくりで，部屋の銘木に合わせた部屋名とする。下宿・旅館が多かった本郷地区の歴史的な景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001761"},{"id":"00000525","register_sub_id":"101","register_pk":"101515","name":"堀商店","kana":"ほりしょうてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都港区新橋2-5-2","lat":35.66794918,"lng":139.75614879,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造４階建塔屋付，建築面積173㎡","structure_material":"鉄筋コンクリート造４階建塔屋付","registered":"1998.04.21(平成10.04.21)","register_no":"13 － 0009","desc":"新橋駅に近い角地に建つ建築金物を扱う商店のビル。鉄筋コンクリート造４階建で，西端に垂直線を強調した窓を持つ階段室と塔屋を設ける。軒廻りの装飾が特異で，スクラッチタイル貼りの外壁，水平線を強調した窓廻りに時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000525"},{"id":"00001657","register_sub_id":"101","register_pk":"102647","name":"松本家住宅主屋","kana":"まつもとけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区神田多町2-9","lat":35.69429638,"lng":139.76894818,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造3階建、瓦葺、建築面積137㎡","structure_material":"木造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0082","desc":"神田多町問屋街に残る震災復興町家で、多町大通りに面した角地に東面して建つ。木造３階建、切妻造、平入で、正面は出桁造の構えをとり、北妻面は窓の少ない防火に配慮した造りとする。東京の下町における震災復興期の和風町家として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001657"},{"id":"00012299","register_sub_id":"101","register_pk":"531623","name":"繭山龍泉堂店舗","kana":"まゆやまりゅうせんどうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都中央区京橋二丁目5-60他","lat":35.67613889,"lng":139.77125278,"geo_status":"db","era":"昭和35年／昭和58年・平成29年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造3階一部4階建地下1階、建築面積191㎡","structure_material":"鉄筋コンクリート造3階一部4階建地下1階","registered":"2018.05.10(平成30.05.10)","register_no":"13-405","desc":"美術商が集まる京橋二丁目の一角にある店舗兼住宅。設計は東畑謙三による。通りに面した北面と東面は錆付きの由来石を額縁状に廻し、壁面を弁柄入黒漆喰で仕上げるなど骨董美術を意識した意匠でまとめる。目覚ましい都市の戦後復興を彩った商業建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012299"},{"id":"00014143","register_sub_id":"101","register_pk":"508773","name":"安与ビル","kana":"やすよびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和後","pref":"東京都","address":"東京都新宿区新宿三丁目114-13","lat":35.69060833,"lng":139.70131111,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上9階地下2階建、建築面積416㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造地上9階地下2階建","registered":"2022.02.17(令和4.02.17)","register_no":"13-0461","desc":"新宿東口に建つ。鉄骨鉄筋コンクリート造地下２階地上９階建。背面にＬ字型のサービス部分を立上げ、入隅に、竪格子状ルーバーを付けた八角形平面を各階で角度を変えて積層させる、特異ながら品のある外観意匠。内装は残月亭写し始め、谷口吉郎円熟期の逸品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014143"},{"id":"00001500","register_sub_id":"101","register_pk":"102490","name":"萬屋酒店","kana":"よろずやさけてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都大田区池上4-23-6","lat":35.575211,"lng":139.704681,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積106㎡","structure_material":"木造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"13 － 0071","desc":"池上本門寺参道沿いの現在地に茶屋を営んだのが当家のはじまりと伝える。つし二階建，出桁造りの江戸時代以来の町家の形式で，上げ下げ戸を含め旧状を良く残す。門前町の代表的な建物のひとつであり，ランドマークとして親しまれている。棟梁は加藤甚五郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001500"},{"id":"00007881","register_sub_id":"101","register_pk":"108861","name":"旅館西郊本館","kana":"りょかんせいこうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区荻窪3-63","lat":35.70285511,"lng":139.62549601,"geo_status":"db","era":"昭和6／昭和中期改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、スレート葺一部鉄板葺及び瓦葺、建築面積473㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"13-0252","desc":"敷地東側の中庭を囲むように「コ」の字形に建つ。木造２階建、スレート一部鉄板及び桟瓦葺、建築面積４７３㎡。１階は玄関や広間、厨房など、２階には宿泊室を配する。ベージュ色のモルタル洗出し仕上げの大壁造とする外観は落ち着きのある街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007881"},{"id":"00011906","register_sub_id":"101","register_pk":"211071","name":"五十嵐商店第一号倉庫","kana":"いがらししょうてんだいいちごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町二丁目2687","lat":35.372095,"lng":139.229047,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、建築面積27㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14-245","desc":"敷地後方中央に南面する。桁行三間、梁間二間、切妻造、平入。外壁をモルタル仕上げとし、扉口はモルタル仕上げの片引戸、内板戸、格子戸片引きで、二階南面に鳥居枠の窓を穿つ。小屋組は登梁形式。外壁に目地を刻み石造風に仕上げ、敷地後方の景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011906"},{"id":"00011908","register_sub_id":"101","register_pk":"211073","name":"五十嵐商店第三号倉庫","kana":"いがらししょうてんだいさんごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町二丁目2687-1","lat":35.372043,"lng":139.229089,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、建築面積2.2㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-247","desc":"第一号倉庫の南に建つ。間口一・二メートル、奥行一・八メートル。切妻造とするが、軒の出は造らず、壁から屋根までモルタルで塗込め、正面のみ水切のため、妻壁を迫出す。小屋組は、梁を架け、棟木を受ける簡素な構造。小規模ながら敷地景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011908"},{"id":"00011907","register_sub_id":"101","register_pk":"211072","name":"五十嵐商店第二号倉庫","kana":"いがらししょうてんだいにごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町二丁目2687","lat":35.372132,"lng":139.229109,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、建築面積27㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14-246","desc":"店舗兼主屋と第一号倉庫との間に南面する。桁行三間、梁間二間、切妻造、平入。外壁はモルタル仕上げで、腰まで目地を刻む。扉口はモルタル仕上げの両開戸で、二階南面に引分戸の窓を穿つ。小屋組はキングポストトラスで、新たな技法を取り入れた倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011907"},{"id":"00011909","register_sub_id":"101","register_pk":"211074","name":"五十嵐商店第四号倉庫及び第五号倉庫","kana":"いがらししょうてんだいよんごうそうこおよびだいごごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町二丁目2687","lat":35.372184,"lng":139.228998,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、建築面積106㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-248","desc":"敷地北西にあり南面する。桁行四間、梁間三間の二棟に切妻造の屋根を架け、正面に下屋庇を付ける。外壁は四隅の柱や鉢巻にモルタル仕上げを見せる。内部は、中央両端半間に間仕切壁を設けるほかは一室で、小屋組はキングポストトラスとする大型倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011909"},{"id":"00011905","register_sub_id":"101","register_pk":"211070","name":"五十嵐商店店舗兼主屋","kana":"いがらししょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町二丁目2687","lat":35.372165,"lng":139.229201,"geo_status":"db","era":"昭和3年／昭和11年頃増築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造3階建、建築面積122㎡、門柱付","structure_material":"木造3階建","registered":"2017.10.27(平成29.10.27)","register_no":"14-244","desc":"秦野市中心部に東面する。木造三階建で、外壁は正面をモルタル洗出し、側背面をモルタル仕上げと異にし、柱形や柱頭飾に意匠を凝らす。一階は店舗部で広い土間と畳敷のミセ・帳場を配し、二、三階は居室部で応接間を設ける。古典様式風の外観で親しまれる商店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011905"},{"id":"00009929","register_sub_id":"101","register_pk":"196076","name":"伊藤屋旅館奥棟","kana":"いとうやりょかんおくとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字橋下484-1他","lat":35.14646586,"lng":139.07442493,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積50㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"14 － 0186","desc":"本館北側の傾斜地に建つ。木造二階建、入母屋造桟瓦葺で、窓上に庇を廻らす。上下階とも客室数室を配し、本館同様、南縁の全開口にガラス窓をたてる。内部造作では違棚やトコ脇にも窓を開け、壁に山形窓を穿つなど通風採光に配慮し、各部意匠も洗練される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009929"},{"id":"00009928","register_sub_id":"101","register_pk":"196075","name":"伊藤屋旅館本館","kana":"いとうやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字橋下484-1他","lat":35.14639548,"lng":139.07423103,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"14 － 0185","desc":"川の北岸に南面して建つ木造二階建の旅館。入母屋造桟瓦葺で上下階に庇を廻らし、二階縁の南面では、腰部や欄間にもガラス窓をたてて開放的な形式とする。客室の内部造作も座敷飾など繊細な意匠になる。近代の湯河原温泉整備期における初期の旅館建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009928"},{"id":"00009930","register_sub_id":"101","register_pk":"196077","name":"伊藤屋旅館門柱及び石垣","kana":"いとうやりょかんもんちゅうおよびいしがき","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字橋下484-1他","lat":35.14634606,"lng":139.07397129,"geo_status":"db","era":"昭和初期／平成20頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"門柱 石造 石垣 石造、総延長47m","structure_material":"門柱 石造 石垣 石造","registered":"2014.04.25(平成26.04.25)","register_no":"14 － 0187","desc":"敷地南面の入口中央東寄りに門柱一対を立て、左右に石垣をのばす。門柱は花崗岩製で瘤出し仕上げに丸面取を施す。石垣は見付を方形とした切石を高さ一～二メートルに布積し、頂部に蒲鉾形の笠石を伏せる。積石も丸面を取り、重厚ながら柔和な印象をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009930"},{"id":"00002526","register_sub_id":"101","register_pk":"103516","name":"岩本楼ローマ風呂","kana":"いわもとろうろーまぶろ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市江の島2-2-7","lat":35.30108333,"lng":139.48025,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、ガラス屋根、建築面積43㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"14 － 0058","desc":"江の島の老舗旅館の洋風浴室。浴室は方３間規模で，ガラスドームを架ける他，壁面には壁泉やベネチア窓風飾りをタイルやテラコッタで造り，脱衣室境には孔雀模様のステインドグラスを嵌める。タイル等は小森忍，ステインドグラスは別府七郎の製作と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002526"},{"id":"00007986","register_sub_id":"101","register_pk":"128818","name":"上野屋玄関棟","kana":"うえのやげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字丸山616-1他","lat":35.14763818,"lng":139.07117875,"geo_status":"db","era":"昭和11頃／昭和25頃・昭和35頃・昭和50頃改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板一部銅板葺、建築面積385㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"14-0162","desc":"敷地の東南隅、東面して建つ。大広間部と玄関部がＬ字型に取り付く木造２階建、建築面積３８５㎡。屋根は入母屋造、鉄板及び銅板葺で、さらに前後に落棟を付け、正面中央には起りのある屋根の玄関を張り出す。複雑な外観構成が老舗旅館の風格を醸成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007986"},{"id":"00007987","register_sub_id":"101","register_pk":"128819","name":"上野屋別館","kana":"うえのやべっかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字丸山616-1他","lat":35.14775578,"lng":139.07106114,"geo_status":"db","era":"大正12／昭和25頃・昭和35頃・平成元頃改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積195㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"14-0163","desc":"玄関棟の西面に接続する。木造２階建、鉄板葺で、建築面積１９５㎡。南北棟で、北入母屋造南寄棟造の南面に入母屋造の落棟を付設する。北半部は下見板張で、小壁を漆喰仕上げとし、銅板葺庇を付ける。本館や玄関棟と近接して建ち、変化のある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007987"},{"id":"00007985","register_sub_id":"101","register_pk":"128817","name":"上野屋本館","kana":"うえのやほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字丸山616-1他","lat":35.14757263,"lng":139.07099945,"geo_status":"db","era":"昭和5／昭和前期・昭和25増築・平成2・平成4改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造4階建、鋼板葺、建築面積195㎡、離れ付","structure_material":"木造4階建","registered":"2010.01.15(平成22.01.15)","register_no":"14-0161","desc":"山裾に占める敷地の南西に建つ。傾斜地に建つ木造４階建で、上階ほど階段状に山側へ張り出し、４階から階段により離れに至る。北面に入母屋破風を見せ、南面を切妻造とする鉄板葺。３、４階の正側面には銅板葺の庇と高欄をまわし、楼閣風の外観に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007985"},{"id":"00011661","register_sub_id":"101","register_pk":"210677","name":"宇山商事店舗兼主屋","kana":"うやましょうじてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市寿町2202","lat":35.375916,"lng":139.229014,"geo_status":"db","era":"昭和3年／昭和40年頃改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"14-0233","desc":"旧矢倉沢往還沿いに東面して建つ。一階下屋は一段、二階は二段の出桁造で、奥行きの深い下屋庇を構成する。内部は前土間とし、地域の町家の特徴を示す。壁を磨き漆喰にするなど丁寧な仕上げや、良材を用いた座敷部が、当地の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011661"},{"id":"00014340","register_sub_id":"101","register_pk":"511329","name":"小田原宿なりわい交流館（旧角吉店舗）","kana":"おだわらじゅくなりわいこうりゅうかん（きゅうかどきちてんぽ）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県小田原市本町三丁目242","lat":35.2483,"lng":139.16,"geo_status":"db","era":"昭和7年／平成13年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積73㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0318","desc":"小田原宿中心部にある漁網店の店舗。かつては魚市場が隣接。二階建、切妻造桟瓦葺、外壁下見板張、正面ガラス戸の下屋を設け、二階正面は出格子とし、二段の出桁造とする。一階は土間と１５畳のミセ、二階は漁具の作業場とした。水産業の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014340"},{"id":"00003954","register_sub_id":"101","register_pk":"104944","name":"金澤園","kana":"かなざわえん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市金沢区柴町46","lat":35.34404521,"lng":139.63526916,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積252㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"14 － 0082","desc":"海岸の近傍に建てられた割烹旅館。入母屋造，桟瓦葺の木造２階建で，北面に玄関を設け，１，２階に４室ずつ客室を配す。客室は銘木を用いた凝ったつくりの座敷飾りや建具，欄間により，それぞれ趣向を凝らす。戦前の郊外行楽地における休泊施設の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003954"},{"id":"00002228","register_sub_id":"101","register_pk":"103218","name":"環翠楼別館","kana":"かんすいろうべっかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤88","lat":35.232662,"lng":139.093048,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造3階建、鉄板葺、建築面積396㎡","structure_material":"木造3階建","registered":"2001.08.28(平成13.08.28)","register_no":"14 － 0056","desc":"本館南棟の西側に位置し，国道１号線の屈曲に応じて本館とは棟の方向を振って建つ。入母屋造，鉄板葺の木造３階建で，２，３階は本館の３，４階とそれぞれ同レベルにあり，廊下で結ばれる。県下の真鶴に所在したものを移築したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002228"},{"id":"00002226","register_sub_id":"101","register_pk":"103216","name":"環翠楼本館北棟","kana":"かんすいろうほんかんきたとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤88","lat":35.232986,"lng":139.093399,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造一部鉄筋コンクリート造4階建、鉄板葺、建築面積337㎡","structure_material":"木造一部鉄筋コンクリート造4階建","registered":"2001.08.28(平成13.08.28)","register_no":"14 － 0054","desc":"塔之澤で最も古い歴史をもつ旅館で，国道１号線と早川と湯坂山に囲まれた三角形状の敷地の北側，玉の緒橋西詰南に建つ。国道側からは３階建地下１階で，３階に７２畳敷の大広間を設ける。国道の曲がり縁に建つことから塔之澤のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002226"},{"id":"00002227","register_sub_id":"101","register_pk":"103217","name":"環翠楼本館南棟","kana":"かんすいろうほんかんみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤88","lat":35.232746,"lng":139.093307,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造4階建、鉄板瓦棒葺、建築面積545㎡","structure_material":"木造4階建","registered":"2001.08.28(平成13.08.28)","register_no":"14 － 0055","desc":"本館北棟の南方，湯坂山際に建つ。木造４階建で，平面形状はおおむねＬ型とし，最上階に１００畳大の「神代閣」と６０畳大の「万象閣」の大広間を配する。屋根は銅板瓦棒葺，千鳥破風付きの賑やかな入母屋造を洋風トラスで組む。棟梁は北棟と同じ井上米吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002227"},{"id":"00009740","register_sub_id":"101","register_pk":"195569","name":"桔梗屋主屋","kana":"ききょうやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市藤沢1-751-1他","lat":35.34696822,"lng":139.48535755,"geo_status":"db","era":"明治44頃／昭和初期増築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積115㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"14 － 0180","desc":"店蔵の北方に接続して建つ。一階は三室を配し、西側へ震災後増築、昭和初期に二階一部を増築した。一階三室は南からゲンカン、ブツマ、オクノザシキとする。オクノザシキは、トコ・違棚・平書院を備えた格の高い座敷で、当主の居室らしい落着いた空間としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009740"},{"id":"00009741","register_sub_id":"101","register_pk":"195570","name":"桔梗屋文庫蔵","kana":"ききょうやぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県藤沢市藤沢1-752-1他","lat":35.34699915,"lng":139.48520407,"geo_status":"db","era":"文久元／大正14改修","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積50㎡","structure_material":"土蔵造3階建","registered":"2013.12.24(平成25.12.24)","register_no":"14 － 0181","desc":"敷地西方に南北棟で建つ三階建の土蔵で、外壁の腰を海鼠壁とする。一階東面に二箇所の出入口を開き、二階南妻と東面に窓を設ける。小屋は登り梁で、中央間のみ和小屋とする。藤沢宿の中では登り梁を残す唯一の土蔵であるとともに、近世に遡る希少な遺例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009741"},{"id":"00009739","register_sub_id":"101","register_pk":"195568","name":"桔梗屋店蔵","kana":"ききょうやみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市藤沢1-751-1他","lat":35.34688611,"lng":139.48530278,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"14 － 0179","desc":"街道に南面して建つ土蔵造二階建で、外壁を黒漆喰塗とする。二階正面窓の掛子塗の窓枠や軒蛇腹などを丁寧につくり、一階主屋境には千人扉と呼ぶ重厚な観音開の土戸を吊るなど、優秀な左官技術を伝える。藤沢宿において関東大震災以前に遡る貴重な店舗建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009739"},{"id":"00011896","register_sub_id":"101","register_pk":"211061","name":"旧石曽根商店店舗兼主屋","kana":"きゅういしそねしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県藤沢市藤沢字東横須賀711","lat":35.346392,"lng":139.485747,"geo_status":"db","era":"大正13年／昭和42年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積115㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0235","desc":"旧東海道藤沢宿に位置する履物屋の店舗兼主屋。木造二階建鉄板葺で、二階は出桁造とする。街路側にミセ、オロシバを配し、その奥に中廊下を通して六畳、四畳半、仏間を配し、その背後に台所等水廻りを突出させる。近代の藤沢宿の賑わいを今に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011896"},{"id":"00010566","register_sub_id":"101","register_pk":"201140","name":"旧稲元屋呉服店一番蔵","kana":"きゅういなもとやごふくてんいちばんぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市藤沢字東横須賀727","lat":35.34679444,"lng":139.4843,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"14－0195","desc":"内蔵の南に東面して並び建つ。桁行三間梁間二間、土蔵造二階建、切妻造鉄板葺。外壁漆喰塗で鉢巻を廻らし、腰を鼠色とする。内部には関東大震災後に多数の筋違や金物が付加されて震災復旧の様子を窺うことができ、また藤沢宿の土蔵の古例としても価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010566"},{"id":"00010565","register_sub_id":"101","register_pk":"201139","name":"旧稲元屋呉服店内蔵","kana":"きゅういなもとやごふくてんうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市藤沢字東横須賀727","lat":35.34684167,"lng":139.48432222,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"14－0194","desc":"東海道藤沢宿で呉服商を営んだ稲元屋の土蔵。東面する桁行三間半梁間二間、切妻造銅板葺で蔵前を付ける。外壁を人造石洗出し及び研出し仕上げとして石造風に目地を切り、妻面の窓は扉廻りや庇を黒漆喰塗として立面を引き締める。宿場の面影を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010565"},{"id":"00011486","register_sub_id":"101","register_pk":"210452","name":"旧越前屋雨谷商店店舗兼主屋","kana":"きゅうえちぜんやあまやしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県藤沢市打戻1119","lat":35.387075,"lng":139.41258611,"geo_status":"db","era":"大正13年／昭和13年・平成26年移築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"14-0227","desc":"もと薬問屋の店舗兼用住宅。旧店舗部は角地に面したため、土間とガラス戸を矩の手に廻らし、帳場を設ける。出桁や庇の太い桁など、震災復興期らしい重厚さを見せる。旧主屋部は八畳二室の良質な座敷である。藤沢の往時の有様を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011486"},{"id":"00014767","register_sub_id":"101","register_pk":"519025","name":"旧澤良商店店舗兼主屋","kana":"きゅうさわりょうしょうてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県秦野市本町三丁目2838","lat":35.370975,"lng":139.23054167,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、銅板葺、建築面積114㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0335","desc":"龍門寺参道入口に建つ元乾物青果商の店舗兼主屋。通りに西面する木造二階建切妻造平入銅板葺の店舗で、背面に平屋建寄棟造鉄板葺の主屋を接続。店舗一階は全体を土間床、北西に事務所を附属。二階は主座敷八畳と次の間を配す。秦野の賑わいを伝える商家遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014767"},{"id":"00014768","register_sub_id":"101","register_pk":"519026","name":"旧澤良商店土蔵","kana":"きゅうさわりょうしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県秦野市本町三丁目2838","lat":35.371,"lng":139.23046667,"geo_status":"db","era":"明治前期／明治中期移築、大正後期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積23㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0336","desc":"店舗兼主屋の北に建つ旧商品蔵兼家財蔵。土蔵造二階建切妻造平入の置屋根で鉄板葺とし、片町通に妻を見せる。南面一箇所の戸口を店舗蔵前に開く。内部は一、二階とも一室で、窓は二階東妻のみとする。小屋組は登梁を牛梁で受ける。街路景観の要となる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014768"},{"id":"00012136","register_sub_id":"101","register_pk":"352935","name":"旧鈴木薬店店舗兼主屋","kana":"きゅうすずきやくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市大鋸二丁目270","lat":35.344699,"lng":139.487976,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"14-255","desc":"藤沢宿近くの境川東岸に位置する。二階建、切妻造桟瓦葺の商家で、二階天井高を二・九メートルと高く取り、八畳座敷と六畳次の間を並べ、硝子戸を用いて明るい空間を実現している。天井板、床廻りなども良材を用いた質の高いもので、近代商家の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012136"},{"id":"00013058","register_sub_id":"101","register_pk":"368241","name":"旧田島屋材木店（古民家スタジオ・イシワタリ）主屋","kana":"きゅうたじまやざいもくてん（こみんかすたじおいしわたり）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市長谷一丁目269-3","lat":35.31396667,"lng":139.54185833,"geo_status":"db","era":"昭和2年／昭和30年代増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積150㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"14 － 0274","desc":"通りの北側敷地に建つ二階建。一階南面に座敷二室を配して東側に玄関を構え、二階も南に二室を並べ、上下階とも南面の縁にガラス戸をたてる。材木商の建築らしく軸部堅牢で良材を多用する。変容著しい長谷周辺において昭和初期の様相を伝える希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013058"},{"id":"00013059","register_sub_id":"101","register_pk":"368242","name":"旧田島屋材木店（古民家スタジオ・イシワタリ）門及び塀","kana":"きゅうたじまやざいもくてん（こみんかすたじおいしわたり）もんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市長谷一丁目269-3","lat":35.31389444,"lng":139.54190278,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"門 木造、間口1.8m 塀 木造、瓦葺、総延長17m","structure_material":"門 木造","registered":"2019.12.05(令和1.12.05)","register_no":"14 － 0275","desc":"敷地南辺東端に開く門と左右袖塀、敷地西辺まで折曲がりに延びる塀からなる。門は約二〇センチメートル角の門柱一対に板戸引違とし、袖塀は竪板張で笠木を載せる。塀は腰高のコンクリート基礎に竪板張の板塀をたてて銅板葺とする。瀟洒な屋敷構えを創る門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013059"},{"id":"00004129","register_sub_id":"101","register_pk":"105119","name":"神戸屋ふるや店店舗及び主屋","kana":"こうべやふるやてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県小田原市国府津4-2-18","lat":35.2802942,"lng":139.21273025,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積73㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"14 － 0085","desc":"国府津駅前に位置し，国道１号線に面した角地に建つ。タクシー会社の車庫兼社屋として建てられたもので，現在では店舗として利用されている。木造であるが，外壁はモルタルで洋風石造建築を模しており，隅の円柱，窓周り，軒部等に特徴的な意匠を備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004129"},{"id":"00015422","register_sub_id":"101","register_pk":"533437","name":"幸保家住宅石蔵","kana":"こうぼけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市東浦賀二丁目12-9","lat":35.24405556,"lng":139.72164167,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積17㎡","structure_material":"木骨石造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"14 - 0363","desc":"主屋の南隣に建つ米蔵。切妻造桟瓦葺で鉢巻を含め、外壁全面に長尺の房州石を積上げた木骨石造建築。北面に戸口を設け、各階一室で木造軸組と束立の和小屋を現し、一階土間の内壁に荷擦木を打付ける。店舗兼主屋と一連で、浦賀の往事の景観を今に伝える石蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015422"},{"id":"00015421","register_sub_id":"101","register_pk":"533436","name":"幸保家住宅店舗兼主屋","kana":"こうぼけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市東浦賀二丁目12-9","lat":35.24411667,"lng":139.72165278,"geo_status":"db","era":"大正14年／令和6年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"14 - 0362","desc":"浦賀湾東側の街路に西面して建つ、元米穀商の店舗兼主屋。二階建寄棟造桟瓦葺で正面に下屋を付す。一階内部は前土間で、繊細な格子戸を建て、奥に二室を配す。二階は二室で表側を１０畳の床構え付き座敷とする。窓に手摺を付し港町の風情を伝える貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015421"},{"id":"00002896","register_sub_id":"101","register_pk":"103886","name":"済生堂薬局小西本店店舗","kana":"さいせいどうやっきょくこにしほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県小田原市本町4-2-48","lat":35.24711826,"lng":139.15691081,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦一部銅板葺、建築面積99㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"14 － 0070","desc":"東海道に面して建つ店舗建築。木造・平屋建，寄棟造，桟瓦葺，平入で，正面に銅板瓦棒葺の下屋庇をつける。柱など主要部に欅材を用い，店部分は天井も高く，薬棚等の室内意匠もよく残る。市街化の進む旧中宿町にあり，かつての城下町の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002896"},{"id":"00002140","register_sub_id":"101","register_pk":"103130","name":"ジェラール水屋敷地下貯水槽","kana":"じぇらーるみずやしきちかちょすいそう","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県横浜市中区元町1-77","lat":35.43969934,"lng":139.65093928,"geo_status":"db","era":"明治10代","year":1877,"year_source":"converted","year_min":1877,"year_max":1877,"year_label":null,"structure":"煉瓦造、面積114㎡","structure_material":"煉瓦造","registered":"2001.04.24(平成13.04.24)","register_no":"14 － 0049","desc":"幕末から横浜に居留したフランス人ジェラールが経営した船舶給水業の施設で，兼営したフランス瓦煉瓦製造工場の地下に築造され，谷戸の湧水を集めて貯水した。天井はいわゆる防火床。水屋敷の遺構として親しまれ，最近ポケットパーク的に整備された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002140"},{"id":"00005713","register_sub_id":"101","register_pk":"106701","name":"寸松堂蔵","kana":"すんしょうどうくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市笹目町292-1他","lat":35.31422899,"lng":139.54363998,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0128","desc":"主屋北東隅に接続して道路に面して建つ。土蔵造２階建，切妻造，桟瓦葺。南北に開く窓は額縁を塗籠で張り出し，同じく塗籠の庇を設けるなど重厚である。内部に階段を設けず，主屋の１階，２階から各々の階に連絡する。主屋と一体となった土蔵形式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005713"},{"id":"00005712","register_sub_id":"101","register_pk":"106700","name":"寸松堂主屋","kana":"すんしょうどうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市笹目町292-1他","lat":35.314121,"lng":139.543777,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、銅板葺、建築面積232㎡、塔屋付","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0127","desc":"交差点の角地に建つ。木造２階建（塔屋付），入母屋造，瓦棒銅板葺。長押や組物を外部に見せて寺院建築風とし，塔屋には相輪を戴く。また外壁を塗籠として格子を設け，城郭風の意匠も混用する。店内部は格天井張。堅牢で特異な外観を呈する商店建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005712"},{"id":"00010944","register_sub_id":"101","register_pk":"208915","name":"関次商店穀物蔵","kana":"せきじしょうてんこくもつぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市本町四丁目1429","lat":35.34750556,"lng":139.48147222,"geo_status":"db","era":"明治19／大正後期増築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積91㎡","structure_material":"土蔵造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0217","desc":"旧東海道に北面する敷地の南端に位置する。桁行九・一メートル梁間五・五メートルの建ちの高い平屋建土蔵で、和小屋を架ける。内部は半割丸太を各柱間に横方向に入れ込んで荷摺木にするという、独特な工法を使い、大壁を裏返ししない技法も特異である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010944"},{"id":"00010945","register_sub_id":"101","register_pk":"208916","name":"関次商店肥料蔵","kana":"せきじしょうてんひりょうぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市本町四丁目1429","lat":35.34750556,"lng":139.48147222,"geo_status":"db","era":"明治40／大正後期増築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木骨石造平屋建、瓦葺、建築面積50㎡","structure_material":"木骨石造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0218","desc":"旧東海道に北面する敷地に建つ。木材で軸を組み、外壁に鎌倉石を張る混構造となる。内部の荷摺木の技法は穀物蔵と同様に半割丸太を各柱間に横方向に入れ込んで荷摺木とする。また関東大震災後、背面側にオロシと呼ぶ下屋を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010945"},{"id":"00014769","register_sub_id":"101","register_pk":"519027","name":"立花屋茶舗店舗兼主屋","kana":"たちばなやちゃほてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市本町三丁目2839","lat":35.37113333,"lng":139.23033889,"geo_status":"db","era":"慶応元年(1865)頃／明治後期改修、昭和2年移築、同10年・同45年頃増築","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積147㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0337","desc":"台町交差点北に位置する茶商の店舗兼主屋。つし二階建切妻造平入鉄板葺の店舗北に寄棟造二階建の主屋を接続。店舗は銅板葺下屋にガラス戸を建込む。主屋二階には東久邇宮宿所とした座敷を配す。通りに面した軒の低い町家が、秦野の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014769"},{"id":"00014770","register_sub_id":"101","register_pk":"519028","name":"立花屋茶舗左の蔵","kana":"たちばなやちゃほひだりのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市本町三丁目2839","lat":35.37114722,"lng":139.2305,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積50㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0338","desc":"店舗の東背後に建つ商品蔵兼家財蔵。土蔵造二階建の東西棟で、切妻造の置屋根を鉄板葺とし、西妻下屋に戸口を設け、両開の掛子塗戸を吊る。外壁は白漆喰塗で腰は下見板張。二階床に格子付の荷上口を備える。右の蔵と一体で龍門寺参道の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014770"},{"id":"00014771","register_sub_id":"101","register_pk":"519029","name":"立花屋茶舗右の蔵","kana":"たちばなやちゃほみぎのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県秦野市本町三丁目2839","lat":35.37109722,"lng":139.23053611,"geo_status":"db","era":"明治41年／大正後期改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積50㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0339","desc":"店舗兼主屋の背後、左の蔵の南に並ぶ商品蔵兼家財蔵。土蔵造二階建切妻造妻入の置屋根鉄板葺とし左の蔵と一連で下屋を付す。外壁はモルタル塗で腰は洗出仕上。戸口は両開掛子塗戸。二階床に格子付荷上口を備える。左の蔵とともに龍門寺参道の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014771"},{"id":"00013239","register_sub_id":"101","register_pk":"366228","name":"玉屋本店店舗兼主屋","kana":"たまやほんてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市片瀬海岸一丁目2617-1","lat":35.31025278,"lng":139.48666944,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、銅板葺一部金属板葺、建築面積183㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"14 － 0280","desc":"江ノ島参詣道沿いの老舗羊羹店。二階建町家の一階正面を下屋、上下階とも出桁造とする。前寄りの土間のミセは大断面のケヤキで重厚な軸部としつつ、屋号を表すステンドグラスを飾り瀟洒な意匠も備える。後方はコウバ等を配する。戦前の参詣道の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013239"},{"id":"00002895","register_sub_id":"101","register_pk":"103885","name":"だるま料理店主屋","kana":"だるまりょうりてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県小田原市本町2-1-30","lat":35.25132758,"lng":139.15952486,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、銅板一部瓦葺、建築面積503㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"14 － 0069","desc":"明治２６年に地元の網元が創業した老舗で，現在の主屋は関東大震災後に，桧・松・欅の良材を集め，随所に和風の粋を凝らして建てた質の高い建築。木造・２階建で，正面中央に唐破風玄関を設け，比翼入母屋造風屋根とするなど，楼閣風の際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002895"},{"id":"00007462","register_sub_id":"101","register_pk":"108444","name":"茅ヶ崎館中二階棟","kana":"ちがさきかんちゅうにかいとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県茅ヶ崎市中海岸3-11595-1他","lat":35.32037,"lng":139.401077,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"14 － 0149","desc":"広間棟の南西に位置し、桁行１１ｍ梁間５．５ｍ規模の寄棟造南北棟と、直交する桁行８．２ｍ梁間７．１ｍの入母屋造東西棟よりなる。スレート葺で、各棟南面には下屋庇を付ける。床を高く張る小規模な棟を鉤の手に配して、変化に富む敷地景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007462"},{"id":"00007461","register_sub_id":"101","register_pk":"108443","name":"茅ヶ崎館広間棟","kana":"ちがさきかんひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県茅ヶ崎市中海岸3-11595-1他","lat":35.3205327,"lng":139.4012369,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺・スレート葺及び瓦葺、建築面積274㎡","structure_material":"木造平屋一部2階建","registered":"2009.01.08(平成21.01.08)","register_no":"14 － 0148","desc":"茅ヶ崎海岸の高台に占める敷地の中央、南庭に面して建つ。東西に長い木造平屋建の寄棟造鉄板葺で、東側に入母屋造スレート葺の２階建を設ける。西端に開放的な広間を配し、簡素で軽快な意匠のトコや付書院を構える。南庭越しに湘南の海を望む旅館の主棟である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007461"},{"id":"00007734","register_sub_id":"101","register_pk":"108716","name":"塔之澤一の湯本館","kana":"とうのさわいちのゆほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤字湯ノ沢90-1他","lat":35.23329905,"lng":139.0934332,"geo_status":"db","era":"明治後期／大正6・大正11増築・昭和中期・昭和後期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造4階一部地下1階建、銅板葺及び鉄板葺、建築面積786㎡","structure_material":"木造4階一部地下1階建","registered":"2009.08.07(平成21.08.07)","register_no":"14-0155","desc":"塔之澤温泉の入口、玉の緒橋の袂に位置する。木造を主体とする４階地下１階建。屋根を銅板や鉄板で葺き、入母屋造や寄棟造などを階高に応じて組み合わせて、複雑な外観を造る。大広間や客室、浴室などに様々な意匠が見られ、老舗旅館の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007734"},{"id":"00006021","register_sub_id":"101","register_pk":"107006","name":"箱根太陽山荘別館","kana":"はこねたいようさんそうべっかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅1320-375","lat":35.25041129,"lng":139.04568183,"geo_status":"db","era":"大正後期／昭和28増改築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階一部3階建、瓦葺一部鉄板葺、建築面積168㎡","structure_material":"木造2階一部3階建","registered":"2006.11.29(平成18.11.29)","register_no":"14 － 0138","desc":"本館西に道路を挟んで建つ木造３階建。東下りの傾斜に従って床高に差があり，本館３階から別館２階への渡廊下を道路上に架ける。２階以上が客室で，３階に１０畳と６畳の続き間座敷を設ける。切妻造，桟瓦葺で，南面中央に入母屋屋根を突出して変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006021"},{"id":"00005940","register_sub_id":"101","register_pk":"106925","name":"箱根太陽山荘本館","kana":"はこねたいようさんそうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅1320-374","lat":35.250595,"lng":139.045883,"geo_status":"db","era":"昭和15／昭和25・26増改築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積267㎡","structure_material":"木造2階一部3階建","registered":"2006.11.29(平成18.11.29)","register_no":"14 － 0137","desc":"警視庁の保険療養所として創建と伝え，東下りの傾斜地に建つ。西側道路に面した２階に入母屋屋根の玄関を設け，寄棟造，桟瓦葺の木造３階建とする。３階に８畳間を中心とする客室を配す。南面縁外の擬宝珠高欄が目をひく。湯治場の風情を残す近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005940"},{"id":"00004128","register_sub_id":"101","register_pk":"105118","name":"長谷川家住宅石蔵","kana":"はせがわけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市国府津3-2-25","lat":35.28003837,"lng":139.20981516,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積41㎡","structure_material":"木骨石造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"14 － 0084","desc":"国府津地区の東海道近傍に建つ木骨石造２階建の蔵。古写真より大正５年の建築であることが知られる。１階は西面に戸口２箇所を開き，内部は２室構成とする。屋根は切妻造，桟瓦葺で，関東大震災後に設けられた補強帯鉄が外観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004128"},{"id":"00004127","register_sub_id":"101","register_pk":"105117","name":"長谷川家住宅店舗及び主屋","kana":"はせがわけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県小田原市国府津3-13-4","lat":35.27956821,"lng":139.20983249,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積157㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"14 － 0083","desc":"国府津地区の東海道沿いにあって，関東大震災後の復興期に建てられた店舗兼住居。木造２階建，平入，入母屋造，桟瓦葺で，棟木銘より昭和２年の上棟が知られる。正面軒は出桁造で支え，屋根には緩やかなむくりをつける。国府津における震災復興町家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004127"},{"id":"00008430","register_sub_id":"101","register_pk":"134826","name":"日影茶屋本店石蔵","kana":"ひかげちゃやほんてんいしくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県三浦郡葉山町堀内字五ツ合16-1","lat":35.28380056,"lng":139.56984488,"geo_status":"db","era":"大正10年頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"石造2階建、瓦葺、建築面積31㎡","structure_material":"石造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"14 － 0170","desc":"客室棟の南方に位置する。石造二階建、東西棟の切妻造桟瓦葺で、桁行六・三メートル梁間四・五メートル。外壁は石目に特徴ある房州石とし、道路側の西妻の二階開口両側を半円柱の柱型とするなど凝ったつくりとなる。重厚で風合いある石蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008430"},{"id":"00008429","register_sub_id":"101","register_pk":"134825","name":"日影茶屋本店客室棟","kana":"ひかげちゃやほんてんきゃくしつとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県三浦郡葉山町堀内字五ツ合16-1他","lat":35.28416703,"lng":139.56993077,"geo_status":"db","era":"大正12年／昭和9年・昭和40年頃改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積390㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"14 － 0169","desc":"通りに西面して車寄せを構える南北棟と、これに北側で直行する東西棟からなる。木造二階建、入母屋造桟瓦葺、建築面積三九〇平方メートル。南北棟は二階を広間とし、東西棟は各階とも小部屋に分ける。簓子下見板張に大きく開口を取り、老舗旅館の面影を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008429"},{"id":"00003209","register_sub_id":"101","register_pk":"104199","name":"福住旅館別荘石蔵","kana":"ふくずみりょかんべっそういしぐら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字湯場613-1","lat":35.23106772,"lng":139.09902354,"geo_status":"db","era":"明治初期／昭和8移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木骨石造2階建、瓦葺、建築面積18㎡","structure_material":"木骨石造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"14 － 0079","desc":"主屋北東端の東方に棟をやや振って建つ。桁行２間半梁間２間，桟瓦葺，切妻造の２階建妻入蔵で，福住旅館金泉楼及び萬翆楼と同様に外部には白石あるいは湯本石と呼ばれる地元産の凝灰岩を積む。箱根における数少ない木骨石造建築の遺存例として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003209"},{"id":"00003208","register_sub_id":"101","register_pk":"104198","name":"福住旅館別荘主屋","kana":"ふくずみりょかんべっそうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字湯場613-1","lat":35.230804,"lng":139.098862,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積292㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"14 － 0078","desc":"湯坂山の山裾東縁に位置する。ほぼ南を正面としたコ字型平面をもつ，桟瓦葺，寄棟造の木造平屋建で，北側の１間幅廊下の南方に和室７室と台所，北方に便所と浴室を配する。湯本福住旅館の長期滞在者用客室として建設された別荘風の上質な数寄屋造建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003208"},{"id":"00003210","register_sub_id":"101","register_pk":"104200","name":"福住樓主屋","kana":"ふくずみろうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤74","lat":35.23281794,"lng":139.09455721,"geo_status":"db","era":"明治20頃-昭和初期","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造地上3階地下1階建、鉄板葺・スレート葺及び瓦葺、建築面積2133㎡","structure_material":"木造地上3階地下1階建","registered":"2003.03.18(平成15.03.18)","register_no":"14 － 0080","desc":"玉の緒橋から千歳橋にかけての早川左岸に建築的アンサンブルを奏でる。国道１号線沿の玄関棟とその奥の棟は前身の「玉之湯旅館」時代の木骨石造建築を改造したもの。西方に浴室棟や木造３階建の各室意匠を変えた客室棟，質の高い書院造の広間棟などを連ねる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003210"},{"id":"00003211","register_sub_id":"101","register_pk":"104201","name":"福住樓茶室","kana":"ふくずみろうちゃしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤74","lat":35.232544,"lng":139.093964,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"14 － 0081","desc":"主屋広間棟の西方，早川寄りに独立して建つ。「洗小亭」と名付けられ，中央に位置する５畳間の北西方に小間，南西方に風呂場を配する。小間は中板付３畳台目の茶室で，福住樓の顧客のひとりであり，数寄者として知られる野崎幻庵の設計と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003211"},{"id":"00010273","register_sub_id":"101","register_pk":"199046","name":"藤田屋旅館本館","kana":"ふじたやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字橋下495","lat":35.146747,"lng":139.073783,"geo_status":"db","era":"大正12年／昭和4年・昭和26年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積385㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"14-0191","desc":"木造二階建の東棟と西棟を雁行して建て、中央に入母屋造の玄関を構える。川に臨んで八畳主体の客室を並べて高欄を設え、室内のトコや欄間に繊細な意匠の組子細工や透彫を飾る。東棟では入口に多様な数寄屋意匠の小庇を付す。温泉街の旅情を醸す旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010273"},{"id":"00000397","register_sub_id":"101","register_pk":"101387","name":"富士屋ホテルアイリー","kana":"ふじやほてるあいりー","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24332907,"lng":139.05975701,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建，鉄板葺，建築面積160㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0013","desc":"敷地南方の斜面に北面して建つ。創業間もない時期の建物で，昭和10年に現在地に移築された。正面両端に突出部をつくり中央に唐破風屋根を設ける点は，本館，一・二号館と共通する。現存する数少ない我が国最初期のリゾートホテル施設として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000397"},{"id":"00000395","register_sub_id":"101","register_pk":"101385","name":"富士屋ホテル１号館","kana":"ふじやほてるいちごうかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24388275,"lng":139.0590483,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建，瓦葺，建築面積292㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0011","desc":"本館の南に客室用の新館として建てられた。左右対称で正面両端に八角平面の突出部を持ち中央に唐破風屋根の玄関ポーチを持つ特異な外観は本館に似る。屋根や玄関の意匠を簡略にし，和風の要素を押さえる点に特徴がある。カムフィ・ロッジの異名を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000395"},{"id":"00000399","register_sub_id":"101","register_pk":"101389","name":"富士屋ホテル食堂","kana":"ふじやほてるしょくどう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24449401,"lng":139.0591546,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造・木造2階建塔屋付，銅板葺一部鉄板葺，589㎡","structure_material":"鉄筋コンクリート造・木造2階建塔屋付","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0015","desc":"和風の意匠を基調にした建物で，１階を鉄筋コンクリート造，２階を木造とする。中央部に２重の塔屋「昇天閣」を設けた外観は特異で，要所に彫刻を配した書院風の豪華な室内意匠も優れている。設計には，木子幸三郎が係わった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000399"},{"id":"00000396","register_sub_id":"101","register_pk":"101386","name":"富士屋ホテル２号館","kana":"ふじやほてるにごうかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24375429,"lng":139.05925205,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建，瓦葺，建築面積292㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0012","desc":"一号館と同時期に建てられた同一の規模・意匠になる建物。レストフル・カテジの異名を持つ。鎧戸付きの縦長の上下窓，天井や軒に用いられた繰形状の蛇腹装飾に本格的な洋風の意匠をみることができ，用いられた技術・技能の水準の高さがうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000396"},{"id":"00000398","register_sub_id":"101","register_pk":"101388","name":"富士屋ホテル花御殿","kana":"ふじやほてるはなごてん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24371443,"lng":139.05962412,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造5階建，銅板葺一部鉄板葺，建築面積1088㎡","structure_material":"鉄筋コンクリート造5階建","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0014","desc":"コの字型平面を持つ鉄筋コンクリート造，５階建の建物。意匠は和風を基調とする。複雑な屋根や高欄付のバルコニー等に特徴がある特異な外観を持ち，豪華な室内意匠にもみるべきものがある。設計はホテルの経営者山口正造で，工事請負は河原徳次郎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000398"},{"id":"00000394","register_sub_id":"101","register_pk":"101384","name":"富士屋ホテル本館","kana":"ふじやほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24418395,"lng":139.05901286,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建，瓦葺，建築面積706㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0010","desc":"外国人の宿泊を意識して，全体に洋風の意匠を基調にしながら内外の要所に和風の意匠を加味した特異な建物。正面中央に唐破風屋根の玄関ポーチ，左右に八角平面の突出部をつくり正面性を強調した左右対称の外観に特徴がある。工事請負は河原兵次郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000394"},{"id":"00013241","register_sub_id":"101","register_pk":"366230","name":"富士屋旅館旧三号館","kana":"ふじやりょかんきゅうさんごうかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字橋上557-1","lat":35.14634722,"lng":139.07321667,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積159㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"14 － 0282","desc":"湯河原温泉の川沿いに建つ二階建の木造旅館。入母屋造の主体部の両端から川側に入母屋の張出しを設け、大屋根の中央に千鳥破風を飾る。上下階とも窓上に庇を廻らし、上階は刎高欄付の縁を廻らすなど、風格ある立面を構成する。往時の温泉街の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013241"},{"id":"00014772","register_sub_id":"101","register_pk":"519030","name":"保全堂薬局店舗兼主屋","kana":"ほぜんどうやっきょくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町一丁目2626-1他","lat":35.37406667,"lng":139.22760278,"geo_status":"db","era":"昭和3年／昭和40年代改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、鉄板葺一部銅板葺、建築面積188㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0340","desc":"秦野の本町四ツ角交差点の南に位置する薬局の店舗兼主屋。2階建洋風店舗の西に2階建和風主屋を接続する。店舗は正面中央を薄く張り出し三連の上下窓を開け、出隅の柱頭飾のレリーフなどセセッション風意匠を用いた外観が、通りの歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014772"},{"id":"00009440","register_sub_id":"101","register_pk":"194233","name":"松の茶屋田舎家","kana":"まつのちゃやいなかや","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字上町518-1他","lat":35.22854073,"lng":139.09872689,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋一部2階建、茅葺一部瓦葺、建築面積356㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"14 － 0173","desc":"敷地の中ほどに建ち、木造平屋一部二階建、建築面積三五六平方メートルである。東半の入母屋造茅葺部分には残月の間や大炉の間を、西半の桟瓦葺部には霞の間などを配し、いずれも数寄屋風意匠を基調として多彩な室内空間を創る。瀟洒なつくりのもと別荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009440"},{"id":"00009443","register_sub_id":"101","register_pk":"194236","name":"松の茶屋松月","kana":"まつのちゃやしょうげつ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字上町518-1他","lat":35.22827899,"lng":139.09830572,"geo_status":"db","era":"昭和前期／昭和34年移築・昭和後期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"14 － 0176","desc":"中央棟西側に渡廊下を介して接続する。木造平屋建、建築面積六九平方メートル、寄棟造、茅葺型銅板葺である。外壁は真壁漆喰塗りで、下部に丸竹を詰打ちとする。室内は西端に主室である松月の間を配し、東側に四畳半などを並べる。落着いた佇まいの離れ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009443"},{"id":"00009441","register_sub_id":"101","register_pk":"194234","name":"松の茶屋中央棟","kana":"まつのちゃやちゅうおうとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字上町518-1他","lat":35.2284741,"lng":139.09857222,"geo_status":"db","era":"昭和27年／昭和後期改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋一部2階建、こけら葺一部瓦葺、建築面積363㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"14 － 0174","desc":"建物群の中央に建ち、木造平屋一部二階建、こけら葺一部桟瓦葺、建築面積三六三平方メートル。南面東寄りに玄関を構え、屈曲する廊下沿いに上質なつくりの客室や、調理場を配置する。複雑な平面と屋根構成になり、変化に富む外観をつくる、もと旅館の客室棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009441"},{"id":"00009442","register_sub_id":"101","register_pk":"194235","name":"松の茶屋浴室棟","kana":"まつのちゃやよくしつとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字上町518-1他","lat":35.22848124,"lng":139.09830572,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積18㎡、渡廊下付","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"14 － 0175","desc":"中央棟北西部の北側に渡廊下を介して建ち、谷側を大きなガラス窓として対岸の山並みを望む浴室棟。木造平屋建、建築面積一八平方メートル、八注造銅板葺。平面は八角形で中央に石製の円形浴槽を備え、床と腰壁に大理石を張るなど独特な形式になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009442"},{"id":"00005815","register_sub_id":"101","register_pk":"106802","name":"三河屋本店蔵","kana":"みかわやほんてんくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市雪ノ下1-270-1他","lat":35.32283115,"lng":139.55398771,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0126","desc":"店舗兼住宅の北側後方に建つ。桁行８間，梁間３間の規模で，木造平屋建，切妻造，波形鉄板葺。内部を３室に間仕切り，中央の室には中２階を設ける。鎌倉市内に現存する蔵の中では比較的規模が大きく，近代の鎌倉が発展した時期の商家における遺構として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005815"},{"id":"00005734","register_sub_id":"101","register_pk":"106722","name":"三河屋本店店舗兼住宅","kana":"みかわやほんてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市雪ノ下1-270-1他","lat":35.32269826,"lng":139.55408224,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0125","desc":"若宮大路に面して建つ。桁行５間，間口８間の規模で，木造２階建，切妻造，桟瓦葺。１階正面に下屋を張り出す。店舗は木太い根太天井を現し，通り土間を通し，床上部奥に座敷を配する。正面軒を出桁造りとし，正面に成の高い長大な差鴨居を渡し重厚な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005734"},{"id":"00008832","register_sub_id":"101","register_pk":"162275","name":"三河屋旅館本館","kana":"みかわやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町小涌谷字小涌谷503-1","lat":35.23702357,"lng":139.04653856,"geo_status":"db","era":"大正13年頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺・銅板葺及び一部スレート葺、建築面積1014㎡","structure_material":"木造2階一部平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"14 － 0171","desc":"箱根小涌谷に建ち、唐破風玄関を構えた主屋、洋風内装のラウンジ棟、客室を一列に配した月梅、田の字形に配した松竹、月梅と中庭を介して建つ浴場棟からなり、建築面積1014㎡を測る。温泉地の発展に伴う増築過程をよく示す老舗旅館の本館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008832"},{"id":"00013513","register_sub_id":"101","register_pk":"504877","name":"湯浅物産館","kana":"ゆあさぶっさんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市雪ノ下一丁目272イ2他","lat":35.32235833,"lng":139.55385278,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積246㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"14 － 0286","desc":"若宮大路に東面して建つ二階建の看板建築。間口六間、奥行一一間半で、店の奥にトップライト付きの吹抜けを設けた近代的なつくりとする。正面はスクラッチタイル貼とし、二階に六連の額縁飾付半円アーチ窓を配して意匠を凝らし、街路景観に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013513"},{"id":"00011662","register_sub_id":"101","register_pk":"210678","name":"龍宮殿本館","kana":"りゅうぐうでんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町元箱根字蛸川139-3","lat":35.210406,"lng":139.011223,"geo_status":"db","era":"昭和13年／昭和31年移築、平成28年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階一部3階建、銅板葺、建築面積1348㎡","structure_material":"木造2階一部3階建","registered":"2017.06.28(平成29.06.28)","register_no":"14-0234","desc":"芦ノ湖の東岸に建つ。昭和初期に浜名湖弁天島に建てられたホテルを昭和三一年に当地に移築。平等院鳳凰堂を模した外観で、二階建の中央建物の両翼に三階建の望楼風建物を配する。伝統的な様式を模した吹抜け階段ホールを持つなど、外国人向けホテルの希少な例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011662"},{"id":"00011098","register_sub_id":"101","register_pk":"205205","name":"秋山孝ポスター美術館長岡本館（旧長岡商業銀行宮内支店）","kana":"あきやまたかしぽすたーびじゅつかんながおかほんかん（きゅうながおかしょうぎょうぎんこうみやうちしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市宮内二丁目127-1","lat":37.420394,"lng":138.841663,"geo_status":"db","era":"大正14／昭和27移築、平成21改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積94㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0440","desc":"旧三国街道に西面して建つ。鉄筋コンクリート造平屋建切妻造瓦葺。外壁は正面が洗出し、側面はタイル張り、窓枠は人造石研出しである。雁木は曳家の際鉄筋コンクリート造に改められたが、大正末の銀行建築の姿をよく残し、地域のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011098"},{"id":"00009135","register_sub_id":"101","register_pk":"164688","name":"麻屋高野店舗兼主屋","kana":"あさやたかのてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市東本町一丁目字善光寺町3-1他","lat":37.11934771,"lng":138.24664592,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積118㎡","structure_material":"木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"通りに南面し、木造2階建、建築面積118平方メートル、切妻造鉄板葺である。1階はミセ、チャノマ、ザシキ、ドインを並べ、2階はチャノマ吹抜けの前後にマエニカイとウシロニカイを配し渡廊下でつなぐ。近代高田の町家において発展した空間構成を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009135"},{"id":"00009136","register_sub_id":"101","register_pk":"164689","name":"麻屋高野土蔵","kana":"あさやたかのどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市東本町一丁目字善光寺町3-1他","lat":37.11944407,"lng":138.24666377,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地後方に建つ、アマヤで覆われた土蔵で、建築面積52平方メートル、土蔵造2階建、切妻造鉄板葺である。土蔵周囲は主屋のトオリニワと連続する内部空間とし、積雪時の通路と作業場所を確保している。雪国における町家の特色と生活様態を示す家財蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009136"},{"id":"00011929","register_sub_id":"101","register_pk":"210936","name":"荒惣内蔵","kana":"あらそううちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県胎内市本町28","lat":38.051519,"lng":139.402788,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、鋼板葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-471","desc":"敷地中央の南寄りに東西棟で南面する。置屋根形式で、桁行八メートル、梁間四メートルで、一尺間隔で柱を立て、板を嵌める丁寧な造り。正面のみ両開扉と二階に片開窓を二所設け、三段の掛子塗とし、扉下部に桃の漆喰彫刻が施され珍しい造形を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011929"},{"id":"00011927","register_sub_id":"101","register_pk":"210934","name":"荒惣店舗兼主屋","kana":"あらそうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市本町28","lat":38.051479,"lng":139.403005,"geo_status":"db","era":"文政7年（1824）／明治前期・同34年増築、昭和40年頃改修","year":1824,"year_source":"db","year_min":1824,"year_max":1824,"year_label":null,"structure":"木造2階建、瓦葺、232㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-469","desc":"旧宿場町中条の中心にあり東面する。南側の通り土間に沿って、ミセ、茶の間、板の間を並べ、北に座敷二室を増築する。二階は床の間、床脇を備えた上の間と次の間を並べ、正面に縁側を設ける。ミセは北へも増築しコの字平面となり、繁栄の過程を示す大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011927"},{"id":"00011928","register_sub_id":"101","register_pk":"210935","name":"荒惣見世蔵","kana":"あらそうみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県胎内市本町28","lat":38.051522,"lng":139.403049,"geo_status":"db","era":"明治34年","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-470","desc":"敷地北に東西棟で建つ。桁行一〇メートル、梁間四・六メートルで、両妻面は両開扉を四段の掛子塗とし、内部は一尺角の棟持柱を中央に立て堅牢に造る。一階側面は海鼠壁で飾り、通りに面する二階北面は黒漆喰塗の両開の窓を三所開き、街路景観を重厚に形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011928"},{"id":"00001592","register_sub_id":"101","register_pk":"102582","name":"行形亭裏門","kana":"いきなりやうらもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92665259,"lng":139.0405389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、鉄板葺、間口2.1m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0064","desc":"敷地北端の裏山の上に位置する。表門と同様の銅板葺のムクリ屋根を載せる。疎ら垂木，片開きの縦格子透し門で，その一枚戸に引き戸形式の潜戸を付ける。柱には念入りな面取りがなされ，裏庭の景観を引き締めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001592"},{"id":"00001591","register_sub_id":"101","register_pk":"102581","name":"行形亭表門","kana":"いきなりやおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92610038,"lng":139.04106994,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、鉄板葺、間口2.3m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0063","desc":"敷地の南東部に位置する。銅板葺の薄いムクリ屋根を載せた数寄屋風の門であるが，内側に広がった小屋根付きの控え板壁を伸ばして高麗門風の構えをとる。鶴の透し彫りが施された板欄間付きの縦格子透し門扉に気品が感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001591"},{"id":"00001587","register_sub_id":"101","register_pk":"102577","name":"行形亭九番の間","kana":"いきなりやきゅうばんのま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92627786,"lng":139.04076796,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0059","desc":"離れ座敷に隣接する。一室の座敷に加えて玄関，廊下を備える独立した客室。木造平屋建，鉄板葺で，腰壁黒塗簓子下見板張，建物上部を真壁造りとする。建物後部は築山に載り，建物前面が懸造状に高い床束に載ることで，舞台装置的に庭に張り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001587"},{"id":"00001586","register_sub_id":"101","register_pk":"102576","name":"行形亭寿の間・二番の間","kana":"いきなりやことぶきのま・にばんのま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92649252,"lng":139.04057625,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積252㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0058","desc":"行形亭は新潟市内の代表的老舗料亭として知られている。この木造平屋建の座敷棟は，広大な敷地の最奥部に位置し庭と広く面する。木造平屋建，黒塗簓子下見板張，鉄板葺寄棟屋根で，大広間を中心に構成される寿の間が，主屋から連続する内部空間の終点となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001586"},{"id":"00001585","register_sub_id":"101","register_pk":"102575","name":"行形亭三番の間","kana":"いきなりやさんばんのま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92661297,"lng":139.04082745,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0057","desc":"行形亭では敷地中央の池付の庭を囲むように各建物が配される。木造平屋建の三番の間は敷地の北側に位置し，その両端が広間及び二番の間と廊下で接続される。腰壁黒塗簓子下見板張，上部を真壁造りとする。数寄屋風の内部は掛込天井及び舟底天井の形式を取る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001585"},{"id":"00001584","register_sub_id":"101","register_pk":"102574","name":"行形亭主屋","kana":"いきなりやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92628093,"lng":139.04104766,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積107㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0056","desc":"料亭・行形亭は元禄年間の創業といわれる。総２階建の主屋の１階前面には，庇下の空間を利用したＬ字型の土間が配される。正面妻では上部の梁と小壁，下部の板壁と窓を効果的に組み合わせ，両側の２階庇の破風が意匠を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001584"},{"id":"00001593","register_sub_id":"101","register_pk":"102583","name":"行形亭中門及び塀","kana":"いきなりやちゅうもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92616683,"lng":139.04076437,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、木羽葺、間口1.4m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0065","desc":"離れ座敷の庭を囲み，土蔵と対面する。間口４尺５寸の中門は自然木で棟木を支え，屋根は木羽葺，門扉は網代戸とし，瀟洒な印象を与える。塀は腰壁板張り，上部漆喰塗りとし，土蔵壁面と調和した意匠で，離れ座敷表玄関への通路を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001593"},{"id":"00001590","register_sub_id":"101","register_pk":"102580","name":"行形亭土蔵","kana":"いきなりやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.926048,"lng":139.040802,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0062","desc":"離れ座敷と同時期に建設される。置屋根型式の桟瓦葺で，２階床部まで腰板が張られ，その上部を漆喰仕上げとする。道路側の妻面には鶴の鏝絵が施される。前面道路から見る黒板塀と黒松越しの土蔵は新潟の風情を表す代表的景観として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001590"},{"id":"00001589","register_sub_id":"101","register_pk":"102579","name":"行形亭離れ座敷","kana":"いきなりやはなれざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92621535,"lng":139.04081138,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積319㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0061","desc":"敷地の南側に位置する木造２階建の建屋。入母屋造り，桟瓦葺，簓子下見板張で，和風を基調とした玄関には，多種の洋風照明器具，自然木を用いた階段手摺りなどに独特な造作を施している。また，内部の随所に，行形亭のシンボルである鶴を模した意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001589"},{"id":"00001588","register_sub_id":"101","register_pk":"102578","name":"行形亭湯殿","kana":"いきなりやゆどの","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92606238,"lng":139.04065304,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0060","desc":"九番の間に隣接し，客用の浴室として設けられた，木造平屋建の建屋。前面の庇の下に通土間が配され，それに沿って脱衣室，廊下，浴室が並んでいる。脱衣室には床の間が設けられ，数寄屋風の意匠とし，浴室の天井には白漆喰で龍の鏝絵が描かれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001588"},{"id":"00006272","register_sub_id":"101","register_pk":"107256","name":"井筒屋旅館主屋","kana":"いづつやりょかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市小町221","lat":38.225994,"lng":139.478989,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積115㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"15 － 0257","desc":"西側道路に面して建つ近代の町家建築。桁行５間，梁間４間半規模の木造２階建で，切妻造，桟瓦葺とする。平入で，正面１階には下屋を，２階には縁を付ける。外壁は正面をモルタル仕上げとし，側面を縦板張とする。旧城下町町人地に建ち，町並みの景観に寄与。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006272"},{"id":"00010276","register_sub_id":"101","register_pk":"199049","name":"遠人村舎","kana":"えんじんそんしゃ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県三条市庭月501","lat":37.541094,"lng":139.104109,"geo_status":"db","era":"明治期／昭和12年・平成8年移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"15-0393","desc":"漢学者諸橋轍次が大漢和辞典編纂を手がけた建物。切妻造で屋根は一文字瓦葺の周囲を金属板葺とする。四畳半と三畳の二室の北西に半間幅の廊下を廻らす。外壁にスギ皮を張り、内部造作に吟味された丸太材を使うなど、漢学者の書斎に相応しく趣ある意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010276"},{"id":"00003395","register_sub_id":"101","register_pk":"104385","name":"大橋屋主屋及び土蔵","kana":"おおはしやしゅおくおよびどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区本町通十一番町1813","lat":37.927387,"lng":139.047745,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造3階一部2階建、瓦葺、建築面積323㎡","structure_material":"木造3階一部2階建","registered":"2003.07.01(平成15.07.01)","register_no":"15 － 0156","desc":"市中心部の本町通に面する短冊状の敷地にたつ。妻入で，正面２階に半円アーチと矩形の窓を並置し，壁面を銅板網代張り，その上部に２重の入母屋屋根を見せる。内部は二・三階に客室を設け，各座敷の天井や開口部などに意匠を凝らし変化に富む造作を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003395"},{"id":"00010761","register_sub_id":"101","register_pk":"201596","name":"割烹東忠上の蔵","kana":"かっぽうとうちゅううえのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県小千谷市元町538-1","lat":37.308484,"lng":138.798462,"geo_status":"db","era":"明治前期／昭和前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鋼板葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"15 ‐ 0422","desc":"本館北奥部と妻面を接して建つ、切妻造の二階建土蔵。上下階とも両妻面を張出し、外壁は主体部二階を漆喰塗とする他は下見板を張る。戦前に一階を撞球室としたため洋風持送などの内装を持ち、北妻に半切妻屋根の玄関を設ける。割烹に附属した娯楽施設の遺構","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010761"},{"id":"00010760","register_sub_id":"101","register_pk":"201595","name":"割烹東忠別館","kana":"かっぽうとうちゅうべっかん","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県小千谷市元町538-1","lat":37.308445,"lng":138.798662,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積107㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"15 ‐ 0421","desc":"敷地形状により本館と斜めに接続し、スキップフロア状の動線で連絡するため、変化に富んだ空間構成を持つ。一階は広間二室、二階は大広間とし、庭に面して縁を廻らし、開口を広くとる。座敷飾は大振りで、かつ洗練された意匠になる、瀟洒で上質な和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010760"},{"id":"00010759","register_sub_id":"101","register_pk":"201594","name":"割烹東忠本館","kana":"かっぽうとうちゅうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県小千谷市元町538-1","lat":37.308416,"lng":138.798598,"geo_status":"db","era":"江戸末期／昭和39改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造3階建、鋼板葺、建築面積200㎡","structure_material":"木造3階建","registered":"2015.11.17(平成27.11.17)","register_no":"15 ‐ 0420","desc":"湯殿川畔の傾斜地に建つ木造三階建の割烹で、江戸末期建築の二階建に三階大広間を増築した。外観は建ちの高い真壁造で、一・二階に大小一〇室ほどの客室などを配し、要所に良材を用いた座敷飾を備える。小千谷縮や養鯉業による当地の繁栄を伝える料理屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010759"},{"id":"00003406","register_sub_id":"101","register_pk":"104396","name":"割烹みよや","kana":"かっぽうみよや","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県三島郡出雲崎町大字羽黒町101-1","lat":37.54438498,"lng":138.69031903,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"15 － 0167","desc":"日本海に近い旧北国街道に面して建つ。妻入で，欄間窓付縦長窓などの前面にベランダが付き，上部にハンマービーム風の妻飾りを設ける。２階内部の天井・壁面に施された漆喰の格縁やモールディング，外壁の天使をあしらった鏝絵などの仕上に高度な技を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003406"},{"id":"00005112","register_sub_id":"101","register_pk":"106102","name":"割烹吉源主屋","kana":"かっぽうよしげんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県村上市寺町1437","lat":38.22457994,"lng":139.47655991,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積566㎡","structure_material":"木造2階一部平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"15 － 0189","desc":"寺町の通りに北面して建つ。入母屋造，桟瓦葺のたちの高い２階建の西に切妻造，桟瓦葺の２階建を雁行させ，背後に１５畳４室を並べた南北棟の平屋建を延ばす。内部は，２階の洋風大広間を中心とした良質なつくり。棟札から年代と棟梁「遠藤鉀子郎」が判明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005112"},{"id":"00010950","register_sub_id":"101","register_pk":"208921","name":"環翠楼大正の間","kana":"かんすいろうたいしょうのま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県阿賀野市村杉字薬師平4520","lat":37.800197,"lng":139.29007,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"15-0424","desc":"村杉温泉の老舗旅館で、杉林に囲まれた敷地に構える。木造二階建で横長平面を持つ客室棟で、中央を突出させて玄関ポーチを設ける。東の広縁を介して各室に入るようになっている。軒天井などに洋風意匠も見られる。丁寧な造作になる数寄屋風の内装を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010950"},{"id":"00013705","register_sub_id":"101","register_pk":"504969","name":"環翠楼中広間","kana":"かんすいろうちゅうひろま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"新潟県","address":"新潟県阿賀野市村杉字薬師平4520","lat":37.80020833,"lng":139.290025,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"15 － 549","desc":"南北棟で平屋建寄棟造桟瓦葺。本館から続く廊下からホールに出、北に向かって下座敷、上座敷が続く。西脇は脇座敷である。北・東に広縁を廻し、額入障子を建てる。小壁のせいが高く、貫を二段廻らし開放感のある空間をつくる。敷地北寄りの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013705"},{"id":"00013704","register_sub_id":"101","register_pk":"504968","name":"環翠楼臨泉閣","kana":"かんすいろうりんせんかく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県阿賀野市村杉字薬師平4520","lat":37.80019722,"lng":139.29051667,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積71㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"15 － 548","desc":"新潟平野の山間部にある村杉温泉に所在。敷地中央の高台に位置し、石階でアプローチする。二階建入母屋造桟瓦葺で一、二階とも八畳座敷二室からなり四周に縁を廻らす。床構えは床脇を地袋天袋とした端正な構え。三方にガラス戸を建て庭を望む近代和風の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013704"},{"id":"00003081","register_sub_id":"101","register_pk":"104071","name":"吉川家住宅店舗","kana":"きっかわけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市大町195","lat":38.22432962,"lng":139.47867617,"geo_status":"db","era":"明治25頃","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"15 － 0142","desc":"村上城下旧町人地の中心的通りに面して建つ。桁行２間半梁間４間半規模，南北棟，切妻造，桟瓦葺の町家で，明治２５年の大火後の再建と伝える。近年，北側の増築に際してファサードが伝統的意匠に改装され，大町通りの街路景観整備の核的存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003081"},{"id":"00005598","register_sub_id":"101","register_pk":"106586","name":"喜八屋旅館石蔵","kana":"きはちやりょかんいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県佐渡市小木町55-1他","lat":37.816284,"lng":138.279861,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"石造2階建、建築面積26㎡","structure_material":"石造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"15 － 0203","desc":"別館の北東に位置し，桁行２間半，梁間２間半の規模で，石造２階建，ＲＣ造の陸屋根とする。食器等の蔵であるが，屋上は別館客室のテラスとして使われた。外壁は大谷石を積み，破れ目地を見せる。当初は敷地の最後部に位置し，海岸に面して建っていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005598"},{"id":"00005596","register_sub_id":"101","register_pk":"106584","name":"喜八屋旅館旧館","kana":"きはちやりょかんきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市小木町55-1他","lat":37.816372,"lng":138.279633,"geo_status":"db","era":"明治38／昭和3増築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造5階建、鉄板葺、建築面積115㎡","structure_material":"木造5階建","registered":"2006.08.03(平成18.08.03)","register_no":"15 － 0201","desc":"小木港海岸線に平行して通る国道に西面して建つ。桁行１２．１ｍ，梁間９．１ｍの規模で，木造５階建，寄棟造，鉄板葺とする。１階に居間等を配し，２階，４階，５階を客室とする。２階正面はせり出しとし，３階以上は増築であり，旧正面の形式を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005596"},{"id":"00005597","register_sub_id":"101","register_pk":"106585","name":"喜八屋旅館別館（裏三階）","kana":"きはちやりょかんべっかん（うらさんかい）","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県佐渡市小木町55-1他","lat":37.816273,"lng":138.2798,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造3階建、鉄板葺、建築面積43㎡","structure_material":"木造3階建","registered":"2006.08.03(平成18.08.03)","register_no":"15 － 0202","desc":"旧館の東裏に建ち，桁行８．２ｍ，梁間４．５ｍの規模で，木造３階建，寄棟造，鉄板葺，平入とする。１階を物置，２階を新館への通路等，３階を客室２間とする。東側の海の眺望を重視して建てられ，眺望を確保しようとする当時の旅館の姿を知ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005597"},{"id":"00006448","register_sub_id":"101","register_pk":"107431","name":"旧石崎家住宅（石泉荘）離れ座敷","kana":"きゅういしざきけじゅうたく（せきせんそう）はなれざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新発田市諏訪町3-11-21","lat":37.941097,"lng":139.328537,"geo_status":"db","era":"明治38／昭和初期増築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"15 － 0261","desc":"屋敷地内を南北に流れる新発田川の右岸に建つ。もと料亭の離れ座敷。主体部は桁行４間半、梁間２間半、南北棟、切妻造、桟瓦葺の木造平屋建で、南・西面に縁を廻し、東面に玄関、北面に水回り、北西川端に４畳半を張り出す。川に対して開放的なつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006448"},{"id":"00013518","register_sub_id":"101","register_pk":"504882","name":"旧片桐家住宅主屋","kana":"きゅうかたぎりけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区上大川前通十二番町2742-3","lat":37.92859167,"lng":139.04890278,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0531","desc":"新潟市の中心部に建つ商家。平屋建正面寄棟造背面切妻造桟瓦葺。角地に建ち、東正面はガラス戸を建て中央を戸口とし、南側面は板壁とする。玄関脇をミセとし、奥を二列六室として手前上手に座敷をおく。庭木等とともに表通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013518"},{"id":"00013519","register_sub_id":"101","register_pk":"504883","name":"旧片桐家住宅土蔵","kana":"きゅうかたぎりけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区上大川前通十二番町2742-1","lat":37.92861667,"lng":139.048725,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0532","desc":"主屋の西背後に建つ。二階建切妻造桟瓦葺。周囲の下屋は後の改修。平入の戸口を掛子塗の開戸とし、通りに面した妻側に引違いの窓を開ける。一、二階とも一室で柱間に板を張る。小屋は和小屋で中央の小屋梁を短い梁で受ける。主屋とともに通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013519"},{"id":"00015166","register_sub_id":"101","register_pk":"530590","name":"旧割烹有明奥棟","kana":"きゅうかっぽうありあけおくとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区古町通九番町1463","lat":37.92563333,"lng":139.04627778,"geo_status":"db","era":"昭和3年／昭和33年・同40年代・令和3年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"15 - 0597","desc":"中棟の西に位置する奥棟。二階建片寄棟造桟瓦葺の東に切妻造を接続し全体Ｌ字の棟とする。北側路地に面する外観は竪板張、格子窓、丸太垂木の庇など数寄屋風。内部一階は土間と小上り、二階に床構え付き座敷を三室配し、床柱に銘木を用いた華やかな料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015166"},{"id":"00015164","register_sub_id":"101","register_pk":"530588","name":"旧割烹有明表棟","kana":"きゅうかっぽうありあけおもてとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区古町通九番町1463","lat":37.92564722,"lng":139.04619722,"geo_status":"db","era":"明治43年／昭和33年増築、同40年代改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積222㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"15 - 0595","desc":"古町の東新道に東面する旧料亭の表棟。二階建寄棟造妻入桟瓦葺で、正面北寄りに起り付き入母屋玄関を付し、北側路地に二階壁面を張出す。二階は南面側に四室の続き間を配し、各室には床と棚を設え、室境に千鳥などの透し彫の板欄間を飾った上質な料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015164"},{"id":"00015165","register_sub_id":"101","register_pk":"530589","name":"旧割烹有明中棟","kana":"きゅうかっぽうありあけなかとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市中央区古町通九番町1463","lat":37.92563611,"lng":139.04623333,"geo_status":"db","era":"大正13年／昭和33年増築、令和4年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"15 - 0596","desc":"表棟の西に中庭を挟んで位置する座敷棟。二階建寄棟造平入桟瓦葺で、表棟と渡り廊下で繋ぐ。二階に配する十八畳の客間は、床、棚、平書院を備え、床柱に大径の瘤付丸太を用い、床脇に円窓を開けるなど数寄屋風の意匠とし、大正の豪気な気風を伝える料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015165"},{"id":"00014350","register_sub_id":"101","register_pk":"511339","name":"旧酢屋呉服店店舗兼主屋","kana":"きゅうすやごふくてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県上越市中央三丁目976-2","lat":37.17825,"lng":138.24493611,"geo_status":"db","era":"明治41年／昭和前期改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、鉄板葺、建築面積192㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0573","desc":"直江津の中町通に西面する呉服店の店舗兼住宅。土蔵が通りから後退するため、店舗正側面の入母屋造、軒の出桁造、霧除庇の豪壮な外観を見せる。正面雁木、内蔵が面する茶の間吹抜は雪国らしい構成。二階二〇畳座敷は客を招いて祇園祭を高欄越しに観覧した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014350"},{"id":"00004950","register_sub_id":"101","register_pk":"105940","name":"旧第四銀行住吉町支店","kana":"きゅうだいしぎんこうすみよしちょうしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区柳島町2-10","lat":37.93053359,"lng":139.05808489,"geo_status":"db","era":"昭和2／平成15移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積537㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2005.11.10(平成17.11.10)","register_no":"15 － 0186","desc":"重厚な古典主義様式の銀行建築。２階建で，躯体は鉄筋コンクリート造，外壁に花崗岩を張って石造風とし，コーニスを廻す。正面入口にはイオニア式列柱４本を並べ，柱間の壁上部アーチ型窓とする。当初の外装材，内部の造作をよく保存している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004950"},{"id":"00007736","register_sub_id":"101","register_pk":"108718","name":"旧高野寫眞舘（高野家住宅主屋）","kana":"きゅうたかのしゃしんかん（たかのけじゅうたくしゅおく）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県糸魚川市大町2-101-1他","lat":37.0454317,"lng":137.86141074,"geo_status":"db","era":"昭和3／昭和29改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積228㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0312","desc":"糸魚川駅前の市街地に東面して建つ。桁行１５ｍ梁間９．９ｍの鉄筋コンクリート造２階建で、正面に玄関ポ－チ、背面に物置、北面に土蔵などを付設。寄棟造妻入桟瓦葺。外壁はモルタル塗で、柱型をあらわし、軒蛇腹をまわす。簡明な意匠になる昭和初期の写真館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007736"},{"id":"00010758","register_sub_id":"101","register_pk":"201593","name":"旧外山虎松商店店舗兼主屋","kana":"きゅうとやまとらまつしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県三条市神明町1669","lat":37.629541,"lng":138.961391,"geo_status":"db","era":"昭和27頃／昭和40年代・平成26改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積99㎡、塀付","structure_material":"木造2階一部平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"15 ‐ 0419","desc":"五十嵐川沿いの三条市街地に所在し、三叉路の角地に建つ。木造二階建で、通りに面して縦長窓を配したパラペットを立上げ、コーニスを廻らせる。北辺には看板を取り付けた塀が続く。戦後間もなく復興した商店建築で、地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010758"},{"id":"00010275","register_sub_id":"101","register_pk":"199048","name":"旧新光屋米店精米所","kana":"きゅうにっこうやこめてんせいまいじょ","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県三条市仲之町1800","lat":37.62959587,"lng":138.9633021,"geo_status":"db","era":"大正期／平成25年改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積120㎡","structure_material":"煉瓦造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"15-0392","desc":"店舗兼主屋の背面に南北棟で建つ。煉瓦造平屋建で、壁面はイギリス積としてコーニスを廻らし、出入口上部を半円アーチ、窓などの開口部分は欠円アーチとする。小屋組はキングポストトラスを組む。三条市中心部において希少な、戦前期に遡る煉瓦造建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010275"},{"id":"00010274","register_sub_id":"101","register_pk":"199047","name":"旧新光屋米店店舗兼主屋","kana":"きゅうにっこうやこめてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市仲之町1800","lat":37.629468,"lng":138.96331387,"geo_status":"db","era":"昭和3年頃／昭和中期・平成25年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"15-0391","desc":"市街中心の商店街に南面して建つ二階建町家で、入母屋の妻面を見せる。一階正面を雁木状の歩道、内部手前を土間のミセとし、東に通り土間を通して奥に事務室が続き、二階は座敷を配する。高い内部空間をもち、平面形式などに地方的特色を備えた近代の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010274"},{"id":"00014790","register_sub_id":"101","register_pk":"519048","name":"旧若林医院西洋館","kana":"きゅうわかばやしいいんせいようかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県佐渡市畑野字高野甲717-2","lat":37.98687222,"lng":138.38888056,"geo_status":"db","era":"大正2年頃","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0594","desc":"日本館北西に接続する２階建寄棟造の南北棟。北妻窓上部の軒を切上げ切妻破風を付す。南西に玄関を設け、各階幅１間の片廊下の西に部屋を配し、１階は続き間座敷、２階は２室の洋室とする。通りに面したスティックスタイルの外観が地域の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014790"},{"id":"00014789","register_sub_id":"101","register_pk":"519047","name":"旧若林医院日本館","kana":"きゅうわかばやしいいんにほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県佐渡市畑野字高野甲717-2","lat":37.98676389,"lng":138.38885,"geo_status":"db","era":"大正2年頃","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積151㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0593","desc":"小倉川北岸の角地に位置するかつての医院。２階建入母屋造平入桟瓦葺の日本館は南面に大小の玄関を設け、切妻造屋根を付す。一階は東西に中廊下を通し北東隅を土間の診療室とし、二階には座敷を３室配す。ガラス戸を多く用いた外観が地域景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014789"},{"id":"00012138","register_sub_id":"101","register_pk":"352937","name":"越乃雪本舗大和屋店舗兼主屋","kana":"こしのゆきほんぽやまとやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県長岡市柳原町3-3","lat":37.446242,"lng":138.844136,"geo_status":"db","era":"昭和22年頃／昭和20年代後半・昭和40年頃増築、昭和56年改修","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造2階建、瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"15 - 0473","desc":"市街地に位置する。木造二階建で、一階は前面土間で、通り土間に沿ってミセ、ブツマ、居室を、二階に二室を設ける。ミセには竹や磨き丸太を用いた床の間を設け、数寄屋風の意匠をみせる。切妻造妻入で、正面に雁木を付し、伝統的な表構えをもつ商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012138"},{"id":"00011097","register_sub_id":"101","register_pk":"205204","name":"小松屋旅館奥座敷棟","kana":"こまつやりょかんおくざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛681","lat":37.73706,"lng":138.837954,"geo_status":"db","era":"昭和32／昭和45・同53改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造2階建、瓦葺一部鉄板葺、建築面積84㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0439","desc":"本館の西側にあり、渡廊下によって接続される。木造二階建、南北方向の棟とし、南側は入母屋造、北側は切妻造とする。周囲を庭に囲まれ上質な空間を創出している。階段や床の間などにケヤキ材を多用するとともに、面皮や皮付材なども用い凝った造作としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011097"},{"id":"00011096","register_sub_id":"101","register_pk":"205203","name":"小松屋旅館表座敷棟","kana":"こまつやりょかんおもてざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛681","lat":37.736914,"lng":138.838234,"geo_status":"db","era":"大正14／昭和45・同53改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0438","desc":"敷地の南側、本館に向かって左側に東西棟で建つ。木造平屋建、入母屋造桟瓦葺で、中庭に面して閑静な佇まいをみせている。床の間の落掛、狆潜り、違棚の束や筆返しなどに、敷地内にあった老木からとったという黒柿を多用しており、凝った造作となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011096"},{"id":"00011095","register_sub_id":"101","register_pk":"205202","name":"小松屋旅館広間棟","kana":"こまつやりょかんひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛681","lat":37.736952,"lng":138.838082,"geo_status":"db","era":"大正3／昭和45改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0437","desc":"本館の南東に接続して建ち、東西に庭を配して落ち着いた佇まいをみせる。切妻造桟瓦葺、平屋建、南北棟である。床柱に神代欅、天袋框に黒柿など銘木を用いながらも平明な構成としている。また八畳の天井は三枚の板で張られており、大胆な意匠となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011095"},{"id":"00011094","register_sub_id":"101","register_pk":"205201","name":"小松屋旅館本館","kana":"こまつやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛681","lat":37.737017,"lng":138.838193,"geo_status":"db","era":"昭和26／昭和45・同53改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0436","desc":"彌彦神社参詣の宿場として栄えた岩室温泉にある老舗旅館。北国街道から少し奥まった位置に東面して建ち、入母屋造の玄関を突き出す。屋根は東側を入母屋造、西側を切妻造とする。二階には客室三室を並べ、要所に銘木を用い、凝った造作としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011094"},{"id":"00001570","register_sub_id":"101","register_pk":"102560","name":"佐野商店店舗兼住宅","kana":"さのしょうてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区沼垂東4-5622","lat":37.92336128,"lng":139.06763724,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0042","desc":"雑貨商を営む佐野商店の店舗兼住宅で，木造総二階建，寄棟造・桟瓦葺で，昭和１２年の建設と伝える。軒をせがい造りとし，一階・二階の開口部に庇を設け，外壁を縦板張とする。直交する街路の一角に建ち，この地域の伝統的な町家の形式をよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001570"},{"id":"00008842","register_sub_id":"101","register_pk":"162285","name":"三条市水道局大崎浄水場送水ポンプ室","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうそうすいぽんぷしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60896509,"lng":138.99710529,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋一部地下1階建、建築面積199㎡","structure_material":"鉄筋コンクリート造平屋一部地下1階建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0351","desc":"調整池の北側に建ち、浄水を配水池に圧送する施設。鉄筋コンクリート造平屋建、一部地下1階、東西20ｍ南北11.4ｍ、西面に玄関を突出する。外壁は漆喰仕上げで窓に半円アーチを象り、内部は腰壁をタイル張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008842"},{"id":"00008840","register_sub_id":"101","register_pk":"162283","name":"三条市水道局大崎浄水場着水井（送水井）","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうちゃくすいせい（そうすいせい）","category":"産業3次","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60869924,"lng":138.99758401,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、面積10㎡","structure_material":"鉄筋コンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0349","desc":"ろ過池の東北隅に位置する。鉄筋コンクリート造、内径3.6ｍル深さ1.8ｍの円筒形の井戸で、取水ポンプ場からの水を受ける着水井と、ろ過池への送水井の役割を兼ねる。ろ過池とともに浄水場機能の中核を担う施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008840"},{"id":"00008841","register_sub_id":"101","register_pk":"162284","name":"三条市水道局大崎浄水場調整池","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうちょうせいち","category":"産業3次","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60881678,"lng":138.99723184,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、面積132㎡","structure_material":"鉄筋コンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0350","desc":"送水ポンプ室の南側に位置し、浄水を一時的に貯える施設。鉄筋コンクリート造、東西9.1ｍ南北14.5ｍ深さ3.6ｍで、上部をコンクリート造の屋根と盛土で閉塞し、6基の換気筒を配する。配水池とともに浄水場の最終工程を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008841"},{"id":"00008843","register_sub_id":"101","register_pk":"162286","name":"三条市水道局大崎浄水場配水池","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうはいすいち","category":"産業3次","subcategory":"土木構造物","type_guess":"発電・機械","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新2409-3","lat":37.61037846,"lng":138.99711932,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"コンクリート造、面積1344㎡、機械室付","structure_material":"コンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0352","desc":"浄水を貯える施設で敷地北端の丘の上に位置する。コンクリート造、東西２４ｍ南北２８ｍ深さ４．２ｍの二池が東西に並ぶ。上部の盛土上に３６基の換気筒を配し、南面中央に鉄筋コンクリート造平屋建で軽快な意匠の機械室を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008843"},{"id":"00008845","register_sub_id":"101","register_pk":"162288","name":"三条市水道局大崎浄水場門","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.6085658,"lng":138.99726374,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"石造及びコンクリート造、延長13m","structure_material":"石造及びコンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0354","desc":"浄水場敷地の西面中央に開く。花崗岩積でコンクリートを充填した高さ１．８ｍの親柱を４．４ｍ間隔で配し、その左右に袖壁を矩折れに延ばして６本の副柱を配し、モルタル洗出し仕上げとする。堂々とした造りで、昭和初期の浄水場施設の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008845"},{"id":"00008844","register_sub_id":"101","register_pk":"162287","name":"三条市水道局大崎浄水場量水器室","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうりょうすいきしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.61041369,"lng":138.99645568,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積3.9㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0353","desc":"配水池の西側に建つ。鉄筋コンクリート造平屋建、東西１．８ｍ南北２．０ｍである。外壁は洗出し仕上げで軒蛇腹を廻らし、出入口に庇を付ける。内部は漆喰塗りで中央背面寄りに量水器の土台を残す。簡素ながらも瀟洒な意匠で、景観に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008844"},{"id":"00012726","register_sub_id":"101","register_pk":"367629","name":"島道鉱泉主屋","kana":"しまみちこうせんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県糸魚川市大字島道字大沢獄3541-47","lat":37.08043389,"lng":138.02752278,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"15 － 495","desc":"市東部の山中にある温浴保養施設。主屋は敷地西端に北面して建つ。切妻造セメント瓦葺、総二階建で上下階とも北西二面に廊下を廻し、中央に中廊下を通して東西各2室を設ける。正面全面を掃出しとするなど開放的につくる。伝統的な湯治場の風情を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012726"},{"id":"00012727","register_sub_id":"101","register_pk":"367630","name":"島道鉱泉離れ","kana":"しまみちこうせんはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県糸魚川市大字島道字大沢獄3541-47","lat":37.08043389,"lng":138.02752278,"geo_status":"db","era":"昭和16年頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、瓦葺、建築面積41㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"15 － 496","desc":"主屋背面の西端に接続して建つ。南北棟の切妻造セメント瓦葺、外壁下見板張。上下階とも主屋とつながる廊下を東端に通し、1階に広間、2階に座敷2室を設ける。東面全面を掃出しとするなど開放的につくる。主屋とともに伝統的な湯治場の風情を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012727"},{"id":"00012513","register_sub_id":"101","register_pk":"367808","name":"すき焼八木店舗","kana":"すきやきやぎてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新発田市中央町三丁目甲1316-1他","lat":37.94836,"lng":139.325531,"geo_status":"geocoded","era":"昭和10年頃／昭和15年増築、昭和49年･平成18年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積104㎡、塀付","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"15 － 0487","desc":"市中心部の街路に北面して建つ商店。切妻造桟瓦葺の総二階建で、正面西半を後退させて玄関を設け、東半に店舗、茶の間、仏間の三室、二階に和室4室を配する。銘木を用いた座敷飾や縁側の色硝子など、戦前の都市部における店舗兼住宅の様相をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012513"},{"id":"00010430","register_sub_id":"101","register_pk":"199389","name":"清廣館本館","kana":"せいこうかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県阿賀野市出湯字寺山802子他","lat":37.817835,"lng":139.30075,"geo_status":"db","era":"昭和3頃／昭和40頃・昭和50・平成20改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造3階建、瓦葺、建築面積257㎡","structure_material":"木造3階建","registered":"2015.03.26(平成27.03.26)","register_no":"15 － 0399","desc":"出湯温泉の温泉旅館。木造三階建、入母屋造の大規模な建物でＬ字形平面を持つ。客室の内部は部屋毎に床柱などの材種を変え、銘木を多用した数寄屋風の意匠となる。上階は軒を出桁造とし、ガラス窓を並べて手摺を設け、湯治宿に相応しく風情ある外観を見せる","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010430"},{"id":"00011107","register_sub_id":"101","register_pk":"205214","name":"瀬賀惣一郎商店倉庫","kana":"せがそういちろうしょうてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県村上市塩谷1234","lat":38.156398,"lng":139.414555,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積24㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0449","desc":"店舗兼主屋の北に並び建つ。鉄筋コンクリート造二階建で主屋兼店舗側に開口部を開く。外壁は人造石洗出仕上で石造風の目地を入れ、妻壁はやや簡略化したペディメント風につくり、窓下部にアールデコ風の装飾を付けるなど当地域に珍しい近代的な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011107"},{"id":"00011106","register_sub_id":"101","register_pk":"205213","name":"瀬賀惣一郎商店店舗兼主屋","kana":"せがそういちろうしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県村上市塩谷1234","lat":38.156301,"lng":139.414592,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積279㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0448","desc":"塩谷集落の南、通りに西面して建つ。木造二階建桟瓦葺で通りに妻を向け、正面に下屋を付すなど当地域共通の特徴を示すが、屋根を入母屋造とし、二階に建具を並べるなど発展した形態を見せる。内部吹抜の梁や、上質なしつらえの座敷の造作が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011106"},{"id":"00005114","register_sub_id":"101","register_pk":"106104","name":"早撰堂菓子店主屋","kana":"そうせんどうかしてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市大町1510","lat":38.22462979,"lng":139.47848069,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"15 － 0191","desc":"村上城下の目抜き通りに東面して建つ。桁行３間，梁間１０間の規模で，南北棟，切妻造，桟瓦葺の２階建町家。内部は１階にミセ，チャノマ等を並べ，２階はチャノマ上部吹抜けの前後にマエニカイ等を配する。棟梁は増田寅吉。通りの歴史的景観要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005114"},{"id":"00004341","register_sub_id":"101","register_pk":"105331","name":"髙橋あめや主屋","kana":"たかはしあめやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県上越市南本町3-81","lat":37.10159539,"lng":138.2451218,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積109㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"15 － 0172","desc":"北国街道に面する切妻造，平入の町家で，正面に雁木を設け，その上方に２階の格子窓を見せる。１階内部は土間床のミセを正面に構え，奥に事務室が続き，２階は通りに面して座敷２室を並べる。雪国における商家の表構えをよく残す町家建築として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004341"},{"id":"00011099","register_sub_id":"101","register_pk":"205206","name":"つるがや店舗兼主屋","kana":"つるがやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県三条市本町四丁目601","lat":37.629671,"lng":138.952732,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0441","desc":"三条の中心市街に所在する。通りに南面して建ち、妻入とする。正面にせがい造の入母屋屋根を見せ、当地の町家の特色を良く示す。内部は手前に店舗、奥に通り土間を通して吹き抜けのチャノマと、ネマを配する。二階には丁寧な造作になる座敷を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011099"},{"id":"00001595","register_sub_id":"101","register_pk":"102585","name":"鍋茶屋応接室棟","kana":"なべぢゃやおうせつしつとう","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92385017,"lng":139.04607393,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造一部鉄筋コンクリート造3階建、瓦葺、建築面積48㎡","structure_material":"木造一部鉄筋コンクリート造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0067","desc":"主屋の南側に位置する。１階はＲＣ造で，外壁石張の洋間には矩形上げ下げ窓とステンドグラスの入った２連の尖頭アーチ型窓が付けられる。精緻な細工を凝らした漆喰天井や装飾照明が，内部空間に華美な趣を与える。２，３階は木造の和風。設計施工は清水組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001595"},{"id":"00001597","register_sub_id":"101","register_pk":"102587","name":"鍋茶屋表門及び外塀","kana":"なべぢゃやおもてもんおよびそとべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92412972,"lng":139.04596227,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、間口2.6m、外塀延長35m","structure_material":"鉄筋コンクリート造","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0069","desc":"敷地西面の通称鍋茶屋通りに面して建つ。表門は片流れ桟瓦葺。外塀には，表門と同様に，腰壁石積にＲＣ造壁面が載り，上下の接続部をリシン仕上げとする。縦格子の開口部によって，門と壁の意匠的統一性がさらに図られる。離れ座敷と共に清水組による施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001597"},{"id":"00001594","register_sub_id":"101","register_pk":"102584","name":"鍋茶屋主屋","kana":"なべぢゃやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92416238,"lng":139.04626969,"geo_status":"db","era":"明治43／昭和12増改築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造3階建、瓦葺、建築面積1251㎡","structure_material":"木造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0066","desc":"鍋茶屋は幕末期創業と伝わる料亭である。主屋は概ねＨ字型に構成され，南側の東西棟部分以外が昭和１２年に清水組によって増築される。１階から３階に向かって規模が大きくなる各室では，欄間・棚等に多様な意匠が施され，近代和風の粋が凝らされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001594"},{"id":"00001598","register_sub_id":"101","register_pk":"102588","name":"鍋茶屋土蔵","kana":"なべぢゃやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92401749,"lng":139.04633696,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積43㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0070","desc":"主屋と並び，建物群に埋め尽くされた敷地の東部に位置する。新建材で覆われる外部東面は，妻面と開口部に土蔵造りの痕跡を残す。２階中央部の棟木と母屋を支える大梁に自然木の極端な曲り材を用い，内部空間の見所を作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001598"},{"id":"00001596","register_sub_id":"101","register_pk":"102586","name":"鍋茶屋離れ座敷","kana":"なべぢゃやはなれざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.9238211,"lng":139.04622239,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0068","desc":"敷地の南東端に位置する。木造２階建，瓦葺。１階には座敷の他に茶室，２階は二間続きの座敷を配し，全体的に数寄屋風の意匠でまとめられる。道路を望む広い開口部及び細い水平材と束の組合わせからなる繊細な妻飾りが，街路の景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001596"},{"id":"00001600","register_sub_id":"101","register_pk":"102590","name":"鍋茶屋離れ土蔵","kana":"なべぢゃやはなれどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92427379,"lng":139.04603802,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積72㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0072","desc":"敷地の北西端，主屋と中庭を挟んで建つ。現在，食堂として使われる。土蔵造２階建，切妻桟瓦葺。腰の海鼠壁の上を漆喰塗りとし，１・２階に形式・意匠を同じくする観音開き扉を配す。広大な敷地を持つ鍋茶屋正面の隅部を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001600"},{"id":"00001599","register_sub_id":"101","register_pk":"102589","name":"鍋茶屋煉瓦蔵","kana":"なべぢゃやれんがぞう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区東堀通8-1420","lat":37.92394921,"lng":139.04632434,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積63㎡","structure_material":"煉瓦造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0071","desc":"敷地東部で，離れ座敷と土蔵に挟まれて建つ。煉瓦造平屋建で，壁面は小口積で作られる。片流れ桟瓦葺の屋根の上に，防火・目隠用の煉瓦壁を立ち上げる。土蔵と同じく外壁を介せずに東堀通りに面し，主屋・離れ座敷と共に街路に多様な景観をもたらしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001599"},{"id":"00013702","register_sub_id":"101","register_pk":"505227","name":"長谷川家住宅双子蔵","kana":"はせがわけじゅうたくふたごくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新発田市大栄町七丁目甲317-1","lat":37.94631944,"lng":139.32765833,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積105㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"15 － 546","desc":"市の中心部に位置。南北二棟の土蔵全体を桟瓦葺の置屋根で覆い一体とする。土蔵はいずれも東西棟で二階建切妻造。東面の開戸を掛子塗とするなど見応えがある。小屋組は棟木で断面の太い垂木を受ける。二蔵を大屋根で覆う特徴的な外観が地域の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013702"},{"id":"00011917","register_sub_id":"101","register_pk":"210924","name":"平久呉服店店舗兼主屋","kana":"ひらきゅうごふくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新発田市御幸町一丁目甲824-1他","lat":37.94817,"lng":139.323293,"geo_status":"db","era":"昭和10年頃／昭和57年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積66㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-459","desc":"中心市街地の御幸町の角地に南面する。一階には通りに面して矩折れに土間を設け、ミセや茶の間、和室を配し、二階には床の間・床脇を備えた座敷や数寄屋風の下地窓のある和室を設け、接客にあてた。採光のため廻らされたガラス窓が外観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011917"},{"id":"00003078","register_sub_id":"101","register_pk":"104068","name":"益甚酒店店舗","kana":"ますじんさけてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県村上市大町194","lat":38.22421861,"lng":139.47866154,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積114㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"15 － 0139","desc":"旧村上城下町人地の中心的通りに西面して建つ。南北棟，切妻造，桟瓦葺，平入の２階建店舗で，間口は５間半とし，１階店舗の奥に平屋建の１２畳と通り土間が付属し，２階は６畳６畳８畳の３室が並ぶ。たちの高いつくりが昭和初期町家の特徴をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003078"},{"id":"00006124","register_sub_id":"101","register_pk":"107108","name":"山上染物店主屋","kana":"やまがみそめものてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市肴町1985","lat":38.223911,"lng":139.46994,"geo_status":"db","era":"明治初期／昭和55・平成17改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積101㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"15 － 0254","desc":"県道沿いに北面して建つ。桁行４間，梁間７間規模で，木造２階建，切妻造，桟瓦葺。１階前方を店とし，東端に土間を通し，土間沿いに茶の間・台所を並べ，２階にオモテニカイ等を配する。もとは石置屋根で緩い屋根勾配を特徴とし，街道沿いの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006124"},{"id":"00013979","register_sub_id":"101","register_pk":"508239","name":"山重本店店舗","kana":"やまじゅうほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県加茂市仲町236","lat":37.65761667,"lng":139.05505,"geo_status":"db","era":"明治後期／昭和38年・同40年増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺一部鉄板葺、建築面積523㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0560","desc":"加茂山北麓から市街を見下ろす料亭で、斜面を利用して上段の店舗棟と下段の喫茶棟の各二階建が接続する。店舗上階の長細い大広間は南と北に縁が通り、元は襖で小間に仕切って使った。店舗棟西端に広間、喫茶棟に小間の客室を配す。近代料亭の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013979"},{"id":"00008660","register_sub_id":"101","register_pk":"149381","name":"吉乃川酒造常倉","kana":"よしのがわしゅぞうじょうくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋4-2247","lat":37.41672118,"lng":138.84103699,"geo_status":"db","era":"大正12年／昭和3年改修","year":1923,"year_source":"converted","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積546㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0333","desc":"県道の東側に南北棟で建つ倉庫。桁行34ｍ梁間16ｍの鉄筋コンクリート造、小屋は鉄骨トラス組とする。切妻造で、ＲＣ造天井スラブ上に鉄板を張り、2ヶ所に越屋根を載せる。2階の部屋はトラス陸梁から鉄筋で吊される。醸造業の近代化を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008660"},{"id":"00011916","register_sub_id":"101","register_pk":"210923","name":"吉原写真館","kana":"よしはらしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新発田市大手町二丁目1286","lat":37.951417,"lng":139.321401,"geo_status":"db","era":"昭和11年／昭和47年増築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造3階建、瓦葺、建築面積175㎡","structure_material":"木造3階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-458","desc":"大手町に南面する。木造三階建で、二階には傾斜した大窓より自然光を取り入れたスタジオや床の間・床脇のある座敷がよく残る。外壁をモルタル仕上げとし、一階正面腰壁のスクラッチタイル貼や水平性を強調した庇や丸窓など、幾何学的な意匠を特徴とする外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011916"},{"id":"00009259","register_sub_id":"101","register_pk":"194052","name":"嵐渓荘緑風館","kana":"らんけいそうりょくふうかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市長野1680-1","lat":37.52675255,"lng":139.11817141,"geo_status":"db","era":"昭和8年頃／昭和30年頃移築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造3階建、瓦葺、建築面積140㎡、望楼付","structure_material":"木造3階建","registered":"2012.08.13(平成24.08.13)","register_no":"15 － 0374","desc":"山間部の川沿いに建つ。木造三階建、建築面積一四〇平方メートル、入母屋造鉄板葺で、頂部に望楼を載せる。外壁は簓子下見板張とし、各階に庇を廻らせる。内部客室は部屋ごとに座敷飾りの意匠を違え、瀟洒なつくりとする。風情ある一軒宿の温泉旅館である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009259"},{"id":"00004742","register_sub_id":"101","register_pk":"105732","name":"凌雲閣松之山ホテル本館","kana":"りょううんかくまつのやまほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県十日町市松之山天水越81","lat":37.06229796,"lng":138.59965614,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造3階建、瓦葺、建築面積514㎡","structure_material":"木造3階建","registered":"2005.07.12(平成17.07.12)","register_no":"15 － 0185","desc":"山間部の高台に建つ温泉旅館の本館。３階建，入母屋造，桟瓦葺で正面中央に車寄せ玄関を突出させ，大屋根に千鳥破風を付す。客室をはじめ客溜りや階段室も銘木を使い，座敷飾りや欄間，天井造作など手の込んだ細工になる。内外とも風格ある佇まいをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004742"},{"id":"00007345","register_sub_id":"101","register_pk":"108327","name":"料亭宇喜世北門","kana":"りょうていうきよきたもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市仲町三丁目字下田端169他","lat":37.11194514,"lng":138.24259662,"geo_status":"db","era":"昭和前期／昭和26頃改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、茅葺、間口4.3m","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"15 － 0309","desc":"本館玄関の正面、大門通りに面して建つ。茅葺屋根をもつ間口４．３ｍの腕木門。柱や楣、束等は八角断面で、名栗仕上げとする。腕木や桁は角材。軒には磨き丸太の半割を並べる。扉は両開板戸。茅葺の落ち着いた佇まいになり、料亭の表構えを特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007345"},{"id":"00007346","register_sub_id":"101","register_pk":"108328","name":"料亭宇喜世東門","kana":"りょうていうきよひがしもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県上越市仲町三丁目字下田端169他","lat":37.111897,"lng":138.242905,"geo_status":"db","era":"昭和26頃","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造、銅板葺、間口2.9m","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"15 － 0310","desc":"本館東端の北側、仲町通りに東面して建つ。南北棟の銅板葺切妻屋根が載る間口２．９ｍの腕木門。柱や楣、棟木、桁などに磨き丸太を用い、軒は一軒疎垂木。両開板戸を吊る。軽快な意匠になり、主屋や北門とともに街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007346"},{"id":"00007344","register_sub_id":"101","register_pk":"108326","name":"料亭宇喜世本館","kana":"りょうていうきよほんかん","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県上越市仲町三丁目字下田端169他","lat":37.11180583,"lng":138.24258241,"geo_status":"db","era":"明治中期／昭和前期改修・昭和13増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階一部3階建、瓦葺一部鉄板葺、建築面積550㎡","structure_material":"木造2階一部3階建","registered":"2008.10.23(平成20.10.23)","register_no":"15 － 0308","desc":"木造２階一部３階建の桟瓦葺一部鉄板葺、東西３７ｍ南北１４ｍで、北面西端に突出部を設けるＬ字型の平面になる。北面中央西寄りには唐破風造屋根の玄関を付ける。２階の１５３畳に及ぶ大広間や、部屋ごとに意匠を違える３階客間などをもつ。近代料亭建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007344"},{"id":"00011930","register_sub_id":"101","register_pk":"210937","name":"料亭南都屋","kana":"りょうていなんとや","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県胎内市本町2858他","lat":38.051832,"lng":139.402779,"geo_status":"db","era":"昭和4年／平成15年曳家","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積226㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-472","desc":"木造二階建、入母屋造、桟瓦葺で、正面に入母屋造の玄関と右側に切妻造の前の間を張り出す。内部は、一階に三室続きの中の間や応接室を配し、二階は五九畳半の大広間とする。小屋組は洋小屋であり、造作材に米松や地松の良材を用い洗練された意匠の料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011930"},{"id":"00011676","register_sub_id":"101","register_pk":"210692","name":"荒町庵（旧米田楼）","kana":"あらまちいおり（きゅうよねだろう）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県南砺市城端字西下町185","lat":36.516331,"lng":136.902275,"geo_status":"db","era":"明治後期／昭和2年・同22年・平成28年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積76㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0132","desc":"城端中心地に建つ。当初は米田楼と称する料理屋であった。東西方向に長い敷地に建つ木造二階建、切妻造平入、外壁下見板張で、東面街路側を正面とする。屋根は施釉瓦。正面二階には縁を設けて曳山を眺める空間とする。城端の賑わいを今に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011676"},{"id":"00000760","register_sub_id":"101","register_pk":"101750","name":"井波屋仏壇店","kana":"いなみやぶつだんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県高岡市守山町37-1","lat":36.74697948,"lng":137.01063186,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造２階建，瓦葺，建築面積96㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"16 － 0044","desc":"間口３間，奥行６間半の小規模な店舗で，内部は過半を土間とし背後に部屋をおく。２階は前１間にテラスを設け，中央部は吹き抜けとする。正面意匠は，鋳物製の唐草模様で飾る大きなアーチ窓を置く独特のデザインになり，明治後期の店舗として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000760"},{"id":"00002031","register_sub_id":"101","register_pk":"103021","name":"小沢家住宅店蔵","kana":"おざわけじゅうたくみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県滑川市荒町1618","lat":36.76617566,"lng":137.3374873,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"16 － 0058","desc":"小沢家は明治期より呉服商を営んだ商家である。店蔵は桁行６間・梁間３間・総２階建，切妻造・桟瓦葺で，三代目万治の明治後期に建てられた。黒漆喰塗で観音開扉をもつ重厚な土蔵造で，棟の剣形雪割瓦や鯱，正面の起り屋根の下屋など，地方色も備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002031"},{"id":"00002028","register_sub_id":"101","register_pk":"103018","name":"城戸家住宅主屋","kana":"きどけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県滑川市瀬羽町1862","lat":36.76332659,"lng":137.3355953,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積191㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"16 － 0055","desc":"旧北陸街道沿いに建ち，江戸後期より味噌醤油の醸造業を営んできた商家。主屋は慶応大火後，明治初期に再建。２階建，切妻造，桟瓦葺，平入の形式で，全体に良質の材や銘木を用いる。内部では１階前面に板敷でつくりつけの帳場を持つミセ構えをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002028"},{"id":"00002027","register_sub_id":"101","register_pk":"103017","name":"清都酒造場主屋","kana":"きよとしゅぞうじょうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市京町12-12","lat":36.75617282,"lng":137.01371599,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積176㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"16 － 0054","desc":"旧氷見街道沿いに建つ商家で，清都家が以前からの造り酒屋を購入したのは明治３９年。銘柄「勝駒」は高岡市民に親しまれている。主屋は明治２０年頃の建設と伝え，２階建，切妻造，桟瓦葺，平入で，登り梁や袖壁及び厚板目板打の庇など伝統的な形式である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002027"},{"id":"00001411","register_sub_id":"101","register_pk":"102401","name":"小杉町民展示館（旧小杉貯金銀行本店）","kana":"こすぎちょうみんてんじかん（きゅうこすぎちょきんぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県射水市戸破4286-1","lat":36.72226155,"lng":137.09927992,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積169㎡","structure_material":"土蔵造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"16 － 0049","desc":"地域の有力者の共同出資によって創業した，小杉町の中心的銀行の本館。内部改装の後，現在歴史資料展示館として利用されている。黒塗漆喰壁の土蔵造で，窓には金属性の防火扉が取り付けられている。内部には随所に明治後期の洋風意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001411"},{"id":"00010134","register_sub_id":"101","register_pk":"197967","name":"松風樓一の蔵","kana":"しょうふうろういちのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市福光字川原7471-15","lat":36.560486,"lng":136.875171,"geo_status":"db","era":"昭和前期／昭和26頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"16 － 0098","desc":"敷地北辺西寄りに建つ、土蔵造二階建、切妻造で、置屋根式の桟瓦葺とする。基礎はコンクリート造とし、外壁は漆喰塗で、北面は竪板張とする。南側に戸前の下屋を付け、戸口の扉枠は鳥居形で黒漆喰塗とし、鉄製両開扉を吊り込む。小屋組は垂木小屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010134"},{"id":"00010133","register_sub_id":"101","register_pk":"197966","name":"松風樓西棟","kana":"しょうふうろうにしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県南砺市福光字川原7471-15他","lat":36.560372,"lng":136.875046,"geo_status":"db","era":"明治33／昭和26頃移築・昭和33頃改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積168㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"16 － 0097","desc":"敷地の西寄りに東棟から中庭を介して建つ木造二階建、正面入母屋造で、北に平屋建の浴室、便所が接続する。一階に仏間と次の間を設け、東棟への回廊は南半を土間とし、中間に中庭に通じる戸口を設ける。二階軒の漆喰蛇腹など、当地の茶屋建築の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010133"},{"id":"00010135","register_sub_id":"101","register_pk":"197968","name":"松風樓二の蔵","kana":"しょうふうろうにのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市福光字川原7471-15","lat":36.560522,"lng":136.875103,"geo_status":"db","era":"昭和前期／昭和26頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"16 － 0099","desc":"敷地の北西角に一の蔵と並んで建つ。土蔵造二階建、切妻造で、置屋根式の桟瓦葺とする。基礎はコンクリート造とし、外壁は漆喰塗で、北面と西面は竪板張とする。南側に戸前の下屋を付け、一の蔵の戸前から入る。戸口は片引土戸とする。角地の景観を整える蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010135"},{"id":"00010132","register_sub_id":"101","register_pk":"197965","name":"松風樓東棟","kana":"しょうふうろうひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県南砺市福光字川原7471-8","lat":36.56024,"lng":136.875256,"geo_status":"db","era":"明治33／昭和前期改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積449㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"16 － 0096","desc":"小矢部川の西岸に位置する料理旅館。木造二階建、寄棟造の本館の北に、中庭を介して二階建、寄棟造の離れを増築している。本館一階東側の厨房上の二階を広間とする他は六畳から十畳の客室とする。各室毎に趣向を凝らした造作をもつ近代数寄屋建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010132"},{"id":"00012522","register_sub_id":"101","register_pk":"367817","name":"富山電気ビルディング新館","kana":"とやまでんきびるでぃんぐしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県富山市桜橋通り3","lat":36.696598,"lng":137.216766,"geo_status":"geocoded","era":"昭和31年／昭和38年・同40年増築","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"鉄筋コンクリート造6階地下1階建、建築面積1156㎡","structure_material":"鉄筋コンクリート造6階地下1階建","registered":"2018.11.02(平成30.11.02)","register_no":"16 － 0142","desc":"北面道路沿いに建つ、本館とＬ字形をなす鉄筋コンクリート造６階地下１階建のビル。本館と同じ富永譲吉の設計による全体にシンプルでモダンな意匠が特徴で、本館同様、柱形や窓など機能上の必須要素のみを巧みに構成した外観は増築の違和感を感じさせない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012522"},{"id":"00012521","register_sub_id":"101","register_pk":"367816","name":"富山電気ビルディング本館","kana":"とやまでんきびるでぃんぐほんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県富山市桜橋通り3","lat":36.696598,"lng":137.216766,"geo_status":"geocoded","era":"昭和11年／昭和32年増築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造5階地下1階建、建築面積2087㎡、塔屋付","structure_material":"鉄筋コンクリート造5階地下1階建","registered":"2018.11.02(平成30.11.02)","register_no":"16 － 0141","desc":"富山駅と市街地中心部を結ぶ幹線道路沿いに西面して建つ。鉄筋コンクリート造５階地下１階建で、外観は柱形を並べて垂直性を強調し、中央部を高くして大きなバルコニーをつくり出し、両端に丸窓を設けるなど表情に変化をつける。県内初の本格的オフィスビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012521"},{"id":"00009750","register_sub_id":"101","register_pk":"195579","name":"北陸銀行本店","kana":"ほくりくぎんこうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県富山市堤町通り1-2-9他","lat":36.68909194,"lng":137.21790083,"geo_status":"db","era":"昭和36／昭和48増築","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄骨鉄筋コンクリート造6階地下2階建、建築面積2864㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造6階地下2階建","registered":"2013.12.24(平成25.12.24)","register_no":"16 － 0093","desc":"鉄骨鉄筋コンクリート造六階地下二階建、三階建塔屋付。六層分の柱列を表し、柱間に小割の石を貼詰める。重厚な構造ながら、軽快な外観を構成し、一階では表通りから裏通りの商店街に通じるコロネードを通す。富山市の戦後復興期を象徴する大型事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009750"},{"id":"00002625","register_sub_id":"101","register_pk":"103615","name":"牧田組本社（旧南島商行本店）","kana":"まきたぐみほんしゃ（きゅうみなみじましょうこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県射水市庄西町1-18-33","lat":36.7890097,"lng":137.06783222,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、銅板葺、建築面積81㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"16 － 0066","desc":"富山湾に注ぐ庄川の河口に築かれたオフィスビル。木造躯体に褐色煉瓦を貼り，腰，隅柱，蛇腹などに花崗岩を用いる。前方に張り出し重量感のある石造柱に挟まれた入口を中心に，上げ下げ窓を左右対称に配する外観とする。伏木港における海運の近代化を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002625"},{"id":"00013985","register_sub_id":"101","register_pk":"508245","name":"みなとがわ倉庫","kana":"みなとがわそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県氷見市朝日本町907","lat":36.85281944,"lng":136.98604722,"geo_status":"db","era":"大正後期／昭和中期・平成28年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造平屋建、瓦葺、面積486㎡","structure_material":"土蔵造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"16 - 0157","desc":"氷見市街地の湊川左岸、旧藺製品倉庫の南に北面して建つ長大な土蔵。切妻造桟瓦葺、外壁は下見板張。北面に梁間の大きい戸前を設け東端を荷揚場とする。内部は桁行に六室を並べ、各室北側に額縁黒漆喰塗戸口、南面に高窓を設ける。湊川水運の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013985"},{"id":"00008271","register_sub_id":"101","register_pk":"133913","name":"若井家住宅主屋（旧中越銀行）","kana":"わかいけじゅうたくしゅおく（きゅうちゅうえつぎんこう）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市川原町65-6","lat":36.75033358,"lng":137.0097681,"geo_status":"db","era":"明治35年／大正7年移築","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、瓦葺、建築面積139㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"16 － 0090","desc":"道路に東面する敷地中央に位置する。入母屋造妻入桟瓦葺で正面に深い下屋を出す。桁行１５ｍ梁間９．２ｍの木造２階建。漆喰塗で塗り込め、２階正面には掛子塗の両扉を吊る開口を三ヶ所穿つ。下屋正面両端には洋風の石柱を建てる。近代地方銀行の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008271"},{"id":"00011284","register_sub_id":"101","register_pk":"209120","name":"粟津演舞場","kana":"あわづえんぶじょう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県小松市井口町ヘ10-1他","lat":36.33346,"lng":136.447175,"geo_status":"db","era":"昭和8頃／昭和18頃・平成26改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積319㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0261","desc":"粟津温泉街の中心部に位置する劇場建築。昭和八年粟津温泉で開催された全国旅館組合総会の会場として建設された。正面に入母屋造の大屋根妻面と左右突出部の切妻破風を並べ、中央に起り屋根の玄関を付すなど装飾的に見せる。当時の温泉街の賑わいを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011284"},{"id":"00010584","register_sub_id":"101","register_pk":"201158","name":"石黒商店店舗兼主屋","kana":"いしぐろしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市十間町53他","lat":36.570524,"lng":136.657963,"geo_status":"db","era":"昭和11年頃／昭和41年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積135㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"17－0249","desc":"美術商の店舗兼用住宅として建築された町家。建ちの高い一階正面は、瓦葺の庇の下に銅板葺の小庇を設けて立面を整える。せがい造の軒や、大屋根に付く採光用の越屋根、木部の弁柄塗と黒漆喰壁のコントラストにより華やかな外観を呈し、街並み景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010584"},{"id":"00005432","register_sub_id":"101","register_pk":"106420","name":"角島家住宅店舗及び主屋","kana":"かどしまけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市安江町5-14","lat":36.5760305,"lng":136.65604592,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造3階建、鋼板葺一部瓦葺、建築面積60㎡","structure_material":"木造3階建","registered":"2006.03.27(平成18.03.27)","register_no":"17 － 0152","desc":"北側道路に接して建ち，桁行９．５ｍ，梁間７．６ｍの規模で，木造３階建，切妻造，鋼板葺一部桟瓦葺で，正面１階をタイル貼り，２階以上を銅板張りとし，東端にモルタル塗の外壁を立ち上げる。１階を店舗，２階以上を住宅とし，正面を洋風意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005432"},{"id":"00004356","register_sub_id":"101","register_pk":"105346","name":"北島屋茶店主屋","kana":"きたじまやさてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市一本杉町54","lat":37.04803376,"lng":136.96138217,"geo_status":"db","era":"明治37頃／昭和8改造","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積93㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0122","desc":"住宅として建てられ昭和８年茶舗となる。間口４間奥行６間半，切妻造，桟瓦葺で，１階東に通り庭，西に表からミセの間，居室を１列に並べ，２階には表裏にそれぞれ次の間付座敷をとる。大火以前に遡る稀少な建物で，七尾中心地の歴史的景観に欠かせない町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004356"},{"id":"00004346","register_sub_id":"101","register_pk":"105336","name":"北中家住宅主屋","kana":"きたなかけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市泉二丁目491","lat":36.547143,"lng":136.64090612,"geo_status":"db","era":"江戸末期／大正初期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造及び土蔵造2階建、瓦葺、建築面積241㎡","structure_material":"木造及び土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0112","desc":"市内南部，旧北国街道に東面する味噌・醤油製造販売を営む町家。間口９間奥行９間，２階建，平入，桟瓦葺で，正面のほぼ全面に格子をはめ，２階両端に袖壁を付ける。１階南東隅に座敷蔵を取り込み，木部弁柄漆塗り，色土壁として内外とも質の高い造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004346"},{"id":"00004350","register_sub_id":"101","register_pk":"105340","name":"旧石川銀行橋場支店","kana":"きゅういしかわぎんこうはしばしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市尾張町1-7-10","lat":36.57084281,"lng":136.66370819,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積101㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0116","desc":"浅野川大橋南方の交差点に面した不整形の敷地に建つ。清水組の設計施工で，外観はネオルネサンス式を基調とし，胴蛇腹で上下にほぼ１対２に分割し，出入口はイオニア式の片蓋柱で飾る。曲面で構成される変化のある立面をもち，ランドマークとして目立つ建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004350"},{"id":"00014353","register_sub_id":"101","register_pk":"511342","name":"旧石川県繊維会館","kana":"きゅういしかわけんせんいかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県金沢市西町三番丁16","lat":36.569725,"lng":136.65609167,"geo_status":"db","era":"昭和27年／同59年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、瓦葺、建築面積525㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2022.10.31(令和4.10.31)","register_no":"17 - 0308","desc":"金沢城北西の市街地にある繊維協会の会館で、建築家谷口吉郎の設計。タイル貼白壁を迫出し、細い柱形に見せるコンクリート造で切妻造とし、全体にモダニズムをベースに和風建築の可能性を拓いた建物。階段廻りの亀甲石貼や折鶴形蛍光灯など金沢に相応しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014353"},{"id":"00003532","register_sub_id":"101","register_pk":"104522","name":"旧石川商銀信用組合小松支店","kana":"きゅういしかわしょうぎんしんようくみあいこまつしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県小松市京町19-5","lat":36.40815638,"lng":136.44866755,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積143㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"17 － 0084","desc":"加能合同銀行小松支店として建設と伝える。スクラッチタイル張，コーナーに円筒形の階段室塔屋を配した建築構成に特徴がある。ドリス式オーダーに半円アーチやイオニア式キャピタルなどを組合わせた玄関枠の意匠と内部階段室の螺旋状階段の造形に見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003532"},{"id":"00013787","register_sub_id":"101","register_pk":"507749","name":"旧新保商店主屋","kana":"きゅうしんぼしょうてんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市安江町40-3","lat":36.57345,"lng":136.65544167,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"17 － 0302","desc":"店舗に北接して建つ。切妻造桟瓦葺の二階建町家で、正背面に下屋を付す。正面は出桁造で袖壁を設け、二階に格子窓を開いて一階南側に出格子を設ける。内部は一階は北を土間、南を一列二室、二階は床付座敷二室を配する。店舗と共に商店街の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013787"},{"id":"00013786","register_sub_id":"101","register_pk":"507748","name":"旧新保商店店舗","kana":"きゅうしんぼしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市安江町40-3","lat":36.5734,"lng":136.65544167,"geo_status":"db","era":"明治32年頃／明治後期・昭和前期・平成14年・令和2年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建及び土蔵造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建及び土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"17 － 0301","desc":"横安江町商店街の元履物店。街路に西面して建つ切妻造二階建町家。明治三二年大火後の再建で、焼け残った土蔵を取込んで一連の桟瓦葺大屋根を架け、正背面に下屋を付す。正面は出桁造で袖壁を設け、二階は格子窓を連ねる。明治大火後の商店街の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013786"},{"id":"00012143","register_sub_id":"101","register_pk":"352942","name":"旧高田桶店店舗兼主屋","kana":"きゅうたかだおけてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市扇町134","lat":36.560264,"lng":136.670806,"geo_status":"db","era":"明治後期／平成26年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、金属板葺、建築面積74㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"17-281","desc":"金沢城東方の旧天神町区域に建つ。木造二階建、切妻造平入。間口三間、奥行六間で附属屋を付す。通り土間沿いに店、茶の間、座敷を並べ、二階にアマと座敷を配す。軒高は極めて低く、もと板葺石置屋根の屋根勾配、正面柱の蔀戸痕跡など金沢の古い形式を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012143"},{"id":"00000206","register_sub_id":"101","register_pk":"101196","name":"旧三田商店","kana":"きゅうみたしょうてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市尾張町1-8-5","lat":36.57070741,"lng":136.66295543,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積150㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"17 － 0004","desc":"交差点に面する部分を曲線で処理し、スクラッチタイルを貼る外観は質素であるが、正面の出入口に様式建築の装飾を集中させる点は特徴的である。施主の心意気を受けて施工されたこの建物は、金沢に残る数少ない昭和初期の名物建築として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000206"},{"id":"00003959","register_sub_id":"101","register_pk":"104949","name":"旧村松商店（村松商事ビル）","kana":"きゅうむらまつしょうてん（むらまつしょうじびる）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市尾張町1-111","lat":36.57057314,"lng":136.66290679,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積213㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0089","desc":"老舗糸卸小売商の自社ビル。南，西２方を道路に面する角地に建つ鉄筋コンクリート造の２階建で，南西隅部に塔屋を設ける。パラペット頂部や壁面に釉薬タイルの帯を付け，隅部は太い蛇腹を上下に並べたような壁仕上げとしアールデコ調の特徴ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003959"},{"id":"00011488","register_sub_id":"101","register_pk":"210453","name":"旧渡辺材木店店舗兼主屋","kana":"きゅうわたなべざいもくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市東山二丁目17","lat":36.57483389,"lng":136.66679111,"geo_status":"db","era":"明治30年頃／大正8年移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造二階建、瓦葺、建築面積135㎡","structure_material":"木造二階建","registered":"2017.05.02(平成29.05.02)","register_no":"17-0268","desc":"木造二階建、切妻造、桟瓦葺の間口五間で、明治三〇年頃に、材木商を開業するため建築された。大正期には道路拡張のため後方に曳家され、正面に平格子を取り付ける等の改修もなされた。良材を多用し、明治から大正にかけての金沢の町家の特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011488"},{"id":"00003964","register_sub_id":"101","register_pk":"104954","name":"経田屋米穀店","kana":"きょうでんやべいこくてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県金沢市東山1-17-7","lat":36.57209538,"lng":136.66626888,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積134㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0094","desc":"製粉業を兼ねた米穀商の店舗。２階建，切妻造，桟瓦葺で，１階正面に出桁で庇を付け，内部は西に通り土間，東に表から店，茶の間を配し，現在２階にも居室をとる。１階の大戸，蔀戸，２階の格子窓，袖卯建による表構えは，町並みの景観形成に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003964"},{"id":"00004135","register_sub_id":"101","register_pk":"105125","name":"佐藤家住宅主屋","kana":"さとうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市十一屋町323","lat":36.5443628,"lng":136.66028945,"geo_status":"db","era":"昭和12／昭和27頃曳家改造","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積107㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"17 － 0107","desc":"当初料亭として建てられ，第２次大戦後曳家の上住宅に改造されたもの。１・２階にそれぞれ設けられる床棚付の書院に，白鳥をあしらった欄間彫刻など質の高い意匠を備える。全体にたちが高く，２階部に縁と小庇を廻すなど近代和風建築の好例といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004135"},{"id":"00004132","register_sub_id":"101","register_pk":"105122","name":"澁江家住宅主屋","kana":"しぶえけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市東山1-4-1","lat":36.57282379,"lng":136.66576489,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積62㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"17 － 0104","desc":"平入の町屋で，西側で街路に面する。２階の大屋根は出桁造とし，腕木を二重に重ねて意匠を凝らす。１階は南寄りに玄関を置き，茶の間など居室を設ける。２階は東に縁を設ける座敷を中心に，前室２室と納戸を配している。金沢における大正期の町家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004132"},{"id":"00001069","register_sub_id":"101","register_pk":"102059","name":"白銀屋旅館茶室","kana":"しろがねやりょかんちゃしつ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市山代温泉万松通７","lat":36.28892549,"lng":136.36069875,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建，瓦葺，建築面積49㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0034","desc":"山代温泉では建築年代が古い旅館の付属施設で，敷地の北西隅に建つ。外観は簡素で一部に改造もみられるが，内部は木部全体を漆塗りで仕上げ，天井を折り上げるなど書院風のつくりになり，建築当初の雰囲気をよくとどめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001069"},{"id":"00001068","register_sub_id":"101","register_pk":"102058","name":"白銀屋旅館本館","kana":"しろがねやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県加賀市山代温泉万松通７","lat":36.28879019,"lng":136.36094001,"geo_status":"db","era":"文政年間","year":1824,"year_source":"estimated","year_min":1818,"year_max":1830,"year_label":"文政年間","structure":"木造２階建，瓦葺，建築面積520㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0033","desc":"山代温泉で江戸時代から続く老舗の旅館。本館は，間口の広い町家で，吹き抜けに架構をみせた「わくのうち」と呼ばれる構法を用いた部屋を持つ，この地方特有の形式になる。正面にべんがら格子を入れ，両袖にうだつを建てた外観にも特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001068"},{"id":"00004353","register_sub_id":"101","register_pk":"105343","name":"高澤ろうそく店主屋","kana":"たかざわろうそくてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市一本杉町11-1","lat":37.04640711,"lng":136.9640096,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積89㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0119","desc":"七尾の中心を東西に貫く通りに北面して建つ。桁行５間半梁間４間半，土蔵造２階建，切妻造，桟瓦葺で，内部は１階を店舗，２階に展示スペース，座敷を配す。２階は小窓以外は塗り込め，１階の両端部も壁とする閉鎖的なつくりで，重厚な町家の正面を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004353"},{"id":"00004355","register_sub_id":"101","register_pk":"105345","name":"夛田家住宅（旧上野啓文堂）主屋","kana":"ただけじゅうたく（きゅううえのけいぶんどう）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県七尾市一本杉町32-1","lat":37.0470962,"lng":136.96275522,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積96㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0121","desc":"万年筆専門文具店として建設。木造２階建で，内部は和室だが，通りに面した正面はモルタル塗壁を高く立ち上げた看板建築。万年筆とインク瓶のモチーフや柱頭飾り風の特徴ある装飾を付け，２階窓をペン先型に象るなど，斬新な意匠で町並景観に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004355"},{"id":"00004134","register_sub_id":"101","register_pk":"105124","name":"谷庄古美術店主屋","kana":"たにしょうこびじゅつてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市十間町44","lat":36.57069532,"lng":136.65739632,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積214㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"17 － 0106","desc":"和洋並立の店舗兼住宅。正面中央に玄関を開き，洋館の１階を店舗とし，和館部は１間幅の畳廊下を通して座敷，仏間，茶室等を配する。和館立面は洋館に揃えて高くし，洋館正面は３連のアーチ窓の２階と大窓の１階を対比させ，特徴的な外観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004134"},{"id":"00004357","register_sub_id":"101","register_pk":"105347","name":"戸市酒販酒蔵","kana":"といちしゅはんさかぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県小松市大川町2-45","lat":36.41473228,"lng":136.45046217,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積75㎡","structure_material":"木骨石造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0123","desc":"小松大橋南橋詰すぐ近くに建つ。２階建，切妻造，妻入で，木造軸組の外側に板状の切石を積み上げて漆喰で仕上げ，屋根野地板の上にも切石を張り桟瓦を葺く。西面１階戸口及び２階の小窓以外に開口を設けない閉鎖的なつくりで，防火的な外観を表通りに見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004357"},{"id":"00006449","register_sub_id":"101","register_pk":"107432","name":"戸水屋菓子店店舗兼主屋","kana":"とみずやかしてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市寺町二丁目45他","lat":36.55004741,"lng":136.65558679,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積172㎡","structure_material":"木造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"17 － 0164","desc":"寺町大通りに東面して建つ。正面桁行５間、梁間７間、切妻造、桟瓦葺、平入のたちの高い２階建町家で、北寄りに土間を通し、南３間分を店とする。正面は出桁造とし、１階の欄間下に木製庇を差し掛け、２階には袖卯建を付けるなど存在感ある表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006449"},{"id":"00004354","register_sub_id":"101","register_pk":"105344","name":"鳥居醤油店主屋","kana":"とりいしょうゆてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市一本杉町29","lat":37.0469638,"lng":136.96299549,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積124㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"17 － 0120","desc":"七尾の中心を東西に貫く通りに北面して建つ。桁行７間半梁間４間半，土蔵造２階建，切妻造，桟瓦葺で，内部は１階を店や座敷，２階は主に物置とする。間口が広く，軒の出の小さい重厚な構えで，つし２階としたたちの低い外観は，町並の景観に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004354"},{"id":"00003419","register_sub_id":"101","register_pk":"104409","name":"西検番事務所","kana":"にしけんばんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市野町2-25-17","lat":36.556477,"lng":136.64743,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積501㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0081","desc":"犀川大橋南方に位置し，芸妓衆の稽古場兼管理事務所として建設。洋風の事務所棟と中庭を隔てた木造２階建，和風の稽古場棟とから成り，事務所棟は寄棟造，桟瓦葺の木造２階建，下見板張で，明治期に流行したバージボード付きの玄関ポーチに特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003419"},{"id":"00005131","register_sub_id":"101","register_pk":"106121","name":"橋本酒造旧精米所","kana":"はしもとしゅぞうきゅうせいまいしょ","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32757593,"lng":136.3858831,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積99㎡","structure_material":"土蔵造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0142","desc":"釜場及び白米庫の西方，敷地南辺沿いに東西棟で建つ。桁行６間，梁間５間，切妻造，桟瓦葺の土蔵造平屋建で，北面東寄りと東面北寄りに出入口を設ける。南側梁行２間の土蔵と北側梁行３間トラス小屋の土蔵を接合し，一体的な屋根を架けた特異なつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005131"},{"id":"00005122","register_sub_id":"101","register_pk":"106112","name":"橋本酒造主屋","kana":"はしもとしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32772886,"lng":136.38654531,"geo_status":"db","era":"文化11","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造2階建、瓦葺、建築面積391㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0133","desc":"街道に東面して建つ。主体部は桁行７間，梁間７間規模，切妻造，桟瓦葺のつし２階建町家で，南寄りに通り土間を通し，南に１列，北に３列の諸室を配する。南端はもと釜場で，高い吹き抜けで，棟上に越屋根を載せる。江戸後期における造り酒屋の主屋の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005122"},{"id":"00005129","register_sub_id":"101","register_pk":"106119","name":"橋本酒造冷蔵室","kana":"はしもとしゅぞうれいぞうしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.327923,"lng":136.386078,"geo_status":"db","era":"大正期／昭和31移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木骨石造2階建、瓦葺、建築面積93㎡","structure_material":"木骨石造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0140","desc":"貯蔵庫の北西，敷地北辺沿いに東西棟で建つ。桁行５間，梁間４間規模，切妻造，桟瓦葺，妻入の木骨石造２階建で，東面に２間の下屋を差し掛けて戸口を開く。屋根は置屋根である。内部は中央に１本の柱を建て，地棟に木太い合掌を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005129"},{"id":"00005120","register_sub_id":"101","register_pk":"106110","name":"春成酒造店主屋","kana":"はるなりしゅぞうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県七尾市今町15","lat":37.04419062,"lng":136.96927131,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積191㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0131","desc":"能登街道の起点となる「違い堀」の近くに位置する。桁行７間半，梁間６間，切妻造，桟瓦葺，平入の木造２階建で，通りに西面して建ち，北方を店舗，事務室とし，南方に８畳を３室並べる。たちの高いせがい造の町家で，規模も大きく，周囲で際だった存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005120"},{"id":"00004131","register_sub_id":"101","register_pk":"105121","name":"平木屋旗店","kana":"ひらきやはたてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県金沢市菊川1-12-1","lat":36.55054674,"lng":136.6629594,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積110㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"17 － 0103","desc":"金沢の中心地，犀川右岸に建つ平屋建，平入の町家。建物は東寄りに土間を通し，西寄りに表側からミセ，茶の間，床と仏間を備える奥の間を配する。現在は鉄板葺であるが，かつては板葺であった。城下町金沢の近世の商家の様子を今日に伝える建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004131"},{"id":"00011286","register_sub_id":"101","register_pk":"209122","name":"法師延命閣","kana":"ほうしえんめいかく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県小松市粟津町カ17他","lat":36.331897,"lng":136.44772,"geo_status":"db","era":"明治44頃","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積247㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0263","desc":"粟津温泉の老舗旅館。延命閣は敷地の中央に独立して建つ宿泊棟で、浴室を併設する。大床と書院を備えた一二畳半大の上段を中心に、矩折の畳廊下を廻らし、さらに座敷を連ねて土縁を設ける独特の平面構成とする。色壁を用いて加賀らしい華やかな内部空間を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011286"},{"id":"00011287","register_sub_id":"101","register_pk":"209123","name":"法師玄関棟","kana":"ほうしげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県小松市粟津町ワ46-1","lat":36.331348,"lng":136.44735,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積334㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0264","desc":"粟津温泉の中心地に位置する老舗旅館。玄関棟は前面に玄関と帳場、背面にもと客室を並べる平面で、内部には高い吹き抜け空間を備え、梁組等を見せる。外観では正面側二階に円窓を横に四つ並べた出窓を張り出す特異な形態を見せ、法師の象徴として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011287"},{"id":"00001071","register_sub_id":"101","register_pk":"102061","name":"山岡商山堂（山岡ビル）","kana":"やまおかしょうざんどう（やまおかびる）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県加賀市山中温泉湯の出町レ26-3","lat":36.24621076,"lng":136.37282133,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積108㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"17 － 0036","desc":"山中温泉の中心街にある。もと漆器店の本店で現在はギャラリー等に利用されている。昭和６年の大火後に建てられたもので，地域で最初期の鉄筋コンクリート造の建物として貴重。交差点に面したつくられた入口廻りの装飾等にも時代の特徴があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001071"},{"id":"00006633","register_sub_id":"101","register_pk":"107616","name":"あめや呉服店店舗兼主屋","kana":"あやめごふくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県鯖江市本町3-206","lat":35.946758,"lng":136.18524465,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"18 － 0060","desc":"鯖江市街地の旧北陸道に東面して建つ。桁行５間半で、南面は入母屋造、北面は隣家に接する２階建平入町家。２階は黒漆喰塗で塗り込め、正面に２ヶ所、南側に３ヶ所の窓を開ける。１階正面にミセ、奥に座敷を設ける。鉄製扉で大壁造とする重厚な外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006633"},{"id":"00006634","register_sub_id":"101","register_pk":"107617","name":"あめや呉服店西蔵","kana":"あやめごふくてんにしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県鯖江市本町3-206","lat":35.94674439,"lng":136.18508812,"geo_status":"db","era":"昭和初期／昭和前期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"18 － 0062","desc":"東蔵の西奥に棟を並行に建つ。桁行４間梁間２間半規模の土蔵造２階建で、切妻造桟瓦葺。１階内部に４畳半の茶室を置く。基礎は笏谷石を用い、外壁はもとは漆喰仕上げであったが、モルタル仕上げに改修された。隣接して土蔵が建ち並び、存在感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006634"},{"id":"00006635","register_sub_id":"101","register_pk":"107618","name":"あめや呉服店東蔵","kana":"あやめごふくてんひがしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県鯖江市本町3-206","lat":35.94674962,"lng":136.1850067,"geo_status":"db","era":"大正2／昭和前期改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"18 － 0061","desc":"主屋の西奥、中庭を介して建つ。南北棟の切妻造桟瓦葺、桁行４間半梁間３間の土蔵造２階建である。目地を切るモルタル塗仕上げとし、上方を白漆喰で塗り込める。２階南窓は庇を設け、分銅形の紋様をもつ掛子塗戸片開をたてる。質実な意匠の土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006635"},{"id":"00000430","register_sub_id":"101","register_pk":"101420","name":"恵美写真館表門","kana":"えみしゃしんかんおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市本町3-1-28","lat":35.94661377,"lng":136.18627878,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造薬医門，銅板葺","structure_material":"木造薬医門","registered":"1998.01.16(平成10.01.16)","register_no":"18 － 0006","desc":"主屋の正面東方にあり，道路に面して建つ。伝統的な薬医門の形式をもつが，アーチ形の屋根，正面の虹梁等に洋風の意匠を取り入れた特異な形態の門。和風を基調にして要所に洋風を取り入れた意匠は，本館と共通する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000430"},{"id":"00000429","register_sub_id":"101","register_pk":"101419","name":"恵美写真館洋館","kana":"えみしゃしんかんようかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市本町3-1-28","lat":35.94668857,"lng":136.18617864,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建，瓦葺，建築面積42㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"18 － 0005","desc":"寄棟造，２階建の主体部に入母屋造の玄関ポーチを正面に付けた建物。全体的には和風になるが，玄関ポーチの開口部や軒廻りの装飾等に洋風の意匠を取り入れている。外壁は左官仕上で，各部の装飾等に優れた技能が発揮されている。左官は石動芳次郎がつとめた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000429"},{"id":"00016368","register_sub_id":"101","register_pk":"536435","name":"加藤善次郎商店店舗兼主屋","kana":"かとうぜんじろうしょうてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市本町241-2","lat":35.89833056,"lng":136.16600833,"geo_status":"db","era":"明治前期／昭和前期・同30年代・同54年・同61年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積132㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"18 - 0271","desc":"旧北陸道沿いに東面して建つ、打刃物問屋の店舗兼主屋。二階建切妻造平入桟瓦葺で正面に下屋を付し、二階は両端に袖壁を設け、軒は出桁造とする。一階内部は北東隅を土間とし、南側に一列３室を配す。一階上屋筋に摺上戸を留めるなど、古風な構えを残す町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016368"},{"id":"00016369","register_sub_id":"101","register_pk":"536436","name":"加藤善次郎商店土蔵","kana":"かとうぜんじろうしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市本町241-2","lat":35.89833611,"lng":136.16581389,"geo_status":"db","era":"昭和7年／昭和前期増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"18 - 0272","desc":"店舗兼主屋の西に位置する家財蔵。２階建切妻造妻入桟瓦葺で、外壁は漆喰塗で、一階はモルタル洗出仕上に目地を切り石貼風とする。東面の下屋内には床構え付きの座敷を配す。戸口や窓に鉄扉を付すなど厳重なつくりで、西妻に屋号を掲げて地域の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016369"},{"id":"00013534","register_sub_id":"101","register_pk":"504901","name":"旧浅井薬店（小澤金物店）店舗兼主屋","kana":"きゅうあさいくすりてん（おざわかなものてん）てんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市幸町222-1","lat":35.90337222,"lng":136.16645556,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積101㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"18 － 0215","desc":"武生城下の中心部に位置。二階建切妻造桟瓦葺。正面の出入口脇にショーウィンドウを構える。内部は土間脇に旧調剤室があり板間のミセを張り出す。奥の通り土間沿いに八畳、奥に浴室便所などを突出する。表構えに当時の流行を取り入れた商店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013534"},{"id":"00009751","register_sub_id":"101","register_pk":"195580","name":"旧大井百貨店（大井洋装店）","kana":"きゅうおおいひゃっかてん（おおいようそうてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県越前市元町81他","lat":35.90147502,"lng":136.16553409,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建地階付、建築面積239㎡","structure_material":"鉄筋コンクリート造3階建地階付","registered":"2013.12.24(平成25.12.24)","register_no":"18 － 0118","desc":"武生中心部の角地に建つ。間口八・七メートル奥行二八メートル、鉄筋コンクリート造三階建で地階をつける。正面入口上部に装飾的な半円アーチを設け、街路に面する北及び西面に大オーダーを廻らし、柱間に三連窓を配する。当地の賑わいを物語る近代商業建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009751"},{"id":"00013535","register_sub_id":"101","register_pk":"504902","name":"旧大木道具店店舗兼主屋","kana":"きゅうおおきどうぐてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県坂井市三国町北本町四丁目423-6","lat":36.21367778,"lng":136.14912778,"geo_status":"db","era":"昭和前期／平成30年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"18 － 0216","desc":"九頭竜川河口の町中にある商店。街路の角地に建つ木造二階建、入母屋造桟瓦葺で、建物東半三方に下屋を廻してショーウインドウを設け、二階には上げ下げ窓を並べる。内部二階座敷などは往時の姿を良く残す。建ちの高い外観が、町並のアクセントとなる建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013535"},{"id":"00013536","register_sub_id":"101","register_pk":"504903","name":"旧大木道具店土蔵","kana":"きゅうおおきどうぐてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県坂井市三国町北本町四丁目423-6","lat":36.21354722,"lng":136.148925,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積75㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"18 － 0217","desc":"敷地西端に東面して建つ。二階建の土蔵造桟瓦葺で北面に大振りの下屋を設ける。外壁は腰高くモルタル塗に目地を切り、上部は漆喰を軒先まで塗込める。一階は東西二室に区切って東室を床を備えた座敷とし、二階を物置とする。街路景観の一角を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013536"},{"id":"00013716","register_sub_id":"101","register_pk":"505249","name":"旧大和田銀行本店社屋","kana":"きゅうおおわだぎんこうほんてんしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県敦賀市相生町8-13他","lat":35.65681111,"lng":136.06866111,"geo_status":"db","era":"明治34年／明治37年・平成8年改修","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、瓦葺、建築面積248㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 218","desc":"敦賀の中心部に位置。木造二階建切妻造桟瓦葺平入。正面にパラペットを立上げて陸屋根にみせ、矩形の縦長窓を並べて洋風意匠の外観とする。正面を客溜り、営業室として両脇に応接室を配し、背後に和室を並べる。地方銀行の本店遺構として通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013716"},{"id":"00007988","register_sub_id":"101","register_pk":"128820","name":"旧京都電燈株式会社高浜営業店","kana":"きゅうきょうとでんとうかぶしきがいしゃたかはまえいぎょうてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県大飯郡高浜町宮崎73字島崎5-2","lat":35.49008632,"lng":135.54857673,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"18-0082","desc":"道路沿いに東面して建つ。木造２階建、寄棟造桟瓦葺。桁行梁間とも８．９ｍの平面になる。正面は２階にバルコニーを造り、中央に玄関を設け、半円アーチ窓を開ける。ベージュ色のモルタル仕上げで多彩な装飾を施す。左右対称を強調した正面構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007988"},{"id":"00009937","register_sub_id":"101","register_pk":"196084","name":"旧敦賀倉庫株式会社新港第一号・第二号・第三号倉庫","kana":"きゅうつるがそうこかぶしきがいしゃしんこうだいいちごう・だいにごう・だいさんごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県敦賀市蓬萊町1-4","lat":35.65948445,"lng":136.06978071,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積994㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"18 － 0121","desc":"敦賀港の中央に建つ。鉄筋コンクリート造平屋建の倉庫で、段差付のパラペットや小窓の上下の小庇、出入口の庇で水平線を強調する。隅部は一段高い塔屋状としてタイルを逆Ｌ字形に貼りアクセントとする。当時流行の国際様式の影響が看取される大型倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009937"},{"id":"00008682","register_sub_id":"101","register_pk":"149403","name":"旧旅籠若狭屋","kana":"きゅうはたごわかさや","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県南条郡南越前町今庄75字東中町13","lat":35.77317227,"lng":136.19671079,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積160㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0103","desc":"旧今庄宿に所在し、旧北国街道に西面する。間口10ｍ奥行9.5ｍの平入町家。木造2階建、切妻造鉄板葺とし、前後に庇を付ける。正面は中央間を出入口とし、その他は平格子を構える。2階に客間、1階に和室や台所などを配する。宿場町の佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008682"},{"id":"00011126","register_sub_id":"101","register_pk":"205233","name":"旧増尾家住宅主屋","kana":"きゅうますおけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県南条郡南越前町板取35-1","lat":35.726969,"lng":136.154029,"geo_status":"db","era":"文政6","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造2階建、茅葺、建築面積111㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"18 - 0157","desc":"北国街道の板取宿に建つもと旅籠。茅葺屋根を兜造妻入とする。正面側にニワを設け、床上部は二列とし、表列をクチノマ、ナカノマ、オクノマの三室、奥列をダイドコとブツマに分ける。北国街道に面した旅籠屋の意匠と間取りを伝える民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011126"},{"id":"00000406","register_sub_id":"101","register_pk":"101396","name":"旧森田銀行本店","kana":"きゅうもりたぎんこうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県坂井市三国町南本町3-217-2","lat":36.21234617,"lng":136.15033043,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積163㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"18 － 0004","desc":"鉄筋コンクリート造，２階建で，外壁に茶系タイルと擬石を張り，内外とも古典主義的な意匠でまとめる。内部は，１階が吹き抜けの営業室と個室，２階部分背後に会議室を置く。県内では初期の本格的な鉄筋コンクリート造建築で，質も高い。設計は，山田七五郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000406"},{"id":"00008671","register_sub_id":"101","register_pk":"149392","name":"旧料亭花月楼","kana":"きゅうりょうていかげつろう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県勝山市106字西中下後町28","lat":36.06048354,"lng":136.49736692,"geo_status":"db","era":"明治37年／大正4年増築","year":1904,"year_source":"converted","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積341㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0092","desc":"勝山市中心部の本町に所在する。木造2階建、入母屋造桟瓦葺の2棟を棟をずらして接続し、南側の棟が後年の増築になる。1階に5室、2階に10室の座敷を配する。北棟の2階奥を32畳の大広間とし、幅2間半のトコや傘状に棹縁を配る天井など意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008671"},{"id":"00008449","register_sub_id":"101","register_pk":"134845","name":"酒井家住宅主屋","kana":"さかいけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市下深江町116他","lat":35.94813186,"lng":136.18534557,"geo_status":"db","era":"明治43年／昭和57年頃改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積153㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"18 － 0084","desc":"旧北国街道に東面する町家。正面八・五メートル奥行一二メートルの木造二階建、切妻造桟瓦葺、正・背面に庇、側面に下屋を付設する。一階に事務室や座敷、仏間、二階に茶室ほかを配する。一階に出格子を構え二階を塗り込めるなど、町家らしい構えを示す","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008449"},{"id":"00008450","register_sub_id":"101","register_pk":"134846","name":"酒井家住宅土蔵","kana":"さかいけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市下深江町116他","lat":35.94811763,"lng":136.18525098,"geo_status":"db","era":"明治中期／昭和57年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"18 － 0085","desc":"主屋後方、中庭を介して建つ。桁行七・六メートル梁間五・七メートル、切妻造桟瓦葺の二階建土蔵。基礎を笏谷石とし、外壁をモルタル洗い出し仕上げ、腰を海鼠壁とする。窓や出入口まわりに漆喰仕上げを残し、庇には丁寧な仕上げの鏝細工が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008450"},{"id":"00000129","register_sub_id":"101","register_pk":"101119","name":"白鳥会館","kana":"しらとりかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県小浜市小浜白鳥25","lat":35.49282182,"lng":135.73755222,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建，瓦葺，建築面積59㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"18 － 0002","desc":"明治２１年の大火後に，土蔵造で建築されたもので，元薬品製造販売に使われた店蔵である。正面の開口部廻りや腰壁等壁面の一部等に煉瓦を用いている。特に正面外観の花弁型の特殊煉瓦を使用して特異なアーチを形造る意匠は類例が少なく見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000129"},{"id":"00000130","register_sub_id":"101","register_pk":"101120","name":"白鳥会館煉瓦塀","kana":"しらとりかいかんれんがべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市小浜白鳥25","lat":35.49275709,"lng":135.73751914,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"煉瓦造，延長4.0m","structure_material":"煉瓦造","registered":"1997.05.07(平成9.05.07)","register_no":"18 － 0003","desc":"店蔵と一体的に造られた煉瓦塀で，小規模ながら煉瓦積みの技術に見るべきものがある。店蔵の棟札に煉瓦工の名が記されており，手がけた職人の名が知られる。当時この地方で煉瓦工が職能として成立していたことを示すものとして，技術史上も意義が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000130"},{"id":"00014479","register_sub_id":"101","register_pk":"513893","name":"杉原商店事務所","kana":"すぎはらしょうてんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市不老町17字東町2-1他","lat":35.9072,"lng":136.24454167,"geo_status":"db","era":"昭和8年／同50年頃移築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積72㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"18 - 0238","desc":"主屋の北東に南面する和紙問屋の事務所。土蔵造2階建、切妻造平入桟瓦葺で南に下屋を付す。外壁は漆喰仕上で二階腰まで簓子下見板を張り、北に平格子付窓を４箇所開く。内部１階の南は廊下で西端に踏込土間、北は事務所とする。敷地北東の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014479"},{"id":"00009753","register_sub_id":"101","register_pk":"195582","name":"寿屋対碧亭","kana":"すやたいへきてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県越前市粟田部町29字船佐山41","lat":35.91706284,"lng":136.24090872,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、茅葺一部瓦葺及び銅板葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"18 － 0120","desc":"料理旅館の庭園内に建ち、木造平屋建、入母屋造茅葺で、南西隅に桟瓦葺の四畳半を張出す。主体部はトコ付の六畳の西側に四畳前室を、東側に山形窓のトコをもつ二畳を配し、周囲に下屋を廻らせる。四畳半には円窓など多彩な窓を穿つ、開放的な構成の草庵風茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009753"},{"id":"00003422","register_sub_id":"101","register_pk":"104412","name":"南越（旧中村商店）","kana":"なんえつ（きゅうなかむらしょうてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市蓬莱町125","lat":35.90224738,"lng":136.16837452,"geo_status":"db","era":"明治45／昭和5頃・昭和15増改造","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造3階建、瓦葺、建築面積89㎡","structure_material":"木造3階建","registered":"2003.07.01(平成15.07.01)","register_no":"18 － 0022","desc":"木造３階建，切妻造，桟瓦葺。当初は２階建で，２度の増改造を経ている。間口は４間で，１・２階を店舗及び倉庫とし，３階には和室４室を設ける。正面外観は２階・３階に大きな窓４カ所を設け，和風を基調としながら近代的な様相をも併せ持つ商店建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003422"},{"id":"00006492","register_sub_id":"101","register_pk":"107475","name":"都菓子舗作業所","kana":"みやこかしほさぎょうじょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県小浜市小浜鹿島41","lat":35.493023,"lng":135.73872876,"geo_status":"db","era":"明治中期／大正期曳家","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"18 － 0054","desc":"明治２１年の大火後に再建されたもとの主屋で、敷地北方に曳家され洋菓子製造の作業場となる。桁行３間半、梁間３間半、切妻造、桟瓦葺、平入の２階建町家で、２階は６畳と４畳半、板間２室とする。１階は改造されてはいるが、明治中期の町家の姿を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006492"},{"id":"00006451","register_sub_id":"101","register_pk":"107434","name":"都菓子舗店舗兼主屋","kana":"みやこかしほてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県小浜市小浜鹿島41","lat":35.492985,"lng":135.73877,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"18 － 0053","desc":"中町通りに南面して建つ。桁行３間半、梁行５間半、切妻造、桟瓦葺、平入の２階建洋風町家で、東側に通り土間、西端に半間幅の通路を通し、店の奧にトコ付の６畳間を配する。たちが高く、２階をドイツ下見板張とし、庇の幕板を看板とした正面は周囲で際立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006451"},{"id":"00008672","register_sub_id":"101","register_pk":"149393","name":"料亭板甚蔵座敷","kana":"りょうていいたじんくらざしき","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県勝山市95字西上袋田町東中下後町27他","lat":36.05981438,"lng":136.49890726,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"converted","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造2階地下1階建、瓦葺、建築面積64㎡","structure_material":"土蔵造2階地下1階建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0093","desc":"勝山市中心部を貫く本町通りに店を構える料亭の西奥に位置する。桁行11ｍ梁間5.7ｍ、土蔵造2階建、切妻造桟瓦葺。各階に2室の座敷を配し、コンクリート基礎に地下室を造る。1階奥の主座敷は、トコを黒漆喰塗に竹の落掛とするなど独特の意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008672"},{"id":"00006452","register_sub_id":"101","register_pk":"107435","name":"料亭開花亭","kana":"りょうていかいかてい","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"福井県","address":"福井県福井市中央3-1209他","lat":36.062721,"lng":136.213394,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造2階建、瓦葺、建築面積355㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"18 － 0056","desc":"足羽川の北、河畔に建つ料亭。通りの南に占める敷地のやや奥に東西棟で主部を設け、その東端に南北棟を付ける。１階は川に面して客間４室を設け、２階は７２畳の大広間や客間を配する。丁寧な造りの座敷飾りや天井、繊細な明障子など、伝統的な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006452"},{"id":"00010774","register_sub_id":"101","register_pk":"201609","name":"料亭天狗楼表門","kana":"りょうていてんぐろうおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"福井県","address":"福井県鯖江市中小路町32-4","lat":35.945497,"lng":136.186179,"geo_status":"db","era":"昭和26頃","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"18 ‐ 0142","desc":"料亭棟の東に接道して建つ。間口一・九メートルの棟門で、切妻造桟瓦葺とし、棟石及び鬼は笏谷石で作る。冠木上に繊細な筬欄間を嵌めるなど瀟洒な意匠を見せる。料亭棟の玄関とやや軸線をずらし、料亭の導入部に変化を与えると共に、通りの景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010774"},{"id":"00010772","register_sub_id":"101","register_pk":"201607","name":"料亭天狗楼調理棟","kana":"りょうていてんぐろうちょうりとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市中小路町32-4","lat":35.945614,"lng":136.186156,"geo_status":"db","era":"昭和元","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"18 ‐ 0140","desc":"料亭棟の北に接続し、東の道路に面して建つ二階建の建物。一階は南端に通り土間を設け、厨房としての機能を当初から担っている。正面外観は黒漆喰で塗込め、一階に出格子、二階を出桁で支えて両脇に袖壁を設けるなど、当地の伝統的な町家の形式となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010772"},{"id":"00010773","register_sub_id":"101","register_pk":"201608","name":"料亭天狗楼土蔵","kana":"りょうていてんぐろうどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市中小路町32-4","lat":35.945642,"lng":136.185945,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"18 ‐ 0141","desc":"敷地北西に建つ二階建の土蔵。南北棟で東に庇を大きく張出して蔵前とし、西面にも小庇のついた出入口を設ける。小屋は登梁形式とし、内部に幅広の床板を張る。蔵前部分の腰は洗出し仕上げで石積風に目地を切る。料亭に附属する昭和初期の土蔵として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010773"},{"id":"00010771","register_sub_id":"101","register_pk":"201606","name":"料亭天狗楼料亭棟","kana":"りょうていてんぐろうりょうていとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市中小路町32-4","lat":35.945562,"lng":136.186039,"geo_status":"db","era":"明治中期／昭和初期移築・同41改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積198㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"18 ‐ 0139","desc":"もと陣屋町の中に建つ二階建の料亭。料亭棟は東を通る道路からやや引いて建て、敷地南西隅の庭に面して座敷を並べる。一階に前室付の座敷、二階に大広間を配す。赤色壁や扇形の下地窓等に料亭らしい華やぎを見せ、また玄関の笏谷石敷などに地方的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010771"},{"id":"00007482","register_sub_id":"101","register_pk":"108464","name":"若栗商店店舗兼主屋","kana":"わかぐりしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市吉江町1字一ノ割1他","lat":35.985413,"lng":136.169968,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積237㎡","structure_material":"木造2階一部平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0074","desc":"七曲りと称される通りに西面する。切妻造妻入桟瓦葺で、正側面に下屋をまわし、南面前方と背面に角屋を付ける。内部は正面に土間床のミセを設け、その奥を２列各３室の居室とする。ブツマやキュウソクマ、ザシキなどが、漆塗や欄間彫刻で華やかに飾られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007482"},{"id":"00000239","register_sub_id":"101","register_pk":"101229","name":"飯島家住宅（旧飯島楼）","kana":"いいじまけじゅうたく（きゅういいじまろう）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県山梨市小原西765","lat":35.69478583,"lng":138.69016524,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造2階建，瓦葺，建築面積122㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"19 － 0013","desc":"旧青梅街道の小原宿の中ほどに街道に面して建つ。木造２階建で、ほぼ長方形の平面に入母屋造妻入の玄関を付し、１階平面には中廊下に六畳の客間を配する。２階の縁から富士山を望むことができたといい、近代初期の旧街道の面影を今に伝えて親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000239"},{"id":"00010965","register_sub_id":"101","register_pk":"208935","name":"いさご屋旅館","kana":"いさごやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3696","lat":35.377818,"lng":138.425123,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造3階建、瓦葺、建築面積201㎡","structure_material":"木造3階建","registered":"2016.02.25(平成28.02.25)","register_no":"19-0076","desc":"久遠寺の参道沿いにある旅館。木造三階建、入母屋造平入。入母屋の玄関を設け、二、三階の各窓には刎高欄の手摺を設ける。二階南側は大広間とし、三階は客室を並べる。ヒノキ一枚板の階段踏板や寄木、網代天井など趣向を凝らす。古刹の門前に風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010965"},{"id":"00010964","register_sub_id":"101","register_pk":"208934","name":"岩下温泉旅館旧館","kana":"いわしたおんせんりょかんきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県山梨市上岩下1055","lat":35.683648,"lng":138.654182,"geo_status":"db","era":"明治8頃／昭和17頃増築","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階一部地下1階建、瓦葺、建築面積159㎡","structure_material":"木造2階一部地下1階建","registered":"2016.02.25(平成28.02.25)","register_no":"19-0075","desc":"奥に東西棟の温泉棟、これと直交した前方に玄関棟があり、ほぼ南面して建つ。明治八年頃の温泉棟は二階建で、一部地階に源泉浴場がある。増築の玄関棟も二階建で、二階に瀟洒な座敷を設ける。伝統的な和風建築で、温泉地の歴史的景観に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010964"},{"id":"00001110","register_sub_id":"101","register_pk":"102100","name":"小原屋原田商店油蔵","kana":"おばらやはらだしょうてんあぶらぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町鰍沢1714","lat":35.5482812,"lng":138.45920976,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，瓦葺，建築面積152㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"19 － 0036","desc":"敷地奥に東面して建つ大規模な２階建の土蔵で、前面に幅１間の土庇が付く。内部は間仕切り壁で３室に区画され、南端部の部屋は２階建とするが他は吹き抜けである。開口部の少ない閉鎖的な土蔵であるが、正面腰壁をなまこ壁とするなど丁寧な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001110"},{"id":"00001109","register_sub_id":"101","register_pk":"102099","name":"小原屋原田商店塩蔵","kana":"おばらやはらだしょうてんしおぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町鰍沢1714","lat":35.54832178,"lng":138.45936395,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，瓦葺，建築面積86㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"19 － 0035","desc":"文庫蔵の西に建つ２階建の土蔵で、正面に土庇が付く。１階は仕切壁で２室に区画され、西側の部屋を塩蔵として使用したためその名がある。東側の部屋は２階へ通じる階段があり、物置として使われた。正背面にのみ開口部を開くが、全体に簡素な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001109"},{"id":"00001111","register_sub_id":"101","register_pk":"102101","name":"小原屋原田商店新座敷","kana":"おばらやはらだしょうてんしんざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡富士川町鰍沢1714","lat":35.54828283,"lng":138.45935746,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積31㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"19 － 0037","desc":"文庫蔵に直交して建つ平屋建の建物。小規模であるが、外観は周囲にあわせて土蔵造としている。全体として簡素な外観になるが、内部は近年土間床に改造し従業員の食堂として使用している。商家の屋敷構を構成する要素として貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001111"},{"id":"00001108","register_sub_id":"101","register_pk":"102098","name":"小原屋原田商店文庫蔵","kana":"おばらやはらだしょうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町鰍沢1714","lat":35.54830068,"lng":138.4594873,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，瓦葺，建築面積53㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"19 － 0034","desc":"敷地の北側角地に建つ切妻造、２階建の小規模な土蔵。内部は１，２階とも１室とする。１階正面に扉口及び小窓があるほか、２階も両妻に小窓を開くのみの閉鎖的な構成になる。軒廻りは疎垂木を見せるが、外壁とも塗込の漆喰仕上げとする標準的な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001108"},{"id":"00001107","register_sub_id":"101","register_pk":"102097","name":"小原屋原田商店店蔵","kana":"おばらやはらだしょうてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町鰍沢1714","lat":35.5482033,"lng":138.45947594,"geo_status":"db","era":"安政3頃","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積78㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"19 － 0033","desc":"富士川の舟運で栄えた鰍沢で、弘化３年の創業と伝える商家。往時は主に塩などの仲買を行った。店蔵は１階前面を店舗とし、２階は居室に充て前面に細格子窓を開く伝統的な構えになる。もと表通りに面していたが、道路拡幅のため昭和３５年に曳き屋された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001107"},{"id":"00004753","register_sub_id":"101","register_pk":"105743","name":"風間酒造酒店","kana":"かざましゅぞうさけてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山下於曽910","lat":35.69735618,"lng":138.72730142,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積70㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"19 － 0051","desc":"主屋の北東，表通り際に建つ。桁行５間半，梁間３間，土蔵造，２階建，寄棟造，桟瓦葺で，１階を店舗とし東面戸口部分は土庇とする。２階の軒を腕木で大きく持ち出して塗込め，道側の窓を掛子塗とするなど重厚な造りで，主屋とともに独特の店構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004753"},{"id":"00014807","register_sub_id":"101","register_pk":"519065","name":"旧料亭角田主屋","kana":"きゅうかくだけおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県富士吉田市下吉田三丁目827-3他","lat":35.49287222,"lng":138.80203889,"geo_status":"db","era":"昭和3年／昭和中期改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積240㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0178","desc":"下吉田の月江寺参道に西面する元料亭。主屋は二階建入母屋造平入桟瓦葺で、正面に唐破風造の玄関を付し、二階中央に軒唐破風に千鳥破風を重ね、腰組付高欄を廻らした華やかな外観。二階座敷は出節床柱、折上格天井など昭和初期の豪壮な気風を示す料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014807"},{"id":"00014808","register_sub_id":"101","register_pk":"519066","name":"旧料亭角田脇門","kana":"きゅうかくだけわきもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県富士吉田市下吉田三丁目827-3","lat":35.49276667,"lng":138.80208611,"geo_status":"db","era":"昭和3年頃／昭和30年代移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、鉄板葺、間口1.8m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0179","desc":"主屋の西に位置し、月江寺参道に面して建つ一間一戸の腕木門。起り付きの切妻造鉄板葺。主柱間に冠木を渡し、絵様付き腕木で軒桁を支え、軒は二軒疎垂木。門口には引違の板戸とし、欄間に梅の透彫を入れて飾る。主屋とともに料亭の華やかさを伝える脇門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014808"},{"id":"00014801","register_sub_id":"101","register_pk":"519059","name":"旧松亭蔵座敷","kana":"きゅうしょうていくらざしき","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山梨県","address":"山梨県甲府市中央三丁目263-1他","lat":35.66132222,"lng":138.57487222,"geo_status":"db","era":"大正7年／令和3年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積37㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0172","desc":"甲府旧城下の魚町通りに位置するかつての料亭の座敷。敷地中央に位置する寄棟造桟瓦葺の東西棟で、外壁は塗込めて黒漆喰仕上、基礎廻りをモルタル塗仕上。戸口を西に設け、内部は一室の畳敷で東面に床を構え、黒檀の框など吟味した材を用いた蔵座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014801"},{"id":"00014802","register_sub_id":"101","register_pk":"519060","name":"旧松亭土蔵","kana":"きゅうしょうていどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲府市中央三丁目263-1他","lat":35.66128889,"lng":138.57500278,"geo_status":"db","era":"明治44年／令和元年改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積129㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0173","desc":"蔵座敷の東に位置するかつての家財蔵。二階建寄棟造東西棟の南に寄棟造の南北棟を延ばし全体でＬ字を呈す。南西面に矩折れに下屋を付し外壁は漆喰塗仕上で二段の水切を廻らす。小屋組はトラス組。入隅に戸口と窓が並んだ特徴ある外観が、地域の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014802"},{"id":"00013537","register_sub_id":"101","register_pk":"504904","name":"旧堀田古城園主屋","kana":"きゅうほったこじょうえんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-1他","lat":35.68523889,"lng":138.57735,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積179㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0157","desc":"甲府市街北部、国指定史跡の武田氏館跡の指定地内に所在。平屋建寄棟造桟瓦葺。玄関両脇に室をおき、廊下を挟んで神棚付続き間、座敷を矩折れに並べ、南脇に離れ座敷を突出する。庭に面してガラス戸を建て、たちが高く開放的な外観を持つ近代和風建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013537"},{"id":"00013538","register_sub_id":"101","register_pk":"504905","name":"旧堀田古城園北離れ","kana":"きゅうほったこじょうえんきたはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-1","lat":35.68516667,"lng":138.57746111,"geo_status":"db","era":"昭和8年／平成29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0158","desc":"主屋の奥に南離れ、茶室とともに三棟並んで建つ。平屋建寄棟造鋼板葺で、六畳大座敷を主体とした独立建物。真壁造で庭側をガラス窓とし開放的な外観をつくる。建具の一部に金唐紙を用い、床脇を地袋天袋とするなど瀟洒な意匠を持つ。敷地の一角を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013538"},{"id":"00013542","register_sub_id":"101","register_pk":"504909","name":"旧堀田古城園木戸門","kana":"きゅうほったこじょうえんきどもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-1","lat":35.68535833,"lng":138.57732778,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0162","desc":"敷地北西隅に通りに面して建つ。切妻造桟瓦葺の木戸門で、前後に控えの柱を立てる。門柱は角柱で、挿肘木と斗で腕木を受け、軒桁を架ける。柱間は引違いの格子戸を建て「堀田古城園」の扁額を掲げる。武田氏の居館跡にある旧料亭旅館の表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013542"},{"id":"00013540","register_sub_id":"101","register_pk":"504907","name":"旧堀田古城園茶室","kana":"きゅうほったこじょうえんちゃしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-2","lat":35.685025,"lng":138.57740833,"geo_status":"db","era":"昭和8年／平成29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0160","desc":"敷地南東隅に北離れ、南離れとともに独立して建つ。平屋建寄棟造鋼板葺。真壁造で一見して北と南の離れと同様の意匠だが、菱形の平面の四畳半をつくるなど独特な形式を持つ。地袋と琵琶棚を並べて床構えとする等、小規模ながら数寄屋趣味が横溢する佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013540"},{"id":"00013541","register_sub_id":"101","register_pk":"504908","name":"旧堀田古城園長屋","kana":"きゅうほったこじょうえんながや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-1","lat":35.68531944,"lng":138.57743889,"geo_status":"db","era":"昭和8年／平成29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0161","desc":"敷地の北面に木戸門の東に建つ。平屋建寄棟造桟瓦葺。物置等として、数室に区画されていたが現在は二室とする。活用のため東面の一部や間仕切撤去等の改修はあるが、主要材は当初を残し真壁造の外観も踏襲する。木戸門とともに敷地北辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013541"},{"id":"00013539","register_sub_id":"101","register_pk":"504906","name":"旧堀田古城園南離れ","kana":"きゅうほったこじょうえんみなみはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市大手三丁目3735-2","lat":35.68510278,"lng":138.57743333,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"19 － 0159","desc":"主屋の奥に北離れ、茶室とともに三棟並んで建つ。平屋建寄棟造鋼板葺で、六畳大座敷を主体とした独立建物。真壁造で庭側をガラス窓とし開放的な外観をつくる。床構えなど細部意匠を含めて北離れと同規模同形式の設えとする。敷地東辺の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013539"},{"id":"00000431","register_sub_id":"101","register_pk":"101421","name":"松寿軒長崎","kana":"しょうじゅけんながさき","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南アルプス市荊沢319 他","lat":35.58896722,"lng":138.46596336,"geo_status":"db","era":"昭和1","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積102㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"19 － 0024","desc":"和菓子づくりを営む家の店舗。韮崎から下諏訪へと通じる国道５２号線（富士川街道）が鍵の手に曲がる場所に位置する。寄棟造，平入の土蔵造町家で，軒先を持送状に３段に重ねるなど重厚な外観を持つ。街道の要所に建つ老舗として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000431"},{"id":"00012360","register_sub_id":"101","register_pk":"531684","name":"大市館","kana":"だいいちかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町下部48","lat":35.42244444,"lng":138.48183056,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造3階建、瓦葺、建築面積450㎡","structure_material":"木造3階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-136","desc":"下部温泉の中心部に東面して建つ旅館。木造三階建、入母屋造桟瓦葺で、正面北端に入母屋の玄関を設ける。一階に食堂、二、三階に大小一二の客室を配し、窓には刎高欄の手摺を付ける。下部川にかかる神泉橋のたもとにあって温泉街の景観に趣を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012360"},{"id":"00011496","register_sub_id":"101","register_pk":"210459","name":"中村屋旅館本館","kana":"なかむらやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲州市塩山上於曽1225","lat":35.70848806,"lng":138.73008111,"geo_status":"db","era":"大正6年頃／昭和10年頃改修、昭和30年頃増築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"19-0091","desc":"塩山温泉に位置する。木造二階建、寄棟造、桟瓦葺。南正面中央に入母屋造の玄関が付き、二階正側面の小庇は吹寄せ垂木の瀟洒な意匠を見せる。玄関の天井は棹縁を扇形に配る特徴的なもので、二階の座敷は窓を多くとって開放的な造りとする。近代和風旅館の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011496"},{"id":"00012336","register_sub_id":"101","register_pk":"531660","name":"萩原家住宅西座敷","kana":"はぎはらけじゅうたくにしざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼字中町3150他","lat":35.66121389,"lng":138.73105833,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"西店舗の奥に接続する。平屋建、切妻造の東西棟で、妻面を白漆喰で塗籠める。中央に土間を通して東に居室、西に座敷二室を配し、後方の西蔵との間にクジョウノマが突出する。それぞれ意匠の異なる造作で仕上げた座敷が近世商家の暮らしぶりを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012336"},{"id":"00012335","register_sub_id":"101","register_pk":"531659","name":"萩原家住宅西店舗","kana":"はぎはらけじゅうたくにしてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼字中町3150他","lat":35.66129444,"lng":138.73108056,"geo_status":"db","era":"江戸末期／平成24年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積86㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"東店舗兼主屋の西側に並び建つ。木造二階建、切妻造の東西棟で、正面に下屋を通す。奥行は三間と狭く、一階をミセとし、二階に座敷を設ける。正面の面格子、揚戸や大戸などの構えがよく残り、東店舗兼主屋とともに連続性のある旧宿場の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012335"},{"id":"00012337","register_sub_id":"101","register_pk":"531661","name":"萩原家住宅西蔵","kana":"はぎはらけじゅうたくにしのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼字中町3150他","lat":35.66110278,"lng":138.73098611,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"敷地の南奥に建つ。土蔵造二階建、切妻造の南北棟で、東面と北面に戸口を開き、下屋を廻す。一階は一四畳一間で座敷飾を備え、庭に面した南面にも観音扉の窓を開く。東面下屋の北端には便所も備える。床柱に珍木を用いるなど、随所に趣向を凝らす蔵座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012337"},{"id":"00012333","register_sub_id":"101","register_pk":"531657","name":"萩原家住宅東店舗兼主屋","kana":"はぎはらけじゅうたくひがしてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼字中町3150他","lat":35.66124722,"lng":138.73124167,"geo_status":"db","era":"江戸末期／昭和45年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、金属板葺、建築面積204㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"旧甲州街道勝沼宿にあり、通りに北面して建つ。木造二階建、切妻造の東西棟で、正面に下屋、背面に張出しを設ける。東に一間半幅の土間を通し、床上部は二列構成とし、上手奥に座敷を配する。発展した平面形式をもち、繊細な格子で意匠を整えた大規模な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012333"},{"id":"00012334","register_sub_id":"101","register_pk":"531658","name":"萩原家住宅東蔵","kana":"はぎはらけじゅうたくひがしのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼字中町3150他","lat":35.66118889,"lng":138.73140278,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積104㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"東店舗兼主屋の土間側に建つ、いわゆる蔵座敷。土蔵造二階建、切妻造の南北棟で、南に渡廊下を介し便所や浴室を設ける。一階は一二畳半の座敷二室で、座敷飾を備える。通りに面した北妻面には、庇付の観音扉の窓を上下に開き、重厚な街路景観をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012334"},{"id":"00003085","register_sub_id":"101","register_pk":"104075","name":"村松家住宅商家蔵","kana":"むらまつけじゅうたくしょうかぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南アルプス市桃園615-1","lat":35.625549,"lng":138.464554,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"19 － 0042","desc":"駿信往還に東面して建つ。桁行８間梁間２間半の東面に５尺幅の下屋庇を付け，西面の南寄りに観音扉を開けて主屋土間に連絡する。貸付業開業時の店蔵とされ，北半を商品蔵，南半１階を店，同２階を居室とする。棟札から棟梁「夜子沢村幡野宗兵衛」が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003085"},{"id":"00016370","register_sub_id":"101","register_pk":"536437","name":"山口家住宅（𠮷田屋）表門","kana":"やまぐちけじゅうたく（よしだや）おもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県富士吉田市中曽根一丁目3843-1","lat":35.48400833,"lng":138.79864444,"geo_status":"db","era":"明治後期／昭和27年移築、平成13年改修、同21年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、銅板葺、間口2.4m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0186","desc":"御師住宅の連なる富士みちに西面して建つ旧旅館の表門。一間薬医門、切妻造瓦棒銅板葺で、重厚な板戸を両開きに吊る。幅一尺の主柱同士を冠木で固め、控柱上の桁との間に断面矩形の梁を三筋架ける。軸部木太く質実なつくりで富士みちのランドマークとなる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016370"},{"id":"00012531","register_sub_id":"101","register_pk":"367826","name":"相澤商店店舗","kana":"あいざわしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上田市中央二丁目4633","lat":36.399529,"lng":138.255493,"geo_status":"geocoded","era":"昭和10年／平成9年移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、銅板葺、建築面積157㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0534","desc":"市中心部にある商家で、店舗は敷地中央部に西面して建つ。土蔵造二階建、寄棟造銅板葺で、正面に下屋を通す。伝統的な和風意匠を基調に、下屋軒下のアカンサスの浮彫や腰壁のスクラッチタイル張などの洋風意匠を加味する。昭和前期の気風を伝える町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012531"},{"id":"00006431","register_sub_id":"101","register_pk":"107414","name":"飯島商店作業所棟","kana":"いいじましょうてんさぎょうしょとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市中央1-1-21","lat":36.3982057,"lng":138.24987089,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造3階建、瓦葺、建築面積330㎡","structure_material":"木造3階建","registered":"2007.10.02(平成19.10.02)","register_no":"20 － 0319","desc":"店舗の西方に東西棟で建つ。もと上田倉庫会社創業時の繭倉で、桁行２０間、梁間５間と長大。切妻造、桟瓦葺の木造３階建で、外壁は漆喰仕上げ。内部棟通りに３間間隔に柱を建て、大引を方杖で支える。小屋組はキングポストトラス。蚕都上田の繁栄を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006431"},{"id":"00006432","register_sub_id":"101","register_pk":"107415","name":"飯島商店事務所棟","kana":"いいじましょうてんじむしょとう","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市中央1-1-21","lat":36.398197,"lng":138.249573,"geo_status":"db","era":"明治27頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造3階建、瓦葺、建築面積231㎡","structure_material":"木造3階建","registered":"2007.10.02(平成19.10.02)","register_no":"20 － 0318","desc":"店舗棟の西方、角地に南北棟で建つ。もと上田倉庫会社創業時の繭倉で、桁行１４間、梁間５間規模の木造３階建。外壁は大壁で、漆喰仕上げ。切妻造、桟瓦葺とし、棟通りに３間間隔に柱を建てる。一部切り縮められているが、蚕都上田の発展を物語る施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006432"},{"id":"00006430","register_sub_id":"101","register_pk":"107413","name":"飯島商店店舗棟","kana":"いいじましょうてんてんぽとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市中央1-1-21","lat":36.39811785,"lng":138.25018718,"geo_status":"db","era":"大正13／昭和38頃曳家","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積146㎡","structure_material":"木造3階建","registered":"2007.10.02(平成19.10.02)","register_no":"20 － 0317","desc":"上田駅前からの通りに東面して建つ。正面１５ｍ、奥行１０ｍ、寄棟造、鉄板葺、木造３階建の洋風店舗事務所。外部はモルタル塗で石目地を切り、上部に櫛形飾り付のパラペットを廻す。小屋組はキングポストトラス。縦長窓が並ぶ整然とした意匠でまとめられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006430"},{"id":"00008113","register_sub_id":"101","register_pk":"132511","name":"大塚魚店旧店舗兼主屋","kana":"おおつかうおてんきゅうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県小諸市本町2-70","lat":36.32913365,"lng":138.42423865,"geo_status":"db","era":"江戸末期／明治後期・大正後期・昭和中期・平成18年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積224㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"20 － 0356","desc":"小諸城下の東西の通りに北面して建つ。間口１４ｍの木造２階建、東西棟の切妻造桟瓦葺で、正面に下屋庇を付ける。道路に面した北半部を店舗として開き、南半部は東側の通り土間と居室空間となる。登梁の鼻先を延ばし軒桁を支持するなど、伝統的な表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008113"},{"id":"00010282","register_sub_id":"101","register_pk":"199055","name":"越志家住宅主屋（旧廣善院客殿）","kana":"おしけじゅうたくしゅおく（きゅうこうぜんいんきゃくでん）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市戸隠字宝光社2332","lat":36.730986,"lng":138.076759,"geo_status":"db","era":"江戸後期／明治34年・平成5年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、茅葺、建築面積252㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0459","desc":"戸隠の宿坊廣善院のもと客殿で、寄棟造茅葺である。中央奥に神殿を南面させ、手前二室を道場として玄関を構える。西列に座敷、東列に居室を配する。明治後期に祭壇を仏式から神式へ改めるなどの改修を受けており、宿坊の変容過程や戸隠信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010282"},{"id":"00010283","register_sub_id":"101","register_pk":"199056","name":"越志家住宅土蔵","kana":"おしけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市戸隠字宝光社2332","lat":36.73095,"lng":138.076956,"geo_status":"db","era":"明治中期／昭和40年頃移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0460","desc":"主屋の東方に建つ二階建の土蔵。置屋根式鉄板葺で西面に下屋を設ける。外壁漆喰塗で、腰を簓子下見板張とし、丑鼻に付した家紋や窓枠を鏝絵細工で飾る。もとは一階に食料を、二階に家財を収めていたという土蔵で、戸隠の宿坊における生活様態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010283"},{"id":"00005147","register_sub_id":"101","register_pk":"106137","name":"かどや商店店舗","kana":"かどやしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市松代町松代701","lat":36.56712621,"lng":138.20139142,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0215","desc":"東面する道路に接して建つ。桁行５間，梁間３間半の規模で，切妻造，桟瓦葺の木造２階建。正面に下屋を張出し真壁造とするが，妻破風から側壁，隅柱上の垂木までを漆喰で塗込める。町人町の往時の様子を伝える商家として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005147"},{"id":"00009016","register_sub_id":"101","register_pk":"162376","name":"金具屋別館臨仙閣本館","kana":"かなぐやべっかんりんせんかくほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県下高井郡山ノ内町大字平穏2147-1","lat":36.73419131,"lng":138.43203138,"geo_status":"db","era":"昭和4年／昭和15年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造3階地下1階建、鉄板葺、建築面積303㎡","structure_material":"木造3階地下1階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0413","desc":"川沿いの通りに南面する。Ｌ字型棟の入母屋造鉄板葺、木造三階地下一階建、建築面積３０３㎡。各階に連続窓を開き、庇や縁を付けて重層的な外観とする。内部は二階の赤壁や磨丸太、三階の海鼠壁や漆喰壁など仕様を大きく違え、変化に富む構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009016"},{"id":"00009017","register_sub_id":"101","register_pk":"162377","name":"金具屋別館臨仙閣浴堂","kana":"かなぐやべっかんりんせんかくよくどう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県下高井郡山ノ内町大字平穏2145-3他","lat":36.7341578,"lng":138.4321924,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0414","desc":"臨仙館本館の東に小路を挟んで建つ。東西棟の切妻造鉄板葺で、棟際に煙出風の小屋根、南北に下屋を付設する。木造平屋建、建築面積７５㎡。中廊下で男女の浴室を南北に分ける。円柱に虹梁、皿斗付大斗肘木や叉首組など仏堂風意匠の大浴場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009017"},{"id":"00003430","register_sub_id":"101","register_pk":"104420","name":"金具屋旅館大広間","kana":"かなぐやりょかんおおひろま","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県下高井郡山ノ内町大字平穏2202","lat":36.73510228,"lng":138.43266379,"geo_status":"db","era":"昭和11／昭和25改築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積322㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"20 － 0137","desc":"斉月楼と同時に建設された１７０畳の大広間。一時大雪のため屋根を大きく傷めたが，昭和２５年に修復されている。外観は斉月楼と比較して簡素な意匠とするが，内部の折り上げ格天井など見るべきものがある。木造和風旅館建築の大広間の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003430"},{"id":"00014604","register_sub_id":"101","register_pk":"515146","name":"軽井沢新スタジオ（旧アントニン・レーモンド軽井沢別邸）主屋","kana":"かるいざわしんすたじお","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県北佐久郡軽井沢町大字長倉字広原21-10","lat":36.323125,"lng":138.62328889,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積146㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"20 - 0632","desc":"軽井沢の南方に建つアントニン・レーモンド晩年の別荘兼事務所。一二角形平面の居間・食堂兼スタジオを中心に、西に厨房等、東に寝室と和室を付す。居間・食堂は煙突付暖炉を中心に唐傘形に丸太の梁組を架ける。設計者の丸太を用いた作風の円熟期を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014604"},{"id":"00015183","register_sub_id":"101","register_pk":"530607","name":"旧犬飼呉服店店舗兼主屋","kana":"きゅういぬかいごふくてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市大手四丁目1244-イ","lat":36.23622778,"lng":137.97416944,"geo_status":"db","era":"昭和前期／令和5年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積87㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"20 - 0659","desc":"松本城南東、善光寺街道の角地に建つ旧呉服店の町家。土蔵造二階建、正面はモルタル洗出仕上に目地を入れ石造風、側面などを漆喰塗仕上。一階は通り土間沿いに部屋を一列に並べ、二階に端正な床構え付き座敷を配す。石造風外観が街路景観の近代化を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015183"},{"id":"00015184","register_sub_id":"101","register_pk":"530608","name":"旧犬飼呉服店土蔵","kana":"きゅういぬかいごふくてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市大手四丁目1244-イ","lat":36.23621111,"lng":137.974225,"geo_status":"db","era":"明治6年","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積23㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"20 - 0660","desc":"主屋の背後に建つ家財蔵。妻入の土蔵造二階建で、正面一・二階に銅板葺庇を付ける。内部は各階一室の板敷で、二階に豪壮な梁組を現す。外壁は白漆喰塗で腰海鼠壁とし、正面二階中央に掛子塗扉を付した窓を開く。重厚かつ均整のとれた外観で屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015184"},{"id":"00015018","register_sub_id":"101","register_pk":"529296","name":"旧小澤家住宅（油屋）表門","kana":"きゅうおざわけじゅうたく（あぶらや）おもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡辰野町大字小野字町975-1","lat":36.04188333,"lng":137.96864167,"geo_status":"db","era":"江戸末期／昭和50年代改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、鉄板葺、間口2.1m、左右袖塀付","structure_material":"木造","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0657","desc":"主屋の北に位置し、通りに東面する一間一戸切妻造鉄板葺の薬医門。南北に袖塀を付し、南に潜戸を設ける。主柱に渡した冠木上に三筋の男梁を架け、正面側は先端に実肘木付平三斗を置き丸桁を支持、梁中央は蟇股を飾る。勇壮な構えで旅籠の格式を伝える表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015018"},{"id":"00015017","register_sub_id":"101","register_pk":"529295","name":"旧小澤家住宅（油屋）主屋","kana":"きゅうおざわけじゅうたく（あぶらや）おもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡辰野町大字小野字町975","lat":36.0418,"lng":137.96845278,"geo_status":"db","era":"万延2年（1861）／昭和50年代改修","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積276㎡","structure_material":"木造平屋一部2階建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0656","desc":"三州街道の小野宿北寄りに位置し、かつて旅籠を営んだ主屋。通りに東面する切妻造妻入鉄板葺の本棟造で、棟頂部に雀踊りを飾る。正面南側は土間と旧のウマヤを配し、北側は式台を設け、西に三間続きの座敷を配す。広い式台玄関が格式を示す規模雄大な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015017"},{"id":"00013249","register_sub_id":"101","register_pk":"366238","name":"旧小諸脇本陣主屋","kana":"きゅうこもろわきほんじんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県小諸市市町一丁目18","lat":36.33002778,"lng":138.42053333,"geo_status":"db","era":"江戸末期／平成31年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積275㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"20 － 0560","desc":"小諸宿脇本陣とされる旅籠の主屋で、北国街道に南面して建つ。木造二階建、切妻造桟瓦葺平入で、背面に別棟の渡廊下や水回りが付く。正面は一階西側に大きな切妻屋根の式台を設け、二階東側は手摺を廻した縁とする。本陣と共に近世宿場町の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013249"},{"id":"00013251","register_sub_id":"101","register_pk":"366240","name":"旧小諸脇本陣土蔵","kana":"きゅうこもろわきほんじんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県小諸市市町一丁目18","lat":36.32991389,"lng":138.42051389,"geo_status":"db","era":"明治前期／平成31年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"20 － 0562","desc":"離座敷の東側に主屋の渡廊下を介して建つ。土蔵造二階建、切妻造桟瓦葺妻入で、南面に戸口を開く。外壁は白漆喰塗で、鉢巻を廻らす。内部は一、二階とも板敷の一室で、二階は南面と東面に窓を配す。もとは家財道具を収めた蔵で、屋敷構えの一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013251"},{"id":"00013250","register_sub_id":"101","register_pk":"366239","name":"旧小諸脇本陣離座敷","kana":"きゅうこもろわきほんじんはなれざしき","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県小諸市市町一丁目18","lat":36.32937083,"lng":138.42122694,"geo_status":"db","era":"江戸末期／平成31年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺一部金属板葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"20 － 0561","desc":"南北に長い敷地の中央西側で、主屋の渡廊下に接続して建つ。木造平屋建、切妻造桟瓦葺の南北棟で、南面と北面に下屋を付す。内部は田字形に四室配し、八畳の主座敷には床、棚、書院を備える。宿場町の脇本陣において、往時の様相を今に伝える建物の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013250"},{"id":"00006428","register_sub_id":"101","register_pk":"107411","name":"旧信濃中牛馬合資会社社屋","kana":"きゅうしなのちゅうぎゅうばごうしがいしゃしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字長野大門町67-1","lat":36.656536,"lng":138.187668,"geo_status":"db","era":"明治45／大正13頃曳家","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"煉瓦造2階一部平屋建、瓦葺、建築面積98㎡、門付","structure_material":"煉瓦造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"20 － 0315","desc":"善光寺の門前、大門町中央通りに西面して建つ運送会社の社屋。間口７．４ｍ、奥行９．３ｍの煉瓦造２階建で、屋根は切妻造、桟瓦葺とし屋根窓をのせる。正面は施釉煉瓦に花崗岩を要所に配する。目地仕上げなど施工も丁寧。善光寺門前の町並みの近代化を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006428"},{"id":"00006429","register_sub_id":"101","register_pk":"107412","name":"旧第一勧業銀行松本支店","kana":"きゅうだいいちかんぎょうぎんこうまつもとしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市大手3-70-5","lat":36.235939,"lng":137.969574,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造3階一部地下1階建、建築面積692㎡、塔屋付","structure_material":"鉄筋コンクリート造3階一部地下1階建","registered":"2007.10.02(平成19.10.02)","register_no":"20 － 0316","desc":"松本城に向かう通りに東面して建つ。鉄筋コンクリート造３階建一部地下室及び塔屋付で、営業室は吹抜けの大空間とする。外壁はモルタル塗で石目地を切る。独特の曲線形状になるアーチの開口を正面に７連、両側面と背面に各３連開け、外観を特色づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006429"},{"id":"00008283","register_sub_id":"101","register_pk":"133925","name":"旧光屋店舗兼主屋","kana":"きゅうひかるやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市大手4-1169-2","lat":36.23536109,"lng":137.97370731,"geo_status":"db","era":"明治20年／平成7年移築・平成19年改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積258㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0366","desc":"旧善光寺街道に東面して建つ、間口１５ｍに及ぶ大型の町家。木造２階建。正背面に下屋を設け、奥行は１８ｍ。外壁は大壁造で、正面上屋には掛子塗両開戸を吊る窓を六ヶ所開ける。腰は海鼠壁とする。座敷構えや欄間など、意匠、材料ともに洗練されたものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008283"},{"id":"00008284","register_sub_id":"101","register_pk":"133926","name":"旧光屋文庫蔵","kana":"きゅうひかるやぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県松本市大手4-1169-1他","lat":36.23549278,"lng":137.97365923,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造2階建、瓦葺、建築面積17㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0367","desc":"店舗兼主屋の西北に位置する。東西棟の切妻造桟瓦葺。桁行４．５ｍ梁間３．６ｍの２階建土蔵。切石基礎とし、外壁は漆喰仕上げで腰を海鼠壁とする。南面やや西寄りに出入口を開け、掛子塗の両開戸を吊る。拝み部分に「光」をあしらい、建物の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008284"},{"id":"00009600","register_sub_id":"101","register_pk":"194596","name":"旧伏見屋北土蔵","kana":"きゅうふしみやきたどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県諏訪郡下諏訪町字原東521-1他","lat":36.07990597,"lng":138.08532916,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"20 － 0431","desc":"敷地の北西に位置し、桁行梁間とも三・六メートル、土蔵造二階建、切妻造置屋根式の鋼瓦葺で、主屋側に下屋と戸口を設ける。街道側の腰を海鼠壁とし、上部に観音扉の窓および庇を設け意匠性を高める。呉服蔵として使用されたと伝わり、街道側の景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009600"},{"id":"00009598","register_sub_id":"101","register_pk":"194594","name":"旧伏見屋店舗兼主屋","kana":"きゅうふしみやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県諏訪郡下諏訪町字原東521-1","lat":36.07982269,"lng":138.0854868,"geo_status":"db","era":"元治元／平成22改修","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造2階建、銅板葺、建築面積144㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"20 － 0429","desc":"諏訪大社下社春宮と秋宮を結ぶ旧中山道に面して建つ。木造二階建で通土間を有した町家形式の建築で、通りに面して上店、下店を、背面には座敷と縁を配す。一階正面には出格子をたて摺上戸を設ける。参詣道として賑わった街道沿いの商家の佇まいを良好に残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009598"},{"id":"00009599","register_sub_id":"101","register_pk":"194595","name":"旧伏見屋南土蔵","kana":"きゅうふしみやみなみどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県諏訪郡下諏訪町字原東521-1他","lat":36.07984351,"lng":138.0852905,"geo_status":"db","era":"慶応元","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"20 － 0430","desc":"敷地の南西に位置し、桁行六・四メートル梁間三・九メートル、土蔵造二階建、切妻造置屋根式の鋼瓦葺で、主屋側に下屋を設ける。外壁は漆喰塗で、南面は腰を簓子下見板張とする。家財等の収納に使用された土蔵で、店舗兼主屋とともに商家の構えを引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009599"},{"id":"00005829","register_sub_id":"101","register_pk":"106815","name":"旧三河屋商店店舗兼住宅","kana":"きゅうみかわやしょうてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市大字長野東町165-3","lat":36.655724,"lng":138.189087,"geo_status":"db","era":"江戸後期／平成8曳家","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積169㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0260","desc":"油問屋の店舗兼住宅として建築。２階建，塗屋造の町家で，間口９間，奥行４間半の切妻造，桟瓦葺，平入の表に１間幅の庇がつく。正面１階中央が戸口で，左手は庇下を室内に取り込む。１階は中央が通り土間で左右を居室とし，２階に２４畳広間と居室を配す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005829"},{"id":"00016384","register_sub_id":"101","register_pk":"536451","name":"旧矢﨑商店店舗兼主屋","kana":"きゅうやざきしょうてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪郡下諏訪町字塚田3156-19","lat":36.07699722,"lng":138.08676944,"geo_status":"db","era":"昭和11年／昭和20年改修、同30年増築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、桟瓦葺一部鉄板葺、建築面積156㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0678","desc":"御田町通りの中心部に西面して建つ、旧生糸問屋の店舗兼主屋。木造二階建で正面側はモルタル洗出仕上、腰タイル貼の立体感ある看板建築でアールデコ調の外観とするが、背面側は桟瓦葺で、和風の座敷を張出すなど対照的。戦後の下諏訪の繁栄を伝える看板建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016384"},{"id":"00016386","register_sub_id":"101","register_pk":"536453","name":"旧矢﨑商店納屋","kana":"きゅうやざきしょうてんなや","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪郡下諏訪町字塚田3156-19","lat":36.07705556,"lng":138.08693889,"geo_status":"db","era":"昭和前期／昭和30年頃改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋一部2階建、鉄板葺、建築面積13㎡","structure_material":"木造平屋一部2階建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0680","desc":"店舗兼主屋の北東に位置する味噌蔵兼物置。不整形平面の平屋一部二階建、片流屋根瓦棒鉄板葺。外壁モルタル洗出仕上、腰は独特な自然石貼。内部は隅柱や落し込み板の最下段にクリを用いる。頂部にパラペットを廻らした洋風の独特な外観が主屋と呼応する納屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016386"},{"id":"00016385","register_sub_id":"101","register_pk":"536452","name":"旧矢﨑商店文庫蔵","kana":"きゅうやざきしょうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪郡下諏訪町字塚田3156-19","lat":36.07698611,"lng":138.08695833,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0679","desc":"店舗兼主屋の南東に西面して建つ文庫蔵。土蔵造二階建切妻造桟瓦葺。外壁漆喰塗、腰海鼠壁仕上で、蔵前は柱や桁に丸太を用いる。内部は柱に横板を落し込み、柱や最下段の壁板にクリを用いる。小屋組はトラス。階段下に棚を造作するなど丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016385"},{"id":"00014371","register_sub_id":"101","register_pk":"511360","name":"旧料亭信濃離れ菊の間","kana":"きゅうりょうていしなのはなれきくのま","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県諏訪市大手二丁目3008-1他","lat":36.04295,"lng":138.11704722,"geo_status":"db","era":"大正前期／昭和中期増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0616","desc":"上諏訪駅の南に位置する料亭離れ。平屋建入母屋造桟瓦葺の東西棟で北面し、内部は東を寄付、西を八畳座敷とし、南面に縁を付して水屋と便所に連絡する。床や書院、窓廻りや天井に多様な竹を散り嵌め、細部まで技巧を凝らす。煎茶趣味が溢れる数寄屋風の離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014371"},{"id":"00014372","register_sub_id":"101","register_pk":"511361","name":"旧料亭信濃離れ桐の間","kana":"きゅうりょうていしなのはなれきりのま","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県諏訪市大手二丁目3008-1他","lat":36.04299167,"lng":138.116975,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0617","desc":"上諏訪駅の南に位置する料亭離れ。平屋建入母屋造桟瓦葺の南北棟で東面し、内部は北の玄関から取次ぎの間を通って十畳の座敷に至る。座敷の畳床と両脇床の構成は近代らしい。銘木や竹をふんだんに用い、内外に渡り技巧を凝らした上質な造りの数寄屋風の離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014372"},{"id":"00005851","register_sub_id":"101","register_pk":"106837","name":"杭全家住宅主屋","kana":"くまたけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代635","lat":36.565125,"lng":138.201859,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積166㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0274","desc":"松代城下，旧谷街道に西面して建つ商家。桁行７間，梁間２間半の塗屋造２階建，切妻造，桟瓦葺。表に下屋を付け，玄関，便所を配す。内部は南半がもと土間，北半を居室とし，背面の角屋まで１２畳半３室を並べる。２階正面など簡素であるが重厚な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005851"},{"id":"00014374","register_sub_id":"101","register_pk":"511363","name":"栗林家住宅（創舎わちがい）店舗","kana":"くりばやしけじゅうたく（そうしゃわちがい）てんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県大町市大町4084-1他","lat":36.50513056,"lng":137.85910833,"geo_status":"db","era":"大正後期／平成17年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0619","desc":"大町の中心市街地で、通りに西面する庄屋の町家。切妻造平入桟瓦葺、真壁造漆喰仕上、正面に格子戸を建て、南側を通り土間とし、北側を表から前土間、ミセ、オエ、カッテを並べる。通りに面し二階に床付座敷を配し、窓を設け、歴史的な町並みを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014374"},{"id":"00011692","register_sub_id":"101","register_pk":"210708","name":"寿高原食品四階倉庫","kana":"ことぶきこうげんしょくひんよんかいそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県千曲市大字戸倉字大明神1465-1","lat":36.491697,"lng":138.152688,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造4階建、瓦葺、建築面積318㎡","structure_material":"土蔵造4階建","registered":"2017.06.28(平成29.06.28)","register_no":"20-0510","desc":"戸倉駅前に建つ桁行二九メートル、梁間一一メートル、土蔵造の大規模倉庫。三階までは中央二間毎に六寸柱を立て大梁で固め、四階は柱を立てず大空間とする。小屋組はキングポストトラス。方杖付の庇を持つ窓を一間置きに開く多窓式の外観で地域景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011692"},{"id":"00008457","register_sub_id":"101","register_pk":"134853","name":"小林家住宅主屋","kana":"こばやしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県塩尻市大字宗賀字本山4917他","lat":36.06116593,"lng":137.9011553,"geo_status":"db","era":"明治前期／明治期改修・昭和34年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積146㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"20 － 0370","desc":"旧本山宿に所在し、中山道に東面する。桁行一二メートル梁間九・九メートルの木造二階建、切妻造鉄板葺。二階全面に千本格子を通し、両端に袖ウダツを設け、一階に式台を構える。類例の少ない二重出梁を残す。三棟の平入町家が連続して残り、宿場の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008457"},{"id":"00005816","register_sub_id":"101","register_pk":"106803","name":"小諸市北国街道ほんまち町屋館","kana":"こもろしほっこくかいどうほんまちまちやかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県小諸市本町2-2-9","lat":36.329369,"lng":138.423676,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積160㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0298","desc":"旧北国街道沿いの商家で，桁行７間半，梁間６間の規模で，木造２階建，切妻造，桟瓦葺とする。２階通り側に２０畳の座敷を設け，裏側に８畳間２室を並べる。側面及び２階軒裏を塗り込め，漆喰塗の鉢巻きを廻し，重厚な塗屋造の外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005816"},{"id":"00003091","register_sub_id":"101","register_pk":"104081","name":"笹屋ホテル別荘","kana":"ささやほてるべっそう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県千曲市上山田温泉1-1-1","lat":36.48370704,"lng":138.14180298,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積965㎡","structure_material":"木造2階一部平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0111","desc":"ホテル本館西方に建つ３棟と渡り廊下から成る客室群。遠藤新の設計になる木造和風旅館建築で，畳敷きの座敷と一段下げた椅子置きの広縁から庭に至る客室構成に遠藤新の作風が示されている。この構成は後の国際観光旅館等に大きな影響を与えたとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003091"},{"id":"00007633","register_sub_id":"101","register_pk":"108615","name":"塩尻短歌館","kana":"しおじりたんかかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県塩尻市大字広丘原新田288-1","lat":36.15272345,"lng":137.94507204,"geo_status":"db","era":"明治元／平成4移築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積266㎡","structure_material":"木造平屋一部2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0350","desc":"敷地の南西隅、南面して建つ。桁行１３ｍ梁間１７ｍ、木造平屋一部２階建、切妻造妻入鉄板葺で、南面に式台と下屋を付ける。２階妻面に出格子を設け、破風板上に棟飾りの雀おどしを戴く。内部の間取や外観に、本棟造民家として整った形態をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007633"},{"id":"00006226","register_sub_id":"101","register_pk":"107210","name":"塩屋醸造店舗及び主屋","kana":"しおやじょうぞうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.65588425,"lng":138.31577575,"geo_status":"db","era":"明治初期／昭和27改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋一部2階建、瓦葺、建築面積210㎡","structure_material":"木造平屋一部2階建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0302","desc":"市道沿いに北面して建つ。間口６間，奥行１１間規模，木造平屋一部２階建，切妻造，桟瓦葺。通りに面して平入の店舗を置き，奥に居住部分を配する。正面に下屋を付け，２階壁や軒廻り等を塗り込む。大規模な商家の外観を持ち，街路沿いの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006226"},{"id":"00010781","register_sub_id":"101","register_pk":"201616","name":"須高農業協同組合井上支所","kana":"すこうのうぎょうきょうどうくみあいいのうえししょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県須坂市大字幸高447-2","lat":36.638402,"lng":138.282958,"geo_status":"db","era":"昭和3／平成10改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、銅板葺、建築面積337㎡、塔屋付","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0493","desc":"左右対称の正面両端をやや張出してマンサード破風を設け、屋根上に小振りの塔屋とドーマー窓を配す。外壁はモルタル塗で大オーダーを表して垂直性を強調する。内部階段などに幾何意匠を用い、入口上部に「井上に産」を図案化して飾る。洋風意匠の事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010781"},{"id":"00008456","register_sub_id":"101","register_pk":"134852","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県塩尻市大字宗賀字本山4916-1","lat":36.06109619,"lng":137.90116145,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積152㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"20 － 0369","desc":"旧本山宿に所在し、中山道に東面する。桁行一二メートル梁間一二メートルの平入町家。切妻造鉄板葺とし、棟に越屋根を付ける。出梁造とし、二階全面に千本格子を通し、両端に袖ウダツを設け、一階に式台を構える。軸部は弁柄塗。華やかな旅篭の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008456"},{"id":"00000047","register_sub_id":"101","register_pk":"101037","name":"中央印刷社屋（旧片倉組事務所）","kana":"ちゅうおういんさつしゃおく（きゅうかたくらぐみじむしょ）","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県岡谷市川岸1-1-20","lat":36.05332844,"lng":138.03452726,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、銅板葺、建築面積335㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"20 － 0002","desc":"日本を代表する製糸業者であった片倉組の本社屋として建設され，その後系列会社に引き継がれて今日に至っている。人造石の柱型に煉瓦の壁面を組み合わせた外観や，洋風を基本に和風のモチーフを巧みに取り込んだ内部が特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000047"},{"id":"00008984","register_sub_id":"101","register_pk":"162344","name":"徳本峠小屋休憩所","kana":"とくごうとうげごやきゅうけいじょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県松本市安曇1743","lat":36.22813383,"lng":137.67830516,"geo_status":"db","era":"大正12年／平成22年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0381","desc":"松本盆地から上高地に至る山道の標高２１３４ｍの峠に建つ。木造平屋建、桁行５．５ｍ梁間５．１ｍ、切妻造石置板葺である。内部は板敷で一部を土間とする。近代登山の舞台となった北アルプスに開設された山小屋の初期形態をとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008984"},{"id":"00003429","register_sub_id":"101","register_pk":"104419","name":"金具屋旅館斉月楼","kana":"なかぐやりょかんさいげつろう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県下高井郡山ノ内町大字平穏2202","lat":36.73486613,"lng":138.43282459,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造4階建、鉄板葺、建築面積172㎡","structure_material":"木造4階建","registered":"2003.07.01(平成15.07.01)","register_no":"20 － 0136","desc":"湯田中・渋温泉の旅館建築。木造４階建，入母屋造，鉄板葺。昭和８年起工，同11年竣工で，内部は主として客室とする。外観・内装ともに数寄屋風の様々な意匠をちりばめ，細部も細かく造り分け，非日常的な空間を現出する，温泉旅館建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003429"},{"id":"00003088","register_sub_id":"101","register_pk":"104078","name":"中澤時計本店","kana":"なかざわとけいほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市大字長野大門町48-1","lat":36.655178,"lng":138.187576,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、銅板葺、建築面積158㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0108","desc":"市区改正による善光寺前中央通りの拡幅に際して建設。角地に位置し，善光寺に向けた北西面を隅切りとする。木造２階建，鉄網コンクリートの洗出仕上げで，細部意匠はセセッションの流れを汲む。設計は長野市嘱託建築技師の本田政蔵，施工は大工棟梁池田市郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003088"},{"id":"00010968","register_sub_id":"101","register_pk":"208938","name":"中野家住宅北土蔵","kana":"なかのけじゅうたくきたどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字須坂字春木町421-1","lat":36.655865,"lng":138.312858,"geo_status":"db","era":"安政4（1857）","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"20-0497","desc":"蔵座敷からさらに西に接続する。土蔵造二階建で、一階は南に出入口を、二階は東の蔵座敷からの出入口を設けて、動線を分ける。もとは一階に日用品、二階に家財道具などを収納したと伝わる。屋根は置屋根形式とし、蔵の多いことで知られる須坂の町を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010968"},{"id":"00010967","register_sub_id":"101","register_pk":"208937","name":"中野家住宅蔵座敷","kana":"なかのけじゅうたくくらざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂字春木町420","lat":36.655867,"lng":138.313009,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造3階建、瓦葺、建築面積90㎡","structure_material":"木造3階建","registered":"2016.02.25(平成28.02.25)","register_no":"20-0496","desc":"下店から渡り廊下を介して西に接続する居住棟。木造三階建のたちの高い建物で、南に玄関を開く。一階は仏間を兼ねた接客用の続き間座敷とし、北面に床を構え、付書院を備える。二階と三階を寝室等として居住に用いる。須坂の大店の暮らしぶりを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010967"},{"id":"00010966","register_sub_id":"101","register_pk":"208936","name":"中野家住宅下店","kana":"なかのけじゅうたくしたみせ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂字春木町420","lat":36.655867,"lng":138.313184,"geo_status":"db","era":"明治中期／平成23改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積86㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"20-0495","desc":"通りに東面して建つ。切妻造平入とし、正面を塗込めて土蔵造風とする。二階正面は黒漆喰塗として、出桁を設け、格子窓を穿って迫力を見せる。当初は一階にミセとチャノマを設ける。繊維で知られる須坂において、明治期の呉服店の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010966"},{"id":"00010969","register_sub_id":"101","register_pk":"208939","name":"中野家住宅南土蔵","kana":"なかのけじゅうたくみなみどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字須坂字中町218","lat":36.655734,"lng":138.312977,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"20-0498","desc":"上店の西方に接続して建つ。土蔵造二階建で、商品の呉服の在庫を保管するための蔵である。東に出入口を開き、両開とする掛子塗の厚い土戸を吊って、高い左官技術を見せる。小屋は和小屋で、置屋根形式として、当地の伝統的な土蔵の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010969"},{"id":"00008691","register_sub_id":"101","register_pk":"149412","name":"中房温泉板倉","kana":"なかぶさおんせんいたくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39464311,"lng":137.74709957,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0378","desc":"本館菊の東に位置する。東西棟の切妻造鉄板葺。桁行6.1ｍ梁間4.6ｍの木造平屋建。切石基礎上に土台をまわし、方柱を4間×3間にたて、横板を落とし込み板壁とする。桁や梁、母屋を架け、一軒疎垂木を配る。内部は東西2室に分ける。素朴な味わいをもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008691"},{"id":"00008689","register_sub_id":"101","register_pk":"149410","name":"中房温泉温泉大プール","kana":"なかぶさおんせんおんせんだいぷーる","category":"産業3次","subcategory":"その他工作物","type_guess":"旅館","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39391157,"lng":137.74620787,"geo_status":"db","era":"大正12年","year":1923,"year_source":"converted","year_min":1923,"year_max":1923,"year_label":null,"structure":"石造、面積147㎡","structure_material":"石造","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0376","desc":"温泉地の西南に位置する。温泉を用いた屋外プール。幅8.7ｍ長さ17ｍで、深さ1.2ｍを測る。周辺でとれる有明花崗岩を利用した切石を4段に積み上げ、壁面を造る。北・西・東の3方には階段2段が積まれる。近代的な温泉場の先駆けをなす施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008689"},{"id":"00008686","register_sub_id":"101","register_pk":"149407","name":"中房温泉旧湯会所","kana":"なかぶさおんせんきゅうゆかいしょ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39459245,"lng":137.7469195,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、板葺一部鉄板葺、建築面積46㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0373","desc":"本館菊の西南に位置する。東西棟の切妻造で、南側を石置板葺、北を鉄板葺とする。桁行6.4ｍ梁間6.4ｍの木造2階建。外壁は下見板張で、南面には窓を穿つ。1階は西半部を板敷、東寄りを部屋として間仕切る。木立を背景に石置屋根の特徴ある外観を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008686"},{"id":"00008687","register_sub_id":"101","register_pk":"149408","name":"中房温泉田村薬師堂","kana":"なかぶさおんせんたむらやくしどう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39436471,"lng":137.7464125,"geo_status":"db","era":"嘉永元年(1848)／昭和50年改修","year":1848,"year_source":"converted","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積4.5㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0374","desc":"温泉地の西方に位置する。正面1間、側・背面2間、宝形造鉄板葺。正面に引違い格子戸をたて、側・背面板壁。正・側三方に切目縁をまわす。円柱が直接に桁を支持し、軒天井を張る。内部は後半部に壇を構え、本尊を安置。温泉起源に関わる伝説を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008687"},{"id":"00008690","register_sub_id":"101","register_pk":"149411","name":"中房温泉土蔵","kana":"なかぶさおんせんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39462526,"lng":137.74715489,"geo_status":"db","era":"嘉永7年(1854)／明治期移築","year":1854,"year_source":"converted","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積14㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0377","desc":"本館菊の東南に位置する。南北棟とする切妻造鉄板葺で、桁行4.6ｍ梁間3.0ｍの木造二階建。方柱に横板を建て込む板蔵で、外壁には土を塗り上げたとみられる。西面中央を出入口とし、引込戸をたてる。山村に多くみられる特徴的な蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008690"},{"id":"00008685","register_sub_id":"101","register_pk":"149406","name":"中房温泉本館菊","kana":"なかぶさおんせんほんかんきく","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39463572,"lng":137.74695204,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、鉄板葺、建築面積123㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0372","desc":"有明山中腹に位置する温泉施設。東西棟の切妻造鉄板葺、桁行13ｍ梁間5.4ｍの木造2階建。西側に平屋建の浴場を付設。各階とも南側に縁を通し、4室の和室を配する。南面は全面を開放的に扱い、1階を掃き出し、2階を窓とする。近代の湯治場建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008685"},{"id":"00008688","register_sub_id":"101","register_pk":"149409","name":"中房温泉山の神の社","kana":"なかぶさおんせんやまのかみのやしろ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県安曇野市穂高有明7226他","lat":36.39434865,"lng":137.74636298,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、こけら葺、建築面積0.18㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"20 － 0375","desc":"田村薬師堂の西に位置する。陰刻のある巨大な岩の上に鎮座する小祠。土台上に建つ1間社流造、こけら葺。身舎は円柱で貫や長押で固め、台輪上に三斗を組む。妻は虹梁大瓶束で、二軒繁垂木。庇は几帳面取方柱、三斗組。丁寧に仕上げられた小規模社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008688"},{"id":"00015314","register_sub_id":"101","register_pk":"532438","name":"野沢温泉ロッヂ","kana":"のざわおんせんろっぢ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"昭和後","pref":"長野県","address":"長野県下高井郡野沢温泉村大字豊郷字大ナデ7812-2他","lat":36.92067778,"lng":138.45156667,"geo_status":"db","era":"昭和44年／平成26年改修","year":1969,"year_source":"db","year_min":1969,"year_max":1969,"year_label":null,"structure":"木造及び鉄筋コンクリート造地上3階地下1階建、鉄板葺、建築面積79㎡","structure_material":"木造及び鉄筋コンクリート造地上3階地下1階建","registered":"2025.03.13(令和7.03.13)","register_no":"20 - 0668","desc":"長坂ゲレンデ脇に建つ木造三階建スキーロッヂ。設計は吉阪隆正＋Ｕ研究室。平面正六角形を基本に外観ドングリ形とし、外壁緑色鉄板張で随所に窓を開ける。内部は中心に螺旋階段を配し、外周にスキップフロアで部屋を並べるなど複雑で独創的な構成の山荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015314"},{"id":"00005737","register_sub_id":"101","register_pk":"106725","name":"花屋ホテル井戸","kana":"はなやほてるいど","category":"産業3次","subcategory":"その他工作物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.35091,"lng":138.159698,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、面積0.8㎡","structure_material":"石造","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0297","desc":"事務所棟の東側に位置する井戸で，花崗岩の切石で井戸枠を組む。井戸枠は外側９０ｃｍ角とし，高さ７０ｃｍ，幅１５ｃｍで長さ９０ｃｍと６０ｃｍの切石４本で組まれる。現在も水を汲み上げ，使用され，和風旅館の出入口の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005737"},{"id":"00005878","register_sub_id":"101","register_pk":"106863","name":"花屋ホテル大奥棟","kana":"はなやほてるおおおくとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.35110328,"lng":138.15893666,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0293","desc":"奥棟の西側に位置し，桁行４間，梁間３間の規模で，木造平屋建，入母屋造，桟瓦葺とする。８畳間の座敷に４畳半の前室を付け，温泉浴室が付属する。独立した離れの形式をとり，床棚を備え豊かな座敷空間を形成している。創建当初の建物で，特に質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005878"},{"id":"00005877","register_sub_id":"101","register_pk":"106862","name":"花屋ホテル奥棟","kana":"はなやほてるおくとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.35104,"lng":138.159027,"geo_status":"db","era":"大正9頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積184㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0292","desc":"二七番棟の西に位置し，桁行４間半，梁間４間半の規模で，木造２階建，切妻造，桟瓦葺とする。客室２室を並べ，６畳間を前室とし，８畳間の座敷をとり，広縁を付ける。床の間の落し掛けに面皮付きの桜材を用いるなど，近代の意匠的な工夫が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005877"},{"id":"00005856","register_sub_id":"101","register_pk":"106842","name":"花屋ホテルお城棟","kana":"はなやほてるおしろとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.351109,"lng":138.15984004,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積324㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0281","desc":"玄関の北側に建ち，桁行１１間，梁間４間の規模とし，木造２階建，入母屋造，桟瓦葺とする。１階を小規模の客室とし，２階を大広間とする。１階，２階周囲に連子窓を付け，軒を持ち送りで支えて塗り込め，城郭建築風の意匠とし，ホテル正面側の構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005856"},{"id":"00005881","register_sub_id":"101","register_pk":"106866","name":"花屋ホテル表棟","kana":"はなやほてるおもてとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.350697,"lng":138.159958,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積265㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0296","desc":"中広間の東側に位置し，敷地出入口の南脇に建つ。桁行１０間，梁間４間の規模で，木造２階建，入母屋造，桟瓦葺とする。客室棟で北西隅に玄関を付ける。２階窓に手摺を設け，庇下に欄間をとるなど，丁寧なつくりである。和風旅館の正面の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005881"},{"id":"00005870","register_sub_id":"101","register_pk":"106856","name":"花屋ホテル北渡廊下","kana":"はなやほてるきたわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.3511009,"lng":138.15933604,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0287","desc":"南渡廊下の西端から北西に中棟まで延び，長さ１５ｍ，幅１ｍの規模で，木造，切妻造，銅板葺とする。丸太柱を礎石立ちとし，側面吹き放ちで，手摺を設け，内法に小壁を設ける。数寄屋風の簡素な造りで，周囲の庭と一体となり，落ち着きのある景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005870"},{"id":"00005873","register_sub_id":"101","register_pk":"106859","name":"花屋ホテル五〇番棟","kana":"はなやほてるごじゅうばんとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.351265,"lng":138.15934007,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積181㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0289","desc":"本館の西側に位置し，中棟の南側に連続して建つ。桁行６間，梁間４間半規模で，木造２階建，入母屋造，桟瓦葺とする。８畳の座敷に前室を設けた客室２室を並べ，離れの形式をとる。昭和初期の旅館の活況によって増築した客室で，数寄屋の優れた技術が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005873"},{"id":"00005855","register_sub_id":"101","register_pk":"106841","name":"花屋ホテル事務室棟","kana":"はなやほてるじむしつとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.351013,"lng":138.159668,"geo_status":"db","era":"大正7／昭和7増築","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積550㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0280","desc":"敷地中央，本館の南側に東面して建つ。南側を帳場とし，桁行１７間，梁間５間半の規模で，木造２階建，寄棟造，桟瓦葺とする。２階は現在は食堂として使用し，正面に４連の格子窓を並べる。北側は入母屋造の屋根を東方に張り出し玄関とし，正面の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005855"},{"id":"00005859","register_sub_id":"101","register_pk":"106845","name":"花屋ホテル倉庫","kana":"はなやほてるそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.35080072,"lng":138.15976072,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0283","desc":"帳場の東方に位置し，桁行６間，梁間２間半の規模で，土蔵造２階建，切妻造，桟瓦葺とする。１階を倉庫として使い，２階は梁組を室内に見せた客室とする。外壁に縦長の窓を等間隔に並べる。ホテルの正面側に位置し，ホテルの表構えの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005859"},{"id":"00005858","register_sub_id":"101","register_pk":"106844","name":"花屋ホテル大浴室","kana":"はなやほてるだいよくしつ","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.350887,"lng":138.159439,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積99㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0282","desc":"帳場の西側に位置し，桁行６間，梁間５間半の規模で，木造平屋建，寄棟造，桟瓦葺とする。北側に下屋を張り出し脱衣室とし，女子風呂は南側に浴室を張り出す。浴室上部の壁に等間隔に窓を並べる。屋根に換気用の越屋根を上げ，温泉ホテルの中心的な施設とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005858"},{"id":"00005874","register_sub_id":"101","register_pk":"106860","name":"花屋ホテル中棟","kana":"はなやほてるなかとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.351154,"lng":138.159225,"geo_status":"db","era":"大正9頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積296㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0290","desc":"五〇番棟の西に接続して建ち，桁行１０間，梁間５間の規模で，木造２階建，切妻造，桟瓦葺とする。１階に大小の客室を配し，２階を格天井と鏡天井を配した豪華な広間とする。規模の比較的大きな建物で，両妻を漆喰で塗り込める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005874"},{"id":"00005860","register_sub_id":"101","register_pk":"106846","name":"花屋ホテル中広間・厨房棟","kana":"はなやほてるなかひろま・ちゅうぼうとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.3507919,"lng":138.15962676,"geo_status":"db","era":"大正期／昭和24増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積491㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0284","desc":"帳場の南側に隣接して建ち，桁行１５間半，梁間４間半の規模とし，木造２階建，寄棟造，桟瓦葺とする。１階を厨房とし，２階に中規模の広間を設ける。広間の南側と北側に廊下を設け，東西に床構えを備え，天井を格天井とし，優れた意匠の広間空間を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005860"},{"id":"00005875","register_sub_id":"101","register_pk":"106861","name":"花屋ホテル二七番棟","kana":"はなやほてるにじゅうななばんとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.35087269,"lng":138.15914265,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0291","desc":"大浴室の西側に建ち，桁行４間半，梁間４間半の規模で，木造平屋建，入母屋造，桟瓦葺とする。前室付きの８畳座敷に温泉浴室を付属する客室２室を並べ，離れの形式をとる。外部の庭園と一体となった質の高い落ち着いた客室空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005875"},{"id":"00005879","register_sub_id":"101","register_pk":"106864","name":"花屋ホテル八一番棟","kana":"はなやほてるはちじゅういちばんとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.35088862,"lng":138.15900645,"geo_status":"db","era":"大正9頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0294","desc":"奥棟の南側に位置し，桁行８間，梁間５間半の規模で，木造平屋建，寄棟造，桟瓦葺とする。広縁付きの座敷に書院をもった床構えを備え，続き間座敷の形式とする客室２室を並べ，共に温泉浴室を付属する。規模の大きな客室を備え，質及び規模とも優れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005879"},{"id":"00005869","register_sub_id":"101","register_pk":"106855","name":"花屋ホテル東渡廊下","kana":"はなやほてるひがしわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.35109059,"lng":138.15949207,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0286","desc":"南渡廊下西寄りから本館に延びる渡廊下で，長さ２２ｍ，幅１ｍの規模で，木造，切妻造，銅板葺とする。丸太柱に梁を架け束立てとする形式と，むくりを付けた梁に棟木を架ける形式を使い，柱間に手摺を設ける。数寄屋風の簡素な造りで，庭と一体の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005869"},{"id":"00005854","register_sub_id":"101","register_pk":"106840","name":"花屋ホテル本館","kana":"はなやほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.35119921,"lng":138.15954283,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積633㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0279","desc":"敷地中央の北方に位置し，桁行１３間半，梁間６間半の規模で，木造２階建，入母屋造，桟瓦葺とする。１，２階共に，８畳間を中心とした座敷に前室を付けた客室を配す。全室に広縁を設け，床構え等に優れた大工技術を用い，優れた意匠と上質の空間を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005854"},{"id":"00005867","register_sub_id":"101","register_pk":"106853","name":"花屋ホテル南渡廊下","kana":"はなやほてるみなみわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.35098055,"lng":138.15945328,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0285","desc":"事務室棟から西に延び，大浴場に至る渡廊下で，長さ１８ｍ，幅１．８ｍの規模で，木造，切妻造，鉄板葺とする。面皮柱を使い，桁を丸太とし，梁を渡し中央に束立てし，棟木を通す。側面を吹き放ちとし，数寄屋風の意匠とし，簡素で落ち着きのある景観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005867"},{"id":"00005880","register_sub_id":"101","register_pk":"106865","name":"花屋ホテル六一番棟","kana":"はなやほてるろくじゅういちばんとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.350697,"lng":138.159332,"geo_status":"db","era":"昭和25頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積140㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0295","desc":"中広間の南側に位置する客室棟で，桁行８間半，梁間４間半の規模で，木造平屋建，寄棟造，桟瓦葺とする。離れの形式をとり，３室を設け，西側に入母屋造の玄関を設ける。敷居に黒柿を用いるなど，床の間を中心に良材を使い，技術的に高度な形式が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005880"},{"id":"00008114","register_sub_id":"101","register_pk":"132512","name":"藤野屋旅館本館","kana":"ふじのやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上水内郡信濃町大字柏原字中島2711-22","lat":36.80839706,"lng":138.19683574,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積254㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"20 － 0357","desc":"黒姫駅前の通りに南面して建つ。木造２階建、東西棟の切妻造鉄板葺で、一部背面を葺き降ろす。建築面積２５４㎡。２階は中廊下で、南北各四部屋を並べる。正面には庇をかけ、大きく起る切妻屋根を中央に付けて玄関とする。明治末の旅館の佇まいをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008114"},{"id":"00000210","register_sub_id":"101","register_pk":"101200","name":"藤屋旅館","kana":"ふじやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市大字長野字大門町82","lat":36.65709985,"lng":138.18767251,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造3階建，建築面積967㎡","structure_material":"木造3階建","registered":"1997.06.12(平成9.06.12)","register_no":"20 － 0004","desc":"長野駅から善光寺へと向かう桟道に面して建つ。前面道路を十間に拡張する市区改正にあわせて建築された。外観はコンクリートにタイルを貼った意匠であるが、主体構造は木造である。その特異な意匠で、善光寺門前のランドマークとして広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000210"},{"id":"00008991","register_sub_id":"101","register_pk":"162351","name":"ブライダル染花みむら店舗","kana":"ぶらいだるせんかみむらてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪市諏訪1-10101-1","lat":36.04448555,"lng":138.11841248,"geo_status":"db","era":"昭和4年／昭和後期改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積63㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0388","desc":"三村貴金属店店舗の南隣に建ち、建築面積63㎡、木造二階建、片流れ屋根鉄板葺である。正面を洋風意匠とし、細部に幾何学意匠を用いた造形表現が試みられている。三村貴金属店店舗とともに個性的な外観の店舗として町並みを特徴付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008991"},{"id":"00010779","register_sub_id":"101","register_pk":"201614","name":"布袋屋小林家住宅主屋","kana":"ほていやこばやしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代字紺屋町504","lat":36.561649,"lng":138.199016,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積115㎡","structure_material":"木造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0491","desc":"松代城下の旧町人地にあたる紺屋町に所在し、北国街道脇往還に北面して建つ。正面に出格子や摺揚戸をたて、二階は漆喰塗込めとして横長の窓を穿つ。内部は通り土間と田字形平面をもつ伝統的な間取りをもつ。当地における町家の特徴を示す、もと店舗兼用住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010779"},{"id":"00010780","register_sub_id":"101","register_pk":"201615","name":"布袋屋小林家住宅土蔵","kana":"ほていやこばやしけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代字紺屋町504","lat":36.561411,"lng":138.199091,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0492","desc":"主屋の背面にあたる敷地南方に南北棟で建つ。土蔵造二階建で、一階北面に持送りで支える庇を付けて出入口を設ける。二階の三方に採光用の窓を設け、いずれも掛子塗を施して観音開きとし、丁寧な左官仕上げとする。伝統的な松代の町家の宅地空間を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010780"},{"id":"00004805","register_sub_id":"101","register_pk":"105795","name":"ますや旅館新築","kana":"ますやりょかんしんちく","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県小県郡青木村大字田沢2686","lat":36.36944144,"lng":138.10519484,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造3階建、瓦葺、建築面積209㎡","structure_material":"木造3階建","registered":"2005.07.12(平成17.07.12)","register_no":"20 － 0191","desc":"本館北東にやや離れて建ち階段室のある渡り廊下で連絡する。桁行８間，梁間６間，３階建，入母屋造，桟瓦葺で，１階を倉庫，２，３階に客室を配し４周に縁を廻らす。２，３階にも庇を付けた賑やかな外観で，本館，東館とともに最も目立つ東面の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004805"},{"id":"00004806","register_sub_id":"101","register_pk":"105796","name":"ますや旅館土蔵","kana":"ますやりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県小県郡青木村大字田沢2686","lat":36.3693296,"lng":138.10525226,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"20 － 0192","desc":"本館玄関南に接続する。桁行４間半，梁間３間，土蔵造，２階建，桟瓦葺の置き屋根で，西面戸口に下屋を付す。高く築いた切石積基礎上に建ち，細かな細工の鉢巻を廻し表通りに面して開く窓廻りを黒漆喰塗で飾るなど，老舗旅館の風格ある構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004806"},{"id":"00004803","register_sub_id":"101","register_pk":"105793","name":"ますや旅館西館","kana":"ますやりょかんにしかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県小県郡青木村大字田沢2686","lat":36.36921999,"lng":138.10501533,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造3階建、瓦葺、建築面積53㎡","structure_material":"木造3階建","registered":"2005.07.12(平成17.07.12)","register_no":"20 － 0189","desc":"本館の南西に接続し，南及び西面を通りに面して建つ。桁行４間，梁間３間半，３階建，入母屋造，桟瓦葺で，１，２階にも庇を廻らす。１階は倉庫とし，２，３階に客室を配し４周に縁を廻らす。小規模だが角地に面し，老舗旅館の風格ある構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004803"},{"id":"00004804","register_sub_id":"101","register_pk":"105794","name":"ますや旅館東館","kana":"ますやりょかんひがしかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県小県郡青木村大字田沢2686","lat":36.36935987,"lng":138.10530809,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造3階建、瓦葺、建築面積89㎡","structure_material":"木造3階建","registered":"2005.07.12(平成17.07.12)","register_no":"20 － 0190","desc":"本館の東南に建つ。桁行５間，梁間３間半，入母屋造，桟瓦葺の木造３階建で，１，２階にも庇を付け，１階は倉庫，２，３階は客室とし４周に縁を廻らす。旅館施設中最古の建物で，屋根に反りを付け２，３階の縁廻りを腕木で持ち出すなど，独特の外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004804"},{"id":"00004807","register_sub_id":"101","register_pk":"105797","name":"ますや旅館東蔵","kana":"ますやりょかんひがしぐら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県小県郡青木村大字田沢2686","lat":36.36927117,"lng":138.10545112,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"20 － 0193","desc":"通りを隔てて東館南方に建つ。桁行４間半，梁間３間，土蔵造，２階建，切妻造，桟瓦葺で，戸口を開く西面に下屋を付す。本屋，下屋とも軒を漆喰で塗り込め，腰廻りを海鼠壁風とした重厚な外観をもち，東館，土蔵と共に温泉場目抜き通りの歴史的景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004807"},{"id":"00004802","register_sub_id":"101","register_pk":"105792","name":"ますや旅館本館","kana":"ますやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県小県郡青木村大字田沢2686","lat":36.36936038,"lng":138.1050981,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造3階建、瓦葺、建築面積338㎡","structure_material":"木造3階建","registered":"2005.07.12(平成17.07.12)","register_no":"20 － 0188","desc":"田沢温泉の中心にある老舗旅館の本館で，通りの奥に建つ。桁行１４間，梁間６間，３階建，入母屋造，桟瓦葺で，１階を客溜りや賄いの部屋，２，３階に客室を取り周囲に縁を廻らす。大規模でたちが高く，内部に太い円柱を見せるなど内外とも豪壮な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004802"},{"id":"00003979","register_sub_id":"101","register_pk":"104969","name":"松本館旧館","kana":"まつもとかんきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県松本市丸の内7-39","lat":36.23716202,"lng":137.97278139,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積313㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"20 － 0179","desc":"松本市の中心部，松本城近傍に建つ料亭建築。長方形平面の２階建部と，平屋建の北西張出部からなる。２階は南端に階段を設けて他は一室の大広間「鳳凰の間」とし，地元の彫刻家太田南海の手による床柱や，折上格天井，建具など各所に壮麗な内装を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003979"},{"id":"00003980","register_sub_id":"101","register_pk":"104970","name":"松本館便所棟","kana":"まつもとかんべんじょとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県松本市丸の内7-39","lat":36.237045,"lng":137.97264877,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"20 － 0180","desc":"旧館の南西隅に，渡り廊下を介して接続する。南側は別棟に接し，庭園に面する北側は正八角形型の平面をなす。内部外部とも軸部を赤く塗り，天井は格天井とし絵様を描き，壁面上部には中国風の欄間を設けているなど，異国風の四阿を模した建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003980"},{"id":"00009754","register_sub_id":"101","register_pk":"195583","name":"丸山漆器店大谷石蔵","kana":"まるやましっきてんおおやいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"長野県","address":"長野県塩尻市大字奈良井字城1096-1他","lat":35.97100472,"lng":137.81704373,"geo_status":"db","era":"昭和36","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"石造3階建、瓦葺、建築面積33㎡","structure_material":"石造3階建","registered":"2013.12.24(平成25.12.24)","register_no":"20 － 0432","desc":"奈良井駅北側に建ち、石造三階建、切妻造、妻入、桟瓦葺である。大谷石積で、階境に水切を廻らし、妻にペディメントを表す。二階と三階の妻面に石庇付の窓を設ける。特徴的な外観をもち、丁寧に施工された石蔵で、伝統産業である漆器生産の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009754"},{"id":"00012535","register_sub_id":"101","register_pk":"367830","name":"万平ホテルアルプス館","kana":"まんぺいほてるあるぷすかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字桜ノ沢９２５－１","lat":36.350819,"lng":138.630157,"geo_status":"geocoded","era":"昭和11年／昭和48年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造3階建、金属板葺、建築面積1282㎡","structure_material":"木造3階建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0538","desc":"旧軽井沢中心部に建つ老舗ホテルの本館。木造三階建、切妻造妻入の大屋根を左右に並べた正面は欧州中世の町家風に上階の一部を出桁でせり出して異国情緒を表しつつ、本棟造風の細部など要所に和風意匠を加味する。山岳リゾートに相応しい意匠のホテル建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012535"},{"id":"00003235","register_sub_id":"101","register_pk":"104225","name":"三原屋商店北蔵","kana":"みはらやしょうてんきたぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字長野字桜枝町879-1","lat":36.65863652,"lng":138.18338438,"geo_status":"db","era":"明治5頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0122","desc":"店舗の西に隣接して南北棟で建つ。桁行５間半梁間２間半の２階建土蔵で，内部は南北２室に分け，東面に２戸の入口を開ける。大町道側の北妻面は下屋部を海鼠壁仕上げとして街路景観を整えるとともに，窓を高い位置に開け３階建の様に見せている点も特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003235"},{"id":"00003234","register_sub_id":"101","register_pk":"104224","name":"三原屋商店店舗","kana":"みはらやしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字長野字桜枝町879-1","lat":36.65858909,"lng":138.183426,"geo_status":"db","era":"明治5頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積144㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0121","desc":"「大町道」と「うちわや小路」との交差点西南角地に建つ。間口３間半規模，東西棟，片寄棟造の２階建店蔵の奥に南北棟の２階建土蔵を繋げた形状になる。店蔵部は入口を大きく採り，腰を瓦平積，軒を出桁造風とし，隣接の海鼠壁土蔵と対照的な表構えにつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003234"},{"id":"00008990","register_sub_id":"101","register_pk":"162350","name":"三村貴金属店店舗","kana":"みむらききんぞくてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪市諏訪1-10101-1","lat":36.04453127,"lng":138.11836194,"geo_status":"db","era":"昭和3年／昭和44年・平成7年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積78㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0387","desc":"諏訪市駅前の本町商店街に位置する。通りに面したファーサードは洋風に見せた看板建築。施工は諏訪建築株式会社で、設計は同社取締役の小口平助。諏訪には看板建築が多数残るが、今回が第１号。茅野出身の藤森先生が関わる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008990"},{"id":"00014373","register_sub_id":"101","register_pk":"511362","name":"山崎長兵衛商店旧店舗（荒町ＴｈｅＧＡＴＥ）","kana":"やまざきちょうべえしょうてん（あらまちざげーと）きゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県小諸市荒町二丁目2789-1","lat":36.32568611,"lng":138.42881389,"geo_status":"db","era":"大正15年／昭和30年代移築","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積145㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0618","desc":"小諸城下の荒町に所在する商家の洋風店舗。二階建、石造風意匠のモルタル仕上正面ファサードを立ち上げ、背後に片流れ屋根を架ける。一階南半を商品置場、北半を土間とミセ、二階は付書院床構えの大きな続き座敷とする。街道沿いの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014373"},{"id":"00002390","register_sub_id":"101","register_pk":"103380","name":"山田旅館新館","kana":"やまだりょかんしんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県北安曇郡小谷村大字中土18836","lat":36.86213008,"lng":137.98056223,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積250㎡","structure_material":"木造3階建","registered":"2001.10.12(平成13.10.12)","register_no":"20 － 0095","desc":"浴室の西妻面に接続し，西方から北方に向けて「く」の字形に折曲がって建つ。各層外部に庇を廻した入母屋造，もと板葺の総３階建木造客室棟で，現在は鉄板葺きとなり，各階外面部の欄干の外側にも建具を入れている。棟梁は山岸市太郎と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002390"},{"id":"00002387","register_sub_id":"101","register_pk":"103377","name":"山田旅館本館","kana":"やまだりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県北安曇郡小谷村大字中土18836","lat":36.86197942,"lng":137.98101202,"geo_status":"db","era":"江戸末期／明治17増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造3階建、鉄板葺、建築面積353㎡","structure_material":"木造3階建","registered":"2001.10.12(平成13.10.12)","register_no":"20 － 0092","desc":"信越国境の雨飾山を北の背とし，南に中谷川を臨む小谷温泉の老舗旅館。本館は，切妻造，もと石置板葺の木造３階建で，現在は建具が入っているが，１階西・南面に縁側，２階３階にヴェランダ状の縁廊下を廻すなど木造３階建旅館建築の佇まいを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002387"},{"id":"00002389","register_sub_id":"101","register_pk":"103379","name":"山田旅館浴室","kana":"やまだりょかんよくしつ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県北安曇郡小谷村大字中土18836","lat":36.86213557,"lng":137.98073434,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積96㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"20 － 0094","desc":"長屋の西妻面に接続し，西方の新館に向けて建つ。創建時は露天風呂を覆う簡素な上屋であったが，大正１５年に改築し浴室内を洋風に造る。外観は切妻造の２階建で，東隣の長屋よりはたちが高く，長屋・新館とともに温泉街的な町並みをつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002389"},{"id":"00006433","register_sub_id":"101","register_pk":"107416","name":"萬屋骨董店店舗兼主屋（旧小諸銀行）","kana":"よろずやこっとうてんぽけんしゅおく（きゅうこもろぎんこう）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県小諸市本町3-36","lat":36.32931464,"lng":138.42521249,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"20 － 0320","desc":"北国街道小諸宿の本町通りのほぼ中央に位置し南面して建つ。正面５間、奥行７間の平面規模で、切妻造、桟瓦葺、平入とする。黒漆喰で塗り込めた土蔵造町家風の銀行建築で、越屋根をのせ、正面両端に１階２階を通した２層分の袖卯建を建ち上げているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006433"},{"id":"00003648","register_sub_id":"101","register_pk":"104638","name":"よろづや旅館桃山風呂","kana":"よろづやりょかんももやまぶろ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県下高井郡山ノ内町大字平穏3137","lat":36.740025,"lng":138.420135,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"20 － 0171","desc":"切妻造，平入で，雄大な唐破風玄関を設け，内部は浴室と脱衣室からなり，浴槽は楕円形で縁や床に稲田石を用いる。架構は虹梁や組物など社寺建築の技法を巧みに用い，浴室天井は折上格天井とし，菱欄間や彫物欄間を要所に配している。設計は沖津清。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003648"},{"id":"00014814","register_sub_id":"101","register_pk":"519072","name":"旅館すぎもと松軒楼","kana":"りょかんすぎもとしょうけんろう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市大字里山辺字湯原451-7他","lat":36.24680556,"lng":138.00065556,"geo_status":"db","era":"昭和8年／昭和28年・同38年・平成5年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造3階建、瓦葺、建築面積143㎡","structure_material":"木造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0636","desc":"松本城北東の美ケ原温泉に位置し、西下がりの坂道沿いに建つ木造3階建の旅館。切妻造東西棟の南面西寄りに千鳥破風を付し、東寄りに入母屋造の南北棟を突出する。外壁は真壁の漆喰塗仕上。通りに面して高欄付きの窓を並べ、温泉街の景観をつくる旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014814"},{"id":"00009955","register_sub_id":"101","register_pk":"196102","name":"浅井銃砲火薬店店舗兼主屋","kana":"あさいじゅうほうかやくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県飛騨市神岡町船津字西町1196","lat":36.33251607,"lng":137.29774561,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造及び土蔵造2階建、瓦葺、建築面積270㎡","structure_material":"木造及び土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0220","desc":"通りに西面し、正面は二階建町家の立面をもち、右手にモルタル塗で内外とも洋風意匠の応接間を付属する。玄関後方に居室を連ねて最奥部に二階建の内蔵を建て、また応接間背後には丁寧な造作の客座敷を前庭に面して接続する。上質な和洋意匠の店舗兼用住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009955"},{"id":"00009956","register_sub_id":"101","register_pk":"196103","name":"浅井銃砲火薬店土蔵","kana":"あさいじゅうほうかやくてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県飛騨市神岡町船津字西町1196","lat":36.33259953,"lng":137.29775312,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階地下1階建、金属板葺、建築面積44㎡","structure_material":"土蔵造2階地下1階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0221","desc":"店舗兼主屋の北隣に並び建ち、土蔵造二階地下一階建、桁行四・八メートル梁間九・一メートル、切妻造金属板葺。周囲の土間を店舗兼主屋から張出した下屋で囲う。外壁は漆喰塗で二階北面に窓を穿つ。商家の屋敷構えを整える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009956"},{"id":"00009957","register_sub_id":"101","register_pk":"196104","name":"浅井銃砲火薬店塀","kana":"あさいじゅうほうかやくてんへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県飛騨市神岡町船津字西町1196-1","lat":36.33242637,"lng":137.29764088,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、金属板葺、総延長18m","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0222","desc":"敷地南西面に折曲がりにのびて前庭を囲む板塀。高さ一メートルほどのモルタル洗出しの基礎上に土台を伏せ、腕木で軒桁を支持して垂木を配り、金属板葺の屋根をかける。柱間を大和張として小壁に格子窓を並べる。落ち着いた佇まいの板塀が角地の景観を引立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009957"},{"id":"00009601","register_sub_id":"101","register_pk":"194597","name":"空穂屋店舗兼主屋","kana":"うつぼやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市靱屋町38他","lat":35.43094739,"lng":136.76695931,"geo_status":"db","era":"明治25頃／昭和初期・昭和中期増築","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積307㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"21 － 0210","desc":"金華山西麓の住宅地で、通りに東面して建つ二階建町家。切妻造桟瓦葺で、正面は一階腰を石貼とし、二階は格子を並べ、両端に袖うだつを設ける。敷地後方には茶室と二階建の紙倉庫を付属する。地元の伝統産業である紙問屋の特徴を良く示す大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009601"},{"id":"00009602","register_sub_id":"101","register_pk":"194598","name":"空穂屋土蔵","kana":"うつぼやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市靱屋町39","lat":35.4310628,"lng":136.76679931,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"21 － 0211","desc":"敷地の奥北寄りに建つ。桁行五・六メートル梁間三・五メートル、土蔵造二階建、切妻造桟瓦葺で、東妻を戸口とし、下屋で主屋に接続する。外壁は軒廻り鉢巻付きの大壁とし、正面に一間の下屋を附す。明治二四年の濃尾地震以前に遡る土蔵の数少ない遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009602"},{"id":"00006490","register_sub_id":"101","register_pk":"107473","name":"越前屋店舗兼主屋","kana":"えちぜんやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県郡上市八幡町新町926","lat":35.748852,"lng":136.957336,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、鉄板葺、建築面積129㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0152","desc":"通りに面して建つ、間口４間、奥行８間半の町家。切妻造、鉄板葺、平入の木造２階建。２階正面は繊細な千本格子の出格子とし、軒は出桁造とする。１階は店舗利用のために改造されているが、２階内部は座敷等がよく残る。当地域で比較的建築年代の古い町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006490"},{"id":"00006532","register_sub_id":"101","register_pk":"107515","name":"蒲酒造場主屋","kana":"かばしゅぞうじょうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町6-6","lat":36.234943,"lng":137.187012,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積263㎡、渡廊下及び雪隠付","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0130","desc":"壱之町通りに南面して建つ。明治３７年大火後，近郊所在の和田家住宅主屋を譲り受けて再建。間口１１間規模の大型平入町家で，東方を土間，西方を床上部とし，通り沿いに雪隠を設ける。多彩な連子格子や大戸等による長大な表構えが通り景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006532"},{"id":"00014014","register_sub_id":"101","register_pk":"508274","name":"旧岡田酒店店舗兼主屋","kana":"きゅうおかださけてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県揖斐郡大野町大字相羽字村通283-1","lat":35.45504722,"lng":136.63417222,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積203㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"21 - 0293","desc":"濃尾平野北部揖斐川支流に挟まれた相羽集落の川沿いに建つ酒造業の主屋。二階建、入母屋造桟瓦葺、道沿いに店舗の入口を開き、酒を小売りした店庭が土間の一角にある。土間吹抜は二階への荷揚げに用いた。床上は田の字型間取りの店舗兼主屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014014"},{"id":"00015453","register_sub_id":"101","register_pk":"533468","name":"旧纐纈家住宅（古民家あいせき）井戸","kana":"きゅうこうけつけじゅうたく（こみんかあいせき）いどやかた","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県関市本町七丁目13","lat":35.487,"lng":136.91388056,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、面積0.8㎡","structure_material":"石造","registered":"2025.08.06(令和7.08.06)","register_no":"21 - 0309","desc":"店舗兼主屋の北に設けた中庭の南寄りに位置する井戸である。井戸枠は〇・九メートル四方、高さ40センチメートル、厚さ15センチメートルの花崗岩切石4枚を精緻に組合わせ、深さは七メートルとする。茶室専用として使ったと伝え、中庭の景観をつくる井戸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015453"},{"id":"00015452","register_sub_id":"101","register_pk":"533467","name":"旧纐纈家住宅（古民家あいせき）茶室","kana":"きゅうこうけつけじゅうたく（こみんかあいせき）ちゃしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県関市本町七丁目13他","lat":35.48703056,"lng":136.91389167,"geo_status":"db","era":"昭和2年／令和3年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、銅板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"21 - 0308","desc":"店舗兼主屋の北面濡縁から渡廊下で繋がる茶室棟である。平屋建切妻造桟瓦葺で西が四畳席の茶室、東が四畳半大の客間で南面に内縁を付し、西に給仕口と水屋を設ける。渡廊下は片流銅板葺で、中庭側を吹放ちとする。造作など丁寧なつくりの近代和風建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015452"},{"id":"00015451","register_sub_id":"101","register_pk":"533466","name":"旧纐纈家住宅（古民家あいせき）店舗兼主屋","kana":"きゅうこうけつけじゅうたく（こみんかあいせき）てんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県関市本町七丁目13他","lat":35.48692222,"lng":136.91381667,"geo_status":"db","era":"明治中期／昭和16年・令和3年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"21 - 0307","desc":"本町通に南面して建つ旧酒店の店舗兼主屋である。二階建切妻造平入桟瓦葺で東半の屋根を落棟とする。内部は前土間とし、かつて信用購買組合事務室として使用した。二階は正面側を八畳の続き間座敷とし軸部など漆塗で仕上げる。近代の本町の繁栄を伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015451"},{"id":"00008692","register_sub_id":"101","register_pk":"149413","name":"旧櫻井銘木店店舗兼主屋","kana":"きゅうさくらいめいぼくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市元浜町30-1他","lat":35.43574444,"lng":136.7696782,"geo_status":"db","era":"明治中期／昭和14年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積199㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"21 － 0194","desc":"通りに南面する町家。間口7.9ｍの切妻造桟瓦葺、木造2階建で、背面には居室や台所などの2階屋を付設する。正面は下屋が大きく引違い戸の開口を設け、東寄りを格子窓とする。上屋は格子窓に黒漆喰壁とし、袖ウダツを付ける。伝統的な町家の表構えを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008692"},{"id":"00008693","register_sub_id":"101","register_pk":"149414","name":"旧櫻井銘木店土蔵","kana":"きゅうさくらいめいぼくてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市元浜町30-1","lat":35.435911,"lng":136.76960443,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積78㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"21 － 0195","desc":"主屋の北奥に位置する。梁間15ｍ桁行南4.7ｍ北5.8ｍの台形平面になる2階建土蔵。切妻造桟瓦葺。南・北中央に大きく開口を設け引込戸をたて、2階は南面に矩形の窓を穿つ。1、2階とも板床。材木商が集まった往時の長良川筋町並みの景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008693"},{"id":"00016387","register_sub_id":"101","register_pk":"536454","name":"旧旅籠柏屋主屋","kana":"きゅうはたごかしわやおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県可児郡御嵩町御嵩字南町1520-1","lat":35.42982222,"lng":137.13088611,"geo_status":"db","era":"江戸末期／令和4年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積161㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"21 - 0311","desc":"御嶽宿中心部、中山道に北面する旧旅籠。二階建切妻造平入桟瓦葺で一階正面は格子を並べ、二階は漆喰で軒まで塗込める。一階はかつて中土間を通し、南西に床構え付き座敷を残す。二階は正面側に四室、南東隅に一室を配す。宿場町の歴史を今に伝える大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016387"},{"id":"00007354","register_sub_id":"101","register_pk":"108336","name":"旧松喜仏壇店店舗兼主屋","kana":"きゅうまつきぶつだんてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市白木町96","lat":35.428974,"lng":136.765656,"geo_status":"db","era":"明治44／大正3頃増築・平成6改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積146㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"21 － 0166","desc":"通りに東面して建つ町家。間口６．３ｍ奥行１５ｍの木造２階建とその奥の台所や客間棟等からなる。正面の２階建は南に通り土間を配し、北にミセなど３室を一列に並べ、２階に６室設ける。出桁造で、２階に出格子や袖卯建を構えるなど、伝統的な町家構えを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007354"},{"id":"00004546","register_sub_id":"101","register_pk":"105536","name":"旧美濃町産業会館","kana":"きゅうみのまちさんぎょうかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県美濃市1901-3","lat":35.54712603,"lng":136.91249338,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、スレート葺、建築面積509㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"21 － 0053","desc":"美濃町信用購買販売利用組合が建設。桁行２２ｍ梁間１１ｍ規模，切妻造の木造総２階建で，外壁は腰タイル張、上部下見板張とし，正面の軒下には瓔珞飾りを付ける。窓の楣と窓台を繋げてほぼ全周に廻し，水平線を強調した外観意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004546"},{"id":"00009603","register_sub_id":"101","register_pk":"194599","name":"旧山岸写真館店舗兼主屋","kana":"きゅうやまぎししゃしんかんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県高山市馬場町1-61","lat":36.141381,"lng":137.26231729,"geo_status":"db","era":"昭和初期／昭和63改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、鉄板葺、建築面積75㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"21 － 0212","desc":"城山公園への登り口に東面して建つ。写真館として建てられた木造二階建の建物で、正面のモルタル塗の外壁に意匠を凝らす。三連縦長窓の上に欠円アーチを連続させたコーニスを廻らし、入口上の商号など各所に左官細工による装飾を配するなど瀟洒な外観を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009603"},{"id":"00009604","register_sub_id":"101","register_pk":"194600","name":"旧山岸写真館土蔵","kana":"きゅうやまぎししゃしんかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県高山市馬場町1-61","lat":36.14141967,"lng":137.26236785,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、鉄板葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"21 － 0213","desc":"店舗兼主屋北に隣接して南北棟で建つ。桁行三・六メートル梁間五・八メートル、土蔵造二階建、切妻造、置屋根式の鉄板葺。外壁は腰高のモルタル洗出しで上部漆喰壁とする。小規模な土蔵であるが、店舗兼主屋の洋風意匠と対照的に通りの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009604"},{"id":"00015454","register_sub_id":"101","register_pk":"533469","name":"昇平楼客殿","kana":"しょうへいろうきゃくでん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岐阜県","address":"岐阜県本巣市政田字五ノ坪137","lat":35.44019722,"lng":136.647375,"geo_status":"db","era":"昭和27年頃","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"21 - 0310","desc":"旧名鉄揖斐線政田駅前に位置する川魚料理店の座敷棟。切妻造桟瓦葺の南北棟で東、南、西に庇を廻す。座敷一〇畳の西面に床・棚を備え、次の間六畳の北面にも床・棚を持つ。庭に面して、一間幅の入側を通して畳敷とする。全体に造作の木太い書院座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015454"},{"id":"00002251","register_sub_id":"101","register_pk":"103241","name":"庄村家住宅主屋","kana":"しょうむらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県郡上市八幡町島谷1145","lat":35.748051,"lng":136.955154,"geo_status":"db","era":"明治初期頃","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期頃","structure":"木造2階建、亜鉛メッキ鋼板葺、建築面積188㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"21 － 0046","desc":"江戸時代より八幡の商業中心地であった今町の通りに面した商家。主屋は桁行６間の切妻造・平入で，絵様付の出桁で２階の格子窓を受け，起り屋根の庇を設ける。内部には装飾的な欄間等を用いた数寄屋風の座敷をもつ。規模も大きく各部の意匠が整った商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002251"},{"id":"00015191","register_sub_id":"101","register_pk":"530615","name":"寿美吉旅館主屋（旧住質店店舗兼主屋）","kana":"すみよしりょかんおもや（きゅうすみしちてんてんぽけんおもや）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県高山市本町四丁目21","lat":36.14604167,"lng":137.25705833,"geo_status":"db","era":"大正12年／昭和前期改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積115㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"21 - 0304","desc":"高山市街の宮川西岸に位置し、通りに西面して建つ二階建旅館。もとは質店の店舗兼主屋。一階正面の出格子は、上部を長方形、下部を正方形に組む高山に特徴的な縦格子を用い、通りの歴史的な景観を伝える。内部は玄関上部吹抜の整然とした梁組に見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015191"},{"id":"00015192","register_sub_id":"101","register_pk":"530616","name":"寿美吉旅館厨房棟（旧住質店味噌蔵）","kana":"すみよしりょかんちゅうぼうとう（きゅうすみしちてんみそぐら）","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県高山市本町四丁目21","lat":36.14603611,"lng":137.256975,"geo_status":"db","era":"大正後期／昭和前期・同25年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、鉄板葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"21 - 0305","desc":"主屋の北側に接して建つ旧味噌蔵。南北棟の土蔵造二階建で、屋根は切妻造鉄板葺の置屋根形式。内部一階は厨房で二階は納戸とし小屋組は登梁形式。西側に張出す下屋は鉄板葺、外壁は腰をモルタル洗出仕上、上部を格子構とし主屋とともに通りの景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015192"},{"id":"00015193","register_sub_id":"101","register_pk":"530617","name":"寿美吉旅館土蔵（旧住質店質蔵）","kana":"すみよしりょかんどぞう（きゅうすみしちてんしちぐら）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県高山市本町四丁目21","lat":36.14597778,"lng":137.25703611,"geo_status":"db","era":"大正12年／昭和前期改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"21 - 0306","desc":"主屋の南側に接して建つ旧質蔵。土蔵造二階建、切妻造南北棟、置屋根形式の鉄板葺。開口部には土扉を吊って、鉄製格子を嵌めるなど厳重なつくりとする。北面には主屋室内に向けて両開の掛子塗扉を吊り、要所を黒漆喰で装飾し、高い左官技術を見せる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015193"},{"id":"00010154","register_sub_id":"101","register_pk":"197987","name":"千歳楼栖鳳閣","kana":"せんざいろうせいほうかく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県養老郡養老町養老字松原1079他","lat":35.28465,"lng":136.541296,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"21 － 0235","desc":"流芳閣から廊下を介して北方に接続して建ち、東側を懸造として座敷からの眺望を得る。十畳の袖の間と、二室の八畳を中心として縁を廻らす。袖の間は竹内栖鳳筆と伝える絹本を天井に貼る。ガラス障子などを多用し、外光を積極的に取入れた室内空間を実現する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010154"},{"id":"00010152","register_sub_id":"101","register_pk":"197985","name":"千歳楼本館","kana":"せんざいろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県養老郡養老町養老字松原1079他","lat":35.284289,"lng":136.540968,"geo_status":"db","era":"明治13／昭和36頃改修","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造2階建、瓦葺及び鉄板葺、建築面積409㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"21 － 0233","desc":"養老公園北端の山際に位置する旅館建築。木造二階建で正面に車寄を張出す。二室の一五畳を中心とする一階は南東面に縁を廻らし、二階に二八畳の大広間を配する。浴室には養老の滝に見立てた模様の大理石を飾る。濃尾平野を望む景勝地に建つ、瀟洒な木造旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010152"},{"id":"00010153","register_sub_id":"101","register_pk":"197986","name":"千歳楼流芳閣","kana":"せんざいろうりゅうほうかく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県養老郡養老町養老字松原1079他","lat":35.284468,"lng":136.541168,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋一部3階建、瓦葺及び鉄板葺、建築面積216㎡","structure_material":"木造平屋一部3階建","registered":"2014.10.07(平成26.10.07)","register_no":"21 － 0234","desc":"本館北方に雁行して接続し、東面を懸造とする。客室のほか洗面所、三階建の月見台からなり、外壁は真壁とし、赤色の漆喰で仕上げる。客室は桜の間、竹の間、楓の間などと称し、それぞれの室名と室内意匠等との調和を図っている。風雅な趣の数寄屋座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010153"},{"id":"00006175","register_sub_id":"101","register_pk":"107159","name":"大黒屋旅館主屋","kana":"だいこくやりょかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県瑞浪市日吉町7905-1","lat":35.43117552,"lng":137.23391872,"geo_status":"db","era":"安政6","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造2階建、瓦葺、建築面積240㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0109","desc":"旧中山道に南面して建つ。桁行７間，梁間９間規模，木造２階建，切妻造，桟瓦葺で，正面に軒庇が付く。屋根は両妻に卯建を上げる。正面外壁は腰下見板張の上を黒漆喰塗とする。明治維新以前は問屋及び尾州家定本陣であり，宿場の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006175"},{"id":"00001709","register_sub_id":"101","register_pk":"102699","name":"天狗総本店","kana":"てんぐそうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県高山市本町1-21","lat":36.14096245,"lng":137.25848868,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、建築面積103㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"21 － 0031","desc":"商店街の角地に精肉店として建設された木造二階建で、外壁を立ち上げて洋風とする。二階の隅部に設けたベランダ、パラペット上に並ぶ尖塔、屋号の天狗をモチーフとする妻飾などに特色があり、伝統的な町並の中で異彩を放っている。大工は地元の西田清。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001709"},{"id":"00011696","register_sub_id":"101","register_pk":"210712","name":"長瀬茂八郎商店店舗兼主屋","kana":"ながせもはちろうしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県高山市上一之町36-2","lat":36.142071,"lng":137.260954,"geo_status":"db","era":"大正期／昭和期・平成元年改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺一部鉄板葺、建築面積71㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"21-0249","desc":"大正二年の大火後程なく再建された町家。上一之町の通りに東面して建つ。正面二階の壁面を一階より半間後退させるのが特徴。間口五間、奥行四間で一階南側を通り土間とし、奥側を吹抜けとする。二階の座敷や茶室は製茶業を営んだ施主が趣向を凝らしたもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011696"},{"id":"00011697","register_sub_id":"101","register_pk":"210713","name":"なべしま銘茶店舗兼主屋","kana":"なべしまめいちゃてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県高山市下一之町12","lat":36.144386,"lng":137.259925,"geo_status":"db","era":"明治中期／昭和中期・同56年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、鉄板葺、建築面積206㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"21-0250","desc":"明治二五年の大火後の再建で、下一之町の通りに東面して建つ。正面二階の壁面を一階より半間後退させるのが特徴で、二階開口部には板連子を入れる。一階南側を通り土間とし、二階は一部を吹抜けとして直材による梁組を見せる。豪商の繁栄を示す大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011697"},{"id":"00011698","register_sub_id":"101","register_pk":"210714","name":"なべしま銘茶土蔵","kana":"なべしまめいちゃどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県高山市下一之町12","lat":36.144363,"lng":137.259837,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、鉄板葺、建築面積68㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"21-0251","desc":"店舗兼主屋の西側、敷地奥に建つ南北五間、東西四間の土蔵。置屋根形式で切妻の南北棟、平入。外壁は白漆喰で仕上げ、一階に両開扉を持つ入口と窓を、二階に窓を二つ設ける。柱をやや内転びに立てる手法など、当地域における土蔵の古式を見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011698"},{"id":"00006383","register_sub_id":"101","register_pk":"107366","name":"八ツ三館大広間棟","kana":"やつさんかんおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県飛騨市古川町向町1-8-33","lat":36.23306542,"lng":137.18775121,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積283㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0146","desc":"本館の後方に南北棟で建つ、入母屋造桟瓦葺の２階建。荒城川沿いに玄関を設け、１階には応接間や数室の和室、２階に大広間を設ける。大広間は畳廊下を含め１００畳の広さで、大床や違棚、付書院を備える。良質な材を使い、上質な空間を造り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006383"},{"id":"00006382","register_sub_id":"101","register_pk":"107365","name":"八ツ三館土蔵","kana":"やつさんかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町向町1-8-33","lat":36.23306293,"lng":137.1878621,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造2階建、瓦葺、建築面積90㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0147","desc":"本館と大広間の間に、南北棟で建つ。切妻造桟瓦葺の置屋根で、桁行６間、梁間４間と規模が大きい２階建である。本館側に前室を設け両開の土戸をたて、それ以外に開口を設けない。地棟に登梁を架ける小屋組や軸部に大材を用いるなど、力強い空間である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006382"},{"id":"00006381","register_sub_id":"101","register_pk":"107364","name":"八ツ三館本館","kana":"やつさんかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町向町1-8-33","lat":36.23304948,"lng":137.18754766,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積385㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0145","desc":"荒城川に架かる霞橋のたもと、県道に面して建つ。桟瓦葺の２階建で、南北棟の入母屋造を正面に、その奥に両下造の東西棟を突出させる。２階に客室を主に設け、１階には吹抜けのホールや応接室、浴室ほかを配する。各室ごとにデザインを違え、見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006381"},{"id":"00008000","register_sub_id":"101","register_pk":"128832","name":"湯之島館玄関","kana":"ゆのしまかんげんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県下呂市湯之島字平岩625","lat":35.81210254,"lng":137.24161984,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積161㎡","structure_material":"木造平屋一部2階建","registered":"2010.01.15(平成22.01.15)","register_no":"21-0179","desc":"渡り廊下を挟んで本館の西側に建つ。木造平屋一部２階建、桟瓦葺、建築面積１６１㎡。１階の南北棟入母屋屋根の中央に、２階の東西棟入母屋屋根が載り、西向きの玄関ポーチ上に入母屋造の妻面を見せる。重層する屋根と黒漆喰仕上げの外壁が重厚な趣を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008000"},{"id":"00007998","register_sub_id":"101","register_pk":"128830","name":"湯之島館本館","kana":"ゆのしまかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県下呂市湯之島字平岩625","lat":35.81205415,"lng":137.24200682,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造3階建、瓦葺、建築面積462㎡","structure_material":"木造3階建","registered":"2010.01.15(平成22.01.15)","register_no":"21-0177","desc":"南斜面の敷地中央に建つ。木造３階建、入母屋造桟瓦葺、建築面積４６２㎡。中廊下を挟んで西と南を客室、北と東を便所や食堂などにあてる。眺望を考慮し、南側は客室を雁行に配し、窓を連続させ開放的に扱う。内部も良質で、和風意匠の粋を凝らした建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007998"},{"id":"00007999","register_sub_id":"101","register_pk":"128831","name":"湯之島館渡り廊下","kana":"ゆのしまかんわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県下呂市湯之島字平岩625","lat":35.81208744,"lng":137.24180696,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"21-0178","desc":"本館の西側に接続して建つ。梁間２．２ｍ、桁行折曲り延長１３ｍで、木造平屋建、銅板葺。化粧屋根裏天井で、窓上の小壁は赤壁とし、ガラス戸の外側に格子を付け、腰は杉皮張とする。四季折々の眺望を楽しむ本館への導入空間として巧みな意匠につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007999"},{"id":"00010303","register_sub_id":"101","register_pk":"199076","name":"吉田家住宅主屋","kana":"よしだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県美濃加茂市太田本町2丁目字上町3799","lat":35.438125,"lng":137.015924,"geo_status":"db","era":"江戸末期／明治中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積188㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"21-0237","desc":"中山道太田宿のもと旅籠で旧道に北面して建つ。間口六間で前面に下屋を設けて出格子をたて、正側面の上部は軒まで漆喰で塗込め、正面では長押や軒の腕木を表し、両端に袖壁を設ける。内部は西寄りに居室を並べる。太田宿に残る近世の旅籠として貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010303"},{"id":"00009170","register_sub_id":"101","register_pk":"164723","name":"旅館かみなか土蔵","kana":"りょかんかみなかどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県高山市花岡町1-5-4","lat":36.14348434,"lng":137.25267537,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本館の北隣に建つ。桁行5.6メートル梁間4.8メートル、土蔵造2階建、切妻造桟瓦葺。外壁は漆喰塗で軒に鉢巻を廻らし、腰をモルタル洗出しとする。上下各階に本館への出入口を設け、土蔵内に階段を設けないという、特徴的なつくりになる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009170"},{"id":"00009169","register_sub_id":"101","register_pk":"164722","name":"旅館かみなか本館","kana":"りょかんかみなかほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県高山市花岡町1-5-4","lat":36.14335585,"lng":137.25269202,"geo_status":"db","era":"明治中期／昭和33年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、鉄板葺、建築面積398㎡","structure_material":"木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"通りに西面し、木造2階建、建築面積398平方メートル、切妻造及び寄棟造、鉄板葺である。正面中央の玄関に唐破風造桟瓦葺の庇を付ける。上下階とも周囲に出格子を建て瀟洒な外観とする。内部造作も意匠を凝らしており、往時の賑わいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009169"},{"id":"00000785","register_sub_id":"101","register_pk":"101775","name":"新井旅館あやめの棟","kana":"あらいりょかんあやめのとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市修善寺970","lat":34.97020017,"lng":138.92704427,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造一部鉄筋コンクリート造地上２階地下１階建，瓦葺，建築面積111㎡","structure_material":"木造一部鉄筋コンクリート造地上２階地下１階建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0026","desc":"｢天平風呂｣の南に隣接して建つ。木造２階建で，１階・２階は１０畳間を主室とする２客室づつの構成をとり，地階に「あやめ風呂」を設ける。「あやめ風呂」は，「天平風呂」と同様に池に面し，池中が見える仕組みになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000785"},{"id":"00000778","register_sub_id":"101","register_pk":"101768","name":"新井旅館霞の棟","kana":"あらいりょかんかすみのとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県伊豆市修善寺970","lat":34.97012682,"lng":138.9267319,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造３階建，瓦葺，建築面積170㎡","structure_material":"木造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0019","desc":"「雪の棟」の南方に位置し，南に桂川を臨む。１階は半地下の宴会場，２階３階客室構成の建物で，瓦葺入母屋屋根の妻を塗込め，真壁造りの外観とする。客室は，赤松の芯去り材の極上物で造られ，随所に優れた木工技術と用材の妙を見ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000778"},{"id":"00000781","register_sub_id":"101","register_pk":"101771","name":"新井旅館甘泉楼","kana":"あらいりょかんかんせんろう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県伊豆市修善寺字温泉場968-3","lat":34.97062037,"lng":138.92707328,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造２階建，銅板葺，建築面積411㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0022","desc":"修禅寺寄りの敷地のメイン建物で，「月の棟」とは地下通路で結ばれる。１階を大浴場（現在は温泉プール），２階を１２０畳舞台付大広間とし，南面と北面の柱１本置きに舟肘木を付け，外部に硝子障子を建て回す。瓦棒銅板葺の大屋根が他の棟と対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000781"},{"id":"00000788","register_sub_id":"101","register_pk":"101778","name":"新井旅館観音堂","kana":"あらいりょかんかんのんどう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市修善寺978-1","lat":34.97042354,"lng":138.92585814,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造平屋建，瓦葺，建築面積17㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0029","desc":"新井旅館当主相原家の持仏堂で，敷地の西北隅に南面して建つ。鉄筋コンクリートで円柱・斗・舟肘木を造り，本瓦葺の宝形屋根を架ける。新潟県出雲崎の良寛堂（大正１１年）と形式を同一としていることから，安田靫彦の関与が推測される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000788"},{"id":"00000779","register_sub_id":"101","register_pk":"101769","name":"新井旅館桐の棟","kana":"あらいりょかんきりのとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県伊豆市修善寺字小坂980他","lat":34.97044656,"lng":138.92638172,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造２階建，瓦葺，建築面積178㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0020","desc":"「雪の棟」の北西，「華の池」に接して建ち，池中の「乙姫島」に対峙する。木造２階建の客室棟で，瓦葺の入母屋屋根に緩やかなムクリをつける。南面は，２階軒庇を瓦葺，１階庇を銅板葺とし，真壁造りによる端正な立面を水面に映す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000779"},{"id":"00000783","register_sub_id":"101","register_pk":"101773","name":"新井旅館山陽荘","kana":"あらいりょかんさんようそう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市修善寺字小坂995","lat":34.97098509,"lng":138.92685026,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造２階建，瓦葺，建築面積118㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0024","desc":"「紅葉」の北，敷地の最奥部に位置する。横山大観の滞在用に建てられた棟で，１階２階共１２畳半１０畳続きの間をもち，北と南の２面に縁廊下を付す。真壁造りとし，勾配の緩い寄棟屋根を架けたのびやかな構成をとる。｢大観ギャラリー｣として開放されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000783"},{"id":"00000775","register_sub_id":"101","register_pk":"101765","name":"新井旅館青州楼","kana":"あらいりょかんせいしゅうろう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県伊豆市修善寺970","lat":34.97039924,"lng":138.92705572,"geo_status":"db","era":"明治14","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造３階建，瓦葺，建築面積276㎡","structure_material":"木造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0016","desc":"修禅寺近く，桂川沿いに位置する修善寺温泉を代表する旅館。明治５年，酒造蔵元から養気館「新井」として創業し，昭和１０年代までに主要施設を整えたとされる。青州楼は，唐破風付きの城郭風建築で，六角塔屋をもち，「新井旅館」のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000775"},{"id":"00000780","register_sub_id":"101","register_pk":"101770","name":"新井旅館月の棟","kana":"あらいりょかんつきのとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県伊豆市修善寺字温泉場970他","lat":34.9704455,"lng":138.92671648,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造一部鉄筋コンクリート造地上３階地下１階建，瓦葺，建築面積599㎡","structure_material":"木造一部鉄筋コンクリート造地上３階地下１階建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0021","desc":"新井旅館の本館ともいうべき棟で，玄関ロビー，フロント，厨房，館主の住居部を含む。木造３階建，真壁造りで，東面に正面玄関を設ける。玄関車寄は中央を一段高く突き上げた造りで，平等院鳳凰堂を模したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000780"},{"id":"00000784","register_sub_id":"101","register_pk":"101774","name":"新井旅館天平風呂","kana":"あらいりょかんてんぴょうぶろ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市修善寺字温泉場970他","lat":34.97027674,"lng":138.92702365,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積113㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0025","desc":"「青州楼」の南,「あやめの棟」との間に建つ４間×４間,本瓦葺，総檜の浴場建築。３代当主と親交深った安田靫彦が，ビザンチン様式の計画案を天平様式に変え，自ら設計にあたったとされる。浴場内から池の鯉を眺める趣向もユニークである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000784"},{"id":"00000786","register_sub_id":"101","register_pk":"101776","name":"新井旅館花の棟","kana":"あらいりょかんはなのとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市修善寺字久保1026-1他","lat":34.97009708,"lng":138.92633254,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造２階建，瓦葺，建築面積248㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0027","desc":"「雪の棟」の南西に位置し，「華の池」を挟んで「桐の棟」に向き合う｡南は桂川を眼下に見,対岸の竹林を借景とする｡木造２階建,１階・２階共４客室の客室棟で，庇を銅板葺とするなど数寄屋風の趣をもつ。安田靫彦の監修になるとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000786"},{"id":"00000789","register_sub_id":"101","register_pk":"101779","name":"新井旅館水蔵","kana":"あらいりょかんみずぐら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市修善寺978-1","lat":34.97047318,"lng":138.92599382,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積20㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0030","desc":"相原家所有になる重要文物類の収蔵庫で，「観音堂」の東に隣接して建つ。半地下形式の鉄筋コンクリート造陸屋根の建物で，周囲に７０ｃｍ幅の石積みの堀を回す。万一の場合，堀に水を引き入れて収蔵品を守ろうというユニークなものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000789"},{"id":"00000782","register_sub_id":"101","register_pk":"101772","name":"新井旅館紅葉","kana":"あらいりょかんもみじ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市修善寺小坂995","lat":34.97084631,"lng":138.92679886,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積82㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0023","desc":"南と東の２面に広縁をもつ８畳６畳続きの上質の客室棟で，「甘泉楼」の北西に建ち,「甘泉楼」とは渡廊下で結ばれる｡外部意匠は，屋根瓦に京都産のものを用い，庇回りを銅板葺，外壁をベンガラ色とするなど京風の趣をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000782"},{"id":"00000776","register_sub_id":"101","register_pk":"101766","name":"新井旅館雪の棟","kana":"あらいりょかんゆきのとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県伊豆市修善寺字温泉場970他","lat":34.97028102,"lng":138.9266034,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造２階建，瓦葺，建築面積258㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0017","desc":"２代当主が造成した池泉庭園と同時期の増築棟。敷地のほぼ中央，「華の池」から導かれた二つの流れに挟まれた場所に建つ。客室部は木造２階建，真壁造りで，南東に浴室棟を張りだす。浴室棟はムクリ付の入母屋の屋根に煙だしの小屋根を載せた特徴的な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000776"},{"id":"00000787","register_sub_id":"101","register_pk":"101777","name":"新井旅館吉野の棟","kana":"あらいりょかんよしののとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市修善寺1026-1・2、1027","lat":34.97006399,"lng":138.92605457,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造２階建，瓦葺，建築面積231㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0028","desc":"「花の棟」の西,敷地の西南端に建つ離れ風の客室棟で,「花の棟」と連絡はしているものの，別個の玄関をもつ。各客室の間取りもゆったりとり，天城杉の良材を用いるなど当時新井旅館が最も力を注いだ建築とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000787"},{"id":"00000777","register_sub_id":"101","register_pk":"101767","name":"新井旅館渡りの橋","kana":"あらいりょかんわたりのはし","category":"産業3次","subcategory":"その他工作物","type_guess":"橋","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県伊豆市修善寺970","lat":34.9703427,"lng":138.92669592,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積258㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0018","desc":"新井旅館の本館ともいうべき｢月の棟｣と｢雪の棟｣とを連絡する。屋根付きの太鼓橋で，床は，小幅板を目透かしに貼って水流を見せる趣向をとり，滑り止めの横木を打つ。宿泊客が来館記念の写真を撮る格好の場所となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000777"},{"id":"00010460","register_sub_id":"101","register_pk":"199419","name":"伊東市立木下杢太郎記念館","kana":"いとうしりつきのしたもくたろうきねんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県伊東市湯川2-70-5","lat":34.973736,"lng":139.095965,"geo_status":"db","era":"明治40／昭和60改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"22 － 0208","desc":"通りに南面する二階建、寄棟造桟瓦葺で、軒蛇腹を廻らすなど土蔵風の外観をもつ。中央右寄りに土間を通し、奥寄りと二階に居室を配する。展示室としている前半部は、もと広い板の間のミセで前側一間も土間であった。当地の伝統的な商家の形態を良好に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010460"},{"id":"00014831","register_sub_id":"101","register_pk":"519091","name":"大橋酒店奥蔵","kana":"おおはしさけてんおくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県磐田市見付字東坂1232-1","lat":34.72658611,"lng":137.860375,"geo_status":"db","era":"明治27年／平成18年改修","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造2階建、瓦葺、建築面積56㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"22 - 0326","desc":"東海道見付宿の中ほどに位置する酒屋の土蔵。敷地の南奥に東西棟で建ち、土蔵造二階建、切妻造桟瓦葺で鉢巻を廻らす。北面に桟瓦葺の下屋を設けて東端を米蔵とする。小屋組はトラス組。外壁の腰を簓子下見板張及び海鼠壁とする。酒屋の敷地を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014831"},{"id":"00014832","register_sub_id":"101","register_pk":"519092","name":"大橋酒店新蔵","kana":"おおはしさけてんしんぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県磐田市見付字東坂1232-1","lat":34.72675278,"lng":137.86028333,"geo_status":"db","era":"明治30年／令和元年改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積23㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"22 - 0327","desc":"敷地中央に南北棟で建ち、土蔵造二階建、切妻造桟瓦葺である。外壁は軒まで漆喰で塗込めて水切を三段付し、腰の伊豆石張で意匠を整える。東面中央を戸口とし、重厚な両扉戸を付す。小屋組はトラス組とする。酒屋の屋敷構えを形成する丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014832"},{"id":"00000829","register_sub_id":"101","register_pk":"101819","name":"大旅籠柏屋","kana":"おおはたごかしわや","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県藤枝市岡部町岡部817","lat":34.86744455,"lng":138.25776101,"geo_status":"db","era":"天保7頃","year":1836,"year_source":"db","year_min":1836,"year_max":1836,"year_label":null,"structure":"木造２階建，瓦葺，建築面積270㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"22 － 0032","desc":"旧東海道岡部宿を代表する旅籠屋の一つで，宿の北寄りに建つ桁行九間，梁間八間半の大型の町家である。明治中期頃に廃業した後，間取りの変更や棟を上げて桟瓦葺に変えるなど改造があるが，全体として保存はよい。近年保存修理され，公開活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000829"},{"id":"00001911","register_sub_id":"101","register_pk":"102901","name":"懐古堂ムラカミ屋","kana":"かいこどうむらかみや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県三島市大社町1247-1他","lat":35.11972807,"lng":138.91950596,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積136㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"22 － 0071","desc":"関東大震災後，三嶋大社前の商店街に建てられた看板建築。木造２階建，鉄板葺で，ショーウィンドーを入口両側に，２階窓を水平に構え，正面左右対称とする。ファサード一面を銅板で仕上げ，軒蛇腹と窓下で張り方に変化をつける。現在ギャラリーとして活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001911"},{"id":"00010975","register_sub_id":"101","register_pk":"208945","name":"川奈ホテル本館","kana":"かわなほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊東市川奈字セットノ畠1459-2他","lat":34.939649,"lng":139.140629,"geo_status":"db","era":"昭和11／昭和33頃改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造3階建一部地階及び塔屋付、瓦葺、建築面積2453㎡","structure_material":"鉄筋コンクリート造3階建一部地階及び塔屋付","registered":"2016.02.25(平成28.02.25)","register_no":"22-0219","desc":"太平洋を望むリゾートホテル。テラスは高大な列柱空間を創り、隣に張出すサンパーラーは先端を半円形平面のガラス張とし、雄大な眺望を得る。吹抜けのロビーなどは様々な洋風意匠を駆使し、随所に高級石材や装飾タイルなどを使い、気品ある優れた造形になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010975"},{"id":"00006022","register_sub_id":"101","register_pk":"107007","name":"旧和泉屋（お休み処）","kana":"きゅういずみや（おやすみどころ）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"静岡県","address":"静岡県静岡市清水区蒲原3-25-3","lat":35.120251,"lng":138.605682,"geo_status":"db","era":"江戸末期／昭和期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積57㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"22 － 0117","desc":"旧東海道に面して建つ。間口２間，奥行８間半，木造２階建で，東側に通り土間を設け，西側に３室を並べた町家の形態とする。屋根は切妻造で，２階軒を出桁造とする。元は隣家の鈴木家と一体で，かつては旅籠を営み，旧街道沿いの景観を伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006022"},{"id":"00010461","register_sub_id":"101","register_pk":"199420","name":"旧加藤酒店店舗兼主屋","kana":"きゅうかとうさけてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県富士市本町30","lat":35.154621,"lng":138.65083,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積143㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"22 － 0209","desc":"商店街に所在する町家形式の店舗兼用住宅。正面に成の高い桁を通し、二階は出桁造とする。店舗部にカウンターや傾斜付の量売り台など酒店の設えを残し、二階は和室主体ながら洋間も附属し、何れも材工共に質が高い。製紙業を主とした当地の隆盛をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010461"},{"id":"00007501","register_sub_id":"101","register_pk":"108483","name":"旧小松楼本館","kana":"きゅうこまつろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県湖西市新居町新居俵町1190-3","lat":34.69404452,"lng":137.55983531,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積123㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"22 － 0135","desc":"旧新居宿内の通りに面して建つ。間口１０ｍ奥行１２ｍ、木造２階建、切妻造桟瓦葺。正面外観は、１階の正面中央を玄関、両脇を出格子とする。２階は高欄付の縁で、雨戸建とする。内部は大小の座敷を配し、色壁とするなど、料理茶屋の特徴を留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007501"},{"id":"00016388","register_sub_id":"101","register_pk":"536455","name":"旧関家住宅（つたや）主屋","kana":"きゅうせきけじゅうたく（つたや）おもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県磐田市掛塚字砂町1108","lat":34.673475,"lng":137.79691111,"geo_status":"db","era":"明治21年頃／昭和10年移築","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造2階建、瓦葺、建築面積67㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"22 - 0344","desc":"天竜川の港町として栄えた掛塚の中心部で敷地北寄りに建つ住宅主屋。二階建寄棟造桟瓦葺で、軒を出桁造とし、二階北面にガラス窓を建てる。一階は根太天井を主とする質実なつくりで、二階座敷は良材を用い、床と床脇を設える。天竜川舟運の繁栄を伝える主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016388"},{"id":"00016389","register_sub_id":"101","register_pk":"536456","name":"旧関家住宅（つたや）土蔵","kana":"きゅうせきけじゅうたく（つたや）どぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県磐田市掛塚字砂町1108","lat":34.67329167,"lng":137.7969,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"22 - 0345","desc":"敷地南寄りに東西棟で建つ商品蔵。桁行四間、梁間二間、土蔵造切妻造桟瓦葺で、北面に下屋を付す。一階は外壁を伊豆石の布積とし、下屋正面中央に欠円アーチの戸口を開ける。二階は土壁の大壁で漆喰仕上とし、西妻に窓を開く。地方的特色を示す堅牢な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016389"},{"id":"00010783","register_sub_id":"101","register_pk":"201618","name":"旧田代家住宅主屋","kana":"きゅうたしろけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県浜松市天竜区二俣町鹿島489","lat":34.856311,"lng":137.807472,"geo_status":"db","era":"安政6","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造2階建、瓦葺、建築面積233㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"22 ‐ 0213","desc":"天竜川畔の敷地中央に南面して建つ。木造二階建、切妻造の三面に下屋を廻らせ、軒は上下階とも出桁造とする。右土間形式で、六間取の中央列前面に式台を構える。二階は八畳主体の座敷に床などを備え、南面に開放的な縁を通す。舟運による繁栄を伝える大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010783"},{"id":"00011706","register_sub_id":"101","register_pk":"210722","name":"三養荘本館御幸の間","kana":"さんようそうほんかんみゆきのま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"静岡県","address":"静岡県伊豆の国市墹之上字谷戸洞270-1他","lat":35.03994,"lng":138.933169,"geo_status":"db","era":"昭和32年","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"22-0239","desc":"本館中央棟から北に渡廊下を介して建つ入母屋造、一文字瓦葺の平屋建。座敷一二畳半、次の間一〇畳の三方に縁を廻らし、南に八畳と三畳が付く。本館の他の建物とは濡縁・高欄を設ける点が異なる。渡廊下も、北半内壁を水色の大津壁とするなど意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011706"},{"id":"00000535","register_sub_id":"101","register_pk":"101525","name":"静岡銀行本店（旧静岡三十五銀行本店）","kana":"しずおかぎんこうほんてん（きゅうしずおかさんじゅうごぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市葵区呉服町1-10","lat":34.97576201,"lng":138.37902807,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積826㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.04.21(平成10.04.21)","register_no":"22 － 0010","desc":"静岡の中心街に建つ銀行社屋。石造風に見せるＲＣ造で，街路に面する２面はいずれも４本のドリス式のオーダーを持ち，交差点からの斜めの外観全体もシンメトリーをなしている。中村與資平の設計で，中規模ではあるが重厚な銀行社屋として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000535"},{"id":"00000291","register_sub_id":"101","register_pk":"101281","name":"清水銀行由比支店本町特別出張所","kana":"しみずぎんこうゆいしてんほんまちとくべつしゅっちょうじょ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県静岡市清水区由比41","lat":35.10689101,"lng":138.56650672,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート2階建，建築面積75㎡","structure_material":"鉄筋コンクリート2階建","registered":"1997.09.03(平成9.09.03)","register_no":"22 － 0005","desc":"庚子銀行の本店社屋として建てられ，後に合併を経て現在に至る。立面は４本のイオニア式柱頭を持つ柱を立て，古典様式の基本に則る。内部は吹抜けの広い空間を持つ。小規模ながら洗練された様式を持つ，大正期の地方における銀行建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000291"},{"id":"00005974","register_sub_id":"101","register_pk":"106959","name":"鈴木家住宅店舗兼主屋","kana":"すずきけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県静岡市清水区蒲原3-25-4","lat":35.120235,"lng":138.605621,"geo_status":"db","era":"江戸末期／昭和期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積127㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"22 － 0118","desc":"旧東海道に面して建つ。間口４間，奥行９間，木造２階建で，中央に通り土間を設け，両側に各４室並べた町家の形態とする。屋根は切妻造で，２階軒を出桁造とする。元は隣家の旧和泉屋と一体で，かつては旅籠を営み，旧街道沿いの景観を伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005974"},{"id":"00014157","register_sub_id":"101","register_pk":"508787","name":"丁子屋店舗","kana":"ちょうじやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和後","pref":"静岡県","address":"静岡県静岡市駿河区丸子七丁目2578-1他","lat":34.95024444,"lng":138.3381,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、茅葺一部鉄板葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"22-0314","desc":"東海道に南面する丸子宿の老舗茶店。平屋建、寄棟造茅葺で正面に下屋を付し、背面に棟を直交して切妻造金属板葺の座敷棟が接続。近隣農家の部材を再用した主体部と、明治期の前身店舗座敷を資料室で繋ぎ一体として構成。広重作丸子宿の画から着想を得た建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014157"},{"id":"00004361","register_sub_id":"101","register_pk":"105351","name":"潮生館香梅荘","kana":"ちょうせいかんこうばいそう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県藤枝市志太600-2","lat":34.8680991,"lng":138.23199883,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"22 － 0094","desc":"本館の北西方，池辺に建つ。平屋建，入母屋造，桟瓦葺の主体部に北東の玄関，北西の小座敷を付属する。主体部は８畳床棚付の主室と６畳の次の間，小座敷は床棚付の６畳，玄関は３畳の寄付を備える。内外とも薄紅色漆喰壁とし，梅花模様を配して意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004361"},{"id":"00004360","register_sub_id":"101","register_pk":"105350","name":"潮生館本館","kana":"ちょうせいかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県藤枝市志太600-2-2","lat":34.86808781,"lng":138.23245405,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積198㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"22 － 0093","desc":"志太温泉の礎となった旅館の本館。２階建，入母屋造，桟瓦葺で，南正面西端に入母屋造の玄関を突出する。１階は板間の広いホールや帳場等とし，２階は南・西Ｌ字型に廊下を取り，これに沿って客室を配す。各室とも曲木・変木を使った風趣に富んだ意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004360"},{"id":"00009286","register_sub_id":"101","register_pk":"194079","name":"靏谷家住宅主屋","kana":"つるたにけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県磐田市掛塚1177-2他","lat":34.6717605,"lng":137.79733863,"geo_status":"db","era":"明治17年頃","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積117㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"22 － 0190","desc":"通りに東面して建つ店舗兼用住宅。木造二階建、桁行八・八メートル梁間一三・三メートル、切妻造鉄板葺。下階正面に出格子を設け、軒は上下階とも出桁造とする。内部は前後に三分され、前列を土間、後列に座敷二室を並べる。明治前期の掛塚の佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009286"},{"id":"00006434","register_sub_id":"101","register_pk":"107417","name":"徳兵衛酒店店舗兼主屋","kana":"とくべえさけてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県島田市家山685-1","lat":34.943737,"lng":138.076004,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積174㎡","structure_material":"木造平屋一部2階建","registered":"2007.10.02(平成19.10.02)","register_no":"22 － 0123","desc":"道路東側の敷地の少し入った位置に西面して建つ。間口８間の木造平屋一部２階建。切妻造桟瓦葺で、三方に下屋を廻す。身舎正面は出桁造。南側をミセとし、トコや違棚を構えるオクノマなどを北側に配する。洋小屋組や座敷飾り等に近代的な構造・意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006434"},{"id":"00006435","register_sub_id":"101","register_pk":"107418","name":"徳兵衛酒店土蔵","kana":"とくべえさけてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県島田市家山685-1","lat":34.94364037,"lng":138.07614961,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"22 － 0124","desc":"主屋東南の敷地奥に位置し、東西棟で北面する。桁行３間半、梁間２間の土蔵造２階建で、正面に下屋を設ける。切妻造桟瓦葺で、外壁を漆喰仕上げとし、両妻面に窓を穿ち、腰を海鼠壁とする。正面入口に引戸をたてる。大きな下屋が独特の外観をつくり出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006435"},{"id":"00015457","register_sub_id":"101","register_pk":"533472","name":"浮月楼明輝館","kana":"ふげつろうめいきかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"静岡県","address":"静岡県静岡市葵区紺屋町11-1","lat":34.972025,"lng":138.38508611,"geo_status":"db","era":"昭和25年／平成24年・同26年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積482㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"22 - 0343","desc":"市中心部の料亭建築。庭に南面する木造二階建切妻造桟瓦葺。一階東半は中庭周囲に控の間付の座敷を三室並べ、西半は大床付の大広間で二階も同様。いずれも数寄屋意匠を加味した端正な意匠で吟味された良材を多用する。戦後間もなく再建された上質な和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015457"},{"id":"00009179","register_sub_id":"101","register_pk":"164732","name":"富士カントリー倶楽部クラブハウス","kana":"ふじかんとりーくらぶくらぶはうす","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県御殿場市深沢2472","lat":35.29679493,"lng":138.96721544,"geo_status":"db","era":"昭和33年／昭和35年・昭和43年増築、平成5年改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造及び木造2階建、鉄板葺、建築面積1084㎡","structure_material":"鉄筋コンクリート造及び木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"ゴルフ場の中央東寄りに建つ。建築面積1084平方メートル、鉄筋コンクリート造及び木造2階建、切妻造鉄板葺。建ちを抑えた直線的で明快な立面構成になり、内部では丸太の柱や方杖を表し、石張りの暖炉を築く。レーモンドの作風をよく示すクラブハウス。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009179"},{"id":"00005840","register_sub_id":"101","register_pk":"106826","name":"丸平商店店舗","kana":"まるへいしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県三島市中央町4-16","lat":35.120117,"lng":138.918259,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"22 － 0115","desc":"三嶋大社の西方，門前の道路に南面して建つ。間口４間半，正面と背面に下屋を出して奥行最大８間半とする。塗屋造２階建の店舗建築で，東方を通り土間，西方を床上部とする。料理店に改装されてはいるが，明治来の老舗の表構えを今に伝えていて貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005840"},{"id":"00005841","register_sub_id":"101","register_pk":"106827","name":"丸平商店土蔵","kana":"まるへいしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県三島市中央町4-16","lat":35.12021581,"lng":138.91817826,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造及び石造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造及び石造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"22 － 0116","desc":"店舗の北方，敷地北西部に位置し，南北棟で建つ。桁行６間，梁間２間半規模の細長い平面をもつ２階建の蔵で，南妻面に下屋を差し掛けて蔵前とし，２階に庇付きの窓を開く。１階を木骨石造，２階を海鼠壁土蔵とする混構造のつくりに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005841"},{"id":"00004552","register_sub_id":"101","register_pk":"105542","name":"眠雲閣落合樓応接棟","kana":"みんうんかくおちあいろうおうせつとう","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市湯ヶ島1887-1","lat":34.88953558,"lng":138.92775304,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積18㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"22 － 0098","desc":"住居棟の南方に位置する。入母屋造，赤色桟瓦葺の木造２階建で，桁行１６．５尺梁間１２尺規模の１室洋館。外壁はモルタル塗洗い出し仕上げで，柱型柱頭部と入母屋破風の妻面に漆喰レリーフを施す。小規模ながら，昭和初期における温泉旅館付属施設の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004552"},{"id":"00001412","register_sub_id":"101","register_pk":"102402","name":"眠雲閣落合樓玄関棟","kana":"みんうんかくおちあいろうげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市湯ヶ島1887-1","lat":34.88971151,"lng":138.92752331,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"22 － 0057","desc":"湯ヶ島温泉街は伊豆半島のほぼ中央に位置する。眠雲閣は明治７年の創業で，本谷川と猫越川が合流して狩野川の起点となる景勝地に建っている。入母屋造・平屋建・桟瓦葺の玄関棟は，昭和初期の施設建設時の最初に建てられ，彫刻欄間等に品格が感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001412"},{"id":"00001415","register_sub_id":"101","register_pk":"102405","name":"眠雲閣落合樓紫檀宴会場","kana":"みんうんかくおちあいろうしたんえんかいじょう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市湯ヶ島1887-1","lat":34.88945,"lng":138.927322,"geo_status":"db","era":"昭和8～12","year":1933,"year_source":"converted","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積378㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"22 － 0060","desc":"眠雲亭の北側，持越街道に沿って建つ紫檀宴会場は，木造２階建・入母屋造・桟瓦葺の大建築である。一階が３０畳余の宴会場３室，２階が１０８畳の大宴会場で，特に大宴会場は出節の紫檀の柱・框で構成した床構えや，洗練された棚・付書院等に見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001415"},{"id":"00001416","register_sub_id":"101","register_pk":"102406","name":"眠雲閣落合樓配膳室階段棟","kana":"みんうんかくおちあいろうはいぜんしつかいだんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市湯ヶ島1887-1","lat":34.889408,"lng":138.92745834,"geo_status":"db","era":"昭和8～12","year":1933,"year_source":"converted","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積73㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"22 － 0061","desc":"眠雲亭と紫檀宴会場を接続する木造２階建・入母屋造・桟瓦葺の建物で，北半が階段室，南半が配膳室になる。附属的な建築ながら，材料も良質で，高い建築技術が伺える。ちなみに，近在の大滝に住む棟梁青木清平が，玄関棟・本館など一連の建設を手がけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001416"},{"id":"00001413","register_sub_id":"101","register_pk":"102403","name":"眠雲閣落合樓本館","kana":"みんうんかくおちあいろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市湯ヶ島1887-1","lat":34.88942469,"lng":138.92787748,"geo_status":"db","era":"昭和8～10","year":1933,"year_source":"converted","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、銅板葺、建築面積356㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"22 － 0058","desc":"敷地南東部に建つ本館は，木造２階建・入母屋造・銅板瓦棒葺の形式である。東と南の客室から渓流を望めるよう，鍵形の平面となっている。柱や長押等は良質の桧で統一し，各室の床・棚などに銘木奇木を用い，全体に優れた室内意匠を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001413"},{"id":"00001414","register_sub_id":"101","register_pk":"102404","name":"眠雲閣落合樓眠雲亭","kana":"みんうんかくおちあいろうみんうんてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県伊豆市湯ヶ島1887-1","lat":34.8893208,"lng":138.92746072,"geo_status":"db","era":"昭和8～12","year":1933,"year_source":"converted","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積215㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"22 － 0059","desc":"創業時は「眠雲樓」と称したが，明治１４年に逗留した山岡鉄舟が「落合樓」と命名し，現在の名称となった。敷地南端最奥に建つ木造２階建の眠雲亭は質の高い数寄屋風の意匠で，瀟洒な雰囲気をもっている。各室には源氏物語に因んだ桐板透彫欄間を用いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001414"},{"id":"00001620","register_sub_id":"101","register_pk":"102610","name":"安田屋旅館月棟","kana":"やすだやりょかんつきとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県沼津市内浦三津19","lat":35.02025607,"lng":138.89727562,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積184㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"22 － 0067","desc":"安田屋は内浦湾岸に位置する明治創業の老舗旅館で，西北方に淡島と富士山を望む景勝の地に位置することから尾崎行雄により対岳荘と名付けられた。月棟は木造総二階建の上質な和風建築であり，窓廻り等に改造あるが建築当時の趣を良く伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001620"},{"id":"00001619","register_sub_id":"101","register_pk":"102609","name":"安田屋旅館松棟","kana":"やすだやりょかんまつとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県沼津市内浦三津19","lat":35.020344,"lng":138.89738421,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積147㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"22 － 0066","desc":"月棟に隣接して建つ木造総二階建の和風建築で，入母屋の棟を雁行型に並べた形式で，月棟と一体の景観を見せる。広い螺旋階段などに特色があり，障子や欄間などの細部も優れる。二階の主室は太宰治が逗留して「斜陽」を執筆した所として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001619"},{"id":"00010453","register_sub_id":"101","register_pk":"199412","name":"吉野屋北棟","kana":"よしのやきたとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市北区細江町気賀字陣中904-1","lat":34.810194,"lng":137.653585,"geo_status":"db","era":"昭和初期／昭和10改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、茅葺及び瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"22 － 0201","desc":"入母屋造平屋建の松の間と、日の出の間及び萩の間からなる切妻造茅葺の二階建建物を接続した独特な外観をもつ。松の間は比較的端正な造作とするのに対し、二階建部分は丸太材や籠目状の網代天井、古木を多用する等、数寄屋意匠を取入れて遊興的雰囲気を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010453"},{"id":"00010452","register_sub_id":"101","register_pk":"199411","name":"吉野屋主屋","kana":"よしのやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県浜松市北区細江町気賀字陣中904-1","lat":34.809977,"lng":137.653511,"geo_status":"db","era":"昭和25頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積242㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"22 － 0200","desc":"敷地南西寄りに建つ切妻造桟瓦葺で、周囲に下屋を廻らせる。平面は中廊下式で、西端の座敷を住居とし、北東隅に洋風意匠を加味した応接間を配す。南東側を厨房としてここから各棟に配膳している。施主の住居と接客、調理場としての機能を兼備した主屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010452"},{"id":"00010455","register_sub_id":"101","register_pk":"199414","name":"吉野屋東棟","kana":"よしのやひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市北区細江町気賀字陣中904-1","lat":34.809991,"lng":137.653856,"geo_status":"db","era":"昭和初期／昭和25改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"22 － 0203","desc":"敷地東辺に建つ、入母屋造桟瓦葺。十畳三室を南北に並べて縁を廻らし、西面には池に迫出すように濡縁を設ける。中央の桐の間は東面に床と床脇を備えて狆潜を瓢箪形に象り、欄間に煤竹を組込み風趣ある意匠とするなど、庭園との一体感創出が図られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010455"},{"id":"00010454","register_sub_id":"101","register_pk":"199413","name":"吉野屋南棟","kana":"よしのやみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市北区細江町気賀字陣中904-1","lat":34.809944,"lng":137.653676,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"22 － 0202","desc":"主屋東側に接し、池に面して建つ平屋建の離れ座敷。床と床脇を備えた八畳を主室として四畳半を附属し、屋根は棟をＬ字形とした寄棟造桟瓦葺とする。渡廊下を背面に通し、庭側は柱間を開放し、濡縁と軽快な意匠の庇を折曲がりに廻らせて、瀟洒な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010454"},{"id":"00000684","register_sub_id":"101","register_pk":"101674","name":"旅館いな葉","kana":"りょかんいなば","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県伊東市東松原町478","lat":34.97176687,"lng":139.09741057,"geo_status":"db","era":"大正末頃","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末頃","structure":"木造地上３階地下１階塔屋付，瓦葺，建築面積451㎡","structure_material":"木造地上３階地下１階塔屋付","registered":"1998.09.02(平成10.09.02)","register_no":"22 － 0012","desc":"伊東の中心部を流れる松川河畔に建つ木造３階建の旅館建築で，隣接する「東海館」とともに伊東温泉のシンボルになっている。望楼のある西端部は昭和４年頃，３階は昭和１２年頃の増築とされる。室内の細部意匠にも見所をもつ旅館建築の好個例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000684"},{"id":"00014170","register_sub_id":"101","register_pk":"508800","name":"井筒楼","kana":"いづつろう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県田原市福江町下地13-1他","lat":34.62819722,"lng":137.10325,"geo_status":"db","era":"明治元年／大正元年・昭和7年・同21年・同41年増築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階建、瓦葺、建築面積583㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"23-0575","desc":"港町福江の料理旅館。中庭を囲むロの字形平面で、通りに二階建入母屋造妻入棟、その西に前庭と入母屋造南北棟、東に切妻造東西棟を並べる複雑な外観。真壁造漆喰壁で軒はせがい造。各階に客室を配し、２階の５２畳大広間は目を見張る。港町の賑わいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014170"},{"id":"00004577","register_sub_id":"101","register_pk":"105567","name":"伊藤家住宅主屋","kana":"いとうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券677","lat":35.38334307,"lng":136.93956087,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0181","desc":"本町通りに西面する。つし２階をもち，間口６間半奥行８間，切妻造，平入，桟瓦葺で，１階は北に通り庭，南に居室を２列に配し，背面北に土蔵に至る渡廊下，南に便所と渡廊下を付す。犬山では比較的大型の町家で，たちの低い表構えは古い時代の姿を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004577"},{"id":"00004254","register_sub_id":"101","register_pk":"105244","name":"井上家住宅主屋","kana":"いのうえけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券6","lat":35.38365428,"lng":136.93936872,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0148","desc":"間口３間半奥行７間半規模，２階建の平入町家で，街路に東面して建つ。屋根は切妻造，桟瓦葺で表裏に下屋がつく。当初は北がトオリニワ，南が１列４室の居室であったが，前面を土間，奥を居室とし，１階正面も改修した。２階窓は上下に長押を打つ形式を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004254"},{"id":"00004247","register_sub_id":"101","register_pk":"105237","name":"梅田家住宅主屋","kana":"うめだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券506","lat":35.383266,"lng":136.942749,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積162㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0141","desc":"間口６間半奥行６間半，２階建の平入町家で，屋根を切妻造，桟瓦葺とする。正面に瓦葺庇，背面に下屋を付ける。街路に北面し，東側を土間とし，２列６室の居室を配す。正面は１階，２階とも木格子をつけ，壁は黒漆喰塗とする。西妻壁は押縁下見板張である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004247"},{"id":"00004248","register_sub_id":"101","register_pk":"105238","name":"梅田家住宅倉庫","kana":"うめだけじゅうたくそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券506","lat":35.3830489,"lng":136.94271209,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0142","desc":"主屋の南方，西側道路沿いに建つ。桁行１０間梁間３間半の木造２階建で，切妻造，桟瓦葺である。外壁は下見板張で，西面２階には窓を設け，ガラス障子を建込む。南妻壁は鉄板張とする。内部は２間毎に５室に仕切られており，東面に各室への戸口を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004248"},{"id":"00004576","register_sub_id":"101","register_pk":"105566","name":"遠藤家住宅主屋","kana":"えんどうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券662","lat":35.38212121,"lng":136.93950924,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0180","desc":"料理屋として建てられた町家。２階建で，西表と南の２方を通りに面するため，切妻造の北妻に対して南妻は入母屋造とし，１階も西面とともに南面に庇を廻らす。料理屋らしく２階にも本格的な座敷を配するためたちが高く，町並みの中にあっても一際目立つ存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004576"},{"id":"00006856","register_sub_id":"101","register_pk":"107838","name":"岡崎信用金庫資料館（旧岡崎銀行本店）","kana":"おかざきしんようきんこしりょうかん（きゅうおかざきぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県岡崎市伝馬通1-58","lat":34.957924,"lng":137.167938,"geo_status":"db","era":"大正6／昭和25・34・57改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、スレート葺、建築面積302㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2008.03.07(平成20.03.07)","register_no":"23 － 0283","desc":"旧東海道沿いの角地に建つ。建築面積３０２㎡、鉄筋コンクリート造、２階建一部３階、スレート葺。塔屋を含めたリズミカルな外観は御影石と煉瓦で構成する。ルネッサンス様式を基調としながら、当時流行していた幾何学的意匠も織り交ぜ、多彩な表情をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006856"},{"id":"00001267","register_sub_id":"101","register_pk":"102257","name":"奥村家住宅金庫蔵","kana":"おくむらけじゅうたくきんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券395","lat":35.38315914,"lng":136.94441272,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，瓦葺，建築面積14㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0025","desc":"主屋の西側に建ち、主屋と棟を並べる東西棟、瓦葺切妻屋根、妻入の２階建土蔵で、主屋側の東面に蔵前をとる。主屋２階前面と同様に黒漆喰で塗込めるが、たちは主屋の軒より高く、北面と西面に瓦葺の軒庇を回して街道西方から見た景観に配慮したつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001267"},{"id":"00001266","register_sub_id":"101","register_pk":"102256","name":"奥村家住宅主屋","kana":"おくむらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券395","lat":35.3831298,"lng":136.94449686,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造２階建，瓦葺，建築面積208㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0024","desc":"犬山城下にあり、中山道に通じる主要街道に北面して建つ。天保１３年（１８４２）の大火後ほどなくの再建と伝える。間口７間奥行６間半、東側に通り土間、西側に２列６間を配したつし２階、平入の塗屋造商家で、犬山の豪商の構えを伝える事例として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001266"},{"id":"00001268","register_sub_id":"101","register_pk":"102258","name":"奥村家住宅棟門","kana":"おくむらけじゅうたくむねもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券395","lat":35.38317504,"lng":136.94459024,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造，瓦葺，建築面積6㎡","structure_material":"木造","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0026","desc":"街道沿いの東端に主屋東面に接して建つ瓦葺、切妻屋根の棟門。前面は主屋と同様に黒漆喰で塗込めるが、背面軒回りは白漆喰として庇を張出す。主屋西側の金庫蔵とバランスをとったたちの高いつくりで、街道沿いに独特の商家構えをつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001268"},{"id":"00014171","register_sub_id":"101","register_pk":"508801","name":"角上楼本館","kana":"かくじょうろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県田原市福江町下地38他","lat":34.62738056,"lng":137.102325,"geo_status":"db","era":"昭和11年／平成16年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積421㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"23-0576","desc":"港町として近代に栄えた福江の料理旅館。２階建入母屋造桟瓦葺。中庭を囲んだコの字型平面で、２階に客室を１０室ほど配し、背後に２棟の離れを廊下で接続する。正面東西棟は総二階でたちが高く、軒をせがい造とし、ガラス戸を建て高欄を付す雄大な近代和風。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014171"},{"id":"00014166","register_sub_id":"101","register_pk":"508796","name":"蒲郡クラシックホテル鶯宿亭（旧常磐館別館茶室）","kana":"がまごおりくらしっくほてるおうしゅくてい（きゅうときわかんべっかんちゃしつ）","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県蒲郡市竹島町451-1他","lat":34.81541944,"lng":137.235675,"geo_status":"db","era":"昭和前期／同62年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"23-0571","desc":"ホテル本館南の丘に建つ茶室。平屋建、複雑な構成の入母屋造桟瓦葺。西面玄関から畳廊下、次の間を介して南東に床棚付８畳客室を配し、南西に三畳台目茶室及び水屋を配する。丸太材を多用する数寄屋風で、ガラス戸越しに三河湾を望む、趣ある近代和風の離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014166"},{"id":"00014163","register_sub_id":"101","register_pk":"508793","name":"蒲郡クラシックホテル本館（旧蒲郡ホテル本館）","kana":"がまごおりくらしっくほてるほんかん(きゅうがまごおりほてるほんかん）","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県蒲郡市竹島町452","lat":34.81587222,"lng":137.23580833,"geo_status":"db","era":"昭和9年／同62年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、銅板葺、建築面積907㎡、塔屋付","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2022.02.17(令和4.02.17)","register_no":"23-0568","desc":"三河湾を望む丘の頂に位置。鉄筋コンクリート造躯体に入母屋造銅板葺屋根を載せ、寄棟の塔屋、千鳥破風や軒唐破風で飾る。３層の西棟は和洋折衷のレストランや玄関ホールとし、２層の東棟は客室を並べる。和風意匠を用いて格調高い外観を造る国際観光ホテル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014163"},{"id":"00014165","register_sub_id":"101","register_pk":"508795","name":"蒲郡クラシックホテル料亭竹島（旧常磐館梅別館）","kana":"がまごおりくらしっくほてるりょうていたけしま（きゅうときわかんうめべっかん）","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県蒲郡市竹島町451-1他","lat":34.81553333,"lng":137.23542778,"geo_status":"db","era":"大正5年／同62年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積125㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"23-0570","desc":"ホテル本館南の丘に建つ離れ。平屋建、入母屋造桟瓦葺で複雑な屋根構成とする。北面玄関をやや突出させ、玄関寄付から東に客室２室を配する。南東に張出す客室は雪見障子を建て、三河湾への眺望を誇る、真壁造に竹等を多用し、数寄屋基調の近代和風とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014165"},{"id":"00014164","register_sub_id":"101","register_pk":"508794","name":"蒲郡クラシックホテル六角堂（旧蒲郡ホテル聚美堂）","kana":"がまごおりくらしっくほてるろっかくどう（きゅうがまごおりほてるしゅうびどう）","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県蒲郡市竹島町451-1他","lat":34.81586389,"lng":137.23511667,"geo_status":"db","era":"昭和11年／同62年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"23-0569","desc":"ホテル本館へのアプローチ脇に位置する元物販所。木造平屋建の６角形平面で、６注造屋根に瑠璃瓦を葺き、頂部には宝珠を掲げる。３箇所に入口を開け、内部は無柱の１室で折上天井とする。現在は４室に区画して活用。和風の国際観光ホテルの玄関口をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014164"},{"id":"00005849","register_sub_id":"101","register_pk":"106835","name":"川村家住宅主屋","kana":"かわむらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券171-5","lat":35.38192751,"lng":136.94039401,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積102㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"23 － 0228","desc":"交差点の東南角に位置し，南北の通りに西面して建つ。間口３間半奥行８間，切妻造，桟瓦葺の木造総２階建で，平面は南方を土間とし，北方前側を土間，後方に２室を配する。正面建具に改変はあるが，通り土間の吹抜け等，戦前の犬山城下の商家の姿を伝え貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005849"},{"id":"00004981","register_sub_id":"101","register_pk":"105971","name":"甘強味淋旧本社事務所","kana":"かんきょうみりんきゅうほんしゃじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県海部郡蟹江町城4-1地先内法","lat":35.13139145,"lng":136.78972528,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積92㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2005.11.10(平成17.11.10)","register_no":"23 － 0205","desc":"蟹江川に西面して建つ。南北に細長い台形平面のＲＣ造３階建塔屋付であるが，堤防際のため，西面は２階建外観になる。窓は縦長の上げ下げ窓，外壁はスクラッチタイル張，頂部はコーニスを廻し，玄関はテラコッタ飾りで縁取る。地方における事務所建築の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004981"},{"id":"00004564","register_sub_id":"101","register_pk":"105554","name":"旧磯部家住宅主屋","kana":"きゅういそべけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券72","lat":35.38165704,"lng":136.93946259,"geo_status":"db","era":"慶応年間","year":1866,"year_source":"estimated","year_min":1865,"year_max":1868,"year_label":"慶応年間","structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0168","desc":"当初は呉服屋，戦後は茶販売を営む商家。中本町通りに西面して建つ。間口３間半奥行８間で，１階は店奥の南に通り庭，北に仏間，座敷等を配し，２階は表に座敷等を並べる。間口は狭いが，内外とも細部まで凝ったつくりで，街道の歴史的景観に欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004564"},{"id":"00007503","register_sub_id":"101","register_pk":"108485","name":"旧大野銀行（大野宿鳳来館）土蔵","kana":"きゅうおおのぎんこう（おおのしゅくほうらいかん）どぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県新城市大野字上野17-2","lat":34.95004096,"lng":137.60657946,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"23 － 0312","desc":"本館の西側に位置する。桁行７．３ｍ梁間３．６ｍで、切妻造平入桟瓦葺とする２階建の土蔵。１階は下見板張、２階は白漆喰仕上げとし、２階の窓には木製庇を付ける。鉄扉や黒漆喰を用いた掛子塗の扉などの建具も残す。地域の発展を支えた銀行の付属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007503"},{"id":"00007502","register_sub_id":"101","register_pk":"108484","name":"旧大野銀行（大野宿鳳来館）本館","kana":"きゅうおおのぎんこう（おおのしゅくほうらいかん）ほんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県新城市大野字上野17-2","lat":34.94995302,"lng":137.60674771,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積168㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"23 － 0311","desc":"ＪＲ三河大野駅の駅前通りに面する角地に建つ。東西１７ｍ南北９．７ｍの鉄筋コンクリート造２階建で、交差点に面する出入口の東南隅を曲線状に造る。外装は石積風とし、１、２階を貫く柱型やメダイオン付の玄関ポーチが特徴的な地域のランドマーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007502"},{"id":"00002144","register_sub_id":"101","register_pk":"103134","name":"旧加藤商会ビル","kana":"きゅうかとうしょうかいびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市中区錦1-15-17","lat":35.16812738,"lng":136.8922968,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積77㎡、塔屋付","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2001.04.24(平成13.04.24)","register_no":"23 － 0053","desc":"納屋橋東詰北側の角地に建つ鉄筋コンクリート造３階建地下室付の事務所ビル。東南角をアールにして正面玄関を設け，堀川に面する西面を４階建に見せるなど立地を生かした造りとする他，煉瓦調のタイルや柱頭飾りなどに大正期の建築意匠的特徴がうかがわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002144"},{"id":"00009473","register_sub_id":"101","register_pk":"194266","name":"旧加茂郡銀行羽黒支店","kana":"きゅうかもぐんぎんこうはぐろしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字羽黒字古市場53-1","lat":35.35049265,"lng":136.95185494,"geo_status":"db","era":"明治40年頃／昭和8年頃曳家・平成11年移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0371","desc":"木造二階建、寄棟造桟瓦葺で、二階天井まで吹き抜けた玄関ホールを配す。入口より見上げる二階和室欄間に銀行ならではの彫刻を施すなど細部に装飾が見られる。銀行から診療所、公民館と変遷を遂げ、地域住民の生活拠点としての役割を担う明治期の擬洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009473"},{"id":"00005466","register_sub_id":"101","register_pk":"106454","name":"旧津島信用金庫本店","kana":"きゅうつしましんようきんこほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県津島市本町1-52-1","lat":35.178753,"lng":136.723389,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積221㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"23 － 0213","desc":"鉄筋コンクリート造２階建の銀行店舗である。１階正面中央に玄関を枠取り，入口両側に双子柱を飾る。２階は柱形で垂直性を強調する。外壁は目地切りの人造石洗い出しで，腰回りを花崗岩張りとする。営業室上部は吹き抜けで，ギャラリーを巡らせている","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005466"},{"id":"00008290","register_sub_id":"101","register_pk":"133932","name":"旧湊屋店舗兼主屋","kana":"きゅうみなとやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県一宮市起字堤町33-1","lat":35.31223661,"lng":136.73967425,"geo_status":"db","era":"明治前期／昭和34年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積156㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0327","desc":"旧美濃路の角地に建ち、桁行１３ｍ梁間１２ｍ、木造つし２階建、切妻造桟瓦葺で、正背面の半間を下屋につくる。正面構えは、下屋に出格子をたて、上屋は格子窓を開け、側面けらばを漆喰で塗り込める。旧街道沿いの商家の繁栄を伝える大型町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008290"},{"id":"00008291","register_sub_id":"101","register_pk":"133933","name":"旧湊屋土蔵","kana":"きゅうみなとやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県一宮市起字堤町33-1","lat":35.31242252,"lng":136.73983773,"geo_status":"db","era":"江戸末期・昭和前期／昭和中期移築増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階一部平屋建、瓦葺、建築面積111㎡","structure_material":"土蔵造2階一部平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0328","desc":"敷地の北西角に建ち、建築面積１１１㎡、土蔵造２階建、切妻造桟瓦葺である。南北棟で２階建の東蔵と西蔵の間を、平屋建の中倉が繋ぐ構成で、西面は主屋と同様に簓子下見板張とする。商家の屋敷構えを構成する独特な形式の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008291"},{"id":"00010798","register_sub_id":"101","register_pk":"201633","name":"旧山繁商店奥倉庫","kana":"きゅうやましげしょうてんおくそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県瀬戸市仲切町23他","lat":35.228378,"lng":137.101269,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積221㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0441","desc":"敷地の北東隅、中倉庫の北に平行して建つ。桁行一五メートル梁間一二メートル、切妻造の主体部の東と北に下屋を張出す。梁間には一列の柱を並べる。倉庫ではあるが内部で上絵付を行っていた時期もあり、絵付場の伝統的な作業空間からの展開を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010798"},{"id":"00010793","register_sub_id":"101","register_pk":"201628","name":"旧山繁商店旧事務所","kana":"きゅうやましげしょうてんきゅうじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県瀬戸市仲切町23他","lat":35.228147,"lng":137.101026,"geo_status":"db","era":"大正3／平成7改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0436","desc":"敷地南西部に位置し、旧道に面して建つ。一階の西半に土間の事務室、東半に床上部を配し、二階は一室の空間とする。入母屋造の屋根を架けるが、小屋組はトラス構造である。事務室はカウンターの痕跡を残し、床上部と併用する近代的な帳場の様相を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010793"},{"id":"00010792","register_sub_id":"101","register_pk":"201627","name":"旧山繁商店事務所","kana":"きゅうやましげしょうてんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県瀬戸市仲切町23他","lat":35.227957,"lng":137.101386,"geo_status":"db","era":"昭和22","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0435","desc":"敷地東側の県道に接し、北面して建つ。東に事務室、西に応接室を併設し、事務室正面に玄関ポーチを張出す。応接室の内部は腰に竪板を張り、壁や天井を漆喰で仕上げる。戦後、陶磁器輸出など事業拡張した際に建てられ、瀬戸の陶磁器産業復興の軌跡を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010792"},{"id":"00010795","register_sub_id":"101","register_pk":"201630","name":"旧山繁商店新小屋","kana":"きゅうやましげしょうてんしんごや","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県瀬戸市仲切町23他","lat":35.228101,"lng":137.101207,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積125㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0438","desc":"旧事務所の東に並んで建つ。桁行一八メートルの細長い平面を持つ。外壁を漆喰で塗籠にした二階建で、一階を土間の作業空間とし、当地でモロと呼ぶ作陶場と共通した構造をもつ。出荷前の箱詰等を行っており、瀬戸の陶磁器産業における伝統的な空間を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010795"},{"id":"00010794","register_sub_id":"101","register_pk":"201629","name":"旧山繁商店土蔵","kana":"きゅうやましげしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県瀬戸市仲切町23他","lat":35.22855,"lng":137.101005,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0437","desc":"敷地の北西隅に南面して建つ二階建土蔵で、もとは南に主屋が接続した。腰を海鼠壁として軒に鉢巻を廻らし、小屋は弓状の梁に小束を立てて丑梁と母屋を受ける。南面二階の窓に袖壁付の庇を付け、当地では珍しく棟に影盛を施した大振りな鬼瓦を載せ、風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010794"},{"id":"00010797","register_sub_id":"101","register_pk":"201632","name":"旧山繁商店中倉庫","kana":"きゅうやましげしょうてんなかそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県瀬戸市仲切町23他","lat":35.22825,"lng":137.101242,"geo_status":"db","era":"昭和22","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0440","desc":"前倉庫の北に平行して建つ。切妻造、桁行一八メートルの倉庫建築。前倉庫と同様に小屋組はキングポストトラスを用いて内部を広い無柱空間として、天井を張らずに小屋組を現す。一時期、内部に電気窯を設置して焼付を行い、少量ながら生産も担っていた倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010797"},{"id":"00010791","register_sub_id":"101","register_pk":"201626","name":"旧山繁商店離れ","kana":"きゅうやましげしょうてんはなれ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県瀬戸市仲切町23他","lat":35.228286,"lng":137.100983,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建、瓦葺、建築面積133㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0434","desc":"瀬戸川北岸の中腹に敷地を構える陶磁器卸問屋。離れは創業家である加藤家の離れで、皇族などの宿所にも使われた。一階は東を土間に、西に四室を田字形に並べ、北西室を主座敷とし、二階にも座敷を配する。南面の黒漆喰塗外壁が、重厚な街路景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010791"},{"id":"00010799","register_sub_id":"101","register_pk":"201634","name":"旧山繁商店塀","kana":"きゅうやましげしょうてんへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県瀬戸市仲切町23他","lat":35.228236,"lng":137.100933,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、延長28m、石垣付","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0442","desc":"敷地南西側の通り沿いに構える。基礎の石垣は花崗岩谷積で、南正面の一辺のみ亀甲積四段とする。石垣上端を延石で整え、木造の塀を廻らす。塀の下部は、外側をなぐり仕上の竪板壁、内側をスギ網代とし、上部は黒漆喰塗で、離れと相まって通りの景観を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010799"},{"id":"00010796","register_sub_id":"101","register_pk":"201631","name":"旧山繁商店前倉庫","kana":"きゅうやましげしょうてんまえそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県瀬戸市仲切町23他","lat":35.228161,"lng":137.101216,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積133㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0439","desc":"新小屋の北に平行して建つ。切妻造、桁行一八メートルの倉庫建築で、大正頃の事業拡大を受け、商品の陶磁器収納のため建てられた。小屋組は大スパンのキングポストトラスを架け、内部を無柱空間として広く利用する。伝統産業の盛期を伝える大型倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010796"},{"id":"00010608","register_sub_id":"101","register_pk":"201182","name":"旧料亭菊水","kana":"きゅうりょうていきくすい","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県新城市大野字上野17-7","lat":34.950221,"lng":137.606341,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"23－0425","desc":"鳳来寺山南麓、別所街道の大野宿に所在する元料亭。上下階とも座敷二室ずつを配し、床や棚を飾る瀟洒な構えとなる。またガラス窓を多用して明るい開放的な空間とするほか、二階外壁には鏝絵により奴と雀、竹林を巧みに描き、料亭らしい遊興的雰囲気を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010608"},{"id":"00009763","register_sub_id":"101","register_pk":"195592","name":"喜楽亭","kana":"きらくてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県豊田市小坂本町1-25","lat":35.0874526,"lng":137.15078492,"geo_status":"db","era":"昭和初期／昭和58移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0384","desc":"庭園内に東面して建ち、木造二階建、妻入、入母屋造桟瓦葺で、周囲に庇を廻らす。正面中央を玄関として南側に出格子をたて、二階の窓に高欄付の縁を設け、妻の破風に起りをもたせるなど、瀟洒な外観とする。内部の造作も洗練され、老舗料亭の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009763"},{"id":"00001711","register_sub_id":"101","register_pk":"102701","name":"建中寺徳興殿（旧名古屋商業会議所本館）","kana":"けんちゅうじとっこうでん（きゅうなごやしょうぎょうかいぎしょほんかん）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区筒井1-703-1","lat":35.17945648,"lng":136.92803438,"geo_status":"db","era":"明治29／昭和9移築","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、瓦葺、建築面積454㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"23 － 0045","desc":"名古屋商業会議所（現商工会議所）本館として建てられ、当初は洋風の議事堂が附属していた。入母屋造瓦葺で、２階部分を大空間の「集会所」としており、建中寺に移築されてからは畳敷の大広間となっている。名古屋市街地に建つ木造建築としては最大級のもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001711"},{"id":"00004569","register_sub_id":"101","register_pk":"105559","name":"小島家住宅主屋","kana":"こじまけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券633","lat":35.38299759,"lng":136.94043,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0173","desc":"約千坪の広大な敷地をもつ酒造業の家。通りに東面しつし２階をもつ切妻造，桟瓦葺，平入の町家で，１階は広い間口の通り庭の南に２列６室の居室を配す。大型で，１，２階とも表側はほぼ全面格子を入れた重厚な外観をもち，地区の歴史的景観上欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004569"},{"id":"00004244","register_sub_id":"101","register_pk":"105234","name":"髙木家住宅主屋","kana":"たかぎけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券73他","lat":35.38184461,"lng":136.93952408,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積190㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0138","desc":"間口６間奥行８間，２階建の平入町家で，街路に西面して建つ。元は酒造業を営んだ。南端にトオリニワがあり，北側の落棟の背後に坪庭をもつ。切妻造，桟瓦葺で，正面に半間幅の下屋がつき，格子を建込む。２階は出桁造で塗込とし，鉄格子入の窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004244"},{"id":"00007636","register_sub_id":"101","register_pk":"108618","name":"棚橋家住宅主屋","kana":"たなはしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区有松3004","lat":35.06650037,"lng":136.9709088,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"23 － 0314","desc":"旧東海道に北面する町家。桁行１６ｍ梁間８．５ｍ、木造つし２階建、切妻造桟瓦葺で、下屋庇を付け、後方に台所を張り出す。１階に出格子を設け、２階は軒を出桁造とし、一間ごとに格子窓を並べ、漆喰で塗り込める。風格のある外観で、有松の町並みの中核をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007636"},{"id":"00006855","register_sub_id":"101","register_pk":"107837","name":"中濱家住宅石垣及び塀","kana":"なかはまけじゅうたくいしがきおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区有松2603","lat":35.06732639,"lng":136.97070005,"geo_status":"db","era":"明治期／昭和初期改修","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"石垣 石造、延長74m 塀 木造、瓦葺、延長51m","structure_material":"石垣 石造","registered":"2008.03.07(平成20.03.07)","register_no":"23 － 0282","desc":"敷地の東辺と北辺を廻る。東辺の石垣は人頭大の玉石積で、北辺は亀甲状の切石を精緻に積み、総延長は７４ｍである。塀は石垣上に建つ板塀で、総延長５１ｍ、腰を簓子下見板張とし、小壁を黒漆喰塗とする。門や物置と連なり、統一感のある屋敷景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006855"},{"id":"00006851","register_sub_id":"101","register_pk":"107833","name":"中濱家住宅主屋","kana":"なかはまけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区有松2603","lat":35.067303,"lng":136.970367,"geo_status":"db","era":"明治中期／昭和初期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積240㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"23 － 0278","desc":"旧東海道に面して建つ町家で、正面西隣に土蔵が並ぶ。建築面積２４０㎡、木造２階建、切妻造桟瓦葺。１階は正面全体を木格子で統一し、２階は、軒を出桁造とし、虫籠窓を並べ、黒漆喰で塗り込める。有松絞りで栄えた問屋らしい、重厚で風格のある外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006851"},{"id":"00006852","register_sub_id":"101","register_pk":"107834","name":"中濱家住宅土蔵","kana":"なかはまけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区有松2603","lat":35.067371,"lng":136.970291,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"23 － 0279","desc":"主屋の西隣、旧東海道に妻を見せて建つ。 桁行７．３ｍ梁間４．５ｍ、土蔵造２階建、桟瓦葺である。外壁は黒漆喰塗で、腰は洗出し目地切仕上げとする。１、２階とも通りに掛子塗戸を開き、桟瓦葺の重厚な庇をつけ、主屋とともに豊かな町並みを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006852"},{"id":"00006853","register_sub_id":"101","register_pk":"107835","name":"中濱家住宅物置","kana":"なかはまけじゅうたくものおき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市緑区有松2603","lat":35.06715,"lng":136.970444,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"23 － 0280","desc":"主屋東側に連続し、東南角を矩の手に折れ曲がる平面とする。建築面積３７㎡、平屋建、招屋根、桟瓦葺である。玉石積上に建ち、腰を簓子下見板張とし、小壁を黒漆喰塗とするなど、通り側外観は板塀と同様の構成になり、敷地周囲の意匠の統一が図られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006853"},{"id":"00006854","register_sub_id":"101","register_pk":"107836","name":"中濱家住宅門","kana":"なかはまけじゅうたくもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市緑区有松2603","lat":35.06742991,"lng":136.97065502,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口1.7m","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"23 － 0281","desc":"敷地北側の手越川に面して建つ。間口１．７ｍの腕木門。柱を建て冠木を通し、腕木を出す。軒は一軒疎垂木で、屋根桟瓦葺とし、門口に一枚板の両開戸を吊る。瀟洒な門で、両側に延びる板塀とともに、良好な屋敷景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006854"},{"id":"00007358","register_sub_id":"101","register_pk":"108340","name":"名古屋陶磁器会館","kana":"なごやとうじきかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区徳川1-1003","lat":35.18172628,"lng":136.92354256,"geo_status":"db","era":"昭和7／昭和21増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造3階建、建築面積389㎡","structure_material":"鉄筋コンクリート造一部鉄骨造3階建","registered":"2008.10.23(平成20.10.23)","register_no":"23 － 0309","desc":"名古屋城の約２㎞東方に位置する事務所建築。間口２４ｍの鉄筋コンクリート造で、３階を鉄骨造で増築した。外装スクラッチタイル貼で、幾何学的なモチーフを随所にあしらう。名古屋における陶磁器業発展のシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007358"},{"id":"00010604","register_sub_id":"101","register_pk":"201178","name":"日本陶磁器センター旧館","kana":"にほんとうじきせんたーきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"煙突","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区代官町3903","lat":35.174645,"lng":136.922101,"geo_status":"db","era":"昭和9年／昭和32年移築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造3階一部4階地下1階建、建築面積291㎡、煙突付","structure_material":"鉄筋コンクリート造3階一部4階地下1階建","registered":"2015.08.04(平成27.08.04)","register_no":"23－0421","desc":"代官町に所在する鉄筋コンクリート造のオフィスビル。陶磁器を扱う団体の建築らしく、内外にタイル等の陶磁器をふんだんに使用する。特に三階大会議室ではステージのアルコーブを外部に張出し、細部にアールデコ意匠を採り入れるなど洗練された意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010604"},{"id":"00010605","register_sub_id":"101","register_pk":"201179","name":"日本陶磁器センター新館","kana":"にほんとうじきせんたーしんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市東区代官町3903","lat":35.17448,"lng":136.922052,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄骨鉄筋コンクリート造5階地下1階建、建築面積306㎡","structure_material":"鉄骨鉄筋コンクリート造5階地下1階建","registered":"2015.08.04(平成27.08.04)","register_no":"23－0422","desc":"山下寿郎設計事務所の設計になる鉄骨鉄筋コンクリート造のオフィスビル。ガラス面を広くとったモダニズム建築で、均整のとれた窓配置が軽快な印象を与える。階段室の窓配置や円弧を描く階段は、機能性と意匠性を兼備する。地域のタイルを多く用いる点も特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010605"},{"id":"00006583","register_sub_id":"101","register_pk":"107566","name":"萬乗醸造主屋","kana":"ばんじょうじょうぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.065006,"lng":136.933716,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0234","desc":"敷地の北側中央部に位置し，通りに北面して建つ。桁行８間，梁行６間半の規模で，東西棟，切妻造，桟瓦葺，平入の木造２階建。東方を土間，西方を居室部とし，北西に８畳座敷を配する。北面は黒漆喰塗の真壁造で，開口部のやや少ないつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006583"},{"id":"00004251","register_sub_id":"101","register_pk":"105241","name":"三井家住宅蔵","kana":"みついけじゅうたくくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券682他","lat":35.38352925,"lng":136.93989339,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0145","desc":"主屋の西に蔵前を介して接続する土蔵造２階建で，桁行５間梁間３間。屋根は切妻造，桟瓦葺で，街路に妻を見せる。外壁は黒漆喰塗で腰を海鼠壁とし，１階正面に瓦庇をつけて持送りで受け，庇下に小窓を開ける。２階の窓は両開きの黒漆喰塗土戸に瓦庇を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004251"},{"id":"00004250","register_sub_id":"101","register_pk":"105240","name":"三井家住宅主屋","kana":"みついけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券683他","lat":35.38348374,"lng":136.93998567,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0144","desc":"間口４間半弱奥行７間，２階建の平入町家で，街路に北面する。屋根は切妻造，桟瓦葺で，正面と背面に下屋を付け，西側の落棟を蔵前とする。東側１間半弱がトオリニワで，１５畳大のミセノマを置く。正面の軒は出桁造で，１階に木格子，２階に鉄格子を入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004250"},{"id":"00003651","register_sub_id":"101","register_pk":"104641","name":"明治村大井牛肉店","kana":"めいじむらおおいぎゅうにくてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34013628,"lng":136.98852196,"geo_status":"db","era":"明治20／昭和43移築","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積98㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0064","desc":"神戸元町に牛肉販売・牛鍋料理店として建築。木造洋風２階建で白漆喰塗の外壁に胴蛇腹と軒蛇腹を廻す。各階隅の角柱と２階ヴェランダの独立円柱にコリント式柱頭を飾る。窓は半円アーチ欄間の上げ下げ窓。玄関庇にはむくり破風の和風意匠を用いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003651"},{"id":"00003874","register_sub_id":"101","register_pk":"104864","name":"明治村川崎銀行本店","kana":"めいじむらかわさきぎんこうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34659216,"lng":136.99049432,"geo_status":"db","era":"昭和2／平成2移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積89㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0108","desc":"ＲＣ造３階建銀行建築の正面左角部を部分保存。設計は矢部又吉。１階は花崗岩切石整層積で基壇に扱い，２階と３階を通してコリント式角柱を付ける。出入口はドリス式円柱がエンタブレチュアを支え，行章入のメダイオンを飾る。近代都市建築の外観意匠を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003874"},{"id":"00003868","register_sub_id":"101","register_pk":"104858","name":"明治村小泉八雲避暑の家","kana":"めいじむらこいずみやくもひしょのいえ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34489325,"lng":136.98962768,"geo_status":"db","era":"明治初期／昭和46移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0102","desc":"木造２階建，桟瓦葺，平入，間口３間の町家で，呉服雑貨商として建築。１階は入口が引違戸，店の前がはめ外し板戸と格子窓，２階は手摺付の肘掛窓である。通り土間に沿って３室が並び，２階は表に１０畳と４畳，裏に１２畳座敷を配す。地方都市商家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003868"},{"id":"00003885","register_sub_id":"101","register_pk":"104875","name":"明治村高田小熊写真館","kana":"めいじむらたかだおぐましゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34642407,"lng":136.98824934,"geo_status":"db","era":"明治41／大正初期増築／昭和57移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積70㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0119","desc":"木造２階建，切妻造，鉄板葺屋根の北面に大きくガラス屋根を設けるのは，スタジオの採光である。外壁は柱形を見せる下見板張で，簡素な上げ下げ窓を開く。玄関部分は大正期の増築で，ショウウィンドウの腰を石貼とし，幾何学意匠のパラペット飾りを冠する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003885"},{"id":"00003887","register_sub_id":"101","register_pk":"104877","name":"明治村帝国ホテル中央玄関","kana":"めいじむらていこくほてるちゅうおうげんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34721945,"lng":136.98871196,"geo_status":"db","era":"大正12／昭和60移築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄骨鉄筋コンクリート造3階建、一部銅板葺、建築面積911㎡","structure_material":"鉄骨鉄筋コンクリート造3階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0121","desc":"Ｆ．Ｌ．ライト設計。車寄，ホワイエと両側のラウンジ，ロビーを保存。水平性の強調，床高の微妙な変化や，彫刻した大谷石，スクラッチ煉瓦，透かしテラコッタによる幾何学装飾など，ライトの設計手法を良く表す。移築時に主構造をＳＲＣ造と鉄骨造に改めた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003887"},{"id":"00003869","register_sub_id":"101","register_pk":"104859","name":"明治村半田東湯","kana":"めいじむらはんだあずまゆ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34518086,"lng":136.98958387,"geo_status":"db","era":"明治末期／昭和55移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋一部2階建、瓦葺、建築面積50㎡","structure_material":"木造平屋一部2階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0103","desc":"木造２階建，切妻造，桟瓦葺，妻入の町家で，背後に平屋建の浴室が接続する。正面１階は庇をつけ，両側に男女別の脱衣室への出入口を設け，中央の出格子裏が番台である。男脱衣室から上る２階は和室２室で，肘掛窓に手摺がつく。浴室の内装は移築時の復原。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003869"},{"id":"00003867","register_sub_id":"101","register_pk":"104857","name":"明治村本郷喜之床","kana":"めいじむらほんごうきのとこ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34482541,"lng":136.98967161,"geo_status":"db","era":"明治後期／昭和55移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0101","desc":"石川啄木ゆかりの新井理髪店。木造２階建，桟瓦葺，平入，間口３間の町家である。入口は両開ガラス戸で，両側に引違ガラス窓が続く。１階の前半は店で洋風の板天井とし，背後に和室３室を食違いに配す。２階は６畳２室で，正面には手摺付の肘掛窓を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003867"},{"id":"00003664","register_sub_id":"101","register_pk":"104654","name":"明治村安田銀行会津支店","kana":"めいじむらやすだぎんこうあいづしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34165842,"lng":136.99010652,"geo_status":"db","era":"明治40／昭和40移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積154㎡","structure_material":"土蔵造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0077","desc":"黒漆喰塗の土蔵造，寄棟屋根を赤味の塩焼瓦葺とする。外観は二階建だが，内部は吹抜で営業室上にギャラリーがつく。伝統的な土蔵造の意匠をもとに，玄関ポーチ，石積の腰壁，営業室カウンター，ギャラリーを支える円柱など，洋風意匠を巧みに取り入れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003664"},{"id":"00009967","register_sub_id":"101","register_pk":"196114","name":"木綿蔵ちた（旧竹内虎王商店木綿蔵）","kana":"もめんぐらちた（きゅうたけうちとらおうしょうてんもめんぐら）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字中谷9","lat":34.96480431,"lng":136.86753895,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、瓦葺、建築面積84㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0394","desc":"木綿問屋の商品倉庫として建設。土蔵造二階建、切妻造桟瓦葺で北正面に下屋を設ける。石積基礎で、湿気避けのため床を高く張る。外壁は漆喰塗で、正面腰はモルタル洗出し。戸口を二箇所設けるが、上下階とも内部は一室とする。地場産業の往時を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009967"},{"id":"00004253","register_sub_id":"101","register_pk":"105243","name":"山田家住宅主屋","kana":"やまだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券776","lat":35.38371081,"lng":136.93956345,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0147","desc":"街路の北東角に南面して建つ間口５間奥行６間の２階建平入町家。屋根は切妻造，桟瓦葺で南・西・北に下屋がつく。南から奥行２間半が土間，北に４室を田の字に配す。妻壁は押縁下見板張，正面２階の東半窓に出格子が付く。南西隅のショーケースは後の改造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004253"},{"id":"00004554","register_sub_id":"101","register_pk":"105544","name":"料亭河文表門、塀及び脇門","kana":"りょうていかわぶんおもてもん、へいおよびわきもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市中区丸の内2-12-19","lat":35.17532487,"lng":136.90090007,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造、瓦葺、表門間口3.9m、脇門間口2.7m、塀延長25m","structure_material":"木造","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0157","desc":"名古屋城の南，東西に走る魚の棚通りに南面し，東寄りに表門を開き両脇を屋根付の高塀で仕切る。表門は棟門形式を基本とするが，前後一段下に庇を付け，前方の庇の正面は柱を立て３分し中央に戸口を構える。比例や形式を工夫して格式ある構えを実現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004554"},{"id":"00004553","register_sub_id":"101","register_pk":"105543","name":"料亭河文主屋","kana":"りょうていかわぶんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市中区丸の内2-12-19","lat":35.17540704,"lng":136.90089876,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積325㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0156","desc":"江戸時代中期から続く名古屋屈指の老舗料亭の主屋。２階建，入母屋造，桟瓦葺で，１階東方に帳場や土間を配す以外は客室とする。座敷飾を備えた座敷や和風を基調とした洋間を廊下や鞘の間で適当な距離をおいて配し，格調高くゆとりのある接客空間を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004553"},{"id":"00004555","register_sub_id":"101","register_pk":"105545","name":"料亭河文新用亭及び渡廊下","kana":"りょうていかわぶんしんようていおよびわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市中区丸の内2-12-19","lat":35.17553631,"lng":136.90087655,"geo_status":"db","era":"昭和25～27","year":1950,"year_source":"converted","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積63㎡、渡廊下 木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0158","desc":"主屋北に建つ離れ。平屋建，入母屋造，桟瓦葺で，１０畳の座敷と５畳の鞘の間を南北に並べ，南・東・北３方に広縁を廻らす。南西に接続する渡廊下は，両下造，化粧屋根裏で，床は中央畳敷，両側板張とする。木柄の細い瀟洒な構えでくつろいだ接客空間を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004555"},{"id":"00004557","register_sub_id":"101","register_pk":"105547","name":"料亭河文厨房","kana":"りょうていかわぶんちゅうぼう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市中区丸の内2-12-19","lat":35.175491,"lng":136.90101997,"geo_status":"db","era":"昭和12／昭和25増築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造及び木造2階建、建築面積132㎡","structure_material":"鉄筋コンクリート造及び木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0160","desc":"主屋の北面東端部に接続する。鉄筋コンクリート造，２階建，陸屋根の主体部を中心に，南及び西に戦後復興された木造の下屋や廊下を付設する。主体部は装飾を廃した機能的で簡明な造りだが，内部の磁器タイル，鉄骨階段，滑り出しの窓などに時代の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004557"},{"id":"00004556","register_sub_id":"101","register_pk":"105546","name":"料亭河文用々亭","kana":"りょうていかわぶんようようてい","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市中区丸の内2-12-19","lat":35.17559566,"lng":136.90078872,"geo_status":"db","era":"昭和25～27","year":1950,"year_source":"converted","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0159","desc":"主屋北西に位置し渡廊下で連絡する。平屋，切妻造，桟瓦葺一部銅板葺で，６畳主室の南を幅１間弱の廊下とする。柱や桁に丸太を用い，掛込み天井等で変化に富んだ室内を構成し，各面とも大きく開口部を開き茶屋風に造る。小規模で簡素ながら瀟洒な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004556"},{"id":"00004586","register_sub_id":"101","register_pk":"105576","name":"麻吉旅館聚遠楼","kana":"あさきちりょかんじゅえんろう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町111","lat":34.47768486,"lng":136.72177576,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造3階一部2階建、瓦葺、建築面積195㎡","structure_material":"木造3階一部2階建","registered":"2005.02.09(平成17.02.09)","register_no":"24 － 0054","desc":"本館の西方に位置する。桁行７間半梁間４間半，南北棟，寄棟造，桟瓦葺の木造３階建と，桁行７間半梁間３間，南北棟，寄棟造，桟瓦葺の木造２階建を並列した構成。最上階西方に８畳３室を並べ，東北隅に２１畳大の「聚遠楼」を置く。麻吉旅館の目印的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004586"},{"id":"00004585","register_sub_id":"101","register_pk":"105575","name":"麻吉旅館土蔵","kana":"あさきちりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町109-3","lat":34.477493,"lng":136.722122,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造3階一部2階建、瓦葺、建築面積72㎡","structure_material":"土蔵造3階一部2階建","registered":"2005.02.09(平成17.02.09)","register_no":"24 － 0053","desc":"本館の東南方に位置し，曲がった坂道に沿って棟を振って建つ。桁行３間梁間３間規模，切妻造，桟瓦葺，外観簓子下見板張の３階建土蔵で，本館寄りに桁行４間規模，２階建の蔵前部を持ち，本館の２階レベルに戸口を開ける。現在は麻吉旅館の資料館として活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004585"},{"id":"00004584","register_sub_id":"101","register_pk":"105574","name":"麻吉旅館本館","kana":"あさきちりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町109-3","lat":34.477612,"lng":136.722,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造3階一部2階建、瓦葺、建築面積273㎡","structure_material":"木造3階一部2階建","registered":"2005.02.09(平成17.02.09)","register_no":"24 － 0052","desc":"内宮と外宮を結ぶ参宮道から東に入った傾斜地に位置する。坂道沿いに建つ寄棟造，桟瓦葺の木造３階建で，３階に主玄関を置き，２階に厨房と住居，１階と３階に客室を配する。地形に合わせた変形平面と階段状の階層構成に対応した複雑な屋根構成に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004584"},{"id":"00004588","register_sub_id":"101","register_pk":"105578","name":"麻吉旅館前蔵","kana":"あさきちりょかんまえぐら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町108-2","lat":34.47748352,"lng":136.72200642,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"24 － 0056","desc":"本館南方，坂道を隔てた向かいの敷地に位置し，本館の３階レベルと空中廊下で連絡する別棟の内蔵的存在。桁行２間半梁間２間，切妻造，桟瓦葺の２階建土蔵で，本館や土蔵との間に通る坂道側は簓子下見板張とし，独特な坂道景観の構成要素になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004588"},{"id":"00010173","register_sub_id":"101","register_pk":"198006","name":"麻野館玄関棟","kana":"あさのかんげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市二見町茶屋537-10","lat":34.507966,"lng":136.781059,"geo_status":"db","era":"明治28／大正11頃改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積437㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"24 － 0177","desc":"二見浦に面する二見旅館街のほぼ中央に位置する旅館建築。玄関棟は街道に面する入母屋造桟瓦葺で、周囲に庇を廻らす。一階に玄関、帳場、厨房、浴室等、二階に客室と従業員室を配する。正面西寄りに切妻破風の本玄関を付す。二見の和風旅館の特色を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010173"},{"id":"00010175","register_sub_id":"101","register_pk":"198008","name":"麻野館土蔵","kana":"あさのかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊勢市二見町茶屋537-10","lat":34.508034,"lng":136.780911,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"24 － 0179","desc":"玄関棟と広間棟の間、中庭を挟んで西寄りに位置する二階建の土蔵。屋根は切妻造桟瓦葺とし、外壁は黒漆喰塗の鉢巻下部まで簓子下見板を張る。中庭側の窓の瓦庇は、螻羽に破風板を含む役物瓦を用い、熨斗両端に波紋の飾りを載せるなどアクセントを付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010175"},{"id":"00010174","register_sub_id":"101","register_pk":"198007","name":"麻野館広間棟","kana":"あさのかんひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市二見町茶屋537-10","lat":34.508158,"lng":136.781085,"geo_status":"db","era":"明治28／昭和12頃改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造3階建、瓦葺、建築面積312㎡","structure_material":"木造3階建","registered":"2014.10.07(平成26.10.07)","register_no":"24 － 0178","desc":"玄関棟の奥に位置する旅館建築。北は海岸に面し、海岸への裏口が設けられている。一階と三階を客室とし、二階に客室のほか八〇畳の大広間を設ける。大広間は折上格天井で西面中央にトコ、左右に違棚と付書院を並べる。建具や欄間などに精緻な細工を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010174"},{"id":"00002265","register_sub_id":"101","register_pk":"103255","name":"伊勢河崎商人館北蔵二","kana":"いせかわさきしょうにんかんきたぐらに","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.49693398,"lng":136.71748751,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積102㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0034","desc":"伊勢河崎商人館のもとである小川酒店は老舗の酒卸業で，元禄年間の創業といわれる。北蔵二は酒蔵で，敷地の北側，北蔵一の西側に接するよう並んで建つ。切妻造・本瓦葺の屋根で，平屋建の前室と２階建の後室からなり，前室を比較的広くとる形態に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002265"},{"id":"00002259","register_sub_id":"101","register_pk":"103249","name":"伊勢河崎商人館主屋","kana":"いせかわさきしょうにんかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.496567,"lng":136.717621,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0028","desc":"伊勢河崎商人館は河岸問屋街の河崎にある旧株式会社小川商店の一連の施設。主屋は，２階建，切妻造・妻入で，屋根は本瓦葺である。正面が街路に対して鍵型に突き出ているため，壁面を下見板で囲った特徴ある外観と相俟って，独特な景観を創り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002259"},{"id":"00002261","register_sub_id":"101","register_pk":"103251","name":"伊勢河崎商人館南蔵一","kana":"いせかわさきしょうにんかんみなみぐらいち","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.49651,"lng":136.717743,"geo_status":"db","era":"慶応3","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積66㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0030","desc":"河崎は勢田川沿いに形成された河岸問屋街。街路を挟んで主屋の対面に建つ３棟の土蔵は，背面が勢田川に面している。東端にある南蔵一は２階建，切妻造・妻入で，不整形な敷地のため，平面は菱形であるが，状態は良好である。棟木に慶応３年の墨書がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002261"},{"id":"00002263","register_sub_id":"101","register_pk":"103253","name":"伊勢河崎商人館南蔵三","kana":"いせかわさきしょうにんかんみなみぐらさん","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.496399,"lng":136.717621,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積41㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0032","desc":"南蔵三ももと酒蔵で，南蔵二の西側にほぼ並行して建つ。桁行は南蔵二とほぼ同規模だが，梁間が小さい。切妻造・本瓦葺で，北妻面の庇は南蔵二と共有し，壁面は黒染の下見板張。勢田川に面して３棟の蔵が並ぶ景観は，舟運で栄えた町の歴史をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002263"},{"id":"00002262","register_sub_id":"101","register_pk":"103252","name":"伊勢河崎商人館南蔵二","kana":"いせかわさきしょうにんかんみなみぐらに","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.496429,"lng":136.717682,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積81㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0031","desc":"主屋の対面に建つ３棟の土蔵のうち，南蔵二はその中央にある。３棟の内，規模が最も大きく，鬼瓦に明治２５年の銘がある。もとは酒蔵で，切妻造・本瓦葺。丁寧な野面石積の基礎上に建ち，北妻面に戸口を設け庇をつけ，壁面は黒染の下見板張で，重厚感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002262"},{"id":"00009623","register_sub_id":"101","register_pk":"194619","name":"一乃湯本館","kana":"いちのゆほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市上野西日南町1761他","lat":34.76185553,"lng":136.12978942,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0156","desc":"前庭を挟んで建つ。木造二階建、入母屋造妻入、桟瓦葺で、唐破風屋根の玄関を張出す。一階は脱衣所、二階は湯上りの休憩所として座敷を配す。全体は和風の意匠だが、浴場入口壁にはテラコッタやアーチなど洋風の意匠を見せる。上野城下町の歴史的景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009623"},{"id":"00009624","register_sub_id":"101","register_pk":"194620","name":"一乃湯門","kana":"いちのゆもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊賀市上野西日南町1761他","lat":34.76172942,"lng":136.12984177,"geo_status":"db","era":"大正15／昭和25改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"石造、間口2.1m、柵付","structure_material":"石造","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0157","desc":"本館正面の通りに面して建つ。花崗岩の石柱と鉄製の両開き門扉、両脇柱と鉄柵よりなる。門の上部には昭和二五年一乃湯開業時に設置された一乃湯の名前と温泉マークをかたどったネオン管の看板が取り付く。上野城下町の当時の銭湯文化の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009624"},{"id":"00009027","register_sub_id":"101","register_pk":"162387","name":"いとう旅館本館","kana":"いとうりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野桑町1481他","lat":34.75870975,"lng":136.13317307,"geo_status":"db","era":"明治後期／昭和33年増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積279㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0117","desc":"通りからやや後退した位置に建つ。木造二階建、建築面積279㎡。中庭を囲むように東棟と西棟、北棟が配される。十畳の主室には座敷飾りを構え、天井は格天井で格縁を黒漆塗とし、格板に鳳凰などを色彩豊かに描く。良質な茶屋建築の趣を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009027"},{"id":"00003677","register_sub_id":"101","register_pk":"104667","name":"上野文化センター","kana":"うえのぶんかせんたー","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市上野中町3024","lat":34.76577313,"lng":136.1278026,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積84㎡","structure_material":"木造3階建","registered":"2003.12.01(平成15.12.01)","register_no":"24 － 0048","desc":"上野市の中心街に建つ木造３階建の商店建築。当初は倉庫として建設されたが，現在では事務所等に利用されている。外観は１階を花崗岩の石貼とし，２階以上はモルタル塗で，屋根は寄棟造鉄板葺である。上野市中心街の戦前の繁栄の様子を今に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003677"},{"id":"00009985","register_sub_id":"101","register_pk":"196132","name":"栄楽館土蔵","kana":"えいらくかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野相生町2842","lat":34.76457535,"lng":136.13177735,"geo_status":"db","era":"明治6／平成6改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0175","desc":"南棟の南東隅に位置し、南北棟で建つ土蔵造二階建の蔵。西側に出入口を開き、土戸を建て込む。西面の腰には当地方で「鼓繋ぎ」と呼ぶ独特な海鼠壁状の漆喰塗を施す。鬼瓦には屋号の「栄楽」と入れる。瀟洒な装飾を施した土蔵で、往時の盛況を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009985"},{"id":"00009984","register_sub_id":"101","register_pk":"196131","name":"栄楽館東棟","kana":"えいらくかんひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市上野相生町2842","lat":34.76465292,"lng":136.13172834,"geo_status":"db","era":"明治6／平成6改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積109㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0174","desc":"敷地北東側に南北棟で建つ。木造二階建で、一階には中庭に面して二室の座敷を配し、二階は一室の大広間とする。西面と北面に廻らされた縁からは、ガラス窓越しに庭園への眺望を得る。二階大広間は、トコ柱に丸太の曲り材を用いるなど、数寄屋風の意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009984"},{"id":"00009983","register_sub_id":"101","register_pk":"196130","name":"栄楽館南棟","kana":"えいらくかんみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市上野相生町2842","lat":34.76453548,"lng":136.1316978,"geo_status":"db","era":"明治6／平成6改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0173","desc":"敷地南寄りに奥まって位置する。木造二階建で、一階には座敷三室と茶室が、二階には座敷二室が配される。欄間や高欄など随所に竹と扇を主題とした細工を施す。茶室では棹縁を放射状に配るなど、部屋ごとに天井の意匠を変え、変化に富む内装に見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009983"},{"id":"00009986","register_sub_id":"101","register_pk":"196133","name":"栄楽館門及び塀","kana":"えいらくかんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野相生町2842","lat":34.76474194,"lng":136.13167774,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"門 木造、瓦葺、間口1.8m 塀 土塀、瓦葺、総延長14m","structure_material":"門 木造","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0176","desc":"道路に面して敷地の北辺を区画する塀で、西寄りに門を開く。上野城の石垣材と伝える大振りな石を腰高に積んで基礎とし、周囲に拳大の自然石を貼り付け、その上部に真壁造で瓦葺の塀を建てる。壁の上部には雲形状の絵様を象り、軽妙な佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009986"},{"id":"00012378","register_sub_id":"101","register_pk":"531702","name":"オーデン大門ビル（旧四日市銀行津支店）","kana":"おーでんだいもんびる（きゅうよっかいちぎんこうつしてん）","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県津市大門254","lat":34.71883889,"lng":136.5122,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積238㎡、塔屋及び煙突付","structure_material":"鉄筋コンクリート造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"24-248","desc":"大門通りに東面して建つ旧四日市銀行津支店。鉄筋コンクリート造二階建で、屋上に塔屋と煙突を付ける。正面にイオニア式円柱の大オーダーを四本並べ、中央玄関上部にペディメントを戴く古典的で重厚な外観とする。地方における昭和初期銀行建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012378"},{"id":"00015201","register_sub_id":"101","register_pk":"530625","name":"数馬茶屋","kana":"かずまぢゃや","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊賀市小田町字新町裏1336他","lat":34.76759722,"lng":136.11993889,"geo_status":"db","era":"昭和4年／昭和36年移築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"24 - 0333","desc":"伊賀越仇討で知られる鍵屋の辻の南側、公園内に東面して建つ休憩施設。入母屋造妻入桟瓦葺で北・東に庇を矩折に廻らす。内部は前土間で西に２室を配す。土間廻りは柱や天井材に古材を用いて古風にみせる。伊賀越仇討で待伏した茶屋を再現した記念碑的な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015201"},{"id":"00006862","register_sub_id":"101","register_pk":"107844","name":"角屋旅館本館","kana":"かどやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県津市芸濃町椋本字愛宕町727","lat":34.809673,"lng":136.427032,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、瓦葺、建築面積233㎡","structure_material":"木造2階一部平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"24 － 0068","desc":"旧伊勢別街道に南面して建つ。桁行７間半梁間５間半、切妻造桟瓦葺２階建で、背面西寄りに廊下や離れを出す。表側は西からアガリノマ、玄関土間、通り土間、８畳間を配し、２階には客室３室を並べる。揚戸や出格子等が旧伊勢別街道の旅籠の表構えを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006862"},{"id":"00007216","register_sub_id":"101","register_pk":"108198","name":"川地写真館","kana":"かわちしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県名張市新町218-1","lat":34.61953,"lng":136.086227,"geo_status":"db","era":"大正10／昭和35頃・昭和45改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階一部3階建、瓦葺及び鉄板葺、建築面積102㎡","structure_material":"木造2階一部3階建","registered":"2008.07.08(平成20.07.08)","register_no":"24 － 0073","desc":"南西角地に建つ木造２階一部３階建である。東側道路を正面に、北東の３階建屋根に三角の妻壁を立ち上げ、パラペット隅に小塔形飾りを付ける。外壁はモルタル塗で、１、２階外壁のタイル貼は後の改修。当初の写場は２階西側で、屋根を一部ガラス張としていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007216"},{"id":"00008294","register_sub_id":"101","register_pk":"133936","name":"旧伊藤伝七別邸さつき棟","kana":"きゅういとうでんしちべっていさつきとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県四日市市高砂町3492-67他","lat":34.96178978,"lng":136.63612431,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0091","desc":"敷地の北西隅に建つ。建築面積５６㎡、木造平屋建、切妻造桟瓦葺で、十畳と六畳を並べて南面の庭側に縁をめぐらす。十畳では琵琶棚付のトコやトコ脇、付書院を設け、長押に半割丸太を用いるなど、瀟洒な意匠をもつ。開放的なつくりの離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008294"},{"id":"00013736","register_sub_id":"101","register_pk":"507741","name":"旧喜多藤艶秀亭","kana":"きゅうきたとえんしゅうてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県名張市本町116","lat":34.61864167,"lng":136.08824167,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 294","desc":"敷地の東に建つ。入口を表門とは別にする独立した客室。平屋建切妻造桟瓦葺。外壁は腰を割竹張、上部を色土で仕上げ、内部は和室四室に洋室を配す。各室毎に独立した玄関を設けて個別に出入りでき、意匠を違えた窓をつくる等趣向を凝らす。東辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013736"},{"id":"00013733","register_sub_id":"101","register_pk":"507738","name":"旧喜多藤大広間棟","kana":"きゅうきたとおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61848889,"lng":136.08791944,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積164㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 291","desc":"別館の西に建つ。北面して建ち、二階建入母屋造桟瓦葺。一階は座敷とダンスホールとし、ホールは洋風に中国風意匠を取入れた趣味性の高いつくり。二階は四四畳大広間で折上格天井に色漆喰壁を用いた豪奢な意匠。別館同様川沿いを掃出の開口として眺望を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013733"},{"id":"00013738","register_sub_id":"101","register_pk":"507743","name":"旧喜多藤表門","kana":"きゅうきたとおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61875556,"lng":136.087675,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造、瓦葺一部銅板葺、間口2.6m、左右袖塀付","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 296","desc":"初瀬街道に面して建つ薬医門。間口二・六メートルで左右に袖塀が付属する。本柱、控柱とも節を出した丸太材を用いて腕木を受け軒桁を渡す。屋根は入母屋造桟瓦葺一部銅板葺。軒天井は小丸太を敷並べた瀟洒な意匠。街道沿いにもと料亭旅館の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013738"},{"id":"00013735","register_sub_id":"101","register_pk":"507740","name":"旧喜多藤皐月寮","kana":"きゅうきたとさつきりょう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61848889,"lng":136.08775278,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 293","desc":"翠明荘から接続する茶室。平屋建切妻造桟瓦葺で東面に待合付設。茶室は四畳大で炉を切らず、西面一間半を床構えとし、皮付の曲材を用いた床柱や角竹、斜めの地袋で変化を付ける。南脇は半畳の点前座とし、天井は点前座と主室で網代と竹の棹縁に張り分ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013735"},{"id":"00013734","register_sub_id":"101","register_pk":"507739","name":"旧喜多藤翠明荘","kana":"きゅうきたとすいめいそう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61844444,"lng":136.08781667,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 292","desc":"大広間棟の西に建つ。平屋建入母屋造桟瓦葺で軒先を銅板葺として軽さを演出する。もとは居宅で、大広間と皐月寮へ続く渡り廊下を付属する。内部は一〇畳客間と洋室で、客間書院の格狭間形の下地窓や渡廊下袖壁の半円の切り欠きなど、数寄屋趣味が横溢する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013734"},{"id":"00013732","register_sub_id":"101","register_pk":"507737","name":"旧喜多藤別館","kana":"きゅうきたとべっかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61849722,"lng":136.08805278,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積209㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 290","desc":"名張川沿いのもと料亭旅館。北面して建ち、二階建切妻造桟瓦葺。一階は北をホールと調理場、南を客室とし、二階はホールの周囲に座敷を配する。二階は川沿いの間口いっぱいを掃出のガラス窓開口として眺望を誇る。料亭旅館の中心建物で川沿いの景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013732"},{"id":"00013737","register_sub_id":"101","register_pk":"507742","name":"旧喜多藤便所棟","kana":"きゅうきたとべんじょとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61861667,"lng":136.08796667,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 295","desc":"表門から入って正面に建つ別館の手前に位置する。平屋建入母屋造桟瓦葺で、別館と大広間棟からそれぞれ渡り廊下で接続する。便所と脱衣場・浴室からなり、廊下は柱を立てず、細丸太の垂木を並べて化粧屋根とし、人造石の手洗いを設ける。敷地の一点景を為す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013737"},{"id":"00012380","register_sub_id":"101","register_pk":"531704","name":"旧料理旅館九重別館","kana":"きゅうりょうりりょかんここのえべっかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県伊賀市上野西日南町1773他","lat":34.76145833,"lng":136.12976111,"geo_status":"db","era":"昭和24年頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"24-250","desc":"本館背面に離れて建つ小座敷。座敷二室を設けて各玄関を構え、接続部に共通の水回りを設ける。玄関や下屋に青瓦、壁に乱形石やタイルを用い、内部は大壁とし、新興数寄屋風の意匠で仕上げる。本館とともに伝統木造の料理旅館の姿をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012380"},{"id":"00012379","register_sub_id":"101","register_pk":"531703","name":"旧料理旅館九重本館","kana":"きゅうりょうりりょかんここのえほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊賀市上野西日南町1773他","lat":34.7615,"lng":136.1299,"geo_status":"db","era":"大正13年頃／昭和18年頃増築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積317㎡","structure_material":"木造2階一部3階建","registered":"2018.05.10(平成30.05.10)","register_no":"24-249","desc":"旧城下の町人地にあり、東西通りの敷地の背面に南北通りの敷地を併せたＴ字形の敷地に建つ。本館は従前の町家を改修したもので、東西通りは町家の外観を残しつつ南北通りは前庭をもつ屋敷風として趣を異にする。城下の歴史と変遷を物語る建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012379"},{"id":"00012381","register_sub_id":"101","register_pk":"531705","name":"旧料理旅館九重門及び塀","kana":"きゅうりょうりりょかんここのえもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊賀市上野西日南町1773他","lat":34.76145,"lng":136.13006667,"geo_status":"db","era":"昭和18年頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"門 木造、瓦葺、間口3.1m 塀 木造、瓦葺、総延長14m","structure_material":"門 木造","registered":"2018.05.10(平成30.05.10)","register_no":"24-251","desc":"南北通りの敷地正面と南隣の敷地境を区切る塀と正面中央に開いた切妻造の門。真壁造の中塗仕上、腰羽目板張とし、敷地境は大和塀とする。門は軒の低い棟門で、両側に割竹の袖塀を付ける。本館とともに伝統木造の料理旅館の表構えをかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012381"},{"id":"00012938","register_sub_id":"101","register_pk":"368019","name":"熊野古道おもてなし館（旧杤尾家住宅店舗兼主屋）","kana":"くまのこどうおもてなしかん（きゅうとちおけじゅうたくてんぽけんしゅおく）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県熊野市木本町字関舟町204","lat":33.89030556,"lng":136.10396667,"geo_status":"db","era":"明治中期／平成26年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積145㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"24 － 273","desc":"市中心部のもと小間物問屋。熊野街道に北面して建つ切妻造桟瓦葺つし二階建で、正面下屋上を黒漆喰塗として中央に白漆喰枠の虫籠窓を穿ち、東側に背面納戸付の袖塀を付す。内部は改変があるが、西奥の座敷に当初の姿を残す。街道の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012938"},{"id":"00008497","register_sub_id":"101","register_pk":"134893","name":"桑名市石取会館（旧桑名信用金庫京町支店）","kana":"くわなしいしどりかいかん(きゅうくわなしんようきんこきょうまちしてん)","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県桑名市京町16","lat":35.06359908,"lng":136.69427903,"geo_status":"db","era":"大正14年／平成3年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積168㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"24 － 0101","desc":"市の中心、京町と職人町の通りが交叉する角地に建つ。鉄筋コンクリート造二階建で、北に旧金庫室を付ける。東南角を曲面とし、縦長の窓を二層を通して開ける。南・東面は簡潔で幾何学的な柱型を現し、縦長窓上部には歯飾りを施し、陰影の深い意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008497"},{"id":"00010614","register_sub_id":"101","register_pk":"201188","name":"小西萬金丹本舗内蔵","kana":"こにしまんきんたんほんぽうちくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市八日市場町8","lat":34.491087,"lng":136.702054,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積14㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0205","desc":"店舗兼主屋の北西隅に接続し、東西棟で建つ。桁行二間梁間二間、土蔵造二階建、切妻造本瓦葺である。外壁は頂部に鉢巻を廻らし、高く簓子下見板を張る。南面に戸口を開いて漆喰塗の土戸を吊る。商品の萬金丹や製薬道具を納めた蔵で、敷地後方の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010614"},{"id":"00010615","register_sub_id":"101","register_pk":"201189","name":"小西萬金丹本舗外蔵","kana":"こにしまんきんたんほんぽそとくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市八日市場町7","lat":34.491101,"lng":136.70229,"geo_status":"db","era":"安永8年（1779）","year":1779,"year_source":"db","year_min":1779,"year_max":1779,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0206","desc":"店舗兼主屋の北東方に南北棟で建ち、土蔵造二階建、切妻造本瓦葺である。南正面を戸口として土戸を開き、桟瓦葺の下屋を設ける。外壁は頂部に鉢巻を廻らして簓子下見板を張る。二階は換気窓のみ設ける。着物などを納めていた家財蔵で、商家の屋敷構えを創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010615"},{"id":"00010613","register_sub_id":"101","register_pk":"201187","name":"小西萬金丹本舗店舗兼主屋","kana":"こにしまんきんたんほんぽてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊勢市八日市場町8","lat":34.49104,"lng":136.702105,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積144㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0204","desc":"外宮門前の通り沿いに南面して建つ。起り付の切妻造妻入で、正面に本瓦葺の下屋を設ける。外壁全体を簓子下見板張とし、二階正面に出格子をたてる。内部は中央のミセの奥に座敷を並べ、東に茶室、西に坪庭を配する。伊勢町家の特徴を示す大型の商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010613"},{"id":"00009619","register_sub_id":"101","register_pk":"194615","name":"佐野家住宅石垣","kana":"さのけじゅうたくいしがき","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県松阪市飯南町深野字田之浦3490-1","lat":34.47530963,"lng":136.40986743,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、延長48m","structure_material":"石造","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0152","desc":"敷地の北から東辺を囲む。折曲り延長四八メートルで、上部は土塀や生垣とする。当地域でよく見られる、玉石を野面積みとした石垣で、北面の一部では石垣下部に窪みを設けて湧水溜とするなど特徴的なつくりにも変化を見せる。伝統的な敷地景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009619"},{"id":"00009618","register_sub_id":"101","register_pk":"194614","name":"佐野家住宅小蔵","kana":"さのけじゅうたくこくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県松阪市飯南町深野字田之浦3490-1","lat":34.47530616,"lng":136.4100717,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積7.2㎡","structure_material":"土蔵造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0151","desc":"敷地の北方に南北棟で建つ。切妻造桟瓦葺、妻入で南面の戸口に庇を付ける。棟木と桁に流し板を渡して屋根野地とする。道具類の収納に用いられた蔵で、桁行四・八メートル梁間一・五メートルと小規模ながら、土塀、石垣とともに屋敷構えの境界を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009618"},{"id":"00009617","register_sub_id":"101","register_pk":"194613","name":"佐野家住宅主屋","kana":"さのけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯南町深野字田之浦3490-1","lat":34.47492307,"lng":136.40976713,"geo_status":"db","era":"明治前期／明治中期増築・昭和11・昭和37改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積172㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0150","desc":"佐野翠香堂の屋号で薬種業を営んだ家の主屋。櫛田川北岸の和歌山街道に南面する。切妻造桟瓦葺、東に通り土間、西に食違二列六間取の座敷を配す主体部と、東に接続し、二室と縁が取付く東西棟の増築部からなる。主体部正面の建ちが低く当地域でも古式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009617"},{"id":"00009620","register_sub_id":"101","register_pk":"194616","name":"佐野家住宅土塀","kana":"さのけじゅうたくどべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯南町深野字田之浦3490-1","lat":34.4750959,"lng":136.41033353,"geo_status":"db","era":"明治頃","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治頃","structure":"土塀、瓦葺、延長16m、潜戸付","structure_material":"土塀","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0153","desc":"敷地東面の石垣上に築かれた土塀で、北側の六・四メートルに対し南側九・三メートルは棟を下げて、潜戸一所を開く。切妻造桟瓦葺で、軒裏まで漆喰塗込として鉢巻を廻らす。重厚な趣を見せ、小蔵、石垣とともに敷地の景観を整える要素の一つとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009620"},{"id":"00014854","register_sub_id":"101","register_pk":"519114","name":"清風亭客室棟","kana":"せいふうていきゃくしつとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県名張市鍛治町91","lat":34.618575,"lng":136.09006111,"geo_status":"db","era":"大正3年／昭和39年・平成26年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"24 - 0330","desc":"玄関棟の南に位置する客室棟は、名張川沿いに面する座敷棟。二階建切妻造桟瓦葺とし、一階は厨房と２室の座敷、二階は３室続きの座敷で東に床を構え、船底天井を張り、南に縁を通して川を望む開放的なつくり。大人数の宴席も対応可能な広間で時代相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014854"},{"id":"00014853","register_sub_id":"101","register_pk":"519113","name":"清風亭玄関棟","kana":"せいふうていげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県名張市鍛治町91","lat":34.61865556,"lng":136.09010278,"geo_status":"db","era":"大正3年／昭和39年・平成10年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"24 - 0329","desc":"市街地南方の鍛冶町にある料理旅館。通りに面した玄関棟は二階建切妻造平入の東西棟で、一階の戸口以外は出格子構えとし東寄りに土間、中央に階段と帳場を配す。二階は前後二列に部屋を配し、渡廊下で南の客室棟と接続。格子構えの外観が通りの景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014853"},{"id":"00009023","register_sub_id":"101","register_pk":"162383","name":"中六店舗","kana":"なかろくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県志摩市磯部町上之郷字上ノ里392他","lat":34.38041726,"lng":136.81022788,"geo_status":"db","era":"昭和4年／昭和後期改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積172㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0113","desc":"伊勢神宮の別宮伊雑宮の門前に位置する。木造二階建、建築面積１７２㎡。Ｌ字形棟の入母屋造桟瓦葺で、一階には小さく入母屋造の角屋を付設し、外観に変化を付ける。神社側に妻を見せ、二階は大きく掃き出し窓を設け、軽快で開放的な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009023"},{"id":"00014027","register_sub_id":"101","register_pk":"508287","name":"星出館主屋","kana":"ほしでかんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊勢市河崎二丁目156-3","lat":34.49481944,"lng":136.71410278,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積326㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"24 - 0311","desc":"勢田川水運で栄えた河崎の八間道路に西面する二階建旅館。入母屋造桟瓦葺の大屋根の下に庇を付し、斜行する道路に対して正面が雁行し、唐破風玄関を設けて賑やかな外観とする。客室は各々意匠を凝らし、中庭を跨ぐ二階橋を備える。近代の伊勢詣を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014027"},{"id":"00014028","register_sub_id":"101","register_pk":"508288","name":"星出館塀","kana":"ほしでかんへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊勢市河崎二丁目156-3","lat":34.49476667,"lng":136.714,"geo_status":"db","era":"昭和2年頃／平成30年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造、瓦葺、延長10m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"24 - 0312","desc":"主屋の西正面の南端に設けた塀。玄関南から敷地西辺を延びて、南西角で折れて主屋に取付く。自然石の基礎に節付丸太柱を立て、地長押で固め、漆喰壁に櫛形下地窓を開き、腰は竪板張とする。屋根は桟瓦葺、杉丸太の疎垂木の軒で、和風旅館の外観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014028"},{"id":"00013812","register_sub_id":"101","register_pk":"507774","name":"松井真珠店蔵","kana":"まついしんじゅてんくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県志摩市阿児町神明字カシコ733-4","lat":34.30776111,"lng":136.81893889,"geo_status":"db","era":"昭和26年／昭和61年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積26㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0298","desc":"店舗の北方、鉄筋コンクリート造二階建の商品蔵である。桟瓦葺の切妻屋根や出格子窓で土蔵風外観とする。入口は両開き鉄扉と片引戸、網戸で、窓は鉄扉とガラス戸の両開きである。内壁は杉板張で天井を白漆喰塗。賢島駅の向かいに特色ある景観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013812"},{"id":"00013811","register_sub_id":"101","register_pk":"507773","name":"松井真珠店店舗","kana":"まついしんじゅてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県志摩市阿児町神明字カシコ733-4","lat":34.30756389,"lng":136.81901389,"geo_status":"db","era":"昭和4年頃／昭和48年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0297","desc":"賢島港に面する木造二階建の真珠販売店。寄棟造の桟瓦葺で南正面から東西両側面へ桟瓦葺下屋を廻す。二階手摺には松の図柄を彫抜く。一階は西半北寄りを床上の帳場とし、二階は階段西を六畳座敷、東を一二畳半の広間とする。当地の産業を象徴する店舗建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013811"},{"id":"00011147","register_sub_id":"101","register_pk":"205254","name":"八千代大広間棟","kana":"やちよおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県松阪市殿町1295","lat":34.574695,"lng":136.528846,"geo_status":"db","era":"昭和初期／昭和32改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積249㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"24 - 0233","desc":"玄関棟の奥に棟を直交して建つ木造二階建。一階に三〇畳の広間など、二階には一一〇畳の大広間を配する。内部造作は昭和三二年の改修によるが、大広間の折上格天井や枝付の大木の床柱、瀟洒な欄間意匠など、当時の旅館建築における和風意匠の嗜好をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011147"},{"id":"00011146","register_sub_id":"101","register_pk":"205253","name":"八千代玄関棟","kana":"やちよげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県松阪市殿町1295","lat":34.574629,"lng":136.529018,"geo_status":"db","era":"昭和初期／昭和32改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積215㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"24 - 0232","desc":"松坂旧城下で通りに東面する料理旅館。玄関棟はやや後退して建つ木造二階建で、東正面に入母屋造の妻を見せ、玄関を構える。一階にロビーなど、二階は中廊下沿いに客室を配する。客室は網代天井や古びを見せた材を用いるなど、室ごとに異なる意匠と趣をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011146"},{"id":"00011148","register_sub_id":"101","register_pk":"205255","name":"八千代鶴亀棟","kana":"やちよつるかめとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県松阪市殿町1295","lat":34.574533,"lng":136.529023,"geo_status":"db","era":"大正初期／昭和前期移築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"24 - 0234","desc":"玄関棟正面の南側に建つ木造平屋建。一〇畳の鶴の間と八畳の亀の間を南北に並べ、東西に縁を通す。小津家住宅時代の遺構とみられ、造作は玄関棟などと比べて古風な意匠をもつ。松坂城下において旧武家町が閑静な住宅地へと変遷した近代的変容の一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011148"},{"id":"00009982","register_sub_id":"101","register_pk":"196129","name":"山口家住宅主屋","kana":"やまぐちけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市上八町1495-6","lat":34.62521264,"lng":136.09125385,"geo_status":"db","era":"明治前期／昭和6・平成18改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積186㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0172","desc":"初瀬街道に南面する木造二階建町家で、後方に明治期の座敷部を残しつつ、正面側を昭和六年に建替えて旅館とした。正面中央に主玄関を開き、東側に出格子をたて、西側に脇玄関を開く。二階は小部屋を多数配し、正面に手摺を付ける。戦前の街路の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009982"},{"id":"00007748","register_sub_id":"101","register_pk":"108729","name":"大和屋店舗","kana":"やまとやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市本町55","lat":34.61962575,"lng":136.08873443,"geo_status":"db","era":"江戸末期／昭和34・昭和43改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"24-0078","desc":"旧市街地を通る初瀬街道に北面して建つ。間口８．３ｍの木造つし２階建、切妻造平入桟瓦葺で正面に下屋庇を付ける。正面全面を開口とし、西半部を土間、東半部を床上とする。上部は白漆喰仕上げで虫籠窓を穿ち、屋根に越屋根を載せ、老舗らしい佇まいを呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007748"},{"id":"00010979","register_sub_id":"101","register_pk":"208949","name":"料理旅館梅家","kana":"りょうりりょかんうめや","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市平田374","lat":34.766555,"lng":136.213882,"geo_status":"db","era":"明治後期／大正8改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積113㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"24-0231","desc":"伊賀街道に北面して建つ料理旅館。二階建入母屋造平入で、一階は西を土間とする四間取の平面とし、二階は中廊下の左右に部屋を配する。一階正面外観は欄間付竪格子戸を並べ、天女と鷹の鬼瓦、東西脇塀の欄間の蝙蝠の意匠など要所にアクセントをつけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010979"},{"id":"00009025","register_sub_id":"101","register_pk":"162385","name":"旅館薫楽荘蔵","kana":"りょかんくんらくそうくら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野桑町1474他","lat":34.75854356,"lng":136.13283674,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0115","desc":"主屋の西北に位置する。土蔵造二階建、桁行４．９ｍ梁間３．９ｍ。南北棟の切妻造桟瓦葺で、北妻は通りに面する。外壁は銅板張で腰を簓子下見板張とし、東面は腰海鼠壁で出入口を穿つ。通り側の腰壁は下見板張りとして、塀と連続的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009025"},{"id":"00009024","register_sub_id":"101","register_pk":"162384","name":"旅館薫楽荘本館","kana":"りょかんくんらくそうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野桑町1474他","lat":34.75850374,"lng":136.13294233,"geo_status":"db","era":"明治後期／昭和49年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積189㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0114","desc":"敷地の北寄りに、通りに北面して建つ。木造二階建、建築面積１８９㎡、切妻造桟瓦葺。一階に五室、二階に六室の座敷を設け、各室はトコや棚、欄間などで意匠を凝らす。玄関の装飾タイルや四阿風のホール天井、廊下の小壁など見所の多い建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009024"},{"id":"00009026","register_sub_id":"101","register_pk":"162386","name":"旅館薫楽荘門及び塀","kana":"りょかんくんらくそうもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野桑町1474他","lat":34.75859802,"lng":136.13295586,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長12m","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0116","desc":"通り沿いに設けられ、主屋との間に庭が設けられる。高さ３．３ｍ延長１２ｍの塀で、主屋正面に間口２．０ｍの門口を開き、前後に瓦庇をかけ、引き分け戸をたてる。塀は腰高に竪板を張り、小壁を黒漆喰仕上げとする。粋な雰囲気を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009026"},{"id":"00006863","register_sub_id":"101","register_pk":"107845","name":"旅館寿亭水雲閣","kana":"りょかんことぶきていすいうんかく","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県三重郡菰野町大字菰野8588","lat":35.01568672,"lng":136.445015,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、銅板葺、建築面積131㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"24 － 0069","desc":"三滝川南岸近くの小高い位置に、南北棟で建つ。桁行７間梁間４間半規模、入母屋造銅板葺の木造２階建で、各階とも主室１０畳と次の間８畳からなり、北・西・南の三方に入側をまわし、北・西面には高欄付の濡縁を付ける。主室は良材を用い、品格ある意匠に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006863"},{"id":"00003678","register_sub_id":"101","register_pk":"104668","name":"今津ヴォーリズ資料館（旧百卅三銀行今津支店）","kana":"いまづう゛ぉーりずしりょうかん（きゅうひゃくさんじゅうさんぎんこういまづしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県高島市今津町今津175","lat":35.40217363,"lng":136.03557204,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積84㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"25 － 0229","desc":"Ｗ.Ｍ.ヴォーリズの設計により銀行店舗として建てられた。ＲＣによる柱梁構造に，壁面を煉瓦積としている。外観は石積風の古典様式を基調とするが，比較的簡素にまとめる。昭和末期から図書館として利用され，平成１５年からは資料館として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003678"},{"id":"00009035","register_sub_id":"101","register_pk":"162395","name":"宇水理髪館店舗","kana":"うみずりはつかんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市河原3-103-2","lat":35.26507238,"lng":136.25564587,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積46㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"25 － 0303","desc":"通りに南面して建ち、桁行４．５ｍ梁間１０ｍ、木造二階建、切妻造桟瓦葺である。正面のアーチ頂部にバリカン形をあしらい、左右にアカンサス模様を飾る。町家形式を踏襲しつつ正面を洋風意匠でまとめており、町並みのアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009035"},{"id":"00002634","register_sub_id":"101","register_pk":"103624","name":"大津魚忠","kana":"おおつうおちゅう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市京町2-404、405","lat":35.006599,"lng":135.865829,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積169㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0185","desc":"大津旧市街の中心に呉服商の住居として建てられた町家で，現在は料亭を営む。２階建，切妻造，平入，桟瓦葺で，正面１階は格子，２階は虫籠窓を設け，深い軒を腕木と出桁で受ける。軒高が高く，木割の細い繊細な構えは，明治後期の商家の姿を良く留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002634"},{"id":"00002150","register_sub_id":"101","register_pk":"103140","name":"かぎ楼","kana":"かぎろう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀653","lat":35.22521131,"lng":136.28862793,"geo_status":"db","era":"明治10／大正期増築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積308㎡","structure_material":"木造2階一部3階建","registered":"2001.04.24(平成13.04.24)","register_no":"25 － 0144","desc":"かぎ楼は江戸期創業の老舗の料亭旅館である。南北に棟を通す木造２階建，入母屋造の主屋に，３階建の客室棟が接続する。客室棟の内部は数寄屋風にまとめられ，３階の北及び東面に擬宝珠風高欄を廻す。多賀大社門前町のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002150"},{"id":"00009501","register_sub_id":"101","register_pk":"194294","name":"加藤家住宅（旧布惣）一之蔵","kana":"かとうけじゅうたく（きゅうぬのそう）いちのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市高宮町1121-1他","lat":35.23671538,"lng":136.25750706,"geo_status":"db","era":"江戸末期／平成21年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0325","desc":"街道に面して主屋の北隣に建つ。土蔵造二階建、桁行五・四メートル梁間五・〇メートル、切妻造瓦葺で、入口を主屋の店舗に面した南面に開く。置屋根とし、扠首組の木鼻に彫刻を施す。主屋と並び建ち、宿場町の歴史的な景観をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009501"},{"id":"00009503","register_sub_id":"101","register_pk":"194296","name":"加藤家住宅（旧布惣）三之蔵","kana":"かとうけじゅうたく（きゅうぬのそう）さんのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市高宮町1121-1他","lat":35.23659974,"lng":136.25766767,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0327","desc":"敷地背面の東南隅に主屋から離れて建つ。土蔵造二階建、桁行八・一メートル梁間五・一メートル、切妻造瓦葺で、入口を西面に開く。大規模で建ちが高く、軒廻りは桁先をみせず鉢巻を廻す。主屋、一之蔵、二之蔵とともに伝統的な町家の構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009503"},{"id":"00009500","register_sub_id":"101","register_pk":"194293","name":"加藤家住宅（旧布惣）主屋","kana":"かとうけじゅうたく（きゅうぬのそう）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市高宮町1121-1他","lat":35.23664471,"lng":136.25751919,"geo_status":"db","era":"江戸末期／昭和15年・平成21年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0324","desc":"中仙道高宮宿中心部に建つ元麻布商で街道に西面して建つ。木造二階建、桁行一六・六メートル梁間一二・四メートル、切妻造瓦葺。前面を店舗、背面を田の字型の床上部とする。正面は、海老虹梁状の腕木や二階の幅広の格子窓など当地方の町屋の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009500"},{"id":"00009502","register_sub_id":"101","register_pk":"194295","name":"加藤家住宅（旧布惣）二之蔵","kana":"かとうけじゅうたく（きゅうぬのそう）にのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市高宮町1121-1他","lat":35.23667683,"lng":136.25761199,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0326","desc":"主屋の背面北側に南面して建つ。土蔵造二階建、桁行三・八メートル梁間四・〇メートル、切妻造瓦葺で、入口を南面に開く。小規模ながら丁寧な造りで、軒廻りは桁先を現した塗籠仕上げとする。主屋、一之蔵、三之蔵とともに伝統的な町家の構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009502"},{"id":"00002640","register_sub_id":"101","register_pk":"103630","name":"かめや旅館広間","kana":"かめやりょかんひろま","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀631","lat":35.224834,"lng":136.288498,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0191","desc":"本館背後に増築された座敷棟。１５畳の主室と１２畳半の次の間からなり，２方に縁を廻らす。主室には床を中心に付書院，花頭窓付き地袋棚を配し，次の間にも地袋棚を備える。良材を用い，造作や建具は丁寧な造りで，座敷飾の独特の構えも巧みにまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002640"},{"id":"00002639","register_sub_id":"101","register_pk":"103629","name":"かめや旅館本館","kana":"かめやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀631","lat":35.224972,"lng":136.288635,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積155㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0190","desc":"多賀神社門前で江戸時代から営業する料理旅館。通りに面する本館は木造，２階建で，１階は広く土間を取り，２階は中廊下を配して前後に座敷を配する。正面に入母屋造の破風を見せ，その下に切妻造の玄関を張り出した姿は，社頭の景観を構成する主要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002639"},{"id":"00006308","register_sub_id":"101","register_pk":"107291","name":"木之本町きのもと交遊館","kana":"きのもとちょうきのもとこうゆうかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本1118","lat":35.50413345,"lng":136.22594248,"geo_status":"db","era":"昭和10／平成17改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積83㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"25 － 0246","desc":"湖北銀行木之本支店として建設。北国街道に東面して建つＲＣ造２階建である。旧客溜り部分を保存して背面側を改築した。正面はイオニア式円柱４本の大オーダーを付けた重厚なデザインである。外壁は人造石洗出し仕上げとする。町並みのランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006308"},{"id":"00012956","register_sub_id":"101","register_pk":"368036","name":"旧近江銀行愛知川支店","kana":"きゅうおうみぎんこうえちがわしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町愛知川38-2","lat":35.17180278,"lng":136.20772778,"geo_status":"db","era":"大正15年頃／平成30年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、建築面積161㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 439","desc":"旧愛知川宿中心部にある旧銀行店舗。鉄筋コンクリート造平屋建の一部2階建。正面中央部を枠取って西洋古典様式基調の意匠で整え、パラペット中央に幾何学的な意匠の軒飾を付す。県下における最初期の鉄筋コンクリート造建築で、地域の近代化を象徴する存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012956"},{"id":"00016399","register_sub_id":"101","register_pk":"536466","name":"旧小澤家住宅店舗兼主屋","kana":"きゅうおざわけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀627","lat":35.22474444,"lng":136.28917222,"geo_status":"db","era":"江戸末期／平成28年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"25 - 0530","desc":"多賀大社の門前町に位置し、かつて土産物屋を営んだ商家の主屋。多賀道に北面する二階建切妻造平入桟瓦葺で正面に下屋を付す。二階外壁は漆喰塗仕上で両端に袖壁を付す。一階東は旧の土間、西は床上で南西に角座敷を附属。通りに面し門前の景観をつくる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016399"},{"id":"00016401","register_sub_id":"101","register_pk":"536468","name":"旧小澤家住宅土蔵","kana":"きゅうおざわけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀627","lat":35.22478611,"lng":136.28911111,"geo_status":"db","era":"江戸末期／平成28年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積20㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"25 - 0532","desc":"主屋の西側に位置する土蔵。2階建切妻造桟瓦葺の東西棟で北面に庇を付す。外壁漆喰塗仕上で東面に戸口を開け、北面に窓を二箇所開ける。絵様付腕木で軒桁を支持するなど軒廻り賑やかで、小規模ながらも主屋と一体となって門前の歴史的な景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016401"},{"id":"00016400","register_sub_id":"101","register_pk":"536467","name":"旧小澤家住宅離れ","kana":"きゅうおざわけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀627","lat":35.224675,"lng":136.28911111,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"25 - 0531","desc":"主屋の南に接続する離れ座敷。平屋建切妻造桟瓦葺の南北棟で北・西に銅板葺下屋を付す。内部は２室の続き間座敷で南室東面に床を構え、各室は西面の広縁や濡縁を介して庭を望む。床柱に竹を用い、書院障子の組子や欄間彫刻など要所に繊細な意匠を用いる離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016400"},{"id":"00013739","register_sub_id":"101","register_pk":"505285","name":"旧木之本宿本陣（竹内家住宅）主屋","kana":"きゅうきのもとしゅくほんじん（たけうちけじゅうたく）おもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町941-1","lat":35.50531111,"lng":136.22567222,"geo_status":"db","era":"延享元年(1744)／平成30年改修","year":1744,"year_source":"db","year_min":1744,"year_max":1744,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積249㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 470","desc":"北国街道に西面する間口六間半の大規模町家。つし二階建切妻造平入桟瓦葺で、南を通り土間、北の表を一室の広いミセとし、その奥に二列六室を配する。たちが低く古式で、平面や小屋組に当初形式をよく残す。一八世紀前半に遡る木之本宿の本陣遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013739"},{"id":"00010477","register_sub_id":"101","register_pk":"199431","name":"旧滋賀銀行甲南支店","kana":"きゅうしがぎんこうこうなんしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲南町寺庄字上川原1078","lat":34.917886,"lng":136.181947,"geo_status":"db","era":"大正14／昭和50改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積150㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"25 － 0357","desc":"寺庄集落中ほどで杣街道に面して建つ。鉄筋コンクリート造で正面に矩形の柱形を張出し、内側にイオニア式オーダーを表し重厚なエンタブレチュアを支える。玄関上部は半円アーチの窓を設け装飾的な持送りを兼ねた要石を飾り、銀行建築らしい古典的意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010477"},{"id":"00000059","register_sub_id":"101","register_pk":"101049","name":"黒壁ガラス館本館（旧第百三十銀行長浜支店）","kana":"くろかべがらすかんほんかん（きゅうだいひゃくさんじゅうぎんこうながはましてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県長浜市元浜町12-38","lat":35.38069376,"lng":136.26709716,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積169㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"25 － 0001","desc":"伝統的な土蔵造を基調として，軒蛇腹，上下窓，天井飾等の要所に洋風の意匠を取り入れた建物。明治期には多くの銀行が土蔵造でつくられたが，滋賀県下における初期の事例のひとつである。黒漆喰塗りの外観から｢黒壁｣の愛称を持ち，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000059"},{"id":"00009498","register_sub_id":"101","register_pk":"194291","name":"阪本屋店舗兼主屋","kana":"さかもとやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市長等1-240他","lat":35.00810318,"lng":135.86102479,"geo_status":"db","era":"昭和11年／昭和中期改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積239㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0322","desc":"通りに北面する二階建町家。切妻造桟瓦葺で、正面に下屋を設ける。正面は、下階東側を店舗とし、西側は腰を御影石張とする。上階は黒色の小口タイル貼として中央に看板用の小屋根を突出す。内部では洋風の応接間を設けるほか、細部意匠にも趣向を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009498"},{"id":"00009036","register_sub_id":"101","register_pk":"162396","name":"滋賀中央信用金庫銀座支店店舗","kana":"しがちゅうおうしんようきんこぎんざしてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県彦根市河原3-117","lat":35.26617105,"lng":136.2550518,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、スレート葺、建築面積54㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"25 － 0304","desc":"市街地の交差点に建ち、木造二階建、建築面積５４㎡、寄棟造スレート葺である。交差点側を隅切りして腰折れ破風を載せ、左右に切妻破風を並べる。外壁は二階分の柱形と縦長窓を配するなど、瀟洒な外観で街角のアイストップとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009036"},{"id":"00002047","register_sub_id":"101","register_pk":"103037","name":"竹平楼御在所","kana":"たけへいろうございしょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県愛知郡愛荘町愛知川1608","lat":35.169476,"lng":136.206879,"geo_status":"db","era":"明治11","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"25 － 0139","desc":"竹平楼は中山道沿いに位置する江戸後期創業の旅籠で，明治１１年の明治天皇御巡幸に際して新築。南北棟，入母屋造，妻入で，各１間幅の床・床脇・付書院をもつ８畳を主室とし，半間幅の縁が南西２面に取付く。材料・意匠とも質の高い数寄屋風書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002047"},{"id":"00002048","register_sub_id":"101","register_pk":"103038","name":"竹平楼広間","kana":"たけへいろうひろま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県愛知郡愛荘町愛知川1608","lat":35.169521,"lng":136.206711,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"25 － 0140","desc":"敷地のほぼ中央に位置する東西棟，入母屋造，桟瓦葺の平屋建で，１０畳６室を３室２列に配置し，南北の両平側に半間幅の疎垂木木舞裏天井の縁廊下を付ける。各列端部に床・棚を設えた書院風広間になり，大工棟梁は湖東町今在家の木沢助次郎とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002048"},{"id":"00001195","register_sub_id":"101","register_pk":"102185","name":"中村商家保存館主屋","kana":"なかむらしょうかほぞんかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市旭町5","lat":35.27407349,"lng":136.261246,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造２階建，瓦葺，建築面積216㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"25 － 0112","desc":"彦根城下の東部地区を南北に通る町屋街の角地に東面して建つもと酒小売店舗。間口約１４ｍ、奥行約１２ｍの規模で、表側南半分を土間、北半分を田字型８畳４室とし、つし２階を設ける伝統的形式をとる。彦根における町屋の変遷を知るうえで貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001195"},{"id":"00007056","register_sub_id":"101","register_pk":"108038","name":"双葉館魚寅楼奥座敷","kana":"ふたばかんうおとらろうおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県草津市草津二丁目字下御田伝532他","lat":35.015926,"lng":135.961243,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積114㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"25 － 0256","desc":"本館の東側に接続し、庭園に面して建つ。建築面積１１４㎡、木造２階建、入母屋造及び切妻造瓦葺で、１、２階とも庭園側に縁と庇を巡らす。全体に良材を用いて丁寧に仕上げており、１階の大広間は折上格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007056"},{"id":"00007057","register_sub_id":"101","register_pk":"108039","name":"双葉館魚寅楼塀","kana":"ふたばかんうおとらろうへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県草津市草津二丁目字下御田伝532他","lat":35.01604224,"lng":135.96114054,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、瓦葺、延長11m","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"25 － 0257","desc":"本館の旧玄関から道路沿いに延びる。折曲り延長１１ｍ、木造、瓦葺。延石上に節丸太の柱を建てて地覆をまわし、瓦には目板瓦を用いる。本館同様、腰を竪板張、内法壁は赤色とし、隅切矩形の窓を開ける。料亭の外塀に相応しい、瀟洒で上品な塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007057"},{"id":"00007055","register_sub_id":"101","register_pk":"108037","name":"双葉館魚寅楼本館","kana":"ふたばかんうおとらろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県草津市草津二丁目字下御田伝532他","lat":35.015987,"lng":135.961029,"geo_status":"db","era":"昭和11頃／昭和63改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積243㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"25 － 0255","desc":"角地に建つ料亭建築で、２階に８０畳敷の大広間をもつ。建築面積２４３㎡、木造２階建、入母屋造桟瓦葺。通りに面する北側は、腰を竪板張、内法壁を赤色とし、料亭らしく仕上げる。南側は庭園に面し、２階に高欄付の縁をまわすなど、開放的なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007055"},{"id":"00006571","register_sub_id":"101","register_pk":"107554","name":"古川家住宅主屋","kana":"ふるかわけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県犬上郡豊郷町四十九院919","lat":35.207333,"lng":136.234329,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積142㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"25 － 0242","desc":"旧中山道に東面する敷地の北東寄りに建つ。油商の店舗兼住宅として建設。間口６間半，奥行６間半の妻入で，茅葺屋根を瓦形鉄板仮葺とする。元は南側に通り土間，床上部に２列６室型の居室を設け，表側を土間とする。街路から塀越しに見える入母屋屋根が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006571"},{"id":"00000297","register_sub_id":"101","register_pk":"101287","name":"本家鶴喜そば主屋","kana":"ほんけつるきそばしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本4-11-40","lat":35.07059813,"lng":135.87026601,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建，瓦葺，建築面積167㎡","structure_material":"木造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"25 － 0007","desc":"木造２階建，入母屋造，桟瓦葺の平入り町家である。２階の高欄や屋根の正面に取りつけた向拝風の屋根，千鳥破風の妻飾等に外観の特色がある。江戸時代中頃から続くそば屋の店舗として，坂本の町並みの入口にあって広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000297"},{"id":"00009032","register_sub_id":"101","register_pk":"162392","name":"豆信蔵","kana":"まめしんくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県大津市長等3-308","lat":35.01115747,"lng":135.85938233,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"25 － 0300","desc":"主屋後方に中庭を介して南北棟で建つ。桁行８．４ｍ梁間４．０ｍ、木造二階建、入母屋造妻入、桟瓦葺で、北妻を出入口として庇を付ける。外部は漆喰塗で、内部は一階を土間とし、二階は居室として西面に窓を開ける。料亭の附属建物の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009032"},{"id":"00009033","register_sub_id":"101","register_pk":"162393","name":"豆信門塀","kana":"まめしんもんへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市長等3-308","lat":35.01141513,"lng":135.85936002,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、瓦葺、総延長8.2m","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"25 － 0301","desc":"主屋玄関正面に構えた門を含み、敷地東南面に折曲がりに塀を廻らす。門は格子戸引分けとし、桟瓦葺の庇を葺下ろす。塀は、延長８．２ｍ、両下造桟瓦葺で、腰に高く竪板を張り、上部を漆喰塗りとする。主屋と調和が図られた外観が料亭らしい情緒を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009033"},{"id":"00009031","register_sub_id":"101","register_pk":"162391","name":"豆信料亭棟","kana":"まめしんりょうていとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県大津市長等3-308","lat":35.01135958,"lng":135.85929071,"geo_status":"db","era":"大正7年／昭和9年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"25 － 0299","desc":"大津旧市街地の角地に建ち、木造二階建、建築面積１７０㎡、入母屋造桟瓦葺である。一階正面は格子を建て、大広間のある二階の窓には高欄風の手摺を付けるほか、大小の格子窓を配して瀟洒な外観とする。往時の賑わいを伝える料亭建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009031"},{"id":"00000217","register_sub_id":"101","register_pk":"101207","name":"丸八百貨店","kana":"まるはちひゃっかてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県高島市朽木市場838・847","lat":35.35410302,"lng":135.91605615,"geo_status":"db","era":"昭和8頃／昭和18頃増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造3階建，スレート葺，建築面積83㎡","structure_material":"木造3階建","registered":"1997.06.12(平成9.06.12)","register_no":"25 － 0003","desc":"村の中心部の角地に建つ百貨店。もとは２階建で、３階は物見櫓等に利用するために増築された。人造石洗い出しの外壁の２階と３階の間の帯状に廻らされた鋸歯形の模様（当初のパラペット飾り）等に特徴があり、村でひときわ目をひく建物としてよく知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000217"},{"id":"00006153","register_sub_id":"101","register_pk":"107137","name":"八百久店舗兼主屋","kana":"やおきゅうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県草津市草津3-11-37","lat":35.014664,"lng":135.958054,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"25 － 0239","desc":"市中心部を貫く旧東海道に西面して建つ。桁行４間，梁間６間半，切妻造，平入で，正面を出桁造とする町家建築。棟通りをやや後退させて，２階の空間を確保しつつ，正面で軒高を抑え，格子窓や木瓜形虫籠窓を配するなど，町並みとの調和を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006153"},{"id":"00006145","register_sub_id":"101","register_pk":"107129","name":"吉川芳樹園店舗兼主屋","kana":"よしかわほうじゅてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県草津市草津2-7-33","lat":35.017372,"lng":135.960358,"geo_status":"db","era":"江戸末期／昭和50頃改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部3階建、瓦葺、建築面積158㎡","structure_material":"木造平屋一部3階建","registered":"2007.05.15(平成19.05.15)","register_no":"25 － 0238","desc":"市中心部を貫く旧東海道に西面して建つ。桁行５間半，梁間６間半規模で，平入とし，街路に面する南北棟切妻造の背面で棟が直交するＴ字形の屋根形式をもつ。正面に虫籠窓の意匠を残し，出桁等を漆喰で塗り込める。旧草津宿の歴史的景観を構成する町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006145"},{"id":"00000256","register_sub_id":"101","register_pk":"101246","name":"新井ビル","kana":"あらいびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区今橋2-1-1","lat":34.6907452,"lng":135.50638848,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建，建築面積254㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"1997.07.15(平成9.07.15)","register_no":"27 － 0021","desc":"鉄筋コンクリート４階建、１階正面の玄関部分は４本のドリス式オーダーを並べた重厚な外観になる。もと銀行店舗として建設されたもので、内部は中央が吹き抜けとなり２階周囲に個室を稗史階以上は事務室とする構成になる。設計河合浩蔵、施工清水組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000256"},{"id":"00016681","register_sub_id":"101","register_pk":"579165","name":"淡路町洋館（旧中井歯科商店）","kana":"あわじまちようかん（きゅうなかいしかしょうてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区淡路町三丁目48","lat":34.686849,"lng":135.501595,"geo_status":"db","era":"大正後期／昭和16年・令和7年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"鉄筋コンクリート造3階建、建築面積59㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2026.07.09(令和8.07.09)","register_no":"27 - 0972","desc":"淡路町の交差点に建つ旧歯科用品卸商の店舗。鉄筋コンクリート造3階建、外壁スクラッチタイル貼。額縁状に縁取った北東隅部は柱形を現し、一階を石張風、上階をクリーム色モルタル塗仕上とした対照的なつくりとする。角地を強調する独特な外観の事務所ビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016681"},{"id":"00004148","register_sub_id":"101","register_pk":"105138","name":"いけだピアまるセンター（旧池田実業銀行本店）","kana":"いけだぴあまるせんたー（きゅういけだじつぎょうぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府池田市新町2-14","lat":34.82716927,"lng":135.42400248,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積303㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0291","desc":"鉄筋コンクリート造２階建で，外部は基底部を石張風に仕上げ，隅部及び１，２階縦長上げ下げ窓間の狭い壁面を褐色タイル張とし，頂部をアーキトレイブ風につくる。銀行建築らしい重厚さと近代的感覚を合わせ持つ。設計は鉄道院出身で大阪で活躍した小笠原鈅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004148"},{"id":"00000222","register_sub_id":"101","register_pk":"101212","name":"生駒時計店","kana":"いこまとけいてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区平野町2-2-12","lat":34.687532,"lng":135.50635577,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造地上5階地下1階建塔屋付，建築面積176㎡","structure_material":"鉄筋コンクリート造地上5階地下1階建塔屋付","registered":"1997.06.12(平成9.06.12)","register_no":"27 － 0019","desc":"大阪市街地の角地に建つRC造、５階建の時計塔を持つビルで、設計は宗兵蔵である。外壁にスクラッチタイルを用いることや、窓の上下の縁で水平線を強調しつつバルコニーや出窓などに曲線や装飾を有効に配するデザインによく時代の特徴があわらわている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000222"},{"id":"00014870","register_sub_id":"101","register_pk":"519130","name":"立売堀ビルディング","kana":"いたちぼりびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西区立売堀一丁目24-1他","lat":34.680025,"lng":135.49668889,"geo_status":"db","era":"昭和3年／昭和中期改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積128㎡、塔屋付","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0897","desc":"四つ橋筋に東面するオフィスビル。鉄筋コンクリート造地上4階地下1階建で、外観は三層構成で柱形が垂直性を高め、柱頭にセセッション風レリーフを配す。内部は店舗を配す１階以外を中廊下式平面とする。大正後期に拡幅した四つ橋筋の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014870"},{"id":"00003566","register_sub_id":"101","register_pk":"104556","name":"稲束家住宅主屋","kana":"いなつかけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府池田市綾羽1-2466","lat":34.82675745,"lng":135.42602831,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積254㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"27 － 0259","desc":"近世の在郷町中心地を南北に通る街路に東面して建つ。間口５間半規模の切妻造，本瓦葺の平入つし２階建商家で，南方を下手とし，土間奥に角屋を出し，北西方に座敷棟を張り出す。正面はつし２階に大きな虫籠窓を開け，庇と２階壁面を北に延ばして表門をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003566"},{"id":"00001630","register_sub_id":"101","register_pk":"102620","name":"宇野薬局","kana":"うのやっきょく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区徳井町2-3-3","lat":34.68411204,"lng":135.51189162,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造3階建、瓦葺、建築面積58㎡","structure_material":"木造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0091","desc":"松屋町筋の角地に西面して建つ。木造３階建，タイル張の看板建築で，各階軒の水平線，３階側面の丸窓，パラペットに載せた緑色のスパニッシュ風瓦などに昭和初期の意匠傾向が認められる。設計は坂本建築事務所，施工は西成の長岡栄吉と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001630"},{"id":"00014054","register_sub_id":"101","register_pk":"508314","name":"大阪農林会館ビル","kana":"おうさかのうりんかいかんびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区南船場三丁目15-10他","lat":34.67689722,"lng":135.50310833,"geo_status":"db","era":"昭和5年／同24年以降改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造5階地下1階建、建築面積770㎡、塔屋付","structure_material":"鉄筋コンクリート造5階地下1階建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0830","desc":"南船場中心部の交差点に建つテナントビル。鉄筋コンクリート造地上五階地下一階建、外壁は一階石張、二階以上タイル張。南西隅に旧正面玄関、北東に玄関を設ける。内部は階段室やメールシュート、金庫室等に往時の意匠を見る。改変少なく地域景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014054"},{"id":"00003270","register_sub_id":"101","register_pk":"104260","name":"大阪ガスビルディング","kana":"おおさかがすびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区平野町4-1、4-2-1、4-3-1","lat":34.68795,"lng":135.500061,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上8階地下2階建、建築面積2253㎡","structure_material":"鉄骨鉄筋コンクリート造地上8階地下2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0215","desc":"御堂筋に面して建つ本社社屋。設計は安井武雄，施工は大林組。ＳＲＣ造，地上８階地下２階建で，外壁は１・２階を石材で黒くまとめ，上部は白色のタイル張。水平垂直の要素を取り混ぜた外観や内部にも質の高い意匠を持つ，過渡期的近代建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003270"},{"id":"00014871","register_sub_id":"101","register_pk":"519131","name":"大阪ガスビルディング北館","kana":"おおさかがすびるでぃんぐきたかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和後","pref":"大阪府","address":"大阪府大阪市中央区道修町四丁目29-1他","lat":34.68823889,"lng":135.50020278,"geo_status":"db","era":"昭和41年／平成18年改修","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上8階地下3階建、建築面積2，348㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造地上8階地下3階建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0898","desc":"御堂筋に面し、安井武雄設計の南館の北に建つ増築棟。鉄骨鉄筋コンクリート造地上8階地下3階建で、大胆に変更した柱割が新旧の区別と全体の調和を生み、各階庇の連続や同種外装材を用いて端正な南館の意匠を継承する。御堂筋の象徴的なオフィスビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014871"},{"id":"00003285","register_sub_id":"101","register_pk":"104275","name":"岡本家住宅主屋","kana":"おかもとけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町18-11","lat":34.450294,"lng":135.357727,"geo_status":"db","era":"江戸中期／天保12増築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積228㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0230","desc":"岡本家はト半役所西面の御下筋北端東側で醤油醸造業を営んだ有力町人。主屋は間口６間の平入り町家で，利齋家と同様綴葺の屋根を持つ。増築の角屋座敷に天保１２年の棟札があり，本体は１８世紀中期頃まで上ると見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003285"},{"id":"00007512","register_sub_id":"101","register_pk":"108494","name":"小川香料大阪支店社屋","kana":"おがわこうりょうおおさかしてんしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区平野町2-3-1他","lat":34.687836,"lng":135.50441,"geo_status":"db","era":"昭和5／昭和38増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造3階地下1階建、建築面積153㎡","structure_material":"鉄筋コンクリート造一部鉄骨造3階地下1階建","registered":"2009.01.08(平成21.01.08)","register_no":"27 － 0521","desc":"三休橋筋東側の街区に南面して建つ。建築面積１５３㎡、鉄筋コンクリート造、地上４階、地下１階建。円弧を用いた窓枠と窓庇を交差させた独特な意匠をみせ、玄関上部には八角形のステンドグラスをあしらうなど、全体をアールデコ様式でまとめた佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007512"},{"id":"00004145","register_sub_id":"101","register_pk":"105135","name":"奥山家住宅主屋","kana":"おくやまけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西淀川区姫島1-13-1、2","lat":34.702351,"lng":135.456558,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0288","desc":"燃料店を営んだ家の店舗兼住居で，表通りに南面して建つ。東から住居，店舗，倉庫を並べ，東端住居部分は２階建とする。各部で高さを変えたパラペットを立ち上げ陸屋根風に見せ，外壁はスクラッチタイル張とし，庇もコーニス状に造るなど洋風意匠に腐心する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004145"},{"id":"00014059","register_sub_id":"101","register_pk":"508319","name":"小野家住宅店舗兼主屋","kana":"おのけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府枚方市新町一丁目5-1","lat":34.81857222,"lng":135.649475,"geo_status":"db","era":"江戸末期／昭和前期・同41年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積206㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0835","desc":"枚方宿の旧京街道に西面する大規模町家。江戸時代は醤油屋を営み庄屋を務めた。切妻造桟瓦葺平入つし二階建、通り土間の北に二列六室、南に一列三室を配す。外観は揚見世や半蔀等の設備がよく残り、内部の座敷も改変が少ない。旧街道の景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014059"},{"id":"00014061","register_sub_id":"101","register_pk":"508321","name":"小野家住宅道具蔵","kana":"おのけじゅうたくどうぐぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府枚方市新町一丁目5-1","lat":34.8185,"lng":135.64958333,"geo_status":"db","era":"江戸末期／昭和35年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0837","desc":"主屋背面側の敷地南辺中央に建つ土蔵。切妻造桟瓦葺、北面に下屋庇を設ける。基礎は花崗岩切石、外壁は漆喰仕上で軒裏を波型に塗り込める。各階もとは一室だが、一階は階段室と区画して洋室に改修し、開口にガラス戸が建つ。二階は改変なく登り梁を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014061"},{"id":"00014060","register_sub_id":"101","register_pk":"508320","name":"小野家住宅離れ","kana":"おのけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府枚方市新町一丁目5-1","lat":34.81853611,"lng":135.64961111,"geo_status":"db","era":"江戸末期／平成25年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0836","desc":"主屋の東背面に中庭を挟んで建つ離れ。木造平屋建、中庭側の西面切妻造庇付、背面側入母屋造で桟瓦葺。内部は床を備えた八畳間一室だが現在は洋室とする。中庭側に廊下を通し、渡廊下で主屋と繋がる。主屋及び中庭と一体になって敷地内の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014060"},{"id":"00003290","register_sub_id":"101","register_pk":"104280","name":"尾食家住宅主屋","kana":"おめしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町38-19","lat":34.451691,"lng":135.358414,"geo_status":"db","era":"天保10","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造2階建、瓦葺、建築面積290㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0235","desc":"貝塚寺内町北側の入口に当たる上方口の西側に建つ。川沿いにあるためもともと台形平面で，町外からの見付となる北側は段違いに破風を構えた入母屋造とし，且つ昭和１６年の道路拡幅で前面南側を３角に切り取られているため複雑な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003290"},{"id":"00006185","register_sub_id":"101","register_pk":"107169","name":"貝塚市歴史展示館（旧ユニチカ株式会社貝塚工場事務所）","kana":"かいづかしれきしてんじかん（きゅうゆにちかかぶしきがいしゃかいづかこうじょうじむしょ）","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市半田138-1","lat":34.44186,"lng":135.370041,"geo_status":"db","era":"昭和10／昭和20増築・平成17改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積326㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"27 － 0419","desc":"ＪＲ東貝塚駅の北方に広がる旧ユニチカの敷地に南面して建つ。Ｌ字形平面，正面１９ｍの旧事務所部分の東側に，玄関ポーチ付建屋を増築したもので，全体に寄棟屋根を載せ，窓上下に水平材を廻らすことで外観を整える。紡績業で繁栄した近代大阪の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006185"},{"id":"00014639","register_sub_id":"101","register_pk":"515181","name":"鍵屋別棟","kana":"かぎやべつむね","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府枚方市堤町215他","lat":34.81196389,"lng":135.63703333,"geo_status":"db","era":"昭和3年／昭和8年頃増築、平成13年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積293㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0883","desc":"枚方宿に所在する料理旅館の別棟。東棟に玄関と二階客室、西棟に客室と二階大広間を持ち、廊下や階段で繋ぐ。地階には淀川からの船入石垣を残す。大広間はキングポスト・トラス小屋組で大空間を実現した折上格天井床構え付六三畳間で縁高欄越しに淀川を望む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014639"},{"id":"00001929","register_sub_id":"101","register_pk":"102919","name":"片桐棲龍堂西ノ蔵","kana":"かたぎりせいりゅうどうにしのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区西湊町3-1-16","lat":34.56754469,"lng":135.4640619,"geo_status":"db","era":"江戸後期／明治6移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0110","desc":"大阪市街日本橋から明治６年に移築された土蔵で，主屋の西方，アプローチ通路を隔てた位置に建つ。桁行３間，梁行４間，東西棟，切妻造，本瓦葺，妻入の比較的規模の大きな２階建土蔵で，現在は漢方資料館として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001929"},{"id":"00006699","register_sub_id":"101","register_pk":"107682","name":"交野市立教育文化会館（旧交野無尽金融株式会社本社屋）","kana":"かたのしりつきょういくぶんかかいかん（きゅうかたのむじんきんゆうかぶしきがいしゃほんしゃおく）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府交野市倉治6-9-21","lat":34.79632055,"lng":135.68990298,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積282㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0447","desc":"正面１９ｍ奥行１５ｍ規模、鉄筋コンクリート造２階建、スクラッチタイル貼の銀行建築で、大林組の設計施工になる。銀行建築には珍しくゴシック系のデザインを採り、営業室まわりにチューダーアーチを配し、パラペットに中世城郭風の狭間を廻らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006699"},{"id":"00016413","register_sub_id":"101","register_pk":"536480","name":"紙野家住宅主屋","kana":"かみのけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府貝塚市近木町1065-13","lat":34.44689167,"lng":135.35631944,"geo_status":"db","era":"昭和26年／平成5年頃改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階建、瓦葺、建築面積109㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"27 - 0952","desc":"南海貝塚駅の北西に位置し、通りに東面する旧遊郭。二階建切妻造桟瓦葺で正面中央の玄関に出節柱を立て、二階窓の腰に格狭間を飾る。玄関はタイル敷の土間で船底天井とし、北面に勘定台を備える。二階は六室の座敷を配し、細部まで凝ったつくりの遊郭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016413"},{"id":"00003684","register_sub_id":"101","register_pk":"104674","name":"河村商店（旧加島銀行池田支店）","kana":"かわむらしょうてん（きゅうかしまぎんこういけだしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府池田市栄本町3172-1","lat":34.8256989,"lng":135.42540714,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積330㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"27 － 0270","desc":"池田市の中心街にあって，能勢街道に面して建つ。設計は辰野片岡建築事務所。木造２階建であるが，石と赤煉瓦の外観で組積造風に見せる。窓上や柱型上部にやや抽象化された装飾を設け，正面西側部分はマンサード屋根の破風を設け，塔屋風に見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003684"},{"id":"00010006","register_sub_id":"101","register_pk":"196153","name":"川本家住宅倉庫","kana":"かわもとけじゅうたくそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府茨木市上泉町1167","lat":34.82326752,"lng":135.57183102,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"27 － 0582","desc":"店舗兼主屋の西奥に南北棟で建つ。木造平屋建、桁行八・〇メートル梁間五・〇メートル、切妻造鉄板葺である。外壁は軒下まで杉皮張とし、小屋は和小屋を組む。東西面に出入口を設け、店舗兼主屋からのトロッコレールを引き込む。商家の生業の様態を伝える倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010006"},{"id":"00010004","register_sub_id":"101","register_pk":"196151","name":"川本家住宅店舗兼主屋","kana":"かわもとけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府茨木市上泉町1167","lat":34.82327692,"lng":135.5720479,"geo_status":"db","era":"昭和3／平成17改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積182㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"27 － 0580","desc":"通りに東面する間口六間の町家で、二階正面を黒漆喰塗とし両端に袖壁を設ける。一階内部は前面を広いミセとして背面北寄りに座敷を配し、南寄りの通り土間に敷地奥の倉庫にのびるトロッコレールを残す。近世以来商工業の拠点として栄えた茨木の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010004"},{"id":"00010005","register_sub_id":"101","register_pk":"196152","name":"川本家住宅離れ","kana":"かわもとけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府茨木市上泉町1167","lat":34.82334408,"lng":135.57189859,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積55㎡、渡廊下付","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"27 － 0581","desc":"店舗兼主屋の後方に渡廊下を介して建つ。屋根はやや起りのある入母屋造で桟瓦葺とし、東西に八畳と六畳を並べて縁を廻らせる。八畳はトコの左右に違棚と琵琶棚を配し、幅広の付書院を設ける。六畳もトコ棚を備え、いずれも銘木などを多用し趣向を凝らせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010005"},{"id":"00000417","register_sub_id":"101","register_pk":"101407","name":"北浜レトロビルヂング（旧桂隆産業ビル）","kana":"きたはまれとろびるち゛んぐ（きゅうけいりゅうさんぎょうびる）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区北浜1-1-26","lat":34.69172372,"lng":135.50749623,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"煉瓦造地上2階地下1階建，建築面積56㎡","structure_material":"煉瓦造地上2階地下1階建","registered":"1997.12.12(平成9.12.12)","register_no":"27 － 0029","desc":"土佐堀通りに面して建つ小規模な煉瓦造建築。正面開口部は，花崗岩の切石を用いて縁取りし，玄関廻りを変形アーチを４本の柱型で受け，２階は大きく開く窓枠を置いてアクセントとする。近隣の洋風建築とも，金融の町北浜の往事の面影を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000417"},{"id":"00006009","register_sub_id":"101","register_pk":"106994","name":"ギャラリー再会","kana":"ぎゃらりーさいかい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市浪速区恵美須東1-4-16","lat":34.65273757,"lng":135.50686138,"geo_status":"db","era":"昭和28／平成9改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、スレート葺、建築面積97㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"27 － 0414","desc":"通天閣から放射状にのびる街路沿いに建つ。間口３間，奥行１０間で，中庭を介して店舗と住居を通路で繋ぐ伝統的町家形式を踏襲したつくり。独特の幾何学模様の破風飾り，ねじれ柱付のバルコニー，ガス灯風の照明など，舞台美術を思わせるファサードが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006009"},{"id":"00005287","register_sub_id":"101","register_pk":"106275","name":"旧和泉銀行本店（Ｃ．Ｔ．Ｌ．ＢＡＮＫ）","kana":"きゅういずみぎんこうほんてん（しー・てぃー・える・ばんく）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市北町14-3","lat":34.464527,"lng":135.373062,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積328㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0341","desc":"鉄筋コンクリート造２階建の銀行建築。外壁はタイル張で，隅部を石積風につくり，腰とコーニスにはテラコッタを張る。正面中央入口は２階分の半円アーチ窓を設け，キーストーンの位置にメダリオンを飾る。紀州街道に面して建ち，地域景観のシンボル的な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005287"},{"id":"00013423","register_sub_id":"101","register_pk":"368508","name":"旧十八屋（櫻館）主屋","kana":"きゅうじゅうはちや（さくらかん）おもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区桜之町西三丁4","lat":34.58981111,"lng":135.481125,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"27 － 0801","desc":"短冊形の敷地で、通りに西面して建つ。つし二階建の二軒長屋で、規模の異なる北棟と南棟からなる。共に南にトオリニワを配し、北に北棟は一列三室、南棟は一列二室の座敷を並べる。連続する一階の格子状の駒寄、二階の虫籠窓など、近世町家の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013423"},{"id":"00012580","register_sub_id":"101","register_pk":"367875","name":"旧丹治商会社屋","kana":"きゅうたんじしょうかいしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府堺市堺区永代町一丁7-1","lat":34.569778,"lng":135.473083,"geo_status":"geocoded","era":"明治後期／平成29年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造2階建、銅板葺、建築面積58㎡","structure_material":"煉瓦造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0753","desc":"市中心部の住宅地の一角に南面して建つ、もと煉瓦製造会社の社屋。煉瓦造二階建、外壁化粧煉瓦張で、四隅に柱形を表し、欠円アーチの縦長窓を並べ、アーチに沿って水切二段を設ける。コーニスに持送と歯飾を付し、背面に円窓を穿つなど瀟洒な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012580"},{"id":"00012581","register_sub_id":"101","register_pk":"367876","name":"旧丹治商会門及び煉瓦塀","kana":"きゅうたんじしょうかいれんがべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府堺市堺区永代町一丁7-1","lat":34.569778,"lng":135.473083,"geo_status":"geocoded","era":"明治後期／平成29年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"門 石造、間口2.1m 煉瓦塀 煉瓦造、総延長18m","structure_material":"門 石造","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0754","desc":"社屋入口正面に立つ石製門とその左右に延び前庭を区切る煉瓦塀。煉瓦塀の正面は煉瓦を千鳥に積んだ透塀で、要所を焼過煉瓦や役物で飾る。両側面は高さ４メートルの高塀で、外観を社屋と調和させる。煉瓦製造を営んだ会社らしく意匠性と堅牢性を兼ね備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012581"},{"id":"00014188","register_sub_id":"101","register_pk":"508818","name":"鴻池組旧本店洋館","kana":"こうのいけぐみきゅうほんてんようかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市此花区伝法四丁目63-1","lat":34.688725,"lng":135.45456667,"geo_status":"db","era":"明治43年／大正3年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、スレート葺、建築面積90㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0838","desc":"此花区伝法に北面する洋館。二階建寄棟造平入スレート葺で東に和館が接続。頂部の櫛形ペディメントに社章を掲げ、外壁はモルタル仕上に煉瓦タイル貼ボーダーを巡らす。内部二階応接室の内装は濃密なアール・ヌーヴォー意匠とし、時代の息吹を伝える洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014188"},{"id":"00014189","register_sub_id":"101","register_pk":"508819","name":"鴻池組旧本店和館","kana":"こうのいけぐみきゅうほんてんわかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市此花区伝法四丁目63-1","lat":34.688725,"lng":135.45468333,"geo_status":"db","era":"明治43年／昭和前期増築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0839","desc":"洋館東隣に建つ二階建切妻造平入桟瓦葺の和館。外観は重厚な町家で、両端に袖壁を立上げ、軒は出桁で持出し、垂木形に塗込める。内部は東を土間とした二列五室で、南庭に張出す二階座敷は意匠を凝らした数寄屋造。重厚な外観ながら繊細な内部意匠の和館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014189"},{"id":"00015205","register_sub_id":"101","register_pk":"530629","name":"後藤家住宅三階蔵","kana":"ごとうけじゅうたくさんがいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区大手通一丁目4","lat":34.68621389,"lng":135.51656389,"geo_status":"db","era":"明治44年／昭和32年移築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積33㎡","structure_material":"土蔵造3階建","registered":"2024.12.03(令和6.12.03)","register_no":"27 - 0938","desc":"大阪谷町筋で洋服製造販売及び卸売を営んだ商家の商品蔵兼家財蔵。寄棟造桟瓦葺、建ちの低い三階建の土蔵で外壁は白漆喰塗仕上、腰を竪板張とする。南面戸口に両開き土戸を吊り、各階窓に漆喰塗込の庇を付す。大阪の服飾業の発展を伝える貴重な三階建土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015205"},{"id":"00006291","register_sub_id":"101","register_pk":"107274","name":"小林新聞舗店舗兼住宅","kana":"こばやししんぶんほてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市平野区平野本町4-12-3","lat":34.6236,"lng":135.555084,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建及び木造平屋建、瓦葺、建築面積142㎡","structure_material":"鉄筋コンクリート造2階建及び木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"27 － 0423","desc":"商店街のアーケードに北面して建つ。ＲＣ造２階建の店舗の背後に木造平屋建の住居が接続する。正面中央西寄りに店舗入口，東端に住居の通り土間への戸口を開き，小庇を付ける。正面は柱形で４分割し，２階に２つずつ配したアーチ形の窓枠が外観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006291"},{"id":"00004381","register_sub_id":"101","register_pk":"105371","name":"西條合資会社旧店舗主屋","kana":"さいじょうごうしがいしゃきゅうてんぽしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市長野町13-11","lat":34.44926514,"lng":135.57043587,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積286㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0309","desc":"街路に北面して建つ造り酒屋。桁行１０間半梁間３間半のつし２階建で入母屋造，桟瓦葺とし，北と東に庇がつく。東半をミセドマ，西半を居室とし，南に吹抜の土間と座敷が突出する。正面は１階西寄りを出格子とし，塗籠の２階には虫籠窓を開き，出桁造とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004381"},{"id":"00004382","register_sub_id":"101","register_pk":"105372","name":"西條合資会社旧店舗土蔵","kana":"さいじょうごうしがいしゃきゅうてんぽどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市長野町13-11","lat":34.44916075,"lng":135.57042751,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積28㎡","structure_material":"土蔵造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0310","desc":"主屋の西に接続する土蔵造の平屋建である。桁行３間梁間２間の東西棟で，屋根を切妻造，桟瓦葺とする。切石の基礎上に建ち，外壁は白漆喰塗で，腰は縦羽目板張である。南側に両開土戸を釣込んだ戸口を設け，主屋から縁が接続する。北面には小庇付の窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004382"},{"id":"00005758","register_sub_id":"101","register_pk":"106746","name":"芝川ビルディング","kana":"しばかわびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区伏見町3-3-3","lat":34.689056,"lng":135.501831,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積349㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0382","desc":"御堂筋から東に入ったブロックの北西隅に建つ。鉄筋コンクリート造４階建地階付で，腰を竜山石，上部はスクラッチタイル貼とし，３階軒部にスパニッシュ瓦を葺く。設計は渋谷五郎と本間乙彦。古代マヤ・インカの細部装飾を採入れたアールデコ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005758"},{"id":"00001528","register_sub_id":"101","register_pk":"102518","name":"船場ビルディング","kana":"せんばびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区淡路町2-5-8","lat":34.68710787,"lng":135.5041779,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート地上5階地下1階建、建築面積717㎡","structure_material":"鉄筋コンクリート地上5階地下1階建","registered":"2000.02.15(平成12.02.15)","register_no":"27 － 0087","desc":"御堂筋近くに建つ鉄筋コンクリート造５階建の住宅兼事務所ビル。外観はタイル張オフィスビルの意匠になるが，内部中央に細長いパティオ風の中庭を設けて吹き抜けとし，その周囲各階に回廊を巡らす特色ある造りとする。設計は村上徹一の建築事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001528"},{"id":"00016680","register_sub_id":"101","register_pk":"579164","name":"天満屋ビル","kana":"てんまやびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市港区海岸通一丁目5-1","lat":34.652522,"lng":135.430086,"geo_status":"db","era":"昭和10年／昭和22年・平成11年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積151㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2026.07.09(令和8.07.09)","register_no":"27 - 0971","desc":"築港大道路に南面して建つ旧回漕業の事務所兼住宅。設計は小笠原祥光。鉄筋コンクリート造3階建、外壁はスクラッチタイル貼とする。南西隅にアールを付け、玄関脇の垂直壁、水平性を示す庇など幾何学的な意匠の外観で、昭和戦前の流行を伝える事務所ビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016680"},{"id":"00014053","register_sub_id":"101","register_pk":"508313","name":"丼池繊維会館","kana":"どぶいけせんいかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区久太郎町三丁目19","lat":34.68089167,"lng":135.50260833,"geo_status":"db","era":"大正11年／昭和30年以降改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積191㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0829","desc":"南船場丼池筋の交差点に建つ鉄筋コンクリート造地上三階地下一階建のテナントビル。外壁の二、三階はタイル張、隅を几帳面状に丸め深い軒下にデンティルを廻し窓間に装飾を付す。内部は改変が大きいが階段廻り等に当初の意匠が残る。地域の歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014053"},{"id":"00002153","register_sub_id":"101","register_pk":"103143","name":"中内眼科医院","kana":"なかうちがんかいいん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府富田林市富田林町146","lat":34.50038979,"lng":135.60339942,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積286㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2001.04.24(平成13.04.24)","register_no":"27 － 0134","desc":"富田林重伝建地区に近い堺町筋の角地に建つ。当初，国分銀行の本社屋として建設。ＲＣ造３階建で，隅部に玄関を設ける。１階壁面に大型の半円アーチ窓，２階に半円錐窓台付の上げ下げ窓を配す。町屋建築が多いこの地域で，近代的景観を際だたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002153"},{"id":"00008513","register_sub_id":"101","register_pk":"134909","name":"南海ビル","kana":"なんかいびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区難波5-12","lat":34.66469613,"lng":135.50104338,"geo_status":"db","era":"昭和7年／昭和32年・昭和55年・平成21年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄骨鉄筋コンクリート造7階一部8階地下2階建、建築面積5915㎡、装飾塔付","structure_material":"鉄骨鉄筋コンクリート造7階一部8階地下2階建","registered":"2011.01.26(平成23.01.26)","register_no":"27 － 0541","desc":"御堂筋南端に位置する南海難波駅のターミナルビル。ＳＲＣ造八階地下二階建。角を曲線で処理し、飾り壺を戴くコリント式の壁付円柱とアーチの連続で壁面を構成する。エントランス上部や屋上の装飾塔など随所に装飾が配され、華やかで格調高い外観を実現する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008513"},{"id":"00003464","register_sub_id":"101","register_pk":"104454","name":"南天苑本館","kana":"なんてんえんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府河内長野市天見158","lat":34.397423,"lng":135.594589,"geo_status":"db","era":"大正2／昭和10移築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積608㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0257","desc":"Ｌ字型平面の木造２階建，桟瓦葺，入母屋造の料理旅館建築。大正２年に堺市に建設され，昭和１０年に現在地に移築されている。設計は辰野片岡事務所による。内部は客室を中心とし，１階東南隅には大広間を設ける。近代の大規模和風建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003464"},{"id":"00014055","register_sub_id":"101","register_pk":"508315","name":"原田産業大阪本社ビル","kana":"はらださんぎょうおおさかほんしゃびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区南船場二丁目9","lat":34.67693889,"lng":135.50371944,"geo_status":"db","era":"昭和3年／同40年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積143㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0831","desc":"南船場の中心部に建つ鉄筋コンクリート造二階建の商社本社ビル。古典様式をアレンジした特徴的な外観は石張とモルタル洗出仕上。内部は階段室の吹抜両脇に部屋を配し、内装に日華石やオーク材等良質な材を用いる。小規模だが豊かな空間構成の近代ビル建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014055"},{"id":"00012218","register_sub_id":"101","register_pk":"353018","name":"播谷商店主屋","kana":"はりたにしょうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町一丁目53-1","lat":34.633791,"lng":135.513644,"geo_status":"db","era":"昭和4年頃／平成27年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"27-713","desc":"第二次市域拡張で大阪市に編入された地に建つ。主屋は南北棟の広間棟の左右に東西棟の玄関棟、仏間棟が連なる構成で、それぞれ入母屋造、切妻造、寄棟造とする。広間棟の座敷八畳は東・南面を庭に向かって開く。意匠を凝らした中廊下式の近代和風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012218"},{"id":"00012219","register_sub_id":"101","register_pk":"353019","name":"播谷商店店舗","kana":"はりたにしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町一丁目53-1","lat":34.633757,"lng":135.513474,"geo_status":"db","era":"昭和4年頃／昭和50年代後半改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"27-714","desc":"敷地の南西隅に建ち、二方を街路に面する質屋店舗。南北棟の起り屋根を桟瓦で葺き、腰部を花崗岩貼、窓には格子を入れ、二階壁面は黒色タイル貼で軒まで黒漆喰で塗込める。内部は南西端に二方向に入口を持つ土間とする。堅牢さを表現した店舗建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012219"},{"id":"00012220","register_sub_id":"101","register_pk":"353020","name":"播谷商店土蔵","kana":"はりたにしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町一丁目53-1","lat":34.633834,"lng":135.513494,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"27-715","desc":"店舗の北側に建ち、南面庇で蔵前として接する。建築面積五六平方メートル、東西棟の土蔵造二階建、切妻造桟瓦葺で、外壁は腰花崗岩板貼、一階部分竪板張で、上部は軒まで白漆喰で塗込める。質屋店舗に欠かせない土蔵で、地域の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012220"},{"id":"00012221","register_sub_id":"101","register_pk":"353021","name":"播谷商店門及び塀","kana":"はりたにしょうてんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町一丁目53-1","lat":34.63367667,"lng":135.51378468,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"門 木造、瓦葺一部銅板葺、間口3.8m 塀 コンクリート造、総延長41m","structure_material":"門 木造","registered":"2018.03.27(平成30.03.27)","register_no":"27-716","desc":"敷地南面に門を開き、東面へ矩折れに塀を設ける。塀は石積基壇の上にコンクリート塀を立ち上げ、約三メートル間隔に柱型を設け、上部の桁状部分を支え、その上に低い板塀を立てるなど、意匠性に富み地域の歴史的景観に寄与する門と塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012221"},{"id":"00013143","register_sub_id":"101","register_pk":"368388","name":"針中野中野鍼裏門","kana":"はりなかのなかのはりうらもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.61840833,"lng":135.53513333,"geo_status":"db","era":"昭和13年頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造、銅瓦葺、間口2.3m、西方潜戸付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0785","desc":"敷地北辺東隅に北面して建ち、庭園に続く経路に開く門。表門に類似した特異な形式の一間一戸、脇戸付。屋根に銅瓦を用い、小壁に筬欄間、背面側天井を格天井とするなど相違点はあるが、表門に比肩する堂々としたつくりで、北東隅の敷地景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013143"},{"id":"00013142","register_sub_id":"101","register_pk":"368387","name":"針中野中野鍼表門","kana":"はりなかのなかのはりおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.6182,"lng":135.53475,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造、瓦葺、間口2.2m、東方潜戸付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0784","desc":"旧応接処と文書蔵の間に南面して建つ。高塀に切妻屋根が突出したような特異な形式の一間一戸、脇戸付の門。親柱上に肘木を十字に組み、前後に延びる桁を載せて梁で繋ぐ。背面は屋根を葺下ろし、鏡天井を張る。歴史ある当院に相応しい堂々とした門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013142"},{"id":"00013138","register_sub_id":"101","register_pk":"368383","name":"針中野中野鍼旧応接処","kana":"はりなかのなかのはりきゅうおうせつしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.61823889,"lng":135.5347,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造一部土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"木造一部土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0780","desc":"鍼の処の南西に接続し、東面して建つもと賓客用施設。木造一部土蔵造二階建、本瓦葺で、東面北側に入母屋玄関を付す。外壁は真壁漆喰塗で腰を竪板張とするが、南面は漆喰を軒裏まで塗込めて土蔵造風に仕上げる。並び建つ土蔵と調和した街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013138"},{"id":"00013139","register_sub_id":"101","register_pk":"368384","name":"針中野中野鍼主屋","kana":"はりなかのなかのはりしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.61835,"lng":135.53491111,"geo_status":"db","era":"明治43年／昭和13年頃増築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0781","desc":"敷地北辺中央に北面して建つ入母屋造桟瓦葺で、四周に下屋を廻し、東面に便所と新館が突出する。外壁は軒裏まで漆喰で塗込めて虫籠窓を穿ち、腰に竪板を張る。内部は西を土間、東を居室とし、病室用の新館は床を設けた上質なつくり。屋敷構の中核を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013139"},{"id":"00013137","register_sub_id":"101","register_pk":"368382","name":"針中野中野鍼鍼の処","kana":"はりなかのなかのはりはりのところ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.61832778,"lng":135.53473611,"geo_status":"db","era":"江戸末期／明治43年・平成15年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、金属板葺、建築面積102㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0779","desc":"針中野に位置する鍼灸院。敷地北西に北面して建つ。大和棟風で、正背面に下屋を付す。外壁は漆喰塗で、腰を竪板張とする。内部は東に通り土間、西に二列四室を配し、その南を旧応接処に繋がる縁とする。江戸末期の街路景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013137"},{"id":"00013141","register_sub_id":"101","register_pk":"368386","name":"針中野中野鍼物置蔵","kana":"はりなかのなかのはりものおきくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.61820278,"lng":135.53485556,"geo_status":"db","era":"明治43年／平成7年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0783","desc":"文書蔵の東に東面して建つ。土蔵造二階建、東西棟の金属板葺で、外壁は漆喰塗で軒裏を壁面より張り出して塗込め、腰を竪板張とする。内部は上下階とも一室で、壁を漆喰で仕上げ、和小屋組とする。妻を見せる建物が並ぶ敷地南辺の景観に変化を加えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013141"},{"id":"00013140","register_sub_id":"101","register_pk":"368385","name":"針中野中野鍼文書蔵","kana":"はりなかのなかのはりもんじょくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.618225,"lng":135.5348,"geo_status":"db","era":"明治35年／平成7年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0782","desc":"敷地南辺中央に北面して建つ。土蔵造桟瓦葺で、外壁は漆喰で軒裏まで塗込めて鉢巻一段を廻し、腰を竪板張とする。内部は一階を前後二室に分け、二階は一室とする。和小屋組とし、棟から桁にかけて野地板を流板に張る。表門回りの景観を重厚に演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013140"},{"id":"00003456","register_sub_id":"101","register_pk":"104446","name":"廣海家住宅主屋","kana":"ひろうみけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市西町５６９他","lat":34.44891859,"lng":135.35450793,"geo_status":"db","era":"文久元","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積641㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0249","desc":"回船問屋の本宅。旧海岸沿いに広大な敷地を構える。主屋は間口１８間半の長大な町家で，桁行９間，梁間６間の中央部の両側にそれぞれ梁間４間の店(桁行５間)と座敷部(桁行４間半)を並べた平面。店部分を除き改造は少ない。ニワの梁組は豪壮で見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003456"},{"id":"00014056","register_sub_id":"101","register_pk":"508316","name":"フジカワビル","kana":"ふじかわびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市中央区瓦町一丁目7-1","lat":34.685825,"lng":135.50674444,"geo_status":"db","era":"昭和28年／同44年・平成28年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄筋コンクリート造5階地下1階建、建築面積153㎡","structure_material":"鉄筋コンクリート造5階地下1階建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0832","desc":"堺筋に西面して建つ鉄筋コンクリート造地上五階地下一階建オフィスビル。二～四階正面を内窓付ガラスブロック積とし、両脇に小バルコニーを設けて陰影を演出。機能的な平面計画や階段等の随所に村野による繊細な意匠を凝らす。小規模だが都市部の景観に寄与。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014056"},{"id":"00002798","register_sub_id":"101","register_pk":"103788","name":"伏見ビル","kana":"ふしみびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区伏見町2-21-1","lat":34.688988,"lng":135.505737,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造3階一部4階建、建築面積198㎡","structure_material":"鉄筋コンクリート造3階一部4階建","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0178","desc":"大阪船場の中心部にある鉄筋コンクリート造３階建のビル。設計は辰野片岡事務所出身の長田岩次郎。角地に建ち，外観はコーナーを隅丸とし，３階の窓上に飾り丸窓，交差点に面する北西隅の２，３階に水平リブ状の飾り線を付けるなど変化に富んだ外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002798"},{"id":"00000300","register_sub_id":"101","register_pk":"101290","name":"三木楽器","kana":"みきがっき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区北久宝寺町3-3-4","lat":34.67988285,"lng":135.50166257,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建，建築面積468㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"1997.09.03(平成9.09.03)","register_no":"27 － 0023","desc":"鉄筋コンクリート造，地上４階地下１階建の楽器店。設計は増田建築事務所，施工は鴻池組で，ドイツの楽器店を模したと伝える。大正期の都市部における中層商業ビルの好例で，外壁をタイル張りとして縦の線を強調した外観によく時代の特徴があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000300"},{"id":"00014872","register_sub_id":"101","register_pk":"519132","name":"御堂ビルディング","kana":"みどうびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市中央区本町四丁目27-12他","lat":34.68408056,"lng":135.50016667,"geo_status":"db","era":"昭和40年","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上9階地下4階建、建築面積3，442㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造地上9階地下4階建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0899","desc":"御堂筋と本町通の交差点角に建つオフィスビル。設計は竹中工務店設計部。センターコアを採用し、フルウェブ梁や軽量コンクリートなど当時の技術を駆使し大スパン構造を実現。単窓を繰返した壁面に茶、灰、土の３色の磁器タイル貼で格調高い外観に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014872"},{"id":"00001435","register_sub_id":"101","register_pk":"102425","name":"ミナミ株式会社（旧川崎貯蓄銀行福島出張所）","kana":"みなみかぶしきがいしゃ（きゅうかわさきちょちくぎんこうふくしましゅっちょうじょ）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市福島区福島5-17-7","lat":34.695042,"lng":135.484879,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート地上2階地下1階建、建築面積206㎡","structure_material":"鉄筋コンクリート地上2階地下1階建","registered":"1999.11.18(平成11.11.18)","register_no":"27 － 0079","desc":"川崎銀行系の建築を数多く手がけた矢部又吉の設計による小品。正面に４本のフルーティング付きイオニア式ジャイアント・オーダーを配し，端部を角型ピラスターで納める。敷地形状に対応してファサードに緩やかな凸曲面状のカーブを付けている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001435"},{"id":"00007398","register_sub_id":"101","register_pk":"108380","name":"八木家住宅主屋","kana":"やぎけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市三日市町1109","lat":34.437973,"lng":135.570343,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積134㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0519","desc":"高野街道に西面して建つ。間口８間半規模の平入町家で、切妻造桟瓦葺とし、正面に本瓦葺の深い軒を付ける。中央南寄りに大戸口を開く。内部は南半部を土間のニワなどとし、北半部にザシキやミセなどを配した。旧三日市宿にあって町家の伝統様式をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007398"},{"id":"00007399","register_sub_id":"101","register_pk":"108381","name":"八木家住宅土蔵","kana":"やぎけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市三日市町1109","lat":34.4380584,"lng":135.57030326,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0520","desc":"主屋の北側に建ち、通りに妻を見せる。切妻造本瓦葺の土蔵造２階建。外壁は白漆喰仕上げとし、腰に杉の焼板を張る。通り側の妻には窓を各階に開け、銅板の扉を吊り、下階の窓には漆喰仕上げの庇を付ける。主屋とともに旧宿場町の街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007399"},{"id":"00001720","register_sub_id":"101","register_pk":"102710","name":"山内ビル","kana":"やまうちびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西区土佐堀1-1-5","lat":34.69242414,"lng":135.49561934,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造地上4階地下1階建、建築面積75㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0092","desc":"法律事務所として建設された事務所建築で外壁は褐色タイル貼り。一階東端の入口を花崗岩で縁取り二階の窓台装飾を垂らしてアーチの中心飾りとする。一階中央及び西にも同様なデザインの窓を設け二・三階の縦長窓の縦枠を一階から連続させて縦の線を強調する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001720"},{"id":"00003453","register_sub_id":"101","register_pk":"104443","name":"吉村家住宅主屋","kana":"よしむらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市西町12-7","lat":34.44886328,"lng":135.3552178,"geo_status":"db","era":"江戸中期／江戸末期増築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積460㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0246","desc":"江戸時代油屋，金融業を営んだ商家。主屋の北側主要部は古く，１８世紀中頃まで遡ると見られる。貝塚では町家の座敷は上手側背後に増築されるのが通例であるが，ここでは幕末期に下手側（南側）に増築されているのが珍しい。増築座敷の意匠も優秀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003453"},{"id":"00003282","register_sub_id":"101","register_pk":"104272","name":"利齋家住宅主屋","kana":"りさいけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町18-3","lat":34.44984707,"lng":135.35744593,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積253㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0227","desc":"利齋家はト半役所北側の角地で薬種を商った貝塚寺内町の有力町人である。主屋は比較的梁間が狭く，切妻造の屋根は棟を挟んだ３間を一段高く綴葺とするが小屋は一連の登梁で段差とは関係がない。１７世紀まで遡る可能性があるが，それだけに後の改造も大きい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003282"},{"id":"00003284","register_sub_id":"101","register_pk":"104274","name":"利齋家住宅土蔵","kana":"りさいけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町18-3","lat":34.44997,"lng":135.357407,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積127㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0229","desc":"主屋西側に接して建てられた２階建の袖蔵。梁間は２間と標準的であるが，桁行は１０間の長大な蔵で，内部は南北５間の２室に区切られ，南半を薬種，北半を衣装や道具の倉庫に使われていた。主屋と同様，兵庫県南部地震後本瓦から桟瓦に葺き替えられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003284"},{"id":"00011350","register_sub_id":"101","register_pk":"209187","name":"リバーサイドビルディング","kana":"りばーさいどびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市北区中之島三丁目45他","lat":34.691798,"lng":135.493279,"geo_status":"db","era":"昭和40","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"鉄筋コンクリート造5階地下1階建、建築面積175㎡、塔屋付","structure_material":"鉄筋コンクリート造5階地下1階建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0648","desc":"土佐堀川に面して建つ横長平面の事務所建築。設計は岸田日出刀。高速道路の構造を引用したと伝え、構造壁を集約し、正背面に全長分の窓を配する明快な構成とする。妻壁は淡陶タイルでモザイク状に飾る。インターナショナルスタイルの事務所建築の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011350"},{"id":"00013615","register_sub_id":"101","register_pk":"504986","name":"今村家住宅貸店舗","kana":"いまむらけじゅうたくかしてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県丹波篠山市西町字柚ノ木64-4他","lat":35.07525556,"lng":135.21049444,"geo_status":"db","era":"昭和8年／平成21年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"28 － 0745","desc":"陶々菴南側の道路拡幅に伴う隅切地に建つ。正方形の一角を落とした五角形平面の平屋に、Ｌ字形で入母屋造の二階を載せ、外壁は真壁造漆喰塗とする。内部は一階店舗は道路側に広く開口をとり、二階は座敷とする。特異な外観が伝統的な町並に変化を加える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013615"},{"id":"00010016","register_sub_id":"101","register_pk":"196163","name":"魚橋呉服店北土蔵","kana":"うおはしごふくてんきたどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市威徳寺町51-1","lat":34.84888121,"lng":134.70397637,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0581","desc":"店舗兼主屋の東後方に建ち、土蔵造二階建、桁行八・三メートル梁間三・九メートル、切妻造本瓦葺である。平面は南北二室に分かれ、双方に戸口を設けて庇を付ける。外壁漆喰塗で鉢巻を廻らし、腰に竪板や割竹を詰打ちとする。南土蔵とともに屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010016"},{"id":"00010014","register_sub_id":"101","register_pk":"196161","name":"魚橋呉服店店舗兼主屋","kana":"うおはしごふくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市威徳寺町51-1","lat":34.84895468,"lng":134.70381699,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積147㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0579","desc":"野里街道に西面する二階建町家で南主屋と並び建つ。正面二階は出桁造で軒蛇腹まで塗込め、ガラス窓を設ける。前寄りを土間のミセと畳敷のミセノマとして格天井を張り、中央はもと吹抜で二階に高欄を残す。商工業で栄えた野里の街並を伝える大型の商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010014"},{"id":"00010015","register_sub_id":"101","register_pk":"196162","name":"魚橋呉服店南主屋","kana":"うおはしごふくてんみなみしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市威徳寺町50","lat":34.84887898,"lng":134.70376804,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、瓦葺、建築面積132㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0580","desc":"北隣に接する店舗兼主屋より軒が低く、本瓦を葺く。正面二階は出桁造で、垂木まで塗込め、虫籠窓を並べる。一階南寄りに土間を通し、手前に車庫、奥にナカノマを配し、坪庭を挟んで後方に離れ座敷を接続する。店舗兼主屋とともに野里の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010015"},{"id":"00010017","register_sub_id":"101","register_pk":"196164","name":"魚橋呉服店南土蔵","kana":"うおはしごふくてんみなみどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市威徳寺町50","lat":34.84881409,"lng":134.7039292,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0582","desc":"南主屋の東後方に南北棟で建つ。土蔵造二階建、桁行四・六メートル梁間三・三メートル、切妻造本瓦葺で、南端に漬物蔵を附属する。外壁漆喰塗で腰を海鼠壁とする。西面南寄りの戸口に掛子塗の扉を開いて庇を付し、直上にも窓を穿つ。家財を収めた土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010017"},{"id":"00000999","register_sub_id":"101","register_pk":"101989","name":"海岸ビル","kana":"かいがんびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市中央区海岸通３","lat":34.686574,"lng":135.19066183,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上４階建，５階以上部分を除く，建築面積1185㎡","structure_material":"鉄筋コンクリート造地下１階地上４階建","registered":"1998.12.11(平成10.12.11)","register_no":"28 － 0039","desc":"旧神戸居留地バンド（海岸通り）を代表する建造物。三井物産神戸支店ビルとして建てられた。設計は河合浩蔵。鉄筋コンクリート造４階建のオフィスビルで，ルネサンス様式の骨格にセセッションの細部が随所に採り入れられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000999"},{"id":"00003465","register_sub_id":"101","register_pk":"104455","name":"海岸ビルヂング","kana":"かいがんびるぢんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市中央区海岸通3-1-5","lat":34.685947,"lng":135.186859,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"煉瓦造3階建、建築面積682㎡","structure_material":"煉瓦造3階建","registered":"2003.07.01(平成15.07.01)","register_no":"28 － 0122","desc":"煉瓦造３階建の事務所建築で，設計は河合浩蔵，施工は旗手組。戦災により内装のかなりの部分と外部装飾の一部を失っているが，唐破風状の曲線を取り入れるなど独特の細部意匠が特徴である。現在では店舗，事務所，ギャラリーなどとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003465"},{"id":"00016563","register_sub_id":"101","register_pk":"574925","name":"旧尾上家住宅（小倉屋）主屋","kana":"きゅうおのえけじゅうたく（こくらや）てんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市堺町30","lat":34.83817194,"lng":134.70058,"geo_status":"db","era":"寛政7年（1795）／大正前期・昭和後期・令和6年改修","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積142㎡","structure_material":"木造平屋一部2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0850","desc":"野里街道に西面する旧金物商の主屋。つし二階建切妻造平入本瓦葺で棟高を南北で違え、南棟に煙出を載せる。北に2列の部屋を並べ、南は広い通り土間とする。外壁漆喰塗で三箇所の虫籠窓を開け、建ちの低い表構えが近世姫路城下町の様相を伝える貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016563"},{"id":"00013845","register_sub_id":"101","register_pk":"507804","name":"旧駿河屋","kana":"きゅうするがや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県神戸市北区有馬町字有馬830","lat":34.79699444,"lng":135.24748333,"geo_status":"db","era":"大正15年／令和2年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積42㎡","structure_material":"木造3階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0748","desc":"有馬温泉にある元竹細工の工房で、湯本坂に北面して建つ。木造三階建で、元は一階は工房、二階は住居、三階は床付座敷で湯治客の貸間とした。外壁は杉皮張で化粧垂木に杉丸太を用い、北側座敷は北西面に広く開口をとる。戦前の湯本坂界隈の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013845"},{"id":"00011773","register_sub_id":"101","register_pk":"210789","name":"旧高砂銀行本店（高砂商工会議所会館）","kana":"きゅうたかさごぎんこうほんてん（たかさごしょうこうかいぎしょかいかん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県高砂市高砂町字北本町1104他","lat":34.746596,"lng":134.802323,"geo_status":"db","era":"昭和7年／昭和55年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積300㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0660","desc":"本町通りに面して建つ銀行建築。鉄筋コンクリート造二階建で、正面中央を出入口とし、両脇にイオニア式オーダーの柱を立て、頂部にパルメット文様、持送りを並べたエンタブレチュアを廻らすなど外観は古典主義様式に倣い、当時の小規模銀行建築の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011773"},{"id":"00011774","register_sub_id":"101","register_pk":"210790","name":"旧高砂通運本社屋","kana":"きゅうたかさごつううんほんしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県高砂市高砂町字鍛冶屋町1396","lat":34.747823,"lng":134.801196,"geo_status":"db","era":"昭和14年／平成27年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積53㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0661","desc":"商店街の角地に建つ事務所建築。木造二階建で通りに面した外壁を煉瓦積スクラッチタイル貼とする。屋根は緩勾配の寄棟造鉄板葺。平坦な壁面、壁頂部の水平ライン、矩形の開口部を各面に設けるなどモダニズム建築に通ずる外観意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011774"},{"id":"00013844","register_sub_id":"101","register_pk":"507803","name":"旧摩耶観光ホテル","kana":"きゅうまやかんこうほてる","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区畑原字ノタ山344","lat":34.72763056,"lng":135.21277222,"geo_status":"db","era":"昭和5年／昭和36年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階地下2階建、陸屋根、建築面積901㎡","structure_material":"鉄筋コンクリート造2階地下2階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0747","desc":"摩耶山南麓中腹に建つ。鉄筋コンクリート造Ｌ字形平面の四層各階に水平庇を廻らして曲面を強調し、大きな開口を開ける。内部の大ホールや大食堂は、大梁と柱形で大空間を分節し、舞台等にアールデコ調意匠をみせる。かつての山上リゾート施設の有様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013844"},{"id":"00011990","register_sub_id":"101","register_pk":"354926","name":"旧大和屋旅館","kana":"きゅうやまとやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字中409","lat":35.626036,"lng":134.808864,"geo_status":"db","era":"昭和2年／昭和40年頃改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造3階建、瓦葺、建築面積59㎡","structure_material":"木造3階建","registered":"2017.10.27(平成29.10.27)","register_no":"28-672","desc":"湯の里通りに北面する木造三階建の旅館。間口三間、切妻造とし、二、三階正面側は床の間、床脇、付書院を備えた客室で、建具や欄間に繊細な意匠を見せる。正面に縁を廻らし、ガラス戸を建て、内に高欄を設けた外観が、温泉街の街路景観を良好に形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011990"},{"id":"00004178","register_sub_id":"101","register_pk":"105168","name":"日下旅館","kana":"くさかりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷1958","lat":35.16335762,"lng":134.78944091,"geo_status":"db","era":"明治43／大正10増築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建一部3階建、瓦葺、建築面積539㎡","structure_material":"木造2階建一部3階建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0173","desc":"ＪＲ生野駅前に建つ旅館建築。南を正面とする木造２階建で，口の字型に近い平面とし，南東部の３階建が大正の増築で，２階・３階には数寄屋風の座敷を配している。縁側の高欄や軒廻り小壁の鶴や雲を象った下地窓などに，和風旅館らしい造形要素がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004178"},{"id":"00010216","register_sub_id":"101","register_pk":"198049","name":"神戸ゴルフ倶楽部クラブハウス","kana":"こうべごるふくらぶくらぶはうす","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲山町一ケ谷1-3","lat":34.75839,"lng":135.238059,"geo_status":"db","era":"昭和7／昭和29・昭和59改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積457㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"28 － 0595","desc":"日本最古のゴルフ場に建つクラブハウス。外観は下見板張の外壁に白色の上下窓や扉を並べ、内部はタイル貼の暖炉の東西に食堂や休憩室を、背面側にロッカー室を配する。内壁に高い腰パネルを張り、天井は化粧梁形を見せて板張とするなど洗練された意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010216"},{"id":"00010217","register_sub_id":"101","register_pk":"198050","name":"神戸ゴルフ倶楽部チェンバー","kana":"こうべごるふくらぶちぇんばー","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県神戸市灘区六甲山町北六甲4561-1他","lat":34.75994521,"lng":135.23688068,"geo_status":"db","era":"大正13／昭和28・昭和49改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積396㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"28 － 0596","desc":"大阪の青年実業家の社交場として建設された「サースディ倶楽部」を取得し、改修した宿泊施設。横長の建物で南面中央に玄関を配し、ロビーを介して東半を中廊下と宿泊室に間仕切り、西半を食堂や休憩室とする。屋根勾配を抑えた建ちの低い外観が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010217"},{"id":"00000706","register_sub_id":"101","register_pk":"101696","name":"神戸市立博物館（旧横浜正金銀行神戸支店）","kana":"こうべしりつはくぶつかん（きゅうよこはましょうきんぎんこうこうべしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区京町24","lat":34.68726356,"lng":135.19307519,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造地上５階地下１階建，建築面積1775㎡","structure_material":"鉄筋コンクリート造一部鉄骨造地上５階地下１階建","registered":"1998.09.02(平成10.09.02)","register_no":"28 － 0026","desc":"正面に６本のドリス式の半円柱が建つ古典主義様式の建築。英国王立建築家協会会員桜井小太郎の設計になる。内部は博物館として改修されたが，二階吹き抜けの旧銀行業務室は大ホールとして天井とも保存された。神戸における様式建築の最後期の作品でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000706"},{"id":"00010322","register_sub_id":"101","register_pk":"199095","name":"神戸ポートタワー","kana":"こうべぽーとたわー","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県神戸市中央区波止場町7他","lat":34.682645,"lng":135.186723,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄骨造及び鉄筋コンクリート造、高さ108m、面積479㎡、展望室付","structure_material":"鉄骨造及び鉄筋コンクリート造","registered":"2014.12.19(平成26.12.19)","register_no":"28-0601","desc":"国際的貿易港である神戸港全体を眺望する中突堤を選び、港湾博物館施設として建設された。我が国で初の鋼管パイプフレーム構造で、直線材で曲面を構成した優美なつづみ形は今日でも斬新な意匠といえる。港神戸の象徴的な存在として、今なお広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010322"},{"id":"00013847","register_sub_id":"101","register_pk":"507806","name":"御所坊新館","kana":"ごしょぼうしんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県神戸市北区有馬町字有馬853","lat":34.79673889,"lng":135.24729722,"geo_status":"db","era":"昭和30年頃／昭和36年増築","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造及び鉄筋コンクリート造2階地下1階建、瓦葺一部銅板葺、建築面積351㎡","structure_material":"木造及び鉄筋コンクリート造2階地下1階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0750","desc":"本館の南斜面の上部に位置し、木造三階建部分と、鉄筋コンクリート造一層に木造二層分をのせる混構造部分からなる。外観は本館と同様モルタル吹付仕上で屋根は桟瓦葺。内装は和室を含め水平線や垂直線を重視した幾何学的な意匠で統一。敷地中程の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013847"},{"id":"00013848","register_sub_id":"101","register_pk":"507807","name":"御所坊土蔵","kana":"ごしょぼうどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市北区有馬町字有馬836-1","lat":34.79666944,"lng":135.24755,"geo_status":"db","era":"明治23年／昭和60年頃改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0751","desc":"本館及び新館とは道を挟んで南側の隣接地に位置する。土蔵造二階建切妻造妻入桟瓦葺。漆喰を鉢巻まで塗込め、腰壁を海鼠壁とする。内部は一室で一部吹抜。元は茶室付属の土蔵で茶道具や漆器を収納した。外観は当初を踏襲し、明治の温泉街の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013848"},{"id":"00013846","register_sub_id":"101","register_pk":"507805","name":"御所坊本館","kana":"ごしょぼうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神戸市北区有馬町字有馬859他","lat":34.79676667,"lng":135.24695556,"geo_status":"db","era":"明治後期／昭和6年増築、昭和30年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造3階建、瓦葺、建築面積527㎡","structure_material":"木造3階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0749","desc":"有馬温泉街の中心、滝川沿いに位置する。木造三階建桟瓦葺で、玄関のある東面は切妻造、その西にやや屈曲して入母屋造の昭和増築部が接続する。外壁は吹付仕上と真壁造漆喰仕上一部板張が混在。川沿いの眺望良好地に好んで建てられた旅館別館の姿を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013846"},{"id":"00010850","register_sub_id":"101","register_pk":"201685","name":"小林屋旅館","kana":"こばやしやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕369","lat":35.625446,"lng":134.810065,"geo_status":"db","era":"昭和前期／昭和中期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階一部3階建、瓦葺、建築面積472㎡","structure_material":"木造2階一部3階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0620","desc":"川沿いの通りに面して建つ木造三階建旅館で、正面二階に客室、三階に広間を配し、開口を広め、庇を廻らせる。奥行の長い平面で最奥の二階建も客室とし、中間部に採光用の中庭と、小さめの内湯のみを設ける平面など、城崎温泉の伝統的な旅館形態をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010850"},{"id":"00011168","register_sub_id":"101","register_pk":"205275","name":"佐藤家及び西村家住宅","kana":"さとうけおよびにしむらけじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市中央町49-4他","lat":35.543929,"lng":134.822402,"geo_status":"db","era":"昭和2頃／昭和59・平成5改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、鋼板葺、建築面積210㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0651","desc":"北但馬地震後に耐火建築が強く推奨されるなか、駅前通りに面して建てられた三戸一体の鉄筋コンクリート造店舗併用住宅。、三戸それぞれに異なる立面デザインとし、各所にアーチやロンバルディア帯、メダイオンといった洋風意匠をちりばめ特徴ある外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011168"},{"id":"00010854","register_sub_id":"101","register_pk":"201689","name":"新かめや本館","kana":"しんかめやほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕279","lat":35.626095,"lng":134.810416,"geo_status":"db","era":"昭和34","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造3階建、瓦葺、建築面積206㎡","structure_material":"木造3階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0624","desc":"河畔に建つ木造三階建旅館で平田雅哉の設計になる。正面階境に庇を廻らし、一階東寄りの玄関と二階西寄りに千鳥破風を配して外観を整える。玄関廻りに細格子の横長窓を配し、直線的で端正な意匠の座敷飾に朱塗の棚で趣を添えるなど、平田の作風の一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010854"},{"id":"00009053","register_sub_id":"101","register_pk":"162413","name":"新港貿易会館（旧新港相互館）","kana":"しんこうぼうえきかいかん（きゅうしんこうそうごかん）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区新港町8-2","lat":34.68454382,"lng":135.19888864,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造4階地下1階建、建築面積519㎡、塔屋付","structure_material":"鉄筋コンクリート造4階地下1階建","registered":"2011.10.28(平成23.10.28)","register_no":"28 － 0530","desc":"神戸の新港地区に建ち、建築面積５１９㎡、鉄筋コンクリート造四階地下一階建である。外壁はスクラッチタイル貼で、十字路に面した西南隅に出入口を開く。幾何学図形やアールデコ風の装飾など新しい意匠を巧みに取り入れた独創的な事務所ビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009053"},{"id":"00016419","register_sub_id":"101","register_pk":"536486","name":"宝塚ゴルフ倶楽部クラブハウス","kana":"たからづかごるふくらぶくらぶはうす","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県宝塚市蔵人字深谷1391-1他","lat":34.78751111,"lng":135.34071667,"geo_status":"db","era":"昭和34年／昭和46年・平成8年増築、同24年改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造地上3階地下1階建、建築面積2，550㎡","structure_material":"鉄筋コンクリート造一部鉄骨造地上3階地下1階建","registered":"2025.11.17(令和7.11.17)","register_no":"28 - 0847","desc":"逆瀬川沿いのゴルフ場のクラブハウス。設計は村野藤吾を中心とした建設委員会。斜面地に建つ鉄筋コンクリート造一部鉄骨造、地上3階地下１階建。外周に軒を張出し、中央に塔屋を配す。水平性を強調しつつ、塔屋と組合わせた外観が、周囲の環境と調和を生む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016419"},{"id":"00014401","register_sub_id":"101","register_pk":"511390","name":"帝国信栄本社屋","kana":"ていこくしんえいほんしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区琴ノ緒町五丁目312-1他","lat":34.69563056,"lng":135.19473056,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造2階建、建築面積273㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"28 - 0788","desc":"三ノ宮駅北側の市街地に所在する商業ビル。鉄筋コンクリート造二階建、交差点に面する角を御影石縁取りと垂直性を強調した柱形でセセッションを取入れた正面入口とし、側壁は表現主義的な円柱意匠とする。営業室の柱には変形したイオニア式柱頭飾を付す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014401"},{"id":"00006041","register_sub_id":"101","register_pk":"107026","name":"豊岡市役所南庁舎別館（旧兵庫縣農工銀行豊岡支店）","kana":"とよおかしやくしょみなみちょうしゃべっかん（きゅうひょうごけんのうこうぎんこうとよおかしてん）","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市中央町11-22","lat":35.54362268,"lng":134.81992832,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積495㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0252","desc":"北西の角地に北面して建ち，間口２７ｍ，奥行１４ｍの規模で，南面西端に付属室を，東端に金庫室を張り出す。正面中央を玄関とし，奥の事務室を２階まで吹抜けとする。外壁はタイル貼，腰及び四隅を石貼とし，正面にピラスターを並べ，重厚な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006041"},{"id":"00004280","register_sub_id":"101","register_pk":"105270","name":"西尾家住宅酒蔵","kana":"にしおけじゅうたくさかぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.096832,"lng":135.138184,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積360㎡","structure_material":"土蔵造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0182","desc":"主屋の東南方に位置し，土蔵ギャラリーとともに屋敷地東辺を画する。桁行１１間梁間５間規模，南北棟，切妻造，桟瓦葺の仕込蔵の北方に，棟を落として物置（もと麹蔵）等を配する。酒造場の中核施設になり，敷地東面に長大な酒蔵景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004280"},{"id":"00004278","register_sub_id":"101","register_pk":"105268","name":"西尾家住宅新蔵二","kana":"にしおけじゅうたくしんぐらに","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.09708,"lng":135.137939,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積279㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0180","desc":"茶室，部屋蔵・中蔵，新蔵一の西面に沿って南北に流れる水路を越えた拡張敷地に南北棟で建つ。桁行１２間梁間６間規模の大きな２階建酒蔵で，切妻造，桟瓦葺，妻入とし，街道側の北妻面には高い位置に水切を設け，西面には２段６列の小窓を整然と配置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004278"},{"id":"00004279","register_sub_id":"101","register_pk":"105269","name":"西尾家住宅土蔵ギャラリー","kana":"にしおけじゅうたくどぞうぎゃらりー","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.09674701,"lng":135.13796741,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積156㎡","structure_material":"土蔵造平屋一部2階建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0181","desc":"主屋の南方にほぼ東西棟で建つ。桁行８間梁間５間規模，切妻造，桟瓦葺の平屋建で，現在は西尾本家の資料館として活用され，東半は展示ギャラリーとなっている。他の酒蔵と同様，基礎を花崗石積とし，腰を縦板張，上部を漆喰塗に仕上げ，軒裏まで塗込める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004279"},{"id":"00010851","register_sub_id":"101","register_pk":"201686","name":"西村屋本館大広間棟","kana":"にしむらやほんかんおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所469","lat":35.625312,"lng":134.80561,"geo_status":"db","era":"昭和前期／昭和中期・平成3改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積322㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0621","desc":"老舗旅館の入口脇に建つ木造二階建の大広間棟。南の通り側に入母屋の妻を見せ、西面に並べる窓に庇と高欄を廻らせ、落着きある外観を呈する。二階は洋小屋を用いた八〇畳大の大広間で、折上格天井を張り、南面に大振りな座敷飾、北面に舞台を設け豪壮に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010851"},{"id":"00010852","register_sub_id":"101","register_pk":"201687","name":"西村屋本館平田館","kana":"にしむらやほんかんひらたかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所469","lat":35.625857,"lng":134.804578,"geo_status":"db","era":"昭和35／昭和後期改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造2階建、瓦葺、建築面積591㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0622","desc":"客室から庭への目線が交差せぬよう配置計画された客室棟。吹抜けのロビーに橋を架け、天井に四季の花を描き、廊下はガラスブロック壁で採光する。各室は数寄屋を基調とし、伝統意匠と現代技法を巧みに融合させる。細部にも設計者平田雅哉の作風が窺える優品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010852"},{"id":"00010853","register_sub_id":"101","register_pk":"201688","name":"西村屋本館門及び塀","kana":"にしむらやほんかんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所469","lat":35.625158,"lng":134.805665,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口3.3m、左右袖塀及び潜り戸付 塀 木造、瓦葺、総延長33m、供待付","structure_material":"門 木造","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0623","desc":"敷地南正面に構える門の左右に袖塀を付設し、折曲りに塀を廻らせる。門は大型の薬医門で男梁を舟肘木で受け、屋根に緩く起りをもたせて優雅に見せる。西側には供待を附属する。塀は竪板張で基礎の前面に地元産の玄武岩を並べ、老舗旅館らしい趣ある構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010853"},{"id":"00006169","register_sub_id":"101","register_pk":"107153","name":"西山酒造場店舗兼主屋","kana":"にしやましゅぞうじょうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県丹波市市島町中竹田1171他","lat":35.241241,"lng":135.129135,"geo_status":"db","era":"明治24頃／昭和27頃改造","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積204㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0270","desc":"市道に西面して建つ。建築面積２０４㎡，木造２階建，入母屋造，妻入，桟瓦葺とする。正面１階は真壁造で木製格子を嵌め，２階は軒下に瓦庇及び虫籠格子を付ける。通り土間沿いに和室を並べる。北側に座敷を突出させ，当地で特徴的な座敷中門造とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006169"},{"id":"00006174","register_sub_id":"101","register_pk":"107158","name":"西山酒造場塀","kana":"にしやましゅぞうじょうへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県丹波市市島町中竹田1171他","lat":35.24124345,"lng":135.12903794,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、総延長45m、搬入口付","structure_material":"木造","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0272","desc":"店舗兼主屋の両側に延びる。高さ３．３ｍ，延長４５ｍ，木造，桟瓦葺。真壁造で，腰を杉板の縦板張，上部を漆喰塗とする。軒高を店舗兼主屋の１階軒よりも高くした高塀で，酒造業大店の広大な敷地正面を飾る格式あるつくり。町並み景観の形成にも寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006174"},{"id":"00014654","register_sub_id":"101","register_pk":"515196","name":"橋乃家本館","kana":"はしのやほんかん","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神戸市北区有馬町字有馬792","lat":34.79713889,"lng":135.24754444,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造3階建、鉄板葺、建築面積162㎡","structure_material":"木造3階建","registered":"2023.08.07(令和5.08.07)","register_no":"28 - 0791","desc":"有馬温泉街の入口でかつての太古橋の袂に所在する木造三階建旅館。入母屋造妻入鉄板葺、二・三階は川沿いを眺める高欄付の入側を巡らす。客室は階段室を中心に配置し、個別に床構えを備える。格天井で舞良戸を構えた広い玄関は温泉街の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014654"},{"id":"00004273","register_sub_id":"101","register_pk":"105263","name":"フットテクノビル","kana":"ふっとてくのびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市中央区元町通5-2-8","lat":34.684254,"lng":135.181808,"geo_status":"db","era":"大正10／昭和24改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積178㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0175","desc":"旧外国人居留地の西に接する地域に建つ事務所ビルで，帝国生命保険神戸出張所として建設。鉄筋コンクリート造４階建で，栄町通に南面し，西南角に円みをつける。１階は腰花崗石張，上部擬石仕上げ，２階以上は改装されているが，創建時の骨格をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004273"},{"id":"00003576","register_sub_id":"101","register_pk":"104566","name":"鳳鳴酒造事務室一","kana":"ほうめいしゅぞうじむしついち","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県篠山市呉服町48","lat":35.07673138,"lng":135.22025214,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積6.3㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"28 － 0128","desc":"敷地の北側街路に面し，主屋の西側に建つ。木造平屋建，桟瓦葺の小規模な建築で，内部は一室とする。屋根は街路寄りに棟を設け，南に向かってほぼ片流れ状にかける。街路立面の上部は漆喰塗りとし，中央に虫籠窓風のアクセントを設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003576"},{"id":"00003575","register_sub_id":"101","register_pk":"104565","name":"鳳鳴酒造主屋","kana":"ほうめいしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市呉服町46","lat":35.076664,"lng":135.22032748,"geo_status":"db","era":"文化元","year":1804,"year_source":"db","year_min":1804,"year_max":1804,"year_label":null,"structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"28 － 0127","desc":"篠山城の北東，呉服町に所在する造り酒屋の主屋。北側で街路に面して平入とするつし二階の建物である。入口から通り土間を背面まで通し，東側を床上部とする。街路に面した緩やかなむくりの瓦屋根が特徴的で，城下町篠山の景観を今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003575"},{"id":"00010321","register_sub_id":"101","register_pk":"199094","name":"松尾ビル（旧小橋屋呉服店神戸支店）","kana":"まつおびる（きゅうおばしやごふくてんこうべしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市中央区元町通6-5-6他","lat":34.683497,"lng":135.180124,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造5階一部地下1階建、建築面積369㎡","structure_material":"鉄筋コンクリート造5階一部地下1階建","registered":"2014.12.19(平成26.12.19)","register_no":"28-0600","desc":"元町通り東側の角地に西面して建つ百貨店建築。外観は一階正面に三連大アーケード、上階に縦長三連アーチ窓を表し、三段迫出しの窓台など要所に表現派風の曲線を用いる。内部も柱頭飾、梁や廻縁の蛇腹引など、豊かな装飾をもつ。大正期の意匠の傾向をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010321"},{"id":"00010219","register_sub_id":"101","register_pk":"198052","name":"三木屋西館","kana":"みきやにしかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所487","lat":35.62505618,"lng":134.8059964,"geo_status":"db","era":"昭和2／昭和中期・平成25改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"28 － 0598","desc":"東館の西に並び建つ温泉旅館建築。東館より建ちの低い入母屋造桟瓦葺屋根の二階建建物で、東館と接続し、南面にガラス窓をたてて、二階に手摺を設ける。内部は上下階とも客室を配する。東館とともに、大正一四年北但地震後の城崎温泉復興期の姿を良く留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010219"},{"id":"00010218","register_sub_id":"101","register_pk":"198051","name":"三木屋東館","kana":"みきやひがしかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所487","lat":35.625131,"lng":134.80623316,"geo_status":"db","era":"昭和2／昭和中期・昭和47改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造3階建、瓦葺、建築面積348㎡","structure_material":"木造3階建","registered":"2014.10.07(平成26.10.07)","register_no":"28 － 0597","desc":"城崎温泉のほぼ中央に所在する三階建の温泉旅館建築で寄棟造桟瓦葺である。各階とも同じ広さの矩形平面とし、北面に玄関を附属し、南側は庭園に面する。一階はロビーと宴会場、二階は客室、三階は大宴会場とし、舟底天井を見せる。端正な意匠の木造和風旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010218"},{"id":"00007524","register_sub_id":"101","register_pk":"108506","name":"武庫川女子大学甲子園会館（旧甲子園ホテル）","kana":"むこがわじょしだいがくこうしえんかいかん（きゅうこうしえんほてる）","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市戸崎町6他","lat":34.734264,"lng":135.377945,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造4階地下1階建塔屋付、一部瓦葺、建築面積2056㎡","structure_material":"鉄筋コンクリート造4階地下1階建塔屋付","registered":"2009.01.08(平成21.01.08)","register_no":"28 － 0385","desc":"敷地中央に建つ。建築面積２,０５６㎡、鉄筋コンクリート造、地上４階地下１階建、緑黄色の桟瓦葺。起伏に富んだ空間構成や、テラコッタタイルによる幾何学意匠などライトの建築手法を基調としつつ、和風意匠を加味してまとめた、関西の本格的ホテルの先駆例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007524"},{"id":"00010682","register_sub_id":"101","register_pk":"201256","name":"ゆとうや旅館詠帰亭","kana":"ゆとうやりょかんえいきてい","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕373","lat":35.625472,"lng":134.809664,"geo_status":"db","era":"昭和3年／昭和8年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積275㎡","structure_material":"木造平屋一部2階建","registered":"2015.08.04(平成27.08.04)","register_no":"28－0608","desc":"敷地東方に建つ別棟で、皇室などの宿所としても使われた。平屋建の詠帰亭と二階建の扶老亭を雁行配置とし廊下で繋ぐ。詠帰亭は唐破風、扶老亭は切妻の玄関をそれぞれ付し、内部は上質な座敷を並べ、浴室、洗面所や洗面脱衣室も良材による和風意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010682"},{"id":"00010687","register_sub_id":"101","register_pk":"201261","name":"ゆとうや旅館表門及び塀","kana":"ゆとうやりょかんおもてもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕373","lat":35.625842,"lng":134.809459,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"表門 鉄筋コンクリート造、瓦葺一部銅板葺、間口3.8m 塀 木造、瓦葺一部銅板葺、総延長8.5m","structure_material":"表門 鉄筋コンクリート造","registered":"2015.08.04(平成27.08.04)","register_no":"28－0613","desc":"敷地北に道路に面して建つ。薬医門形式の入母屋造桟瓦葺で軒先を銅板葺とする。太いコンクリート造の本柱と脇柱の表面を、赤錆色の砂利の洗出し仕上げとして玉石を散らして埋込み、その上に立てた細い柱で軒を支える。独創的な意匠を見せる、老舗旅館の表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010687"},{"id":"00010686","register_sub_id":"101","register_pk":"201260","name":"ゆとうや旅館土蔵","kana":"ゆとうやりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕373","lat":35.625112,"lng":134.809111,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積75㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"28－0612","desc":"敷地南西隅に建つ大型の土蔵。桁行五間梁間四間、土蔵造二階建で、屋根を切妻造の桟瓦葺とする。外壁は漆喰塗で腰は北面、西面を海鼠壁、他は石造風のモルタル塗目地切り仕上げとし、軒は塗込めとする。内部は中央に通し柱を建て、小屋は牛梁に登梁をかける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010686"},{"id":"00010683","register_sub_id":"101","register_pk":"201257","name":"ゆとうや旅館渡り廊下","kana":"ゆとうやりょかんわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕373","lat":35.625333,"lng":134.809339,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"鉄筋コンクリート造及び木造平屋建、瓦葺及び銅板葺、建築面積168㎡","structure_material":"鉄筋コンクリート造及び木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"28－0609","desc":"敷地南の建物を結ぶ渡り廊下で、途中に浴室、東屋を設ける。鉄筋コンクリートと木造の混構造で、数寄屋意匠を基調とするが、付近の天然記念物玄武洞に因む六角形平面や六角格子壁を取入れ、松、竹、梅を模した飾り窓を配するなど、随所に奇抜な造形を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010683"},{"id":"00012434","register_sub_id":"101","register_pk":"531758","name":"旅亭文市楼旧館","kana":"りょていぶんいちろうきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県三木市本町三丁目1385-1他","lat":34.79506111,"lng":134.9828,"geo_status":"db","era":"大正13年／昭和前期増築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積374㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"28-691","desc":"旧城下町人地の入組んだ路地奥にある。旧館は入母屋造妻入の大広間棟と客間棟からなり、大広間は書院風の格調高いつくりとし、各客間は数寄屋風や草庵風の意匠を用いて個性豊かにつくる。戦前の地方都市の営みの一端を物語る伝統木造の料理旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012434"},{"id":"00012435","register_sub_id":"101","register_pk":"531759","name":"旅亭文市楼新館","kana":"りょていぶんいちろうしんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県三木市本町三丁目1385-1他","lat":34.79521944,"lng":134.9829,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"28-692","desc":"旧館客間棟の背面に渡廊下で接続する。入母屋造の座敷棟で、中廊下をＴ字に通して客間五室を配する。各客間は傘天井や網代天井を使い分け、入口に板葺の庇を付すなど数寄屋好みの意匠を凝らす。旧館とともに戦前に都市部で興隆した料理旅館の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012435"},{"id":"00006235","register_sub_id":"101","register_pk":"107219","name":"小田垣商店店舗","kana":null,"category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市立町19-5","lat":35.072399,"lng":135.223373,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積193㎡","structure_material":"木造平屋一部2階建","registered":"2007.10.02(平成19.10.02)","register_no":"28 － 0283","desc":"篠山城下の東方に所在する商家地区を南北に通る旧京街道に西面して建つ。桁行１５ｍ、梁間１２ｍ規模、切妻造、桟瓦葺、平入の木造つし２階建で、内部は北半を土間とし、外部は軒下等を塗り込め、妻面に水切瓦を付ける。街道景観の中核をなす大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006235"},{"id":"00007790","register_sub_id":"101","register_pk":"108771","name":"小川又兵衛商店内蔵","kana":"おがわまたべえしょうてんうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市鵲町8-1","lat":34.6777209,"lng":135.83229961,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積32㎡","structure_material":"土蔵造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"29-0133","desc":"短冊形の敷地の中央、渡廊下の東側に接続する。桁行５．５ｍ梁間３．８ｍの土蔵造平屋建、切妻造桟瓦葺。南面に下屋庇を付設。西面は、出入口周囲を黒漆喰塗で木瓜型に象り、切目縁を設け渡廊下の縁と繋ぐ。奈良町における町家の屋敷構えを示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007790"},{"id":"00007788","register_sub_id":"101","register_pk":"108769","name":"小川又兵衛商店店舗兼主屋","kana":"おがわまたべえしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市鵲町8-1","lat":34.67772528,"lng":135.83205138,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積144㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"29-0131","desc":"元興寺の東向かいの細長い敷地に建つ。間口８．８ｍの木造２階建、切妻造桟瓦葺。出格子を設ける前方の表屋と後方の主体部、その間を繋ぐゲンカンからなる表屋造。南側に通り土間、表屋にミセノマ、主体部に居室等を配し、奈良町の伝統的な町家の形態をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007788"},{"id":"00007789","register_sub_id":"101","register_pk":"108770","name":"小川又兵衛商店渡廊下","kana":"おがわまたべえしょうてんわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市鵲町8-1","lat":34.67771635,"lng":135.83218562,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"29-0132","desc":"店舗兼主屋の東端と内蔵を繋ぐ廊下で、桁行７．８ｍ梁間４．８ｍの木造平屋建、桟瓦葺である。南側を通り土間、北側を物入及び便所とし、北側の中庭に面して高欄付切目縁を設ける。瀟洒な意匠で、町家における内庭の空間構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007789"},{"id":"00002072","register_sub_id":"101","register_pk":"103062","name":"菊水楼旧本館","kana":"きくすいろうきゅうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県奈良市高畑町1130","lat":34.68179072,"lng":135.83448634,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積299㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0030","desc":"敷地は春日大社参道に面した角地にあり，背後に荒池を望む景勝地に建つ。入母屋造，桟瓦葺の純和風木造２階建で，料理旅館として長い歴史をもち，多くの賓客を迎えた。現在も建築当時の姿を保ち，格式ある料理旅館のたたずまいは市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002072"},{"id":"00002073","register_sub_id":"101","register_pk":"103063","name":"菊水楼本館","kana":"きくすいろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県奈良市高畑町1130","lat":34.68177,"lng":135.834259,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造3階建、瓦葺、建築面積293㎡","structure_material":"木造3階建","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0031","desc":"旧本館に接続して明治３４年に増築。入母屋造，桟瓦葺の純和風木造３階建で，正面に突出する入母屋造の玄関天井に菊水の彫刻，１階壁面には菊花を象った丸窓をあしらう。三条通からの眺望は表門とともに大鳥居前の景観に欠くことの出来ない存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002073"},{"id":"00010224","register_sub_id":"101","register_pk":"198057","name":"旧川本家住宅蔵及び納屋","kana":"きゅうかわもとけじゅうたくくらおよびなや","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県大和郡山市洞泉寺町10","lat":34.64639,"lng":135.784556,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積64㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"29 － 0213","desc":"敷地西辺に建つ土蔵造二階建で、座敷棟茶室と渡廊下で接続する。北側を切妻造本瓦葺の蔵、南側を切妻造段違で桟瓦葺の納屋とし、東面に瓦葺の庇を付ける。外壁は漆喰塗で腰を竪板張とし、蔵の戸口枠は木瓜形につくる。敷地の奥に重厚な構えを見せる附属屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010224"},{"id":"00010223","register_sub_id":"101","register_pk":"198056","name":"旧川本家住宅座敷棟","kana":"きゅうかわもとけじゅうたくざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県大和郡山市洞泉寺町10","lat":34.646394,"lng":135.784691,"geo_status":"db","era":"大正13／昭和前期・昭和中期改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積127㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"29 － 0212","desc":"本館の西に坪庭を介して接続する木造二階建で、切妻造桟瓦葺とし、西面北に茶室、南に浴室、便所を張出す。南側は一階が厨房、二階が髪結場など営業用で、北側一階の座敷一二畳や二階の六畳二室は居住用の室である。南面高塀には猪目形の透かし窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010223"},{"id":"00010222","register_sub_id":"101","register_pk":"198055","name":"旧川本家住宅本館","kana":"きゅうかわもとけじゅうたくほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県大和郡山市洞泉寺町10","lat":34.646394,"lng":135.784795,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造3階建、瓦葺、建築面積135㎡","structure_material":"木造3階建","registered":"2014.10.07(平成26.10.07)","register_no":"29 － 0211","desc":"街路に東面する木造三階建の旧妓楼で、切妻造桟瓦葺とする。正面は一階に瓦葺庇をつけ、中央を戸口、両脇を出格子とする。上階も繊細な出格子に小庇を付ける。一階は帳場や仏間で、上階の客室は三畳から八畳で色土壁に釣トコを備える。歓楽街の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010222"},{"id":"00013870","register_sub_id":"101","register_pk":"507828","name":"旧吉野銀行桜井支店","kana":"きゅうよしのぎんこうさくらいしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県桜井市大字桜井951","lat":34.51164722,"lng":135.84775833,"geo_status":"db","era":"昭和5年／平成30年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積100㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"29 － 0324","desc":"桜井駅前の商店街の道路に北面して建つ。木造二階建、寄棟造鉄板葺。外壁は一階は人造石仕上、二階はタイル貼で、竪長窓を並べコーニスを卵鏃風文様とデンティルで飾る。内部東半の客溜は吹抜け上部にギャラリーを廻らす。意匠簡明ながら本格的な木造洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013870"},{"id":"00006602","register_sub_id":"101","register_pk":"107585","name":"旧六十八銀行八木支店","kana":"きゅうろくじゅうはちぎんこうやぎしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県橿原市八木町1-501-2","lat":34.508617,"lng":135.792694,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積157㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"29 － 0112","desc":"近鉄橿原線八木西口駅近くに，国道に北面して建つ。両翼を薄く張り出したルネッサンス風の形態をとり，中央部の玄関とその上部の半円形窓の左右にイオニア式の円柱を配する。幾何学的な細部や玄関廻りタイルの芋目地貼等に新味が認められる。設計は舟橋俊一。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006602"},{"id":"00000454","register_sub_id":"101","register_pk":"101444","name":"古梅園事務所","kana":"こばいえんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７他","lat":34.68061565,"lng":135.82752115,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造2階建，瓦葺，建築面積120㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0006","desc":"店舗の南側に接続する平入，つし２階の建物で，立ちは軒庇とも店舗より一段低いが，一体的な意匠にまとめる。北端は出入口で大戸口とし，中央部は事務室で格子戸をはめる。南端部は車庫に改造したが，今も奈良町の伝統的な店構えをよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000454"},{"id":"00000453","register_sub_id":"101","register_pk":"101443","name":"古梅園店舗","kana":"こばいえんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68074433,"lng":135.82751651,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造2階建，瓦葺，建築面積56㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0005","desc":"旧奈良町の一画にある老舗の製墨業古梅園の店舗で，風格ある看板を掲げる。平入，つし２階の伝統的な構えになり，正面は庇及び上屋ともせがい造りとする。格子は多用せず開放的になるが，外壁を黒漆喰塗とした重厚な店舗として広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000453"},{"id":"00000459","register_sub_id":"101","register_pk":"101449","name":"古梅園西内蔵","kana":"こばいえんにしうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68078921,"lng":135.82707253,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"土蔵造2階建，瓦葺，建築面積55㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0011","desc":"敷地のほぼ中央北よりに東西方向に建つ大型の土蔵で，南面に桟瓦葺きの下屋を取り付ける。 外観は２階の東面及び南面に小庇付の開口部を設け，漆喰仕上げの軒蛇腹付の外壁や外引きの防火戸が意匠を整える。 内向きの生活空間の西を限る土蔵でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000459"},{"id":"00003687","register_sub_id":"101","register_pk":"104677","name":"ぜいたく豆本舗本店主屋","kana":"ぜいたくまめほんぽほんてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県奈良市角振町24-1","lat":34.682068,"lng":135.827423,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積133㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"29 － 0070","desc":"奈良市の中心地，三条通に面する町家。道路拡張により前面側は１間ほど切縮められている。当初は１階西側を床上部としたが，数度の改造を経て総土間に改められた。つし２階の外観で，２階には東西２列に居室を配する。奈良町の景観を今日に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003687"},{"id":"00010989","register_sub_id":"101","register_pk":"208959","name":"玉や主屋","kana":"たまやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県葛城市當麻元當麻方1242","lat":34.51564,"lng":135.697334,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"29-0228","desc":"當麻寺門前の角地に建つ二階建のもと旅籠。西面入母屋造、東面切妻造、起りのある桟瓦葺で下屋と高欄を廻らす。外周に格子をたてるほか、壁に「松に鶴」の鏝絵を飾り、また軒の持送りに宝珠を彫刻するなど華やいだ雰囲気をもち、古刹門前の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010989"},{"id":"00010990","register_sub_id":"101","register_pk":"208960","name":"玉や離れ座敷","kana":"たまやはなれざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県葛城市當麻元當麻方1242","lat":34.515727,"lng":135.697258,"geo_status":"db","era":"江戸末期／平成22頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"29-0229","desc":"主屋北西側に南北棟で建ち、廊下で接続する。木造二階建、南面入母屋造、北面切妻造、桟瓦葺で、二階南東面に高欄付の縁を廻らす。一階の板間はもと二室の客室で、西面にトコを二所備え、旧室境に透彫欄間を飾る。落ち着いた佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010990"},{"id":"00009354","register_sub_id":"101","register_pk":"194147","name":"田村青芳園茶舗店舗兼主屋","kana":"たむらせいほうえんちゃほてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市勝南院町19-1","lat":34.67909534,"lng":135.83042688,"geo_status":"db","era":"江戸後期／昭和中期・昭和後期・平成元年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"29 － 0198","desc":"奈良町の通りに東面して建つ平入町家。木造二階建、切妻造桟瓦葺、間口八メートル奥行一四・一メートルで、背面に下屋を付ける。正面は軒を出桁とし、両側に卯建を設け、二階に大きな虫籠窓を設けるなど特徴あるつくりとする。奈良の伝統的町家の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009354"},{"id":"00005024","register_sub_id":"101","register_pk":"106014","name":"辻家住宅主屋","kana":"つじけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県天理市丹波市町20","lat":34.59352904,"lng":135.83461714,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"29 － 0091","desc":"上街道沿いの角地に建つ。桁行５間，梁行５間半規模の２階建で，屋根は北を切妻造，南を入母屋造の本瓦葺とし，内部は北方床上部に２列３室を配し，２階には８畳座敷や茶室等を設ける。本２階建のたちの高い姿形は，市のたつ通りに面して際だった存在になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005024"},{"id":"00000257","register_sub_id":"101","register_pk":"101247","name":"南都銀行本店","kana":"なんとぎんこうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市橋本町16-1他","lat":34.6822217,"lng":135.82854553,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建，建築面積516㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"1997.07.15(平成9.07.15)","register_no":"29 － 0001","desc":"正面に４本のイオニア式の列柱を並べ細部に装飾を施す外観は、古典様式を簡潔にまとめた好例。昭和28年に背後に増築し、その後窓枠や内装の改修を受けたが、外観はよく保存されている。設計長野宇平治、施工大林組。古都奈良の数少ない様式建築の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000257"},{"id":"00002081","register_sub_id":"101","register_pk":"103071","name":"山田酒店（茶房長谷路）主屋","kana":"やまださけてん（さぼうはせじ）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市初瀬857","lat":34.53112793,"lng":135.90625159,"geo_status":"db","era":"文化9／大正初期増築","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造2階建、瓦葺、建築面積109㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0039","desc":"長谷寺への参拝路に面して建つ茶房を併設した酒店。文化８年の長谷川の氾濫後に建造された。木造つし２階建，切妻造，桟瓦葺。通りに面して店舗を構え，北側に食堂，茶の間，東側に中庭に面した和室を２室とる。江戸末建立の酒店として重厚な店構えを持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002081"},{"id":"00002438","register_sub_id":"101","register_pk":"103428","name":"池庄漆器店主屋","kana":"いけしょうしっきてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県海南市黒江692","lat":34.16143,"lng":135.204636,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積123㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"30 － 0047","desc":"江戸後期より続く漆器問屋の一つで，敷地は正面が小路に，背面が黒江の中心街区の川端通りに接する。小路に面する主屋は切妻造，２階建で，背面に平屋建の角屋を延ばす。建物高が全体的に低い構成で，重厚な本瓦葺屋根をあげ，近世の町並み景観を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002438"},{"id":"00014287","register_sub_id":"101","register_pk":"509677","name":"一木旅館旧館","kana":"いちきりょかんきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県海南市下津町上字前原288","lat":34.11071944,"lng":135.15778889,"geo_status":"db","era":"明治後期／昭和12年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0322","desc":"長保寺参詣道に所在する旅館の客室棟。二階建、入母屋造桟瓦葺、塀を挟んで参詣道に二階を見せる。本館の西に玄関棟で繋がる。一階に大小四室の続き座敷、二階に床構え付六畳と次の間六畳を配する。数寄屋風で銘木趣味のやや濃厚な意匠で新館と好対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014287"},{"id":"00014286","register_sub_id":"101","register_pk":"509676","name":"一木旅館玄関棟","kana":"いちきりょかんげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市下津町上字前原288","lat":34.11072778,"lng":135.15790833,"geo_status":"db","era":"昭和12年頃／昭和30年頃改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0321","desc":"長保寺参詣道に所在する旅館の玄関棟。通りに開く門から石敷き路で引き込んだ前庭奥にあり、平屋建、両下造桟瓦葺で、本館と旧館を繋ぐ東西廊下と新館への渡り廊下及び水廻りで構成する。玄関土間に那智黒石を散らすほか、内外に数寄を凝らした意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014286"},{"id":"00014288","register_sub_id":"101","register_pk":"509678","name":"一木旅館新館","kana":"いちきりょかんしんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市下津町上字前原288","lat":34.11083333,"lng":135.15785278,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0323","desc":"長保寺参詣道の旅館客室棟。二階建、入母屋造桟瓦葺で、玄関棟の北に渡り廊下で繋がる。寄付、前室、床構え付き主室、広縁からなる個別客室を、一階三部屋、二階二部屋配し、落ち着いた数寄屋風意匠でまとめる。広縁は敷地背面の宮川に面して風情がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014288"},{"id":"00014285","register_sub_id":"101","register_pk":"509675","name":"一木旅館本館","kana":"いちきりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県海南市下津町上字前原288","lat":34.11068889,"lng":135.15797222,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積126㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0320","desc":"長保寺参詣路に南面して所在する町家で旅館を営む。平屋建、切妻造平入本瓦葺で軒が低く、東側から広い通り土間と一列二室、玄関と角屋に延びる廊下、待合等の和室二室と背面側に角屋の床構え付き続き座敷を設ける。参詣路の歴史的景観を伝える貴重な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014285"},{"id":"00014289","register_sub_id":"101","register_pk":"509679","name":"一木旅館門及び塀","kana":"いちきりょかんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市下津町上字前原288","lat":34.11066944,"lng":135.15780556,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"門 木造、杉皮葺、間口1.7m 塀 木造、瓦葺、総延長20m","structure_material":"門 木造","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0324","desc":"長保寺参詣道に南面する旅館の門塀。門は切妻造杉皮葺の腕木門で、出節の柱に両折れ板戸を建てる。土間に那智黒石を敷き込む。塀は桟瓦軒先銅板葺で、真壁造漆喰仕上に角窓を開け、腰に半割丸太を張る。数寄を凝らす意匠で参詣道に趣を与える近代和風の門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014289"},{"id":"00014079","register_sub_id":"101","register_pk":"508339","name":"大前屋旅館","kana":"おおまえやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県新宮市三輪崎一丁目293他","lat":33.68544167,"lng":135.98591667,"geo_status":"db","era":"明治36年／昭和48年改修","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"30 - 0317","desc":"三輪崎港の通りに北面する近代和風旅館。二階建入母屋造桟瓦葺で庇を付す。東寄に玄関を開け両脇に出格子を構え、二階の建ちが高い。内部は玄関ホールから中廊下を通して両脇に続き間座敷等を配置する。各室に縁や出窓を設け、海や通りへの眺望を確保する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014079"},{"id":"00002436","register_sub_id":"101","register_pk":"103426","name":"尾崎林太郎家住宅三階蔵","kana":"おざきりんたろうけじゅうたくさんかいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県海南市黒江598","lat":34.160969,"lng":135.204605,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積64㎡","structure_material":"土蔵造3階建","registered":"2001.10.12(平成13.10.12)","register_no":"30 － 0045","desc":"尾崎家は海上輸送の要所であった黒江川沿いの荷揚場南に位置している。三階蔵は漆器商品を収蔵し，東側道路に面した長屋門と主屋との間に建つ。東西棟の切妻造，桟瓦葺，内部は三層で，建ちも高く，商家に相応しいつくりである。上棟式の御幣より年代が判る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002436"},{"id":"00001337","register_sub_id":"101","register_pk":"102327","name":"上御殿本館","kana":"かみごてんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県田辺市龍神村龍神42-1","lat":33.95708504,"lng":135.56189866,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、瓦葺、建築面積197㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"30 － 0036","desc":"紀州徳川家初代頼宣公の保護を受けた温泉別荘としての由緒をもつことで知られる。明治１７年類焼後の再建になるもので，日高川を背にし，旧国道に面して建つ。紀州藩御殿の系譜をひく総２階，入母屋屋根の旅館建築で，２階に床を一段あげた「御成間」をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001337"},{"id":"00007111","register_sub_id":"101","register_pk":"108093","name":"亀屋旅館本館","kana":"かめやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県田辺市本宮町川湯1434-1","lat":33.81285088,"lng":135.77402075,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"30 － 0134","desc":"大塔川沿いの川湯温泉のほぼ中央に位置する。入母屋造桟瓦葺の木造２階建で、１階に銅板葺庇を付ける。桁行１５ｍ梁間９．０ｍ規模で、正面中央に南面して玄関を設ける。１、２階とも中廊下式で、両側に部屋を配する。風景と調和し、老舗旅館の風格を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007111"},{"id":"00014523","register_sub_id":"101","register_pk":"513937","name":"旧浦清兵衛商店店舗","kana":"きゅううらせいべえしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県有田郡広川町大字広字南市場1323他","lat":34.02657222,"lng":135.17288056,"geo_status":"db","era":"明治後期／令和4年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積121㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"30 - 0334","desc":"旧広村中心地の辻角に建つ造り酒屋の旧店舗。二階建、入母屋造本瓦葺で軒まで塗込め、壁面は黒漆喰塗仕上で重厚にみせる。内部は東を土間、西を床上とし、北西を床構付き座敷とする。大きな格子窓を二階北角に寄せた外観が地域のランドマークとなる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014523"},{"id":"00002566","register_sub_id":"101","register_pk":"103556","name":"旧葛城館","kana":"きゅうかつらぎかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県橋本市高野口町名倉1053","lat":34.3074,"lng":135.556992,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造3階建、瓦葺、建築面積113㎡","structure_material":"木造3階建","registered":"2001.11.20(平成13.11.20)","register_no":"30 － 0048","desc":"ＪＲ和歌山線高野口駅前に北面して建つ。桁行５間半，梁間５間規模の総３階建で，東西棟，入母屋造，桟瓦葺とし，正面及び東側面には銅板葺の庇を各階に廻し，屋根正面には瓦葺の千鳥破風と銅板葺の唐破風を重ねる。木造３階建和風旅館建築の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002566"},{"id":"00002087","register_sub_id":"101","register_pk":"103077","name":"旧西本組本社ビル","kana":"きゅうにしもとぐみほんしゃびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市小野町3-43","lat":34.23189997,"lng":135.16330714,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積82㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2000.12.04(平成12.12.04)","register_no":"30 － 0042","desc":"ＲＣ造３階建。腰を花崗岩張，２，３階をタイル張とし，玄関部にはペディメントをイオニア式柱で支えたポーティコがとりつく。立面のデザインと細部の装飾はよく均整がとれ，建設会社旧本社ビルとしての風格をもつ。設計は早大出身で西本組に勤めた岩井信一。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002087"},{"id":"00014406","register_sub_id":"101","register_pk":"511395","name":"旧堀田茶舗（立石茶屋）座敷棟","kana":"きゅうほったちゃほ（たていしちゃや）ざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡湯浅町大字湯浅字道町860-2","lat":34.03470278,"lng":135.17827778,"geo_status":"db","era":"昭和９年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"30 - 0331","desc":"市街地四ツ辻に所在する商家の住居で、店舗背面北寄りに接続する東西棟。二階建、西切妻・東寄棟造で桟瓦葺、二階壁銅板張。各階二室、衣桁形板欄間や四方竹竿縁等を用いる数寄屋風和室と、二階西部屋の洋室からなる。四ツ辻の暮らしの歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014406"},{"id":"00014405","register_sub_id":"101","register_pk":"511394","name":"旧堀田茶舗（立石茶屋）店舗","kana":"きゅうほったちゃほ（たていしちゃや）てんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡湯浅町大字湯浅字道町860-2","lat":34.03468889,"lng":135.17816667,"geo_status":"db","era":"江戸末期／平成19年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"30 - 0330","desc":"熊野街道と深専寺参道の四ツ辻北東角に西面するつし二階建町家。背面に便所・風呂を張り出す。切妻造本瓦葺、軒を塗込めて虫籠窓を設ける。内部は正面に幅の狭い前土間、南側を通り土間とした一列二室の小規模な店舗。四ツ辻の賑わいの歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014405"},{"id":"00014407","register_sub_id":"101","register_pk":"511396","name":"旧堀田茶舗（立石茶屋）土蔵","kana":"きゅうほったちゃほ（たていしちゃや）どぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡湯浅町大字湯浅字道町860-2","lat":34.03468333,"lng":135.17835833,"geo_status":"db","era":"江戸末期／昭和前期・平成23年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"30 - 0332","desc":"四ツ辻角の商家の商品蔵で、敷地東辺の通りに妻面の竪板張壁を見せる。土蔵造二階建、切妻造桟瓦葺。内部は一階戸口廻りを土間で吹抜とし、他は板敷で各階二室に仕切る。内部の風食の程度から、頻繁な商品搬出入が分かり、湯浅の商業地としての繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014407"},{"id":"00015497","register_sub_id":"101","register_pk":"533512","name":"旧万忠金物店店舗","kana":"きゅうまんちゅうかなものてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県有田郡湯浅町大字湯浅字道町771","lat":34.03531667,"lng":135.17790833,"geo_status":"db","era":"大正3年頃／昭和前期・令和6年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積83㎡","structure_material":"木造3階建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0405","desc":"湯浅町の中心部に位置する旧金物店の店舗。熊野街道に東面して建つ木造３階建切妻造平入鉄板葺で正面は各階境に出桁庇を付し、２・３階は連続窓を開け、軒裏は黒漆喰で塗込める。1階は店舗でかつて上階は物置とした。湯浅初の木造３階建と伝える貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015497"},{"id":"00005029","register_sub_id":"101","register_pk":"106019","name":"珠数屋四郎兵衛店舗","kana":"じゅずやしろべえてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山771","lat":34.21305184,"lng":135.58637127,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、銅板葺、建築面積290㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"30 － 0080","desc":"弘法大師１１００年御遠忌に際し建設。棟梁は地元大工の阪田平造と伝える。入母屋造，銅板瓦葺の木造２階建，正面２階中央に唐破風を構える。２階道路側は参詣客の休憩室としての大広間とする。商店名とともによく知られ，地元の人々から広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005029"},{"id":"00005653","register_sub_id":"101","register_pk":"106641","name":"高垣酒造主屋","kana":"たかがきしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県有田郡有田川町小川1465","lat":34.0781656,"lng":135.2801267,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積245㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0095","desc":"敷地のほぼ中央に東西棟で建つ。桁行９間半，梁行６間，入母屋造，桟瓦葺で，西方を土間，東方床上部を２列６室とし，東南に床付きの１０畳座敷を配する。土間部の上には南北棟の入母屋造，桟瓦葺の２階を載せた独特の外観で，全体として上質のつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005653"},{"id":"00005902","register_sub_id":"101","register_pk":"106887","name":"多田家住宅（旧和中家住宅）主屋","kana":"ただけじゅうたく（きゅうわなかけじゅうたく）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市和歌浦中2-10-8","lat":34.19028886,"lng":135.1678938,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"30 － 0101","desc":"南北に走る明光通り商店街に西面して建つ。間口８間半，奥行４間規模，北を切妻造，南を入母屋造とした本瓦葺のつし２階建で，前面に本瓦葺の下屋を付け，内部は北を土間，南を床上部とし，南に落棟で１０畳座敷を延ばす。和歌浦の歴史的景観を伝える要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005902"},{"id":"00014919","register_sub_id":"101","register_pk":"519179","name":"辻慶進堂店舗兼主屋","kana":"つじけいしんどうてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県紀の川市名手市場193","lat":34.27552778,"lng":135.4358,"geo_status":"db","era":"昭和27年／昭和50年代改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0354","desc":"大和街道に北面する印刷業の店舗兼主屋。入母屋造二階建桟瓦葺で両袖に卯建壁を設ける。一階は西を土間とし、二階は中廊下の東西に各二室配す。二階洋室はマントルピースの左右に床と棚を組合わせるなど、数寄屋風と洋風意匠を独特に用いた和洋折衷の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014919"},{"id":"00014921","register_sub_id":"101","register_pk":"519181","name":"辻慶進堂土蔵","kana":"つじけいしんどうどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県紀の川市名手市場193","lat":34.27532778,"lng":135.435875,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0356","desc":"離れの西隣に西面して建つ道具蔵。土蔵造二階建切妻造平入桟瓦葺。外壁は白漆喰壁で南妻の拝に鏝絵で家紋を掲げ、出入口と窓に持送付庇を付し、腰は板張とする。一階は二室、二階は一室とし、小屋組は登梁を水平の繋梁で繋ぐ。離れとともに屋敷構えを構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014921"},{"id":"00014920","register_sub_id":"101","register_pk":"519180","name":"辻慶進堂離れ","kana":"つじけいしんどうはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"和歌山県","address":"和歌山県紀の川市名手市場193","lat":34.27533611,"lng":135.435975,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0355","desc":"矩折れ状敷地の南東奥に建つ隠居所。寄棟造東西棟桟瓦葺。北面西端に玄関、東に八畳二間の座敷を配し、南から西に縁及び廊下を廻す。座敷は床、床脇、付書院を備え、節のある太い材を用いた床柱や細い丸竹を竿縁とした船底天井を張るなど数寄屋風意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014920"},{"id":"00013320","register_sub_id":"101","register_pk":"366309","name":"橋本太次兵衛家住宅旧米穀集荷事務所","kana":"はしもとたじべえけじゅうたくきゅうべいこくしゅうかじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県御坊市湯川町小松原195","lat":33.90305278,"lng":135.16269722,"geo_status":"db","era":"大正後期／昭和21年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"30 － 0281","desc":"新座敷が建つ敷地の道向かいで、旧熊野街道に西面して建つ。木造平屋建、寄棟造桟瓦葺妻入で、外壁は下見板張、上部を漆喰塗とする。東西に板間の洋間を二室並べ、小屋はキングポストトラス組とする。玄関庇軒先の繰形や縦長の上下窓など、洋風意匠が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013320"},{"id":"00013321","register_sub_id":"101","register_pk":"366310","name":"橋本太次兵衛家住宅土塀","kana":"はしもとたじべえけじゅうたくどべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県御坊市湯川町小松原195","lat":33.90310556,"lng":135.16272222,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土塀、瓦葺、総延長20m","structure_material":"土塀","registered":"2020.04.03(令和2.04.03)","register_no":"30 － 0282","desc":"旧米穀集荷事務所の北側で、敷地と街路を区切る。折れ曲がり延長２０メートルの土塀で、基礎は外側が谷積、内側が切石布積で、末広がりの高い石積とする。上部壁面はモルタル洗出し仕上、鉢巻まで同様に仕上げ、桟瓦を葺く。旧熊野街道沿いの景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013321"},{"id":"00005650","register_sub_id":"101","register_pk":"106638","name":"初桜酒造主屋","kana":"はつさくらしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町中飯降85","lat":34.303116,"lng":135.533478,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積197㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0092","desc":"旧大和街道に南面する敷地の南寄りに東西棟で建つ。桁行６間，梁行６間，入母屋造，桟瓦葺，木造２階建の町家建築で，東方を土間とし，西方床上部に２列３室を配し，２階正面側に３室の続き間座敷を設ける。良材を用い，床脇柱など趣向を凝らしたつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005650"},{"id":"00004285","register_sub_id":"101","register_pk":"105275","name":"火伏医院主屋","kana":"ひぶせいいんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市橋本1-16、1-17","lat":34.31635706,"lng":135.61208473,"geo_status":"db","era":"享保6／江戸末期改造","year":1721,"year_source":"db","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積101㎡","structure_material":"木造平屋一部2階建","registered":"2004.07.23(平成16.07.23)","register_no":"30 － 0056","desc":"旧伊勢街道に北面して建つ。間口８間規模，切妻造，桟瓦葺，平入のつし２階建町家で，西側を中土間とし，東側の２室続きの座敷部は落棟で，江戸末期の改築とみられる。棟札から年代の判明する町家で，当地方町家の指標的建築として貴重","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004285"},{"id":"00004287","register_sub_id":"101","register_pk":"105277","name":"前田家住宅主屋","kana":"まえだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市高野口町名倉392-1","lat":34.3051796,"lng":135.55573388,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"30 － 0058","desc":"通りに北面して建つ。桁行６間梁間４間，切妻造，桟瓦葺のつし２階建町家で，軒下まで塗込めて重厚な外観をつくり，正側面３面に半間，背面に１間の下屋庇を廻す。内部は西側を中土間，東側床上部は四間取りとし，土間上部背面側に煙出しを揚げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004287"},{"id":"00006386","register_sub_id":"101","register_pk":"107369","name":"山本勝之助商店事務所","kana":"やまもとかつのすけしょうてんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市阪井679他","lat":34.15996247,"lng":135.25991665,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0119","desc":"シュロ皮商の店舗として建設。国道に南面する間口３間、奥行８間の木造２階建で、寄棟造桟瓦葺の東西棟の裏に切妻造本瓦葺の南北棟が続く。南面は１、２階ともガラス窓とし、東面南端に戸口を開く。１階表の事務所には鉄柱を用いる。外壁の黒漆喰が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006386"},{"id":"00006387","register_sub_id":"101","register_pk":"107370","name":"山本勝之助商店店蔵一","kana":"やまもとかつのすけしょうてんみせぐらいち","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市阪井679他","lat":34.15998659,"lng":135.25981705,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"土蔵造2階建、瓦葺、建築面積128㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0120","desc":"事務所の西に並ぶ土蔵造２階建の商品倉庫。桁行７間、梁間４間の南北棟で、国道に妻を見せる。切妻造桟瓦葺で、東平側に瓦葺庇をつけて蔵前とする。外壁は白漆喰塗で、腰に鉄板を張り、２階には小窓を穿つ。小屋組は登梁。歴史的街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006387"},{"id":"00006389","register_sub_id":"101","register_pk":"107372","name":"山本勝之助商店店蔵三","kana":"やまもとかつのすけしょうてんみせぐらさん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市阪井479-1","lat":34.159744,"lng":135.259903,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"土蔵造2階建、瓦葺、建築面積119㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0122","desc":"事務所の向かいに建つ土蔵造２階建である。桁行８間、梁間３間の東西棟で、切妻造桟瓦葺とし、北に吹放ちの瓦葺庇をつけて、３箇所に戸口を開く。１階は板床。束立の和小屋である。外壁は白漆喰塗で、妻は鉢巻に造り、軒は垂木形に塗り込めて変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006389"},{"id":"00006388","register_sub_id":"101","register_pk":"107371","name":"山本勝之助商店店蔵二","kana":"やまもとかつのすけしょうてんみせぐらに","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市阪井479-1","lat":34.15979319,"lng":135.25966646,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"30 － 0121","desc":"店蔵一と国道を挟んで向かいに建つ土蔵造２階建である。桁行５間、梁間２間半の南北棟で、切妻造桟瓦葺。東に瓦葺庇をつけて蔵前とする。外壁は白漆喰塗で、腰は竪板張。１階は板床とする。束立の和小屋で、野地は割竹の小舞である。妻の屋号がアクセント。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006388"},{"id":"00013445","register_sub_id":"101","register_pk":"368530","name":"和歌山県建築士会館","kana":"わかやまけんけんちくしかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"和歌山県","address":"和歌山県和歌山市卜半町38","lat":34.23260833,"lng":135.16998889,"geo_status":"db","era":"昭和41年／平成25年改修","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄筋コンクリート造3階地下１階建、建築面積184㎡","structure_material":"鉄筋コンクリート造3階地下１階建","registered":"2020.08.17(令和2.08.17)","register_no":"30 － 0283","desc":"和歌山城北の市堀川北岸に建つ。正面一階の壁面を内側に立て、上階の平滑な壁を鉄筋コンクリート造の桁で受けて浮遊感を出す。正面のタイル貼壁面に窓を規則正しく並べ、側壁をコンクリート打放しにして正面性を強調し、内樋により端正な立面に仕立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013445"},{"id":"00002057","register_sub_id":"101","register_pk":"103047","name":"石田家住宅主屋","kana":"いしだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市神足2-13-10","lat":34.919952,"lng":135.69841,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"26 － 0080","desc":"市内を縦貫する旧西国街道に東面して建つ。切妻造，桟瓦葺，つし２階の町家で，北東南３面に桟瓦葺の庇を廻す。内部は南に通り庭を，北に２列６室を配する。神足村旧家の商家を石田家先代が購入したもので，茶の小売業を営みつつ旧街道の佇まいを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002057"},{"id":"00007226","register_sub_id":"101","register_pk":"108208","name":"伊藤喜商店旧店舗兼主屋","kana":"いとうきしょうてんきゅうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区松原通大和大路東入二丁目轆轤町100","lat":34.99765093,"lng":135.77404872,"geo_status":"db","era":"大正15頃／平成19改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積145㎡、塀付","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0311","desc":"松原通に北面して建つ木造２階建の平入町家で醤油を商った。間口５間半で、切妻屋根を桟瓦葺とし、銅板葺庇がつく。背後に風呂と便所が突出する。正面１階は戸口の両側窓に円形断面の格子を入れ、腰を石貼とする。２階は格子窓。大正期の大型町家の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007226"},{"id":"00002947","register_sub_id":"101","register_pk":"103937","name":"今林家住宅糸蔵","kana":"いまばやしけじゅうたくいとぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府宮津市字万町604-1","lat":35.53615816,"lng":135.19186918,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0137","desc":"敷地の北西部に主屋に接しながら，東西棟で建つ。丁寧なつくりに加えて敷地内最大規模の蔵で，糸問屋として機能上かつ建築上の中心的建造物。切妻造，妻入で，梁間を桁行よりも長くとり，２階に２つの開口部を左右対称に設けた大きな妻面を造るのが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002947"},{"id":"00007511","register_sub_id":"101","register_pk":"108493","name":"今林家住宅旧生糸蔵","kana":"いまばやしけじゅうたくきゅうきいとぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府宮津市字万町604-1","lat":35.53615481,"lng":135.19187467,"geo_status":"db","era":"安政5／平成20改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"26 － 0333","desc":"旧店舗の後方に建つ。桁行５．８ｍ梁間３．９ｍ、土蔵造２階建、切妻造桟瓦葺。外部漆喰塗で腰を竪板張とし、南面西寄りを出入口として両開戸を吊り、瓦葺の庇を掛ける。明治初年には内部に縮緬織機を据えて機織りをしたと伝え、部材の一部を棟木に残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007511"},{"id":"00007510","register_sub_id":"101","register_pk":"108492","name":"今林家住宅旧店舗","kana":"いまばやしけじゅうたくきゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府宮津市字万町604-1","lat":35.53605868,"lng":135.19185932,"geo_status":"db","era":"江戸末期／昭和27頃・平成20改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積80㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"26 － 0332","desc":"主屋の西に高塀を介して南面して並び建つ。間口９．８ｍ奥行８．２ｍ、木造２階建、切妻造桟瓦葺。当初は東のトオリニワと、食違い四間取を基本とする間取。正面は真壁造で、２階両袖に卯建を付け、出格子を構える。宮津城下の商家町の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007510"},{"id":"00002945","register_sub_id":"101","register_pk":"103935","name":"今林家住宅主屋","kana":"いまばやしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府宮津市字万町604-1","lat":35.53607589,"lng":135.19193657,"geo_status":"db","era":"明治25／大正期増築","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積261㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0135","desc":"市中心部にある。木造２階建，切妻造，平入で，通り側に半間幅の下屋庇を設ける。正面には平格子・出格子を構え，玄関戸口に引上式大戸を残す。棟の東方には越屋根を設け，軒高を低くした２階西方には袖卯建を付ける。旧宮津城下を代表する町家建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002945"},{"id":"00000697","register_sub_id":"101","register_pk":"101687","name":"エンマ（旧村井銀行祇園支店）","kana":"えんま（きゅうむらいぎんこうぎおんしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区四条通大和大路東入祇園町南側573-5","lat":35.00365368,"lng":135.77462516,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積186㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0019","desc":"たばこ王として知られた村井家のお抱え建築家的存在であった吉武長一による一連の村井銀行支店シリーズのひとつ。アメリカ仕込みの古典主義建築の作風がよく示されており，パラペットのバラストレードなどの細部もよく残されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000697"},{"id":"00015032","register_sub_id":"101","register_pk":"529310","name":"岡墨光堂奥蔵","kana":"おかぼっこうどうおくのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町113","lat":35.00951111,"lng":135.76532778,"geo_status":"db","era":"明治20年","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0674","desc":"主屋の東に建つ家財蔵。土蔵造２階建切妻造平入本瓦葺で、西面を戸口とし下屋を付す。各階一室の板敷とし、南辺に階段を設け、小屋組は束立の和小屋。外壁は漆喰塗仕上とし、腰は竪板張。一階西面の窓と戸口に掛子塗扉を吊り、外観重厚で丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015032"},{"id":"00015031","register_sub_id":"101","register_pk":"529309","name":"岡墨光堂表蔵","kana":"おかぼっこうどうおもてのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町113","lat":35.00959722,"lng":135.76509167,"geo_status":"db","era":"明治中期／大正11年移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0673","desc":"主屋の北、通りに面して建ち、表具などを仮置する土蔵。土蔵造２階建切妻造妻入本瓦葺。外壁は漆喰塗仕上で腰に竪板を高く張り、西面南寄りに窓を開ける。南面戸口に厚い鉄扉を吊り、職場と接続する。軒に鉢巻を廻らした重厚な外観が通りの歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015031"},{"id":"00015029","register_sub_id":"101","register_pk":"529307","name":"岡墨光堂主屋","kana":"おかぼっこうどうおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町113","lat":35.00950833,"lng":135.76520278,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積193㎡、西面北塀付","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0671","desc":"富小路通に西面して建つ表具業の主屋。表屋造とし、2階建切妻造平入桟瓦葺の事務所棟の東に居室棟を配し、渡廊下で接続する。事務所棟には残月床の座敷やマントルピースを備えた洋室など、上質な客間を配す。通りに面した大きな虫籠窓が時代相を示す町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015029"},{"id":"00015030","register_sub_id":"101","register_pk":"529308","name":"岡墨光堂職場","kana":"おかぼっこうどうしょくば","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町113","lat":35.0096,"lng":135.76516389,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積61㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0672","desc":"主屋居室棟の北に建ち表装などを行う作業場。2階建鉄筋コンクリート造切妻造鉄板葺の東西棟で、西端部は平面撥形とし、表の蔵に接続する。一階は二室、二階は一室の板敷で、小屋組は木造のキングポスト・トラス。鉄扉を吊った窓が並ぶ厳重なつくりの作業場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015030"},{"id":"00016677","register_sub_id":"101","register_pk":"579161","name":"喫茶ソワレ","kana":"きっさそわれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府京都市下京区四条通小橋西入真町96-4","lat":35.004178,"lng":135.770337,"geo_status":"db","era":"昭和23年頃／昭和35年頃改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造2階建、人工スレート葺、建築面積36㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"26 - 0742","desc":"高瀬川の西岸に位置する喫茶店。二階建切妻造妻入人工スレート葺で、正面に円錐屋根の塔屋を載せる。内部は柱や梁などナグリ仕上とし、腰壁は葡萄などの木彫で濃密に装飾する。全体的に工芸的なつくりの喫茶店で、青色の内部照明が幻想的な雰囲気を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016677"},{"id":"00011524","register_sub_id":"101","register_pk":"210474","name":"旧鴻池銀行七条支店","kana":"きゅうこうのいけぎんこうしちじょうしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市下京区七条通新町西入夷之町704","lat":34.98942194,"lng":135.75612611,"geo_status":"db","era":"昭和2年／平成20年頃改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階一部地下1階建、建築面積164㎡","structure_material":"鉄筋コンクリート造2階一部3階一部地下1階建","registered":"2017.05.02(平成29.05.02)","register_no":"26-0513","desc":"七条通に南面する鉄筋コンクリート造二階一部三階建。正面に縦長のアーチ窓を並べ、隅石を表し、壁頂にロンバルド帯を飾る等ロマネスクを基調としつつ、玄関庇の持送や内部柱の柱頭まわりなどは幾何模様で装飾密度を高める。意匠華やかな昭和初期の銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011524"},{"id":"00015486","register_sub_id":"101","register_pk":"533501","name":"旧福知山信用金庫本店","kana":"きゅうふくちやましんようきんこほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府福知山市字中ノ21","lat":35.29974444,"lng":135.12481389,"geo_status":"db","era":"昭和3年／平成26年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積212㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0701","desc":"福知山城跡北西の市街地の角地に建つ旧銀行の店舗。二階建鉄筋コンクリート造で外壁モルタル塗仕上、腰は花崗岩切石貼。南西隅切部を中軸とする左右対称の簡明な立面構成で、出入口の庇や半円形窓台をアクセントとする。近代の福知山の繁栄を伝える銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015486"},{"id":"00003443","register_sub_id":"101","register_pk":"104433","name":"旧藤ノ森湯","kana":"きゅうふじのもりゆ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市北区紫野東藤ノ森町11-1","lat":35.03759083,"lng":135.74688628,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"26 － 0157","desc":"船岡温泉の東方，鞍馬口通に面して建つ。脱衣場，浴場・釜場からなり，脱衣場棟２階に和室を設ける。木造だが，浴場左右と釜場境の壁は木骨煉瓦造とする。正面出入口に唐破風を付け，内外を装飾タイル張とするなど，随所に意匠を凝らす。現在飲食店等に転用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003443"},{"id":"00002051","register_sub_id":"101","register_pk":"103041","name":"キンシ正宗堀野記念館（旧堀野家本宅）主屋","kana":"きんしまさむねほりのきねんかん（きゅうほりのけほんたく）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区堺町通二条上る亀屋町172","lat":35.014095,"lng":135.763031,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"26 － 0074","desc":"堺町通に東面して建つ間口６間半規模のやや大型の町家。主体部は南北棟，切妻造，桟瓦葺で，正面は階下に２本切子格子，階上に虫籠窓を並べ，黒漆喰で仕上げる。内部は２段２列に室を配置し，階上に書院座敷，階下に数寄屋風座敷を設ける点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002051"},{"id":"00002289","register_sub_id":"101","register_pk":"103279","name":"近又主屋","kana":"きんまたしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区御幸町通四条上る大日町407","lat":35.00475578,"lng":135.7662771,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積110㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0081","desc":"近江出身の近江屋又八が創業した商人宿。近又は屋号で，明治３６年頃に現在地に移った。御幸町通に東面して建つ２階建・平入・桟瓦葺の町家建築で，１階北半と２階に客室を設ける。数寄屋風の意匠でまとめられ，床や棚，窓，欄間など変化に富んだ造形を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002289"},{"id":"00002290","register_sub_id":"101","register_pk":"103280","name":"近又離れ","kana":"きんまたはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市中京区御幸町通四条上る大日町407","lat":35.00476368,"lng":135.76622734,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積98㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0082","desc":"主屋の後方に中庭を挟んで連なり，昭和３年の御大礼に際して建設されたという。２階建，切妻造・桟瓦葺で，１階・２階とも中廊下とし，上手２室，下手１室の客室を配する。主屋と同じく数寄屋風で，障子等の建具や板欄間など細部に凝ったつくりをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002290"},{"id":"00010838","register_sub_id":"101","register_pk":"201673","name":"壽ビルディング","kana":"ことぶきびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市下京区西木屋町通松原上る三丁目市之町251-7他","lat":35.00167,"lng":135.769175,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積159㎡、塔屋付","structure_material":"鉄筋コンクリート造5階建","registered":"2015.11.17(平成27.11.17)","register_no":"26 ‐ 0494","desc":"河原町通に面して建つ鉄筋コンクリート造五階建。内外観は簡素な意匠を基本としつつ、正面玄関や階段にアール・デコ風意匠を取入れ、一階外壁の石張や柱形頂部にアカンサスなどの様式主義的要素を備える。京都中心部に残る昭和初期の事務所ビルとしても希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010838"},{"id":"00000298","register_sub_id":"101","register_pk":"101288","name":"SACRA（旧不動貯金銀行京都支店）","kana":"さくら（きゅうふどうちょきんぎんこうきょうとしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区三条通富小路西入中之町20","lat":35.00872215,"lng":135.76487264,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木骨煉瓦造地上3階地下1階建，銅板葺，建築面積232㎡","structure_material":"木骨煉瓦造地上3階地下1階建","registered":"1997.09.03(平成9.09.03)","register_no":"26 － 0008","desc":"木骨煉瓦造，地上３階地下１階建で，屋根を銅板葺とする旧銀行の建物。全体に装飾豊かな洋風の意匠を持ち，１階部分のストライプ模様や正面中央の円形装飾等に代表されるように，細部に幾何学的な形態を用いてまとめる点に時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000298"},{"id":"00008142","register_sub_id":"101","register_pk":"132583","name":"清輝樓","kana":"せいきろう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府宮津市字魚屋937他","lat":35.53781659,"lng":135.19500851,"geo_status":"db","era":"明治34年／明治後期・大正前期・大正13年増築・昭和中期改修","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積683㎡","structure_material":"木造2階一部3階建","registered":"2010.04.28(平成22.04.28)","register_no":"26 － 0343","desc":"当初は宮津湾に面した位置に建ち、建築面積６８３㎡、木造３階建、入母屋造桟瓦葺で、海側は開放的なつくりとする。東面の中央部を玄関とし、海側の北・西側に客室を配し、南側３階に百五畳敷の大広間をもつ広間棟を建てる。天橋立観光を支えてきた旅館である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008142"},{"id":"00001395","register_sub_id":"101","register_pk":"102385","name":"俵屋旅館","kana":"たわらやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区麸屋町通姉小路上る中白山町280","lat":35.0088436,"lng":135.76891839,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積283㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"26 － 0048","desc":"京都に現存する最古の旅館として知られる。禁門の変で焼失の後に再建された木造２階建の建物。玄関は麸屋町通りに面し，敷地の中には複数の中庭・外庭が全客室から見えるように配置される。洗練された数寄屋風建築に優雅さと風格が感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001395"},{"id":"00013420","register_sub_id":"101","register_pk":"368505","name":"茶又旅館主屋及び離れ","kana":"ちゃまたりょかんおもやおよびはなれ","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府舞鶴市字本小字本町38","lat":35.44845,"lng":135.32638333,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積207㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0607","desc":"旧田辺城下の町人地、竹屋町通に東面して建つ。木造二階建、桟瓦葺で、主屋の背面に離れが建ち、接続部を介して一体となる。外観は朱色の壁と二階の高欄付窓が特徴的で、主屋の一階には帳場、厨房や住居部、二階及び離れは客室を配す。戦後復興した旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013420"},{"id":"00013421","register_sub_id":"101","register_pk":"368506","name":"茶又旅館土蔵","kana":"ちゃまたりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府舞鶴市字本小字本町38他","lat":35.44850833,"lng":135.32626389,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0608","desc":"敷地の背面北寄り、高野川に面して建つ旅館の土蔵。土蔵造二階建、切妻造桟瓦葺東西棟で、東面の南隅に入口を設け、西面に各階二箇所の窓を穿つ。内部は各階一室で、一階は土間、二階は板敷とし、家財蔵として使用した。川沿いの景観を形成する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013421"},{"id":"00013422","register_sub_id":"101","register_pk":"368507","name":"茶又旅館門及び塀","kana":"ちゃまたりょかんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府舞鶴市字本小字本町38","lat":35.44847222,"lng":135.32644167,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"門 木造、瓦葺、間口2.0m、塀 木造、瓦葺、総延長13m","structure_material":"門 木造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0609","desc":"主屋の前面、道路境界に沿って建つ。門を塀のやや南寄りに開き、屋根は塀より一段高くする。柱上に棟木を渡し腕木で桁を支え、内側に荒い格子の両引分戸を建てる。塀は壁を朱色の漆喰塗腰高の竪板張とし、要所に飾格子付小窓を設ける。通りの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013422"},{"id":"00008141","register_sub_id":"101","register_pk":"132582","name":"茶六本館","kana":"ちゃろくほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府宮津市字魚屋866他","lat":35.53687273,"lng":135.1918386,"geo_status":"db","era":"大正期／昭和10年増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造3階建、瓦葺、建築面積259㎡","structure_material":"木造3階建","registered":"2010.04.28(平成22.04.28)","register_no":"26 － 0342","desc":"通りに西面して建つ木造３階建の旅館建築で、建築面積２５９㎡、屋根は桟瓦葺である。切妻造平入の当初部分と、入母屋造妻入の昭和増築部からなる特徴的な立面で、１階に出格子を付け、上階窓の高欄では室境に脇障子風の仕切りを設けるなど瀟洒な意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008141"},{"id":"00009189","register_sub_id":"101","register_pk":"164742","name":"月見館本館","kana":"つきみかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市伏見区桃山町泰長老160-4他","lat":34.92838535,"lng":135.77030348,"geo_status":"db","era":"昭和8年／昭和中期・昭和40年・平成期改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造地上3階地下1階建、瓦葺、建築面積679㎡","structure_material":"木造地上3階地下1階建","registered":"2012.02.23(平成24.02.23)","register_no":"26 - 0396","desc":"宇治川の北岸に位置する。木造3階地下1階建、建築面積679平方メートルで、東西棟と南北棟がＬ字形の主棟を構成する。屋根は桟瓦葺で千鳥破風を飾る。各階ともに、南面に窓を連続させ、観月の名所と知られる宇治川に望む。昭和初頭の旅館の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009189"},{"id":"00016676","register_sub_id":"101","register_pk":"579160","name":"鶴清","kana":"つるせ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区木屋町通松原下る二丁目下材木町451他","lat":34.99676,"lng":135.767826,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造地上3階地下1階建、瓦葺一部銅板葺、建築面積607㎡","structure_material":"木造地上3階地下1階建","registered":"2026.07.09(令和8.07.09)","register_no":"26 - 0741","desc":"鴨川右岸に建つ木造３階建の旅館。全体コの字平面で木屋町通りに面して玄関を構え、鴨川に面して入母屋造の大屋根の軒に切妻破風を飾る。３階大広間は148畳半で折上格天井を張る。小屋組は鉄骨のキングポスト・トラス。鴨川沿いの風情をつくる大規模旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016676"},{"id":"00014628","register_sub_id":"101","register_pk":"515170","name":"富美代大広間棟","kana":"とみよおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市東山区大和大路通四条上る二筋目東入末吉町103他","lat":35.00456944,"lng":135.77331667,"geo_status":"db","era":"昭和9年／昭和中期増築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"26 - 0653","desc":"主屋北側に建つ大広間棟。切妻造桟瓦葺の東西棟二階建で南は主庭、北は奥庭に臨む。一階は東に水廻り、西に座敷を配して北に入側縁を付す。二階は二間続きの大広間で西に床構え、北と南に入側縁を付す。大宴会も可能とした近代の時代相を良く示す大広間棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014628"},{"id":"00014627","register_sub_id":"101","register_pk":"515169","name":"富美代主屋","kana":"とみよおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区大和大路通四条上る二筋目東入末吉町103他","lat":35.0045,"lng":135.77334444,"geo_status":"db","era":"大正4年／昭和50年頃改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積207㎡","structure_material":"木造2階一部3階建","registered":"2023.08.07(令和5.08.07)","register_no":"26 - 0652","desc":"祇園北側の通りに南面する茶屋。主体部は二階建切妻造平入桟瓦葺で、北へ廊下を延ばして大広間棟と接続する。東の通り土間中央を玄関とし、西の床上部は坪庭廻りに中小の座敷を配する。伝統的外観ながら、各室への動線や採光に配慮した近代らしい茶屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014627"},{"id":"00003993","register_sub_id":"101","register_pk":"104983","name":"鳥彌三主屋","kana":"とりやさしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市下京区西石垣通四条下る斎藤町136他","lat":35.00209124,"lng":135.7703241,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積136㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"26 － 0163","desc":"鴨川右岸，西石垣通に西面する木造２階建の料亭。桁行７間梁間５間半の切妻造，平入で，左手２間分の大棟がわずかに低い。１階の通り土間沿いを厨房とし，２階を中心に大小の客間を配す。出格子や２階縁の格子組手摺など，多彩な格子が趣ある外観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003993"},{"id":"00003995","register_sub_id":"101","register_pk":"104985","name":"鳥彌三新座敷","kana":"とりやさしんざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市下京区西石垣通四条下る斎藤町136他","lat":35.00201935,"lng":135.77039502,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積27㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"26 － 0165","desc":"主屋の東裏手，中庭を介して，鴨川に面して建つ。南に中二階が続き，主屋とは２階南端の渡り廊下で接続する。１階は客室２室の間に土間通路を開き，夏季には川岸に仮設したユカへ至る。２階は広間で，川側に腰高の縁を設ける。鴨川縁の景観の一要素をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003995"},{"id":"00003994","register_sub_id":"101","register_pk":"104984","name":"鳥彌三中二階","kana":"とりやさちゅうにかい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市下京区西石垣通四条下る斎藤町136他","lat":35.00197222,"lng":135.77036402,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"26 － 0164","desc":"主屋の東裏手，鴨川に面して建つ。桁行１間半梁間２間の切妻造，桟瓦葺。新座敷に接続し，中庭から階段を昇った中２階高に６畳室を設け，妻側に奥行の浅いトコ，タナを備え，川側には腰高に縁を付ける。新座敷と軒高を違え，川岸の外観に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003994"},{"id":"00001283","register_sub_id":"101","register_pk":"102273","name":"冨田屋表蔵","kana":"とんだやおもてぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区大宮通元誓願寺下る二丁目石薬師町697他","lat":35.02736617,"lng":135.74889004,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建，瓦葺，建築面積35㎡","structure_material":"土蔵造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0042","desc":"主屋と並び、街路に面して建つ土蔵。角地であるため妻面と平面を街路に見せている。街路側には出入り口を設けず、腰から下を一枚板で飾る特徴的な外観を持つ。現在は内部が居室として利用され、角地に建つこともあってランドマーク的な役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001283"},{"id":"00001281","register_sub_id":"101","register_pk":"102271","name":"冨田屋主屋","kana":"とんだやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区大宮通元誓願寺下る二丁目石薬師町697他","lat":35.02742869,"lng":135.74882248,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造２階建，瓦葺，建築面積117㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0040","desc":"近世末期まで伏見で両替商を営んでいた所有者が、明治18年頃にこの地に移り織物問屋を創業して建てた建築である。間口約５間、奥行７間の大規模な表屋造で、明治期に京都市内に作られた大規模商家建築の好例ということができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001281"},{"id":"00001284","register_sub_id":"101","register_pk":"102274","name":"冨田屋中蔵","kana":"とんだやなかぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区大宮通元誓願寺下る二丁目石薬師町697他","lat":35.02744942,"lng":135.74866183,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造２階建，瓦葺，建築面積17㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0043","desc":"敷地の北端中央に立つ二階建ての土蔵。年代を示す資料はないが主屋と同時期と思われる。東の主屋側に扉を開き縁を廻して主屋、離れと連絡している。入口の上部には小規模ではあるが幾何学的模様の鏝絵を設けるなど、デザインにも工夫の跡が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001284"},{"id":"00001282","register_sub_id":"101","register_pk":"102272","name":"冨田屋離れ","kana":"とんだやはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区大宮通元誓願寺下る二丁目石薬師町697他","lat":35.02739938,"lng":135.74859607,"geo_status":"db","era":"昭和10代","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積89㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0041","desc":"昭和１０年代に敷地が西側に拡張されたのを受けて建築された。次の間を伴う離れ座敷と、応接間、茶室から構成され、南側に庭に面して縁を廻す。北側で宝蔵、中蔵と接しており、上層商家の建築構成を示すものとして欠くことのできないものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001282"},{"id":"00001285","register_sub_id":"101","register_pk":"102275","name":"冨田屋宝蔵","kana":"とんだやほうぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区大宮通元誓願寺下る二丁目石薬師町697他","lat":35.02745242,"lng":135.74855,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積26㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0044","desc":"昭和１０年の敷地拡張とほぼ同時に建築された土蔵である。中蔵と同じく東面に入口を設けている。扉の内側には屋号である富田屋を示す装飾を設け、扉上部には「宝蔵」と記している。明治期の上層商家の屋敷構成を知る上で欠くことのできない建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001285"},{"id":"00006544","register_sub_id":"101","register_pk":"107527","name":"中村治男家住宅主屋","kana":"なかむらはるおけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区室町通寺之内上る三丁目上柳原町117","lat":35.03542697,"lng":135.75834938,"geo_status":"db","era":"明治後期／昭和8改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階一部平屋建、瓦葺、建築面積151㎡","structure_material":"木造2階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0262","desc":"街路に西面して間口３間半の表屋を建て，坪庭を介して間口６間の居住棟を並置する表屋造の町家である。表屋の１階正面は右手に大戸，左手に出格子を設け，２階に虫籠窓を開く。居住棟は１・２階とも背面に８畳座敷と６畳次の間を設ける。京町家の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006544"},{"id":"00001286","register_sub_id":"101","register_pk":"102276","name":"西島家住宅主屋","kana":"にしじまけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区車屋町通夷川上る少将井御旅町352","lat":35.01566845,"lng":135.7602659,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造２階建，瓦葺，建築面積119㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0045","desc":"街路に東面して建つ中規模の町屋である。間口４間、奥行７間半の規模を持ち、１階の格子と犬矢来、２階の虫籠窓が外観を特徴づけている。通り土間を設けるなど標準的な表屋造の構成を示しており、明治期の商家の様子を今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001286"},{"id":"00001287","register_sub_id":"101","register_pk":"102277","name":"西島家住宅土蔵","kana":"にしじまけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市中京区車屋町通夷川上る少将井御旅町352","lat":35.015705,"lng":135.760452,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，瓦葺，建築面積33㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"26 － 0046","desc":"敷地の最も奥側、東端に建つ。妻面の大半を板張りとするほかは漆喰壁とし、西側に庇をさしかけて蔵前とする。桁行４間の規模を持ち、建ちが高いのが特徴。家伝によれば元治の大火以前の建築とされるが、少なくとも主屋以前の建造になる蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001287"},{"id":"00000357","register_sub_id":"101","register_pk":"101347","name":"日本生命京都三条ビル旧棟（旧日本生命京都支店）","kana":"にほんせいめいきょうとさんじょうびるきゅうとう（きゅうにほんせいめいきょうとしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区三条通高倉東入桝屋町75","lat":35.00876549,"lng":135.76390305,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造2階建，銅板葺，建築面積65㎡","structure_material":"煉瓦造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"26 － 0009","desc":"洋風の近代建築が多く立ち並ぶ三条通りに面して建つ。現在残るのは，明治４５年に着工，大正３年に竣工した社屋の通りに面した塔屋を含む１スパン部分である。設計は辰野片岡建築事務所で，外壁を石張りにする外観には，その作風がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000357"},{"id":"00003681","register_sub_id":"101","register_pk":"104671","name":"パビリオンコート（旧山中合名会社美術館）門","kana":"ぱびりおんこーと（きゅうやまなかごうめいがいしゃびじゅつかん）もん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区粟田口三条坊町14-2","lat":35.00792879,"lng":135.78264874,"geo_status":"db","era":"大正元／平成14移築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、鉄板葺、間口2.0m","structure_material":"木造","registered":"2003.12.01(平成15.12.01)","register_no":"26 － 0160","desc":"大正元年に，現在地の南側隣接地に離れ等と同時に建てられた。寺院等の旧材を利用して建てられた腕木門形式の門で，扉は七宝文装飾の両折戸とする。各部材は装飾・風蝕度合いなどから複数の建築から集められたと思われ，一部に鉄材も用いられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003681"},{"id":"00003679","register_sub_id":"101","register_pk":"104669","name":"パビリオンコート（旧山中合名会社美術館）洋館","kana":"ぱびりおんこーと（きゅうやまなかごうめいがいしゃびじゅつかん）ようかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区粟田口三条坊町14-2","lat":35.00805607,"lng":135.78238924,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造地上2階地下1階建、建築面積198㎡","structure_material":"煉瓦造地上2階地下1階建","registered":"2003.12.01(平成15.12.01)","register_no":"26 － 0158","desc":"古美術品の展示・収蔵施設として建てられた。設計は池村元之助，施工は清水組である。構造は壁体を煉瓦積とし，床をＲＣ造の梁とスラブでつくる。外観は昭和１１年に改修され，地上階部分がタイル貼となっている。ＲＣを用いた初期の建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003679"},{"id":"00003680","register_sub_id":"101","register_pk":"104670","name":"パビリオンコート（旧山中合名会社美術館）和館","kana":"ぱびりおんこーと（きゅうやまなかごうめいがいしゃびじゅつかん）わかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区粟田口三条坊町14-2","lat":35.00793107,"lng":135.78257046,"geo_status":"db","era":"明治37／昭和42移築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"26 － 0159","desc":"当初古美術品の陳列施設として建てられたものを，昭和４２年に現在地に移築したもの。木造平屋建，桟瓦葺で，舟肘木を用い，窓上部に菱形格子を巡らす。南側面上部は蟇股や欄間彫刻を飾る。現在では内部を改装し，喫茶店等に活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003680"},{"id":"00011149","register_sub_id":"101","register_pk":"205256","name":"林家住宅主屋","kana":"はやしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区今小路通七本松西入二丁目東今小路町751-4他","lat":35.029564,"lng":135.737213,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0500","desc":"間口四間奥行約五間半で、切妻造平入の総二階建。正面中央の三畳間から土間や居室部を経ずに離れと結び、二階の四畳半板間は踊りの舞台も兼ねるなど、お茶屋建築の特色ある平面構成である。二階の座敷はそれぞれ松と鶴を主題に意匠を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011149"},{"id":"00011150","register_sub_id":"101","register_pk":"205257","name":"林家住宅離れ","kana":"はやしけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区今小路通七本松西入二丁目東今小路町752-5他","lat":35.029413,"lng":135.73721,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造一部土蔵造平屋建、瓦葺、建築面積55㎡","structure_material":"木造一部土蔵造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0501","desc":"主屋背面に渡廊下を介して建つ。物置、納戸部分と客用の居室に分かれ、居室部分は五畳座敷と四畳半茶室を雁行させ、主屋との間の庭を眺めることができる。納戸部分は土蔵造。茶室を網代張に竿縁を放射状に配した傘天井とするなど、数寄屋風にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011150"},{"id":"00014186","register_sub_id":"101","register_pk":"508816","name":"柊家旅館本館及び塀","kana":"ひいらぎやりょかんほんかんおよびへい","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区麩屋町通姉小路上る中白山町274他","lat":35.01045556,"lng":135.76556111,"geo_status":"db","era":"明治前期／昭和28年増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造２階建、瓦葺、建築面積862㎡ 塀 木造、瓦葺、総延長40m","structure_material":"木造２階建","registered":"2022.02.17(令和4.02.17)","register_no":"26-0645","desc":"幕末大火後に建設された旅館で、増築による複雑な平面をもつ。入口は路地風に設え、玄関ホールから北と西へ廊下を延ばして客室を配す。客室はすべて数寄屋を基調とし、上下階で同平面となる二室も意匠を違えて趣を凝らす。中心市街の老舗旅館の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014186"},{"id":"00001117","register_sub_id":"101","register_pk":"102107","name":"富士ラビット","kana":"ふじらびっと","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区七条通新町西入夷之町721","lat":34.98911596,"lng":135.75660971,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造地上３階地下１階建，建築面積119㎡","structure_material":"鉄筋コンクリート造地上３階地下１階建","registered":"1999.06.07(平成11.06.07)","register_no":"26 － 0037","desc":"京都で自動車販売の草分けといわれる日光社の社屋として建てた３階建の商業ビル。社名の日光を象ったといわれる塔屋の意匠や古典的な柱のオーナメント、１階正面の自動車の描かれたステンドグラスなど様々な要素が混じり合った建物として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001117"},{"id":"00003441","register_sub_id":"101","register_pk":"104431","name":"船岡温泉旧船岡楼","kana":"ふなおかおんせんきゅうふなおかろう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区紫野南舟岡町82-1","lat":35.0369269,"lng":135.74448948,"geo_status":"db","era":"大正12頃／昭和5改造","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積194㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"26 － 0155","desc":"脱衣場，浴場の西方に隣接して建つ。木造，２階建で，玄関部，主棟，北棟からなる。主棟１階に小間，２階に広間を取り，北棟１，２階にも座敷を配す。目立った装飾はないが，客室床・棚回りや欄間，縁高欄等に瀟洒な意匠を凝らし旅館建築らしい佇まいを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003441"},{"id":"00003442","register_sub_id":"101","register_pk":"104432","name":"船岡温泉旧理髪店","kana":"ふなおかおんせんきゅうりはつてん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区紫野南舟岡町82-1","lat":35.03709328,"lng":135.7447169,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"26 － 0156","desc":"脱衣場北東に通りに面して建つ。木造，２階建で，正側面の２階壁面をモルタル塗で高く立ち上げたいわゆる看板建築。温泉の付属施設で，１階の表側に土間の店舗，その背後と２階に和室を配す。内部腰回りの装飾タイル，正側面壁頂部の蛇腹などに意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003442"},{"id":"00003439","register_sub_id":"101","register_pk":"104429","name":"船岡温泉脱衣場","kana":"ふなおかおんせんだついじょう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区紫野南舟岡町82-1","lat":35.03700838,"lng":135.7446409,"geo_status":"db","era":"大正12／昭和3改造","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"26 － 0153","desc":"料理旅館船岡楼の付属浴場として建設された施設の１つ。木造２階建で，１階は表に玄関・番台，奥に脱衣場を配し，２階に和室２室を取る。欄間・天井に奇抜な木彫を飾る内部や，昭和３年新設の軒唐破風のある鞍馬口通側外観など，市民に親しまれた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003439"},{"id":"00003440","register_sub_id":"101","register_pk":"104430","name":"船岡温泉浴場","kana":"ふなおかおんせんよくじょう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市北区紫野南舟岡町82-1","lat":35.03687224,"lng":135.74468214,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積121㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"26 － 0154","desc":"創業当初の煉瓦造浴場を建て替えたもの。ＲＣ造，平屋建で，脱衣場に続く廊下と男女浴場（後方は旧焚場）からなる。一段切上げた採光部に丸窓を明け，千本鞍馬口にあった菊水橋の石造欄干を転用し，内部を装飾タイルで飾るなど，奇抜な造形が親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003440"},{"id":"00009331","register_sub_id":"101","register_pk":"194124","name":"鮒鶴新館","kana":"ふなつるしんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市下京区東木屋町通松原上る美濃屋町182-1他","lat":34.99922545,"lng":135.76875974,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄骨造4階地下1階建、鉄板葺、建築面積278㎡","structure_material":"鉄骨造4階地下1階建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0404","desc":"本館の南に接続する鉄骨造四階建。緩勾配の入母屋造鉄板葺で破風を川側に見せる。川側三階までは縁と手摺で本館と意匠を揃え、三階庇上に唐破風を飾る。西側の三階建突出部はスクラッチタイル張で洋風の意匠も取入れる。近代の新構造に和風意匠をまとう。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009331"},{"id":"00009330","register_sub_id":"101","register_pk":"194123","name":"鮒鶴本館","kana":"ふなつるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市下京区東木屋町通松原上る美濃屋町182-1他","lat":34.99931289,"lng":135.76886622,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造3階一部4階地下1階建、鉄板葺、建築面積273㎡、塔屋付","structure_material":"木造3階一部4階地下1階建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0403","desc":"鴨川右岸に建つ木造三階建で、建築面積二七三平方メートル、木屋町通に玄関を構え、川側客室は縁の手摺で飾る。急勾配の屋根上にパラペットを廻らせ。四階屋根上に入母屋造の塔屋を設ける。地下にアールデコ意匠のダンスホールを持つ、近代の大規模和風料亭。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009330"},{"id":"00009332","register_sub_id":"101","register_pk":"194125","name":"鮒鶴南門","kana":"ふなつるみなみもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市下京区東木屋町通松原上る美濃屋町182-1他","lat":34.99924151,"lng":135.76856046,"geo_status":"db","era":"昭和7年頃／平成13年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造、瓦葺、間口2.1m、左右袖塀付","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0405","desc":"木屋町通の新館玄関前に開く腕木門で、起り付の切妻造桟瓦葺とする。コンクリート基礎に立つ親柱は円柱で、門口は二・一メートル、上部に鶴に松の欄間彫刻を飾る。両脇の袖塀は門破風板の拝部まで立ち上げ、漆喰塗の腰を杉皮張とする。料亭入口の瀟洒な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009332"},{"id":"00005284","register_sub_id":"101","register_pk":"106272","name":"文椿ビルヂング（旧西村貿易店社屋）","kana":"ふみつばきびるぢんぐ（きゅうにしむらぼうえきてんしゃおく）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区三条通烏丸西入御倉町79","lat":35.00870507,"lng":135.75890862,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、銅板葺及びスレート葺、建築面積185㎡、地下室付","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"26 － 0208","desc":"木造２階建の事務所建築で，小屋組をキングポストトラスとし，銅板及びスレート葺のマンサード屋根を架ける。外壁はタイル張で，南面中央の入口部は８角断面を半割した片蓋柱で飾る。三条通と両替町通が交差する角地にあり，地域の近代的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005284"},{"id":"00003109","register_sub_id":"101","register_pk":"104099","name":"フランソア喫茶室","kana":"ふらんそあきっさしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市下京区西木屋町通四条下る船頭町184","lat":35.00334066,"lng":135.77020693,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"26 － 0141","desc":"繁華街木屋町にある喫茶店で，木造２階建の伝統的な長屋を洋風に改築したもの。今回の登録は昭和１６年改築の北半部分。設計は当時京大に留学していたイタリア人のベンチベニ氏で，京都の知識人のサロンとして長年親しまれてきた。内装や家具も良く残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003109"},{"id":"00010836","register_sub_id":"101","register_pk":"201671","name":"松村家住宅主屋","kana":"まつむらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区六角通烏丸西入骨屋町155","lat":35.007508,"lng":135.759099,"geo_status":"db","era":"明治42／昭和10頃・同中期改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積311㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"26 ‐ 0492","desc":"六角通に南面する間口八間半の表屋造町家。表屋は上下階とも窓を並べ、西端の落棟部に虫籠窓を穿つ。住居部二階には、良材による洗練された意匠の造作を持つ大広間や茶室を配し、京町家として異色の接客空間を備える。鉾町に残る大型で上質な町家として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010836"},{"id":"00010837","register_sub_id":"101","register_pk":"201672","name":"松村家住宅土蔵","kana":"まつむらけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市中京区六角通烏丸西入骨屋町155","lat":35.007651,"lng":135.758992,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"26 ‐ 0493","desc":"主屋北西側、中庭の奥に南北棟で建つ。桁行七・八メートル梁間五・九メートル、土蔵造二階建、切妻造本瓦葺で、一階南妻の戸口に庇を付す。外壁漆喰塗で鉢巻を廻らし、腰を竪板張、二階南面には瓦庇の窓を穿つ。旧は反物を納めた土蔵で、庭空間を引立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010837"},{"id":"00004593","register_sub_id":"101","register_pk":"105583","name":"家邊徳時計店（家邊家住宅）店舗","kana":"やべとくとけいてん（やべけじゅうたく）てんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区三条通富小路東入中之町25","lat":35.00854896,"lng":135.7652399,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積107㎡","structure_material":"煉瓦造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0193","desc":"街路に北面して建つ煉瓦造２階建の店舗建築で，内部には金庫室や螺旋階段がある。１階は３連アーチを飾り，２階をセットバックさせる。エンタブレチュア，隅石に加え，豊かな装飾細部を随所に配す。三条通の近代的な町並景観の核として，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004593"},{"id":"00006540","register_sub_id":"101","register_pk":"107523","name":"山中油店主屋","kana":"やまなかあぶらてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区下立売通智恵光院西入下丸屋町508","lat":35.020157,"lng":135.745865,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積326㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0258","desc":"下立売通に南面する間口９間の平屋建町家。切妻造，桟瓦葺で表裏に庇が付き，北に落棟が続く。正面にはバッタリ床几と蔀，出格子，飾り窓を設け，つし２階に虫籠窓を開く。西半が通り土間，東半が２列の居室で，北奥に１０畳座敷を配す。京町家の典型として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006540"},{"id":"00000138","register_sub_id":"101","register_pk":"101128","name":"レストラン菊水","kana":"れすとらんきくすい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区川端通四条上る川端町187","lat":35.00397799,"lng":135.77319049,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造地上5階地下1階建塔屋付，建築面積203㎡","structure_material":"鉄筋コンクリート造地上5階地下1階建塔屋付","registered":"1997.05.07(平成9.05.07)","register_no":"26 － 0002","desc":"京都における西欧料理の草分け的な存在である菊水の店舗で，ＲＣ造，５階建ての正面に塔屋が付く。建物の様式は表現主義を基調とし，内外に様々な新様式を取り入れ見事にまとめている。内部は改装されているが，大正期の京都の新建築活動の規範的作品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000138"},{"id":"00004144","register_sub_id":"101","register_pk":"105134","name":"嶋臺巽蔵","kana":null,"category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区御池通烏丸東入仲保利町191","lat":35.01107891,"lng":135.76088898,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"26 － 0170","desc":"御池通に面して建つ土蔵。３間四方の平面で，東と北の酒店側に扉口を開く。外観は腰縦板張，上部は漆喰塗とし，軒まで塗込め，屋根は本瓦葺である。内部は１階・２階とも柱を現し，いずれも一室とする。京都の近代初頭の景観を今日に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004144"},{"id":"00004141","register_sub_id":"101","register_pk":"105131","name":"嶋臺絲店","kana":null,"category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区御池通烏丸東入仲保利町191","lat":35.01108892,"lng":135.76068486,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造2階建、瓦葺、建築面積113㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"26 － 0167","desc":"御池通りに南面して建つ。切妻造，桟瓦葺，平入で，西側を一段高く葺く。正面には庇をかけ，出格子を設ける。庇上の壁面は土壁とし，横長の虫籠窓を設けている。平面ほぼ中央南北に土間を通し，１階はその両脇を広い２室とする。近代初頭京町屋の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004141"},{"id":"00004142","register_sub_id":"101","register_pk":"105132","name":"嶋臺酒店","kana":null,"category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区御池通烏丸東入仲保利町191","lat":35.0111261,"lng":135.76093726,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造2階建、瓦葺、建築面積80㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"26 － 0168","desc":"敷地の南東隅に建ち，東街路側を正面とする。平面は巽蔵を囲むＬ字型で，総土間とする。１階正面は連子格子を設け，南寄りに入り口を開く。庇上は土壁とし，虫籠窓を開く。御池通に面した妻面は上部白漆喰塗とし，巽蔵と連続する景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004142"},{"id":"00007663","register_sub_id":"101","register_pk":"108645","name":"石賀本店土蔵","kana":"いしがほんてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県米子市法勝寺町22他","lat":35.42722138,"lng":133.33419086,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積104㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0147","desc":"南北に細長い敷地の南端に建ち、米子城旧外堀に面していた。桁行２０ｍ梁間６．０ｍの土蔵造２階建、東西棟の切妻造とし、北面に庇を通し、赤瓦を葺く。西から塗物蔵、米蔵、唐津蔵、倉庫の４室を設け、東寄りに石段の通用口を開く。旧外堀沿いの面影を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007663"},{"id":"00010500","register_sub_id":"101","register_pk":"199448","name":"植田家住宅主屋","kana":"うえだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県境港市末広町82","lat":35.546891,"lng":133.231548,"geo_status":"db","era":"明治中期／昭和58改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積76㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"31 － 0202","desc":"境港の市街地中心部で通りに東面して建つ、もと履物屋の町家建築。木造二階建、切妻造桟瓦葺で正面に下屋を設ける。平面は北側に土間を通し、床上部は居室を二列に配し、正面中央を玄関とする。赤色瓦が地方的特色を示し、通りに落ち着いた佇まいをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010500"},{"id":"00010501","register_sub_id":"101","register_pk":"199449","name":"植田家住宅離れ","kana":"うえだけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"鳥取県","address":"鳥取県境港市末広町82","lat":35.546823,"lng":133.231402,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"31 － 0203","desc":"主屋の西方に渡廊下を介して建つ。木造平屋建で下屋を廻らし、赤色瓦を葺く。内部は十畳と八畳の二室からなり、いずれも高く棹縁天井を張り、長押を廻らし、透彫欄間を飾る。軸部も、吟味した良質な材で建てられており、格調高い上質な空間を創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010501"},{"id":"00010047","register_sub_id":"101","register_pk":"196194","name":"面谷家住宅旧砂糖蔵","kana":"おもたにけじゅうたくきゅうさとうぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県境港市花町8","lat":35.54712588,"lng":133.24126217,"geo_status":"db","era":"明治後期／昭和19改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"31 － 0190","desc":"店舗兼主屋の南に棟を連ねて建つ。土蔵造二階建、切妻造桟瓦葺で、西正面及び南面は腰を竪板張、上部を漆喰塗とし、西面には出窓と格子窓を穿つ。内部は二室に分かれ、南を土間、北を洋間とする。土間部は二階に部屋を設ける。敷地南西隅の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010047"},{"id":"00010045","register_sub_id":"101","register_pk":"196192","name":"面谷家住宅新座敷（旧精米所）","kana":"おもたにけじゅうたくしんざしき（きゅうせいまいじょ）","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県境港市花町8","lat":35.54733186,"lng":133.24144939,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積53㎡","structure_material":"土蔵造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"31 － 0188","desc":"敷地の北、道具蔵の東に建つ土蔵で、元は精米所と伝えるが現在は座敷に改修されている。西から六畳、四畳半茶室、水屋を並べ、茶室北に小間を配す。茶室のトコはトコ柱に古材を用いる。南面は障子をたて縁を付す。大正期の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010045"},{"id":"00010044","register_sub_id":"101","register_pk":"196191","name":"面谷家住宅店舗兼主屋","kana":"おもたにけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県境港市花町8","lat":35.54723587,"lng":133.24131791,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、瓦葺、建築面積180㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"31 － 0187","desc":"島根県との県境、境水道南側の通りに西面して建つ、間口一〇間に及ぶ町家。切妻造桟瓦葺で前後に下屋を設け、つし部分は漆喰塗込とし虫籠窓を穿つ。平面は南端を土間、床上部は六間取とし、北東隅の座敷に座敷飾を備える。境港に残る数少ない醸造家の遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010044"},{"id":"00010046","register_sub_id":"101","register_pk":"196193","name":"面谷家住宅道具蔵","kana":"おもたにけじゅうたくどうぐくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県境港市花町8","lat":35.54734649,"lng":133.24133862,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"31 － 0189","desc":"主屋北に隣接し、道路に妻面を向けて建つ。土蔵造二階建、切妻造桟瓦葺で、店舗兼主屋側に出入口を設け、両開きの鉄扉を付す。西正面は腰高の簓子下見板張、上部を漆喰塗とし小窓を三箇所開け、他面は竪板張とする。主屋とともに屋敷の正面構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010046"},{"id":"00008161","register_sub_id":"101","register_pk":"132602","name":"木屋旅館","kana":"きやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県東伯郡三朝町大字三朝895他","lat":35.41023856,"lng":133.89429664,"geo_status":"db","era":"明治期／大正8年・昭和29年・昭和33年増築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階一部3階地下1階建、鉄板葺、建築面積516㎡","structure_material":"木造2階一部3階地下1階建","registered":"2010.04.28(平成22.04.28)","register_no":"31 － 0158","desc":"三朝温泉中心部の河畔に建つ旅館で、建築面積５１６㎡、木造２階建一部３階建、桟瓦葺及び鉄板葺で、地階に浴室を設ける。各客室は意匠を凝らし、外部は各階に庇を付け、窓に高欄を付ける。温泉街の発展とともに増築を重ね、複雑で特徴的な外観を造り上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008161"},{"id":"00012621","register_sub_id":"101","register_pk":"367915","name":"旧小倉家住宅主屋","kana":"きゅうおぐらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県倉吉市河原町2884","lat":35.429565,"lng":133.812912,"geo_status":"geocoded","era":"昭和11年／昭和50年頃改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積114㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0255","desc":"市中心部西方の旧八橋往来沿いにある商家で、主屋は通りに北面して建つ。切妻造桟瓦葺の総二階建で、正面に下屋を付す。伝統形式を継承するが、たちの高いつくりで、正面二階の大きな掃出し窓、硝子窓桟の割付、手摺の意匠などに昭和前期の傾向が現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012621"},{"id":"00012622","register_sub_id":"101","register_pk":"367916","name":"旧小倉家住宅土蔵","kana":"きゅうおぐらけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県倉吉市河原町2884","lat":35.429565,"lng":133.812912,"geo_status":"geocoded","era":"大正5年頃／昭和50年頃改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0256","desc":"主屋の背面に近接して建つ。土蔵造二階建、南北棟の切妻造で、北面西寄りに戸口を開く。外壁は漆喰塗で小路に面する西面は階境に庇を通す。内部は上下階とも板敷で、和小屋を組む。旧八橋往来と川が交差する角地にあって商家町の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012622"},{"id":"00015372","register_sub_id":"101","register_pk":"532496","name":"旧山陰合同銀行根雨支店店舗","kana":"きゅうさんいんごうどうぎんこうねうしてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県日野郡日野町根雨字屋敷466","lat":35.23773889,"lng":133.44182778,"geo_status":"db","era":"昭和2年／昭和54年頃改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積126㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"31 - 0298","desc":"出雲街道に東面する銀行店舗。木造寄棟造鉄板葺で、内部の正面側は吹抜で天井を折り上げ、中心飾を付す。正面は大オーダーの付柱を並べ、窓廻りをタイル貼、軒にコーニス廻らし、中央にペディメントを立上げレリーフを付す。昭和初期らしい外観の銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015372"},{"id":"00002089","register_sub_id":"101","register_pk":"103079","name":"旧塩屋出店主屋","kana":"きゅうしおやでみせしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭545","lat":35.26986531,"lng":134.22914504,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"31 － 0037","desc":"宿場町として栄えた智頭町の中心地近くに位置し，智頭街道に突き当たる街路に西面して建つ。木造２階建，切妻造，平入の町屋で，長大な正面のほぼ中央に玄関を置き，その北側をカミテ，南側をシモテとする。正面２階のたちが低く古式を感じさせる点に特色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002089"},{"id":"00002092","register_sub_id":"101","register_pk":"103082","name":"旧塩屋出店外塀","kana":"きゅうしおやでみせそとべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭545","lat":35.26996616,"lng":134.22918762,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造、瓦葺、延長9.9m","structure_material":"木造","registered":"2000.12.04(平成12.12.04)","register_no":"31 － 0040","desc":"主屋の北西端に発し，敷地北西端で東方に回り込み敷地北辺を限る塀。街道に沿った部分は腕木門風のつくりで，中央に門を開ける。敷地北辺の部分は瓦葺の屋根を載せた真壁造の土塀で，主屋北妻面との間に客用玄関口を形づくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002092"},{"id":"00000081","register_sub_id":"101","register_pk":"101071","name":"協同組合倉吉大店会（旧第三銀行倉吉支店）","kana":"きょうどうくみあいくらよしだいてんかい（きゅうだいさんぎんこうくらよししてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市魚町2540-1","lat":35.43163287,"lng":133.82646344,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積179㎡","structure_material":"土蔵造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"31 － 0001","desc":"倉吉の旧街道｢倉吉往来｣に面して建つ明治期の疑洋風建築の好例。当初第三銀行の支店として建造され，その後いくつかの金融機関を経て，現在は事務所として使用されている。旧往来に面した角地にあって，倉吉の中心街の明治期の様子を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000081"},{"id":"00008052","register_sub_id":"101","register_pk":"128883","name":"五臓圓ビル","kana":"ごぞうえんびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市二階町2-207","lat":35.50151721,"lng":134.23064801,"geo_status":"db","era":"昭和6／昭和中期・昭和55・平成9改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積119㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2010.01.15(平成22.01.15)","register_no":"31-0156","desc":"角地に建つ鉄筋コンクリート造３階建、建築面積１１９㎡で、陸屋根とする。外壁はスクラッチタイル貼で、北隅を四分一円弧の曲面として上下に額縁を付し、パラペットも高めて隅部を強調する。鳥取市内で現存最古の本格的な鉄筋コンクリート造建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008052"},{"id":"00016432","register_sub_id":"101","register_pk":"536499","name":"坂江家住宅店舗兼主屋","kana":"さかえけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県米子市灘町一丁目65","lat":35.43353611,"lng":133.32365,"geo_status":"db","era":"安政6年（1859）／明治24年・昭和中期改修","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"31 - 0300","desc":"加茂川河口の北側に位置し、かつて油屋を営んだ店舗兼主屋。間口二間、奥行九間、二階建切妻造平入桟瓦葺で二階の腰を海鼠壁とする。通り土間沿いにミセ、中の間、仏間、居間を一列に並べ、二階奥に八畳の座敷を配す。間口狭く、米子城下に残る貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016432"},{"id":"00016433","register_sub_id":"101","register_pk":"536500","name":"坂江家住宅土蔵","kana":"さかえけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県米子市灘町一丁目65","lat":35.43369722,"lng":133.32363333,"geo_status":"db","era":"明治5年","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積11㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"31 - 0301","desc":"主屋の北に中庭を挟んで位置する家財蔵。間口一間半、奥行二間半、土蔵造二階建、切妻造妻入桟瓦葺。外壁は白漆喰塗仕上で、腰は海鼠壁とする。内部は各階一室の板敷とし、柱、棟木、垂木の材は木太く、良材を用いた竪板張など、全体に良質なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016433"},{"id":"00006359","register_sub_id":"101","register_pk":"107342","name":"山陰民具店舗兼主屋","kana":"さんいんみんぐてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県倉吉市西岩倉町2196","lat":35.43244374,"lng":133.81764937,"geo_status":"db","era":"江戸後期／明治後期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階一部平屋建、瓦葺一部茅葺（鉄板仮葺）、建築面積119㎡","structure_material":"木造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"31 － 0111","desc":"倉吉市街西部の西岩倉通の北側に位置する。間口５間、奥行６間半の平入町家である。表を瓦葺の２階建に改修しており、元の茅葺屋根を背面に残し、鉄板仮葺とする。内部は東半が幅の広い通り土間、西に１列３室の居室を配す。茅葺町家の歴史を伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006359"},{"id":"00006278","register_sub_id":"101","register_pk":"107262","name":"高砂屋（城下町とっとり交流館）店舗棟","kana":"たかさごや（じょうかまちとっとりこうりゅうかん）てんぽとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市元大工町1","lat":35.4989019,"lng":134.23702769,"geo_status":"db","era":"明治後期／平成16曳家","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積135㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"31 － 0104","desc":"街道沿いに建つ商家建築。店舗棟と住居棟を東西に並べて配置する。店舗棟は、建築面積１３５㎡、木造２階建，桟瓦葺。間口一杯の差鴨居や太い柱を組んで、広い土間と帳場による店空間をつくる。特に土間の松梁は成があり長大で、往時の繁栄ぶりを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006278"},{"id":"00012012","register_sub_id":"101","register_pk":"210953","name":"東光園本館","kana":"とうこうえんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"鳥取県","address":"鳥取県米子市皆生温泉三丁目2155他","lat":35.457319,"lng":133.364932,"geo_status":"db","era":"昭和39年／平成3年改修","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄骨鉄筋コンクリート造7階建地下1階、建築面積761㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造7階建地下1階","registered":"2017.10.27(平成29.10.27)","register_no":"31-231","desc":"海岸に面して建つ鉄骨鉄筋コンクリート造地下一階地上七階建のホテル。六本の主柱が七階部分を支え、そこから五、六階の客室部を吊る構造で、各階とも異なる平面を実現している。階段部分などにも秀逸な構造デザインを見せる。メタボリズム建築の集大成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012012"},{"id":"00005490","register_sub_id":"101","register_pk":"106478","name":"豊田家住宅（久米郡倉吉驛）主屋","kana":"とよたけじゅうたく（くめごおりくらよしえき）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市西町2701","lat":35.43194737,"lng":133.8203568,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積118㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0095","desc":"東西に通る街路に北面して建つ。切妻造，桟瓦葺，平入，木造２階建で，正面は出桁造とする。構造は真壁造，正面外壁は鼠漆喰塗とし，２階開口部に手摺を設ける。倉吉の伝統的な町家形式を保持しており，打吹玉川保存地区に連なる町並み景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005490"},{"id":"00005491","register_sub_id":"101","register_pk":"106479","name":"豊田家住宅（久米郡倉吉驛）離れ","kana":"とよたけじゅうたく（くめごおりくらよしえき）はなれ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"鳥取県","address":"鳥取県倉吉市西町2701","lat":35.43201122,"lng":133.82036389,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積51㎡、渡廊下付","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0096","desc":"南北に細長い敷地の南寄りにあり，前方の主屋と渡廊下で接続している。東西棟の切妻造，桟瓦葺，平入，２階建で，１階，２階とも床・棚を備えた６畳間とする。各所に上質の材を用い，床の間廻りは特に凝ったつくりで，昭和初期の熟達した和風の造形が窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005491"},{"id":"00002298","register_sub_id":"101","register_pk":"103288","name":"米子専門大店","kana":"よなごせんもんだいてん","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県米子市道笑町1-111","lat":35.426682,"lng":133.335648,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積225㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2001.08.28(平成13.08.28)","register_no":"31 － 0041","desc":"市内中心部，道路の角地にたつ。鉄筋コンクリート造３階建で，縦長上げ下げ窓を街路側に配し，頂部に菱形の浮き彫りを施した付け柱をもつ石造風壁面からなる。米子銀行記章付の山型パラペットの下にデンティルを廻す。米子で最初の貸ビルで，原八十吉の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002298"},{"id":"00000360","register_sub_id":"101","register_pk":"101350","name":"旅館大橋大広間棟","kana":"りょかんおおはしおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町三朝302","lat":35.41182651,"lng":133.89107231,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建，瓦葺，建築面積214㎡","structure_material":"木造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"31 － 0020","desc":"温泉旅館を構成する建物の一つ。三徳川に沿って建ち並ぶ本館と離れの間に建つ。大規模な木造２階建の建物で，１階は厨房とし２階を大広間とする。左右一対の千鳥破風をつけた大屋根は，特徴的である。近年内部は改修されたが、外観は旧状を良く保っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000360"},{"id":"00000362","register_sub_id":"101","register_pk":"101352","name":"旅館大橋太鼓橋","kana":"りょかんおおはしたいこばし","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町三朝302","lat":35.41197358,"lng":133.89027844,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造，瓦葺，建築面積23㎡","structure_material":"木造","registered":"1997.11.05(平成9.11.05)","register_no":"31 － 0022","desc":"本館と西離れを繋ぐ廊下で，公道から川岸に通じる通路をまたぐ太鼓橋に切妻造の上屋をかけた形式になる。本体部は円弧型の橋桁やや高欄をつけるなど本格的な造りとなる。道路側には橋の両端に灯明が付くなど凝った造作になり，温泉情緒を盛り上げている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000362"},{"id":"00000361","register_sub_id":"101","register_pk":"101351","name":"旅館大橋西離れ","kana":"りょかんおおはしにしはなれ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町三朝302","lat":35.41191355,"lng":133.8901944,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建一部2階，瓦葺，建築面積68㎡","structure_material":"木造平屋建一部2階","registered":"1997.11.05(平成9.11.05)","register_no":"31 － 0021","desc":"本館の右手に独立して建つ和風の建物で，本館とは太鼓橋で結ばれる。１階部分は露天風呂への脱衣室，２階は管理室となる。三徳川の下流側にあり，三角形の開口部や小庇，手摺等で外観を飾る。本館や離れ等とともに旅館建物の一つとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000361"},{"id":"00000310","register_sub_id":"101","register_pk":"101300","name":"旅館大橋離れ","kana":"りょかんおおはしはなれ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町三朝302","lat":35.41172244,"lng":133.89113853,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造3階建，瓦葺，建築面積312㎡","structure_material":"木造3階建","registered":"1997.09.03(平成9.09.03)","register_no":"31 － 0019","desc":"本館の左手に接続する和風の建物。入母屋造３階建の建屋と寄棟造２階建の建屋からなるが，一体として使用される。客室はやや広めで，各客室は本館同様に意匠を凝らした上品な造りになる。三徳川沿いに展開する雄姿は，三朝温泉の象徴的な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000310"},{"id":"00000309","register_sub_id":"101","register_pk":"101299","name":"旅館大橋本館","kana":"りょかんおおはしほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町三朝302","lat":35.41189274,"lng":133.89057559,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造3階建，瓦葺，建築面積625㎡","structure_material":"木造3階建","registered":"1997.09.03(平成9.09.03)","register_no":"31 － 0018","desc":"大橋旅館は三朝温泉郷の老舗温泉旅館の一つで，三徳川に沿って本館や離れ等が軒を連ねている。本館は，木造３階建になり，１階正面左手に玄関を設け，各階に意匠を凝らした上品な客室を配する。優雅な和風の外観は，三朝温泉の歴史と伝統を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000309"},{"id":"00010991","register_sub_id":"101","register_pk":"208961","name":"カラコロ工房（旧日本銀行松江支店）","kana":"からころこうぼう（きゅうにほんぎんこうまつえしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市殿町43","lat":35.470367,"lng":133.053441,"geo_status":"db","era":"昭和13／昭和56・平成12改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積633㎡、塔屋、煙突及び塀付","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2016.02.25(平成28.02.25)","register_no":"32-0178","desc":"長野宇平治の設計で昭和一三年に完成した。鉄筋コンクリート造三階建、地下一階で、塔屋と煙突を有する。外観はギリシャ神殿風の意匠でまとめ、営業室と客溜は吹き抜けの大空間で、地下は金庫室である。当初形式をよく保持し、地域の核として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010991"},{"id":"00008356","register_sub_id":"101","register_pk":"133998","name":"河田商店奥の蔵","kana":"かわだしょうてんおくのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田ロ197・ロ198-内1・ロ200-内1合併、ハ37-1、ロ72・ロ73・ロ74-1合併2、ロ72-3","lat":34.46810931,"lng":131.77375384,"geo_status":"db","era":"明治後期／昭和前期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0148","desc":"庭の蔵の西に東西棟で建つ。桁行５．９ｍ梁間５．９ｍ、切妻造桟瓦葺の２階建土蔵で、南面を葺き降ろして蔵前とする。１階は二室、２階は一室で、２階には蔵前から入る。腰板張で、蔵前も含めて大壁造で塗り込める。装飾のない、質実な蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008356"},{"id":"00008353","register_sub_id":"101","register_pk":"133995","name":"河田商店店舗兼主屋","kana":"かわだしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田ロ197・ロ198-内1・ロ200-内1合併、ハ37-1、ロ72・ロ73・ロ74-1合併2、ロ72-3","lat":34.467937,"lng":131.77393671,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積217㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0145","desc":"東の通りと、南の小路に画される敷地の東端に位置する。間口９．９ｍの木造つし２階建、切妻造桟瓦葺の平入町家で、北面に落棟で座敷や仏間を付設する。壁は大壁で、正面は大きく開口を穿ち、小路側は庇付の窓を三ヶ所穿つ。骨太で剛直な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008353"},{"id":"00008355","register_sub_id":"101","register_pk":"133997","name":"河田商店庭の蔵","kana":"かわだしょうてんにわのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田ロ197・ロ198-内1・ロ200-内1合併、ハ37-1、ロ72・ロ73・ロ74-1合併2、ロ72-3","lat":34.46806711,"lng":131.77382418,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0147","desc":"主屋の西方、庭を挟んだ位置に南北棟で建つ。桁行８．８ｍ梁間４．７ｍの２階建土蔵。切妻造で、桟瓦を葺く。壁は腰竪板張の漆喰仕上げで、南面に庇付の窓を上下に設ける。庭側の東面は腰を海鼠壁とし、出入口を開け、桟瓦葺庇を付け、庭園景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008355"},{"id":"00008354","register_sub_id":"101","register_pk":"133996","name":"河田商店離れ","kana":"かわだしょうてんはなれ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田ロ197・ロ198-内1・ロ200-内1合併、ハ37-1、ロ72・ロ73・ロ74-1合併2、ロ72-3","lat":34.46804601,"lng":131.77390857,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積22㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0146","desc":"主屋の西北に東西棟で建つ。桁行７．２ｍ梁間３．３ｍの木造２階建で南面に縁を付設する。切妻造桟瓦葺で、東妻面は下屋を付け、妻を大壁で塗り込め、土蔵風に見せる。庭に南面し、１階に二室、２階に一室配し、２階はトコや棚、平書院を設ける書院座敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008354"},{"id":"00008357","register_sub_id":"101","register_pk":"133999","name":"河田商店本蔵","kana":"かわだしょうてんほんぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田ロ197・ロ198-内1・ロ200-内1合併、ハ37-1、ロ72・ロ73・ロ74-1合併2、ロ72-3","lat":34.468038,"lng":131.77367899,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0149","desc":"敷地の南辺、主屋角屋の西に続く。桁行１４ｍ梁間５．９ｍの土蔵造２階建。切妻造桟瓦葺で、東寄りの棟を一段下げる。内部は東寄りと西側に大きく分かれる。石積基礎に建ち、腰海鼠壁とする漆喰仕上げで、要所に開口を設ける。主屋と一連で街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008357"},{"id":"00014085","register_sub_id":"101","register_pk":"508345","name":"旧濱中屋船宿（福間館別館）","kana":"きゅうはまなかやふなやど（ふくまかんべっかん）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県松江市美保関町美保関296","lat":35.56142222,"lng":133.31142222,"geo_status":"db","era":"明治44年頃","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"32 - 0214","desc":"美保関東端の通りに南面する船宿。二階建切妻造桟瓦葺で軒は出桁造。内部は東に通り土間、西に一列二室を配し、二階は前後に三室配置。出桁や木鼻付持送など美保関の町家の特徴を示す。二階の建ちの高い整った座敷から湾を眺望でき、船宿の特徴をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014085"},{"id":"00008339","register_sub_id":"101","register_pk":"133981","name":"旧布施時計店店舗兼主屋","kana":"きゅうふせとけいてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ192-1","lat":34.46858669,"lng":131.77468575,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積139㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0131","desc":"通りに西面する木造２階建、桟瓦葺。正面１階を店舗、２階及び背面を住居として建設。正面側はパラペットを立ち上げ、モルタル仕上げとし、２階角に大きく窓を切り欠き、要所に円窓を開ける。１階入口にはショウウインドウが残る。伝統的な町並に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008339"},{"id":"00002980","register_sub_id":"101","register_pk":"103970","name":"旧米江旅館本館北棟","kana":"きゅうよねえりょかんほんかんきたとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市伊勢宮町535","lat":35.465717,"lng":133.059967,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"32 － 0011","desc":"松江城下の市街地にある老舗の旅館建築。敷地北側の街路に面して建つ北棟は，切妻造・平入の２階建で，入母屋造の玄関を設ける。２階を客室６室とするが，各室ごとに良質の銘木・珍木を用い趣向を凝らした座敷飾を整え，当時の和風建築のあり様を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002980"},{"id":"00002981","register_sub_id":"101","register_pk":"103971","name":"旧米江旅館本館南棟","kana":"きゅうよねえりょかんほんかんみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市伊勢宮町535","lat":35.46558,"lng":133.060028,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造一部鉄筋コンクリート造2階建、瓦葺、建築面積124㎡","structure_material":"木造一部鉄筋コンクリート造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"32 － 0012","desc":"松江城下の市街地にある老舗の旅館建築。敷地南側の街路に面して建つ南棟は，切妻造・平入の２階建で，１階を食堂と茶室，２階を客室３室とする。２階１５畳の広間は折上格天井で，繊細な付書院を備える。よく吟味した材料を用い，瀟洒な造形にまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002981"},{"id":"00010688","register_sub_id":"101","register_pk":"201262","name":"ごうぎんカラコロ美術館（旧山陰合同銀行北支店）","kana":"ごうぎんからころびじゅつかん（きゅうさんいんごうどうぎんこうきたしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市殿町412","lat":35.470379,"lng":133.054199,"geo_status":"db","era":"大正15年／平成24年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積389㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2015.08.04(平成27.08.04)","register_no":"32－0173","desc":"鉄筋コンクリート造二階建で、西面して建つ。営業室と客溜は二層吹抜けの大空間とし、北側に重役室などを配し、北東隅に金庫室を設ける。松江城南東の金融街に位置し、大オーダーの六本付柱、メダリオンの装飾、隅丸の石造風外壁が、地域景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010688"},{"id":"00008362","register_sub_id":"101","register_pk":"134004","name":"ささや呉服店唐津蔵","kana":"ささやごふくてんからつぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ213","lat":34.46896566,"lng":131.77421863,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0154","desc":"敷地の西南に位置する。桁行６．７ｍ梁間３．７ｍの土蔵造２階建、切妻造妻入で、桟瓦を葺く。割石基礎とし、外壁は漆喰で仕上げる。東面に出入口を設け、瓦葺庇を付け、掛子塗の両開戸を吊る。上部に窓を穿ち、銅製の片開戸を設ける。屋敷景観を整える一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008362"},{"id":"00008361","register_sub_id":"101","register_pk":"134003","name":"ささや呉服店旧呉服蔵","kana":"ささやごふくてんきゅうごふくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ213","lat":34.46888314,"lng":131.77454872,"geo_status":"db","era":"江戸末期／昭和40年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0153","desc":"主屋の南、玄関を挟んで東西棟で建つ。桁行５．９ｍ梁間３．９ｍの土蔵造２階建。切妻造で、桟瓦で葺く。外壁は漆喰仕上げで、通り側には腰を海鼠壁とし、各階に瓦庇付の窓を開け、銅製の開戸を吊り、上部に家紋を飾る。主屋と一体で、街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008361"},{"id":"00008360","register_sub_id":"101","register_pk":"134002","name":"ささや呉服店座敷蔵","kana":"ささやごふくてんざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ213","lat":34.46891964,"lng":131.7743932,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0152","desc":"主屋の西南に位置する。桁行５．８ｍ梁間３．２ｍの土蔵造２階建、東西棟の切妻造で、桟瓦を葺く。外壁は漆喰仕上げで、２階東面に鉄格子付の窓を穿つ。１階を六畳の座敷とし、東面から南面にかけて、二段に縁を設け、磨丸太の垂木を配るなど数寄屋風意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008360"},{"id":"00008359","register_sub_id":"101","register_pk":"134001","name":"ささや呉服店店舗兼主屋","kana":"ささやごふくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ213","lat":34.4689601,"lng":131.77460416,"geo_status":"db","era":"江戸末期／昭和44年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積207㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0151","desc":"通りに東面する町家。間口１４ｍ木造２階建、切妻造桟瓦葺とし、銅瓦棒葺の下屋庇を付け、背面は葺き降ろす。北側の小路に大きく妻壁を見せ、庇付の窓を二ヶ所開ける。大壁造とし、両端にウダツを設け、庇には幕板を付ける。商家の表構えを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008359"},{"id":"00008358","register_sub_id":"101","register_pk":"134000","name":"俵種苗店店舗兼主屋","kana":"たわらしゅびょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ212","lat":34.46879884,"lng":131.77447791,"geo_status":"db","era":"明治中期／大正前期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積118㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0150","desc":"通りに東面する町家。間口１０ｍの木造つし２階建、切妻造桟瓦葺とし、東面に鉄板葺の庇を付ける。正面を広い土間の店舗とし、その奥は北寄りに通り土間、南に四間取の床上を設ける。正面には揚戸を残すなど、津和野の伝統的な町家の佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008358"},{"id":"00010889","register_sub_id":"101","register_pk":"201724","name":"日の出館玄関棟","kana":"ひのでかんげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県出雲市大社町杵築南776","lat":35.39519,"lng":132.6869,"geo_status":"db","era":"大正5／平成3改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"32 ‐ 0176","desc":"出雲大社の南に延びる参道東側に位置し、大正三年の神門通り開通後の建築である。西面して建つ木造二階建で、正面に入母屋造の玄関を備える。一階は玄関とロビー、二階は客室二室で、八畳に簡明な座敷飾を備える。近代における大社詣の歴史を物語る和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010889"},{"id":"00010890","register_sub_id":"101","register_pk":"201725","name":"日の出館明治棟","kana":"ひのでかんめいじとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県出雲市大社町杵築南776","lat":35.395241,"lng":132.686847,"geo_status":"db","era":"明治前期／平成3改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"32 ‐ 0177","desc":"玄関棟北に接続し、取合状況からも玄関棟より古いと判る。南面して建つ木造二階建、切妻造桟瓦葺で、客室は一階が二室、二階が控室付の四室で、各部屋とも整った座敷飾を備え、瀟洒なつくりになる。大社詣にかかる数少ない木造旅館建築として貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010890"},{"id":"00016721","register_sub_id":"101","register_pk":"579205","name":"福寿苑店舗","kana":"ふくじゅえんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県松江市天神町142他","lat":35.464841,"lng":133.055913,"geo_status":"db","era":"昭和26年／平成前期改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積113㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2026.07.09(令和8.07.09)","register_no":"32 - 0223","desc":"天神町の四ツ角に位置する旧呉服問屋の店舗。鉄筋コンクリート造2階一部３階建。外壁モルタル塗仕上。矩形の北西隅にアールを付した平面で、縦長窓や丸窓を配したアールデコ風の端正な外観。交差点の顔をつくり、昭和24年大火後の耐火建築としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016721"},{"id":"00008337","register_sub_id":"101","register_pk":"133979","name":"分銅屋ござ蔵及びびんつけ蔵","kana":"ぶんどうやござぐらおよびびんつけぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ190他","lat":34.46839977,"lng":131.77491263,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積52㎡、便所付","structure_material":"土蔵造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0129","desc":"主屋の後方、土蔵の東北に位置する。桁行１３ｍ梁間４．０ｍの切妻造桟瓦葺で、東半部の棟を下げる。壁は腰モルタルで、上部は西寄りが漆喰仕上げ、東側が中塗仕上げである。西面北寄りに桁行３．１ｍ梁間１．１ｍの木造便所を付設する。作業場の名残を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008337"},{"id":"00008335","register_sub_id":"101","register_pk":"133977","name":"分銅屋店舗兼主屋","kana":"ぶんどうやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ190他","lat":34.46849208,"lng":131.77458295,"geo_status":"db","era":"安政(1854-60)頃／昭和前期改修","year":1856,"year_source":"estimated","year_min":1854,"year_max":1859,"year_label":"安政","structure":"木造平屋建、鉄板葺、建築面積185㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0127","desc":"通りに西面する間口１１ｍの町家。切妻造鉄板葺で、当初はつし２階建。正面に下屋庇を付け、背面は葺き降ろし、台所や便所を付設する。漆喰仕上げで、２階に広く格子窓を穿ち、１階には格子戸をたて、幕板のガラスに家紋をあしらう。津和野における町家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008335"},{"id":"00008336","register_sub_id":"101","register_pk":"133978","name":"分銅屋土蔵","kana":"ぶんどうやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ190他","lat":34.46840505,"lng":131.77475438,"geo_status":"db","era":"安政(1854-60)頃","year":1856,"year_source":"estimated","year_min":1854,"year_max":1859,"year_label":"安政","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0128","desc":"主屋の東後方に位置する。桁行８．５ｍ梁間４．５ｍの土蔵造２階建。東西棟の切妻造とし、桟瓦で葺き、西面に出入口を開き、鉄板葺庇を付ける。切石基礎上に、腰板張で、上部漆喰仕上げとし、妻上部に家紋をつくり出す。屋敷構えを構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008336"},{"id":"00008338","register_sub_id":"101","register_pk":"133980","name":"分銅屋はぜ蔵","kana":"ぶんどうやはぜぐらはぜ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ190他","lat":34.4682468,"lng":131.7752133,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積83㎡","structure_material":"土蔵造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0130","desc":"東西に長い敷地の東端に位置する。桁行１３ｍ梁間５．９ｍの土蔵造平屋建。東西棟の切妻造桟瓦葺で、南面に間口４．２ｍ奥行１．３ｍの庇を付ける。石積基礎上に建ち、漆喰仕上げで腰竪板張とし、窓に銅製の戸をたてる。赤瓦と白漆喰に戸の緑青が映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008338"},{"id":"00012449","register_sub_id":"101","register_pk":"531773","name":"保性館幽泉亭","kana":"ほせいかんゆうせんてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"島根県","address":"島根県松江市玉湯町玉造1191-1他","lat":35.41553056,"lng":133.00906111,"geo_status":"db","era":"昭和6年／平成元年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"32-190","desc":"玉造温泉にある皇族専用の宿泊棟。川島徳次郎の作で、入母屋造桟瓦葺の周囲を錣風の屋根とした重厚な構成を鉄材を用いた薄く深い軒で軽快にみせる。内部は多彩な意匠を駆使して創意あふれた数寄屋風にまとめる。当地域の大工の高度な技量が発揮された秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012449"},{"id":"00010346","register_sub_id":"101","register_pk":"199119","name":"山常楼主屋","kana":"やまつねろうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県安来市安来町字内浜1704","lat":35.430006,"lng":133.254796,"geo_status":"db","era":"昭和9年頃／昭和51年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積596㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"32-0168","desc":"安来港の山陰道沿いに位置する。木造二階建の座敷棟を二棟南北に並列させ、北棟から廊下で奥座敷棟に接続する。特に北棟二階に三室続く座敷は併せて七七畳の大空間となる。広間の座敷飾や高欄腰組等の造作も贅が尽くされ、安来鋼で栄えた港町を彩る料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010346"},{"id":"00010347","register_sub_id":"101","register_pk":"199120","name":"山常楼土蔵","kana":"やまつねろうどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県安来市安来町字内浜1704","lat":35.429899,"lng":133.255063,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"32-0169","desc":"奥座敷の南方に東西棟で建つ二階建の土蔵で、東と南に開口部を設ける。内部は東西二室に分け、それぞれに階段を持つ。東面二階の窓廻りは、庇を腕木から軒先まで丁寧に塗込め、掛子塗の扉を吊り、高い左官技術を示す。主屋とともに街道からの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010347"},{"id":"00004615","register_sub_id":"101","register_pk":"105605","name":"山本家住宅主屋","kana":"やまもとけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県安来市伯太町母里71","lat":35.35093848,"lng":133.27469924,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建、瓦葺、建築面積199㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0034","desc":"切妻造，平入で，街道に東面して建つ。真壁造，平屋建，屋根桟瓦葺で，外観は全体がつし２階建になり，１階正面には蔀戸や出格子を設ける。１階は南側を通り土間，北側を床上とし，庭を望む北妻の客間は開放的な構えになる。地域の指標となる明治前期の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004615"},{"id":"00004298","register_sub_id":"101","register_pk":"105288","name":"旅館美保館旧本館","kana":"りょかんみほかんきゅうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市美保関町美保関570","lat":35.56275654,"lng":133.30790442,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積482㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"32 － 0028","desc":"美保神社への参道北側にあり，棟札から大工河合藤助が判明。南面して建つ木造２階建の和風旅館で，１階は事務室等とし，客室は２階に配する。切妻造，桟瓦葺，平入で，南面には出桁造で中央切妻破風付の庇を設ける。数寄屋風の簡明な意匠で纏められている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004298"},{"id":"00004297","register_sub_id":"101","register_pk":"105287","name":"旅館美保館本館","kana":"りょかんみほかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県松江市美保関町美保関573","lat":35.56260008,"lng":133.30809978,"geo_status":"db","era":"明治41／大正期増築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、建築面積604㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"32 － 0027","desc":"美保神社への参道沿いにある。木造２階建の和風旅館で，切妻造，桟瓦葺の２棟が細長い敷地の南北に建ち，その間をホール（中庭）で接続し，北面には中央に軒唐破風付の庇を設ける。全体は繊細な数寄屋風で，窓，欄間，手摺など各部に趣向が凝らされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004297"},{"id":"00001644","register_sub_id":"101","register_pk":"102634","name":"あけぼの旅館","kana":"あけぼのりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県津山市戸川町31-1、32-1","lat":35.05913655,"lng":133.99971555,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積238㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0046","desc":"津山市内で現存する旅館の中で最も古い旅館建築とされる。表側は道路拡幅のため１階に改造されているが，奥の２階建部分は水廻りを除いて書院造風の内部造作をよく残す。旧城下町のたたずまいを残す地区の一画にあり，景観的に重要な位置を占めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001644"},{"id":"00001531","register_sub_id":"101","register_pk":"102521","name":"江見写真館","kana":"えみしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県津山市山下28","lat":35.05957007,"lng":134.00233804,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積187㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"33 － 0032","desc":"津山における草分け的存在の写真館。正面を西に向け，玄関の右手に半円形の応接室を張り出し，玄関上部には成の高い縦長の２連アーチ窓を開ける。北面には屋根面に達する高窓を設けるなど写真館建築の特徴をよく伝える。設計は地元の原田（熊二郎）工務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001531"},{"id":"00005195","register_sub_id":"101","register_pk":"106185","name":"おかやま旧日銀ホール（旧日本銀行岡山支店本館）","kana":"おかやまきゅうにちぎんほーる（きゅうにっぽんぎんこうおかやましてんほんかん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市北区内山下1-6-20","lat":34.6614,"lng":133.930756,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造及び石造2階建、建築面積520㎡","structure_material":"煉瓦造及び石造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"33 － 0101","desc":"県庁に近い市中心部に位置する。外装に花崗岩を用いた煉瓦造及び石造建造物で，小屋組は鉄骨トラスとする。正面中央にコリント式オーダーと三角ペディメントをあしらうなど古典主義様式の格調高いデザインが特徴的。設計は長野宇平治，施工は藤木工務店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005195"},{"id":"00012642","register_sub_id":"101","register_pk":"367936","name":"奥津荘本館","kana":"おくつそうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県苫田郡鏡野町奥津字湯ノ前49","lat":35.216263,"lng":133.942337,"geo_status":"geocoded","era":"昭和10年頃／昭和30年頃・平成16年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積328㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0307","desc":"奥津温泉中心部にある旅館で、街路に東面して建つ。木造総二階建、入母屋造桟瓦葺で棟を矩折れに配し、正面北端の唐破風の玄関上に大屋根の妻面を重ねる。一階全面に並んだ格子や出桁造の深い軒など立体感のある外観で、温泉街の歴史的景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012642"},{"id":"00016434","register_sub_id":"101","register_pk":"536501","name":"旧太池呉服店店舗兼主屋","kana":"きゅうおおいけごふくてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県新見市新見字小山屋851他","lat":34.98350278,"lng":133.46832222,"geo_status":"db","era":"大正2年／大正前期増築、昭和7年頃・同18年頃・平成21年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積213㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"33 - 0390","desc":"市街地中心部の角地に建つ旧呉服店の店舗兼主屋。二階建入母屋造平入桟瓦葺で北に座敷棟を接続。正面一階は平格子、二階は出格子構えで、西面は白漆喰塗大壁で各階腰を海鼠壁とする。内部一階南東部は土間で北西に座敷を配す。建ちが高く、豪壮な外観の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016434"},{"id":"00010050","register_sub_id":"101","register_pk":"196197","name":"旧岡野屋旅館客室棟","kana":"きゅうおかのやりょかんきゃくしつとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷113","lat":35.08574373,"lng":133.69050418,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積172㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0255","desc":"旭川東岸の神橋たもとに建つ木造二階建で、入母屋造桟瓦葺とする。一階に六室、二階は五〇畳の大広間にもなる五室の客室を川に面して並べ、東に廊下を通す。一階西側の縁は川岸の石垣上に迫出し、上下階ともガラス障子をたてる。河岸景観を引き立てる旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010050"},{"id":"00010051","register_sub_id":"101","register_pk":"196198","name":"旧岡野屋旅館門及び塀","kana":"きゅうおかのやりょかんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷114-1","lat":35.08567331,"lng":133.69056993,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"門 木造、銅板葺、間口2.0m 塀 木造、鉄板葺、総延長11m、潜戸付","structure_material":"門 木造","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0256","desc":"旭川に架かる旧出雲街道の神橋たもとから北に奥まって開く門。一間棟門で、内側に控柱を立てる。一軒吹寄垂木で、屋根は切妻造銅板葺である。吹寄菱格子の欄間が繊細である。門の両側に延びる板塀は鉄板葺で、七宝文の透欄間を入れる。東側塀には潜戸を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010051"},{"id":"00000169","register_sub_id":"101","register_pk":"101159","name":"旧中國銀行牛窓支店","kana":"きゅうちゅうごくぎんこううしまどしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県瀬戸内市牛窓町牛窓2835-1","lat":34.61395011,"lng":134.16786245,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，建築面積104㎡","structure_material":"煉瓦造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0015","desc":"ＲＣ造，平屋建の銀行建築で，設計は小林精一。外壁をドイツ製の煉瓦を小口積とし，軒はモルタルで蛇腹を造る。内部は吹き抜けとし，漆喰造の内壁上端に蛇腹を設け，草花の連続模様を施し，全体に簡素な仕上げになる。明治末～大正期の銀行建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000169"},{"id":"00012039","register_sub_id":"101","register_pk":"210980","name":"金光教徒社中央棟","kana":"こんこうきょうとしゃちゅうおうとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県浅口市金光町大谷325-3他","lat":34.538696,"lng":133.624687,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、スレート葺、建築面積125㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-292","desc":"東棟と西棟の間に建つ。木造二階建、寄棟造、スレート葺で、建築面積一二五平方メートル。外壁はモルタルを塗装して石積に見せる特異な外観で、パラペットを高く立ち上げて陸屋根風に見せる。内部は一階に事務室、応接室を配し、二階は現在倉庫とされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012039"},{"id":"00012040","register_sub_id":"101","register_pk":"210981","name":"金光教徒社西棟","kana":"こんこうきょうとしゃにしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県浅口市金光町大谷325-3他","lat":34.538703,"lng":133.624581,"geo_status":"db","era":"大正5年／昭和18年増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、スレート葺、建築面積76㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-293","desc":"金光教徒新聞社の社屋として大正五年に建てられたもの。木造二階建、寄棟造、スレート葺で、建築面積七六平方メートルである。中央部と西側下屋に入口を設け、外壁下見板張で、軒を板張とするなど簡素な意匠でまとめる。地域の景観を形作る洋風建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012040"},{"id":"00012038","register_sub_id":"101","register_pk":"210979","name":"金光教徒社東棟","kana":"こんこうきょうとしゃひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県浅口市金光町大谷337-1","lat":34.538703,"lng":133.624804,"geo_status":"db","era":"大正10年／昭和28年増築","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、スレート葺、建築面積128㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-291","desc":"金光教本部前の広場に北面する。木造二階建、寄棟造、スレート葺で、建築面積一二八平方メートルである。切石積基礎に外壁下見板張とし、中央に入口を配する左右対称の外観が特徴。軒線中央部を僅かに切り上げ、ベディメント状に見せる。洋風意匠の事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012038"},{"id":"00000168","register_sub_id":"101","register_pk":"101158","name":"作州民芸館（旧土居銀行津山支店）","kana":"さくしゅうみんげいかん（きゅうどいぎんこうつやましてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県津山市西今町18","lat":35.0605015,"lng":133.9936987,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建，鋼板葺，建築面積284㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0014","desc":"明治30年設立の土居銀行の社屋として建てられた。ルネッサンス様式を基本としながら，多様なモチーフを用いる。木造であるが西洋古典様式風のオーダーが付く石造風の外観である。現在は資料館として用いられ，その特異な外観からひときわ目を引く存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000168"},{"id":"00010054","register_sub_id":"101","register_pk":"196201","name":"辻本店衣装蔵","kana":"つじほんてんいしょうぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷116","lat":35.0859204,"lng":133.69097242,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0259","desc":"主屋の北に接続する土蔵造二階建で、切妻造、置屋根式の桟瓦葺とする。切石基礎上に建ち、外壁は漆喰塗で、上下階の腰と隅部を海鼠壁とする。東面に戸口を設け、瓦葺庇下を濡縁とする。西の通り側の窓は、土戸の内側を鏝絵で飾り、庇持送りの彫刻も繊細である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010054"},{"id":"00010055","register_sub_id":"101","register_pk":"196202","name":"辻本店奥座敷","kana":"つじほんてんおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷116","lat":35.0860523,"lng":133.69101222,"geo_status":"db","era":"明治中期／大正期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0260","desc":"衣装蔵の北に並ぶ木造平屋建で、入母屋造桟瓦葺の東西面に下屋を廻らし、南に入母屋屋根の脇玄関を設ける。北には化粧部屋、風呂、便所が附属する。八畳主室はトコ、棚、付書院を飾り、次の間には西の表門に向けて式台玄関を開く。造作の丁寧な離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010055"},{"id":"00010057","register_sub_id":"101","register_pk":"196204","name":"辻本店表門及び塀","kana":"つじほんてんおもてもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字城外107他","lat":35.08608988,"lng":133.69095055,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"表門 木造、瓦葺、間口1.7m 塀 木造、瓦葺、総延長25m","structure_material":"表門 木造","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0262","desc":"奥座敷の式台玄関の西正面で、通り沿いに構えた表門と塀。表門は一間薬医門で、切妻造桟瓦葺とし、両開板扉を吊りこみ、破風に懸魚を飾る。左右に延びる塀は、真壁漆喰塗で桟瓦葺とし、腰部は外側が下見板張、内側は船板を竪張とする。街路景観を整える門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010057"},{"id":"00010053","register_sub_id":"101","register_pk":"196200","name":"辻本店事務所","kana":"つじほんてんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷116","lat":35.08565498,"lng":133.69093349,"geo_status":"db","era":"江戸末期／昭和54改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積148㎡","structure_material":"土蔵造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0258","desc":"店舗の南に接続する土蔵造の建物で、切妻造桟瓦葺である。元は北から倉庫、醤油倉庫、納屋としていたが、二階床と間仕切の一部を撤去した。外壁は漆喰塗で腰を海鼠壁とする。西面一階の窓と出入口は後補で、元は店舗側から出入りした。街路の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010053"},{"id":"00010060","register_sub_id":"101","register_pk":"196207","name":"辻本店倉庫","kana":"つじほんてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字城外108-1","lat":35.08607415,"lng":133.69075893,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積223㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0265","desc":"西蔵の北に位置する土蔵造二階建で、通りに妻を見せた切妻造桟瓦葺とし、北に下屋を葺下ろす。下屋部分が古く、のちにこれを取込んで二階建を増築した。外壁は漆喰塗で軒裏を塗込め、腰を竪板張とし、東妻に水切二段を設ける。東面の戸口には瓦葺庇を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010060"},{"id":"00010052","register_sub_id":"101","register_pk":"196199","name":"辻本店店舗兼主屋","kana":"つじほんてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷116","lat":35.08579692,"lng":133.69099911,"geo_status":"db","era":"江戸後期／明治中期・昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積336㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0257","desc":"通りに西面して建つ造酒屋の店舗兼用住宅。切妻造桟瓦葺とし、北面東寄りに入母屋造の新座敷が取付く。正面に下屋を設け、一階に格子と出格子をたて、内部は中央土間の北を住居、南を店舗とする。二階壁の腰を海鼠壁とするなど当地に特徴的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010052"},{"id":"00010059","register_sub_id":"101","register_pk":"196206","name":"辻本店西蔵","kana":"つじほんてんにしぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷112","lat":35.08580755,"lng":133.69070529,"geo_status":"db","era":"明治中期／平成10改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積136㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0264","desc":"主屋から通りを挟んだ向かい側に建つ土蔵造二階建で、切妻造桟瓦葺である。外壁は漆喰塗の大壁で軒裏を塗込めて水切を廻らし、腰、二階窓高と隅を海鼠壁とする。太い梁を何段にも重ねた豪壮な小屋組に醸造施設の往時を偲ばせる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010059"},{"id":"00010058","register_sub_id":"101","register_pk":"196205","name":"辻本店庭塀","kana":"つじほんてんにわべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県真庭市勝山字城外107他","lat":35.08615424,"lng":133.69121667,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、延長47m","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0263","desc":"奥座敷東側の庭園の北面と東面を囲う塀で、通り側の塀の北端から矩折れに延びて東蔵に接続し、延長四七メートルを測る。コンクリート基礎上に建ち、真壁造漆喰塗で、腰を竪板張とする。東面塀はセメント瓦葺、北面塀は桟瓦葺で、東蔵への構内通路と庭を画する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010058"},{"id":"00010056","register_sub_id":"101","register_pk":"196203","name":"辻本店社舎","kana":"つじほんてんやしろしゃ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字城外107","lat":35.08594929,"lng":133.69117467,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、銅板葺、建築面積0.2㎡","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0261","desc":"主屋新座敷の北、庭の南東寄りに位置する屋敷社である。一間社入母屋造の妻入で、唐破風向拝とも銅板葺とする。大石の上に鎮座し、円柱を長押で固め、組物は出組で中備蟇股とする。正側面に刎高欄付の縁を廻し、軒は二軒繁垂木である。本格的な造作の小社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010056"},{"id":"00000312","register_sub_id":"101","register_pk":"101302","name":"いろは丸展示館","kana":"いろはまるてんじかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県福山市鞆町鞆843-1、843-6","lat":34.38266648,"lng":133.38071064,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造2階建，瓦葺，建築面積211㎡","structure_material":"木造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"34 － 0010","desc":"鞆の船着場の正面に妻を見せて建つ２階建の土蔵。妻の中央と両脇をなまこ壁とし，腰に下見板を張り，窓の上に小庇を付ける等，正面の意匠はよく整っている。港に面したひときわ目立つ土蔵で，往事繁栄した鞆の様子を知ることができる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000312"},{"id":"00013652","register_sub_id":"101","register_pk":"505021","name":"太田家住宅主屋","kana":"おおたけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.43013889,"lng":132.74037222,"geo_status":"db","era":"明治38年頃／昭和4年改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積201㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0292","desc":"旧西国街道に南面する間口六間の二階建町家。入母屋造赤色桟瓦葺で正面に下屋を通し、背面に台所等の角屋を張出す。正面は東側が戸口で中央に平格子、西側は出格子を建て二階は黒タイル貼。内部は上手に仏間と座敷を並べる。街道の景観に寄与する重厚な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013652"},{"id":"00013656","register_sub_id":"101","register_pk":"505025","name":"太田家住宅北土蔵","kana":"おおたけじゅうたくきたどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.43042222,"lng":132.74039444,"geo_status":"db","era":"明治後期／昭和前期移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0296","desc":"敷地北東側に南北棟で建つ。土蔵造二階建、切妻造赤色桟瓦葺で南妻に戸口を開き、庇を設ける。周囲の階境に桟瓦葺の水切を廻らし、二階南妻の窓にも瓦庇を付す。小屋は、弓なりの梁に中引梁を渡して棟束を立てる。屋敷地後方の構えを形成する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013656"},{"id":"00013653","register_sub_id":"101","register_pk":"505022","name":"太田家住宅茶室棟","kana":"おおたけじゅうたくちゃしつとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.43032222,"lng":132.74022222,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0293","desc":"主屋と敷地北端の離れの間に建ち、渡廊下で繋ぐ。東西棟、入母屋造桟瓦葺の周囲に軽快に下屋を廻らす。六畳と北側の四畳半茶室からなり、両室とも数寄屋基調で西面に床を備える。茶室は網代天井で東端を掛込天井とする。風情ある庭空間を創る良質な茶室建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013653"},{"id":"00013654","register_sub_id":"101","register_pk":"505023","name":"太田家住宅離れ","kana":"おおたけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.43045278,"lng":132.74027222,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0294","desc":"敷地北西隅に東西棟で建つ入母屋造、赤色桟瓦葺で下屋を廻らす。庭を向く南面を開放的につくりガラス戸を建てる。内部は東の広い座敷と西の次の間からなり、座敷は大振りの床の左右に床脇と書院を造る。内外とも良材を用いて端正な意匠でまとめた離れ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013654"},{"id":"00013655","register_sub_id":"101","register_pk":"505024","name":"太田家住宅南土蔵","kana":"おおたけじゅうたくみなみどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.43020556,"lng":132.74045278,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0295","desc":"主屋北東に西国街道から後退して南北棟で建つ。土蔵造二階建、切妻造赤色桟瓦葺で西面を戸口とし、外壁漆喰塗で腰を海鼠壁とする。街道側の南妻は上下階に窓二個ずつ並べ、下階は梁間全長の、上階は窓毎に庇を付し、梁木口は漆喰塗小庇を付けて意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013655"},{"id":"00013657","register_sub_id":"101","register_pk":"505026","name":"太田家住宅門及び塀","kana":"おおたけじゅうたくもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.430525,"lng":132.74036667,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口1.8m、塀 木造、瓦葺、総延長33m","structure_material":"門 木造","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0297","desc":"敷地北面東寄りに開く門と、東西に折曲がりに廻る外塀及び門の西側から南にのびて通路と庭を画す内塀で、いずれも桟瓦葺。門は一間薬医門切妻造で両妻の女梁に絵様を施す。外塀は腰を竪板張とし、内塀は瀟洒な下地窓を飾る。屋敷構に趣を添える良質な門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013657"},{"id":"00013658","register_sub_id":"101","register_pk":"504605","name":"岡田家住宅主屋","kana":"おかだけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町910","lat":34.42960556,"lng":132.74695,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積212㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0298","desc":"市中心部にある酒問屋を営む商家。主屋は旧西国街道に北面して建つ入母屋造妻入で、正面下屋に幅広く出格子を建て、黒タイル貼の二階は両端に袖卯建を設ける。東を土間、西はミセ奥を二列四室とし、背後に角屋と風呂場を接続する。街道の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013658"},{"id":"00013659","register_sub_id":"101","register_pk":"504606","name":"岡田家住宅土蔵","kana":"おかだけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町910","lat":34.42940833,"lng":132.74694722,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0299","desc":"主屋の南側に西面して建つ。二階建の土蔵造桟瓦葺で、正面に入母屋屋根で格天井を張った一間幅の蔵前を付す。外壁は漆喰で軒先まで塗込め、腰をモルタル洗出しとする。内部は板敷で、壁は一階を竪板張、二階を漆喰塗とする。敷地中央の屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013659"},{"id":"00009829","register_sub_id":"101","register_pk":"195658","name":"株式会社日新林業加計出張所","kana":"かぶしきがいしゃにっしんりんぎょうかけしゅっちょうじょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県山県郡安芸太田町大字加計字神田3340","lat":34.60978922,"lng":132.32310448,"geo_status":"db","era":"大正10／昭和41改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"34 － 0138","desc":"街路に北面して建つ旧銀行店舗。木造平屋建であるが、正側面に庇をつけてつし二階建の町家風に見せる。屋根は寄棟造桟瓦葺で、軒を出桁造の塗籠とする。庇上の窓は内部では高窓となる。正面腰のタイル貼は後の改修であるが、側背面に旧の腰壁竪板張が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009829"},{"id":"00012643","register_sub_id":"101","register_pk":"367937","name":"旧片野製パン所","kana":"きゅうかたのせいぱんしょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県府中市上下町上下字翁1090-3","lat":34.698505,"lng":133.123383,"geo_status":"geocoded","era":"昭和9年／平成17年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋一部2階建、瓦葺及び金属板葺、建築面積23㎡","structure_material":"木造平屋一部2階建","registered":"2018.11.02(平成30.11.02)","register_no":"34 － 0255","desc":"上下町本通り角地に東面して建つ平屋建で、角地側を二階建とする。一階を店舗、二階を床付の和室とし、外壁モルタル大壁の一階にアーチ窓、二階に縦長窓を並べる。柱形や軒蛇腹、開口頂部のレリーフなど豊かな装飾で、街道景観のアイストップとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012643"},{"id":"00010348","register_sub_id":"101","register_pk":"199121","name":"旧日の丸写真館","kana":"きゅうひのまるしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県竹原市本町1-4996-2","lat":34.345097,"lng":132.91079,"geo_status":"db","era":"昭和7年頃／昭和20年頃改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造3階建、瓦葺、建築面積97㎡","structure_material":"木造3階建","registered":"2014.12.19(平成26.12.19)","register_no":"34-0140","desc":"竹原市竹原伝建地区の南西、本川左岸の道路沿い角地に所在する台形敷地一杯に建ち、西角を隅切とした平面で、三階は北角も斜めにする。二階に写真修整室、三階に写場と現像室を設け、全体のかたちや開口部配置は当初を保持しており、特異な景観を創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010348"},{"id":"00000093","register_sub_id":"101","register_pk":"101083","name":"旧マルヤマ商店事務所","kana":"きゅうまるやましょうてんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県福山市松永町364-1","lat":34.45065921,"lng":133.26102954,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、建築面積90㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"34 － 0001","desc":"設計が長谷川建築事務所，施工が横山善吉と伝える事務所建築。装飾のあるパラペット，頭部に飾りがある１・２階を通した柱型，玄関ポーチ等に本格的な洋風の意匠がみられる。大正期に地域の技術者によって建てられた本格的洋風建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000093"},{"id":"00004416","register_sub_id":"101","register_pk":"105406","name":"恋しき主屋","kana":"こいしきしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県府中市府中町字横町564-1、字永井181-1","lat":34.57532817,"lng":133.23293221,"geo_status":"db","era":"明治初期／明治38・大正元増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階一部3階建、瓦葺、建築面積347㎡","structure_material":"木造2階一部3階建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0067","desc":"通り沿いの２階建，切妻造，平入が明治初期，背面に延びる３階建の客室が明治３８年，大正元年の増築になる。正面中央の望楼風３階も増築。格子や手摺などの細部には伝統的な意匠を残すが，変化に富んだ外観を構成し，街路景観上，際だった存在になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004416"},{"id":"00004417","register_sub_id":"101","register_pk":"105407","name":"恋しき離れ（桔梗の間）","kana":"こいしきはなれ（ききょうのま）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県府中市府中町字永井177","lat":34.57499931,"lng":133.23240534,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0068","desc":"敷地奥の中庭に北面して建つ。木造平屋建，東西棟の寄棟造，桟瓦葺で，銅板葺の庇を廻す。６畳の座敷と３畳の控室からなる。真壁造で，壁は黒漆喰仕上，丸窓，三日月窓など多彩な開口部を配し，格子を皮付材とするなど，野趣にも富んだ瀟洒な数寄屋風の建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004417"},{"id":"00004418","register_sub_id":"101","register_pk":"105408","name":"恋しき離れ（菊の間）","kana":"こいしきはなれ（きくのま）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県府中市府中町字永井178","lat":34.57484731,"lng":133.2326042,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0069","desc":"敷地奥の中庭に北面して建つ。真壁造，平屋建，東西棟の寄棟造，桟瓦葺で，６畳の座敷と３畳の控室からなり，廊下を延ばして手洗所を付属する。銘木を用いた床の間，木舞打の軒，櫛型風とした小壁の下地窓など，洗練された数寄屋風で，つくりも丁寧である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004418"},{"id":"00004419","register_sub_id":"101","register_pk":"105409","name":"恋しき離れ（桐・さつきの間）","kana":"こいしきはなれ（きり・さつきのま）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県府中市府中町字永井178、179-2","lat":34.57515545,"lng":133.23266838,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0070","desc":"主屋後方，中庭に面して建つ。真壁造，平屋建で，Ｌ字型棟とした入母屋造，桟瓦葺である。桐の間は６畳と８畳の２室構成，さつきの間は６畳１室で，東にある内玄関と廊下で連結する。書院造で，外壁黒漆喰塗で下屋庇を廻すなど，堂々とした外観構成をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004419"},{"id":"00004420","register_sub_id":"101","register_pk":"105410","name":"恋しき離れ（竹・萩の間）","kana":"こいしきはなれ（たけ・はぎのま）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"広島県","address":"広島県府中市府中町字永井179-5","lat":34.57497017,"lng":133.23279824,"geo_status":"db","era":"昭和23頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0071","desc":"敷地奥の中庭に西面して建つ。真壁造，平屋建，Ｌ字型棟とした切妻造，桟瓦葺で，４畳半茶室，８畳座敷，３畳控室などを巧みな平面構成で処理している。華奢な丸太柱，緩勾配の屋根や庇，竹や網代の造作，繊細な窓など，数寄屋風の軽快で風雅なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004420"},{"id":"00004414","register_sub_id":"101","register_pk":"105404","name":"竹村家主屋","kana":"たけむらやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市久保3-14-1","lat":34.40992075,"lng":133.20746283,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積481㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0065","desc":"木造２階建，桟瓦葺で，北が道路，南が海に面している。全体は南北棟の北側と東西棟の南側が直交したＴ字型の形態で，竹材の細工や造作を多用した繊細な書院造である。北正面は棟違いの八棟造風に扱うなど，外観は重厚かつ豪放で，地域景観の核になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004414"},{"id":"00004415","register_sub_id":"101","register_pk":"105405","name":"竹村家門及び塀","kana":"たけむらやもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市久保3-14-1","lat":34.41005812,"lng":133.20737133,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造、銅板葺、間口2.4m、板塀 木造、瓦葺、延長20m","structure_material":"木造","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0066","desc":"門は北辺西寄りに設けられた切妻造，銅板葺の棟門で，簡素な矩折型の袖塀がつく。これに続く塀は，真壁造，桟瓦葺で，腰から上を黒漆喰塗とし，簾を入れた横長の小窓を開け，重厚さと繊細さを併せ持つ。敷地の北辺と西辺を区画しつつ，街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004415"},{"id":"00000418","register_sub_id":"101","register_pk":"101408","name":"田中写真館","kana":"たなかしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三次市吉舎町吉舎末政190他","lat":34.71965131,"lng":132.99123348,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造地上3階地下1階建，建築面積98㎡","structure_material":"木造地上3階地下1階建","registered":"1997.12.12(平成9.12.12)","register_no":"34 － 0014","desc":"木造３階建の写真館。むくり屋根を柱頭飾付きの円柱で受ける玄関部，ペディメントに設けたカイゼル髭をモチーフにした２連窓などを用いた特異な造形になる。設計施工は地元の棟梁吉川惣一。竣工時から話題となり，今も広く親しまれている建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000418"},{"id":"00012821","register_sub_id":"101","register_pk":"367724","name":"多門亭","kana":"たもんてい","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市東土堂町156-2","lat":34.40787,"lng":133.19808194,"geo_status":"db","era":"大正9年頃／昭和40年頃改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"34 － 260","desc":"千光寺山南腹にある旧料亭。切妻造桟瓦葺の総二階建で軒桁を丸桁、垂木を丸太とするなど素朴な数寄屋風に仕上げる。内部は上下階に各玄関を設け、一階に中廊下を通して小座敷を並べ、二階に大座敷を配する。山腹に広がる市街地の歴史的景観の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012821"},{"id":"00010512","register_sub_id":"101","register_pk":"199453","name":"西山本館","kana":"にしやまほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県尾道市十四日元町562他","lat":34.409629,"lng":133.20367,"geo_status":"db","era":"大正後期／昭和27改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階一部3階建、瓦葺、建築面積425㎡","structure_material":"木造2階一部3階建","registered":"2015.03.26(平成27.03.26)","register_no":"34 － 0147","desc":"旧出雲街道に面して建つ尾道港の旅館建築。木造二階建と三階建の棟が複雑に組み合わされ、すべての客室が庭に面するよう工夫される。丁寧な仕上げの数寄屋風の和室のほか、外国人船員の宿泊にも対応するよう洋室三室を持つなど、港町の風情を醸す木造旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010512"},{"id":"00009828","register_sub_id":"101","register_pk":"195657","name":"みはらし亭","kana":"みはらしてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県尾道市東土堂町甲150-2","lat":34.41011859,"lng":133.19910511,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積92㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"34 － 0137","desc":"千光寺山東方斜面の参道に面する木造二階建。高い石垣の上に建ち、東面に縁を設けて尾道水道の眺望を得る。二階北端に一二畳の主座敷を設け、南端の室は敷地形状により上下階とも変形平面を呈する。屋根は入母屋造桟瓦葺で、軒は丸太の化粧垂木を隅扇に配る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009828"},{"id":"00000171","register_sub_id":"101","register_pk":"101161","name":"三次市歴史民俗資料館（旧三次銀行）","kana":"みよししれきしみんぞくしりょうかん（きゅうみよしぎんこう）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三次市三次町1236","lat":34.81099187,"lng":132.84797427,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積190㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"34 － 0007","desc":"当初銀行の社屋として建てられ、現在では公有化され資料館として利用されている。入口正面のカウンター奥に窓口事務室が広がり、２階部分をバルコニーの付いた吹き抜けとしている。簡素ではあるが柱頭飾りなどのアクセントのある外観で親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000171"},{"id":"00013322","register_sub_id":"101","register_pk":"366311","name":"向酒店店舗兼主屋","kana":"むかいさけてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市久保一丁目682","lat":34.40964444,"lng":133.20465,"geo_status":"db","era":"大正14年頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造二階建、瓦葺、建築面積77㎡","structure_material":"木造二階建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0264","desc":"尾道市街地に建つ店舗兼用住宅。一階正面を土間のミセ、二階は座敷とする。二階正面を漆喰で塗籠め、袖壁を設ける。大屋根は桟瓦葺だが、一階正面の庇を本瓦葺として重厚に見せる一方、二階の建ちは高い近代の町家の特徴を持つ。港町尾道の景観の一部を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013322"},{"id":"00009833","register_sub_id":"101","register_pk":"195662","name":"旧宮崎商館","kana":"きゅうみやざきしょうかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県下関市田中町2-15","lat":33.95893709,"lng":130.94169459,"geo_status":"db","era":"明治40／昭和中期・平成20改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"煉瓦造2階建、銅板葺、建築面積197㎡","structure_material":"煉瓦造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0077","desc":"街路に南面する煉瓦造二階建。正面中央の玄関アーチは迫元と要石の間に迫石を挟む。左右の窓枠は、切石の楣と窓台を延ばした水平帯で立面を引き締める。二階ヴェランダは要石を入れた五連アーチとし、軒先をデンティルで飾る。整った意匠になる煉瓦造の商館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009833"},{"id":"00001532","register_sub_id":"101","register_pk":"102522","name":"國安家住宅","kana":"くにやすけじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"山口県","address":"山口県岩国市岩国1-7-3","lat":34.16619673,"lng":132.17915538,"geo_status":"db","era":"嘉永3前","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造2階建、瓦葺、建築面積257㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"35 － 0032","desc":"岩国の有力商家が集まる本町筋に立地する元鬢付油製造販売業「松金屋」の主屋。間口９間規模のつし２階，平入，塗屋造の町屋建築で，つし２階正面にあけられた横格子の虫籠窓に特徴があり，江戸時代の岩国城下町の様子を伝える商家建築として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001532"},{"id":"00009537","register_sub_id":"101","register_pk":"194330","name":"玉椿旅館","kana":"たまつばきりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県下関市豊浦町大字川棚字湯町5132","lat":34.13816037,"lng":130.9383557,"geo_status":"db","era":"大正10年頃／昭和後期改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積696㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"35 － 0073","desc":"川棚温泉の温泉旅館。敷地東側の木造二階建大広間の北西に厨房と客室、西に浴室、別棟座敷等が接続する。大相撲で横綱が出る度に増築を重ねたといい複雑な平面をもつ。大広間は二階の四〇畳二室の続き間で北端に舞台、南端にトコを構え、折上格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009537"},{"id":"00014956","register_sub_id":"101","register_pk":"519216","name":"中野家住宅衣装蔵","kana":"なかのけじゅうたくいしょうぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.386975,"lng":131.10043611,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0118","desc":"敷地西辺の北寄りに建つ衣装蔵。二階建切妻造平入桟瓦葺の南北棟。外壁は軒まで塗込め漆喰塗仕上とし腰に水切瓦を廻らす。東面に二箇所の石段付の戸口を設けて庇を付す。内部は各階一室の板敷で中央に階段を配す。米蔵と並び建ち、敷地北西の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014956"},{"id":"00014951","register_sub_id":"101","register_pk":"519211","name":"中野家住宅内蔵","kana":"なかのけじゅうたくうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.3868,"lng":131.10058056,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0113","desc":"主屋に北隣し、商品や家財道具を収納する土蔵。二階建切妻造平入の南北棟で東面南寄りに戸口を設け廊下で主屋と接続する。外壁は軒裏まで漆喰で塗込め、二階東に窓を二箇所開け、庇を付す。内部は各階一室の板敷。重厚な外観が敷地中央の景観をつくる内蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014951"},{"id":"00014954","register_sub_id":"101","register_pk":"519214","name":"中野家住宅穀物蔵","kana":"なかのけじゅうたくこくもつぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.38679722,"lng":131.10050278,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0116","desc":"主屋北西に位置する穀物蔵。二階建切妻造桟瓦葺の南北棟。東面北寄りと南面中央に戸口を設け、2階東面に1箇所窓を開ける。外壁は漆喰塗仕上で腰は石張。各階は板敷で南北２室に仕切り、北室１階中央上部を吹抜とする。主屋とともに敷地内の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014954"},{"id":"00014955","register_sub_id":"101","register_pk":"519215","name":"中野家住宅米蔵","kana":"なかのけじゅうたくこめぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.38688611,"lng":131.10045556,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積52㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0117","desc":"敷地西辺中央北寄りに建つ米蔵。平屋建切妻造平入桟瓦葺の南北棟。外壁は軒まで漆喰で塗込め、東面に二箇所の石段付の戸口を設けて庇を付す。西と東の中央に各一箇所窓を開ける。内部各階一室の板敷で壁は縦板張。北に衣装蔵が並び、敷地北西の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014955"},{"id":"00014953","register_sub_id":"101","register_pk":"519213","name":"中野家住宅茶室","kana":"なかのけじゅうたくちゃしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.38703889,"lng":131.10063333,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0115","desc":"離れの北東に位置する四畳半の茶室。入母屋造桟瓦葺の南北棟で東南の軒先を銅板葺とする。内部は北に床と棚、西に火灯窓、東と南に障子と雨戸を建て、欄間に下地窓を開き、濡縁を廻らす。床廻りに銘木用いて意匠を凝らし、庭に面し開放的なつくりとした茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014953"},{"id":"00014950","register_sub_id":"101","register_pk":"519210","name":"中野家住宅店舗兼主屋","kana":"なかのけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.38670278,"lng":131.10059722,"geo_status":"db","era":"明治中期／昭和22年頃・平成5年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積244㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0112","desc":"赤間関街道の古市にある呉服商の店舗兼主屋。通りに南面する２階建切妻造桟瓦葺で外壁は漆喰塗で仕上げる。内部北半は床上、南半は広い土間とし、上部吹抜周囲に廊下を廻らし、洋品店時の陳列棚を並べる。間口長大で、街道沿いの歴史的な景観の核となる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014950"},{"id":"00014952","register_sub_id":"101","register_pk":"519212","name":"中野家住宅離れ","kana":"なかのけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.38693333,"lng":131.10058611,"geo_status":"db","era":"大正後期／昭和4年頃増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建一部3階建、瓦葺、建築面積171㎡","structure_material":"木造平屋建一部3階建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0114","desc":"主屋の北に位置する賓客用の座敷棟。平屋建桟瓦葺で南に切妻造の玄関を付し、北西に三階建で外壁を下見板張とした洋風望楼が建つ。４室の座敷周囲に廊下を廻らし、望楼一階の化粧間は扇状に竿縁天井を張る凝った意匠。洋風望楼が地域のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014952"},{"id":"00014957","register_sub_id":"101","register_pk":"519217","name":"中野家住宅門及び塀","kana":"なかのけじゅうたくもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県長門市日置上字下市6057","lat":34.38678333,"lng":131.10070278,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"門 木造、瓦葺、間口1.6m 塀 木造、瓦葺、総延長36m","structure_material":"門 木造","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0119","desc":"敷地東辺に沿って建つ門及び塀。門は一間一戸の薬医門で、主柱と控柱間に架けた梁上に束を立てて棟木を支持し、軒は一軒疎垂木とする。門の南北に延びる塀は腰高に積んだ石積上に建ち、屋根は桟瓦葺。簡素な門ながら塀と一体となって敷地東辺の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014957"},{"id":"00002094","register_sub_id":"101","register_pk":"103084","name":"柳井市町並み資料館（旧周防銀行本店）","kana":"やないしまちなみしりょうかん（きゅうすおうぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県柳井市大字柳井津字金屋町442","lat":33.96930931,"lng":132.10961907,"geo_status":"db","era":"明治40／平成12移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積174㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"35 － 0039","desc":"柳井市伝建地区の入口近くに所在。日本銀行技師の長野宇平治の原設計，佐藤節雄の実施設計による銀行建築。長野宇平治が古典主義様式を確立する以前の作品で，正面階下のムクリ状のアーチや薄く張り出したバルコニーなどに様式的な試行錯誤の跡が窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002094"},{"id":"00015245","register_sub_id":"101","register_pk":"530669","name":"料亭高大大広間","kana":"りょうていたかだいおおひろま","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県萩市大字唐樋町字唐樋町83他","lat":34.410425,"lng":131.40184167,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積305㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0122","desc":"敷地西端に建つ寄棟造桟瓦葺の大広間。六〇畳と四〇畳の二室からなり、西面に床、両床脇、付書院、東面に舞台を構え、南面は濡縁、北面は内縁を通す。床は上壇を構え、床柱は太いサクラの皮付丸太。トラスを用いて実現した大空間に合わせた意匠の料亭大広間。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015245"},{"id":"00015244","register_sub_id":"101","register_pk":"530668","name":"料亭高大玄関及び廊下","kana":"りょうていたかだいげんかんおよびろうか","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県萩市大字唐樋町字唐樋町83他","lat":34.41043611,"lng":131.40208611,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積153㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0121","desc":"旧萩往還沿いに位置する料亭旅館。玄関は、敷地中央に東面して建つ、入母屋造桟瓦葺で正面に二間幅の式台を構える。玄関と大広間を繋ぐ廊下は、両下造桟瓦葺、一間半幅の畳敷で北西に配膳室を接続する。玄関は頭貫上に彫刻付蟇股を掲げ、料亭の風格を演出。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015244"},{"id":"00015246","register_sub_id":"101","register_pk":"530670","name":"料亭高大土蔵","kana":"りょうていたかだいどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県萩市大字唐樋町字唐樋町83他","lat":34.41041111,"lng":131.40194167,"geo_status":"db","era":"明治前期／昭和51年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土造2階建、瓦葺、建築面積58㎡","structure_material":"土造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0123","desc":"玄関北隣に建つ食器や膳の収納蔵。二階建切妻造桟瓦葺の東西棟で西面に戸口を開ける。外壁は縦羽目板張で軒廻りは漆喰塗込。内部は各階一室で一階は厨房、二階は板敷の収納蔵とし、登梁の和小屋の棟通りに棚を設える。玄関と一体で敷地中央の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015246"},{"id":"00005506","register_sub_id":"101","register_pk":"106494","name":"織本屋（旧折目家住宅）主屋","kana":"おりもとや（きゅうおりめけじゅうたく）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字町83-2","lat":34.03347197,"lng":134.0627272,"geo_status":"db","era":"明和9","year":1772,"year_source":"db","year_min":1772,"year_max":1772,"year_label":null,"structure":"木造2階建、瓦葺、建築面積276㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"36 － 0060","desc":"南北に通る街道に東を正面として建つ商家建築で，古い部分は棟札から年代が判る。切妻造，平入の２階建で，正面に下屋を設ける。本瓦葺の屋根や漆喰塗の外壁など全体に重厚感があり，両側面のうだつは斜めの下段と水平の上段からなる古い形式が特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005506"},{"id":"00012992","register_sub_id":"101","register_pk":"368070","name":"河井百貨店","kana":"かわいひゃっかてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"徳島県","address":"徳島県三好市東祖谷京上146-7","lat":33.86818333,"lng":133.90448611,"geo_status":"db","era":"昭和9年／昭和中期増築、昭和40年代改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、金属板葺、建築面積129㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"36 － 197","desc":"東祖谷中心部のもと日用雑貨店。街道に南面して建つ入母屋造鉄板葺の二階建で、西側に別棟を接続する。1階を全面土間の店とし、2階に3室を並べて南東二面に縁を廻す。建ちが高く、間口の広い大型町家で、街道沿いの歴史的景観の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012992"},{"id":"00012989","register_sub_id":"101","register_pk":"368068","name":"喜多薬店","kana":"きたやくてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"徳島県","address":"徳島県三好市西祖谷山村一宇277","lat":33.89246389,"lng":133.81642222,"geo_status":"db","era":"昭和15年頃／昭和30年頃増築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階地下1階建、瓦葺、建築面積143㎡","structure_material":"木造2階地下1階建","registered":"2019.09.10(令和1.09.10)","register_no":"36 － 194","desc":"西祖谷中心部の日用雑貨店。街道に東面して建つ切妻造セメント瓦葺の二階建で、北を落棟とする。1階前方を前土間の店とし、後方に3室を並べ、2階に2列4室を配し、祖谷川に面する西側を懸造状にして地階を設ける。街道沿いの歴史的町並みを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012989"},{"id":"00014681","register_sub_id":"101","register_pk":"515223","name":"旧四国銀行辻支店車庫","kana":"きゅうしこくぎんこうつじしてんしゃこ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"徳島県","address":"徳島県三好市井川町辻88-2","lat":34.0294,"lng":133.88010278,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"36 - 0223","desc":"銀行店舗の背面に位置する自動二輪車庫。鉄板葺片流れ屋根の平屋建、外壁はモルタル塗リシン吹付仕上、正面に小庇を付し、引違板戸を立てる。内部は大小２室の土間で、大きい北室を車庫、南室を倉庫とする。形式は簡素だが、当時の銀行営業の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014681"},{"id":"00014680","register_sub_id":"101","register_pk":"515222","name":"旧四国銀行辻支店店舗","kana":"きゅうしこくぎんこうつじしてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"徳島県","address":"徳島県三好市井川町辻88-2","lat":34.0293,"lng":133.88025556,"geo_status":"db","era":"昭和34年／昭和後期改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造、建築面積149㎡","structure_material":"鉄筋コンクリート造","registered":"2023.08.07(令和5.08.07)","register_no":"36 - 0222","desc":"辻地区中心部の伊予街道に面する銀行店舗。鉄筋コンクリート造二階建、外部はモルタル洗出に目地切り石張風仕上とし、玄関柱形が正面性を高める。表側の営業室は元は吹抜で二階に回廊を巡らす。背面側は中廊下型平面で諸室を並べる。地域の近代化を象徴する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014680"},{"id":"00008583","register_sub_id":"101","register_pk":"134979","name":"近藤家住宅主屋","kana":"こんどうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県鳴門市大麻町板東字北条86-1","lat":34.15669411,"lng":134.50225303,"geo_status":"db","era":"明治中期／昭和26年・昭和30年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0086","desc":"四国霊場霊山寺の門前、参道と撫養街道の角に東西棟で建つ。入母屋造本瓦葺で、四方に下屋を付設するが、北と東で軒高を違え変化を付ける。間口一二メートル奥行八・一メートルの木造つし二階建で、上屋を大壁とし、軒まで塗り込めるなど、重厚な構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008583"},{"id":"00012048","register_sub_id":"101","register_pk":"210989","name":"島尾家住宅店舗兼主屋","kana":"しまおけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻85-1","lat":34.029037,"lng":133.879969,"geo_status":"db","era":"明治10年頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積175㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-168","desc":"井川町辻の中心地、街路に南面して建つ。木造二階建、切妻造本瓦葺で、奥行南北に細長い平面に、緩やかな平入屋根をかける。表側に店舗部分を取り、右側に土間を通して背面側に作業場を設ける。二階はほぼ正方形の平面とする。町並景観に寄与する町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012048"},{"id":"00010690","register_sub_id":"101","register_pk":"201264","name":"炭米穀店店舗兼主屋","kana":"すみべいこくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県鳴門市撫養町南浜字蛭子前東41","lat":34.174753,"lng":134.603348,"geo_status":"db","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積164㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"36－0126","desc":"通り沿いに建つ、米穀店の店舗兼用住宅。木造二階建で屋根を本瓦葺とし、正面の上下階とも出格子を配する。内部は一階前面を広いミセとし、東寄りに二室続きの座敷を並べて座敷飾を設え、東の庭側に廊下を付す。四国の玄関口としての賑わいを伝える商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010690"},{"id":"00012047","register_sub_id":"101","register_pk":"210988","name":"大正館店舗兼主屋","kana":"たいしょうかんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県小松島市小松島町字外開7-11","lat":34.009886,"lng":134.586412,"geo_status":"db","era":"大正7年／平成18年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-167","desc":"小松島市中心市街地にあり北面する町家。間口六間半で中央に通り土間を通し、西半をミセや旧倉庫とし、東半に帳場やオモテなど四室を配する。二階には平書院を備えた上質な座敷飾りを備える。正面の出格子や二階の手摺など港町の歴史的景観をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012047"},{"id":"00000271","register_sub_id":"101","register_pk":"101261","name":"高原ビル","kana":"たかはらびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県徳島市東船場町1-13","lat":34.0703172,"lng":134.54888446,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建，建築面積87㎡","structure_material":"鉄筋コンクリート造3階建","registered":"1997.07.15(平成9.07.15)","register_no":"36 － 0007","desc":"通りに面して建つＲＣ造のビル。一部を塔屋風に３階建てとし，他は２階建てとする。スクラッチタイルの外壁，パラペットの装飾，塔屋風の部分の窓廻りの装飾等に特徴がある。昭和初期の都市部における洋風の意匠を持つ小規模なビルの好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000271"},{"id":"00012654","register_sub_id":"101","register_pk":"367948","name":"古本家住宅店舗兼主屋","kana":"ふるもとけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町佐野金氏935-1","lat":34.003742,"lng":133.703568,"geo_status":"geocoded","era":"明治25年頃／明治後期移築","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積261㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"36 － 0187","desc":"市西部の山村にある地主宅で、主屋は街道沿いに南面して建つ。店舗とする東側が切妻造、居室とする西側が入母屋造で、下屋を廻し、中央部に玄関を構える。上手に瀟洒な座敷飾の座敷と前室を並べ、正側面に縁を設ける。山村の地主層の暮らしを伝える大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012654"},{"id":"00012655","register_sub_id":"101","register_pk":"367949","name":"古本家住宅土蔵","kana":"ふるもとけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県三好市池田町佐野金氏935-1","lat":34.003742,"lng":133.703568,"geo_status":"geocoded","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"36 － 0188","desc":"敷地南西隅の街道沿いに建つ。土蔵造二階建、切妻造で、北面に吹放し下屋を付す。外壁は下部縦板張、中間下見板張、上部漆喰塗で鉢巻を廻し、上下階南面に各二窓を開く。内部は東西に二分し、北東二面に戸口を設ける。街道の歴史的景観を形成する大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012655"},{"id":"00012656","register_sub_id":"101","register_pk":"367950","name":"古本家住宅庭門及び塀","kana":"ふるもとけじゅうたくにわもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県三好市池田町佐野金氏935-1","lat":34.003742,"lng":133.703568,"geo_status":"geocoded","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"庭門 木造、瓦葺、間口2.0m、北方袖塀付 塀 木造、瓦葺、延長15m","structure_material":"庭門 木造","registered":"2018.11.02(平成30.11.02)","register_no":"36 － 0189","desc":"主屋玄関東側に取付き、東面して建つ一間腕木門と、門南端から矩折れに延びて土蔵東南隅に至る塀。塀は壁漆喰塗の腰縦板張で、一間おきに下地窓を穿つ。出隅部屋根には阿波踊の踊子を表した留蓋瓦を載せる。主屋前庭を囲み、風格ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012656"},{"id":"00012653","register_sub_id":"101","register_pk":"367947","name":"前田商店店舗兼主屋","kana":"まえだしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県三好市東祖谷久保727-9他","lat":33.85648,"lng":133.960327,"geo_status":"geocoded","era":"昭和20年頃","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"36 － 0186","desc":"市南端部の山中の街道沿いに西面して建つ商家主屋。総二階建の正面北端に入母屋玄関を出し、北側に平屋の居室部が取付く。一階に長大材の架構による広い店舗、二階に座敷を設け、正面廊下の欄間を扇面形の下地窓で飾る。山間集落の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012653"},{"id":"00010693","register_sub_id":"101","register_pk":"201267","name":"村田旅館蔵","kana":"むらたりょかんくら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県吉野川市美郷字古土地131-4","lat":34.031884,"lng":134.298892,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"36－0129","desc":"本館から客室棟を挟んで背後の西方に建つ。土蔵造二階建で、桁行五・七メートル梁間四・三メートルである。小屋組は登梁形式とし、二階内法が比較的高い。東正面一階には腕木を出して庇を設ける。敷地形状を利用し、背後の川と相まって、歴史的景観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010693"},{"id":"00010692","register_sub_id":"101","register_pk":"201266","name":"村田旅館本館","kana":"むらたりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県吉野川市美郷字古土地134-2","lat":34.03172,"lng":134.29904,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"36－0128","desc":"四国山地の山間部に位置する店舗兼旅館。一階に店舗、二階に客室用の座敷を配し、二階は敷地の高低差のため、背面側から直接に出入りができるようになっている。座敷は八畳と六畳からなり、外廻りに高欄をまわすなど山間地における旅館の風情を醸している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010692"},{"id":"00008582","register_sub_id":"101","register_pk":"134978","name":"和田の屋本館下棟","kana":"わだのやほんかんしもとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"徳島県","address":"徳島県徳島市眉山町大滝山5-5他","lat":34.0723895,"lng":134.54267135,"geo_status":"db","era":"昭和28年／昭和31年増築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0085","desc":"大滝山山麓、登り口に北面する。東西一三メートル南北五・六メートル、西面に増築部を付設。東西棟を主棟とし、東端に南北棟の入母屋屋根を造るなど複雑な屋根とする。一階は土間で、餅の焼き場や販売所、二階に座敷を設ける。観光地に残る老舗店舗の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008582"},{"id":"00004828","register_sub_id":"101","register_pk":"105818","name":"愛染家住宅主屋","kana":"あいぜんけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市東ハゼ町897","lat":34.322914,"lng":134.04031826,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"37 － 0273","desc":"街道に東面する敷地に建つ。全体はコ字平面で，表屋は南北棟，入母屋造，桟瓦葺の２階建町家で，正面に下屋を出し，中央北寄りに入母屋造玄関を設ける。２階外壁は黒漆喰塗で，腰に白タイルを張り，軒は段形に銅板で覆うなど重厚にして瀟洒な表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004828"},{"id":"00004831","register_sub_id":"101","register_pk":"105821","name":"愛染家住宅西蔵","kana":"あいぜんけじゅうたくにしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県高松市東ハゼ町897","lat":34.322929,"lng":134.040222,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"37 － 0276","desc":"主屋の南方，東蔵の西方に位置し，南北棟で建つ。桁行５間梁間２間半規模，切妻造，桟瓦葺，平入の２階建土蔵で，東面の北端に庇を差し掛けて戸口を設ける。もと酒瓶詰蔵で，外部は腰海鼠壁，上部白漆喰塗，軒鉢巻き付きで東蔵と同様なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004831"},{"id":"00004830","register_sub_id":"101","register_pk":"105820","name":"愛染家住宅東蔵","kana":"あいぜんけじゅうたくひがしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県高松市東ハゼ町897","lat":34.32283204,"lng":134.04026041,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"37 － 0275","desc":"主屋の南方に位置し，東西棟で建つ。桁行３間梁間２間，切妻造，桟瓦葺，平入の２階建土蔵で，北面の東端に庇を付けて戸口を設ける。もと酒保管蔵で，外部は腰高の海鼠壁とし，上部は白漆喰塗，軒には鉢巻きを廻す。金比羅街道に面した表構えの構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004830"},{"id":"00008072","register_sub_id":"101","register_pk":"128903","name":"泉家住宅主屋","kana":"いずみけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田字畑方2244-1他","lat":34.22665138,"lng":134.40418982,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"37-0338","desc":"旧街道に西面して建つ。切妻造本瓦葺で、正・背面に下屋庇を付ける。間口１１ｍ奥行８．８ｍの木造つし２階建。上屋は漆喰塗で、出桁まで塗り込め、虫籠窓を開け、下屋には出格子を残す。南寄りにニワ、北側に田の字型に床上を配する。商家の表構えをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008072"},{"id":"00003613","register_sub_id":"101","register_pk":"104603","name":"かめびし圧搾場","kana":"かめびしあっさくば","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2132","lat":34.22869669,"lng":134.40311724,"geo_status":"db","era":"明治初期／昭和初期改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0170","desc":"主屋（事務室・展示室）の西方，道路を隔てた西敷地に主屋と向き合って建つ。もとは問屋業を営む他家の主屋。桁行１２．３ｍ梁間７．２ｍ規模，切妻造，本瓦葺のつし２階建で，東面は改造されているが，西面は商家主屋の面影をよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003613"},{"id":"00003615","register_sub_id":"101","register_pk":"104605","name":"かめびし旧四号蔵及び旧六号蔵","kana":"かめびしきゅうよんごうぐらおよびきゅうろくごうぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2132","lat":34.22873545,"lng":134.40291448,"geo_status":"db","era":"明治初期／大正末期増改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積153㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0172","desc":"西敷地北辺中央に位置する旧六号蔵は桁行１２ｍ梁間６ｍ規模で，南方矩折れに旧四号蔵がつながる。旧四号蔵は桁行１３．４ｍ梁間６ｍ規模，南北棟，切妻造，本瓦葺の平屋建で，軒先低く屋根を葺き下ろす。貯蔵用倉庫であるが，もとは問屋の施設とみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003615"},{"id":"00003600","register_sub_id":"101","register_pk":"104590","name":"かめびし事務室及び展示室","kana":"かめびしじむしつおよびてんじしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22860152,"lng":134.40328214,"geo_status":"db","era":"安永9／江戸末期増築","year":1780,"year_source":"db","year_min":1780,"year_max":1780,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積372㎡","structure_material":"木造2階一部平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0157","desc":"引田の中心的街路に西面して建つ。もとの主屋で，主体部は間口１９ｍ規模，入母屋造，本瓦葺のつし２階建とし，北東に釜屋を角屋状に張り出し，南方に座敷を増築している。近年施設全般をべんがら色基調に統一し，独特の景観をつくりだして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003600"},{"id":"00004656","register_sub_id":"101","register_pk":"105646","name":"キッコ石石井家内浜長屋","kana":"きっこいしいしいけうちはまながや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜881-10","lat":34.47458765,"lng":134.31883697,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積185㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0248","desc":"醤油醸造主が市街中心部に建設した貸商店長屋。間口３間規模の貸店舗を６軒連ねて道路に西面して建ち，全体を南北棟，入母屋造，桟瓦葺の木造２階建につくり，背面各戸に便所等を角屋状に突出させる。醤油醸造で栄えた街の発展を物語る建物として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004656"},{"id":"00004026","register_sub_id":"101","register_pk":"105016","name":"香龍北川家住宅主屋","kana":"こうりゅうきたがわけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市円座町字永井979-1","lat":34.28897858,"lng":134.01398373,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0191","desc":"高松市街南方，香東川に架かる円座橋西詰近くに位置し，遍路道に南面して建つ。平面規模は桁行９間半梁行５間半，入母屋造，桟瓦葺のつし２階建で，２階は黒漆喰で塗込め，正面に虫籠窓を配す。４隅に施された白漆喰塗の隅柱彫刻が地域の目印となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004026"},{"id":"00003329","register_sub_id":"101","register_pk":"104319","name":"こんぴらうどん参道店（旧櫻屋旅館）","kana":"こんぴらうどんさんどうてん（きゅうさくらやりょかん）","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県仲多度郡琴平町字川西810-3","lat":34.187019,"lng":133.817917,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0156","desc":"南と東が街路に面した角地にあり，南を正面とした平入の木造・２階建で，桟瓦葺屋根は東が入母屋造，西が切妻造になる。料理店に改装されたが，草花彫刻をつけた２階高欄など旅館建築らしい細部を残し，金刀比羅宮の東の参道景観の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003329"},{"id":"00005922","register_sub_id":"101","register_pk":"106907","name":"重元果物店店舗","kana":"しげもとくだものてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県丸亀市浜町115-2","lat":34.29211005,"lng":133.79420991,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"37 － 0308","desc":"桁行６間，梁間３間，木造２階建，入母屋造，本瓦葺の商店街に面した町家建築である。２階外壁は黒漆喰塗と黒色タイル貼で仕上げる。香川県内では，丸亀と多度津の市街地で限定的にみられる手法で，地域色のある建築意匠の遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005922"},{"id":"00001139","register_sub_id":"101","register_pk":"102129","name":"下高瀬簡易郵便局（旧丸岡呉服店）","kana":"しもたかせかんいゆうびんきょく（きゅうまるおかごふくてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県三豊市三野町下高瀬字乙井533-2","lat":34.20169775,"lng":133.7057428,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造２階建，瓦葺，建築面積225㎡","structure_material":"木造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0019","desc":"呉服店の店舗として建てられた。京都の近代建築を模してつくったと伝える通り，周辺の民家よりはるかに規模が大きいひときわ目立つ洋風建築である。内部中央に吹き抜けのギャラリーがあり，その上部に天窓を設けるなど空間構成にもみどころがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001139"},{"id":"00002692","register_sub_id":"101","register_pk":"103682","name":"瀬川酒店主屋","kana":"せがわさけてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県善通寺市上吉田町1-4-10","lat":34.229134,"lng":133.786575,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0090","desc":"善通寺市役所の向かい，ＪＲ善通寺駅から西方に延びる駅前通りに南面して建つ。間口８間ほどの虫籠窓を開けたつし２階建の塗屋造店舗で，棟梁は音田定吉と伝える。長大な入母屋造の本瓦葺屋根を通り沿い見せ，「師団一」の銘柄とともに広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002692"},{"id":"00002826","register_sub_id":"101","register_pk":"103816","name":"瀬川酒店東蔵","kana":"せがわさけてんひがしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県善通寺市上吉田町1-4-10","lat":34.229279,"lng":133.786652,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積146㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0094","desc":"ＪＲ善通寺駅前から西に延びる通りに面して建つ。南北棟，桟瓦葺切妻造の酒蔵で，東西棟，平入の店舗主屋の東に接して建ち，南妻面を通りに見せる。南面は腰を海鼠壁として意匠を整え，店舗主屋とともに老舗の店構えと佇まいを今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002826"},{"id":"00003322","register_sub_id":"101","register_pk":"104312","name":"天満屋呉服店主屋","kana":"てんまんやごふくてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市仏生山町字桜馬場甲542","lat":34.280247,"lng":134.047775,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積177㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0149","desc":"法然寺に向かう街道の東側にある。西を正面とした木造・２階建，平入で，南面切妻造，北面入母屋造の本瓦葺屋根をあげ，西と北に下屋庇を廻す。２階は大柄な虫籠窓を設け，北端の袖壁，南隅の持送りに鏝絵を施すなど，凝った細部を備えた門前町の商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003322"},{"id":"00004044","register_sub_id":"101","register_pk":"105034","name":"へんこつ屋店舗","kana":"へんこつやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県仲多度郡琴平町字川東240-2","lat":34.18848675,"lng":133.82033503,"geo_status":"db","era":"明治中期／昭和初期改造","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積136㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0209","desc":"金刀比羅宮参道筋一之橋東詰近く，新町西商店街に南面して東西棟で建ち，奥に棟を延ばす。角地に位置し，正面は南西の２面に下屋を取り付けた標準的な構えをとるが，内部には網代組のヴォールト状天井など，凝った造作や銘木珍木の使用が随所にみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004044"},{"id":"00012249","register_sub_id":"101","register_pk":"353050","name":"寳月堂南館","kana":"ほうげつどうみなみかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県丸亀市米屋町14-2他","lat":34.291949,"lng":133.797182,"geo_status":"db","era":"大正7年／昭和6年増築、昭和32年・同41年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積216㎡","structure_material":"木造2階一部3階建","registered":"2018.03.27(平成30.03.27)","register_no":"37-431","desc":"丸亀市中心部に建つ。外観は北半部を釉薬タイル貼にスパニッシュ瓦の洋風、南半部を平入黒漆喰塗町家風にまとめる。内部は暖炉を設け腰板張の洋風意匠の洋室や、和風の座敷、茶室を収め複雑な様相を示す。様々な要素を織り交ぜた昭和初期の商店建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012249"},{"id":"00008071","register_sub_id":"101","register_pk":"128902","name":"松村家住宅主屋","kana":"まつむらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田字畑方2243","lat":34.22677278,"lng":134.40413155,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積198㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"37 - 0337","desc":"旧街道に西面して建つ。間口１８ｍのつし２階建、入母屋造本瓦葺で、正面に下屋庇を設ける。上屋には虫籠窓を開け、出桁まで塗り込め、正面北寄りには出格子を残す。内部は中央にゲンカン、南にミセ、北にザシキなどを配す。旧街道筋の歴史的景観を伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008071"},{"id":"00005038","register_sub_id":"101","register_pk":"106028","name":"丸尾醸造所西主屋","kana":"まるおじょうぞうしょにししゅおく","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県仲多度郡琴平町榎井字籏岡94","lat":34.19048103,"lng":133.82866917,"geo_status":"db","era":"明治中期／昭和12増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積103㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0284","desc":"東主屋の西に並び建つ。間口４間，東西棟，切妻造，桟瓦葺，平入の２階建で，背面の庭園に面して８畳仏間と８畳座敷を有する南北棟の座敷棟と便所棟を増築する。東主屋よりたちの高い２階建で，東中商店街の歴史的景観の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005038"},{"id":"00005037","register_sub_id":"101","register_pk":"106027","name":"丸尾醸造所東主屋","kana":"まるおじょうぞうしょひがししゅおく","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県仲多度郡琴平町榎井字籏岡94","lat":34.19173255,"lng":133.82888555,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"塗屋造2階建、瓦葺、建築面積155㎡","structure_material":"塗屋造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0283","desc":"東中商店街に北面して建つ。間口７間，切妻造，桟瓦葺，平入の２階建町家で，北面に庇を付け，東方を店舗，西方を事務室として使用。２階正面は黒漆喰塗で，白縁取の縦格子虫籠窓２所を並べる。琴平への入口にあたる街道筋の歴史的景観をかたちづくる要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005037"},{"id":"00001754","register_sub_id":"101","register_pk":"102744","name":"水尾写真館","kana":"みずおしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県善通寺市上吉田町3-4-6","lat":34.22693366,"lng":133.78137525,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積426㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0054","desc":"善通寺駅前通りに面して南面して建つ。木造２階建、下見板張りの写真館で、道路沿い正面の２階中央上部を立ち上げてゲーブルをつくり、館名を入れる。正面道路側を店舗とし、奥にスタジオを設ける。凹凸の少ないグラフィカルなファサード構成に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001754"},{"id":"00004032","register_sub_id":"101","register_pk":"105022","name":"元屋商店主屋","kana":"もとやしょうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町字城甲660-2","lat":34.485397,"lng":134.183319,"geo_status":"db","era":"明治中期／明治後期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0197","desc":"道路に南面して建つ。東西棟，入母屋造，本瓦葺のつし２階建で，平面規模は桁行７間梁行５間。東方を下手とし，上手の西面に桁行４間，寄棟造，桟瓦葺の座敷棟がとり付く。入母屋の破風や，つし２階の梁端を塗込めるなど防火的なつくりとする点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004032"},{"id":"00005362","register_sub_id":"101","register_pk":"106350","name":"料亭二蝶大座敷","kana":"りょうていにちょうおおざしき","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県高松市百間町7-7","lat":34.34476883,"lng":134.05359283,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積274㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0288","desc":"主屋の南方に東西棟で建つ大広間棟で，内部は桁行９間半，梁間３間半で，６５畳半の座敷とし，東端に舞台，西端に２畳の上段などから成る床飾りを備える。天井を折上げ船底天井とするなど随所に凝ったつくり。設計は東京の建築家谷川増太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005362"},{"id":"00005364","register_sub_id":"101","register_pk":"106352","name":"料亭二蝶表門","kana":"りょうていにちょうおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県高松市百間町7-7","lat":34.34497886,"lng":134.0535311,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造、瓦葺及び銅板葺、間口2.7m、塀延長27m付","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0290","desc":"敷地北辺の西寄りに門口を開き，東西に外塀を延ばす。表門は間口１間半規模，東西棟，切妻造，桟瓦葺の薬医門で，軒先を銅板葺とする。外塀は庵治石基礎上に建つ真壁造の屋根付塀で，腰高く縦板張とし，小壁に窓を開けた端正なつくりで景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005364"},{"id":"00005361","register_sub_id":"101","register_pk":"106349","name":"料亭二蝶主屋","kana":"りょうていにちょうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県高松市百間町7-7","lat":34.34493372,"lng":134.05360169,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積173㎡","structure_material":"木造2階一部平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0287","desc":"高松城の東南方，繁華街の一本南の通りに北面する敷地の東北部に建つ。Ｌ字形平面を持ち，２階建部から西に東西棟，入母屋造，桟瓦葺，平屋建を突きだし，玄関・帳場等とする。玄関部は内外を数寄屋意匠でまとめ，料亭に相応しい表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005361"},{"id":"00005363","register_sub_id":"101","register_pk":"106351","name":"料亭二蝶茶室","kana":"りょうていにちょうちゃしつ","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県高松市百間町7-7","lat":34.34485293,"lng":134.05351062,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0289","desc":"玄関の西南方，大座敷の西北方に位置する。８畳の茶室で，西面に床の間を配し，東面には渡廊下に面して前室，南面には縁側を設ける。床柱の変木，長押の半割竹，蒲組天井など建材にも趣向を凝らす。設計は大座敷同様，香川県出身の谷川増太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005363"},{"id":"00004029","register_sub_id":"101","register_pk":"105019","name":"旅館いしや","kana":"りょかんいしや","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県さぬき市志度字田中598-1","lat":34.32321882,"lng":134.17547931,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積248㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0194","desc":"旧志度街道に北面して建つ。桁行５間半梁間４間，東西棟，片入母屋造，本瓦葺のつし２階建で，南北両面に下屋を差し掛ける。正面つし２階は白漆喰塗で，虫籠窓を２箇所に配し，虫籠窓中央の縦桟及び隅部柱型に黒漆喰の模様を入れて変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004029"},{"id":"00006936","register_sub_id":"101","register_pk":"107918","name":"旅館晩翠離れ屋","kana":"りょかんばんすいはなれや","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県観音寺市観音寺町字上松甲3099-1","lat":34.13001175,"lng":133.65306742,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積96㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"37 － 0319","desc":"主屋の南方に坪庭を介して南北棟で建つ。桁行６間半梁間３間半規模、切妻造桟瓦葺の２階建で、北面から西面にかけて銅板葺の庇をまわす。２階には３６畳大の広間を設け、天井は折上格天井とし、北面の座敷飾りには床柱として径１尺程度の楓の珍木を据える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006936"},{"id":"00006935","register_sub_id":"101","register_pk":"107917","name":"旅館晩翠本館","kana":"りょかんばんすいほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県観音寺市観音寺町字上松甲3099-1","lat":34.13005577,"lng":133.65291752,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"37 － 0318","desc":"遍路道に面する敷地の北東奧に位置する。入母屋造桟瓦葺で南北に庇を設ける平屋建で、東にトコや棚、付書院を備える主室１０畳を、西に８畳の続き間、その北に８畳間を配し、南・北・西の３面に縁廊下をまわす。座敷飾りなどに手堅い意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006935"},{"id":"00009846","register_sub_id":"101","register_pk":"195675","name":"旭館","kana":"あさひかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県喜多郡内子町内子2307他","lat":33.55461006,"lng":132.65444454,"geo_status":"db","era":"大正15／昭和中期改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積273㎡、塔屋付","structure_material":"木造平屋一部2階建","registered":"2013.12.24(平成25.12.24)","register_no":"38 － 0109","desc":"切妻造桟瓦葺の旧映画館。西正面は中央をわずかに張出し、上端は起り付で三段に切下げ、繰形と歯飾りで飾る。中央入口上にヴェランダ、頂部に六角平面の太鼓櫓が載る。内部は正面側が舞台、両脇が通路で、奥寄りに二階客席を設ける。昭和前期の賑わいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009846"},{"id":"00002179","register_sub_id":"101","register_pk":"103169","name":"石崎汽船本社","kana":"いしざききせんほんしゃ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県松山市三津1-4-9","lat":33.86522769,"lng":132.71143004,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積128㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0010","desc":"三津港波止場入口に立地する鉄筋コンクリート造２階建，陸屋根造の事務所建築で，設計は松山に縁の深い木子七郎。正面は左右対称形で，中央部を薄く張出して柱型の間に橙色，両側に白色タイルを張る。瀬戸内海海運で栄えた三津浜を象徴する建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002179"},{"id":"00004052","register_sub_id":"101","register_pk":"105042","name":"梅美人酒造事務所","kana":"うめびじんしゅぞうじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県八幡浜市1557-2","lat":33.46520407,"lng":132.42589474,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0053","desc":"街道に東面して建つ。桁行８間梁間５間規模，南北棟，寄棟造，桟瓦葺の木造２階建で，正側面をタイル張として洋風に見せる。腰は花崗石のルスチカ積，柱型の間に上げ下げ窓を配し，パラペットを背面側端部に廻す。造り酒屋店舗事務所の洋風化を示す事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004052"},{"id":"00001760","register_sub_id":"101","register_pk":"102750","name":"小藪温泉本館","kana":"おやぶおんせんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県大洲市肱川町宇和川","lat":33.45316962,"lng":132.66853694,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造3階建、瓦葺、建築面積181㎡","structure_material":"木造3階建","registered":"2000.09.26(平成12.09.26)","register_no":"38 － 0009","desc":"伊予灘に注ぐ肱川上流部の支流，小藪川に面して建つ明治９年創業の温泉旅館。木造総３階建，入母屋造・桟瓦葺で，各階とも出桁庇を付ける。１階は食堂，客室は２階３室，３階６室である。全体にたちの高い和風建築で，湯治場の象徴的な存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001760"},{"id":"00010071","register_sub_id":"101","register_pk":"196218","name":"木屋旅館本館","kana":"きやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県宇和島市本町追手2-86-12","lat":33.21855607,"lng":132.56828606,"geo_status":"db","era":"明治44／平成23改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積269㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"38 － 0110","desc":"宇和島城下の南東側で、通りに南面する二階建の木造旅館。一階は二〇メートル超の間口に差物を通し、出格子を設ける。桁行中央部を玄関ホールや階段室とし、東西に配する客室では、室ごとに意匠を違えた座敷飾を備える。城下町の風情を伝える和風旅館である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010071"},{"id":"00014538","register_sub_id":"101","register_pk":"513952","name":"旧梅野商会主屋（砥部むかしのくらし館）","kana":"きゅううめのしょうかいおもや（とべむかしのくらしかん）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県伊予郡砥部町大南701-1他","lat":33.73831667,"lng":132.79288889,"geo_status":"db","era":"明治38年／昭和前期・同25年・同37年・令和2年改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"38 - 0171","desc":"町並みの中心部角地にある砥部焼窯元の店舗兼住居。切妻造平入桟瓦葺のつし二階建、正面は真壁造で二階に格子窓を開き、一階は表と前土間をショールームに改修していたが、当初の格子を整備した。一〇畳座敷は琵琶床と付書院を備えて窯元の隆盛を窺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014538"},{"id":"00014539","register_sub_id":"101","register_pk":"513953","name":"旧梅野商会蔵（砥部むかしのくらし館）","kana":"きゅううめのしょうかいくら（とべむかしのくらしかん）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県伊予郡砥部町大南701-1他","lat":33.73833611,"lng":132.79267778,"geo_status":"db","era":"明治38年／昭和37年改修、令和2年移築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積81㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"38 - 0172","desc":"砥部焼窯元の土蔵で元は店舗北隣の辻角に位置した。切妻造桟瓦葺の土蔵造二階建、小屋組はトラス構造、元は腰板張で道に出荷口を設けた。出荷作業用の倉庫で、庇付の窓が多く、吹抜は砥部焼の荷揚げ荷降ろしに用いた。街路沿いに位置して砥部焼の歴史を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014539"},{"id":"00006254","register_sub_id":"101","register_pk":"107238","name":"旧下芳我家住宅主屋","kana":"きゅうしもはがけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県喜多郡内子町内子1946他","lat":33.55265259,"lng":132.65316879,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階一部平屋建、瓦葺、建築面積248㎡、渡廊下付","structure_material":"木造2階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"38 － 0074","desc":"内子町八日市護国伝建地区に続く商店街通りに北面して建つ。間口は約１９ｍの規模で木造２階建，入母屋造。南側に木造平屋建の離れが付く。正面は白漆喰と鼠漆喰を塗り分けて意匠を凝らし，屋根は千鳥破風に鶴の懸魚を付ける。重厚な町並み景観を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006254"},{"id":"00014696","register_sub_id":"101","register_pk":"515238","name":"旧村上家住宅貸家","kana":"きゅうむらかみけじゅうたくかしや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県大洲市大洲字志保町東378","lat":33.50676667,"lng":132.54842222,"geo_status":"db","era":"江戸後期／昭和前期・令和元年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積39㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"38 - 0181","desc":"大洲城下の志保町通に西面する付属屋北隣に建つ町家。二階建切妻造平入桟瓦葺で下屋を付し、二階前面には出窓を設ける。内部一階は前土間形式で、二階は二室で西室を床構え付座敷とし、縁を付して通りを望む。建ちが低く、地域の歴史的景観をつくる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014696"},{"id":"00014110","register_sub_id":"101","register_pk":"508370","name":"旧八木商店本店内蔵","kana":"きゅうやぎしょうてんほんてんうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-1他","lat":34.10741389,"lng":132.96712222,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積36㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0159","desc":"住居棟南に接続する内蔵。土蔵造二階建、切妻造本瓦葺。切石積基壇上に建ち、壁は鉢巻まで漆喰塗込め、腰は竪板張。東面の土戸の開口枠を花崗岩で精緻につくる。内部は１、２階とも１室で、書類や貴重品を収納。小屋組はキングポストトラス。庭の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014110"},{"id":"00014112","register_sub_id":"101","register_pk":"508372","name":"旧八木商店本店表塀","kana":"きゅうやぎしょうてんほんてんおもてへい","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-2他","lat":34.10724444,"lng":132.96740556,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造、瓦葺、総延長28m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0161","desc":"店舗から南に延びる通りに面した表塀。柱を半間毎に立て鉄棒の控えをとり、腰は板張、上部は土壁で欄間に開口を開く。屋根は桟瓦葺。離れ位置から高さを低め、離れ両脇に潜戸を設けて庇を架ける。総延長２８メートル。蟹工船で財をなした豪商の表構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014112"},{"id":"00014108","register_sub_id":"101","register_pk":"508368","name":"旧八木商店本店座敷","kana":"きゅうやぎしょうてんほんてんざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-1他","lat":34.10746667,"lng":132.96733056,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0157","desc":"店舗棟の西に建つ平屋建の入母屋造桟瓦葺。続き間座敷の南に入側を設け縁を廻す。襖や板戸の日本画は大智勝観作。座敷の床柱に栂の四方柾を用いる等良材を多用。小屋組はトラス風。天井が高く、縁にはガラス戸を建て廻らし庭を望む。近代和風の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014108"},{"id":"00014109","register_sub_id":"101","register_pk":"508369","name":"旧八木商店本店住居棟","kana":"きゅうやぎしょうてんほんてんじゅうきょとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-1他","lat":34.10753056,"lng":132.96715833,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積344㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0158","desc":"座敷棟の西に建つ住居棟。寄棟造で通り土間両脇を切妻造とする桟瓦葺。通り土間の北に台所、南に玄関の間、居間、茶の間を並べ、奥には続き間座敷等四室を配する。座敷は赤松の床柱の床棚を備え、襖を菊文の布張、欄間を菊透彫とした、寛いだ空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014109"},{"id":"00014107","register_sub_id":"101","register_pk":"508367","name":"旧八木商店本店店舗","kana":"きゅうやぎしょうてんほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-1他","lat":34.10741389,"lng":132.96745,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0156","desc":"波止浜港の本町通りで廻船業を営んだ商家の東面する店舗。つし二階建入母屋造桟瓦葺。正側面に下屋を廻す。南に座敷を配し正面に切妻を見せる。東面北に玄関を開け南は出格子を建てる。玄関土間沿いに一二畳、南に座敷二室を配し、いずれも良材を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014107"},{"id":"00014111","register_sub_id":"101","register_pk":"508371","name":"旧八木商店本店離れ","kana":"きゅうやぎしょうてんほんてんはなれ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-1他","lat":34.10721111,"lng":132.96734167,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0160","desc":"敷地南西に位置する隠居屋。表塀越しに見える平屋建で切妻造桟瓦葺。Ｌ字形平面で西に続き間座敷、南に水屋付４畳半茶室を配置。茶室は床柱を赤松の皮付丸太とし下地窓を開けるが、南西面には大きなガラス障子を建て明るく安らいだ風情。庭からの点景をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014111"},{"id":"00004058","register_sub_id":"101","register_pk":"105048","name":"佐々木酒造主屋","kana":"ささきしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県伊予郡砥部町総津785","lat":33.62839941,"lng":132.79822104,"geo_status":"db","era":"明治41頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0059","desc":"村内中央を南北に通る旧街道に東面して建つ。南北に長い敷地の北方に位置し，北東部に庭園をとる。間口７間規模で，外観は真壁造とし，中央に店舗の入口，その北に出格子窓を配し，２階北方に座敷を設ける。１階庇の出桁を支持する持送り板に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004058"},{"id":"00003715","register_sub_id":"101","register_pk":"104705","name":"篠永酒造主屋","kana":"しのながしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県四国中央市具定町正之森250-1","lat":33.96810272,"lng":133.52557658,"geo_status":"db","era":"明治19頃／大正6増築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積186㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"38 － 0044","desc":"市北部を東西に横断する四国霊場八十八ヶ所遍路道に面して建つ。入母屋造，桟瓦葺，平入の木造つし２階建。腰竪板張の真壁造で，身舎を出桁造とし，妻には狐格子をあしらう。大棟の胴板には波間に泳ぐ魚を象った飾瓦を張付ける。巡礼路の上質な景観構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003715"},{"id":"00003716","register_sub_id":"101","register_pk":"104706","name":"篠永酒造門","kana":"しのながしゅぞうもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県四国中央市具定町正之森250-1","lat":33.96796669,"lng":133.52562891,"geo_status":"db","era":"明治19頃","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造、瓦葺、間口1.8m、左右袖塀付","structure_material":"木造","registered":"2003.12.01(平成15.12.01)","register_no":"38 － 0045","desc":"主屋の南側に接続し，街路に面して建つ。間口１間，桟瓦葺，一軒疎垂木とした門で，棟の両端部に主屋と同様の雲形の鳥衾をたちあげ，門の両脇には主屋の腰竪板張と高さを揃えた袖壁を配する。簡素ながら丁寧なつくりで，街路景観に彩りを添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003716"},{"id":"00002698","register_sub_id":"101","register_pk":"103688","name":"上甲家住宅","kana":"じょうこうけじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県宇和島市吉田町東小路甲71-1","lat":33.28000935,"lng":132.54051914,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造平屋建、瓦葺、建築面積174㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"38 － 0025","desc":"市中心部にあり，酒・醤油販売等を生業とした商家の建物。大規模な和小屋を架けた切妻造平入の土蔵造とし，正面の真壁の上部に格子形の窓を左右対称に配する。現在，住居，事務所，食堂として利用し，街路景観の重要な要素として，町民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002698"},{"id":"00002180","register_sub_id":"101","register_pk":"103170","name":"住友化学工業愛媛工場歴史資料館","kana":"すみともかがくこうぎょうえひめこうじょうれきししりょうかん","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県新居浜市惣開町5-1","lat":33.96112493,"lng":133.26166255,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0011","desc":"住友銀行新居浜支店として建設。港近くに位置する。野口孫市率いる住友臨時建築部の最初期の作品で，軒回りの密度の高いディテールと，陸アーチと水平目地，胴蛇腹とによる端正なファサード構成に初期住友営繕の作風の一端がうかがわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002180"},{"id":"00003159","register_sub_id":"101","register_pk":"104149","name":"都築酒店店舗及び主屋","kana":"つづきさけてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県喜多郡内子町小田322","lat":33.57027355,"lng":132.80432842,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積122㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0036","desc":"街路に面して建つ。妻面は塗込とし，両妻街路側に袖卯建を張り出す。大戸口が改造されている他は格子戸の建具も良く残り，内部に箱階段を備える。２階街路側の半分に手摺を設けて開放的な作りとし，２階階高を高く取るなど，明治期の店舗兼住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003159"},{"id":"00008073","register_sub_id":"101","register_pk":"128904","name":"森家住宅主屋","kana":"もりけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県松山市三津1-191他","lat":33.86523033,"lng":132.71234834,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積156㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"38-0094","desc":"通りに東面して建つ。間口８．８ｍの木造２階建で、その南に通路を挟んで炊事場や風呂などを設ける。切妻造桟瓦葺、正・背面に下屋庇を付ける。正面は２階壁面を軒裏まで銅板張とし、１階は北寄りの腰に大きな御影石を貼るなど、特色ある表情を造り上げている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008073"},{"id":"00003752","register_sub_id":"101","register_pk":"104742","name":"川田家住宅蔵","kana":"かわだけじゅうたくくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県安芸郡田野町2165","lat":33.42650028,"lng":134.00727629,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0109","desc":"問屋業時代の物品蔵。主屋の北西に位置し，南北棟で建つ。桁行４間梁間２間半規模，切妻造，桟瓦葺の２階建土蔵で，東面南寄りに戸口を設ける。外観は土佐漆喰塗壁に５段の水切瓦を付けた土蔵建築で，破風部等にも丁寧な仕事ぶりが窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003752"},{"id":"00003751","register_sub_id":"101","register_pk":"104741","name":"川田家住宅主屋","kana":"かわだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡田野町2165","lat":33.4262867,"lng":134.00734765,"geo_status":"db","era":"明治元","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積153㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0108","desc":"旧国道に南面する敷地に道路からやや退いて東西棟で建つ。桁行６間梁間４間半規模，切妻造，桟瓦葺の木造平屋建で，南面全面に下屋を架ける。西方を下手とし，東南角に８畳座敷を設け，Ｌ字型に縁を廻す。幕末から明治初期にかけての商家の表構えをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003751"},{"id":"00006341","register_sub_id":"101","register_pk":"107324","name":"河田商店店舗兼主屋","kana":"かわだしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡安田町大字安田1791","lat":33.43739534,"lng":133.98194921,"geo_status":"db","era":"明治期／昭和中期改修","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0230","desc":"通りに東面して建つ木造平屋建の町家。桁行５間梁間７間の切妻造平入で、屋根は左桟瓦葺とする。背面南寄りに釜屋を突出する。内部は当初２列６室の居室であったが、表側の板間と下屋部分を土間に改修した。当地の町家の伝統を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006341"},{"id":"00012251","register_sub_id":"101","register_pk":"353052","name":"旧竹村呉服店主屋","kana":"きゅうたけむらごふくてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県高岡郡佐川町字東町甲1300","lat":33.499204,"lng":133.289512,"geo_status":"db","era":"安永6年(1777)頃／明治初期・平成6年・同27年改修、大正前期増築","year":1777,"year_source":"db","year_min":1777,"year_max":1777,"year_label":null,"structure":"木造2階建、瓦葺、建築面積113㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"39-295","desc":"佐川町中心部に位置する旧呉服店の主屋。木造二階建、建築面積一一三平方メートルで、東寄りを土間とし、西寄りの床上部に二列各三室を配す。屋根は街路側に妻を向け桟瓦を葺く。北六畳間の座敷は、長押を廻さず簡素な造りとするなど、古式を残す民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012251"},{"id":"00012252","register_sub_id":"101","register_pk":"353053","name":"旧竹村呉服店店舗及び表蔵","kana":"きゅうたけむらごふくてんてんぽおよびおもてくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県高岡郡佐川町字東町甲1300","lat":33.499135,"lng":133.289547,"geo_status":"db","era":"文政11年(1828)頃／明治5年頃・平成6年・同27年改修","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"店舗 木造2階建、瓦葺、建築面積60㎡ 表蔵 土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"店舗 木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"39-296","desc":"敷地南端、主屋の街路側に建つ。西寄に畳敷のミセを配し、中央部は土間とし、東端部に表蔵を配して一体に屋根をかける。店舗部分の正面には庇をかけ、腰は店舗・表蔵とも海鼠壁とするが、表蔵は四半貼とし特徴ある外観を創る。地域の歴史を今に伝える建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012252"},{"id":"00012253","register_sub_id":"101","register_pk":"353054","name":"旧竹村呉服店土蔵","kana":"きゅうたけむらごふくてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高岡郡佐川町字東町甲1300","lat":33.499313,"lng":133.289466,"geo_status":"db","era":"明治中期／平成6年・同27年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"39-297","desc":"敷地北西隅に建つ二階建、置屋根形式の土蔵。小屋は登梁を折置とし、登梁上に棟木、母屋桁、軒桁を渡し、垂木を用いず直接化粧板を置く架構。外観は庭に面する東・南を漆喰塗とするが、西・北面は一部板張とする。庭と一体となり伝統的な敷地景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012253"},{"id":"00011004","register_sub_id":"101","register_pk":"208974","name":"旧三浦家住宅店舗","kana":"きゅうみうらけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県須崎市青木町7-1","lat":33.389903,"lng":133.289544,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0284","desc":"土蔵造二階建、東西棟の寄棟造、桟瓦葺で、東と南が道路の敷地南東隅に建つ。一階は南面中央に正玄関、東面に脇玄関を設け、高い格天井の事務所、二階は床付座敷や板間とする。出桁造で三段持ち出しの軒廻り、腰石張で黒漆喰塗の外壁など、上質で重厚な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011004"},{"id":"00006755","register_sub_id":"101","register_pk":"107738","name":"久保呉服店店舗兼主屋","kana":"くぼごふくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1849","lat":33.438648,"lng":133.98137195,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0221","desc":"町のほぼ中心の角地に東面して建つ。桁行６間、梁間４間半、木造平屋建、切妻造、桟瓦葺とする。北側に間口４間の店舗を配し、南側にトコ付の座敷６畳と次の間４畳半を並べ、敷地南端の庭に沿って縁側を設ける。妻側の竪板張の外観が往時の雰囲気を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006755"},{"id":"00003755","register_sub_id":"101","register_pk":"104745","name":"隅田家住宅主屋","kana":"すみだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡田野町2363-1","lat":33.42696606,"lng":134.00353447,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0112","desc":"旧国道に南面して東西棟で建つ。桁行３間半梁間５間半規模，切妻造，桟瓦葺の木造２階建で，主として１階を店舗，２階を居住部とし，１階正面中央に８寸角の柱を入れる。たちの高いつくりに特徴があり，周囲の低平な家並みの中で際だった存在になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003755"},{"id":"00003757","register_sub_id":"101","register_pk":"104747","name":"隅田家住宅精米工場","kana":"すみだけじゅうたくせいまいこうじょう","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡田野町2363-1","lat":33.42699538,"lng":134.00360398,"geo_status":"db","era":"昭和初期／昭和20頃増築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0114","desc":"主屋の東側に東西棟で建つ。桁行３間梁間５間半，切妻造，桟瓦葺の木造平屋建で，南面に下屋を差し掛けてつし２階建風の外観をつくる。米穀商に欠くことの出来ない施設で，戦後直ぐに背面側桁行３間分をトラス架構で拡張している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003757"},{"id":"00001969","register_sub_id":"101","register_pk":"102959","name":"竹崎家住宅（旧高田屋）蔵","kana":"たけざきけじゅうたく（きゅうたかだや）くら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1699","lat":33.42465842,"lng":134.02186975,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0019","desc":"国道５５号線に面した角地に建つ。桁行５間，梁行２間で，西側の桁行２間分を２階建とし，南の平の面に入口を設け，主屋土間を蔵前とする。外観は，石積基礎，腰を押縁下見とし，上部の土佐漆喰壁に水切瓦を付けるなど当地方土蔵建築の特色を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001969"},{"id":"00001967","register_sub_id":"101","register_pk":"102957","name":"竹崎家住宅（旧高田屋）主屋","kana":"たけざきけじゅうたく（きゅうたかだや）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1699","lat":33.42468946,"lng":134.02171847,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0017","desc":"樟脳業で栄え，民権運動の指導者を出した竹崎家の店舗兼住宅で，国道に面する蔵の南方に建つ。桁行３間，梁行６間，南北棟，切妻造，桟瓦葺，平入の主体部の南妻面に奥行１間の下屋をだし，北に方２間の土間兼蔵前を突き出す。平屋建商家建築の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001967"},{"id":"00003762","register_sub_id":"101","register_pk":"104752","name":"谷雄三家住宅主屋","kana":"たにゆうぞうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡田野町字住吉南2425－1","lat":33.42681997,"lng":134.00354182,"geo_status":"db","era":"明治7","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造平屋建一部2階建、瓦葺、建築面積80㎡","structure_material":"木造平屋建一部2階建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0119","desc":"旧国道に北面して東西棟で建つ。桁行４間半梁間５間，切妻造，桟瓦葺の木造つし２階建で，正面西方を土間，東方をミセに充て，奥に６畳２室を並べる。正面下屋付きで，つし２階は土佐漆喰塗壁，ミセ正面には出格子をはめて商家の表構えを整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003762"},{"id":"00006262","register_sub_id":"101","register_pk":"107246","name":"つとや店舗兼主屋","kana":"つとやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡安田町大字安田1670","lat":33.43729232,"lng":133.98032144,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積75㎡","structure_material":"木造平屋一部2階建","registered":"2007.07.31(平成19.07.31)","register_no":"39 － 0215","desc":"北側道路に面して建つ町家建築。桁行４間，梁間５間の規模で，木造平屋一部２階建，切妻造，桟瓦葺とする。表土間を店とし，東寄り通り土間に作業場，奥に８畳座敷を設ける。２階には４畳半２室を設ける。正面下屋上部に水切り瓦を付け，地域的特色をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006262"},{"id":"00006348","register_sub_id":"101","register_pk":"107331","name":"西岡呉服店店舗","kana":"にしおかごふくてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡安田町大字安田1807","lat":33.43785893,"lng":133.98112644,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積107㎡","structure_material":"木造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0216","desc":"町のほぼ中心地に位置し、角地に東面して建つ。桁行７間、梁間４間半、木造２階一部平屋建で、切妻造、桟瓦葺とする。１階店舗内部は土間と畳敷部分からなり、つし２階が倉庫、２階が作業場となる。妻側の竪板張や漆喰塗仕上げの外観が往時の雰囲気を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006348"},{"id":"00001970","register_sub_id":"101","register_pk":"102960","name":"西尾家住宅主屋","kana":"にしおけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡奈半利町乙1578","lat":33.42590866,"lng":134.02130749,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積124㎡","structure_material":"木造平屋一部2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0020","desc":"旧道に面して建つもと旅籠屋。桁行３間半，梁行５間，東西棟，切妻造，桟瓦葺の平屋建の西側に桁行２間半規模の２階屋を増築。平屋部分は，４畳半を２列３室に並べた６間取で，旧道沿いの北面に下屋を出す。２階屋は二重屋根風に妻面をみせる点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001970"},{"id":"00003167","register_sub_id":"101","register_pk":"104157","name":"濱田家住宅店舗","kana":"はまだけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1564-3","lat":33.4259415,"lng":134.02188293,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0071","desc":"奈半利町中心街の三叉路の北西角地に建つ。桁行５間梁間５間，東西棟，切妻造の木造つし２階建店舗の北に桁行３間半規模の平屋建が南北棟で取り付く。現在は呉服店として南北店舗を一体的に使用する。もと造り酒屋部とともに奈半利の町並み景観の中心的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003167"},{"id":"00003168","register_sub_id":"101","register_pk":"104158","name":"濱田家住宅煉瓦蔵","kana":"はまだけじゅうたくれんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1564-3","lat":33.425907,"lng":134.02186642,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造2階建、瓦葺、建築面積34㎡","structure_material":"煉瓦造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0072","desc":"店舗の北に接して建つ。桁行８．５ｍ梁間４ｍ規模の木骨造外部煉瓦長手積で，桟瓦葺の寄棟屋根を東西棟で架ける。北店舗を蔵前とした平入で，内部東方に半円の廻り階段を設置し，２階に洋風手摺を廻す。周囲の水切瓦と土佐漆喰の土蔵と対照をなし際だつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003168"},{"id":"00003165","register_sub_id":"101","register_pk":"104155","name":"東山家住宅蔵","kana":"ひがしやまけじゅうたくくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1281-2","lat":33.42362121,"lng":134.02125038,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積87㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0069","desc":"主屋の北方に建つ。桁行４間半梁間２間半，南北棟，切妻造，桟瓦葺の２階建土蔵の東に桁行２間半，東西棟，切妻造，桟瓦葺で南方に下屋を延ばした平屋建土蔵が取り付く。敷地西北隅の角地に水切瓦と土佐漆喰塗壁を見せる。奈半利の町並み景観の核となる存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003165"},{"id":"00003163","register_sub_id":"101","register_pk":"104153","name":"東山家住宅主屋","kana":"ひがしやまけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1281-2","lat":33.42348482,"lng":134.02123206,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0067","desc":"国道から南に入った市街中心地に位置する。道路に西面して南北棟で建つ。桁行５間半梁行６間規模，入母屋造，桟瓦葺のつし２階建で，東に茶の間，南に釜屋を付属させる。北方上手正面には連子格子をはめ，つし２階は真壁風につくり中央に特徴的な窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003163"},{"id":"00003743","register_sub_id":"101","register_pk":"104733","name":"普光江家住宅主屋西棟","kana":"ふこうえけじゅうたくしゅおくにしとう","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡田野町2051","lat":33.42778837,"lng":134.01022407,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0100","desc":"主屋東棟の西に建つ店舗部で，東棟とは屋根を一体に架ける。桁行３間梁間５間規模，東西棟，切妻造，桟瓦葺の平入，木造つし２階建で，内部北側は土間，南側は釜屋とする。帳場及び居住部の東棟と一体となって商家の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003743"},{"id":"00003742","register_sub_id":"101","register_pk":"104732","name":"普光江家住宅主屋東棟","kana":"ふこうえけじゅうたくしゅおくひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡田野町2051","lat":33.42781931,"lng":134.01032431,"geo_status":"db","era":"明治初期／大正13移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0099","desc":"田野町の中心街弓道に北面して建つ。桁行４間梁間４間規模，東西棟，切妻造，桟瓦葺の木造つし２階建で，内部は田の字型４室間取とし，道路沿いの北面には連子を入れる。東妻面の土佐漆喰塗壁に３段の水切瓦が土佐の土蔵造建築の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003742"},{"id":"00009675","register_sub_id":"101","register_pk":"194671","name":"前田家住宅店舗兼主屋","kana":"まえだけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸市本町5-1736-8","lat":33.50137998,"lng":133.8977987,"geo_status":"db","era":"昭和4頃／昭和後期改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"39 － 0273","desc":"遍路道の角地に北面する。つし二階建、入母屋造及び切妻造桟瓦葺で、東南隅に平屋を張出す。軸部は良材を用いて丁寧につくる。外壁は腰を瓦張とし、屋根に左桟瓦を葺き、東壁面に土佐漆喰の水切瓦を四段付ける等、当地方の住宅の特色をよく示す良質な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009675"},{"id":"00009676","register_sub_id":"101","register_pk":"194672","name":"前田家住宅土塀","kana":"まえだけじゅうたくどべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸市本町5-1736-8","lat":33.50130561,"lng":133.89770619,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土塀、瓦葺、延長5.8m","structure_material":"土塀","registered":"2013.06.21(平成25.06.21)","register_no":"39 － 0274","desc":"主屋南西端に接続し、敷地の西面を画する。南北棟桟瓦葺。北半を主屋南面庇の軒高に揃え、南半を高さを抑えて連ねる。全体を土佐漆喰で塗込めており、棟にはひも漆喰を施して台風等から守る工夫がなされる。東面では左桟瓦を使用し、地方的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009676"},{"id":"00012845","register_sub_id":"101","register_pk":"367748","name":"岬観光ホテル新館","kana":"みさきかんこうほてるしんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県室戸市室戸岬町字白濱4037他","lat":33.30150278,"lng":134.18630972,"geo_status":"db","era":"昭和39年頃","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"木造2階建、瓦葺、建築面積162㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"39 － 299","desc":"本館背面に接続する寄棟造の二階建で、外壁縦板張とする。内部は上下階とも海を望む東側に和風の客室三室を設け、一部客室に浴室・便所を備える。製材を用い、水平・垂直を強調した床や欄間の意匠が時代感覚を現す。観光地室戸岬の発展期の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012845"},{"id":"00012844","register_sub_id":"101","register_pk":"367747","name":"岬観光ホテル本館","kana":"みさきかんこうほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県室戸市室戸岬町字白濱4037他","lat":33.30150278,"lng":134.18630972,"geo_status":"db","era":"昭和9年頃／昭和中期改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階一部3階地下1階建、瓦葺、建築面積274㎡","structure_material":"木造2階一部3階地下1階建","registered":"2019.03.29(平成31.03.29)","register_no":"39 － 298","desc":"室戸岬南端の海岸沿いに建つホテル。木造二階建、切妻造妻入で、西面に玄関ポーチを出し、下見板張の妻に窓を設けた洋風の外観とする。玄関や廊下は大壁上部に繰形を廻すなど洋風とするが、客室は畳敷の和室とする。観光開発萌芽期の室戸岬の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012844"},{"id":"00006340","register_sub_id":"101","register_pk":"107323","name":"南商店内塀","kana":"みなみしょうてんうちべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1771-1","lat":33.43697907,"lng":133.98168936,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"コンクリート造、瓦葺、延長7.0m","structure_material":"コンクリート造","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0229","desc":"主屋背面の中坪を限るコンクリート塀。東側釜屋と南側便所の目隠しで、折れ曲がり７．０ｍ、総高１．７ｍ、基底幅０．５ｍ。基部はモルタルで亀甲形に塗る。壁はヒル石を混ぜたモルタル塗で竪目地を表し、頂部は瓦を葺く。丁寧な造りで庭園景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006340"},{"id":"00006344","register_sub_id":"101","register_pk":"107327","name":"南商店外塀","kana":"みなみしょうてんそとべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1771-1","lat":33.43679467,"lng":133.98154237,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"コンクリート造、瓦葺、延長6.0m","structure_material":"コンクリート造","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0228","desc":"敷地の南西隅を限る塀。西側道路から敷地の南面へ折れ曲がる延長６．０ｍ。基部は大ぶりの浜石を切込み矧ぎで３段積とする。壁体はコンクリート造で、蛇腹２段を造り、頂部には桟瓦を葺く。総高１．８ｍ、基底幅０．６ｍ。街路景観のアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006344"},{"id":"00006339","register_sub_id":"101","register_pk":"107322","name":"南商店店舗兼主屋","kana":"みなみしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1771-1","lat":33.43695828,"lng":133.98161925,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0227","desc":"通りに北面する、つし２階建の町家である。間口５間半の切妻造桟瓦葺で、前後に瓦葺庇がつく。内部は表を土間の店舗、奥を６畳４室とする。背面東端に釜屋、西端に渡廊下を介して便所風呂が接続。妻壁は土佐漆喰塗で水切り瓦５段で飾るなど地域的特色を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006339"},{"id":"00004456","register_sub_id":"101","register_pk":"105446","name":"矢野家住宅主屋","kana":"やのけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県土佐市高岡町甲2145-1","lat":33.4965793,"lng":133.42239383,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積112㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0170","desc":"街道に北面して建つ。間口４間，東西棟，切妻造，平入のつし２階建で，東側を通り土間とし，西側南に南北棟，切妻造，平屋建の居室部を突き出す。正面側は左瓦を使用し，外壁黒漆喰塗で，１階両脇の腰を海鼠壁とし，２階軒下部などに水切瓦を付けるのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004456"},{"id":"00004062","register_sub_id":"101","register_pk":"105052","name":"山中家住宅主屋","kana":"やまなかけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県吾川郡いの町長沢131-28","lat":33.725956,"lng":133.30687,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、瓦葺、建築面積190㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0130","desc":"大森川と吉野川本流の合流点近くに位置する。木造２階建の旅館建築で，１階の平面規模は桁行９間梁行４間半とし，２階の主屋根は片入母屋に造る。地元産の良材を用いているほか，玄関上部などに鶴，亀，鯉など吉祥の漆喰鏝絵を施しているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004062"},{"id":"00002095","register_sub_id":"101","register_pk":"103085","name":"山本家住宅主屋","kana":"やまもとけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香美市土佐山田町東本町5-2-11","lat":33.60787042,"lng":133.69270062,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積49㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"39 － 0034","desc":"土佐山田町の市街を東西に貫通する旧道沿いの細長い商店街に北面して建つ。木造２階建，切妻造，桟瓦葺，平入の町家で，地元の建築家が改修して設計事務所として使用するとともに，主屋シモテ部をギャラリーとし地元の活性化にも貢献している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002095"},{"id":"00011001","register_sub_id":"101","register_pk":"208971","name":"料亭得月楼喜久の間","kana":"りょうていとくげつろうきくのま","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県高知市南はりまや町一丁目255-3他","lat":33.55896,"lng":133.544047,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0281","desc":"喜久の間は高陽の間の西に納戸付の廊下で接続している。木造平屋建、切妻造、桟瓦葺で、一二畳の西側に床とＬ型付書院を構え、南の庭園側に縁を設け、魚梁瀬杉を用いた棹縁天井を張る。長押を用いないなど、数寄屋風意匠で、高陽の間と対比的な造形をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011001"},{"id":"00011000","register_sub_id":"101","register_pk":"208970","name":"料亭得月楼高陽の間","kana":"りょうていとくげつろうこうようのま","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県高知市南はりまや町一丁目255-3他","lat":33.558882,"lng":133.544119,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0280","desc":"木造平屋建、寄棟造、桟瓦葺で、江戸時代末期の庭園に南面して建つ。ゆったり構えた大床と棚、丸窓の張り出し型の附書院、幾何学模様風の格縁天井などに見所がある。面取り材を駆使した繊細な数寄屋風で、新規性も採り入れた意欲的な造形を内包した和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011000"},{"id":"00011003","register_sub_id":"101","register_pk":"208973","name":"料亭得月楼正門","kana":"りょうていとくげつろうせいもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県高知市南はりまや町一丁目254他","lat":33.55921527,"lng":133.54414799,"geo_status":"db","era":"昭和34／昭和60改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造、瓦葺、間口5.9m、西方袖塀付","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"39-0283","desc":"はりまや橋東方、北と南が街路に面して敷地を構える。北面西寄りに建つ正門は、桟瓦葺の横長門で、両側への引き込み戸、皮剥き磨き丸太を用いた柱や桁など、新しい和風意匠を目指した独特な門であるが、老舗の格式に相応しい雄大な外観をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011003"},{"id":"00004441","register_sub_id":"101","register_pk":"105431","name":"料亭得月楼本館","kana":"りょうていとくげつろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県高知市南はりまや町1-17-3","lat":33.559063,"lng":133.544144,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積319㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0155","desc":"高知空襲による焼失後の復興建築。桁行１０間梁間６間規模，入母屋造，桟瓦葺の木造２階建で，北面中央東寄りに切妻造車寄を突出させて玄関とし，２階には天井に魚梁瀬杉の長尺物を用いた８０畳敷大広間を設ける。設計は高知県建築士会草創期会員の柳生濟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004441"},{"id":"00011002","register_sub_id":"101","register_pk":"208972","name":"料亭得月楼渡り廊下","kana":"りょうていとくげつろうわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県高知市南はりまや町一丁目256-4他","lat":33.558955,"lng":133.544229,"geo_status":"db","era":"昭和25／昭和32改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0282","desc":"本館から南に延びる廊下、その先端の待合、客間及び高陽の間への連絡部からなり、桟瓦葺とする。廊下は桁行三間半で、磨き丸太の化粧垂木を見せた船底天井とし、二間に一間半規模の待合は網代天井になる。丁寧な数寄屋風意匠で、全体の調和がよく取れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011002"},{"id":"00009854","register_sub_id":"101","register_pk":"195683","name":"アートスペース谷尾（旧十七銀行直方支店）","kana":"あーとすぺーすたにお（きゅうじゅうしちぎんこうのおがたしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県直方市古町929-1他","lat":33.74602,"lng":130.72789524,"geo_status":"db","era":"大正2頃","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造及び煉瓦造2階建、鉄板葺、建築面積375㎡","structure_material":"木造及び煉瓦造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0110","desc":"角地に建つ木造二階建、鉄板葺で、南東隅を塔屋風に張出す。外壁は煉瓦風タイル小口貼で、基礎やバンド、窓台などに花崗岩を用いてアクセントとし、玄関廻りや柱形などの細部はゼツェッションでまとめる。地域のランドマークとして親しまれる、もと銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009854"},{"id":"00009853","register_sub_id":"101","register_pk":"195682","name":"石原商店店舗","kana":"いしはらしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県直方市殿町590-3","lat":33.74394755,"lng":130.72797208,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0109","desc":"前田園本店の北隣に並び建ち、木造二階建、切妻造桟瓦葺。二階正面に穿つ横長の大窓下に中二階用の小窓を並べて庇を付け、一階の軒庇とともに、三層構成の立面とする。内部のミセ上部を一部吹抜とし二階は座敷とする。前田園とともに良質な街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009853"},{"id":"00009540","register_sub_id":"101","register_pk":"194333","name":"上野ビル（旧三菱合資会社若松支店）旧分析室","kana":"うえのびる（きゅうみつびしごうしがいしゃわかまつしてん） きゅうぶんせきしつ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町1-14-1他","lat":33.90272449,"lng":130.81382588,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0083","desc":"倉庫棟の北側に東面にして建つ。木造平屋建、建築面積一一九平方メートル、切妻造瓦葺である。煉瓦造の周囲の建物にあわせて大壁造とし、窓は縦長窓、腰壁はスクラッチタイル張とする。石炭の品質分析を行った、石炭会社の現地事務所を特徴づける建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009540"},{"id":"00009539","register_sub_id":"101","register_pk":"194332","name":"上野ビル（旧三菱合資会社若松支店）倉庫棟","kana":"うえのびる（きゅうみつびしごうしがいしゃわかまつしてん） そうことう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町1-14-1他","lat":33.90243003,"lng":130.81376342,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積190㎡","structure_material":"煉瓦造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0082","desc":"本館の西側に東面して建つ。煉瓦造二階建、建築面積一九〇平方メートル、切妻造瓦葺、L字形の平面とし、東面に突出した妻に三菱の社標を掲げる。基礎や窓まわりに石材を用いるなど簡素ながらも確かなつくりで、当時の煉瓦造倉庫の技術的水準を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009539"},{"id":"00009538","register_sub_id":"101","register_pk":"194331","name":"上野ビル（旧三菱合資会社若松支店）本館","kana":"うえのびる（きゅうみつびしごうしがいしゃわかまつしてん） ほんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町1-14-1他","lat":33.90256983,"lng":130.8139627,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造3階建、建築面積465㎡","structure_material":"煉瓦造3階建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0081","desc":"若松港に面して建つ。煉瓦造三階建、建築面積四六五平方メートル、陸屋根である。左右対称の正面で、中央に玄関を突出する。縦長窓を規則的に配した重厚な外観に対して、内部は中央の吹き抜けを取り、鋳鉄製の柱やステンドグラスを用いて華やかに仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009538"},{"id":"00009541","register_sub_id":"101","register_pk":"194334","name":"上野ビル（旧三菱合資会社若松支店）門柱及び塀","kana":"うえのびる（きゅうみつびしごうしがいしゃわかまつしてん） もんちゅうおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町1-14-1他","lat":33.90233902,"lng":130.81405407,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"門柱 煉瓦造門柱6基 塀 煉瓦造、総延長115m","structure_material":"門柱 煉瓦造門柱6基 塀 煉瓦造","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0084","desc":"敷地正面である南面の東寄りと、北面の東寄りと西寄りの三箇所に門を開き、南、東、北の三面に塀を廻らす。煉瓦造、塀は総長一一五メートル、正門の門柱は高さ二・三メートルを測る。建設当時の姿をよく残し、石炭会社の現地事務所の構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009541"},{"id":"00012254","register_sub_id":"101","register_pk":"353055","name":"江頭家住宅主屋","kana":"えがしらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県大川市大字榎津字向町746-2","lat":33.207198,"lng":130.374194,"geo_status":"db","era":"江戸末期／昭和前期・同40年代増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積286㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"40-148","desc":"間口八間、奥行八間で入母屋造妻入の直屋に切妻造の角屋を直交し居蔵造とする当地域の大規模町家特有の形式を持つ。通り土間に沿ってミセ、チョウバ、チャノマなど並べ、上手に座敷二室を配す。大戸や蔀戸も良く残り、座敷飾りには華やかな意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012254"},{"id":"00012255","register_sub_id":"101","register_pk":"353056","name":"江頭家住宅門及び塀","kana":"えがしらけじゅうたくもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県大川市大字榎津字向町746-2","lat":33.207189,"lng":130.374048,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"門 木造、瓦葺、間口1.9m、塀 木造、瓦葺、延長7.0m","structure_material":"門 木造","registered":"2018.03.27(平成30.03.27)","register_no":"40-149","desc":"主屋正面の北側に矩折で接続する。門は間口一・九メートルで、両開板扉を吊る。塀は木造で、外側を大壁とし、軒は蛇腹に仕上げ、切妻造の屋根を架け、正面妻面を塗り込める。主屋とともに耐火性を重視した構えで、街路からの歴史的景観を良好に形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012255"},{"id":"00015397","register_sub_id":"101","register_pk":"532521","name":"旧玉乃井旅館","kana":"きゅうたまのいりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福津市津屋崎四丁目1023-1","lat":33.78803333,"lng":130.46295,"geo_status":"db","era":"明治42年／昭和9年頃・同37年増築、令和3年改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積322㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0237","desc":"津屋崎海岸の東側に建つ旧旅館。通りに東面する2階建桟瓦葺で北東に玄関を付す。各階、中廊下を東西に通して客室を並べ、2階は南西に続き間座敷を配し、連窓を建てた広縁を介して海を望む。増築を重ねて、部屋数を増やし、海水浴客の賑わいを伝える旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015397"},{"id":"00007322","register_sub_id":"101","register_pk":"108304","name":"旧古河鉱業若松ビル","kana":"きゅうふるかわこうぎょうわかまつびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町1-217他","lat":33.90237,"lng":130.812698,"geo_status":"db","era":"大正8／平成16改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造2階建、銅板一部スレート葺、建築面積297㎡","structure_material":"煉瓦造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"40 － 0059","desc":"鋭角の角地に敷地を占める、煉瓦造２階建。南西隅に大塔、南東に小塔を建てる。壁面はモルタル塗で、南面と西面は煉瓦タイル貼のピラスターを付け、その間に２連の縦長窓を上下階に開け、縦線を強調する。若松港のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007322"},{"id":"00001083","register_sub_id":"101","register_pk":"102073","name":"草野歴史資料館（旧草野銀行本店）","kana":"くさのれきししりょうかん（きゅうくさのぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市草野町草野411-1","lat":33.31929858,"lng":130.63545988,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造２階建，瓦葺，建築面積177㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"40 － 0005","desc":"久留米市の東部，旧御井郡の中心地として栄えた草野地区の地元銀行建築。木造平屋建，瓦葺寄棟屋根，下見板貼りの銀行店舗で，正面に千鳥破風の車寄ポーチを突き出す。門扉，鉄柵もよく遺されており，地方銀行の様子を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001083"},{"id":"00001149","register_sub_id":"101","register_pk":"132577","name":"草野歴史資料館（旧草野銀行本店）門","kana":"くさのれきししりょうかん（きゅうくさのぎんこうほんてん）もん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市草野町草野411-1","lat":33.31942952,"lng":130.63539017,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"石造，幅員2.9m，左右柵基壇18.7m附属","structure_material":"石造","registered":"1999.06.07(平成11.06.07)","register_no":"40 － 0009","desc":"銀行本館の前庭を前面街路と側面街路に沿って鈎型に囲うもので、正面中央に正門、側面に通用門を設け、高欄風の石造土台の上に鉄柵を建てる。資料館開館（昭和５９年）にあたり復元された門扉と鉄柵は地方銀行におけるアプローチ空間の有様をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001149"},{"id":"00008600","register_sub_id":"101","register_pk":"134996","name":"髙橋家住宅店舗兼主屋","kana":"たかはしけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市博多区下呉服町72","lat":33.60221698,"lng":130.40781532,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0064","desc":"博多町人町に位置し、竪町筋に北面する。間口五・六メートル奥行一二メートルの木造二階建。切妻造桟瓦葺で正面に庇を付ける。二階は格子戸、一階はガラス戸を全面にたてる。通り土間で正面にミセを設け、二階に座敷三室を配する。標準的な博多の近代町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008600"},{"id":"00015263","register_sub_id":"101","register_pk":"530687","name":"田所商店倉庫","kana":"たどころしょうてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県北九州市八幡東区祝町二丁目1189-18","lat":33.86414167,"lng":130.82921111,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造平屋建、瓦葺、建築面積51㎡","structure_material":"煉瓦造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"40 - 0228","desc":"東山一丁目の交差点南東に建つ旧茶製品用倉庫。煉瓦造東西棟の北面西寄りを北に突出して全体矩折とし、北西を隅切とした変形の寄棟造桟瓦葺。入隅部の戸口上に庇を付し、内部は１室の板敷。小屋組はキングポスト・トラス。鉱滓煉瓦を用いた地域性豊かな倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015263"},{"id":"00014214","register_sub_id":"101","register_pk":"508844","name":"百年庭園の宿翠水（旧旅館田川離れ）企救","kana":"ひゃくねんていえんのやど すいすい（きゅう りょかんたがわはなれ）きく","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市小倉北区古船場町9-1他","lat":33.87914167,"lng":130.88152778,"geo_status":"db","era":"昭和37年／同57年改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"40 - 0197","desc":"日本庭園の池庭に面して建つ高級旅館の離れ三棟のうち中央に建つ。木造平屋建入母屋造一部切妻造銅板葺、深い軒と高欄付の張り出し縁によりあたかも池に浮かぶ小船の風情を醸す。正統的な数寄屋の構成に近代的な設備や斬新な意匠を施す近代数寄屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014214"},{"id":"00014215","register_sub_id":"101","register_pk":"508845","name":"百年庭園の宿翠水（旧旅館田川離れ）玄海","kana":"ひゃくねんていえんのやど すいすい（きゅう りょかんたがわはなれ）げんかい","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市小倉北区古船場町9-1他","lat":33.879175,"lng":130.88141389,"geo_status":"db","era":"昭和37年／同57年改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積92㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"40 - 0198","desc":"日本庭園の池庭に面して建つ高級旅館の離れ三棟のうち西寄りに建つ。木造平屋建入母屋造一部切妻造銅板葺、竹や自然木の丸太を多用する古典的な詫びた草庵風建築への志向が認められる一方、幅広格天井風の竿縁の配置など斬新な近代数寄屋の特徴がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014215"},{"id":"00014213","register_sub_id":"101","register_pk":"508843","name":"百年庭園の宿翠水（旧旅館田川離れ）菅生","kana":"ひゃくねんていえんのやど すいすい（きゅう りょかんたがわはなれ）すがお","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市小倉北区古船場町9-1他","lat":33.87908611,"lng":130.88161667,"geo_status":"db","era":"昭和37年／同57年改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積126㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"40 - 0196","desc":"北九州を代表する高級旅館の離れで、多くの賓客を迎えてきた。平屋建入母屋造一部切妻造銅板葺で、伝統的な書院風の数寄屋の造りの中に、障子戸とガラス戸との間にカーテンを設けるなど、近代数寄屋としての新たな様式を形成しようとする意欲的な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014213"},{"id":"00014216","register_sub_id":"101","register_pk":"508846","name":"百年庭園の宿翠水（旧旅館田川離れ）渡り廊下","kana":"ひゃくねんていえんのやど すいすい（きゅう りょかんたがわはなれ）わたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市小倉北区古船場町9-1他","lat":33.87906111,"lng":130.88150556,"geo_status":"db","era":"昭和37年／同57年改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"40 - 0199","desc":"高級旅館の数寄屋風離れ三棟に接続する渡り廊下。木造平屋切妻造銅板葺、床は平瓦の四半敷で節目のある丸太の柱を根石の上に立て、天井は竹を詰め打ちにするなど野趣を表現しながらも飾り気のない瀟洒な意匠で、控えめながらも重要な役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014216"},{"id":"00013468","register_sub_id":"101","register_pk":"368564","name":"福岡県い業会館旧宿直棟","kana":"ふくおかけんいぎょうかいかんきゅうしゅくちょくとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県三潴郡大木町大字八町牟田3-1","lat":33.20713611,"lng":130.43318056,"geo_status":"db","era":"昭和11年／昭和18年、平成29年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"40 － 0175","desc":"本館と、本館西の勝手口から接続する。事務所の宿直等に使用した付属施設。木造平屋建入母屋造で漆喰仕上に腰竪板張と、本館と対照的な和風意匠を持つ。内部は八畳、六畳の二室を並べ、奥に台所を付す。本館とともに地域産業の近代化を物語る建物として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013468"},{"id":"00013467","register_sub_id":"101","register_pk":"368563","name":"福岡県い業会館本館","kana":"ふくおかけんいぎょうかいかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県三潴郡大木町大字八町牟田3-1","lat":33.20716111,"lng":130.43334167,"geo_status":"db","era":"昭和11年／昭和中期、平成26年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積130㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"40 － 0174","desc":"県内のい業関係５団体の事務所。木造二階建寄棟造で玄関ポーチを突出させる。外観は下見板張に付柱のスティックスタイルでまとめる。内部は一階が事務室、二階が会議室等だが、各室で天井意匠を変える等熟れた意匠を持つ。町内では希少な洋風建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013467"},{"id":"00009852","register_sub_id":"101","register_pk":"195681","name":"前田園本店倉庫","kana":"まえだえんほんてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県直方市殿町590-1","lat":33.74376968,"lng":130.72770498,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"煉瓦造及び木造2階建、瓦葺、建築面積111㎡","structure_material":"煉瓦造及び木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0108","desc":"店舗の後方に座敷などを介して東西棟で建ち、煉瓦造及び木造二階建、切妻造桟瓦葺である。東妻が出入口で西妻に鉄板張の扉を開き、周囲に窓を穿つ。外壁は鉄板張で内部をモルタル仕上とし、小屋はキングポストトラスを組む。茶などの保管用に建てられた倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009852"},{"id":"00009851","register_sub_id":"101","register_pk":"195680","name":"前田園本店店舗","kana":"まえだえんほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県直方市殿町590-1","lat":33.74381727,"lng":130.72799528,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積112㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0107","desc":"通りに東面し、木造二階建、切妻造桟瓦葺である。正面二階は出桁造で壁を黒漆喰で仕上げ、腰部と大振りの窓枠を銅板張とし、瓦葺の庇を付ける。一階内部はケヤキの良材を用いた普請でミセなどを配し、二階は座敷とする。近代直方の商家の様相を伝える店舗。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009851"},{"id":"00010237","register_sub_id":"101","register_pk":"198070","name":"門司ゴルフ倶楽部クラブハウス北棟","kana":"もじごるふくらぶくらぶはうすきたとう","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市門司区大字吉志字稗畑175-10","lat":33.863643,"lng":130.952782,"geo_status":"db","era":"昭和35","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造平屋建一部地下1階建、鉄板葺、建築面積434㎡","structure_material":"鉄筋コンクリート造平屋建一部地下1階建","registered":"2014.10.07(平成26.10.07)","register_no":"40 － 0112","desc":"南棟と接続して建ち、東西四〇メートル南北九・一メートルを測る平屋建。キャディー室などのサービス機能を集約して設備充実を図りつつ、プレイヤー用の浴室なども配置するが、プレイヤーとキャディーの動線が交錯しないよう合理的に計画された平面をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010237"},{"id":"00010236","register_sub_id":"101","register_pk":"198069","name":"門司ゴルフ倶楽部クラブハウス南棟","kana":"もじごるふくらぶくらぶはうすみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市門司区大字吉志字稗畑175-10","lat":33.86344,"lng":130.952728,"geo_status":"db","era":"昭和35","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積1257㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"40 － 0111","desc":"桁行五五メートル梁間二二メートルを測る鉄筋コンクリート造二階建のクラブハウス。開放的で水平線を強調した立面とし、内部は打放しコンクリートの躯体で大空間を確保し、丸太の小屋を組む。いわゆるレーモンドスタイルが遺憾なく発揮されたモダニズム建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010236"},{"id":"00010238","register_sub_id":"101","register_pk":"198071","name":"門司ゴルフ倶楽部スタートハウス","kana":"もじごるふくらぶすたーとはうす","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市門司区大字吉志字稗畑175-10","lat":33.862984,"lng":130.952213,"geo_status":"db","era":"昭和35","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"40 － 0113","desc":"木造平屋建で、桁行九・四メートル、梁間三・八メートルを測る。屋根や外壁はクラブハウスと同系色のオレンジ色に近い赤色塗装を施し、丸太の桁を現す。平面は三室とし、左右を待合、中央を管理室とする。腰高の水平連続窓を設け、開放感のある構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010238"},{"id":"00004301","register_sub_id":"101","register_pk":"105291","name":"料亭金鍋表門","kana":"りょうていきんなべおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町2-516、522、523","lat":33.90412422,"lng":130.80809936,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造、瓦葺、間口1.8m、塀延長3.9m付","structure_material":"木造","registered":"2004.07.23(平成16.07.23)","register_no":"40 － 0040","desc":"北と南が道路に面した細長い敷地で，表門は北辺際にある。左右には塀が延び，西塀は折れ曲がって，表門とともに玄関前庭を区画する。間口約２ｍで角柱を立て，腕木，軒桁，垂木に丸太を用い，ガラス欄間を嵌め込むなど，近代的な数寄屋風意匠になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004301"},{"id":"00004300","register_sub_id":"101","register_pk":"105290","name":"料亭金鍋本館","kana":"りょうていきんなべほんかん","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町2-516、522、523","lat":33.90385012,"lng":130.80818138,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造3階建、瓦葺、建築面積382㎡","structure_material":"木造3階建","registered":"2004.07.23(平成16.07.23)","register_no":"40 － 0039","desc":"木造３階建の老舗料亭。南北に細長い建物で，中廊下の東西に部屋を配した平面構成とし，２階に床・棚付３０畳の大広間を設ける。全体に良材を用い，洗練された質の高い数寄屋風で纏め，洋風も用いる。重厚な黒漆喰塗の外観は，地域の景観上，存在感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004300"},{"id":"00013007","register_sub_id":"101","register_pk":"368120","name":"料亭満佐表門及び塀","kana":"りょうていまさおもてもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市博多区中洲一丁目103他","lat":33.59064722,"lng":130.40837222,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"表門 木造、瓦葺、間口2.2m 塀 鉄筋コンクリート造、瓦葺、総延長107m、通用門付","structure_material":"表門 木造","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 163","desc":"敷地の東西北三面を区切る塀と門。表門は西面塀北寄りに間口四・五メートルの門口を開き、外側に庇、内側に片流れ下屋を付す。塀は鉄筋コンクリート造の桟瓦葺、西面塀を腰縦板張とし、東面塀北端に通用門を設ける。老舗料亭の風格ある店構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013007"},{"id":"00013003","register_sub_id":"101","register_pk":"368116","name":"料亭満佐主屋棟","kana":"りょうていまさしゅおくとう","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市博多区中洲一丁目103他","lat":33.59066944,"lng":130.40830833,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積236㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 159","desc":"中洲の一角にあり、主屋棟は那珂川沿いに西面して建つ。木造二階建、入母屋造及び切妻造桟瓦葺妻入で、正面北端に玄関を出す。外壁は聚楽大壁。一階に客室3室、二階に広間を設け、中廊下を通し、各室を異なる趣向の意匠とする。上質な新興数寄屋の料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013003"},{"id":"00013006","register_sub_id":"101","register_pk":"368119","name":"料亭満佐新館棟","kana":"りょうていまさしんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市博多区中洲一丁目103他","lat":33.590625,"lng":130.40850833,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 162","desc":"主屋棟の東側に渡廊下で接続する木造平屋建、切妻造桟瓦葺。南に一二畳の座敷と次の間、北に小座敷や便所を配する。座敷は西面に踏込床、床、床脇を備え、室境は壁引込み式の欄間付襖とする。横桟のみの障子や埋込み照明の平天井など新興数寄屋の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013006"},{"id":"00013005","register_sub_id":"101","register_pk":"368118","name":"料亭満佐厨房棟","kana":"りょうていまさちゅうぼうとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市博多区中洲一丁目103他","lat":33.59075,"lng":130.40843056,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 161","desc":"主屋棟背面に接続する切妻造、寄棟造及び入母屋造桟瓦葺の二階建で、一階中廊下の北に厨房や帳場、南に居室、二階に応接間等を設ける。居室や応接間は大壁で、横桟のみの建具や埋込み照明に細い竿縁を吹寄せで配する天井など、吉田五十八流の手法がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013005"},{"id":"00013004","register_sub_id":"101","register_pk":"368117","name":"料亭満佐離れ棟","kana":"りょうていまさはなれとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市博多区中洲一丁目103他","lat":33.59058889,"lng":130.40843333,"geo_status":"db","era":"昭和29年／昭和30年代増築","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 160","desc":"主屋棟の南東方に建つ木造平屋建、切妻造桟瓦葺銅板腰葺で、離れ、茶室、便所等からなる。離れは西面に床を設け、南東二面に縁を廻して月見台とする。茶室は東面に袋床を設け、名栗仕上の中柱や下地窓付の袖壁を備える。主屋から独立した風流な趣の離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013004"},{"id":"00005676","register_sub_id":"101","register_pk":"106664","name":"飯盛酒造主屋","kana":"いいもりしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市古枝甲122","lat":33.09236397,"lng":130.11395063,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、瓦葺、建築面積347㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0060","desc":"旧長崎街道多良往還に北面して建つ，間口１０間半の木造２階建。入母屋造，桟瓦葺で，東側土間部の外壁は塗屋造，西側の居室部は真壁造とする。居室部は１階が２列６室，２階は１０畳３室で，それぞれ表裏に縁を設ける。土間の背面南側には釜場が接続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005676"},{"id":"00001778","register_sub_id":"101","register_pk":"102768","name":"牛津赤れんが館（旧田中丸商店れんが造り倉庫）","kana":"うしづあかれんがかん（きゅうたなかまるしょうてんれんがづくりそうこ）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県小城市牛津町牛津586-1","lat":33.24764138,"lng":130.20427231,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造2階建、瓦葺、建築面積170㎡","structure_material":"煉瓦造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"41 － 0016","desc":"長崎街道の宿場町牛津の代表的商家で玉屋デパートの前身田中丸商店の煉瓦造２階建倉庫。軒下に周されたデンティル，石材と煉瓦を混用した妻面の空気孔，軽く湾曲した屋根形状などに見所をもつ。かつて商業で繁えた牛津の象徴的建築物として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001778"},{"id":"00002466","register_sub_id":"101","register_pk":"103456","name":"旧古賀銀行神埼支店","kana":"きゅうこがぎんこうかんざきしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県神埼市神埼町神埼字3-438","lat":33.308956,"lng":130.372818,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"41 － 0026","desc":"旧長崎街道に面して建つ。佐賀市に設立された古賀銀行の神埼支店として建設。正面中央にトスカナ式花崗石円柱に支持されたペディメントを配して玄関とし，モルタル洗出し仕上げでセセッション風の柱頭飾りなどを造り出す。大正期銀行支店建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002466"},{"id":"00005686","register_sub_id":"101","register_pk":"106674","name":"旧中島政次家住宅主屋","kana":"きゅうなかしままさつぐけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.09251381,"lng":130.11505412,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造2階建、瓦葺、建築面積175㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0070","desc":"多良往還を挟んで中島酒造場主屋の向いに建つ。間口５間半，奥行７間の木造２階建，入母屋造，桟瓦葺とする。外壁は白漆喰塗の大壁造で，２階窓に銅板張の防火扉がつく。内部は東側を土間，西側を居室とする。２階は表を物置，裏を１０畳座敷と次の間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005686"},{"id":"00004472","register_sub_id":"101","register_pk":"105462","name":"呉竹酒造主屋","kana":"くれたけしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2751","lat":33.09225567,"lng":130.11711754,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積400㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0049","desc":"旧長崎街道多良往還に南面して建つ。入母屋造，桟瓦葺，妻入の２階建で，間口７間半奥行８間半の規模。東面下屋部は事務所とし，玄関通り土間西側には４室を一列に並べる。たちの高い正面の構えに特色がある。棟梁は坂井武八で，欅など「各地名材」を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004472"},{"id":"00004869","register_sub_id":"101","register_pk":"105859","name":"桑原家住宅主屋","kana":"くわはらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県武雄市朝日町大字甘久1956-2","lat":33.21051475,"lng":130.04317817,"geo_status":"db","era":"明治15","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造2階建、瓦葺、建築面積231㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"41 － 0052","desc":"長崎街道に東面して建つ妻入町家。桁行９間梁間５間，切妻造，桟瓦葺の木造２階建で，南側に土間を通し，北側に店・納戸・仏間・座敷などを並べる。階上を塗り込めるが，２階北側客座敷の表側は開放的なつくりとする。棟木墨書から「棟梁橋口徳五郎」が判明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004869"},{"id":"00002712","register_sub_id":"101","register_pk":"103702","name":"小柳酒造主屋","kana":"こやなぎしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29870579,"lng":130.20287507,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0027","desc":"街道に東面して建つ。当地方に見られる切妻造，妻入の塗屋造町家で，主体部は桁行７間，梁間４間半とし，南面に１間半幅の下屋を設け，北に８畳座敷を角屋状に張り出す。近年の道路拡幅により正面の下屋を失っているが，小柳酒造の顔となる建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002712"},{"id":"00012256","register_sub_id":"101","register_pk":"353057","name":"齊藤商店店舗兼主屋","kana":"さいとうしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町字蛭子町427","lat":33.293184,"lng":130.200732,"geo_status":"db","era":"昭和2年頃／昭和40年代改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積157㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"41-109","desc":"城下町に建つ近代町家。木造二階建、切妻造平入の出桁造だが、建ちが高くトラス組の大屋根が特徴。一、二階とも四室を配し、欄間彫刻の松竹梅など意匠を凝らす。ガラスを多用し開放的な造りで、ミセの吹抜けやショウウインドウなど洋風意匠も巧みである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012256"},{"id":"00000714","register_sub_id":"101","register_pk":"101704","name":"杉光陶器店一の蔵","kana":"すぎみつとうきてんいちのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字馬場下甲728","lat":33.12969191,"lng":130.05996398,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造平屋建，瓦葺，建築面積89㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"41 － 0006","desc":"主屋の後方に位置し，南側の路地に沿って建つ切妻造，２階建の土蔵で，切石積の土台上に建ち外壁に縦板を貼る。かつて敷地の背後は塩田川に直接面し，舟運が盛んであった頃は河川から物資の出入が行われたと伝えるが，往時の様相を知る上でも貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000714"},{"id":"00000716","register_sub_id":"101","register_pk":"101706","name":"杉光陶器店三の蔵","kana":"すぎみつとうきてんさんのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字馬場下甲727","lat":33.12981639,"lng":130.05998888,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造平屋建，瓦葺，建築面積69㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"41 － 0008","desc":"主屋の北側に引き込んで建つ切妻造，妻入，２階建の土蔵で，明治末年から一時地元有志の出資により設立された塩田銀行の店舗として使われた。出入口の構えや正面の煉瓦壁は，その時の改造と考えられ，白漆喰塗の町家が連なるなかで特異な外観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000716"},{"id":"00000713","register_sub_id":"101","register_pk":"101703","name":"杉光陶器店主屋","kana":"すぎみつとうきてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字馬場下甲728","lat":33.12985997,"lng":130.059687,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造３階建，瓦葺，建築面積258㎡","structure_material":"木造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"41 － 0005","desc":"塩田川の舟運を用いた物資の集散地として栄えた長崎街道沿の町並みの一画に建つ入母屋造，妻入の土蔵造の大型町家で，正面左手に通り土間，右手に２列の居室を配する構成になる。近年の改装で内部店廻りは一変したが，奥向きの部屋は旧態を良く残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000713"},{"id":"00000715","register_sub_id":"101","register_pk":"101705","name":"杉光陶器店二の蔵","kana":"すぎみつとうきてんにのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字馬場下甲727","lat":33.12992843,"lng":130.05974924,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造平屋建，瓦葺，建築面積56㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"41 － 0007","desc":"敷地の東北部に位置し，銀行店舗として使用された三の蔵の背後に棟をそろえて建つ。切妻造，桟瓦葺，２階建の平入土蔵で，出入口に庇が付く。側面及び背面の外壁を縦板貼りとする簡素な造りになる。塩蔵ともよばれ，商家の構えを知る上で貴重な土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000715"},{"id":"00013011","register_sub_id":"101","register_pk":"368084","name":"草伝社（旧井手家住宅）倉庫","kana":"そうでんしゃ（きゅういでけじゅうたく） そうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県唐津市北波多徳須恵字前田1030-3他","lat":33.37580278,"lng":129.95135833,"geo_status":"db","era":"明治後期／昭和前期・平成21年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"41 － 112","desc":"店舗兼主屋北側に並んで建つ。木造二階建、切妻造桟瓦葺、外壁縦板張で、南面中央に戸口を設け、西妻を路地に面する。当初は二階を渡廊下で店舗兼主屋に接続し、一体の収納空間として利用した。唐津周辺の商家の伝統的な店構えを伝える附属建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013011"},{"id":"00013010","register_sub_id":"101","register_pk":"368083","name":"草伝社（旧井手家住宅）店舗兼主屋","kana":"そうでんしゃ（きゅういでけじゅうたく） てんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県唐津市北波多徳須恵字前田1030-3他","lat":33.37566667,"lng":129.95129167,"geo_status":"db","era":"明治後期／大正後期・昭和中期・平成24年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積241㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"41 － 111","desc":"市東部旧徳須恵宿のもと商家。店舗兼主屋は路地に西面して建つ切妻造桟瓦葺の二階建で、北に土間、南に二列四室を配して南列奥を客座敷とし、北の落棟に台所等、南の別棟に続き間の座敷を設ける。二階は一空間の倉庫とする。宿場町の景観を伝える大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013010"},{"id":"00000608","register_sub_id":"101","register_pk":"101598","name":"竹屋","kana":"たけや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県唐津市中町1884-2","lat":33.44856014,"lng":129.97036131,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造３階建，瓦葺，建築面積100㎡","structure_material":"木造３階建","registered":"1998.07.23(平成10.07.23)","register_no":"41 － 0004","desc":"唐津市の繁華街にある老舗の料理店竹屋の木造３階建の店舗。１階は調理場と家族の住居部であるが，２階は６畳代の客室が３室，３階は１０畳代の客室が２室が配される。いずれも吟味された材料を用い，階段廻りや客室の欄間，床棚など凝った造作になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000608"},{"id":"00013669","register_sub_id":"101","register_pk":"504613","name":"永井家住宅店舗兼主屋","kana":"ながいけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県唐津市呼子町呼子字坊山3085","lat":33.54025278,"lng":129.89503333,"geo_status":"db","era":"江戸後期／昭和前期増築、同中期・平成8年・同19年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積194㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"41 － 0113","desc":"呼子湾沿いの道に東面して建つ二階建、切妻造平入、桟瓦葺の町家。間口六間半で、正面に持送付の腕木庇を付し、二階外壁を漆喰塗とする。北を床上部、南を通り土間とし、通り土間西半の吹抜に貫を多用した小屋組を現す。港町呼子で江戸後期に遡る貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013669"},{"id":"00005681","register_sub_id":"101","register_pk":"106669","name":"中島酒造場主屋","kana":"なかしましゅぞうじょうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.092297,"lng":130.115097,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、瓦葺、建築面積513㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0065","desc":"旧長崎街道多良往還に北面して建つ。木造２階建の塗家造で，入母屋造，桟瓦葺，妻入の店舗を中心に，西側に玄関・２階建の離座敷・土蔵が，東側に東西棟の倉庫が，主棟土間の背後には釜場が接続する。店舗の２階正面は木格子窓とし，両脇に漆喰塗の戸袋がつく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005681"},{"id":"00001538","register_sub_id":"101","register_pk":"102528","name":"野中烏犀圓","kana":"のなかうさいえん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市材木1-82","lat":33.25341793,"lng":130.30979424,"geo_status":"db","era":"寛政8／昭和3増築","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"木造2階建、瓦葺、建築面積363㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"41 － 0014","desc":"野中烏犀圓は寛永３年創業と伝わる老舗薬問屋。冷善楼と呼ばれる座敷と店以外は増築部分。広く街路に面する漆喰壁，正面中央の大破風，看板を吊す屋形が江戸期の商家の風情を伝え，長崎街道周辺の歴史的景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001538"},{"id":"00004471","register_sub_id":"101","register_pk":"105461","name":"肥前浜宿継場主屋","kana":"ひぜんはましゅくつぎばしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2696","lat":33.09250271,"lng":130.11460976,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0048","desc":"旧長崎街道多良往還沿いに建つもと継立場。往還に南妻面を見せた間口４間半の妻入商家で，１階の表構えは揚戸の形式とし，２階は小庇付きの窓２箇所を開ける。内部は東側を土間に充て，西側にミセ，チャノマ，ザシキを一列に並べ，土間奥をカマヤとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004471"},{"id":"00010073","register_sub_id":"101","register_pk":"196220","name":"町家カフェぜん","kana":"まちやかふぇぜん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県唐津市坊主町552-5","lat":33.45139085,"lng":129.96464058,"geo_status":"db","era":"大正14／昭和10・平成24改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"41 － 0094","desc":"唐津城下の西方に位置し、通りに東面して建つ。もとは南半を質屋の店舗、北半を住宅として使用した。二階南半は質倉で、防火防犯に考慮して開口部を小さくし、外観もモルタル塗込めとして、銅板で建具や桁木口等を覆う。当時の質店の建築的特徴をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010073"},{"id":"00005669","register_sub_id":"101","register_pk":"106657","name":"矢野酒造主屋","kana":"やのしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11300079,"lng":130.0937829,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積284㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0053","desc":"旧長崎街道多良往還に東面して建つ，間口６間の木造２階建で，入母屋造，桟瓦葺の妻入とする。正面１階は瓦葺庇の南寄りに戸口を設け，北側を出窓とし，２階外壁は白漆喰塗である。内部は南側に通り土間，北側の表を土間の事務室とし，２列４室の居室を配す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005669"},{"id":"00007599","register_sub_id":"101","register_pk":"108581","name":"吉田家住宅主屋","kana":"よしだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市大字中村字本町103","lat":33.11614921,"lng":130.09521428,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積228㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"41 － 0071","desc":"多良海道に西面する木造２階建の町家。入母屋造桟瓦葺で、背面直角に入母屋造を出す。外壁を白漆喰仕上げの大壁とし、側面は腰に煉瓦を積む。内部は南側の通り土間、北側の居室からなり、座敷には黒檀ほかの銘木を使う。居蔵造の形態をよく伝える近代町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007599"},{"id":"00007600","register_sub_id":"101","register_pk":"108582","name":"吉田家住宅土蔵","kana":"よしだけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市大字中村字本町103","lat":33.11608673,"lng":130.09529475,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"41 － 0072","desc":"敷地の後方に東西棟で建つ。土蔵造２階建で、切妻造妻入桟瓦葺とする。外壁は漆喰仕上げ。内部は１階を広い１室とし、２階を３室に間仕切り、西に納戸を配し、中央の四畳から東端の十畳にかけて舟底天井を張り、室境に欄間を設ける。町家に残る座蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007600"},{"id":"00003484","register_sub_id":"101","register_pk":"104474","name":"青い理髪舘（旧小林理髪舘）","kana":"あおいりはつかん（きゅうこばやしりはつかん）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県島原市上の町888-2","lat":32.79155707,"lng":130.36813472,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0025","desc":"上の町北端で島原街道から西に折れる道路に北面して建つ。間口３間，寄棟造，桟瓦葺の木造，下見板張，２階建洋館。花頭窓風のアーチとキーストーンをあしらった玄関上部のペディメント風意匠は特異で，３連の造り付け鏡面台など理髪室内部の保存状況も良い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003484"},{"id":"00003490","register_sub_id":"101","register_pk":"104480","name":"猪原金物店主屋","kana":"いのはらかなものてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県島原市上の町912","lat":32.78889187,"lng":130.36939063,"geo_status":"db","era":"万延2及び明治後期","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0031","desc":"島原街道の西側に位置する。万延２年の棟札を持つ切妻造・平入の北側上手部分と，明治後期の切妻造・平入の南側下手部分とが一体となり，正面東面と南面に半間の下屋を廻す。商店街の入口近くに在り，上の町の「顔」的存在として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003490"},{"id":"00005382","register_sub_id":"101","register_pk":"106370","name":"今里酒造店舗及び住宅","kana":"いまざとしゅぞうてんぽおよびじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷596","lat":33.13629835,"lng":129.89660384,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積442㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0050","desc":"川棚川右岸沿いの敷地に位置し，上波佐見村往還に南面して建つ。東西棟，入母屋造，平入のつし２階建の背後に南北棟の切妻造を続け，南妻の一部を往還に見せる独特なつくり。ほぼ中央に南北に土間を通し豪壮な梁組を見せ，西方を事務所，東方を床上部とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005382"},{"id":"00002727","register_sub_id":"101","register_pk":"103717","name":"梅ヶ枝酒造主屋","kana":"うめがえしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.089905,"lng":129.814941,"geo_status":"db","era":"安政7","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積216㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0012","desc":"宮村川右岸，平戸往還近くに位置する敷地のほぼ中央に建つ。桁行１８ｍ，梁間８ｍ規模，東西棟，片入母屋造，桟瓦葺の主体部の南に４ｍ幅の下屋を架けて東寄りに玄関をとる。造り酒屋の住居兼事務所で，土間部を中心に試飲所や販売所としても活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002727"},{"id":"00003171","register_sub_id":"101","register_pk":"104161","name":"雲仙観光ホテル","kana":"うんぜんかんこうほてる","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県雲仙市小浜町雲仙湯ノ里320","lat":32.737297,"lng":130.26152,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造一部鉄筋コンクリート造地上3階地下1階建、瓦葺、建築面積1772㎡","structure_material":"木造一部鉄筋コンクリート造地上3階地下1階建","registered":"2003.01.31(平成15.01.31)","register_no":"42 － 0019","desc":"正面約６５ｍ規模，地下１階地上３階建で北面して建つ。外観はアルプス山小屋風を基調に，１階は溶岩石張，２階はログハウス風，３階はハーフティンバー風の構成とし，内部も木質感を活かした重厚で格調高いインテリア空間をつくる。竹中工務店の設計施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003171"},{"id":"00006628","register_sub_id":"101","register_pk":"107611","name":"小野原本店店舗兼主屋","kana":"おのはらほんてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県長崎市築町3-5","lat":32.74521056,"lng":129.87585749,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積84㎡、地下室付","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"42 － 0072","desc":"角地に建ち、東側通りに正面を向ける。入母屋造妻入桟瓦葺、隅切りのある桁行４間梁間４間半の２階建で、北に突出部を設ける。２階を黒漆喰壁とし、両開鉄扉を正・側面に計１０ヶ所開ける。１階に店舗、２階に座敷を設ける。重厚な意匠になる商家建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006628"},{"id":"00006629","register_sub_id":"101","register_pk":"107612","name":"小野原本店附属屋","kana":"おのはらほんてんふぞくや","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県長崎市築町3-5","lat":32.74530566,"lng":129.87593331,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"煉瓦造2階建、建築面積41㎡","structure_material":"煉瓦造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"42 － 0073","desc":"主屋の北側に正面壁面を合わせて建つ。煉瓦造２階建で、パラペットを立ちあげ、モルタル塗仕上げとする。当初は１階が食堂、２階が納戸で、主屋突出部を介して主屋と一連で使われた。黒漆喰仕上げの主屋と対照的な外観や構造をもち、独特の街路景観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006629"},{"id":"00016615","register_sub_id":"101","register_pk":"574977","name":"旧親和銀行本店懐霄館","kana":"きゅうしんわぎんこうほんてんかいしょうかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和後","pref":"長崎県","address":"長崎県佐世保市島瀬町80他","lat":33.17199389,"lng":129.72233583,"geo_status":"db","era":"昭和50年","year":1975,"year_source":"db","year_min":1975,"year_max":1975,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上11階地下2階建、建築面積789㎡、渡廊下付","structure_material":"鉄骨鉄筋コンクリート造地上11階地下2階建","registered":"2026.02.10(令和8.02.10)","register_no":"42 - 0148","desc":"本館背面に屹立する旧電算機棟。正面は花崗岩貼で中央の長大なスリットに向かい壁面が湾曲する独特の造形。巨大な吹抜や業務室に、展望室、噴水付サロン、ギャラリーなどの異質空間を巧みに配する。本館と一体で白井晟一の世界観を完成させた記念碑的作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016615"},{"id":"00016614","register_sub_id":"101","register_pk":"574976","name":"旧親和銀行本店本館","kana":"きゅうしんわぎんこうほんてんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和後","pref":"長崎県","address":"長崎県佐世保市島瀬町80他","lat":33.17199389,"lng":129.72233583,"geo_status":"db","era":"昭和42年／昭和44増築、平成16年・令和4年改修","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造地上6階地下1階建、建築面積1，792㎡","structure_material":"鉄筋コンクリート造一部鉄骨造地上6階地下1階建","registered":"2026.02.10(令和8.02.10)","register_no":"42 - 0147","desc":"佐世保駅から北西に延びる商店街に東面する銀行店舗。「原爆堂計画」の造形を原型とする北半部と、ブロンズパネル貼の弓形構造体を立上げた南半部からなる独創的外観。円筒内壁を巡る螺旋階段など彫塑的な造形が静謐な空間を創出。白井晟一の代表作の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016614"},{"id":"00011012","register_sub_id":"101","register_pk":"208982","name":"旧角屋主屋","kana":"きゅうすみやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県平戸市田助町字浦方68","lat":33.39034,"lng":129.55375,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積228㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"42-0124","desc":"田助湾に面する敷地に西面する。Ｌ字形平面の木造二階建、入母屋造桟瓦葺で下屋を廻らし、正面中央に入母屋玄関を構える。正面と海側の背面は広い開口にガラス戸をたてる。一階東寄りを土間とする他は上下階とも中廊下沿いに居室を配し、造作も洗練される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011012"},{"id":"00011224","register_sub_id":"101","register_pk":"205331","name":"旧升金商会事務所兼倉庫","kana":"きゅうますきんしょうかいじむしょけんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市湊新地町450-1","lat":32.774237,"lng":130.375582,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積133㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"42 - 0128","desc":"店舗兼主屋の街路を隔てた南側に立ち、背面側は海に面する。桁行八間弱、梁間四間半の蔵で、木造二階建、切妻造桟瓦葺。一尺五寸角の柱・梁材など、木太い材を用いる点が特徴で、高い大工技術によって組まれている。港町島原の繁栄の様相を物語る建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011224"},{"id":"00011223","register_sub_id":"101","register_pk":"205330","name":"旧升金商会店舗兼主屋","kana":"きゅうますきんしょうかいてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市湊新地町420","lat":32.774388,"lng":130.375378,"geo_status":"db","era":"明治15","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"42 - 0127","desc":"明治三年に島原藩によって開かれた湊新地の角地に建つ。南北棟の南寄り西側に東西棟を張り出す鉤手状の平面を持ち、隅部に大きくミセを配す。主屋主体部の上手表側に仏間を配する平面は、江戸末期から明治期にかけての島原に多く見られる形式。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011223"},{"id":"00007937","register_sub_id":"101","register_pk":"108917","name":"旧松本薬局店舗兼主屋","kana":"きゅうまつもとやっきょくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県壱岐市勝本町勝本浦字本浦158-3","lat":33.85065787,"lng":129.69411332,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積210㎡","structure_material":"木造2階一部平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"42-0087","desc":"通りに南面して建つ。東西敷地境に高い煉瓦塀を造り、建物側壁とし、店舗と座敷を庭を介して一体とする。正面は煉瓦塀をウダツ風に飾り、１階に出格子を構え、庇を腕木で持ち出す。２階はモルタル壁を石貼風に目地を切る。多様な要素が調和する町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007937"},{"id":"00013671","register_sub_id":"101","register_pk":"505030","name":"銀水","kana":"ぎんすい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県島原市白土桃山二丁目1093","lat":32.77885833,"lng":130.37472778,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積56㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"42 － 0137","desc":"島原城の南方、浜の川湧水の東に北面して建つ名物冷菓かんざらしの店舗。木造二階建、桟瓦葺、一階東半を土間とし、玄関正面の水溜に湧水を引いてミセとする。西半は床付の和室で仏壇を備え、二階は瀟洒な座敷二室を設ける。湧水の歴史的風致を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013671"},{"id":"00016616","register_sub_id":"101","register_pk":"574978","name":"ＳＥＥＤ１９３１（旧諫早銀行本店）","kana":"しーどいちきゅうさんいち（きゅういさはやぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県諫早市本町108-1","lat":32.84517472,"lng":130.05480694,"geo_status":"db","era":"昭和6年／令和6年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階建、塔屋付、建築面積308㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"42 - 0149","desc":"市街地中心部の本町通りの角地に建つ、旧銀行本店店舗。鉄筋コンクリート造2階建、ドリス式オーダーの列柱や軒飾による重厚な意匠で、内部は旧営業室を有し、吹抜の大空間にトスカナ式オーダーの円柱を立てる。古典様式の外観が街角景観をつくる銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016616"},{"id":"00003335","register_sub_id":"101","register_pk":"104325","name":"中尾山うつわ処赤井倉","kana":"なかおやまうつわどころあかいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県東彼杵郡波佐見町中尾郷929","lat":33.12261841,"lng":129.92900389,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積168㎡","structure_material":"木造平屋一部2階建","registered":"2003.03.18(平成15.03.18)","register_no":"42 － 0021","desc":"中尾郷を南北に流れる中尾川右岸沿い敷地にほぼ西面して建つ。桁行８間梁間２間半規模の入母屋造身舎部の西と南面に幅５尺の広縁を廻し，東面には梁行１間半の下屋を差出す。北をドマ，中央をミセ，南をザシキとした商家建築の好事例。棟梁は小玉政治。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003335"},{"id":"00003488","register_sub_id":"101","register_pk":"104478","name":"中野金物店主屋","kana":"なかのかなものてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県島原市上の町906","lat":32.78938473,"lng":130.36918449,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積63㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0029","desc":"島原街道の西側に位置し，東面して建つ。間口３間梁間５間規模，南北棟の切妻造，桟瓦葺，平入のたちの高い本２階建で，正面に１間の下屋を付ける。北側が切り縮められているが，つし２階建から本２階建町家への移行を示す指標的遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003488"},{"id":"00003489","register_sub_id":"101","register_pk":"104479","name":"中野金物店防火壁","kana":"なかのかなものてんぼうかへき","category":"産業3次","subcategory":"その他工作物","type_guess":"店舗","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県島原市上の町906","lat":32.78932798,"lng":130.36910499,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"煉瓦造、延長13m","structure_material":"煉瓦造","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0030","desc":"南側隣地との境界に建ち，主屋の南妻面を構成する。煉瓦造で，２枚厚の根積に１枚半厚の防火壁をイギリス積で建ちあげる。主屋２階部は袖卯建状とし，笠石部は煉瓦で小屋根を造り，南妻破風は３段の持出し積とするなど凝った造作が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003489"},{"id":"00003485","register_sub_id":"101","register_pk":"104475","name":"宮崎商店店舗","kana":"みやざきしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市上の町897","lat":32.79037414,"lng":130.36877659,"geo_status":"db","era":"明治39／昭和6増改造","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0026","desc":"島原街道の西側に位置し，南側に城に向う小路が通る角地に建つ。造り酒屋の店舗棟と座敷棟から成り，店舗棟は南北棟で，桁行４間半規模，切妻造，桟瓦葺の平入とし，北に東西棟，入母屋造のたちの高い座敷棟をＬ型に配する。店舗棟の棟梁は「荒木輝美雄」。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003485"},{"id":"00013471","register_sub_id":"101","register_pk":"368567","name":"旧岩﨑家住宅（塩屋）店舗兼主屋","kana":"きゅういわさきけじゅうたく（しおや）てんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県宇城市小川町小川字上苅萱79-1","lat":32.58510556,"lng":130.70732778,"geo_status":"db","era":"明治39年／昭和40年頃・平成12年・同30年改修","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積211㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"43 － 0180","desc":"旧薩摩街道小川宿に位置し、街道に北面して建つ。木造二階建、切妻造桟瓦葺平入、外壁は白漆喰塗で、妻面に水切瓦を三段廻らす。内部は東を土間、西を座敷とし、主座敷に床、棚、書院を備える。正面外観は改修しているが、建築年代が明らかで上質な町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013471"},{"id":"00009683","register_sub_id":"101","register_pk":"194679","name":"旧松倉家住宅主屋","kana":"きゅうまつくらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県菊池市隈府字城山1329-2","lat":32.98529372,"lng":130.81154373,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"43 － 0123","desc":"御所通りに面して建ち、木造二階建、入母屋造桟瓦葺で、通り側に大小の入母屋屋根を見せ、一階は出格子をたて、二階は窓を広く取り手摺を設ける。当初は料理屋として建てられたため、座敷飾や欄間などを瀟洒つくりとし、接客建築らしい意匠を随所に見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009683"},{"id":"00004479","register_sub_id":"101","register_pk":"105469","name":"旧三角海運倉庫（三角築港記念館）","kana":"きゅうみすみかいうんそうこ（みすみちくこうきねんかん）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県宇城市三角町三角浦1268-1","lat":32.62228,"lng":130.455505,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積168㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"43 － 0074","desc":"三角旧港東南の埠頭沿いに位置する旧海運倉庫。桁行２５ｍ梁間７ｍ規模の土蔵造２階建，平入で，埠頭側に下屋庇を２間張り出し，その他の３面には水切り瓦を付ける。築港当初に建てられた倉庫としては唯一の遺構で，現在レストランとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004479"},{"id":"00014985","register_sub_id":"101","register_pk":"519245","name":"商工クラブ店舗","kana":"しょうこうくらぶてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市中央区西阿弥陀寺町6","lat":32.79405833,"lng":130.69517778,"geo_status":"db","era":"明治23年／令和2年改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造2階建、瓦葺、建築面積266㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"43 - 0201","desc":"熊本城跡の南西の市街地に位置する料亭。通りに北面する２階建切妻造平入桟瓦葺の東西棟で、南東に角屋を延ばす。一階は出格子と平格子構えで東寄りに入母屋造玄関を付し、二階は連窓前面に手擦を廻らし窓上に庇を付す。近代の熊本城下の賑わいを伝える料亭。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014985"},{"id":"00005513","register_sub_id":"101","register_pk":"106501","name":"冨重写真所","kana":"とみしげしゃしんじょ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市新町2-8-5","lat":32.79747553,"lng":130.69943807,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積138㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"43 － 0078","desc":"西側接道の敷地の南東に西面して建つ。桁行７間，梁間３間規模で，東西棟，切妻造，桟瓦葺の木造２階建。外壁は下見板張とする。坪井川に面する東側には，１階に手摺付の縁を設け，庇を張り出す。スラントを用いた撮影室を残す，明治期の写真館の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005513"},{"id":"00000491","register_sub_id":"101","register_pk":"101481","name":"長崎次郎書店","kana":"ながさきじろうしょてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県熊本市新町4-1-19","lat":32.80030968,"lng":130.69671848,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建，瓦葺，建築面積175㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"43 － 0006","desc":"旧城下の商人町の中心近くに建つ。木造２階建で，外壁は煉瓦で固める。設計は保岡勝也。軒の出の小さい屋根，障壁風の壁の上部に設けた小屋根，軒廻りの装飾，２階の連続する変形のアーチ等に特徴がある。市内有数の古い書店として広く知られた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000491"},{"id":"00013470","register_sub_id":"101","register_pk":"368566","name":"西村家住宅主屋","kana":"にしむらけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市中央区西唐人町13","lat":32.79766389,"lng":130.6971,"geo_status":"db","era":"大正6年頃／平成5年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積146㎡、煉瓦造防火壁付","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"43 － 0179","desc":"店舗背面に続く、商家の主屋。木造二階建桟瓦葺で、店舗西側の路地が玄関へ続く。玄関の北に茶の間、西に水回り、東に座敷を配し、南の縁から仏間に接続する。黒檀や桜の面皮柱などの多様な材、工夫を凝らした明り窓など、賓客をもてなす設えを随所に見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013470"},{"id":"00013469","register_sub_id":"101","register_pk":"368565","name":"西村家住宅店舗","kana":"にしむらけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市中央区西唐人町10","lat":32.79748889,"lng":130.69702222,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積105㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"43 － 0178","desc":"熊本城下の西唐人町に位置し、通りに南面して建つ。土蔵造二階建、切妻造桟瓦葺平入で、正面半間、背面一間半の下屋を付し、外壁を黒漆喰塗とし、東妻面は煉瓦造防火壁と一体化する。一、二階とも一室で、小屋を現しとする。近代熊本の繁華街の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013469"},{"id":"00006503","register_sub_id":"101","register_pk":"107486","name":"浜田醤油店舗","kana":"はまだしょうゆてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.777149,"lng":130.635956,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0093","desc":"通り沿いに東面して建つ、桁行６間、梁間５間、切妻造桟瓦葺の平入木造２階建。外観を塗り込め、南半には深い下屋庇をつくり、開口を設け、北半は腰を海鼠壁とするなど意匠を違える。老舗に相応しい、重厚で風格ある表情をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006503"},{"id":"00006463","register_sub_id":"101","register_pk":"107446","name":"浜田醤油洋館","kana":"はまだしょうゆようかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.777031,"lng":130.63599242,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積8㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0095","desc":"敷地東南角に建ち、主屋に接続する。建築面積８㎡、木造２階建、桟瓦葺。もと煙草店として建てられ、現在は１階を倉庫、２階を居室とする。外壁はモルタル塗で、２階の腰から下を洗出し仕上げとする。妻壁は山型で板張の妻飾をつけて洋風意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006463"},{"id":"00000108","register_sub_id":"101","register_pk":"101098","name":"早野ビル","kana":"はやのびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市練兵町45","lat":32.79788395,"lng":130.7027671,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造3階建（一部4階建）、建築面積208㎡","structure_material":"鉄筋コンクリート造3階建（一部4階建）","registered":"1996.12.20(平成8.12.20)","register_no":"43 － 0001","desc":"ＲＣ造の事務所ビルで，設計は矢上信次である。熊本で最初の貸しビルであったと伝えており，２・３階を通した窓廻り，４階及び塔屋の窓廻り，外壁の柱型等に特徴的な装飾が施されている点に初期の事務所ビルの特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000108"},{"id":"00000808","register_sub_id":"101","register_pk":"101798","name":"ピーエス熊本センター（旧第一銀行熊本支店）","kana":"ぴーえすくまもとせんたー（きゅうだいいちぎんこうくまもとしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市中唐人町1","lat":32.7969975,"lng":130.69867187,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造地上２階地下１階建，建築面積332㎡","structure_material":"鉄筋コンクリート造地上２階地下１階建","registered":"1998.09.02(平成10.09.02)","register_no":"43 － 0013","desc":"西村好時の設計。全国の第一銀行の設計を手がけた西村の初期の作として知られる。連続するアーチ窓を用い，道路側の両端に塔屋を配し，石と煉瓦で仕上げた外観は美しく，地域のランドマークにもなっている。内部には１・２階吹き抜けの営業室をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000808"},{"id":"00003927","register_sub_id":"101","register_pk":"104917","name":"氷川町まちつくり酒屋（旧井芹家住宅）主屋","kana":"ひかわちょうまちつくりさかや（きゅういせりけじゅうたく）おもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県八代郡氷川町宮原栄久31-15","lat":32.55617379,"lng":130.68218257,"geo_status":"db","era":"天保3／明治6増築","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造2階建、瓦葺、建築面積281㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"43 － 0067","desc":"旧井芹銀行本店の北側に位置する。切妻造，平入で，街路に面する正面の２階は漆喰で塗り込めるが，背面は１，２階とも縁側を張り出した開放的な外観とする。大きな妻面に水切瓦と瓦葺庇付の開口部が穿たれる。大規模なつくりで地域のランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003927"},{"id":"00003928","register_sub_id":"101","register_pk":"104918","name":"氷川町まちつくり酒屋（旧井芹家住宅）土蔵","kana":"ひかわちょうまちつくりさかや（きゅういせりけじゅうたく）どぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県八代郡氷川町宮原栄久31-15","lat":32.55613644,"lng":130.68183425,"geo_status":"db","era":"明治5／平成12移築","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"43 － 0068","desc":"旧井芹銀行本店の背面に位置する旧米蔵。桁行４間，梁間２間の，切妻造，桟瓦葺，平入で，基礎に切石を敷いた２階建の土蔵。小屋組は和小屋で，平側全面には幅１間で角状の下屋柱を三本張り出す。醸造業を経営していた頃の屋敷の構成要素として貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003928"},{"id":"00003926","register_sub_id":"101","register_pk":"104916","name":"氷川町まちづくり情報銀行（旧井芹銀行本店）","kana":"ひかわちょうまちづくりじょうほうぎんこう（きゅういせりぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県八代郡氷川町宮原栄久35-1","lat":32.55598146,"lng":130.68209296,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積106㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"43 － 0066","desc":"町の中心地で，町役場に近接して建つ銀行建築。左右対称の外観を呈する鉄筋コンクリート造２階建で，正面に特異な意匠の柱頭付の付柱を四本設け，パラペット中央部に幾何学的模様を施すなど，全体をセセッション風の意匠でまとめる。施工は地元の増永組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003926"},{"id":"00009561","register_sub_id":"101","register_pk":"194354","name":"人吉旅館玄関棟","kana":"ひとよしりょかんげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県人吉市上青井町154-1","lat":32.21209548,"lng":130.75417863,"geo_status":"db","era":"昭和8年／昭和12年・昭和14年増築・昭和63年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積407㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0114","desc":"敷地北西に建つ。木造二階建、建築面積四〇七平方メートル、入母屋造桟瓦葺で、正面に入母屋造の玄関を構える。下階に玄関ホールや応接間、上階に大ホールや客室を配し、上下階とも東面の中庭側にガラス戸を建てて開放的につくる。風情ある和風旅館の玄関棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009561"},{"id":"00009563","register_sub_id":"101","register_pk":"194356","name":"人吉旅館中央棟","kana":"ひとよしりょかんちゅうおうとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県人吉市上青井町154-1","lat":32.21198698,"lng":130.75431141,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積234㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0116","desc":"敷地の南辺中央、東棟と西棟の間に建つ。木造二階建、建築面積二三四平方メートル、入母屋造桟瓦葺である。上下階とも四室を一列に並べ、各々違棚や組子欄間の意匠を違える。北面に廊下を通し、各室の南に縁を配して球磨川を望む。河岸景観に趣を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009563"},{"id":"00009564","register_sub_id":"101","register_pk":"194357","name":"人吉旅館西棟","kana":"ひとよしりょかんにしとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"熊本県","address":"熊本県人吉市上青井町154-1","lat":32.21194986,"lng":130.7542286,"geo_status":"db","era":"昭和28年／昭和57年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積139㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0117","desc":"玄関棟と中央棟の接点に建つ客室棟。木造二階建、建築面積一三九平方メートル、切妻造桟瓦葺。上下階とも球磨川に面して三室ずつを並べる。摺ガラスの回転窓や矢岳の透彫欄間を建てるほか、竹や自然木を用いて数寄屋風を加味するなど細部に趣向を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009564"},{"id":"00009562","register_sub_id":"101","register_pk":"194355","name":"人吉旅館東棟","kana":"ひとよしりょかんひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県人吉市上青井町154-1","lat":32.2120398,"lng":130.75441991,"geo_status":"db","era":"昭和5年頃／昭和40年・昭和52年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0115","desc":"敷地南東に建ち、木造二階建、建築面積九四平方メートル、入母屋造桟瓦葺である。室内は、下階に客室富士・扇の二室、上階に清流の間を配する。トコに扇形の墨跡窓を開け、随所に銘木を用いて、各室とも瀟洒な意匠とする。創業頃の敷地の様相を伝える客室棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009562"},{"id":"00002864","register_sub_id":"101","register_pk":"103854","name":"山鹿灯籠民芸館（旧安田銀行山鹿支店）","kana":"やまがとうろうみんげいかん（きゅうやすだぎんこうやまがしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県山鹿市大字山鹿1606-2","lat":33.01514407,"lng":130.68842465,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積185㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"43 － 0049","desc":"山鹿市街中心部に建つ銀行社屋。ＲＣ造２階建で，内部はその大部分を営業室とし，西側に事務室等を設ける。外観はイオニア式風のオーダーを用いて様式主義でまとめるが，角形のスクロールや，玄関上部のパラペット装飾など細部に特色が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002864"},{"id":"00009567","register_sub_id":"101","register_pk":"194360","name":"芳野旅館居間棟","kana":"よしのりょかんいまとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県人吉市上青井町184-1他","lat":32.21422986,"lng":130.756323,"geo_status":"db","era":"明治21年／昭和46年改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0120","desc":"別広間棟の西側に接続する。木造平屋建、建築面積一一〇平方メートル、入母屋造及び切妻造桟瓦葺である。内部は居間四室と仏間などにより構成される。創業者の住居を存置し利用している、敷地内最古の建物で、住宅から温泉旅館へと変遷した経緯を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009567"},{"id":"00009568","register_sub_id":"101","register_pk":"194361","name":"芳野旅館従業員棟","kana":"よしのりょかんじゅうぎょういんとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県人吉市上青井町184-1他","lat":32.21439404,"lng":130.75623306,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0121","desc":"本館西側に建ち、木造二階建、建築面積一七一平方メートル、入母屋造桟瓦葺である。銭湯として建てられたのち料亭を経て従業員室や倉庫となる。室ごとに異なる意匠の下地窓を穿ち、二階張出し部に色ガラスを配した窓を建てるなど、洗練された雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009568"},{"id":"00009566","register_sub_id":"101","register_pk":"194359","name":"芳野旅館別広間棟","kana":"よしのりょかんべつひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県人吉市上青井町184-1他","lat":32.21422986,"lng":130.75651288,"geo_status":"db","era":"大正2年／昭和中期・昭和46年増築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積290㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0119","desc":"本館南側に接続し、木造二階建、入母屋造桟瓦葺である。下階は、廊下の北側に別広間、南側に厨房や休憩室などを配し、上階は客室とする。廊下を竹垂木の舟底天井とし、客室には目の細かい網代天井を張るなど、竹や自然木を巧みに用いて趣ある座敷空間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009566"},{"id":"00009565","register_sub_id":"101","register_pk":"194358","name":"芳野旅館本館","kana":"よしのりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県人吉市上青井町184-1他","lat":32.21448399,"lng":130.75650051,"geo_status":"db","era":"昭和6年／昭和11年増築・昭和50年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積454㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0118","desc":"山田川西岸の敷地北寄りに建つ。木造二階建、建築面積四五四平方メートル、入母屋造桟瓦葺で、北面に入母屋造の玄関を構える。下階を玄関ホールと客室、上階に大広間を配する。内部造作に、舟運に因む舟板や水車の古材を転用するなど風情あるつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009565"},{"id":"00007703","register_sub_id":"101","register_pk":"108685","name":"旅館金波楼大広間棟","kana":"りょかんきんぱろうおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県八代市日奈久上西町字西町又361他","lat":32.43261783,"lng":130.57389496,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積356㎡、煙突付","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"43 － 0106","desc":"本館に接続して南北棟で建ち、北西隅には高さ１５ｍの煉瓦造の煙突を付ける。大規模な木造２階建で、入母屋造桟瓦葺とし、東から南にかけて下屋庇をまわす。２階の八十畳の大広間は網代組の舟底天井で、トコや違棚、琵琶トコには自然木の銘木を大胆にあしらう。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007703"},{"id":"00007704","register_sub_id":"101","register_pk":"108686","name":"旅館金波楼正門及び塀","kana":"りょかんきんぱろうせいもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県八代市日奈久上西町字西町又361他","lat":32.43301853,"lng":130.57402849,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口2.3m、左右袖塀付、塀 木造、瓦葺、総延長26m","structure_material":"門 木造","registered":"2009.04.28(平成21.04.28)","register_no":"43 － 0107","desc":"通りに面して建つ一間腕木門。切妻造桟瓦葺で、緩い起りを付ける。間口２．３ｍで、両開板戸をたて、上部に筬欄間を飾る。西袖塀に潜りを設け、東袖塀から通りに沿って塀が続く。腰を大和張とし、上部は開口を穿つ土壁とする。温泉町の伝統的な街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007704"},{"id":"00007702","register_sub_id":"101","register_pk":"108684","name":"旅館金波楼本館","kana":"りょかんきんぱろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県八代市日奈久上西町字西町又361他","lat":32.43284038,"lng":130.57392893,"geo_status":"db","era":"明治42／大正3増築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造3階建、瓦葺、建築面積568㎡","structure_material":"木造3階建","registered":"2009.04.28(平成21.04.28)","register_no":"43 － 0105","desc":"日奈久温泉に所在する大規模な木造３階建旅館。北側の通りに対して建つ凹型の建物とその北東角に付くＬ字型の棟からなる。屋根は寄棟や切妻を複雑に組み合わせる。通り側は各階に庇を付け、大きく開口を設け、ガラス戸をたて、開放的な外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007702"},{"id":"00014440","register_sub_id":"101","register_pk":"511429","name":"若城金物店蔵","kana":"わかきかなものてんくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"熊本県","address":"熊本県宇城市小川町小川字上苅萱90","lat":32.58505278,"lng":130.70611389,"geo_status":"db","era":"元治元年（1864)","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積89㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"43 - 0196","desc":"薩摩街道沿いの商家の敷地東辺に建つ長大な米蔵。土蔵造二階建、切妻造桟瓦葺、南北妻側に下屋を設け、東面北隅に庇を掛けて引戸を建てる。内部は土間で上部吹抜とするが、元は各階板敷。一階は窓を設けず、木材を打ち付けて壁を保護し、米収納の様子を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014440"},{"id":"00014438","register_sub_id":"101","register_pk":"511427","name":"若城金物店厨房","kana":"わかきかなものてんちゅうぼう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"江戸","pref":"熊本県","address":"熊本県宇城市小川町小川字上苅萱90","lat":32.58516389,"lng":130.70625,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"43 - 0194","desc":"薩摩街道沿いの商家の台所棟で、店舗の背面側に中庭をはさんで建つ。二階建真壁造で南西に便所棟を付属し、切妻造目板瓦葺とする。一階は石貼り土間で東に煉瓦竈、西に井戸と流しを配す。二階は東半を吹抜、西半を板敷とする。往時の生活空間を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014438"},{"id":"00014437","register_sub_id":"101","register_pk":"511426","name":"若城金物店店舗兼主屋","kana":"わかきかなものてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県宇城市小川町小川字上苅萱90","lat":32.58531667,"lng":130.70616667,"geo_status":"db","era":"江戸末期／天保１３年(１８４２)増築・昭和42年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、瓦葺、建築面積280㎡","structure_material":"木造2階一部平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"43 - 0193","desc":"薩摩街道に北面する商家。二階建、切妻造平入の東西棟店舗兼主屋に、切妻造妻入の南北棟倉庫が接続した大型町家。背面南西に角屋の続き間座敷を設けて庭に面して縁を廻す。間口長大で土間に太い梁を見せ、外壁は軒裏まで漆喰で塗り込めた重厚な構えの町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014437"},{"id":"00014439","register_sub_id":"101","register_pk":"511428","name":"若城金物店納屋","kana":"わかきかなものてんなや","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"熊本県","address":"熊本県宇城市小川町小川字上苅萱90","lat":32.58510556,"lng":130.70626389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、瓦葺、建築面積69㎡","structure_material":"木造2階一部平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"43 - 0195","desc":"薩摩街道沿いの商家の納屋。台所棟南に接続する切妻造目板瓦葺の南北棟で、西及び南面に庇を付す。北半を平屋建の味噌倉、南半を二階建とし、一階を開放的な物置、二階を居室とする。格子や突上窓を用いる伝統的な造りで、広大な屋敷構えの東辺を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014439"},{"id":"00005069","register_sub_id":"101","register_pk":"106059","name":"麻生家住宅主屋","kana":"あそうけじゅたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県豊後大野市三重町市場1090","lat":32.9768251,"lng":131.58088296,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積141㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0114","desc":"敷地西端に商店街の道路に西面して南北棟で建つ。桁行７間，梁間５間の規模で，入母屋造，桟瓦葺，木造２階建で，正面に下屋半間を出す。側面及び２階を大壁とし二階軒裏を漆喰で塗り込め，塗屋造とする。醤油醸造関連施設として造られ，往時の繁栄を偲ばせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005069"},{"id":"00003180","register_sub_id":"101","register_pk":"104170","name":"岩尾家住宅（旧日本丸製薬所）主屋","kana":"いわおけじゅうたく（きゅうにほんがんせいやくしょ）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市豆田町4-15","lat":33.32744206,"lng":130.93742655,"geo_status":"db","era":"大正後期／昭和初期増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造3階建、瓦葺、建築面積171㎡","structure_material":"木造3階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0091","desc":"伝統的な町並みが残る豆田上町の中央にある薬局。主屋は大正後期に建てられた２階建，塗籠の町家で，昭和初期に３階の望楼が増築された。正面１階右端には唐破風の屋根を飾り，２階には銘木を多用した大広間を造る。豆田の天守閣として市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003180"},{"id":"00003182","register_sub_id":"101","register_pk":"104172","name":"岩尾家住宅（旧日本丸製薬所）土蔵","kana":"いわおけじゅうたく（きゅうにほんがんせいやくしょ）どぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県日田市豆田町4-15","lat":33.32753171,"lng":130.93744386,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造3階建、瓦葺、建築面積62㎡","structure_material":"土蔵造3階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0093","desc":"主屋北側に接してあり，道路側に妻を見せる３階建，切妻造，桟瓦葺の袖蔵。本来の用途である倉庫であるとともに，吹き抜けを持つ台所や座敷として主屋と一体となって使われる。主屋とともに豆田の町並み景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003182"},{"id":"00007438","register_sub_id":"101","register_pk":"108420","name":"宇野家住宅主屋（旧高瀬入早商店店舗兼主屋）","kana":"うのけじゅうたくしゅおく（きゅうたかせいりはやしょうてんてんぽけんしゅおく）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県日田市大字高瀬字徳行720-3","lat":33.305447,"lng":130.93959,"geo_status":"db","era":"昭和2／昭和57・平成19改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積147㎡","structure_material":"木造2階一部平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0164","desc":"三隈川南岸を並行に走る通りに北面する。入母屋造妻入桟瓦葺の木造２階建で、東面南寄りに切妻造平屋建の角屋を付ける。妻を漆喰仕上げとし、庇を３段の段差を付けたモルタル塗とする。２階は正面寄り三方を高欄付の縁として開放的に扱い、軽快な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007438"},{"id":"00000110","register_sub_id":"101","register_pk":"101100","name":"大分銀行赤レンガ館（旧二十三銀行本店・旧府内会館）","kana":"おおいたぎんこうあかれんがかん（きゅうにじゅうさんぎんこうほんてん・きゅうふないかいかん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県大分市府内町2-2-1","lat":33.23713952,"lng":131.60770466,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄筋コンクリート造2階建、スレート及び瓦棒葺、建築面積775㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"44 － 0001","desc":"クラシックとゴシックの中間的なクイーンアン様式をもとに，ドームを載せる構成が特徴的。設計は多くの名作を残した辰野・片岡建築事務所である。昭和20年の戦災で内部は焼失したが，外壁を保存する形で修復され，平成５年に再度内部が改修された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000110"},{"id":"00006304","register_sub_id":"101","register_pk":"107287","name":"梶原家住宅主屋","kana":"かじわらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県速見郡日出町大字豊岡字本町988-1他","lat":33.359943,"lng":131.49766332,"geo_status":"db","era":"明治40頃／大正7頃増築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積135㎡","structure_material":"木造2階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"44 － 0131","desc":"西側道路に面して建つ。妻入の町家で，桁行７間，梁間４間，木造２階建，入母屋造，桟瓦葺とする。広い玄関を構え，奥に書院，床の間付の客間をもつ。玄関正面に人見梁，持送りを付け，玄関脇は出格子とする。外壁及び妻面を漆喰塗とし，重厚な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006304"},{"id":"00006305","register_sub_id":"101","register_pk":"107288","name":"梶原家住宅土蔵","kana":"かじわらけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県速見郡日出町大字豊岡字本町988-1他","lat":33.35984146,"lng":131.4977885,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"44 － 0132","desc":"主屋の東側に建つ。桁行４間半，梁間３間半規模で，木造平屋建，入母屋造，桟瓦葺とする。西側を廊下とし東側に８畳間２室の続き間座敷をとり，南端に床の間を付ける。北西隅を便所とし，敷地北側の廊下で主屋と繋がる。丁寧な造作で，落ち着いた外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006305"},{"id":"00008222","register_sub_id":"101","register_pk":"132747","name":"旧大分合同銀行社屋","kana":"きゅうおおいたごうどうぎんこうしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後高田市中央通字横町691他","lat":33.55914657,"lng":131.44071891,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積153㎡","structure_material":"木造平屋一部2階建","registered":"2010.04.28(平成22.04.28)","register_no":"44 － 0175","desc":"市中心部の通り沿いに東面して建つ。正面８．５ｍ、平入の土蔵造平屋建と、背面に接続する入母屋造、木造２階建からなる。正面は白漆喰仕上げで、腰石貼とする。伝統意匠を基調としつつ、出桁の持送りなどに洋風意匠を取り入れ、近代的な街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008222"},{"id":"00007813","register_sub_id":"101","register_pk":"108794","name":"旧共同野村銀行社屋","kana":"きゅうきょうどうのむらぎんこうしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後高田市新町字新町963-1","lat":33.5588644,"lng":131.43970858,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造一部鉄筋コンクリート造平屋建、瓦葺、建築面積160㎡","structure_material":"木造一部鉄筋コンクリート造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"44-0165","desc":"通りに北面する木造の旧銀行建築で、背面にコンクリート造金庫室を付ける。正面は腰を石貼とし、タイル貼の柱型をあらわし、モルタル仕上げのパラペットを立ち上げる。正側面に縦型窓を等間隔に配し、玄関上部に装飾柱を飾る。昭和面影を残す町並みの中核施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007813"},{"id":"00009097","register_sub_id":"101","register_pk":"162457","name":"旧竹屋書店店舗兼主屋","kana":"きゅうたけやしょてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町字本町386","lat":32.96716547,"lng":131.39277101,"geo_status":"db","era":"明治32年／昭和40年頃改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、瓦葺、建築面積184㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0196","desc":"角地に建つ商家建築。間口１１ｍ奥行１３ｍの木造二階建。切妻造桟瓦葺で西正面に下屋を付ける。正面など一階はガラス戸をたて込み開放的に扱い、他は漆喰仕上げの大壁とする。正面には瓦庇を付ける連続窓を二箇所開け、特徴的な表構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009097"},{"id":"00009098","register_sub_id":"101","register_pk":"162458","name":"旧竹屋書店土蔵","kana":"きゅうたけやしょてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町字本町386","lat":32.96710812,"lng":131.39285704,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積19㎡","structure_material":"土蔵造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0197","desc":"主屋の背面南寄りから東に延びる上便所の東に接して建つ。南北棟の切妻造桟瓦葺。桁行５．２ｍ梁間３．７ｍの土蔵造平屋建。漆喰仕上げで、鉢巻をまわし、北妻面に出入口を穿つ。内部は中塗仕上げ。屋敷地内に残る小規模土蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009098"},{"id":"00003183","register_sub_id":"101","register_pk":"104173","name":"隈まちづくりセンター黎明館","kana":"くままちづくりせんたーれいめいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県日田市隈2-2-1","lat":33.31355013,"lng":130.93162679,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0094","desc":"大分銀行日田支店として建設。木造２階建，寄棟造，桟瓦葺で，外壁に煉瓦タイルを張り，セセッション風に仕上げる。清水組の設計施工で，設計担当は小笹徳蔵。隈町２丁目の角地にあり，昭和１８年から近年までは浜田医院として長く市民に親しまれてきた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003183"},{"id":"00007431","register_sub_id":"101","register_pk":"108413","name":"後藤家住宅隠居座敷","kana":"ごとうけじゅうたくいんきょざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県日田市隈2-80他","lat":33.315361,"lng":130.929901,"geo_status":"db","era":"明治後期／昭和4・昭和52改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0157","desc":"主屋の後方、庄手川沿いに位置し、主屋と渡廊下で繋がる。桁行１２ｍ梁間６．０ｍ規模の木造平屋建、南北棟の切妻造桟瓦葺とする。川側の石垣は南側を川石練積、北側を布積とする。八畳２室の続き座敷で、東・北・西三方に榑縁を張り、北端に川への石段を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007431"},{"id":"00007432","register_sub_id":"101","register_pk":"108414","name":"後藤家住宅座敷蔵","kana":"ごとうけじゅうたくざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県日田市隈2-80他","lat":33.315441,"lng":130.929901,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積51㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0158","desc":"隠居座敷の北面に接して建つ木造２階建。桁行８．７ｍ梁間６．５ｍ規模、東西棟の入母屋造桟瓦葺。川石を練積とする石垣上に建ち、１階は大壁造の土蔵、２階は真壁造の座敷とし、川側に縁を張る。棟の高い入母屋破風が川に臨み、河岸の景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007432"},{"id":"00007430","register_sub_id":"101","register_pk":"108412","name":"後藤家住宅主屋","kana":"ごとうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県日田市隈2-80他","lat":33.315414,"lng":130.930084,"geo_status":"db","era":"明治20／大正期改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積270㎡","structure_material":"木造2階一部平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0156","desc":"通りに東面して建つ。木造２階建の入母屋造妻入桟瓦葺で、南面に角屋を表と奥に出し、その間に坪庭を設ける。漆喰仕上げの大壁造とし、腰を海鼠壁とする。北側に土間、南にミセや居室、角屋に座敷飾りを構える座敷を配する。明治期における上質な町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007430"},{"id":"00007433","register_sub_id":"101","register_pk":"108415","name":"後藤家住宅東土蔵及び西土蔵","kana":"ごとうけじゅうたくひがしどぞうおよびにしどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市隈2-192","lat":33.31552828,"lng":130.92992393,"geo_status":"db","era":"大正6／平成元移築改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積121㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0159","desc":"座敷蔵の北側、川沿いに南北棟の西土蔵、その東に東西棟の東土蔵が位置する。いずれも切妻造桟瓦葺の土蔵造２階建。外壁は漆喰仕上げで、腰石貼とし、窓には瓦庇を付ける。西土蔵は川側が、座敷蔵から連続する練積の石垣上に建つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007433"},{"id":"00000717","register_sub_id":"101","register_pk":"101707","name":"斉藤家住宅","kana":"さいとうけじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県臼杵市大字福良字屋敷余り212","lat":33.11613488,"lng":131.79401301,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造２階建，瓦葺，建築面積132㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"44 － 0040","desc":"臼杵の町の西の玄関口にあたる福良地区に建つ切妻造，２階建の町家で，１階軒廻りに小庇が付く。北側は宮の参道に面し，水切りの小庇を２段に付け意匠とした妻側及び背後に連なる高塀付きの付属屋を見せる。近年の修理工事で，弁柄塗りの表構えに再生された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000717"},{"id":"00009100","register_sub_id":"101","register_pk":"162460","name":"塩屋旧大蔵","kana":"しおやきゅうおおくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県竹田市大字竹田町字本町509","lat":32.96797322,"lng":131.39199453,"geo_status":"db","era":"江戸末期／昭和33年頃・平成23年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積118㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0199","desc":"路地の西側に建つ。桁行が東西で少し異なる台形平面になる木造二階建で、建築面積１１８㎡。切妻造桟瓦葺で、壁は大壁とし、漆喰で仕上げる。内部北半部を東西に分け、男女の浴場とする。内外に変遷を留め、竹田の町並みに彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009100"},{"id":"00003772","register_sub_id":"101","register_pk":"104762","name":"塩屋主屋","kana":"しおやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県竹田市大字竹田町字本町503","lat":32.96815208,"lng":131.39229357,"geo_status":"db","era":"元治2","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建、瓦葺、建築面積93㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"44 － 0098","desc":"正面入母屋造，背面切妻造，２階建・妻入，桟瓦葺で，正面は街路に沿って壁面が斜めになり，１階の下屋庇は側面にも廻り込む。要所に水切庇付の小窓を配り，軒裏まで漆喰塗とした重厚なつくりとする。棟札から建築年代が明確で，当地域の商家建築の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003772"},{"id":"00009099","register_sub_id":"101","register_pk":"162459","name":"竹田市公民館竹田分館（旧一味楼）","kana":"たけたしこうみんかんたけたぶんかん（きゅういちみろう）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県竹田市大字竹田1918-1他","lat":32.9689036,"lng":131.39439083,"geo_status":"db","era":"大正2年頃／平成23年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積233㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0198","desc":"稲葉川西岸に位置する。南北棟の入母屋造桟瓦葺、木造二階建で、南寄りの西面に玄関、東面に倉庫を付設。建築面積２３３㎡。一階は南北に座敷が並び、二階はステージをもつ大広間とする。九間に及ぶ杉磨丸太や桐など良材を贅沢に使う料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009099"},{"id":"00003638","register_sub_id":"101","register_pk":"104628","name":"筑紫亭主屋","kana":"ちくしていしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市1692、1693、1694他","lat":33.60212141,"lng":131.18823531,"geo_status":"db","era":"大正3／大正11増築","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積413㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"44 － 0095","desc":"南北に細長い敷地北側にある。南と北に中庭を挟んで入母屋造，桟瓦葺，２階建の主体部が建ち，廊下で接続し，全体としては口ノ字型の平面になり，５２畳の大広間と２０畳の広間を２階に配している。良材を用い，造作にも凝った数寄屋風の意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003638"},{"id":"00003639","register_sub_id":"101","register_pk":"104629","name":"筑紫亭離れ","kana":"ちくしていはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県中津市大字島田835-15、835-91","lat":33.60190809,"lng":131.18842466,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋一部2階建、瓦葺、建築面積125㎡","structure_material":"木造平屋一部2階建","registered":"2003.09.19(平成15.09.19)","register_no":"44 － 0096","desc":"主屋の後方，敷地を東西に流れる水路の南側にあり，主屋の増築に続いて建設されたと考えられる。２階建１棟と平屋建２棟を，縁や廊下で巧みに結んだ構成になる。主屋同様に数寄を凝らし，客室は各々異なるつくりの床で飾り，垂木や手摺などに磨丸太を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003639"},{"id":"00003640","register_sub_id":"101","register_pk":"104630","name":"筑紫亭塀","kana":"ちくしていへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市1692、1693、1694","lat":33.60226848,"lng":131.18815986,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、延長17m","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"44 － 0097","desc":"敷地北辺を画す延長１７ｍ，高さ３．１５ｍの塀で，中央に庇付の門口を構え，西側に通用口を設ける。桟瓦葺の小屋根を架けた真壁造で，腰までを割竹で覆い，上部に下地窓を設ける。正面を飾るに相応しい瀟洒で風格のある構成で，街路景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003640"},{"id":"00012666","register_sub_id":"101","register_pk":"367960","name":"とまや店舗兼主屋","kana":"とまやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県杵築市大字杵築字新町385","lat":33.41885,"lng":131.622192,"geo_status":"geocoded","era":"明治8年頃／昭和62年移築","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、瓦葺、建築面積118㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"44 － 0231","desc":"杵築旧城下の街路に北面して建つ商家主屋。入母屋造妻入の二階建。正面は上下階に繰形付持送の出桁で深い軒をつくり、二階は軒先まで塗込める。一階正面にミセ、奥に８畳と６畳を並べ、二階に座敷を設ける。伝統的な町家の形式を示し、城下町の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012666"},{"id":"00002570","register_sub_id":"101","register_pk":"103560","name":"冨士屋旅館石垣","kana":"ふじやりょかんいしがき","category":"産業3次","subcategory":"その他工作物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県別府市大字鉄輪字ウカリユ735-1","lat":33.31688997,"lng":131.47812576,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"石造、折曲り延長71m","structure_material":"石造","registered":"2001.11.20(平成13.11.20)","register_no":"44 － 0072","desc":"敷地の東辺を限るジグザグ状折曲り延長７０ｍ程の石積擁壁で，間に石段１所を設ける。南端から石段の北３ｍ程までは亀甲積に近い丁寧な石積で，その北方は自然石の乱積とする。前門の前の石段とともにかってのアプローチ景観を今に伝えていて貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002570"},{"id":"00002569","register_sub_id":"101","register_pk":"103559","name":"冨士屋旅館石段","kana":"ふじやりょかんいしだん","category":"産業3次","subcategory":"その他工作物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県別府市大字鉄輪字ウカリユ735-1","lat":33.31681791,"lng":131.47810798,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"石造、13段、幅2.1m","structure_material":"石造","registered":"2001.11.20(平成13.11.20)","register_no":"44 － 0071","desc":"敷地東側の石畳道路から前門までの１４段の石段。石段幅は前門の間口に対応した２．１ｍで，踏石には幅４０ｃｍ，厚１５ｃｍ程度の板石，側石には１５ｃｍ角程度の長石を用い，石段北面は亀甲積に近い丁寧な石積面を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002569"},{"id":"00002567","register_sub_id":"101","register_pk":"103557","name":"冨士屋旅館主屋","kana":"ふじやりょかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県別府市大字鉄輪字ウカリユ735-1","lat":33.316875,"lng":131.477951,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造2階建、瓦葺、建築面積361㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"44 － 0069","desc":"別府八湯の中核をなす鉄輪温泉の老舗旅館。東面を正面とした南北棟，寄棟造，木造２階建本館部の南に棟を落とした東西棟，寄棟造の木造２階建が取付く。大正期に南部に入母屋造の玄関を増築するが，東面中央の入母屋造式台玄関跡が当旅館の格式を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002567"},{"id":"00002568","register_sub_id":"101","register_pk":"103558","name":"冨士屋旅館前門","kana":"ふじやりょかんまえもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県別府市大字鉄輪字ウカリユ735-1","lat":33.31683291,"lng":131.47809498,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造、間口2.1m","structure_material":"木造","registered":"2001.11.20(平成13.11.20)","register_no":"44 － 0070","desc":"主屋の旧式台玄関に向き合う位置に建つ。かっては，いでゆ坂から敷地東側の石畳を通り，石段を昇って門をくぐるアプローチをとった。間口１間幅の１間１戸，桟瓦葺の薬医門で，敷地東側の道路からは一段高い位置にあって格好のアイストップにもなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002568"},{"id":"00006468","register_sub_id":"101","register_pk":"107451","name":"別府タワー","kana":"べっぷたわー","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大分県","address":"大分県別府市北浜三丁目10-2","lat":33.281742,"lng":131.505936,"geo_status":"db","era":"昭和32／平成16改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄塔 鉄骨造、高さ73m、脚間15m、展望台付、下部構造 鉄骨鉄筋コンクリート造4階建、面積384㎡","structure_material":"鉄塔 鉄骨造","registered":"2007.10.02(平成19.10.02)","register_no":"44 － 0133","desc":"国道１０号に面して建つ。ＳＲＣ造４階建の建屋の上に高さ７４ｍの鉄塔を組み、総高９０ｍとする。塔身の断面は下から八角形、四角形、三角形と変化し、展望室のカーテンウォールには俯瞰を考慮し傾斜を付ける。別府のランドマークとして広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006468"},{"id":"00007437","register_sub_id":"101","register_pk":"108419","name":"山田家住宅石垣及び煉瓦塀","kana":"やまだけじゅうたくいしがきおよびれんがべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市隈1-214-1","lat":33.31175003,"lng":130.9323314,"geo_status":"db","era":"大正10・昭和28","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"石垣 石造、延長25m、石段付 塀 煉瓦造、延長26m","structure_material":"石垣 石造","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0163","desc":"三隈川沿いに築かれる。石垣は東西２５ｍで、中央で川側に突き出し、石垣に沿って石段を設ける。川石を練積とし、高さは３ｍ前後。煉瓦塀は高さ１ｍの長手積で、石段の降口部分に両開の鉄扉を吊る。明るい煉瓦塀が河川景観に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007437"},{"id":"00007436","register_sub_id":"101","register_pk":"108418","name":"山田家住宅井戸","kana":"やまだけじゅうたくいど","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県日田市隈1-214-1","lat":33.311867,"lng":130.932404,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"切石、面積1.8㎡、上屋付","structure_material":"切石","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0162","desc":"主屋後方、敷地のほぼ中央に位置する。切石を相欠に組む、方１．４ｍ高さ０．６ｍの井戸枠を中心に、西に沓石を置き、その周囲に東西２．８ｍ南北２．２ｍで、石敷の洗い場を設ける。石材は地元産の安山岩。上屋は井戸枠に柱を建て、腕木で切妻屋根を支える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007436"},{"id":"00007434","register_sub_id":"101","register_pk":"108416","name":"山田家住宅主屋","kana":"やまだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県日田市隈1-214-1","lat":33.31197,"lng":130.932465,"geo_status":"db","era":"文化13","year":1816,"year_source":"db","year_min":1816,"year_max":1816,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積210㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0160","desc":"通りに北面して建つ間口２２ｍに及ぶ大型の平入町家。切妻造瓦葺で、前後に深い下屋を付ける。漆喰仕上げの大壁造で、腰海鼠壁。当初は中央に通り土間、西に続き座敷、東に２列３室の居室を設けた。正面は下屋を本瓦葺とし、軒の低い重厚な構えにつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007434"},{"id":"00007435","register_sub_id":"101","register_pk":"108417","name":"山田家住宅土蔵","kana":"やまだけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市隈1-214-1","lat":33.311844,"lng":130.932343,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積67㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0162","desc":"敷地後方の三隈川近くに建つ。桁行１０ｍで、南半部が梁間６．２ｍ、北半部が５．２ｍ。屋根は段違い切妻造、南を桟瓦葺、北を本瓦葺とする。土蔵造２階建で、南半部の２階を居室とする。外壁は漆喰仕上げ、内壁は中塗仕上げ。災害の歴史を伝える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007435"},{"id":"00015398","register_sub_id":"101","register_pk":"532522","name":"旧黒木家住宅店舗兼主屋","kana":"きゅうくろぎけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県児湯郡高鍋町大字高鍋町598-4","lat":32.12478889,"lng":131.50817778,"geo_status":"db","era":"明治33年／大正前期・令和6年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積174㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"45 - 0115","desc":"高鍋城下の旧街道に東面して建つ、肥料製造販売業等を営んだ旧店舗兼主屋。桁行八間半の木造二階建寄棟造平入桟瓦葺で正背面に下屋を付ける。外壁は下見板張で、二階は縦長の上下窓を密に配した洋風の外観。町内最大級の間口の町家で当地の繁栄を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015398"},{"id":"00006273","register_sub_id":"101","register_pk":"107257","name":"旧後藤家商家交流資料館石塀","kana":"きゅうごとうけしょうかこうりゅうしりょうかんいしべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県都城市高城町高城2857","lat":31.80190067,"lng":131.13152078,"geo_status":"db","era":"明治33／平成13移設","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"石造、延長60m","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"45 － 0045","desc":"敷地の南辺，西辺，北辺及び東辺の一部を廻る石塀である。延長６０ｍで，基礎石の上に切石４段を積み，頂部に笠石を載せ，高さ１．７ｍ，厚さ０．３ｍとする。石の材質は凝灰岩で，地域内に多くみられ，地域的な特色をもった石塀のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006273"},{"id":"00006128","register_sub_id":"101","register_pk":"107112","name":"旧後藤家商家交流資料館本館","kana":"きゅうごとうけしょうかこうりゅうしりょうかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県都城市高城町高城2857","lat":31.80198063,"lng":131.131607,"geo_status":"db","era":"明治33／平成13曳家","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積231㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"45 － 0044","desc":"北側道路に面して建つ。桁行８間，梁間７間半の規模で，木造２階建，入母屋造，桟瓦葺とし，塗屋造とする。東側に通り土間をとり，周囲に半間幅の土間を廻す。２階の縁下には下屋を設け，重厚な屋根形式をつくる。意匠，材質ともに優秀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006128"},{"id":"00000920","register_sub_id":"101","register_pk":"101910","name":"杉村金物本店主屋","kana":"すぎむらかなものほんてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-6-12","lat":31.58377558,"lng":131.40321984,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造３階建，瓦葺，建築面積185㎡","structure_material":"木造３階建","registered":"1998.10.09(平成10.10.09)","register_no":"45 － 0003","desc":"油津の港に通じる道路に面した角地に建つ木造３階建の店舗兼用住宅。１階を店舗，２・３階を住居にあてる。縦長の窓や隅の石張り風の仕上げなど洋風の意匠を取り込み，外壁を銅板で覆った外観に特徴があり，町並でひときわ目立つ存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000920"},{"id":"00000921","register_sub_id":"101","register_pk":"101911","name":"杉村金物本店倉庫","kana":"すぎむらかなものほんてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県日南市油津1-6-12","lat":31.5837535,"lng":131.40311389,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造３階建，瓦葺，建築面積185㎡","structure_material":"煉瓦造３階建","registered":"1998.10.09(平成10.10.09)","register_no":"45 － 0004","desc":"主屋の西に隣接して建つ。煉瓦造３階建のせいの高い倉庫で，２階と３階の間は石材を帯状にまわして外観に変化をもたせている。主屋とともに町並でひときわ目立つ存在で，赤煉瓦で開口部の少ない外観の意匠は，銅板で覆った主屋と好対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000921"},{"id":"00005523","register_sub_id":"101","register_pk":"106511","name":"鈴木旅館北離れ","kana":"すずきりょかんきたはなれ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-2-7","lat":31.58419782,"lng":131.40257377,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階一部平屋建、瓦葺、建築面積63㎡","structure_material":"木造2階一部平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0032","desc":"西本館の北側に建ち，桁行４間，梁間３間の規模で，木造２階建，入母屋造，桟瓦葺とし，１，２階に客室をそれぞれ１室とする。北方に木造平屋建の小規模な客室棟が付属する。昭和初期の油津港の繁栄した頃に増築された離れで，当時の旅館の発展を知る上で貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005523"},{"id":"00005525","register_sub_id":"101","register_pk":"106513","name":"鈴木旅館土蔵","kana":"すずきりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-2-7","lat":31.58426654,"lng":131.40251038,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0034","desc":"敷地の北西隅に建ち，桁行６ｍ，梁間４ｍの規模で，土蔵造２階建，切妻造，桟瓦葺とする。外壁を白漆喰塗とし，鉢巻きを廻し，妻側に小さな窓を開く。南妻側に戸口を設け，一部煉瓦貼りとする。小規模ではあるが，昭和期の旅館の繁栄を物語る建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005525"},{"id":"00005522","register_sub_id":"101","register_pk":"106510","name":"鈴木旅館西本館","kana":"すずきりょかんにしほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-2-7","lat":31.58400214,"lng":131.40259375,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0031","desc":"南側道路に面して，本館の西側に建つ。桁行５間半，梁間５間半の規模で，木造２階建，寄棟造，桟瓦葺とする。１階は道路側に表玄関を構え，西半を調理場とし，２階に客間５室をとる。昭和初期に本館の西側に増築されたもので，旅館の発展を今日に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005522"},{"id":"00005524","register_sub_id":"101","register_pk":"106512","name":"鈴木旅館東離れ","kana":"すずきりょかんひがしはなれ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-2-6","lat":31.58406051,"lng":131.40277289,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0033","desc":"主屋の東側に近接して建ち，桁行４間半，梁間２間半の規模で，木造平屋建，入母屋造，桟瓦葺とする。座敷と洋間を続け，浴室を付ける。妻壁を漆喰塗りとし，堅牢なつくりで，旅館繁栄の時期に建てられ，小規模ではあるが独立した離れの旅館形式を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005524"},{"id":"00005521","register_sub_id":"101","register_pk":"106509","name":"鈴木旅館本館","kana":"すずきりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市油津1-2-7","lat":31.58408165,"lng":131.40268189,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0030","desc":"南側道路からやや後退して建ち，南北８間，東西６間の規模で，入母屋造東西棟の２棟を南北棟の両下造でつなぐ。木造２階建，桟瓦葺とする。１階前方に内玄関，浴室を置き，奥を大広間とし，２階に客室５室を置く。油津の明治期からの老舗旅館として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005521"},{"id":"00009866","register_sub_id":"101","register_pk":"195695","name":"奈良家住宅主屋","kana":"ならけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県宮崎市旭1-106","lat":31.91008891,"lng":131.42517298,"geo_status":"db","era":"昭和初期／昭和39移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"45 － 0077","desc":"県庁前の通りに北面し、木造二階建、入母屋造妻入、桟瓦葺で、正面に庇を付す。一階北寄りの店舗は、正面に格子付の出窓を設け、ガラス戸をたて、内部に格天井を張る。一階後方と二階には丁寧な造作の和室を配する。中心市街地の近代化を伝える店舗兼用住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009866"},{"id":"00009867","register_sub_id":"101","register_pk":"195696","name":"奈良家住宅別棟","kana":"ならけじゅうたくべっとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮崎県","address":"宮崎県宮崎市旭一丁目106","lat":31.9100675,"lng":131.42539427,"geo_status":"db","era":"昭和10頃／昭和39移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"45 － 0078","desc":"主屋の東隣に建つ。木造二階建、入母屋造桟瓦葺で、北西に玄関を張出し、下階に下屋、上階に窓庇を廻らす。一階南寄りに和室二室を並べて縁を廻らし、二階は和室五室を配する。各所の欄間に菊花や扇面、格狭間意匠をあしらうなど、室内造作も洗練されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009867"},{"id":"00005526","register_sub_id":"101","register_pk":"106514","name":"満尾書店","kana":"みつおしょてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-9","lat":31.58342506,"lng":131.40330058,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階一部3階建、瓦葺、建築面積169㎡、地下室付","structure_material":"木造2階一部3階建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0035","desc":"南東の角地に建ち，桁行７間，梁間６間の規模で，木造２階一部３階建，寄棟造，桟瓦葺とし，小屋組をトラス構造とする。南東隅と東側を店とし，外壁をモルタル塗人造石洗い出しとし，２階に縦長の窓及び柱形を等間隔に並べ，洋風意匠とした商店建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005526"},{"id":"00004872","register_sub_id":"101","register_pk":"105862","name":"池田家住宅石倉","kana":"いけだけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県霧島市横川町中ノ小字上岸田11-1","lat":31.90708485,"lng":130.70146992,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木骨石造2階建、瓦葺、建築面積46㎡","structure_material":"木骨石造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"46 － 0018","desc":"主屋の北方に位置し，東西棟で東妻面を通りに見せて建つ。桁行５間梁間２間半，切妻造，桟瓦葺の２階建で，床組や小屋組を石造外周壁の内側に沿わせた木柱で支持する木骨石造の倉庫。平入で南面に戸口を設け，外部の腰は石積を露わにし，上部は漆喰塗とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004872"},{"id":"00004871","register_sub_id":"101","register_pk":"105861","name":"池田家住宅主屋","kana":"いけだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県霧島市横川町中ノ小字上岸田11-1","lat":31.90699122,"lng":130.70150886,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積87㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"46 － 0017","desc":"桁行６間半梁行６間半規模，入母屋造，桟瓦葺の木造２階建で，通りに東面して建つ。１階は表側から北側にかけて土間を設け，南側に座敷を配した伝統的町家のつくりになるが，２階はたちの高い下見板張に上げ下げ窓を並べた洋風のつくりで際立った存在になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004871"},{"id":"00016758","register_sub_id":"101","register_pk":"579242","name":"小牧醸造石蔵","kana":"こまきじょうぞういしぐら","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県薩摩郡さつま町時吉字穴川口12-1他","lat":31.912787,"lng":130.461544,"geo_status":"db","era":"大正7年頃／平成9年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造平屋建、セメント瓦葺、建築面積125㎡","structure_material":"石造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"46 - 0130","desc":"川内川と穴川の合流地に位置する焼酎の造酒屋の石蔵。大正の火災後の再建と伝え、溶結凝灰岩の組積造とし耐火性を高める。小屋は木造キングポスト・トラスを組み、切妻造の屋根を架ける。当地域の近代期に特有の石蔵で、川内川河畔の歴史的な景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016758"},{"id":"00016759","register_sub_id":"101","register_pk":"579243","name":"小牧醸造煉瓦造煙突","kana":"こまきじょうぞうれんがづくりえんとつ","category":"産業3次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県薩摩郡さつま町時吉字穴川口12-8","lat":31.912702,"lng":130.461497,"geo_status":"db","era":"大正7年頃／平成5年移築","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造、高さ8.8m","structure_material":"煉瓦造","registered":"2026.07.09(令和8.07.09)","register_no":"46 - 0131","desc":"醸造用のボイラーにかつて併設していた煉瓦造の煙突。石蔵の南西に建つ。基部は一辺一・一五メートルの方形で高さ八・七六メートル。イギリス積で上部を窄め、頂部に蛇腹を廻らし装飾とする。造酒屋のランドマークとして親しまれる、貴重な煉瓦造の煙突。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016759"},{"id":"00007442","register_sub_id":"101","register_pk":"108424","name":"坂本家住宅主屋","kana":"さかもとけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県指宿市西方4681","lat":31.27722104,"lng":130.61866306,"geo_status":"db","era":"大正11／昭和28改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"46 － 0078","desc":"通りに南面して建つ。間口１０ｍ奥行１３ｍ規模。入母屋造妻入桟瓦葺で、四周に庇をまわし、正面にはさらに短い庇を付ける特徴的な外観を構成する。外壁は西面が切石積上を大壁造、正面は奥行７０㎝ほどを吹放ちで開放的にし、その奥北寄りには摺上げ戸を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007442"},{"id":"00007441","register_sub_id":"101","register_pk":"108423","name":"中俣家住宅主屋","kana":"なかまたけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県指宿市西方字宮ヶ濱中4674","lat":31.27678686,"lng":130.61929609,"geo_status":"db","era":"明治後期／昭和36移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積286㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"46 － 0077","desc":"通りに南面して建つ。間口１７ｍ奥行１５ｍと規模の大きい平入町家。屋根は桟瓦葺で、各面で異なる複雑な構成をもつ。正面は東切妻西入母屋造に庇をまわし、さらに庇を付ける。妻や軒を漆喰で塗り込め、正面両隅を切石積とする。屋根が重なる独特の外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007441"},{"id":"00007439","register_sub_id":"101","register_pk":"108421","name":"丸十金物百貨店店舗","kana":"まるじゅうかなものひゃっかてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県指宿市西方4826","lat":31.27576296,"lng":130.62039748,"geo_status":"db","era":"明治後期／昭和33改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積175㎡","structure_material":"木造平屋一部2階建","registered":"2008.10.23(平成20.10.23)","register_no":"46 － 0075","desc":"通りに北面して建つ。間口１１ｍの木造平屋一部２階建、切妻造妻入桟瓦葺。北半部を土間床のミセとし、両側面の壁面に棚をつくる。南半部は西に通り土間を設け、東側に田の字型に４室の居室を配する。正面の開放的な側まわりと大きな妻壁が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007439"},{"id":"00007440","register_sub_id":"101","register_pk":"108422","name":"丸十金物百貨店蔵","kana":"まるじゅうかなものひゃっかてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県指宿市西方4826","lat":31.27568407,"lng":130.62033959,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"46 － 0076","desc":"店舗の後方に位置する。桁行６．３ｍ梁間５．２ｍの土蔵造２階建で、南北棟の切妻造桟瓦葺とする。外壁は切石積基礎をまわし、漆喰仕上げ。東面北寄りを出入口とし、引戸をたてる。内部も漆喰仕上げで、１階は土間床とする。商品の保管庫として使われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007440"},{"id":"00007443","register_sub_id":"101","register_pk":"108425","name":"蜷川菓子店店舗兼主屋","kana":"みながわかしてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県指宿市西方字仮屋ノ下4682","lat":31.27735591,"lng":130.61850518,"geo_status":"db","era":"大正2／昭和36改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"46 － 0079","desc":"通りに南面して建つ。間口１１ｍ奥行９．９ｍ規模の平入町家。前寄りにミセを設け、奥は通り土間と居室とする。屋根は桟瓦葺で、西面入母屋造、東面切妻造とし、側・背面三方に庇を付けるが、正面は道路拡幅に伴い改変された。妻は破風まで一連で塗り込める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007443"},{"id":"00001027","register_sub_id":"101","register_pk":"102017","name":"南日本銀行本店","kana":"みなみにほんぎんこうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市山下町1-1","lat":31.59463614,"lng":130.55688013,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造６階建，建築面積1333㎡","structure_material":"鉄筋コンクリート造６階建","registered":"1998.12.11(平成10.12.11)","register_no":"46 － 0004","desc":"鹿児島無尽株式会社鹿児島支店として建設。３階分通しのコリント式列柱による主階層，アーチ窓を重ねたアチック層，曲面構成の塔屋との対比に妙味が感じられる。設計は元鹿児島県技師の三上昇。三面が道路に面することで格好のランドマークともなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001027"},{"id":"00004873","register_sub_id":"101","register_pk":"105863","name":"森山家住宅石倉","kana":"もりやまけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"鹿児島県","address":"鹿児島県霧島市横川町中ノ小字諏訪985","lat":31.90333222,"lng":130.70106507,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積153㎡","structure_material":"木骨石造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"46 － 0019","desc":"敷地の裏手に位置する。東西棟，切妻造，桟瓦葺，平入の内部に中二階を設けた木骨石造倉庫で，南面に下屋庇を差し掛けてアーチ形の戸口を２箇所設ける他，下屋西端を石壁で囲い庫室とする。桁行９間梁間４間規模と大きく，商家の繁栄振りを物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004873"},{"id":"00014989","register_sub_id":"101","register_pk":"519249","name":"沖縄ホテル大道門","kana":"おきなわほてるうふどーもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県那覇市字大道上大道原35","lat":26.21779167,"lng":127.70008889,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、間口5.9m","structure_material":"鉄筋コンクリート造","registered":"2024.03.06(令和6.03.06)","register_no":"47 - 0091","desc":"道路から敷地に至る通路にあるホテル表門。一間腕木門形式で鉄筋コンクリート造の角柱上部に腕木を挿し軒桁を受ける。屋根は切妻造琉球赤瓦葺で両妻に降棟をつけ大棟には鬼瓦を据える。沖縄の伝統建築の意匠で、戦後沖縄を代表するホテル入口を飾る大道門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014989"},{"id":"00014990","register_sub_id":"101","register_pk":"519250","name":"沖縄ホテル瓦石垣","kana":"おきなわほてるかわらいしがき","category":"産業3次","subcategory":"その他工作物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県那覇市字大道上大道原35","lat":26.21795556,"lng":127.699925,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"石造及びコンクリート造、瓦葺、総延長92m","structure_material":"石造及びコンクリート造","registered":"2024.03.06(令和6.03.06)","register_no":"47 - 0092","desc":"旅館棟の敷地外周を廻る石垣。高さ１・８メートル、総延長９２メートル。コンクリート造壁体に琉球石灰岩を積み、屋根は琉球赤瓦で葺き、棟頂部や端部は砂漆喰で塗込める。長大な石垣で大道門と一体となってホテルの表構えを整え、沖縄らしい景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014990"},{"id":"00014987","register_sub_id":"101","register_pk":"519247","name":"沖縄ホテル旅館棟","kana":"おきなわほてるりょかんとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県那覇市字大道上大道原35","lat":26.21809444,"lng":127.70015,"geo_status":"db","era":"昭和36年／平成5年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積828㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"47 - 0089","desc":"安里駅北東の市街地に位置する昭和戦前から続くホテル。設計は仲座久雄。西に開いたコの字形平面で、中央棟に吹抜の玄関ホールと階段、北棟と南棟に客室を配す。各階窓上には庇を廻らし、中空ブロックで飾った壁面やバルコニーなど、仲座らしい特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014987"},{"id":"00014988","register_sub_id":"101","register_pk":"519248","name":"沖縄ホテルレンガ棟","kana":"おきなわほてるれんがとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県那覇市字大道上大道原35","lat":26.21805,"lng":127.70071389,"geo_status":"db","era":"昭和24年頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"鉄筋コンクリート造及び煉瓦造2階建、瓦葺、建築面積103㎡","structure_material":"鉄筋コンクリート造及び煉瓦造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"47 - 0090","desc":"敷地南東に位置する２階建切妻造桟瓦葺。一階は鉄筋コンクリートのラーメン構造で、煉瓦積を化粧で現し、二階は煉瓦造とした混構造。小屋は木造トラス組。外壁に大きめの矩形開口を開け、各階2室とする。戦後沖縄におけるホテル発祥の遺例として希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014988"}];
